@dataclass(frozen=True, slots=True)
class _PreparedDispatchFinalClaimV1:
    graph: GraphCoordinator
    claimed: object
    handoff_id: str
    clock: object
    installation_id: str
    route_port: object
    issuer_id: str

    def __call__(self, graph, context, binding, claimed, witness, snapshot):
        if (graph is not self.graph or claimed != self.claimed
                or context.handoff_id != self.handoff_id
                or witness.guard.installation_id != self.installation_id):
            raise UnavailableGuard("prepared final claim identity differs; HOLD")
        return graph._commit_dispatch_final_claim_v1(
            context, binding, claimed, witness, snapshot,
            self.route_port, self.issuer_id, frozen_clock=self.clock,
            frozen_installation_id=self.installation_id)


@dataclass(frozen=True, slots=True)
class _InstalledDispatchFinalClaimWriterV1:
    graph: GraphCoordinator
    port: object
    clock_policy: object
    route_port: object
    issuer_id: str

    def __call__(self, *args, **kwargs):
        raise UnavailableGuard("final claim needs same-handoff clock preparation; HOLD")

    def prepare_for_handoff(self, graph, claimed, handoff_id: str):
        from .authority_service.v2_contract import MutationReceiptV2
        from .host.v2_fence_port import VerifiedIngressClockV2
        from .runtime.first_ingress_v2 import trusted_upper

        if (graph is not self.graph or type(claimed) is not MutationReceiptV2
                or claimed.durable_state != "committed"
                or claimed.pending.phase != "claimed"
                or type(handoff_id) is not str or not handoff_id):
            raise UnavailableGuard("final claim preparation needs exact P2; HOLD")
        grant = self.port.installation_grant
        clock = self.port.read_ingress_clock(self.clock_policy)
        if (type(clock) is not VerifiedIngressClockV2
                or clock.sample.authority_id != grant.authority_id
                or clock.sample.installation_id != grant.installation_id
                or clock.sample.source_id != self.clock_policy.source_id
                or claimed.after_anchor.authority_id != grant.authority_id
                or claimed.after_anchor.namespace
                    != claimed.pending.permit.namespace):
            raise UnavailableGuard("paired final claim clock differs; HOLD")
        trusted_upper(clock)
        return _PreparedDispatchFinalClaimV1(
            graph, claimed, handoff_id, clock, grant.installation_id,
            self.route_port, self.issuer_id)


