@dataclass(frozen=True, slots=True)
class _InstalledNaturalDispatchFinalClaimWriterV2:
    graph: GraphCoordinator
    port: object
    clock_policy: object
    route_port: object
    issuer_id: str

    def __call__(self, *args, **kwargs):
        raise UnavailableGuard("natural claim needs same-handoff preparation; HOLD")

    def prepare_natural_for_handoff(
            self, graph, claimed, handoff_id: str,
            original_operation_id: str):
        from .authority_service.v2_contract import MutationReceiptV2
        from .host.v2_fence_port import VerifiedIngressClockV2
        from .runtime.first_ingress_v2 import trusted_upper

        if (graph is not self.graph or type(claimed) is not MutationReceiptV2
                or claimed.durable_state != "committed"
                or claimed.pending.phase != "claimed"
                or claimed.pending.binding.operation_id != original_operation_id
                or type(handoff_id) is not str or not handoff_id):
            raise UnavailableGuard("natural claim preparation needs P2; HOLD")
        grant = self.port.installation_grant
        clock = self.port.read_ingress_clock(self.clock_policy)
        if (type(clock) is not VerifiedIngressClockV2
                or clock.sample.authority_id != grant.authority_id
                or clock.sample.installation_id != grant.installation_id
                or clock.sample.source_id != self.clock_policy.source_id
                or claimed.after_anchor.authority_id != grant.authority_id):
            raise UnavailableGuard("natural claim paired clock differs; HOLD")
        trusted_upper(clock)
        return _PreparedNaturalDispatchFinalClaimV2(
            graph, claimed, handoff_id, original_operation_id, clock,
            grant.installation_id, self.route_port, self.issuer_id)


