def budget_operation_digest(envelope, lease_id: str,
                            ceiling: dict[str, int]) -> str:
    """Budget identity avoids a cycle through the graph cost receipt digest."""
    return canonical_digest({
        "schema": "sylanne.runtime.budget.v1",
        "namespace": list(envelope.authority.namespace.as_tuple),
        "activity_id": envelope.identity.activity_id,
        "operation_id": envelope.identity.operation_id,
        "input_digest": envelope.identity.canonical_input_digest,
        "lease_id": lease_id,
        "ceiling": ceiling,
    })


def namespace_ref(namespace: NamespaceId) -> str:
    """Bounded content-free identity shared by independent authorities."""
    if not isinstance(namespace, NamespaceId):
        raise TypeError("namespace must be NamespaceId")
    return "ns:sha256:" + hashlib.sha256(
        canonical_json(list(namespace.as_tuple)).encode("utf-8")
    ).hexdigest()


def _operation_capability_ref(namespace: NamespaceId, actor: str,
                              issuer_domain: str, domains: frozenset[str],
                              generation: int, operation_id: str) -> str:
    return "operation:" + canonical_digest({
        "namespace": list(namespace.as_tuple), "actor": actor,
        "issuer_domain": issuer_domain, "domains": sorted(domains),
        "generation": generation, "operation_id": operation_id,
    })


def _first_ingress_encoding_acquire_prefix(
    namespace: NamespaceId, job_id: str, ingress_operation_id: str,
    worker_actor: str, activation_generation: int,
) -> str:
    return "job-acquire-" + canonical_digest({
        "schema": "sylanne.first-ingress-job-acquire-id.v2",
        "namespace": list(namespace.as_tuple), "job_id": job_id,
        "ingress_operation_id": ingress_operation_id,
        "worker_actor": worker_actor,
        "activation_generation": activation_generation,
    }) + "-"


def first_ingress_encoding_acquire_operation_id(
    namespace: NamespaceId, job_id: str, ingress_operation_id: str,
    worker_actor: str, activation_generation: int, attempt_nonce: str,
) -> str:
    """A trusted scheduler supplies a fresh nonce for each job-bound attempt."""
    if (type(attempt_nonce) is not str or len(attempt_nonce) != 32
            or any(char not in "0123456789abcdef" for char in attempt_nonce)):
        raise ValueError("job acquire attempt nonce must be 32 lowercase hex digits")
    return _first_ingress_encoding_acquire_prefix(
        namespace, job_id, ingress_operation_id,
        worker_actor, activation_generation) + attempt_nonce


def _job_acquire_id_matches(
    acquire_operation_id: str, namespace: NamespaceId, job_id: str,
    ingress_operation_id: str, worker_actor: str,
    activation_generation: int,
) -> bool:
    prefix = _first_ingress_encoding_acquire_prefix(
        namespace, job_id, ingress_operation_id,
        worker_actor, activation_generation)
    nonce = acquire_operation_id[len(prefix):]
    return (acquire_operation_id.startswith(prefix) and len(nonce) == 32
            and all(char in "0123456789abcdef" for char in nonce))


def source_correction_acquire_operation_id(
    namespace: NamespaceId, job_id: str, original_operation_id: str,
    worker_actor: str, activation_generation: int, attempt_nonce: str,
) -> str:
    """Give one D11 correction acquire attempt a job-bound scheduler identity."""
    if (type(attempt_nonce) is not str or len(attempt_nonce) != 32
            or any(char not in "0123456789abcdef" for char in attempt_nonce)):
        raise ValueError("correction acquire nonce must be 32 lowercase hex digits")
    return "d06-acquire-" + canonical_digest({
        "schema": "sylanne.d06-source-correction-acquire-id.v1",
        "namespace": list(namespace.as_tuple), "job_id": job_id,
        "original_operation_id": original_operation_id,
        "worker_actor": worker_actor,
        "activation_generation": activation_generation,
    }) + "-" + attempt_nonce


