    def prepare_internal_work_v1(
            self, authority: AuthorityContext, lease: object, *,
            envelope, body_policy_id: str, body_policy_version: int,
            cpu_policy_id: str, cpu_policy_version: int,
            reservation_id: str, execution_id: str, algorithm_ref: str):
        """Legacy C04 preparation cannot freeze an executable V2 input."""
        raise UnavailableGuard("C04 V1 preparation is non-executable; HOLD")

    def _owner_domain_write_v3(self, authority, lease, *, operation_id,
                               request_digest, domains, capability, commit, fence_context=None, background_original=None):
        """Keep a current Owner write and its original unknown attempt durable.

        ``commit`` is a W01-owned transaction implementation, never a public
        caller callback. Authority RPCs finish before the graph lock is taken.
        """
        from .authority_service.v2_contract import FencePermitV2, from_wire, to_wire
        from .runtime.restore_anchor import RestoreAnchor
        from .runtime.first_ingress_v2 import trusted_upper

        if background_original is None:
            self._authorize(lease, authority, frozenset(domains), owner_read=True)
            owner = self.__owner_leases.get(lease)
            proof = self.__owner_session_proofs.get(lease)
        else:
            from .runtime.domain_background_issuance_v1 import require_background_issuance_v1
            owner = require_background_issuance_v1(background_original, self, authority, operation_id)
            proof = None
        store, port, namespace = self.__store, self.__content_fence_v2, authority.namespace
        if (not isinstance(store, ProductionGraphStore) or port is None
                or owner is None or (proof is None and background_original is None) or capability not in owner.capabilities):
            raise UnavailableGuard("current signed Owner domain write unavailable; HOLD")
        from .runtime.contact_final_ack_v1 import (contact_owner_call_v1,
            verify_contact_before_finish_v1, require_contact_finish_ack_v1,
            read_finished_contact_recovery_v1, _issue_saved_contact_recovery_v1)
        contact_call = contact_owner_call_v1(self, authority, lease, operation_id, request_digest)
        attempt_id = "owner-domain-" + canonical_digest((
            namespace, operation_id, request_digest))[:48]
        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
            saved = store._db.execute(
                "SELECT request_digest,attempt_id,anchor_json,graph_revision,graph_epoch,"
                "permit_json,receipt_json FROM graph_owner_domain_attempts_v3 "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,)).fetchone()
        target = metadata.requirements
        anchor = port.current_anchor(namespace=namespace,
                                     authority_namespace=target.authority_namespace)
        if (not self._anchor_matches(target, anchor)
                or target.activation_generation != authority.activation_generation):
            raise UnavailableGuard("Owner domain recovery anchor changed; HOLD")
        if saved is not None:
            if saved[:2] != (request_digest, attempt_id):
                raise EventConflict("Owner domain operation changed its original input")
            saved_anchor = RestoreAnchor(**json.loads(saved[2]))
            if saved_anchor != anchor:
                raise UnavailableGuard("Owner domain original anchor changed; HOLD")
            if saved[6] is None and saved[3:5] != (metadata.graph_revision, epoch.revision):
                raise UnavailableGuard("Owner domain unresolved graph stamp changed; HOLD")
        else:
            with store._lock:
                db = store._db
                db.execute("BEGIN IMMEDIATE")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise StaleRead("Owner domain graph changed before intent")
                    db.execute("INSERT INTO graph_owner_domain_attempts_v3"
                               "(bot,persona,operation_id,request_digest,attempt_id,anchor_json,"
                               "graph_revision,graph_epoch) VALUES(?,?,?,?,?,?,?,?)",
                               namespace.as_tuple + (operation_id, request_digest, attempt_id,
                               canonical_json(asdict(anchor)), metadata.graph_revision, epoch.revision))
                    db.execute("COMMIT")
                except BaseException:
                    db.rollback()
                    raise
        # A retry observes the original permit first; it never invents another
        # operation ID or a new attempt for an unknown begin/commit result.
        if saved is not None and saved[5] is not None:
            permit = from_wire(json.loads(saved[5]))
            observed, state = port.get_fence_operation(
                namespace=namespace, authority_namespace=target.authority_namespace,
                operation_id=attempt_id)
            if observed != permit or state not in {"active", "finished"}:
                raise UnavailableGuard("Owner domain original permit differs; HOLD")
        else:
            permit = port.begin_fence(
                namespace=namespace, authority_namespace=target.authority_namespace,
                holder=self.__holder, generation=authority.activation_generation,
                operation="write", operation_id=attempt_id, expected_anchor=anchor,
                retain_on_unknown=True)
            state = "active"
        if (type(permit) is not FencePermitV2 or permit.operation_id != attempt_id
                or permit.operation != "write" or permit.holder != self.__holder
                or permit.pinned_anchor != anchor):
            raise UnavailableGuard("Owner domain permit identity differs; HOLD")
        pre_revision, pre_epoch = (saved[3:5] if saved is not None else
                                   (metadata.graph_revision, epoch.revision))
        scope = FenceScope(namespace, target.authority_namespace,
                           authority.activation_generation, "write", attempt_id,
                           permit, anchor, NamespaceEpoch(*namespace.as_tuple, pre_epoch), pre_revision)
        finish_id = "finish:" + attempt_id
        finish_digest = "sha256:" + canonical_digest({
            "schema": "w01.owner-domain-write.v3", "operation_id": operation_id,
            "request_digest": request_digest, "permit_token": permit.token})
        if saved is not None and saved[6] is not None:
            saved_result = json.loads(saved[6])
            if (saved_result.get('operation_kind') in {'prepare_contact_dispatch','prepare_contact_dispatch_v3'}
                    and contact_call is None):
                raise ValueError('Contact saved receipt requires its exact installed recovery invocation')
            if contact_call is not None:
                if state == 'finished':
                    return read_finished_contact_recovery_v1(contact_call,scope,saved_result,
                        owner=owner,owner_session_proof=proof)
                if saved_result.get('schema') == 'sylanne.domain-production-receipt.v1':
                    from .runtime.contact_final_stage_v3 import PrepareCurrentContactDispatchRequestV3
                    if type(contact_call.request) is PrepareCurrentContactDispatchRequestV3:
                        from .runtime.contact_saved_owner_projection_v3 import _read_saved_contact_owner_projection_v3, _ContactSavedFinishedV3
                        try:
                            _guard,current_owner=_read_saved_contact_owner_projection_v3(
                                contact_call,scope,saved_result,owner,proof)
                        except _ContactSavedFinishedV3:
                            return read_finished_contact_recovery_v1(contact_call,scope,saved_result,
                                owner=owner,owner_session_proof=proof)
                    else:
                        _guard, current_owner = self._owner_binding_in_fence(
                            authority,scope,owner.principal,owner,proof)
                    if fence_context is None:
                        raise ValueError('Contact recovery has no real installed stage context')
                    _issue_saved_contact_recovery_v1(contact_call,scope,saved_result)
                    with fence_context(scope,_guard,current_owner):
                        verify_contact_before_finish_v1(contact_call,scope,saved_result)
                port.finish_fence(scope,request_id=finish_id,request_digest=finish_digest)
                require_contact_finish_ack_v1(contact_call,scope)
                return read_finished_contact_recovery_v1(contact_call,scope,saved_result,
                    owner=owner,owner_session_proof=proof)
            if state == "active":
                port.finish_fence(scope, request_id=finish_id, request_digest=finish_digest)
            # The original receipt is reread under a new current Owner fence;
            # finishing the old attempt alone does not authorize disclosure.
            if background_original is not None:
                from .runtime.domain_background_issuance_v1 import observe_background_owner_v1
                return self._read_v2(authority, lambda: json.loads(saved[6]),
                    fence_observer=lambda current_scope: observe_background_owner_v1(
                        background_original, self, authority, current_scope))
            return self._read_v2(
                authority, lambda: json.loads(saved[6]), owner_binding=owner,
                owner_session_proof=proof)
        if state != "active" or port.validate_fence(scope) != permit:
            raise UnavailableGuard("Owner domain original write is not active; HOLD")
        with store._lock:
            store._db.execute("UPDATE graph_owner_domain_attempts_v3 SET permit_json=? "
                "WHERE bot=? AND persona=? AND operation_id=? AND attempt_id=? AND permit_json IS NULL",
                (canonical_json(to_wire(permit)), *namespace.as_tuple, operation_id, attempt_id))
        try:
            if background_original is None:
                _guard, current_owner = self._owner_binding_in_fence(
                    authority, scope, owner.principal, owner, proof)
            else:
                from .runtime.domain_background_issuance_v1 import observe_background_owner_v1
                _guard, current_owner = observe_background_owner_v1(background_original, self, authority, scope)
                if capability not in current_owner.capabilities:
                    raise AuthorityDenied("current background Owner capability is unavailable")
            clock = port.read_ingress_clock(self.__scene_clock_policy)
            now = trusted_upper(clock)
            context = (fence_context(scope, _guard, current_owner)
                       if fence_context is not None else nullcontext())
            contact_session_observation = None
            if contact_call is not None:
                from .runtime.contact_final_stage_v3 import PrepareCurrentContactDispatchRequestV3
                if type(contact_call.request) is PrepareCurrentContactDispatchRequestV3:
                    from .runtime.contact_owner_invocation_v3 import capture_contact_owner_invocation_v3
                    contact_session_observation = capture_contact_owner_invocation_v3(
                        contact_call, scope, owner, proof)
            with context:
                with store._lock:
                    db = store._db
                    # Save the real permit independently of the business transaction.
                    db.execute("UPDATE graph_owner_domain_attempts_v3 SET permit_json=? "
                               "WHERE bot=? AND persona=? AND operation_id=? AND permit_json IS NULL",
                               (canonical_json(to_wire(permit)), *namespace.as_tuple, operation_id))
                    db.execute("BEGIN IMMEDIATE")
                    try:
                        if self._v2_graph_stamp(namespace) != (metadata, epoch):
                            raise StaleRead("Owner domain graph changed before write")
                        if self._owner_graph_binding_locked(authority, owner.principal,
                                target_admission=current_owner.target_admission, storage_admission=current_owner.storage_admission, current_guard=_guard) != current_owner:
                            raise StaleRead("Owner domain graph grant changed")
                        result = commit(db, metadata, epoch, now, current_owner, scope)
                        db.execute("UPDATE graph_owner_domain_attempts_v3 SET receipt_json=? "
                                   "WHERE bot=? AND persona=? AND operation_id=? AND receipt_json IS NULL",
                                   (canonical_json(result), *namespace.as_tuple, operation_id))
                        if db.execute("SELECT changes()").fetchone() != (1,):
                            raise EventConflict("Owner domain receipt raced")
                        if contact_session_observation is not None:
                            from .runtime.contact_owner_invocation_v3 import record_contact_owner_invocation_v3
                            record_contact_owner_invocation_v3(db, contact_call, scope,
                                result, current_owner, contact_session_observation)
                        db.execute("COMMIT")
                    except BaseException:
                        if db.in_transaction:
                            db.rollback()
                        # The retained attempt remains queryable after a transaction
                        # failure; no guessed zero cost or second operation is issued.
                        raise
                if contact_call is not None:
                    # COMMIT is durable and the exact installed context is still
                    # active. Failure leaves the saved receipt/permit pending;
                    # it neither rolls back committed rows nor finishes the fence.
                    verify_contact_before_finish_v1(contact_call,scope,result)
        except (ValueError, TypeError, StaleRead, AuthorityDenied) as exc:
            # Fixed W01 callbacks contain only transactional staging. As with
            # installed D04 stages, close a known refusal only after proving
            # that the original attempt has no result and its entire business
            # stamp is unchanged. Transport/SQL uncertainty remains pending.
            with store._lock:
                db = store._db
                if db.in_transaction:
                    raise RuntimeError("Owner domain refusal rollback is uncertain") from exc
                prior = db.execute("SELECT request_digest,attempt_id,receipt_json FROM "
                    "graph_owner_domain_attempts_v3 WHERE bot=? AND persona=? AND operation_id=?",
                    (*namespace.as_tuple, operation_id)).fetchone()
                if prior != (request_digest, attempt_id, None) or self._v2_graph_stamp(namespace) != (metadata, epoch):
                    raise
                refusal = {"schema": "sylanne.owner-domain-write-refusal.v3", "status": "held",
                    "operation_id": operation_id, "attempt_id": attempt_id,
                    "request_digest": request_digest, "reason_code": type(exc).__name__,
                    "permit_digest": canonical_digest(to_wire(permit)),
                    "anchor_digest": canonical_digest(asdict(anchor)),
                    "graph_revision": metadata.graph_revision, "graph_epoch": epoch.revision}
                db.execute("BEGIN IMMEDIATE")
                try:
                    db.execute("UPDATE graph_owner_domain_attempts_v3 SET receipt_json=? "
                        "WHERE bot=? AND persona=? AND operation_id=? AND attempt_id=? AND receipt_json IS NULL",
                        (canonical_json(refusal), *namespace.as_tuple, operation_id, attempt_id))
                    if db.execute("SELECT changes()").fetchone() != (1,):
                        raise EventConflict("Owner domain refusal original raced")
                    db.commit()
                except BaseException:
                    db.rollback()
                    raise
            port.finish_fence(scope, request_id=finish_id, request_digest=finish_digest)
            raise
        port.finish_fence(scope, request_id=finish_id, request_digest=finish_digest)
        if contact_call is not None:
            require_contact_finish_ack_v1(contact_call,scope)
        return result

