    def run_current_domain_operation_v1(self, authority, lease, *, operation_kind, request,
            operation_id, activity_id, audience_ref, parent_budget_lease_ref):
        result = self.__domain_production_runtime_v1.run_current(authority, lease,
            operation_kind=operation_kind, request=request, operation_id=operation_id,
            activity_id=activity_id, audience_ref=audience_ref,
            parent_budget_lease_ref=parent_budget_lease_ref)
        if result.get("outbox"):
            wake_followup = getattr(self, "_GraphCoordinator__domain_followup_wake_v1", None)
            if callable(wake_followup):
                wake_followup()
        if operation_kind == "input:register_offline_schedule" and result.get("schema") == "sylanne.domain-production-receipt.v1":
            wake_lifecycle = getattr(self, "_GraphCoordinator__host_lifecycle_wake_v1", None)
            if callable(wake_lifecycle):
                wake_lifecycle()
        if result.get("schema") == "sylanne.domain-production-receipt.v1" and result.get("domain") in {"d02", "d10"}:
            wake_offline = getattr(self, "_GraphCoordinator__offline_recovery_wake_v1", None)
            if callable(wake_offline):
                wake_offline()
        service = getattr(self, "_GraphCoordinator__d07_execution_service_v1", None)
        if result.get("domain") == "d07" and service is not None:
            wake = getattr(service, "wake_committed_job_v1", None)
            if callable(wake):
                for job_id, phase in result.get("job_states", ()):
                    if phase == "queued":
                        wake(job_id)
        return result

