    def prepare_internal_work_v3(
            self, authority: AuthorityContext, lease: object, *, envelope,
            body_policy_id: str, body_policy_version: int,
            cpu_policy_id: str, cpu_policy_version: int,
            reservation_id: str, execution_id: str, cue_source_ref: str,
            focus_ref: str, attention_ticket_ref: str, mood_ref: str,
            encoding_operations, budget, context_tags=()):
        """Prepare the actual installed C04 V3 work under one Owner write."""
        from .domains.d04.projection_issuer_v2 import load_installed_d04_projection_assets_v2
        from .runtime.c04_prepare_service_v3 import (
            stage_current_c04_prepare_v3, record_committed_current_c04_prepare_v3)
        from .runtime.c04_frozen_association_original_v3 import (
            install_c04_frozen_association_original_v3)
        from .runtime.c04_internal_work_original_v1 import read_c04_internal_work_prepared_v1
        from .runtime.c04_product_original_v3 import (
            install_c04_product_original_v3, record_c04_product_request_v3)
        from .runtime.c04_interpretation_policy_v3 import record_installed_c04_interpretation_policy_v3
        from .runtime_contracts import CommandEnvelope

        assembly = self.__d04_installed_joint_assembly
        if (type(envelope) is not CommandEnvelope or envelope.authority != authority
                or authority.issuer_domain != "d12" or assembly is None
                or self.__c04_algorithm_build_digest is None
                or self.__c04_authority_port_v3 is None):
            raise UnavailableGuard("installed C04 V3 preparation unavailable; HOLD")
        policy, asset = load_installed_d04_projection_assets_v2(
            assembly.package_root, assembly.installation_policy.manifest_digest,
            assembly.available_cpu_features)
        with self.__store._lock:
            install_c04_frozen_association_original_v3(self.__store._db)
            install_c04_product_original_v3(self.__store._db)
        operation_id = envelope.identity.operation_id
        request_digest = canonical_digest((
            "w01.c04-prepare.v3", envelope, body_policy_id, body_policy_version,
            cpu_policy_id, cpu_policy_version, reservation_id, execution_id,
            cue_source_ref, focus_ref, attention_ticket_ref, mood_ref,
            encoding_operations, budget, context_tags, self.__c04_algorithm_build_digest))

        def commit(db, metadata, epoch, now, owner, scope):
            stage = stage_current_c04_prepare_v3(
                db, envelope=envelope, owner=owner,
                body_policy_id=body_policy_id, body_policy_version=body_policy_version,
                cpu_policy_id=cpu_policy_id, cpu_policy_version=cpu_policy_version,
                reservation_id=reservation_id, execution_id=execution_id,
                cue_source_ref=cue_source_ref, focus_ref=focus_ref,
                attention_ticket_ref=attention_ticket_ref, mood_ref=mood_ref,
                encoding_operations=encoding_operations, budget=budget,
                context_tags=context_tags,
                algorithm_build_digest="sha256:" + self.__c04_algorithm_build_digest,
                asset=asset, projection_policy=policy,
                d02_issuer=self.__d02_issuer, d11_issuer=self.__d11_issuer,
                body_authority=self.__body_quote_authority,
                cpu_authority=self.__c04_cpu_quote_authority,
                installation_id=self.__content_fence_v2.installation_grant.installation_id,
                now_utc=now)
            if stage.replayed:
                record_installed_c04_interpretation_policy_v3(db, authority.namespace, stage.prepared,
                    installation_id=assembly.installation_policy.installation_id,
                    manifest_digest=assembly.installation_policy.manifest_digest)
                record_c04_product_request_v3(
                    db, envelope=envelope, prepared=stage.prepared,
                    request_digest=request_digest)
                return {"operation_id": operation_id,
                        "prepared_digest": stage.prepared.prepared_digest}
            event = Event(Scope(*authority.namespace.as_tuple, envelope.identity.activity_id),
                          "c04-prepare:" + operation_id, now, "c04.internal_work_prepared.v3",
                          {"request_digest": request_digest})
            candidate = GraphCandidate(event, stage.read_versions,
                                       (stage.reservation_write,), (epoch,))
            from .runtime.c04_prepare_service_v3 import create_running_c04_preparation_job_v3
            from .runtime.d11_types import job_graph_write
            first = self.__store._graph_commit_in_transaction(candidate, _capability=self.__graph_capability)
            if first.status != "committed" or first.epoch.revision != epoch.revision + 1:
                raise UnavailableGuard("C04 reservation Graph CAS differs")
            self.__store.cas_graph_recovery_metadata(metadata, metadata.requirements, _capability=self.__graph_capability)
            after_reservation, actual_epoch = self._v2_graph_stamp(authority.namespace)
            running = create_running_c04_preparation_job_v3(db, stage, holder=self.__holder, now_utc=now)
            job_write = job_graph_write(running)
            if db.execute("SELECT 1 FROM graph_atoms WHERE token=?", (job_write.key.token,)).fetchone():
                raise UnavailableGuard("C04 new job projection already exists")
            job_event = Event(Scope(*authority.namespace.as_tuple, envelope.identity.activity_id),
                "c04-prepare-job:" + operation_id, now, "c04.running_job_prepared.v3",
                {"request_digest": request_digest, "reservation_receipt_digest": canonical_digest(first)})
            second = self.__store._graph_commit_in_transaction(GraphCandidate(job_event,
                (GraphVersion(job_write.key, 0),), (job_write,), (actual_epoch,)), _capability=self.__graph_capability)
            if second.status != "committed" or second.epoch.revision != epoch.revision + 2:
                raise UnavailableGuard("C04 actual running-job Graph CAS differs")
            self.__store.cas_graph_recovery_metadata(after_reservation, after_reservation.requirements,
                _capability=self.__graph_capability)
            actual_metadata, final_epoch = self._v2_graph_stamp(authority.namespace)
            if actual_metadata.graph_revision != metadata.graph_revision + 2 or final_epoch != second.epoch:
                raise UnavailableGuard("C04 actual final preparation stamp differs")
            prepared = record_committed_current_c04_prepare_v3(db, stage,
                graph_revision=actual_metadata.graph_revision, asset=asset,
                projection_policy=policy, running_job=running)
            record_installed_c04_interpretation_policy_v3(db, authority.namespace, prepared,
                installation_id=assembly.installation_policy.installation_id,
                manifest_digest=assembly.installation_policy.manifest_digest)
            record_c04_product_request_v3(db, envelope=envelope, prepared=prepared, request_digest=request_digest)
            return {"operation_id": operation_id, "prepared_digest": prepared.prepared_digest}

        recorded = self._owner_domain_write_v3(
            authority, lease, operation_id="c04-prepare:" + operation_id,
            request_digest=request_digest, domains=("d02", "d04", "d06", "d07", "d11"),
            capability="c04.internal_work.prepare", commit=commit)

        def read():
            db = self.__store._db
            db.execute("BEGIN")
            try:
                prepared = read_c04_internal_work_prepared_v1(db, authority.namespace, operation_id)
                if prepared is None or prepared.prepared_digest != recorded["prepared_digest"]:
                    raise UnavailableGuard("C04 V3 committed preparation differs")
                return prepared
            finally:
                db.rollback()

        return self._read_v2(authority, read, owner_binding=self.__owner_leases.get(lease),
                             owner_session_proof=self.__owner_session_proofs.get(lease))

    def read_frozen_association_work_input_v3(
            self, authority: AuthorityContext, lease: object, *, operation_id: str):
        """Reread the original C04 V3 bytes under current signed Owner access."""
        from .runtime.c04_internal_work_original_v1 import read_c04_internal_work_prepared_v1
        from .runtime.c04_frozen_association_original_v3 import read_c04_frozen_association_original_v3
        self._authorize(lease, authority, frozenset(("d04", "d06", "d07", "d11")), owner_read=True)

        def read():
            db = self.__store._db
            db.execute("BEGIN")
            try:
                prepared = read_c04_internal_work_prepared_v1(db, authority.namespace, operation_id)
                if prepared is None:
                    return None
                return read_c04_frozen_association_original_v3(db, authority.namespace, prepared.binding)
            finally:
                db.rollback()

        return self._read_v2(authority, read, owner_binding=self.__owner_leases.get(lease),
                             owner_session_proof=self.__owner_session_proofs.get(lease))

    def install_current_c04_cpu_quote_policy_v1(
            self, bootstrap: object, authority: AuthorityContext,
            lease: object, *, operation_id: str, policy):
        """Install a signed CPU ceiling under administrator and Owner authority."""
        from .runtime.c04_cpu_quote_policy import (
            C04InternalCpuQuotePolicyV1, install_c04_cpu_quote_schema_v1,
        )
        from .runtime.first_ingress_v2 import trusted_upper

        self._admin(bootstrap)
        if (type(authority) is not AuthorityContext
                or authority.issuer_domain != "d12"
                or type(policy) is not C04InternalCpuQuotePolicyV1
                or policy.namespace != authority.namespace
                or type(operation_id) is not str or not operation_id
                or not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or self.__c04_cpu_quote_authority is None):
            raise UnavailableGuard("installed C04 CPU policy authority unavailable")
        self._authorize(lease, authority, frozenset(("d02", "d11")),
                        owner_read=True)
        owner = self.__owner_leases.get(lease)
        owner_proof = self.__owner_session_proofs.get(lease)
        if (owner is None or owner_proof is None
                or "c04.cpu_policy.install" not in owner.capabilities
                or owner.actor != authority.actor
                or owner.namespace != authority.namespace
                or owner.purpose != authority.purpose
                or authority.audience != (owner.audience,)):
            raise UnavailableGuard("signed C04 CPU install Owner capability unavailable")
        namespace = authority.namespace
        port, store = self.__content_fence_v2, self.__store
        if policy.installation_id != port.installation_grant.installation_id:
            raise UnavailableGuard("C04 CPU policy installation differs")
        request_digest = canonical_digest((namespace, operation_id, policy))
        attempt_id = "c04-cpu-policy-install-" + request_digest[:48]
        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
        target = metadata.requirements
        if (target.namespace != namespace
                or target.activation_generation != authority.activation_generation):
            raise StaleRead("C04 CPU policy activation changed")
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("C04 CPU policy recovery anchor differs")
        now = trusted_upper(port.read_ingress_clock(self.__scene_clock_policy))
        if policy.valid_until_utc <= now:
            raise UnavailableGuard("C04 CPU policy expired")
        permit = port.begin_fence(
            namespace=namespace, authority_namespace=target.authority_namespace,
            holder=self.__holder, generation=authority.activation_generation,
            operation="write", operation_id=attempt_id, expected_anchor=anchor,
            retain_on_unknown=True)
        if (permit is None or permit.operation != "write"
                or permit.operation_id != attempt_id
                or permit.pinned_anchor != anchor
                or permit.holder != self.__holder):
            raise UnavailableGuard("C04 CPU policy write permit differs")
        scope = FenceScope(namespace, target.authority_namespace,
                           authority.activation_generation, "write", attempt_id,
                           permit, anchor, epoch, metadata.graph_revision)
        try:
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("C04 CPU policy write permit changed")
            self._owner_binding_in_fence(
                authority, scope, owner.principal, owner,
                owner_session_proof=owner_proof)
            with store._lock:
                db = store._db
                db.execute("BEGIN IMMEDIATE")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise StaleRead("C04 CPU policy graph changed")
                    install_c04_cpu_quote_schema_v1(db)
                    signature = self.__c04_cpu_quote_authority.install_policy(
                        db, policy)
                    db.execute("COMMIT")
                except BaseException:
                    db.execute("ROLLBACK")
                    raise
        finally:
            port.finish_fence(
                scope, request_id="finish:" + attempt_id,
                request_digest="sha256:" + canonical_digest({
                    "action": "finish_c04_cpu_policy_install",
                    "operation_id": attempt_id, "permit_token": permit.token,
                }))
        return signature

    def adopt_current_fixed_body_work_policy_v1(self, authority, lease, *, operation_id, policy):
        # The fixed installed route still requires its explicit signed Owner
        # capability inside the concrete producer; W09 receives no bootstrap.
        return self.register_current_fixed_body_work_policy_v1(self.__bootstrap, authority, lease,
            operation_id=operation_id, policy=policy)

    def register_current_fixed_body_work_policy_v1(self, bootstrap, authority, lease, *, operation_id, policy):
        from .runtime.d02_fixed_work_policy_install_v1 import register_current_fixed_body_work_policy_v1
        return register_current_fixed_body_work_policy_v1(self, bootstrap, authority, lease,
            operation_id=operation_id, policy=policy)

    def install_current_c04_fixed_body_policy_v1(
            self, bootstrap: object, authority: AuthorityContext,
            lease: object, *, operation_id: str, policy):
        """Install one explicit administrator body policy and initial graph state."""
        from .domains.d02 import BodyDomain
        from .domains.d02.body_quote_original import (
            FixedBodyPolicyV1, install_body_quote_schema,
        )
        from .domains.d02.resource_outcome_verifier import C04_INTERNAL_CPU_WORK_KIND
        from .runtime.first_ingress_v2 import trusted_upper

        self._admin(bootstrap)
        if (type(authority) is not AuthorityContext
                or authority.issuer_domain != "d12"
                or type(policy) is not FixedBodyPolicyV1
                or policy.profile.namespace != authority.namespace
                or policy.work_kind != C04_INTERNAL_CPU_WORK_KIND
                or type(operation_id) is not str or not operation_id
                or not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or self.__body_quote_authority is None):
            raise UnavailableGuard("installed C04 body policy authority unavailable")
        self._authorize(lease, authority, frozenset(("d02",)),
                        owner_read=True)
        owner = self.__owner_leases.get(lease)
        owner_proof = self.__owner_session_proofs.get(lease)
        if (owner is None or owner_proof is None
                or "d02.body_policy.install" not in owner.capabilities
                or owner.actor != authority.actor
                or owner.namespace != authority.namespace
                or owner.purpose != authority.purpose
                or authority.audience != (owner.audience,)):
            raise UnavailableGuard("signed D02 policy install Owner capability unavailable")
        namespace = authority.namespace
        store, port = self.__store, self.__content_fence_v2
        profile_key = BodyDomain.profile_write(policy.profile).key
        state_key = BodyDomain.state_write(namespace, policy.initial_state).key
        request_digest = canonical_digest((namespace, operation_id, policy))
        attempt_id = "c04-body-install-" + request_digest[:48]
        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
            existing = store._db.execute(
                "SELECT token,revision,value,valid FROM graph_atoms "
                "WHERE token IN (?,?)", (profile_key.token, state_key.token),
            ).fetchall()
        target = metadata.requirements
        if (target.namespace != namespace
                or target.activation_generation != authority.activation_generation):
            raise StaleRead("C04 body install activation changed")
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("C04 body install recovery anchor differs")
        if existing:
            expected = {profile_key.token: BodyDomain.profile_write(policy.profile).value,
                        state_key.token: BodyDomain.state_write(
                            namespace, policy.initial_state).value}
            if (len(existing) != 2 or any(
                    row[1] != 1 or row[3] != 1
                    or json.loads(row[2]) != expected[row[0]]
                    for row in existing)):
                raise UnavailableGuard("C04 body policy graph initialization differs")
            with store._lock:
                db = store._db
                db.execute("BEGIN")
                try:
                    if self.__body_quote_authority.policy(
                            db, namespace, policy.policy_id, policy.version) != policy:
                        raise UnavailableGuard("C04 installed body policy original differs")
                    db.execute("COMMIT")
                except BaseException:
                    db.execute("ROLLBACK")
                    raise
            lookup = getattr(port, "get_fence_operation", None)
            if not callable(lookup):
                raise UnavailableGuard("C04 body install replay fence reader unavailable")
            permit, state = lookup(
                namespace=namespace, authority_namespace=target.authority_namespace,
                operation_id=attempt_id)
            if (permit is None or state not in {"active", "finished"}
                    or permit.operation != "write"
                    or permit.operation_id != attempt_id):
                raise UnavailableGuard("C04 body install replay fence differs")
            if state == "active":
                port.finish_fence(
                    FenceScope(namespace, target.authority_namespace,
                               authority.activation_generation, "write",
                               attempt_id, permit, permit.pinned_anchor,
                               epoch, metadata.graph_revision),
                    request_id="finish:" + attempt_id,
                    request_digest="sha256:" + canonical_digest({
                        "action": "finish_c04_body_policy_install",
                        "operation_id": attempt_id,
                        "permit_token": permit.token,
                    }))
            return GraphVersion(profile_key, 1), GraphVersion(state_key, 1)
        now = trusted_upper(port.read_ingress_clock(self.__scene_clock_policy))
        if policy.valid_until <= now:
            raise UnavailableGuard("C04 body policy expired before install")
        permit = port.begin_fence(
            namespace=namespace, authority_namespace=target.authority_namespace,
            holder=self.__holder, generation=authority.activation_generation,
            operation="write", operation_id=attempt_id, expected_anchor=anchor)
        if (permit is None or permit.operation != "write"
                or permit.operation_id != attempt_id
                or permit.pinned_anchor != anchor
                or permit.holder != self.__holder):
            raise UnavailableGuard("C04 body install write permit differs")
        scope = FenceScope(namespace, target.authority_namespace,
                           authority.activation_generation, "write", attempt_id,
                           permit, anchor, epoch, metadata.graph_revision)
        try:
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("C04 body install write permit changed")
            self._owner_binding_in_fence(
                authority, scope, owner.principal, owner,
                owner_session_proof=owner_proof)
            with store._lock:
                db = store._db
                db.execute("BEGIN IMMEDIATE")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise StaleRead("C04 body install graph changed")
                    if any(db.execute(
                            "SELECT 1 FROM graph_atoms WHERE token=?",
                            (key.token,),
                    ).fetchone() is not None for key in (profile_key, state_key)):
                        raise UnavailableGuard("C04 body graph already initialized")
                    install_body_quote_schema(db)
                    self.__body_quote_authority.install_policy(db, policy)
                    writes = self.__body_quote_authority.initial_writes(
                        db, namespace, policy.policy_id, policy.version)
                    candidate = GraphCandidate(
                        Event(Scope(*namespace.as_tuple,
                                    "c04.fixed_body_install.v1"),
                              operation_id, now, "body_policy_install",
                              {"policy_digest": canonical_digest(policy)}),
                        (GraphVersion(profile_key, 0),
                         GraphVersion(state_key, 0)),
                        writes, (epoch,))

                    def record(_db, graph_receipt):
                        if (graph_receipt.status != "committed"
                                or graph_receipt.revisions != (
                                    GraphVersion(profile_key, 1),
                                    GraphVersion(state_key, 1))):
                            raise UnavailableGuard("C04 body install graph CAS differs")
                        replacement = replace(
                            target, deletion_seq=anchor.deletion_seq,
                            deletion_digest=anchor.deletion_digest,
                            execution_seq=anchor.execution_seq,
                            execution_digest=anchor.execution_digest,
                            revocation_epoch=anchor.revocation_epoch)
                        store.cas_graph_recovery_metadata(
                            metadata, replacement,
                            _capability=self.__graph_capability)
                    receipt = GraphStore._graph_commit_in_transaction(
                        store, candidate, _receipt_hook=record,
                        _capability=self.__graph_capability)
                    if receipt.status != "committed":
                        raise UnavailableGuard("C04 body policy graph did not commit")
                    db.execute("COMMIT")
                except BaseException:
                    if db.in_transaction:
                        db.execute("ROLLBACK")
                    raise
            return GraphVersion(profile_key, 1), GraphVersion(state_key, 1)
        finally:
            port.finish_fence(
                scope, request_id="finish:" + attempt_id,
                request_digest="sha256:" + canonical_digest({
                    "action": "finish_c04_body_policy_install",
                    "operation_id": attempt_id,
                    "permit_token": permit.token,
                }))

    def read_current_recollection_projection_v1(
            self, *, namespace: NamespaceId, operation_id: str,
            projection_ref: str, actor_id: str, principal: OwnerPrincipalV1,
            owner_session_token: str,
            owner_session_request: OwnerSessionLoginRequestV1,
    ) -> CurrentRecollectionProjectionV1:
        return self._read_current_recollection_v1(
            namespace=namespace, operation_id=operation_id,
            experience_ref=None, projection_ref=projection_ref,
            actor_id=actor_id, principal=principal,
            owner_session_token=owner_session_token,
            owner_session_request=owner_session_request)

    def _read_current_recollection_v1(
            self, *, namespace: NamespaceId, operation_id: str,
            experience_ref: str | None, projection_ref: str | None,
            actor_id: str, principal: OwnerPrincipalV1,
            owner_session_token: str,
            owner_session_request: OwnerSessionLoginRequestV1,
    ) -> CurrentRecollectionExperienceV1 | CurrentRecollectionProjectionV1:
        """Recheck a committed C04 experience and all source ancestors now.

        D04 and D06 inspectors share one business snapshot under one read fence.
        Only content-free subjective values escape this method.
        """
        from .authority_service.contract import identifier
        from .domains.d04.affect import AffectProvider, AffectScheme
        from .domains.d04.recollection_read import (
            RecollectionSnapshotUnavailable,
            inspect_recollection_experience_snapshot,
        )
        from .domains.d06 import (
            RecollectionProjectionUnavailable,
            inspect_recollection_projection_snapshot,
            source_correction_head_key, validate_source_correction_head,
        )

        if (not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None):
            raise UnavailableGuard("current recollection requires production v2")
        if type(namespace) is not NamespaceId or type(principal) is not OwnerPrincipalV1:
            raise TypeError("typed recollection Owner identity is required")
        identifier(operation_id, "operation_id")
        identifier(actor_id, "actor_id")
        if (experience_ref is None) == (projection_ref is None):
            raise ValueError("exactly one recollection read ref is required")
        experience_key = (self._parse_ref(experience_ref, namespace)
                          if experience_ref is not None else None)
        projection_key = (self._parse_ref(projection_ref, namespace)
                          if projection_ref is not None else None)
        if (experience_key is not None and
                (experience_key.type_name != "d04.recollection_experience.v1"
                 or experience_key.owner.kind != "activity")):
            raise AuthorityDenied("recollection experience ref differs")
        if (projection_key is not None and
                (projection_key.type_name != "d06.recollection_projection.v1"
                 or projection_key.owner.kind != "activity")):
            raise AuthorityDenied("recollection projection ref differs")
        registration = self.__providers.get("d04")
        if registration is None or not isinstance(registration[0], AffectProvider):
            raise UnavailableGuard("registered D04 affect provider is unavailable")
        scheme = registration[0]._active_scheme
        if type(scheme) is not AffectScheme:
            raise UnavailableGuard("active D04 affect scheme is unavailable")
        store = self.__store
        with store._lock:
            metadata, _ = self._v2_graph_stamp(namespace)
        self._check_owner_session_v2(
            namespace=namespace, principal=principal, actor_id=actor_id,
            token=owner_session_token, request=owner_session_request,
            target=metadata.requirements)
        authority = AuthorityContext(
            actor_id, "d12", "recollection-read:" + secrets.token_hex(16),
            namespace, ("persona", "activity", "event"), "workbench_view",
            ("owner",), "owner-grant-v1",
            metadata.requirements.activation_generation)
        mood_key = AtomKey(Owner("persona", *namespace.as_tuple),
                           "d04.mood_field.v1", "current")

        def reader() -> CurrentRecollectionExperienceV1 | CurrentRecollectionProjectionV1:
            db = store._db
            if db.in_transaction:
                raise UnavailableGuard("recollection read requires an idle graph connection")
            db.execute("BEGIN")
            try:
                epoch = GraphStore.graph_epoch(
                    store, *namespace.as_tuple,
                    _capability=self.__graph_capability)
                epoch_row = db.execute(
                    "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                    "WHERE bot=? AND persona=?", namespace.as_tuple,
                ).fetchone()
                if epoch_row is None:
                    raise UnavailableGuard("recollection access epochs are unavailable")
                if (self._version(db, namespace, "scheme", "current")
                        != scheme.scheme_version
                        or self._version(db, namespace, "operator", "current")
                        != scheme.operator_version):
                    raise UnavailableGuard("current D04 affect scheme changed")
                receipt = self._get_operation_fenced(
                    authority, operation_id, v2=True)
                if (receipt is None or receipt.status != "committed"
                        or receipt.operation_id != operation_id
                        or receipt.activity_id != (
                            experience_key or projection_key).owner.subject
                        or len(receipt.invalidated_epochs) != 1
                        or receipt.invalidated_epochs[0].revision > epoch.revision):
                    raise UnavailableGuard("committed C04 operation is unavailable")

                atoms: dict[AtomKey, GraphAtom] = {}

                def load(key: AtomKey) -> GraphAtom:
                    if NamespaceId.from_key(key) != namespace:
                        raise AuthorityDenied("recollection source crosses namespace")
                    if key not in atoms:
                        if len(atoms) >= 512:
                            raise UnavailableGuard("recollection source closure exceeds read bound")
                        store._validate_key(key)
                        row = db.execute(
                            "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                            (key.token,),
                        ).fetchone()
                        atoms[key] = (GraphAtom(key, row[0], json.loads(row[1]),
                                                bool(row[2])) if row else
                                      GraphAtom(key, 0, {}, False))
                    return atoms[key]

                selected_experience_key = experience_key
                if projection_key is not None:
                    projection_atom = load(projection_key)
                    if not projection_atom.valid:
                        raise UnavailableGuard("current D06 projection is absent")
                    try:
                        selected_experience_key = self._parse_ref(
                            projection_atom.value["experience_ref"], namespace)
                        projection_mood_key = self._parse_ref(
                            projection_atom.value["mood_ref"], namespace)
                    except (KeyError, TypeError, ValueError) as exc:
                        raise UnavailableGuard(
                            "current D06 projection refs are invalid") from exc
                    if (selected_experience_key.type_name
                            != "d04.recollection_experience.v1"
                            or selected_experience_key.owner.subject
                            != projection_key.owner.subject
                            or projection_mood_key != mood_key):
                        raise UnavailableGuard(
                            "current D06 projection experience or mood differs")
                experience_atom = load(selected_experience_key)
                mood_atom = load(mood_key)
                if not experience_atom.valid or not mood_atom.valid:
                    raise UnavailableGuard("current C04 experience or mood is absent")
                try:
                    recollection_key = self._parse_ref(
                        experience_atom.value["recollection_ref"], namespace)
                    source = self._parse_ref(
                        experience_atom.value["memory_ref"], namespace)
                    basis = tuple(mood_atom.value["source_refs"])
                    if not basis or len(basis) > 256:
                        raise ValueError("mood source set is unbounded")
                except (KeyError, TypeError, ValueError) as exc:
                    raise UnavailableGuard("current C04 source identities are invalid") from exc
                recollection_atom = load(recollection_key)
                if projection_key is not None:
                    if not recollection_atom.valid:
                        raise UnavailableGuard("current D06 recollection is absent")
                    try:
                        selection_ref = recollection_atom.value["selection_ref"]
                        interpretation_refs = tuple(
                            recollection_atom.value["now_interpretation_refs"])
                        if (type(selection_ref) is not str or not selection_ref
                                or not interpretation_refs
                                or len(interpretation_refs) > 64
                                or len(set(interpretation_refs)) !=
                                   len(interpretation_refs)):
                            raise ValueError("D07 recollection choice is incomplete")
                        selection_key = AtomKey(
                            recollection_key.owner, "d07.selection_ticket.v1",
                            selection_ref)
                        if not load(selection_key).valid:
                            raise ValueError("D07 selection ticket is absent")
                        for ref in interpretation_refs:
                            key = self._parse_ref(ref, namespace)
                            if (key.owner != recollection_key.owner
                                    or key.type_name !=
                                       "d07.current_interpretation.v1"
                                    or not load(key).valid):
                                raise ValueError("D07 current interpretation is absent")
                    except (KeyError, TypeError, ValueError) as exc:
                        raise UnavailableGuard(
                            "current D07 recollection choice is unavailable") from exc
                if (recollection_key.token not in receipt.ledger_refs
                        or db.execute(
                            "SELECT 1 FROM graph_bundle_refs WHERE bot=? AND persona=? "
                            "AND operation_id=? AND ref_kind='experience' AND ref=?",
                            namespace.as_tuple + (operation_id, recollection_key.token),
                        ).fetchone() is None):
                    raise UnavailableGuard("C04 operation does not own the recollection")
                pending = [source.token, *basis]
                seen: set[str] = set()
                while pending:
                    ref = pending.pop()
                    if ref in seen:
                        continue
                    seen.add(ref)
                    if len(seen) > 256:
                        raise UnavailableGuard("recollection source ancestry exceeds read bound")
                    key = self._parse_ref(ref, namespace)
                    if key != source_key(*namespace.as_tuple, key.owner.subject or ""):
                        raise UnavailableGuard("recollection source ref is not canonical")
                    source_atom = load(key)
                    load(access_key(*namespace.as_tuple, key.owner.subject))
                    correction_head = load(source_correction_head_key(
                        namespace, key.owner.subject))
                    if not source_atom.valid:
                        raise UnavailableGuard("current recollection ancestor is absent")
                    if correction_head.revision:
                        try:
                            if not correction_head.valid:
                                raise ValueError("inactive correction head")
                            validate_source_correction_head(
                                correction_head.key, correction_head.value)
                        except (TypeError, ValueError) as exc:
                            raise UnavailableGuard(
                                "current recollection correction head is invalid") from exc
                        raise UnavailableGuard(
                            "current recollection interpretation awaits reevaluation")
                    try:
                        record = SourceRecord.from_dict(source_atom.value)
                    except (TypeError, ValueError) as exc:
                        raise UnavailableGuard("current recollection ancestor is invalid") from exc
                    pending.extend(source_key(*namespace.as_tuple, parent).token
                                   for parent in record.parent_source_ids)
                snapshot = GraphSnapshot(tuple(atoms.values()), (epoch,))
                try:
                    if projection_key is None:
                        candidate = inspect_recollection_experience_snapshot(
                            snapshot, namespace=namespace, audience=("owner",),
                            purpose="context", experience_ref=experience_ref,
                            mood_key=mood_key, receipt=receipt, scheme=scheme)
                    else:
                        candidate = inspect_recollection_projection_snapshot(
                            snapshot, namespace=namespace, audience=("owner",),
                            purpose="context", projection_ref=projection_ref,
                            receipt=receipt, scheme=scheme)
                except (RecollectionSnapshotUnavailable,
                        RecollectionProjectionUnavailable) as exc:
                    raise UnavailableGuard("current recollection source is unavailable") from exc
                if projection_key is None:
                    result = CurrentRecollectionExperienceV1(
                        namespace, operation_id, candidate.experience, candidate.mood,
                        candidate.source_ref, candidate.source_kind,
                        candidate.assertion_status, candidate.provenance_eligibility,
                        candidate.read_versions, candidate.epoch,
                        epoch_row[0], epoch_row[1])
                else:
                    result = CurrentRecollectionProjectionV1(
                        namespace, operation_id, candidate.projection_ref,
                        candidate.recollection_ref, candidate.experience_ref,
                        candidate.experience, candidate.mood,
                        candidate.source_ref, candidate.source_kind,
                        candidate.assertion_status, candidate.provenance_eligibility,
                        candidate.subjective_weight, candidate.subjective_tone,
                        candidate.duration_interval, candidate.read_versions,
                        candidate.epoch, epoch_row[0], epoch_row[1])
                db.execute("COMMIT")
                return result
            except BaseException:
                if db.in_transaction:
                    db.execute("ROLLBACK")
                raise

        def final_check(result: CurrentRecollectionExperienceV1) -> None:
            current = store._db.execute(
                "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                "WHERE bot=? AND persona=?", namespace.as_tuple,
            ).fetchone()
            if current != (result.access_epoch, result.deletion_epoch):
                raise UnavailableGuard("recollection access or deletion epoch changed")

        return self._read_v2(
            authority, reader, owner_principal=principal,
            owner_session_proof=(owner_session_token, owner_session_request),
            final_check=final_check)

    @staticmethod
    def _owner_session_proof(actor: str, token: str | None,
                             request: object | None) -> tuple[str, object] | None:
        from .authority_service.v2_owner_session import OwnerSessionLoginRequestV1

        if token is None and request is None:
            return None
        if (type(token) is not str or not token
                or type(request) is not OwnerSessionLoginRequestV1
                or type(actor) is not str or not actor):
            raise UnavailableGuard("Owner signed session proof is unavailable")
        return token, request

    def _current_owner_principal(self, actor: str, namespace: NamespaceId):
        from .authority_service.v2_owner_contract import OwnerPrincipalV1

        if self.__owner_principal_resolver is None:
            raise UnavailableGuard("current Owner pairing is unavailable")
        try:
            principal = self.__owner_principal_resolver(actor, namespace)
        except Exception as exc:
            raise UnavailableGuard("current Owner pairing is unavailable") from exc
        if type(principal) is not OwnerPrincipalV1:
            raise UnavailableGuard("current Owner pairing is unavailable")
        return principal

    def _owner_graph_binding_locked(self, authority: AuthorityContext,
                                    principal, *, target_admission=None, storage_admission=None, current_guard=None) -> OwnerLeaseBindingV1:
        """Resolve the graph ACL and its independently finalized issue proof."""
        from .authority_service.v2_owner_contract import (
            OwnerGraphCommitProofV1, OwnerPrincipalV1,
            canonical_digest as owner_contract_digest,
        )

        if type(principal) is not OwnerPrincipalV1:
            raise UnavailableGuard("trusted Owner principal is unavailable")
        store = self.__store
        namespace = authority.namespace
        metadata, graph_epoch = self._v2_graph_stamp(namespace)
        target = metadata.requirements
        db = store._db
        atom = db.execute(
            "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
            (owner_grant_key(*namespace.as_tuple).token,),
        ).fetchone()
        proof_row = db.execute(
            "SELECT operation_id,request_digest,grant_id,grant_digest,"
            "graph_incarnation,graph_access_epoch,graph_epoch,"
            "graph_receipt_digest,proof_json "
            "FROM graph_owner_issue_operations_v1 WHERE bot=? AND persona=?",
            namespace.as_tuple,
        ).fetchone()
        epochs = db.execute(
            "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
            "WHERE bot=? AND persona=?", namespace.as_tuple,
        ).fetchone()
        if (atom is None or atom[0] != 1 or atom[2] != 1
                or proof_row is None or epochs is None):
            raise UnavailableGuard("current Owner graph grant is unavailable")
        try:
            grant = json.loads(atom[1])
            validate_owner_grant_v1(grant)
            proof = OwnerGraphCommitProofV1(
                namespace, proof_row[0], proof_row[1], proof_row[2],
                proof_row[3], proof_row[4], 1, proof_row[5],
                proof_row[6], proof_row[7])
        except (TypeError, ValueError, KeyError) as exc:
            raise UnavailableGuard("durable Owner graph grant is invalid") from exc
        if (atom[1] != canonical_json(grant)
                or proof_row[8] != canonical_json(asdict(proof))
                or "sha256:" + canonical_digest(grant) != proof.grant_digest
                or grant["grant_id"] != proof.grant_id
                or grant["issue_operation_id"] != proof.operation_id
                or grant["principal"] != asdict(principal)
                or grant["graph_incarnation"] != proof.graph_incarnation
                or grant["authority_id"] != target.authority_id
                or (target_admission is None and storage_admission is None and (
                    grant["graph_incarnation"] != target.graph_incarnation
                    or grant["installation_id"] != self.__content_fence_v2.installation_grant.installation_id
                    or grant["activation_generation"] != authority.activation_generation))
                or grant["scope"] != "/".join(namespace.as_tuple)
                or target.namespace != namespace
                or target.activation_generation != authority.activation_generation
                or proof.graph_access_epoch > epochs[0]
                or proof.graph_epoch > graph_epoch.revision
                or "workbench.read" not in grant["capabilities"]
                or authority.purpose not in grant["purposes"]
                or not set(authority.audience).issubset(grant["audiences"])):
            raise AuthorityDenied("Owner graph grant does not authorize this read")
        if target_admission is not None and storage_admission is not None:
            raise AuthorityDenied("Owner location cannot mix migration and storage admissions")
        if storage_admission is not None:
            from .authority_service.d12_owner_storage_admission_v1 import require_owner_storage_graph_binding_v1
            require_owner_storage_graph_binding_v1(storage_admission, authority=authority, principal=principal,
                grant=grant, proof=proof, metadata=metadata,
                installation_id=self.__content_fence_v2.installation_grant.installation_id,
                holder=self.__holder, guard=current_guard)
        if target_admission is not None:
            from .authority_service.d12_target_owner_admission_v1 import require_target_owner_graph_binding_v1
            require_target_owner_graph_binding_v1(target_admission, authority=authority, principal=principal,
                grant=grant, proof=proof, metadata=metadata,
                installation_id=self.__content_fence_v2.installation_grant.installation_id,
                holder=self.__holder, guard=current_guard)
        return OwnerLeaseBindingV1(
            principal, authority.actor, namespace, authority.purpose,
            authority.audience[0], grant["grant_id"], grant["scope"],
            grant["issuer_ref"], frozenset(grant["capabilities"]),
            frozenset(grant["purposes"]), frozenset(grant["audiences"]),
            proof.grant_digest, 1, epochs[0], epochs[1], target.graph_incarnation,
            owner_contract_digest(proof), 1, 0, target_admission, storage_admission)

    def _owner_binding_in_fence(self, authority: AuthorityContext,
                                scope: FenceScope, principal,
                                expected: OwnerLeaseBindingV1 | None,
                                owner_session_proof: tuple[str, object] | None = None,
                                ) -> tuple[OwnerAuthorizationGuardV1, OwnerLeaseBindingV1]:
        port = self.__content_fence_v2
        if (principal is None and expected is None):
            raise UnavailableGuard("Owner lease has no paired principal")
        paired = self._current_owner_principal(
            authority.actor, authority.namespace)
        if paired != (expected.principal if expected is not None else principal):
            raise UnavailableGuard("Owner pairing changed")
        reader = getattr(port, "get_current_owner_guard_for_fence", None)
        if not callable(reader):
            raise UnavailableGuard("current Owner guard fence port is unavailable")
        proof_args = {}
        if owner_session_proof is not None:
            token, request = owner_session_proof
            if request.principal != paired:
                raise UnavailableGuard("Owner signed session principal differs")
            proof_args = {
                "owner_actor_id": authority.actor,
                "owner_session_token": token,
                "owner_session_request": request,
            }
        target_reader = getattr(port, "get_current_owner_authority_for_fence_v1", None)
        if owner_session_proof is not None and callable(target_reader):
            reader = target_reader
        guarded = reader(
            namespace=authority.namespace, authority_namespace=scope.authority_namespace,
            permit=scope.permit, **proof_args)
        target_admission = storage_admission = None
        from .authority_service.d12_target_owner_admission_v1 import D12CurrentOwnerAuthorityV1
        if type(guarded) is tuple and len(guarded) == 2 and type(guarded[0]) is D12CurrentOwnerAuthorityV1:
            target_admission = guarded[0].target_admission
            storage_admission = guarded[0].storage_admission
            guarded = (guarded[0].guard, guarded[1])
        if (type(guarded) is not tuple or len(guarded) != 2
                or type(guarded[0]) is not OwnerAuthorizationGuardV1
                or guarded[1] != scope.permit):
            raise UnavailableGuard("current Owner Authority head is unavailable")
        guard = guarded[0]
        if expected is not None:
            principal = expected.principal
        with self.__store._lock:
            metadata, epoch = self._v2_graph_stamp(authority.namespace)
            if (metadata.graph_revision != scope.graph_revision
                    or epoch != scope.graph_epoch):
                raise StaleRead("Owner graph stamp changed under read fence")
            current = self._owner_graph_binding_locked(authority, principal,
                target_admission=target_admission, storage_admission=storage_admission, current_guard=guard)
        if (guard.authority_id != scope.pinned_anchor.authority_id
                or (target_admission is None and guard.installation_id
                    != self.__content_fence_v2.installation_grant.installation_id)
                or guard.namespace != authority.namespace
                or guard.authorization_revision != current.authorization_revision
                or guard.authorization_head != current.authorization_head
                or guard.minimum_revocation_revision != 0
                or guard.minimum_revocation_epoch != current.revocation_epoch
                or guard.pending_revoke_operation_id is not None
                or (expected is not None and current != expected)):
            raise UnavailableGuard("Owner lease differs from current grant or revoke head")
        return guard, current

    def _admin(self, bootstrap: object) -> None:
        if bootstrap is not self.__bootstrap:
            raise AuthorityDenied("host bootstrap authority required")

    @contextmanager
    def _admin_write_gate(self, namespace: NamespaceId):
        """Allow installer bookkeeping only on this authority's active holder."""
        if not isinstance(self.__store, ProductionGraphStore):
            yield
            return
        if self.__content_fence_v2 is not None:
            raise UnavailableGuard("v2 graph write path is not admitted")
        try:
            proof = self.__migration_authority.current(namespace_ref(namespace))
        except Exception as exc:
            raise UnavailableGuard("installer write activation is unavailable") from exc
        with self._content_fence(namespace, proof.generation, "write"):
            try:
                self.__migration_authority.check(
                    namespace=namespace_ref(namespace), holder=self.__holder,
                    generation=proof.generation, operation="write")
            except Exception as exc:
                raise UnavailableGuard("installer write activation is unavailable") from exc
            yield

    def set_guard_version(self, bootstrap: object, namespace: NamespaceId,
                          kind: str, ref: str, version: str | int) -> None:
        self._admin(bootstrap)
        if not isinstance(namespace, NamespaceId) or not kind or not ref or not str(version):
            raise ValueError("invalid guard version")
        store = self.__store
        with self._admin_write_gate(namespace), store._lock:
            store._ensure_open()
            store._db.execute("BEGIN IMMEDIATE")
            try:
                store._db.execute(
                    "INSERT INTO graph_guard_versions(bot,persona,kind,ref,version) "
                    "VALUES(?,?,?,?,?) ON CONFLICT(bot,persona,kind,ref) DO UPDATE "
                    "SET version=excluded.version",
                    namespace.as_tuple + (kind, ref, str(version)),
                )
                store._db.execute("COMMIT")
            except BaseException:
                store._db.execute("ROLLBACK")
                raise

    def advance_authority_epoch(self, bootstrap: object, namespace: NamespaceId,
                                kind: str) -> int:
        self._admin(bootstrap)
        if kind not in {"access", "delete"}:
            raise ValueError("kind must be access or delete")
        store = self.__store
        with self._admin_write_gate(namespace), store._lock:
            store._ensure_open()
            store._db.execute("BEGIN IMMEDIATE")
            try:
                store._db.execute(
                    "INSERT OR IGNORE INTO graph_authority_epochs(bot,persona) VALUES(?,?)",
                    namespace.as_tuple,
                )
                column = kind + "_epoch"
                store._db.execute(
                    f"UPDATE graph_authority_epochs SET {column}={column}+1 "
                    "WHERE bot=? AND persona=?", namespace.as_tuple,
                )
                revision = store._db.execute(
                    f"SELECT {column} FROM graph_authority_epochs WHERE bot=? AND persona=?",
                    namespace.as_tuple,
                ).fetchone()[0]
                store._db.execute("COMMIT")
                return revision
            except BaseException:
                store._db.execute("ROLLBACK")
                raise

    def _authorize(self, lease: object, authority: AuthorityContext,
                   domains: frozenset[str], *, owner_read: bool = False) -> None:
        recovery = (self.__contact_recovery_leases_v3.get(lease)
                    if isinstance(lease, _AuthorityLease) else None)
        if recovery is not None:
            from .runtime.contact_owner_invocation_v3 import require_authenticated_contact_restart_v3
            from .runtime.contact_final_ack_v1 import contact_owner_call_v1
            require_authenticated_contact_restart_v3(recovery, self,
                operation_id=recovery.operation_id, request_digest=recovery.request_digest)
            call = contact_owner_call_v1(self, authority, lease,
                recovery.operation_id, recovery.request_digest)
            if (not owner_read or domains != frozenset({'d08'})
                    or authority is not recovery.authority or call is None
                    or call.request != recovery.request):
                raise AuthorityDenied('Contact restart lease only resumes its authenticated invocation')
        try:
            ref, actor, issuer_domain, namespace, allowed, owner_scope, generation = self.__leases[lease]
        except (KeyError, TypeError):
            raise AuthorityDenied("unknown process authority") from None
        if (authority.capability_ref != ref or authority.actor != actor
                or authority.issuer_domain != issuer_domain
                or authority.namespace != namespace
                or authority.activation_generation != generation
                or not set(authority.owner_scope).issubset(owner_scope)
                or not domains.issubset(allowed)):
            raise AuthorityDenied("authority assertion does not match process grant")
        if (issuer_domain == "d12"
                and isinstance(self.__store, ProductionGraphStore)):
            binding = self.__owner_leases.get(lease)
            if (not owner_read or binding is None
                    or binding.actor != authority.actor
                    or binding.namespace != authority.namespace
                    or binding.purpose != authority.purpose
                    or authority.audience != (binding.audience,)
                    or authority.provider_policy_ref != "owner-grant-v1"):
                raise UnavailableGuard("current Owner graph read lease is unavailable")

    @staticmethod
    def _version(db, namespace: NamespaceId, kind: str, ref: str) -> str:
        row = db.execute(
            "SELECT version FROM graph_guard_versions WHERE bot=? AND persona=? "
            "AND kind=? AND ref=?", namespace.as_tuple + (kind, ref),
        ).fetchone()
        if row is None:
            raise UnavailableGuard(f"{kind} authority is unavailable")
        return row[0]

    def _admit_ingress_deadline(self, namespace: NamespaceId,
                                operation_id: str, generation: int,
                                deadline_utc: float) -> None:
        """Rebind durable UTC to this process; never trust envelope monotonic."""
        if self.__ingress_clock is None:
            raise UnavailableGuard("installation-owned ingress clock is unavailable")
        try:
            sample = self.__ingress_clock()
        except Exception as exc:
            raise UnavailableGuard("trusted ingress clock read failed") from exc
        if type(sample) is not IngressClockSample or not sample.clock_trusted:
            raise UnavailableGuard("trusted ingress clock is unavailable")
        if sample.wall_now_utc >= deadline_utc:
            raise UnavailableGuard("ingress UTC deadline has expired")
        key = (namespace, operation_id, generation)
        prior = self.__ingress_clock_bindings.get(key)
        if prior is None:
            monotonic_deadline = sample.monotonic_now + (
                deadline_utc - sample.wall_now_utc)
            if not math.isfinite(monotonic_deadline):
                raise UnavailableGuard("ingress monotonic deadline cannot be rebuilt")
            self.__ingress_clock_bindings[key] = _IngressClockBinding(
                sample.clock_epoch, deadline_utc, monotonic_deadline,
                sample.wall_now_utc, sample.monotonic_now)
            return
        if (prior.clock_epoch != sample.clock_epoch
                or prior.deadline_utc != deadline_utc
                or sample.monotonic_now < prior.last_monotonic
                or sample.wall_now_utc < prior.last_wall_utc):
            raise UnavailableGuard("ingress process clock binding changed")
        if sample.monotonic_now >= prior.monotonic_deadline:
            raise UnavailableGuard("ingress monotonic deadline has expired")
        self.__ingress_clock_bindings[key] = _IngressClockBinding(
            prior.clock_epoch, prior.deadline_utc,
            prior.monotonic_deadline, sample.wall_now_utc,
            sample.monotonic_now)

    def _exact_ingress_without_query(self, db, bundle: DomainBundle, *,
                                     deadline_check=None) -> bool:
        """Only exact issued first ingress, optionally with media, omits a range predicate."""
        if not isinstance(bundle, DomainBundle):
            return False
        envelope = bundle.envelope
        identity = envelope.identity
        authority = envelope.authority
        guard = envelope.version_guard
        namespace = authority.namespace
        if (identity.phase != "ingress" or authority.issuer_domain != "d06"
                or guard.query_epochs or len(guard.resource_lease_versions) != 1
                or len(guard.read_versions) not in (4, 5)
                or any(read.revision != 0 for read in guard.read_versions)
                or len(envelope.source_qualification.source_refs) != 1
                or envelope.input_refs != envelope.source_qualification.source_refs
                or tuple(proposal.domain for proposal in bundle.proposals) != ("d06", "d11")
                or len(bundle.persistent_job_refs) != 1
                or len(bundle.outbox_refs) != 1):
            return False
        if authority.capability_ref != _operation_capability_ref(
                namespace, authority.actor, "d06", frozenset({"d06", "d11"}),
                authority.activation_generation, identity.operation_id):
            return False
        try:
            source = AtomKey.from_token(envelope.source_qualification.source_refs[0])
            if (source != source_key(*namespace.as_tuple, source.owner.subject or "")
                    or NamespaceId.from_key(source) != namespace):
                return False
            access = access_key(*namespace.as_tuple, source.owner.subject or "")
            from .runtime.source_attachment_graph_v2 import (
                media_source_key, read_media_blobs,
            )
            media = media_source_key(namespace, source.owner.subject or "")
            job = AtomKey.from_token(bundle.persistent_job_refs[0])
            outbox = AtomKey.from_token(bundle.outbox_refs[0])
        except (TypeError, ValueError):
            return False
        media_writes = tuple(
            write for write in bundle.proposals[0].typed_writes
            if write.key == media)
        media_present = len(guard.read_versions) == 5
        if (job.type_name != "runtime.job" or outbox.type_name != "runtime.outbox"
                or job.owner.kind != "activity" or outbox.owner.kind != "activity"
                or job.owner.subject != identity.activity_id
                or outbox.owner.subject != identity.activity_id
                or any(NamespaceId.from_key(key) != namespace for key in (job, outbox))
                or {read.key for read in guard.read_versions}
                != {source, access, job, outbox} | ({media} if media_present else set())
                or {write.key for write in bundle.proposals[0].typed_writes}
                != {source, access} | ({media} if media_present else set())
                or {write.key for write in bundle.proposals[1].typed_writes}
                != {job, outbox}):
            return False
        if media_present:
            if (len(media_writes) != 1
                    or media_writes[0].value.get("source_ref") != source.token):
                return False
            try:
                read_media_blobs(db, namespace, source.owner.subject,
                                 media_writes[0].value)
            except ValueError:
                return False
        row = db.execute(
            "SELECT activation_generation,quote_id,policy_json "
            "FROM runtime_ingress_issuance "
            "WHERE bot=? AND persona=? AND operation_id=?",
            namespace.as_tuple + (identity.operation_id,),
        ).fetchone()
        sealed = db.execute(
            "SELECT bundle_digest FROM ingress_first_observations "
            "WHERE bot=? AND persona=? AND operation_id=?",
            namespace.as_tuple + (identity.operation_id,),
        ).fetchone()
        if (row is None or row[0] != authority.activation_generation
                or row[1] != guard.resource_lease_versions[0].ref
                or sealed is None or sealed[0] != bundle.digest):
            return False
        try:
            policy = IngressIssuancePolicy(**json.loads(row[2]))
        except (TypeError, ValueError, KeyError) as exc:
            raise UnavailableGuard("durable ingress policy is invalid") from exc
        if policy.deadline_utc != envelope.deadline_utc:
            return False
        if deadline_check is None:
            self._admit_ingress_deadline(
                namespace, identity.operation_id,
                authority.activation_generation, policy.deadline_utc)
        else:
            deadline_check(policy.deadline_utc)
        return True

    def _current_scene_proof_locked(self, db, namespace, receipt, source_atom,
                                    owner_guard, graph_epoch):
        """Join current graph heads to a committed ingress in this SQLite read."""
        from .authority_service.v2_owner_contract import (
            OwnerGraphCommitProofV1, canonical_digest as owner_contract_digest,
        )
        from .domains.d03 import RoleBinding, RoleBindingRequest
        from .runtime.first_ingress_v2 import scene_ref_for_conversation

        if (type(owner_guard) is not OwnerAuthorizationGuardV1
                or source_atom is None or not source_atom.valid
                or source_atom.key.type_name != "memory.source"):
            raise UnavailableGuard("current scene Owner or source is unavailable")
        source = SourceRecord.from_dict(source_atom.value)
        identity = json.loads(receipt.identity_json)
        if (type(identity) is not dict
                or identity.get("namespace") != list(namespace.as_tuple)
                or identity.get("source_ref") != source.source_id
                or source_atom.key.owner.subject != source.source_id
                or source.recorded_at != receipt.learned_at):
            raise UnavailableGuard("current scene ingress source differs")
        scene_ref = scene_ref_for_conversation(
            namespace, identity["platform_ref"], identity["conversation_ref"])
        visibility = identity["visibility"]
        metadata, current_epoch = self._v2_graph_stamp(namespace)
        if current_epoch != graph_epoch:
            raise StaleRead("current scene graph epoch changed")
        target = metadata.requirements
        grant_row = db.execute(
            "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
            (owner_grant_key(*namespace.as_tuple).token,),
        ).fetchone()
        proof_row = db.execute(
            "SELECT operation_id,request_digest,grant_id,grant_digest,"
            "graph_incarnation,graph_access_epoch,graph_epoch,"
            "graph_receipt_digest,proof_json "
            "FROM graph_owner_issue_operations_v1 WHERE bot=? AND persona=?",
            namespace.as_tuple,
        ).fetchone()
        epochs = db.execute(
            "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
            "WHERE bot=? AND persona=?", namespace.as_tuple,
        ).fetchone()
        if grant_row is None or proof_row is None or epochs is None:
            raise UnavailableGuard("current scene Owner graph proof is absent")
        try:
            grant = json.loads(grant_row[1])
            validate_owner_grant_v1(grant)
            proof = OwnerGraphCommitProofV1(
                namespace, proof_row[0], proof_row[1], proof_row[2],
                proof_row[3], proof_row[4], grant["grant_revision"],
                proof_row[5], proof_row[6], proof_row[7])
        except (TypeError, ValueError, KeyError) as exc:
            raise UnavailableGuard("current scene Owner graph proof is invalid") from exc
        if (grant_row[0] != grant["grant_revision"] or grant_row[2] != 1
                or grant_row[1] != canonical_json(grant)
                or proof_row[8] != canonical_json(asdict(proof))
                or "sha256:" + canonical_digest(grant) != proof.grant_digest
                or grant["grant_id"] != proof.grant_id
                or grant["issue_operation_id"] != proof.operation_id
                or grant["activation_generation"] != target.activation_generation
                or grant["scope"] != "/".join(namespace.as_tuple)
                or target.namespace != namespace
                or grant["graph_incarnation"] != target.graph_incarnation
                or proof.graph_incarnation != target.graph_incarnation
                or proof.graph_access_epoch > epochs[0]
                or proof.graph_epoch > graph_epoch.revision
                or owner_guard.namespace != namespace
                or owner_guard.authority_id != target.authority_id
                or owner_guard.authority_id != grant["authority_id"]
                or owner_guard.installation_id != grant["installation_id"]
                or owner_guard.installation_id
                != self.__content_fence_v2.installation_grant.installation_id
                or owner_guard.authorization_revision != grant["grant_revision"]
                or owner_guard.authorization_head != owner_contract_digest(proof)
                or target.revocation_epoch
                != owner_guard.minimum_revocation_epoch
                or owner_guard.minimum_revocation_revision != 0
                or owner_guard.minimum_revocation_epoch != 0
                or owner_guard.pending_revoke_operation_id is not None):
            # The only durable graph authorization here is the initial issue.
            # A later Owner head requires a separately authorized refresh.
            raise UnavailableGuard("current scene Owner head lacks matching graph authorization")
        role, _, role_epoch, _ = self._scene_binding_state_locked(
            namespace, owner_guard)
        if role_epoch != graph_epoch:
            raise StaleRead("current scene D01 epoch changed")
        rows = db.execute(
            "SELECT token,revision,value FROM graph_atoms WHERE bot=? AND persona=? "
            "AND owner_kind='scene' AND subject=? "
            "AND type_name='d03.role_binding' AND valid=1",
            namespace.as_tuple + (scene_ref,),
        ).fetchall()
        applicable = []
        for token, revision, encoded in rows:
            key = AtomKey.from_token(token)
            try:
                value = json.loads(encoded)
                binding = RoleBinding(**{
                    **value, "norm_refs": tuple(value["norm_refs"]),
                    "source_refs": tuple(value["source_refs"]),
                })
                at_occurrence = RoleBindingRequest(
                    f"persona:{namespace.persona_id}", None, None, scene_ref,
                    "message", "context", source.occurred_at, True)
                at_learning = replace(at_occurrence, at_time=source.recorded_at)
            except (TypeError, ValueError, KeyError) as exc:
                raise UnavailableGuard("current scene binding is invalid") from exc
            if (key.name != binding.role_binding_id
                    or key.owner.subject != scene_ref
                    or revision != binding.binding_version
                    or binding.scene_ref != scene_ref):
                raise UnavailableGuard("current scene binding identity differs")
            if (binding.scope_selector == "scene"
                    and binding.visibility_scope == visibility
                    and binding.target_entity_ref is None
                    and binding.group_ref is None
                    and binding.applies_to(at_occurrence)
                    and binding.applies_to(at_learning)):
                applicable.append((key, revision, binding))
        if len(applicable) != 1:
            raise UnavailableGuard("current scene has no unique applicable binding")
        key, revision, binding = applicable[0]
        receipt_row = db.execute(
            "SELECT r.operation_id,r.receipt_json,r.pre_graph_revision,"
            "r.pre_graph_epoch,r.post_graph_revision,r.post_graph_epoch,"
            "h.value,h.valid FROM graph_history AS h "
            "JOIN graph_scene_binding_receipts_v1 AS r "
            "ON r.bot=h.event_bot AND r.persona=h.event_persona "
            "AND r.operation_id=h.event_id "
            "WHERE h.token=? AND h.revision=? "
            "AND h.event_session='d03-scene-binding'",
            (key.token, revision),
        ).fetchone()
        if receipt_row is None:
            raise UnavailableGuard("current scene binding lacks fenced history receipt")
        try:
            payload = json.loads(receipt_row[1])
            payload["namespace"] = NamespaceId(**payload["namespace"])
            binding_receipt = SceneBindingReceiptV1(**payload)
        except (TypeError, ValueError, KeyError) as exc:
            raise UnavailableGuard("current scene binding receipt is invalid") from exc
        if (receipt_row[1] != canonical_json(asdict(binding_receipt))
                or receipt_row[6] != encoded or receipt_row[7] != 1
                or receipt_row[4] != receipt_row[2] + 1
                or receipt_row[5] != receipt_row[3] + 1
                or binding_receipt.operation_id != receipt_row[0]
                or binding_receipt.namespace != namespace
                or binding_receipt.scene_ref != scene_ref
                or binding_receipt.binding_id != binding.role_binding_id
                or binding_receipt.role_head_id != role.head_id
                or binding_receipt.owner_grant_id != grant["grant_id"]
                or binding_receipt.owner_authorization_head
                != owner_guard.authorization_head
                or binding_receipt.graph_incarnation != target.graph_incarnation
                or binding_receipt.graph_revision != receipt_row[4]
                or binding_receipt.graph_epoch != receipt_row[5]
                or binding_receipt.graph_revision > metadata.graph_revision
                or binding_receipt.graph_epoch > graph_epoch.revision):
            raise UnavailableGuard("current scene binding receipt differs from current heads")
        return CurrentSceneProof(
            source.source_id, scene_ref, visibility, source.recorded_at,
            graph_epoch.revision, target.graph_incarnation, grant["grant_id"],
            owner_guard.authorization_revision, owner_guard.authorization_head,
            owner_guard.minimum_revocation_epoch, role.head_id,
            binding.role_binding_id, revision, binding_receipt.operation_id,
            binding_receipt.graph_epoch,
        )

    def _check_guard(self, db, bundle: DomainBundle, *,
                     ingress_deadline_check=None,
                     scene_owner_guard=None) -> GraphSnapshot:
        store = self.__store
        envelope = bundle.envelope
        namespace = envelope.authority.namespace
        guard = envelope.version_guard
        if guard.catalogue_version != store._registry.catalogue_hash:
            raise StaleRead("type catalogue changed")
        for kind, version in (("scheme", guard.scheme_version),
                              ("operator", guard.operator_version),
                              ("policy", guard.policy_version)):
            if self._version(db, namespace, kind, "current") != version:
                raise StaleRead(f"{kind} version changed")
        if self._version(db, namespace, "activation", "current") != str(
                envelope.authority.activation_generation):
            raise StaleRead("activation generation changed")
        # A namespace string flag cannot prove a particular worker still owns
        # its job. Runtime job identity/fence is checked inside the same commit.
        budget = get_budget_lease(db, envelope.parent_budget_lease_ref)
        if (budget.state != "active" or
                (budget.bot_id, budget.persona_id) != namespace.as_tuple):
            raise UnavailableGuard("parent budget lease is unavailable for this namespace")
        epoch_row = db.execute(
            "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
            "WHERE bot=? AND persona=?", namespace.as_tuple,
        ).fetchone()
        access_epoch, delete_epoch = epoch_row if epoch_row else (0, 0)
        if (guard.access_epoch, guard.delete_epoch) != (access_epoch, delete_epoch):
            raise StaleRead("access or deletion epoch changed")
        graph_epoch = GraphStore.graph_epoch(
            store, *namespace.as_tuple, _capability=self.__graph_capability)
        if not guard.query_epochs and not self._exact_ingress_without_query(
                db, bundle, deadline_check=ingress_deadline_check):
            raise UnavailableGuard("namespace query epoch is required")
        for query in guard.query_epochs:
            if query.namespace != namespace or query.revision != graph_epoch.revision:
                raise StaleRead("positive or negative query changed")
        for kind, refs in (("source_grant", guard.source_grant_refs),
                           ("focus_lease", guard.focus_lease_versions),
                           ("resource_lease", guard.resource_lease_versions)):
            for item in refs:
                if self._version(db, namespace, kind, item.ref) != str(item.version):
                    raise StaleRead(f"{kind} changed")
        atoms = []
        for read in guard.read_versions:
            if NamespaceId.from_key(read.key) != namespace:
                raise AuthorityDenied("cross-namespace read")
            store._validate_key(read.key)
            row = db.execute(
                "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                (read.key.token,),
            ).fetchone()
            revision = row[0] if row else 0
            if revision != read.revision:
                raise StaleRead("read version changed")
            atoms.append(GraphAtom(read.key, revision, json.loads(row[1]), bool(row[2]))
                         if row else GraphAtom(read.key, 0, {}, False))
        ingress_receipts = []
        host_observed = any(
                proposal.domain == "d03" and any(
                    write.key.type_name == "d03.world_event"
                    and (write.value.get("kind") == "message_received"
                         or write.value.get("reality") == "host_observed")
                    for write in proposal.typed_writes)
                for proposal in bundle.proposals)
        if host_observed:
            from .runtime.ingress_observation import read_committed_ingress_identity

            for source_ref in envelope.source_qualification.source_refs:
                key = self._parse_ref(source_ref, namespace)
                if key.type_name != "memory.source" or key.owner.subject is None:
                    raise UnavailableGuard("host arrival lacks a source identity")
                receipt = read_committed_ingress_identity(
                    db, namespace, key.owner.subject)
                if receipt is not None:
                    ingress_receipts.append(receipt)
        scene_proofs = ()
        if host_observed and scene_owner_guard is not None:
            if len(ingress_receipts) != 1 or len(envelope.source_qualification.source_refs) != 1:
                raise UnavailableGuard("current scene needs one committed host ingress")
            source_key_current = self._parse_ref(
                envelope.source_qualification.source_refs[0], namespace)
            source_atom = next((atom for atom in atoms
                                if atom.key == source_key_current), None)
            scene_proofs = (self._current_scene_proof_locked(
                db, namespace, ingress_receipts[0], source_atom,
                scene_owner_guard, graph_epoch),)
        return GraphSnapshot(tuple(atoms), (graph_epoch,),
                             tuple(ingress_receipts), scene_proofs)

    @staticmethod
    def _parse_ref(ref: str, namespace: NamespaceId) -> AtomKey:
        key = AtomKey.from_token(ref)
        if NamespaceId.from_key(key) != namespace:
            raise AuthorityDenied("bundle reference crosses namespace")
        return key

    def _first_ingress_boundary_locked(self, namespace: NamespaceId,
                                       guard: OwnerAuthorizationGuardV1,
                                       scene_ref: str, visibility: str,
                                       at_time: float) -> None:
        """Require the current Owner, active role, and fenced scene graph heads."""
        from .authority_service.v2_owner_contract import (
            OwnerGraphCommitProofV1, canonical_digest as owner_contract_digest,
        )
        from .domains.d03 import RoleBinding, RoleBindingRequest

        db = self.__store._db
        proof_row = db.execute(
            "SELECT operation_id,request_digest,grant_id,grant_digest,"
            "graph_incarnation,graph_access_epoch,graph_epoch,"
            "graph_receipt_digest,proof_json "
            "FROM graph_owner_issue_operations_v1 WHERE bot=? AND persona=?",
            namespace.as_tuple,
        ).fetchone()
        epochs = db.execute(
            "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
            "WHERE bot=? AND persona=?", namespace.as_tuple,
        ).fetchone()
        if proof_row is None or epochs != (1, 0):
            raise UnavailableGuard("first ingress current Owner proof is absent")
        proof = OwnerGraphCommitProofV1(
            namespace, proof_row[0], proof_row[1], proof_row[2],
            proof_row[3], proof_row[4], 1, proof_row[5], proof_row[6],
            proof_row[7],
        )
        grant_row = db.execute(
            "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
            (owner_grant_key(*namespace.as_tuple).token,),
        ).fetchone()
        if grant_row is None or grant_row[0] != 1 or grant_row[2] != 1:
            raise UnavailableGuard("first ingress current Owner grant is absent")
        grant = json.loads(grant_row[1])
        validate_owner_grant_v1(grant)
        metadata, _ = self._v2_graph_stamp(namespace)
        if (proof_row[8] != canonical_json(asdict(proof))
                or grant_row[1] != canonical_json(grant)
                or "sha256:" + canonical_digest(grant) != proof.grant_digest
                or grant["grant_id"] != proof.grant_id
                or grant["issue_operation_id"] != proof.operation_id
                or grant["graph_incarnation"] != proof.graph_incarnation
                or proof.graph_incarnation != metadata.requirements.graph_incarnation
                or proof.graph_access_epoch != epochs[0]
                or guard.namespace != namespace
                or guard.authority_id != grant["authority_id"]
                or guard.installation_id
                != self.__content_fence_v2.installation_grant.installation_id
                or guard.installation_id != grant["installation_id"]
                or guard.authorization_revision != 1
                or guard.authorization_head != owner_contract_digest(proof)
                or guard.minimum_revocation_revision != 0
                or guard.minimum_revocation_epoch != 0
                or guard.pending_revoke_operation_id is not None):
            raise UnavailableGuard("first ingress current Owner head differs")
        role, _, _, _ = self._scene_binding_state_locked(namespace, guard)
        rows = db.execute(
            "SELECT token,revision,value FROM graph_atoms WHERE bot=? AND persona=? "
            "AND owner_kind='scene' AND subject=? "
            "AND type_name='d03.role_binding' AND valid=1",
            namespace.as_tuple + (scene_ref,),
        ).fetchall()
        if len(rows) != 1:
            raise UnavailableGuard("first ingress current scene binding is absent")
        token, revision, encoded = rows[0]
        key = AtomKey.from_token(token)
        value = json.loads(encoded)
        try:
            binding = RoleBinding(**{
                **value, "norm_refs": tuple(value["norm_refs"]),
                "source_refs": tuple(value["source_refs"]),
            })
            request = RoleBindingRequest(
                f"persona:{namespace.persona_id}", None, None, scene_ref,
                "message", "context", at_time, True)
        except (TypeError, ValueError, KeyError) as exc:
            raise UnavailableGuard("first ingress current scene binding is invalid") from exc
        if (key.name != binding.role_binding_id
                or key.owner.subject != scene_ref
                or revision != binding.binding_version
                or binding.scene_ref != scene_ref
                or binding.scope_selector != "scene"
                or binding.visibility_scope != visibility
                or not binding.applies_to(request)):
            raise AuthorityDenied("first ingress scene does not admit this conversation")
        receipt_row = db.execute(
            "SELECT r.receipt_json FROM graph_history AS h "
            "JOIN graph_scene_binding_receipts_v1 AS r "
            "ON r.bot=h.event_bot AND r.persona=h.event_persona "
            "AND r.operation_id=h.event_id "
            "WHERE h.token=? AND h.revision=? "
            "AND h.event_session='d03-scene-binding'",
            (token, revision),
        ).fetchone()
        if receipt_row is None:
            raise UnavailableGuard("first ingress scene lacks fenced binding receipt")
        scene_receipt = json.loads(receipt_row[0])
        if (scene_receipt.get("scene_ref") != scene_ref
                or scene_receipt.get("binding_id") != binding.role_binding_id
                or scene_receipt.get("role_head_id") != role.head_id
                or scene_receipt.get("owner_grant_id") != proof.grant_id
                or scene_receipt.get("owner_authorization_head")
                != guard.authorization_head):
            raise UnavailableGuard("first ingress scene receipt differs from current heads")

    def commit_first_ingress_v2(self, bootstrap: object, host: IngressHostFacts,
                                installation_policy, clock_policy,
                                encoding_policy,
                                reply_source_policy=None, *,
                                source_admission_v2=None) -> CommitReceipt:
        """Commit the first reported source and encoding job in one fenced write."""
        from .authority_service.v2_contract import FencePermitV2, from_wire, to_wire
        from .domains.d06 import D06DomainAdapter, SourceAdmission
        from .domains.d06.attachment_contract_v2 import SourceAdmissionV2
        from .runtime.source_attachment_graph_v2 import (
            insert_media_blobs, media_source_key, media_source_value,
            read_media_blobs,
        )
        from .host.authority_profile import (
            AdminIngressClockPolicy, AdminIngressEncodingPolicy,
            AdminD06PrivateReplySourcePolicy,
        )
        from .installation_policy import AdminInstallationPolicy
        from .runtime.d11_types import runtime_job_key, runtime_outbox_key
        from .runtime.first_ingress_bundle import build_first_ingress_bundle
        from .runtime.first_ingress_v2 import (
            finish_digest, ingress_ids, policy_identity,
            scene_ref_for_conversation, trusted_upper,
        )
        from .runtime.issuers import (
            D02ResourceIssuer, D11BudgetJobIssuer, ResourceQuote,
            install_schema as install_issuer_schema,
        )
        from .runtime_contracts import (
            RUNTIME_SCHEMA, CommandEnvelope, OperationIdentity,
            VersionGuard, VersionedRef,
        )

        self._admin(bootstrap)
        if (installation_policy is None or clock_policy is None
                or encoding_policy is None):
            raise UnavailableGuard("v2 first ingress administrator policy missing; HOLD")
        if (type(host) is not IngressHostFacts
                or type(installation_policy) is not AdminInstallationPolicy
                or type(clock_policy) is not AdminIngressClockPolicy
                or type(encoding_policy) is not AdminIngressEncodingPolicy):
            raise TypeError("typed v2 first ingress facts and policies required")
        if reply_source_policy is not None and (
                type(reply_source_policy) is not AdminD06PrivateReplySourcePolicy
                or reply_source_policy.version != 1
                or reply_source_policy.scope != "private_conversation"
                or reply_source_policy.grant_expression is not True):
            raise AuthorityDenied("private reply source policy differs from host scope")
        if source_admission_v2 is not None and (
                type(source_admission_v2) is not SourceAdmissionV2
                or not host.text):
            raise UnavailableGuard("captioned verified media admission required; HOLD")
        store = self.__store
        port = self.__content_fence_v2
        if (not isinstance(store, ProductionGraphStore) or port is None
                or type(self.__d02_issuer) is not D02ResourceIssuer
                or type(self.__d11_issuer) is not D11BudgetJobIssuer
                or self.__d11_issuer.resource_issuer is not self.__d02_issuer):
            raise UnavailableGuard("v2 first ingress authorities are unavailable")
        namespace = host.namespace
        policy = installation_policy
        if namespace != policy.namespace or host.lineage.source_ref == "":
            raise AuthorityDenied("first ingress namespace or source differs")
        scene_ref = scene_ref_for_conversation(
            namespace, host.platform_ref, host.conversation_ref)
        source_identity, activity_id, operation_id, job_id, outbox_id, idem = (
            ingress_ids(host.lineage.source_ref))
        fingerprint = ingress_host_fingerprint(host)
        if source_admission_v2 is not None:
            fingerprint = canonical_digest({
                "host_fingerprint": fingerprint,
                "media_content_fingerprint": source_admission_v2.content_fingerprint,
            })
        identity_json = policy_identity(
            policy, clock_policy, encoding_policy, fingerprint,
            host.lineage.source_ref, host.conversation_ref)
        if reply_source_policy is not None:
            identity_data = json.loads(identity_json)
            identity_data["d06_private_reply_source"] = asdict(reply_source_policy)
            identity_json = canonical_json(identity_data)
        attempt_id = "first-ingress-" + canonical_digest({
            "namespace": list(namespace.as_tuple), "operation_id": operation_id,
            "identity": identity_json,
        })[:48]
        grant = policy.root_grant
        if ("d06.encode_source" not in grant.allowed_work_kinds
                or any(amount > grant.max_ceiling.get(name, 0)
                       for name, amount in encoding_policy.quote_ceiling.items())):
            raise UnavailableGuard("root grant does not admit source encoding ceiling")

        # All Authority calls precede the business lock. The profile's signed
        # root grant is read from the provisioned DB; no new grant is minted.
        with store._lock:
            provision = self._provision_row(store._db, namespace)
            if provision is None:
                raise UnavailableGuard("v2 namespace is not provisioned")
            genesis = self._decode_provision_receipt(provision)
            metadata, epoch = self._v2_graph_stamp(namespace)
            stored_grant, signature = self.__d11_issuer.signed_budget_grant_at_version(
                store._db, grant.lease_id, grant.version)
            if (stored_grant != grant or signature != genesis.root_grant_signature
                    or genesis.root_grant_id != grant.grant_id
                    or genesis.root_lease_id != grant.lease_id
                    or genesis.installation_id != policy.installation_id
                    or genesis.manifest_digest != policy.manifest_digest):
                raise UnavailableGuard("provisioned signed root grant differs")
            row = store._db.execute(
                "SELECT identity_json,learned_at,deadline_utc,fence_attempt_id,"
                "requirements_json,anchor_json,graph_revision,graph_epoch,"
                "monotonic_deadline "
                "FROM graph_first_ingress_intents_v2 WHERE bot=? AND persona=? "
                "AND operation_id=?", namespace.as_tuple + (operation_id,),
            ).fetchone()
        target = metadata.requirements
        if (target.namespace != namespace
                or target.authority_id != policy.expected_authority_id
                or target.authority_namespace != policy.authority_namespace
                or target.activation_generation != genesis.generation):
            raise UnavailableGuard("v2 first ingress recovery identity differs")
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("v2 first ingress Authority anchor differs")
        reading = None
        upper = None
        requirements_json = canonical_json(asdict(target))
        anchor_json = canonical_json(asdict(anchor))

        def read_clock():
            try:
                sample = port.read_ingress_clock(clock_policy)
                return sample, trusted_upper(sample)
            except Exception as exc:
                raise UnavailableGuard("paired ingress clock unavailable; HOLD") from exc

        if row is None:
            reading, upper = read_clock()
            learned_at = upper
            deadline = min(
                math.nextafter(math.fsum((learned_at,
                    encoding_policy.deadline_after_seconds)), -math.inf),
                grant.valid_until_utc)
            if (deadline <= learned_at or
                    host.occurred_at is not None and host.occurred_at > learned_at):
                raise UnavailableGuard("paired ingress clock cannot admit source")
            monotonic_deadline = reading.monotonic_after_seconds + (
                deadline - reading.utc_upper_bound_seconds)
            if not math.isfinite(monotonic_deadline):
                raise UnavailableGuard("paired ingress monotonic deadline is invalid")
            with store._lock:
                db = store._db
                db.execute("BEGIN IMMEDIATE")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise StaleRead("first ingress pre-stamp changed")
                    db.execute(
                        "INSERT OR IGNORE INTO graph_first_ingress_intents_v2"
                        "(bot,persona,operation_id,identity_json,learned_at,"
                        "deadline_utc,fence_attempt_id,requirements_json,"
                        "anchor_json,graph_revision,graph_epoch,"
                        "monotonic_deadline) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",
                        namespace.as_tuple + (operation_id, identity_json,
                        learned_at, deadline, attempt_id, requirements_json,
                        anchor_json, metadata.graph_revision, epoch.revision,
                        monotonic_deadline),
                    )
                    row = db.execute(
                        "SELECT identity_json,learned_at,deadline_utc,"
                        "fence_attempt_id,requirements_json,anchor_json,"
                        "graph_revision,graph_epoch,monotonic_deadline "
                        "FROM graph_first_ingress_intents_v2 "
                        "WHERE bot=? AND persona=? AND operation_id=?",
                        namespace.as_tuple + (operation_id,),
                    ).fetchone()
                    db.execute("COMMIT")
                except BaseException:
                    db.execute("ROLLBACK")
                    raise
        if (row[0] != identity_json or row[3] != attempt_id
                or row[4] != requirements_json or row[5] != anchor_json):
            raise UnavailableGuard("durable first ingress intent identity differs")
        learned_at, deadline = row[1:3]
        if (not math.isfinite(learned_at) or not math.isfinite(deadline)
                or not math.isfinite(row[8])
                or deadline <= learned_at or deadline > grant.valid_until_utc):
            raise UnavailableGuard("durable first ingress time is invalid")

        def deadline_check(expected):
            if expected != deadline or trusted_upper(reading) >= deadline:
                raise UnavailableGuard("first ingress paired deadline expired")

        with store._lock:
            db = store._db
            saved = db.execute(
                "SELECT digest,permit_json,pre_graph_revision,pre_graph_epoch,"
                "post_graph_revision,post_graph_epoch,finish_request_id,"
                "finish_request_digest FROM graph_bundle_fences_v2 "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone()
            rejected = db.execute(
                "SELECT status,permit_json,graph_revision,graph_epoch,"
                "finish_request_id,finish_request_digest "
                "FROM graph_first_ingress_rejections_v2 "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone()
            receipt = self._get_operation_fenced(
                AuthorityContext(policy.administrator_holder, "d06", "audit",
                    namespace, ("event", "activity"), "context",
                    (host.conversation_ref,), grant.policy_ref,
                    target.activation_generation), operation_id, v2=True)
        if receipt is not None or rejected is not None:
            if (receipt is None) == (rejected is None):
                raise UnavailableGuard("first ingress terminal ledgers disagree")
            encoded = saved[1] if receipt is not None and saved else (
                rejected[1] if rejected else None)
            if encoded is None:
                raise UnavailableGuard("first ingress terminal permit absent")
            permit = from_wire(json.loads(encoded))
            if (type(permit) is not FencePermitV2
                    or permit.operation_id != attempt_id
                    or permit.pinned_anchor != anchor
                    or permit.holder != self.__holder
                    or permit.subject != port.installation_grant.subject):
                raise UnavailableGuard("first ingress terminal permit differs")
            try:
                observed, state = port.get_fence_operation(
                    namespace=namespace,
                    authority_namespace=target.authority_namespace,
                    operation_id=attempt_id)
            except Exception as exc:
                raise FirstIngressOutcomeUnknown(
                    operation_id, "first ingress terminal Authority status unknown; HOLD"
                ) from exc
            if observed != permit or state not in {"active", "finished"}:
                raise UnavailableGuard("first ingress Authority status differs")
            if receipt is not None:
                with store._lock:
                    obs = store._db.execute(
                        "SELECT content_fingerprint,learned_at,bundle_digest "
                        "FROM ingress_first_observations WHERE bot=? AND persona=? "
                        "AND operation_id=?",
                        namespace.as_tuple + (operation_id,),
                    ).fetchone()
                    identity_row = store._db.execute(
                        "SELECT identity_json,content_fingerprint,learned_at,"
                        "bundle_digest FROM graph_first_ingress_identity_v1 "
                        "WHERE bot=? AND persona=? AND operation_id=?",
                        namespace.as_tuple + (operation_id,),
                    ).fetchone() if store._db.execute(
                        "SELECT 1 FROM sqlite_master WHERE type='table' AND "
                        "name='graph_first_ingress_identity_v1'").fetchone() else None
                if (saved[0] != receipt.operation_digest
                        or obs != (fingerprint, learned_at, receipt.operation_digest)
                        or identity_row != (
                            ingress_host_identity_json(host, operation_id),
                            fingerprint, learned_at, receipt.operation_digest)
                        or saved[2:4] != row[6:8]
                        or saved[4] != saved[2] + 1
                        or saved[5] != receipt.invalidated_epochs[0].revision
                        or saved[5] <= saved[3]
                        or saved[6] != "finish:" + attempt_id
                        or saved[7] != finish_digest(
                            attempt_id, permit.token, operation_id,
                            receipt.operation_digest)):
                    raise UnavailableGuard("first ingress business receipt differs")
                if source_admission_v2 is not None:
                    with store._lock:
                        media_key = media_source_key(namespace, host.lineage.source_ref)
                        media_row = store._db.execute(
                            "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                            (media_key.token,),
                        ).fetchone()
                        expected_media = media_source_value(
                            source_admission_v2,
                            source_key(*namespace.as_tuple, host.lineage.source_ref).token,
                        )
                        if (media_row is None or media_row[0] != 1
                                or media_row[2] != 1
                                or json.loads(media_row[1]) != expected_media
                                or read_media_blobs(store._db, namespace,
                                    host.lineage.source_ref, expected_media)
                                != tuple(item.content for item in
                                         source_admission_v2.attachments)):
                            raise UnavailableGuard("first ingress media original differs")
                if state == "active":
                    if (metadata.graph_revision != saved[4]
                            or epoch.revision != saved[5]):
                        raise UnavailableGuard("first ingress committed stamp differs")
                    scope = FenceScope(namespace, target.authority_namespace,
                        target.activation_generation, "write", attempt_id,
                        permit, anchor, NamespaceEpoch(*namespace.as_tuple,
                            row[7]), row[6])
                    try:
                        if port.validate_fence(scope) != permit:
                            raise UnavailableGuard("first ingress permit changed")
                        port.finish_fence(scope, request_id=saved[6],
                                          request_digest=saved[7])
                    except Exception as exc:
                        raise FirstIngressOutcomeUnknown(
                            operation_id,
                            "first ingress committed finish unconfirmed; HOLD"
                        ) from exc
                elif (metadata.graph_revision < saved[4]
                      or epoch.revision < saved[5]):
                    raise UnavailableGuard(
                        "finished first ingress lost its business recovery stamp")
                return receipt
            if (rejected[0] != "rejected_no_commit"
                    or rejected[2:4] != row[6:8]
                    or rejected[4] != "abort:" + attempt_id
                    or rejected[5] != finish_digest(
                        attempt_id, permit.token, operation_id, None,
                        rejected=True)):
                raise UnavailableGuard("first ingress rejection differs")
            scope = FenceScope(namespace, target.authority_namespace,
                target.activation_generation, "write", attempt_id,
                permit, anchor, NamespaceEpoch(*namespace.as_tuple, row[7]),
                row[6])
            if state == "active":
                if port.validate_fence(scope) != permit:
                    raise UnavailableGuard("first ingress rejected permit changed")
                try:
                    port.finish_fence(scope, request_id=rejected[4],
                                      request_digest=rejected[5])
                except Exception as exc:
                    raise FirstIngressOutcomeUnknown(
                        operation_id,
                        "first ingress rejected finish unconfirmed; HOLD"
                    ) from exc
            raise UnavailableGuard("first ingress terminal rejected_no_commit")
        if reading is None:
            reading, upper = read_clock()
        if upper >= deadline or upper >= grant.valid_until_utc:
            raise UnavailableGuard("first ingress paired deadline expired")
        if (metadata.graph_revision, epoch.revision) != row[6:8]:
            raise UnavailableGuard("uncommitted first ingress pre-stamp changed")
        try:
            # Authority treats the original active operation ID as an exact
            # retry, including after a lost begin response or process crash.
            permit = port.begin_fence(
                namespace=namespace,
                authority_namespace=target.authority_namespace,
                holder=self.__holder, generation=target.activation_generation,
                operation="write", operation_id=attempt_id,
                expected_anchor=anchor, retain_on_unknown=True)
        except Exception as exc:
            raise FirstIngressOutcomeUnknown(
                operation_id,
                "first ingress begin outcome unknown; HOLD original attempt") from exc
        scope = FenceScope(namespace, target.authority_namespace,
            target.activation_generation, "write", attempt_id, permit,
            anchor, epoch, metadata.graph_revision)
        if port.validate_fence(scope) != permit:
            raise UnavailableGuard("first ingress write permit changed")
        guard_reader = getattr(port, "get_current_owner_guard_for_fence", None)
        try:
            if not callable(guard_reader):
                raise UnavailableGuard("first ingress current Owner guard is unavailable")
            guarded = guard_reader(
                namespace=namespace, authority_namespace=target.authority_namespace,
                permit=permit)
            if (type(guarded) is not tuple or len(guarded) != 2
                    or type(guarded[0]) is not OwnerAuthorizationGuardV1
                    or guarded[1] != permit):
                raise UnavailableGuard("first ingress current Owner guard is unavailable")
            owner_guard = guarded[0]
        except Exception:
            self._reject_first_ingress_v2(
                namespace, operation_id, row, permit, scope)
            raise

        actor = policy.administrator_holder
        lease, capability_ref = self.grant(
            bootstrap, actor=actor, issuer_domain="d06", namespace=namespace,
            domains=("d06", "d11"),
            activation_generation=target.activation_generation,
            operation_id=operation_id)
        authority = AuthorityContext(
            actor, "d06", capability_ref, namespace, ("event", "activity"),
            "context", (host.conversation_ref,), grant.policy_ref,
            target.activation_generation)
        source = source_key(*namespace.as_tuple, host.lineage.source_ref)
        media_key = (media_source_key(namespace, host.lineage.source_ref)
                     if source_admission_v2 is not None else None)
        access = access_key(*namespace.as_tuple, host.lineage.source_ref)
        job_key = runtime_job_key(*namespace.as_tuple, activity_id, job_id)
        outbox_key = runtime_outbox_key(*namespace.as_tuple, activity_id, outbox_id)
        quote_id = "ingress-q-" + hashlib.sha256(
            canonical_json([*namespace.as_tuple, operation_id]).encode()
        ).hexdigest()[:40]
        ingress_policy = IngressIssuancePolicy(
            grant.lease_id, dict(encoding_policy.quote_ceiling),
            dict(grant.max_ceiling), deadline, grant.valid_until_utc,
            row[8],
            encoding_policy.snapshot_ref, encoding_policy.resource_ref,
            encoding_policy.character_interval_ref)
        result = None
        transaction_rolled_back = False
        try:
            with store._lock:
                db = store._db
                db.execute("BEGIN IMMEDIATE")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise StaleRead("first ingress recovery stamp changed")
                    if db.execute(
                        "SELECT identity_json,learned_at,deadline_utc,"
                        "fence_attempt_id,requirements_json,anchor_json,"
                        "graph_revision,graph_epoch,monotonic_deadline "
                        "FROM graph_first_ingress_intents_v2 WHERE bot=? "
                        "AND persona=? AND operation_id=?",
                        namespace.as_tuple + (operation_id,),
                    ).fetchone() != row:
                        raise UnavailableGuard("first ingress durable intent changed")
                    deadline_check(deadline)
                    for key in (source, access, job_key, outbox_key) + (
                            (media_key,) if media_key is not None else ()):
                        if db.execute("SELECT 1 FROM graph_atoms WHERE token=?",
                                      (key.token,)).fetchone():
                            raise StaleRead("first ingress revision-0 key changed")
                    if db.execute(
                        "SELECT 1 FROM graph_bundle_operations WHERE bot=? "
                        "AND persona=? AND operation_id=?",
                        namespace.as_tuple + (operation_id,),
                    ).fetchone():
                        raise EventConflict("first ingress operation already committed")
                    current_grant = self.__d11_issuer.current_budget_grant(
                        db, grant.lease_id)
                    if current_grant != grant:
                        raise AuthorityDenied("root grant changed before ingress")
                    self._first_ingress_boundary_locked(
                        namespace, owner_guard, scene_ref, host.visibility,
                        trusted_upper(reading))
                    budget = get_budget_lease(db, grant.lease_id)
                    if budget.state != "active" or any(
                            amount > budget.limits.get(name, 0)
                            - budget.used.get(name, 0)
                            - budget.reserved.get(name, 0)
                            - budget.unconfirmed.get(name, 0)
                            for name, amount in encoding_policy.quote_ceiling.items()):
                        raise UnavailableGuard("root budget has insufficient capacity")
                    epochs = db.execute(
                        "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                        "WHERE bot=? AND persona=?", namespace.as_tuple,
                    ).fetchone() or (0, 0)
                    guard_data = {
                        "access_epoch": epochs[0], "delete_epoch": epochs[1],
                        "scheme": self._version(db, namespace, "scheme", "current"),
                        "operator": self._version(db, namespace, "operator", "current"),
                        "policy": self._version(db, namespace, "policy", "current"),
                    }
                    admission = SourceAdmission(
                        host.lineage.source_ref, host.text, host.sender_ref,
                        host.lineage.source_kind, "reported",
                        host.lineage.evidence_eligibility,
                        host.lineage.internal_activity_actuality,
                        host.occurred_at, learned_at,
                        host.lineage.provenance_family,
                        (host.conversation_ref,),
                        (("context", "consolidation", "expression")
                         if (reply_source_policy is not None
                             and host.visibility == "private") else
                         ("context", "consolidation")))
                    media_admission = None
                    if source_admission_v2 is not None:
                        if replace(source_admission_v2.source,
                                   learned_at=admission.learned_at) != admission:
                            raise AuthorityDenied(
                                "verified media source differs from host admission")
                        media_admission = SourceAdmissionV2(
                            admission, source_admission_v2.attachments)
                    candidate = D06DomainAdapter(namespace).admit_source(admission)
                    command = CommandEnvelope(
                        RUNTIME_SCHEMA,
                        OperationIdentity(activity_id, None, "first", "ingress",
                            operation_id, canonical_digest({
                                "input_refs": list(candidate.qualification.source_refs)})),
                        authority,
                        VersionGuard(
                            tuple(GraphVersion(key, 0) for key in
                                  (source, access, job_key, outbox_key) + (
                                      (media_key,) if media_key is not None else ())),
                            (), epochs[0], epochs[1],
                            store._registry.catalogue_hash,
                            guard_data["scheme"], guard_data["operator"],
                            guard_data["policy"], (), (),
                            (VersionedRef(quote_id, 1),)),
                        candidate.qualification,
                        candidate.qualification.source_refs,
                        grant.lease_id, deadline,
                        ingress_policy.monotonic_deadline,
                        encoding_policy.character_interval_ref,
                        (host.message_id,))
                    install_issuer_schema(db)
                    db.execute("""CREATE TABLE IF NOT EXISTS ingress_first_observations(
                        bot TEXT NOT NULL, persona TEXT NOT NULL,
                        operation_id TEXT NOT NULL,
                        content_fingerprint TEXT NOT NULL,
                        learned_at REAL NOT NULL CHECK(learned_at > 0),
                        bundle_digest TEXT,
                        PRIMARY KEY(bot,persona,operation_id))""")
                    db.execute("""CREATE TABLE IF NOT EXISTS graph_first_ingress_identity_v1(
                        bot TEXT NOT NULL, persona TEXT NOT NULL,
                        operation_id TEXT NOT NULL,
                        source_ref TEXT NOT NULL,
                        platform_ref TEXT NOT NULL,
                        conversation_ref TEXT NOT NULL,
                        sender_ref TEXT NOT NULL,
                        message_id TEXT NOT NULL,
                        visibility TEXT NOT NULL,
                        identity_json TEXT NOT NULL,
                        content_fingerprint TEXT NOT NULL,
                        learned_at REAL NOT NULL,
                        bundle_digest TEXT NOT NULL,
                        PRIMARY KEY(bot,persona,operation_id))""")
                    db.execute("""CREATE TABLE IF NOT EXISTS runtime_ingress_issuance(
                        bot TEXT NOT NULL, persona TEXT NOT NULL,
                        operation_id TEXT NOT NULL,
                        activation_generation INTEGER NOT NULL,
                        request_digest TEXT NOT NULL, policy_json TEXT NOT NULL,
                        quote_id TEXT NOT NULL, grant_id TEXT NOT NULL,
                        guard_json TEXT NOT NULL,
                        source_qualification_json TEXT,
                        PRIMARY KEY(bot,persona,operation_id))""")
                    if "source_qualification_json" not in {
                            column[1] for column in db.execute(
                                "PRAGMA table_info(runtime_ingress_issuance)")}:
                        db.execute("ALTER TABLE runtime_ingress_issuance "
                                   "ADD COLUMN source_qualification_json TEXT")
                    db.execute("""CREATE TRIGGER IF NOT EXISTS
                        runtime_ingress_issuance_no_update_v2
                        BEFORE UPDATE ON runtime_ingress_issuance
                        BEGIN SELECT RAISE(ABORT, 'ingress issuance is immutable'); END
                    """)
                    db.execute(
                        "INSERT INTO ingress_first_observations"
                        "(bot,persona,operation_id,content_fingerprint,"
                        "learned_at,bundle_digest) VALUES(?,?,?,?,?,NULL)",
                        namespace.as_tuple + (operation_id, fingerprint,
                                              learned_at))
                    quote = ResourceQuote(
                        quote_id, 1, *namespace.as_tuple, activity_id,
                        operation_id, None, grant.lease_id,
                        "d06.encode_source", encoding_policy.snapshot_ref,
                        deadline, encoding_policy.resource_ref, job_key.token,
                        (outbox_key.token,), (), dict(encoding_policy.quote_ceiling),
                        None, deadline)
                    self.__d02_issuer.issue_quote(db, quote)
                    db.execute(
                        "INSERT INTO graph_guard_versions(bot,persona,kind,ref,version) "
                        "VALUES(?,?,?,?,?)",
                        namespace.as_tuple + ("resource_lease", quote_id, "1"))
                    db.execute(
                        "INSERT INTO runtime_ingress_issuance"
                        "(bot,persona,operation_id,activation_generation,"
                        "request_digest,policy_json,quote_id,grant_id,guard_json,"
                        "source_qualification_json) "
                        "VALUES(?,?,?,?,?,?,?,?,?,?)",
                        namespace.as_tuple + (
                            operation_id, target.activation_generation,
                            canonical_digest(identity_json),
                            canonical_json(asdict(ingress_policy)), quote_id,
                            grant.grant_id, canonical_json(guard_data),
                            canonical_serialize(asdict(candidate.qualification))))
                    now_utc = trusted_upper(reading)
                    job = self.__d11_issuer.job_for(
                        command, db, now_utc=now_utc)
                    bundle = build_first_ingress_bundle(
                        command, job, admission,
                        source_identity=source_identity,
                        payload_ref=host.lineage.source_ref,
                        idempotency_key=idem,
                        media_admission=media_admission)
                    if source_admission_v2 is not None:
                        insert_media_blobs(db, namespace, media_admission)
                    db.execute(
                        "INSERT INTO graph_first_ingress_identity_v1"
                        "(bot,persona,operation_id,source_ref,platform_ref,"
                        "conversation_ref,sender_ref,message_id,visibility,"
                        "identity_json,content_fingerprint,learned_at,"
                        "bundle_digest) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)",
                        namespace.as_tuple + (
                            operation_id, host.lineage.source_ref,
                            host.platform_ref, host.conversation_ref,
                            host.sender_ref, host.message_id, host.visibility,
                            ingress_host_identity_json(host, operation_id),
                            fingerprint, learned_at, bundle.digest),
                    )
                    db.execute(
                        "UPDATE ingress_first_observations SET bundle_digest=? "
                        "WHERE bot=? AND persona=? AND operation_id=?",
                        (bundle.digest,) + namespace.as_tuple + (operation_id,))
                    finish_id = "finish:" + attempt_id
                    finished_digest = finish_digest(
                        attempt_id, permit.token, operation_id, bundle.digest)
                    result = self._commit_domain_bundle_fenced(
                        bundle, lease, in_transaction=True, now_utc=now_utc,
                        ingress_deadline_check=deadline_check,
                        v2_write=(metadata, epoch, finish_id,
                                  finished_digest,
                                  canonical_json(to_wire(permit))))
                    db.execute("COMMIT")
                except BaseException:
                    if db.in_transaction:
                        db.execute("ROLLBACK")
                        transaction_rolled_back = True
                    raise
        except Exception as exc:
            if transaction_rolled_back:
                try:
                    self._reject_first_ingress_v2(
                        namespace, operation_id, row, permit, scope)
                except Exception as reconcile_exc:
                    raise FirstIngressOutcomeUnknown(
                        operation_id,
                        "first ingress rejection finish unconfirmed; HOLD original attempt"
                    ) from reconcile_exc
                raise
            raise FirstIngressOutcomeUnknown(
                operation_id,
                "first ingress commit outcome unknown; HOLD original attempt") from exc
        try:
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("first ingress permit changed after commit")
        except Exception as exc:
            raise FirstIngressOutcomeUnknown(
                operation_id, "first ingress committed permit unconfirmed; HOLD"
            ) from exc
        with store._lock:
            current, current_epoch = self._v2_graph_stamp(namespace)
            if (current.graph_revision != metadata.graph_revision + 1
                    or current_epoch.revision != result.invalidated_epochs[0].revision):
                raise FirstIngressOutcomeUnknown(
                    operation_id, "first ingress committed stamp unconfirmed; HOLD")
        try:
            port.finish_fence(scope, request_id=finish_id,
                              request_digest=finished_digest)
        except Exception as exc:
            raise FirstIngressOutcomeUnknown(
                operation_id,
                "first ingress finish outcome unknown; HOLD original attempt") from exc
        return result

    def _reject_first_ingress_v2(self, namespace, operation_id, row,
                                 permit, scope) -> None:
        """Only a proven rollback may become a durable abort identity."""
        from .authority_service.v2_contract import to_wire
        from .runtime.first_ingress_v2 import finish_digest

        store = self.__store
        attempt_id = row[3]
        abort_id = "abort:" + attempt_id
        digest = finish_digest(
            attempt_id, permit.token, operation_id, None, rejected=True)
        expected = ("rejected_no_commit", canonical_json(to_wire(permit)),
                    row[6], row[7], abort_id, digest)
        with store._lock:
            db = store._db
            db.execute("BEGIN IMMEDIATE")
            try:
                current, current_epoch = self._v2_graph_stamp(namespace)
                if (current_epoch != scope.graph_epoch
                        or current.graph_revision != scope.graph_revision
                        or db.execute(
                            "SELECT 1 FROM graph_bundle_operations WHERE bot=? "
                            "AND persona=? AND operation_id=?",
                            namespace.as_tuple + (operation_id,),
                        ).fetchone()):
                    raise UnavailableGuard("first ingress rollback cannot be proven")
                if current.graph_revision != row[6]:
                    raise UnavailableGuard("first ingress rollback stamp changed")
                db.execute(
                    "INSERT OR IGNORE INTO graph_first_ingress_rejections_v2"
                    "(bot,persona,operation_id,status,permit_json,graph_revision,"
                    "graph_epoch,finish_request_id,finish_request_digest) "
                    "VALUES(?,?,?,?,?,?,?,?,?)",
                    namespace.as_tuple + (operation_id,) + expected)
                if db.execute(
                    "SELECT status,permit_json,graph_revision,graph_epoch,"
                    "finish_request_id,finish_request_digest "
                    "FROM graph_first_ingress_rejections_v2 "
                    "WHERE bot=? AND persona=? AND operation_id=?",
                    namespace.as_tuple + (operation_id,),
                ).fetchone() != expected:
                    raise UnavailableGuard("first ingress rejection identity differs")
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise
        port = self.__content_fence_v2
        try:
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("first ingress rejected permit changed")
        except Exception as exc:
            raise FirstIngressOutcomeUnknown(
                operation_id, "first ingress rejected permit unconfirmed; HOLD"
            ) from exc
        try:
            port.finish_fence(scope, request_id=abort_id,
                              request_digest=digest)
        except Exception as exc:
            raise FirstIngressOutcomeUnknown(
                operation_id, "first ingress rejected finish outcome unknown; HOLD"
            ) from exc

    def issue_ingress_authorization(self, bootstrap: object, request, session):
        """Issue first D06+D11 ingress from installation policy and signed facts.

        The policy callback is installed with the coordinator and receives only
        namespace and policy identity. It cannot inspect chat content or the DB.
        A missing callback, observation, or real issuer fails closed.
        """
        from .domains.d06 import D06DomainAdapter, SourceAdmission
        from .runtime.d11_types import runtime_job_key, runtime_outbox_key
        from .runtime.issuers import (
            BudgetLeaseGrant, D02ResourceIssuer, D11BudgetJobIssuer,
            ResourceQuote, install_schema as install_issuer_schema,
        )
        from .runtime_contracts import (
            RUNTIME_SCHEMA, CommandEnvelope, OperationIdentity,
            VersionGuard, VersionedRef,
        )

        self._admin(bootstrap)
        if not isinstance(request, IngressIssuanceRequest):
            raise TypeError("typed ingress issuance request required")
        if not isinstance(getattr(session, "authority", None), AuthorityContext) or \
                getattr(session, "lease", None) is None:
            raise TypeError("ingress authority session required")
        authority = session.authority
        self._authorize(session.lease, authority, frozenset({"d06", "d11"}))
        if authority.capability_ref != _operation_capability_ref(
                authority.namespace, authority.actor, authority.issuer_domain,
                frozenset({"d06", "d11"}), authority.activation_generation,
                request.operation_id):
            raise AuthorityDenied("ingress lease is not scoped to this operation")
        if (authority.issuer_domain != "d06" or authority.purpose != "context"
                or authority.namespace != request.host.namespace
                or authority.audience != (request.host.conversation_ref,)
                or not {"event", "activity"}.issubset(authority.owner_scope)):
            raise AuthorityDenied("ingress session differs from trusted host scope")
        if (type(self.__d02_issuer) is not D02ResourceIssuer
                or type(self.__d11_issuer) is not D11BudgetJobIssuer
                or self.__d11_issuer.resource_issuer is not self.__d02_issuer
                or self.__ingress_policy is None):
            raise UnavailableGuard("real D02/D11 issuers and ingress policy are required")
        host = request.host
        namespace = host.namespace
        admission = request.admission
        expected_admission = SourceAdmission(
            host.lineage.source_ref, host.text, host.sender_ref,
            host.lineage.source_kind, "reported",
            host.lineage.evidence_eligibility,
            host.lineage.internal_activity_actuality,
            host.occurred_at, host.learned_at,
            host.lineage.provenance_family,
            (host.conversation_ref,), ("context", "consolidation"),
        )
        if (host.lineage.content_reality != "external_report"
                or admission != expected_admission
                or admission.parent_source_ids
                or request.candidate != D06DomainAdapter(namespace).admit_source(admission)):
            raise AuthorityDenied("ingress source differs from canonical host report")
        digest = hashlib.sha256(
            ("sylanne3.host-ingress.v1:" + host.lineage.source_ref).encode("ascii")
        ).hexdigest()
        if (request.activity_id != "ingress-" + digest[:24]
                or request.operation_id != "host-ingress-" + digest[:32]
                or request.job_id != "encode-" + digest[:24]
                or request.outbox_id != "encode-outbox-" + digest[:24]
                or request.payload_ref != host.lineage.source_ref
                or request.idempotency_key != "host-ingress:" + digest
                or request.job_ref != runtime_job_key(
                    *namespace.as_tuple, request.activity_id, request.job_id).token
                or request.outbox_ref != runtime_outbox_key(
                    *namespace.as_tuple, request.activity_id, request.outbox_id).token):
            raise AuthorityDenied("ingress runtime refs differ from canonical identity")
        request_digest = canonical_digest(request)
        source = source_key(*namespace.as_tuple, admission.source_id)
        access = access_key(*namespace.as_tuple, admission.source_id)
        keys = (source, access, self._parse_ref(request.job_ref, namespace),
                self._parse_ref(request.outbox_ref, namespace))
        store = self.__store
        with self._content_fence(namespace, authority.activation_generation, "write"):
            with store._lock:
                store._ensure_open()
                store._db.execute("BEGIN IMMEDIATE")
                try:
                    db = store._db
                    self._admit_content(namespace, authority.activation_generation,
                                        "write", tuple(key.token for key in keys))
                    if self._version(db, namespace, "activation", "current") != str(
                            authority.activation_generation):
                        raise StaleRead("activation generation changed")
                    observation = db.execute(
                        "SELECT content_fingerprint,learned_at FROM ingress_first_observations "
                        "WHERE bot=? AND persona=? AND operation_id=?",
                        namespace.as_tuple + (request.operation_id,),
                    ).fetchone()
                    if observation is None:
                        raise UnavailableGuard("canonical first observation is absent")
                    if (observation[0] != ingress_host_fingerprint(host)
                            or observation[1] != host.learned_at):
                        raise EventConflict("ingress content or canonical learned time changed")
                    install_issuer_schema(db)
                    db.execute("""CREATE TABLE IF NOT EXISTS runtime_ingress_issuance(
                        bot TEXT NOT NULL, persona TEXT NOT NULL, operation_id TEXT NOT NULL,
                        activation_generation INTEGER NOT NULL,
                        request_digest TEXT NOT NULL, policy_json TEXT NOT NULL,
                        quote_id TEXT NOT NULL, grant_id TEXT NOT NULL,
                        guard_json TEXT NOT NULL,
                        PRIMARY KEY(bot,persona,operation_id))""")
                    prior = db.execute(
                        "SELECT activation_generation,request_digest,policy_json,"
                        "quote_id,grant_id,guard_json "
                        "FROM runtime_ingress_issuance WHERE bot=? AND persona=? "
                        "AND operation_id=?",
                        namespace.as_tuple + (request.operation_id,),
                    ).fetchone()
                    if prior is not None and prior[0] != authority.activation_generation:
                        raise StaleRead("ingress issuance activation generation changed")
                    if prior is not None and prior[1] != request_digest:
                        raise EventConflict("ingress operation request changed")
                    if prior is None:
                        policy = self.__ingress_policy(namespace, authority.provider_policy_ref)
                        if not isinstance(policy, IngressIssuancePolicy):
                            raise UnavailableGuard("typed installed ingress policy unavailable")
                        quote_id = "ingress-q-" + hashlib.sha256(
                            canonical_json([*namespace.as_tuple, request.operation_id]).encode()
                        ).hexdigest()[:40]
                        grant_id = "ingress-g-" + hashlib.sha256(
                            canonical_json([*namespace.as_tuple,
                                            policy.parent_budget_lease_ref,
                                            authority.provider_policy_ref]).encode()
                        ).hexdigest()[:40]
                        epochs = db.execute(
                            "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                            "WHERE bot=? AND persona=?", namespace.as_tuple,
                        ).fetchone() or (0, 0)
                        guard_data = {
                            "access_epoch": epochs[0], "delete_epoch": epochs[1],
                            "scheme": self._version(db, namespace, "scheme", "current"),
                            "operator": self._version(db, namespace, "operator", "current"),
                            "policy": self._version(db, namespace, "policy", "current"),
                        }
                        for key in keys:
                            if db.execute("SELECT 1 FROM graph_atoms WHERE token=?",
                                          (key.token,)).fetchone() is not None:
                                raise StaleRead("first ingress atom already exists")
                        lease = get_budget_lease(db, policy.parent_budget_lease_ref)
                        if (lease.state != "active" or
                                (lease.bot_id, lease.persona_id) != namespace.as_tuple):
                            raise UnavailableGuard("existing active parent budget required")
                        if any(amount > lease.limits.get(name, 0)
                               for name, amount in policy.grant_ceiling.items()):
                            raise UnavailableGuard("installation grant exceeds parent budget limit")
                        if any(amount > lease.limits.get(name, 0)
                               - lease.used.get(name, 0)
                               - lease.reserved.get(name, 0)
                               - lease.unconfirmed.get(name, 0)
                               for name, amount in policy.ceiling.items()):
                            raise UnavailableGuard("parent budget has insufficient available capacity")
                        grant = BudgetLeaseGrant(
                            grant_id, 1, *namespace.as_tuple, lease.lease_id,
                            lease.currency, policy.grant_ceiling, ("d06.encode_source",),
                            policy.grant_valid_until_utc, authority.provider_policy_ref,
                        )
                        if db.execute("SELECT 1 FROM runtime_budget_grants WHERE lease_id=?",
                                      (lease.lease_id,)).fetchone() is None:
                            self.__d11_issuer.issue_budget_grant(db, grant)
                        elif self.__d11_issuer.current_budget_grant(db, lease.lease_id) != grant:
                            raise AuthorityDenied("existing signed D11 grant differs from ingress policy")
                        quote = ResourceQuote(
                            quote_id, 1, *namespace.as_tuple, request.activity_id,
                            request.operation_id, None, lease.lease_id,
                            "d06.encode_source", policy.snapshot_ref,
                            policy.deadline_utc, policy.resource_ref, request.job_ref,
                            (request.outbox_ref,), (), policy.ceiling, None,
                            policy.deadline_utc,
                        )
                        self.__d02_issuer.issue_quote(db, quote)
                        db.execute(
                            "INSERT INTO graph_guard_versions(bot,persona,kind,ref,version) "
                            "VALUES(?,?,?,?,?)",
                            namespace.as_tuple + ("resource_lease", quote_id, "1"),
                        )
                        db.execute(
                            "INSERT INTO runtime_ingress_issuance"
                            "(bot,persona,operation_id,activation_generation,"
                            "request_digest,policy_json,quote_id,grant_id,guard_json) "
                            "VALUES(?,?,?,?,?,?,?,?,?)",
                            namespace.as_tuple + (
                                request.operation_id, authority.activation_generation,
                                request_digest,
                                json.dumps(asdict(policy), sort_keys=True),
                                quote_id, grant_id,
                                json.dumps(guard_data, sort_keys=True)),
                        )
                    else:
                        policy = IngressIssuancePolicy(**json.loads(prior[2]))
                        quote_id, grant_id = prior[3], prior[4]
                        guard_data = json.loads(prior[5])
                    self._admit_ingress_deadline(
                        namespace, request.operation_id,
                        authority.activation_generation, policy.deadline_utc)
                    if (self._version(db, namespace, "scheme", "current") != guard_data["scheme"]
                            or self._version(db, namespace, "operator", "current") != guard_data["operator"]
                            or self._version(db, namespace, "policy", "current") != guard_data["policy"]
                            or self._version(db, namespace, "resource_lease", quote_id) != "1"):
                        raise StaleRead("ingress guard version changed")
                    current_epochs = db.execute(
                        "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                        "WHERE bot=? AND persona=?", namespace.as_tuple,
                    ).fetchone() or (0, 0)
                    if tuple(current_epochs) != (
                            guard_data["access_epoch"], guard_data["delete_epoch"]):
                        raise StaleRead("ingress access or deletion epoch changed")
                    committed = db.execute(
                        "SELECT 1 FROM graph_bundle_operations WHERE bot=? AND persona=? "
                        "AND operation_id=?", namespace.as_tuple + (request.operation_id,),
                    ).fetchone() is not None
                    if not committed:
                        for key in keys:
                            if db.execute("SELECT 1 FROM graph_atoms WHERE token=?",
                                          (key.token,)).fetchone() is not None:
                                raise StaleRead("first ingress atom changed")
                    identity = OperationIdentity(
                        request.activity_id, None, "first", "ingress",
                        request.operation_id, canonical_digest({
                            "input_refs": list(request.candidate.qualification.source_refs),
                        }),
                    )
                    envelope = CommandEnvelope(
                        RUNTIME_SCHEMA, identity, authority,
                        VersionGuard(
                            tuple(GraphVersion(key, 0) for key in keys),
                            (),
                            guard_data["access_epoch"], guard_data["delete_epoch"],
                            store._registry.catalogue_hash,
                            guard_data["scheme"], guard_data["operator"],
                            guard_data["policy"], (), (),
                            (VersionedRef(quote_id, 1),),
                        ),
                        request.candidate.qualification,
                        request.candidate.qualification.source_refs,
                        policy.parent_budget_lease_ref, policy.deadline_utc,
                        policy.monotonic_deadline, policy.character_interval_ref,
                        (host.message_id,),
                    )
                    quote = self.__d02_issuer.qualified_quote(envelope, db)
                    if (quote.quote_id != quote_id or quote.graph_job_ref != request.job_ref
                            or quote.outbox_refs != (request.outbox_ref,)
                            or dict(quote.ceiling) != dict(policy.ceiling)
                            or quote.snapshot_ref != policy.snapshot_ref
                            or quote.resource_ref != policy.resource_ref):
                        raise AuthorityDenied("signed D02 quote differs from durable ingress policy")
                    grant = self.__d11_issuer.current_budget_grant(
                        db, policy.parent_budget_lease_ref)
                    if (grant.grant_id != grant_id
                            or dict(grant.max_ceiling) != dict(policy.grant_ceiling)
                            or grant.valid_until_utc != policy.grant_valid_until_utc
                            or grant.policy_ref != authority.provider_policy_ref):
                        raise AuthorityDenied("signed D11 grant differs from durable ingress policy")
                    current_lease = get_budget_lease(db, policy.parent_budget_lease_ref)
                    if not committed and any(
                            amount > current_lease.limits.get(name, 0)
                            - current_lease.used.get(name, 0)
                            - current_lease.reserved.get(name, 0)
                            - current_lease.unconfirmed.get(name, 0)
                            for name, amount in policy.ceiling.items()):
                        raise UnavailableGuard("parent budget has insufficient available capacity")
                    job = self.__d11_issuer.job_for(envelope, db)
                    if (job.job_id != request.job_id or
                            job.work_kind != "d06.encode_source"):
                        raise AuthorityDenied("D11 job differs from ingress encoding work")
                    db.execute("COMMIT")
                    return IngressAuthorizationResult(envelope, session.lease, job)
                except BaseException:
                    if store._db.in_transaction:
                        store._db.execute("ROLLBACK")
                    raise

    def reserve_and_schedule(self, envelope, lease: object) -> tuple[BudgetReceipt, PersistentJob]:
        """Reserve before an external effect and persist its runnable job atomically.

        The D02/D11 issuers are trusted host dependencies. A command envelope
        alone is never permission to spend or schedule work.
        """
        authority = envelope.authority
        self._authorize(lease, authority, frozenset())
        if (not callable(getattr(self.__d02_issuer, "authorize_schedule", None))
                or not callable(getattr(self.__d11_issuer, "admit_schedule", None))):
            raise UnavailableGuard("D02 and D11 schedule issuers are required")
        namespace = authority.namespace
        store = self.__store
        with self._content_fence(namespace, authority.activation_generation, "write"):
            with store._lock:
                store._ensure_open()
                self._admit_content(namespace, authority.activation_generation, "write",
                                    tuple(item.key.token for item in
                                          envelope.version_guard.read_versions))
                store._db.execute("BEGIN IMMEDIATE")
                try:
                    self._check_guard(store._db, SimpleNamespace(
                        envelope=envelope, proposals=()))
                    if self.__d02_issuer.authorize_schedule(envelope, store._db) is not True:
                        raise AuthorityDenied("D02 did not authorize scheduling resources")
                    admission = self.__d11_issuer.admit_schedule(envelope, store._db)
                    if not isinstance(admission, ScheduleAdmission):
                        raise AuthorityDenied("D11 did not issue a typed schedule admission")
                    budget, job = admission.budget, admission.job
                    if not isinstance(budget, BudgetAdmission) or not isinstance(job, PersistentJob):
                        raise AuthorityDenied("D11 schedule admission is incomplete")
                    if (budget.lease_id != envelope.parent_budget_lease_ref
                            or budget.pre_reserved or budget.settle_now
                            or budget.reservation_operation_id is not None):
                        raise AuthorityDenied("schedule must reserve the command budget once")
                    current = get_budget_lease(store._db, budget.lease_id)
                    if (current.state != "active" or current.version != budget.expected_version
                            or (current.bot_id, current.persona_id) != namespace.as_tuple):
                        raise StaleRead("D11 schedule budget lease is stale")
                    identity = envelope.identity
                    if ((job.bot_id, job.persona_id) != namespace.as_tuple
                            or job.operation_id != identity.operation_id
                            or job.activity_id != identity.activity_id
                            or job.effect_id != identity.effect_id
                            or job.budget_ref != budget.lease_id
                            or job.phase not in {"queued", "waiting"}):
                        raise AuthorityDenied("D11 schedule job identity differs from command")
                    digest = budget_operation_digest(envelope, budget.lease_id,
                                                     budget.ceiling)
                    receipt = reserve_budget(store._db, budget.lease_id,
                                             identity.operation_id, digest, budget.ceiling)
                    job_operation = "job:" + hashlib.sha256(
                        (identity.operation_id + job.job_id).encode("utf-8")
                    ).hexdigest()[:32]
                    persisted = create_job(store._db, job, job_operation, digest)
                    store._db.execute("COMMIT")
                    return receipt, persisted
                except BaseException:
                    store._db.execute("ROLLBACK")
                    raise

    def acquire_persistent_job(self, authority: AuthorityContext, lease: object,
                               job_id: str, *, now_utc: str,
                               lease_seconds: int) -> PersistentJob:
        if isinstance(self.__store, ProductionGraphStore):
            raise UnavailableGuard("production job acquire requires the v2 fenced command")
        self._authorize(lease, authority, frozenset())
        return self._mutate_job(authority, job_id, lambda db: acquire_job(
            db, job_id, authority.actor, now_utc=now_utc,
            lease_seconds=lease_seconds))

    def _first_ingress_encoding_job_locked(self, namespace: NamespaceId,
                                           job_id: str):
        """Join the original business receipt, job table, and graph projections."""
        from .runtime.d11_types import (
            RuntimeOutboxValue, job_graph_write, runtime_job_key,
            runtime_outbox_key,
        )
        from .runtime.first_ingress_v2 import ingress_ids
        from .memory_types import SourceRecord, access_key, source_key, validate_access

        db = self.__store._db
        job = get_job(db, job_id)
        if ((job.bot_id, job.persona_id) != namespace.as_tuple
                or job.work_kind != "d06.encode_source" or job.effect_id is not None):
            raise AuthorityDenied("job is not an installed first-ingress encoding job")
        job_key = runtime_job_key(*namespace.as_tuple, job.activity_id, job_id)
        job_row = db.execute(
            "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
            (job_key.token,),
        ).fetchone()
        if (job_row is None or job_row[2] != 1
                or json.loads(job_row[1]) != job_graph_write(job).value):
            raise UnavailableGuard("encoding job graph projection differs from durable job")
        rows = db.execute(
            "SELECT token,revision,value,valid FROM graph_atoms WHERE bot=? "
            "AND persona=? AND owner_kind='activity' AND subject=? "
            "AND type_name='runtime.outbox'",
            namespace.as_tuple + (job.activity_id,),
        ).fetchall()
        matches = []
        for token, revision, value_json, valid in rows:
            value = json.loads(value_json)
            if value.get("job_id") == job_id:
                matches.append((token, revision, value, valid))
        if len(matches) != 1:
            raise UnavailableGuard("encoding job needs exactly one original outbox")
        token, outbox_revision, value, valid = matches[0]
        outbox = RuntimeOutboxValue(**value)
        expected = ingress_ids(outbox.payload_ref)
        source_key_value = source_key(*namespace.as_tuple, outbox.payload_ref)
        access_key_value = access_key(*namespace.as_tuple, outbox.payload_ref)
        source_row = db.execute(
            "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
            (source_key_value.token,),
        ).fetchone()
        access_row = db.execute(
            "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
            (access_key_value.token,),
        ).fetchone()
        if (source_row is None or access_row is None
                or source_row[2] != 1 or access_row[2] != 1):
            raise UnavailableGuard("encoding source or access is unavailable")
        try:
            source = SourceRecord.from_dict(json.loads(source_row[1]))
            access_value = json.loads(access_row[1])
            validate_access(access_value)
        except (TypeError, ValueError, KeyError) as exc:
            raise UnavailableGuard("encoding source or access is invalid") from exc
        source_dependency = db.execute(
            "SELECT dependency_revision FROM graph_dependencies WHERE dependent_token=? "
            "AND dependency_token=?",
            (access_key_value.token, source_key_value.token),
        ).fetchone()
        if (source.source_id != outbox.payload_ref
                or access_value["source_id"] != source.source_id
                or access_value["status"] != "active"
                or "consolidation" not in access_value["purposes"]
                or "consolidation" not in source.purposes
                or not set(access_value["audiences"]).issubset(source.audiences)
                or source_dependency != (source_row[0],)):
            raise UnavailableGuard("encoding source access lost current eligibility")
        outbox_key = runtime_outbox_key(
            *namespace.as_tuple, job.activity_id, outbox.outbox_id)
        receipt_row = db.execute(
            "SELECT receipt_json FROM graph_bundle_operations WHERE bot=? "
            "AND persona=? AND operation_id=?",
            namespace.as_tuple + (job.operation_id,),
        ).fetchone()
        dependencies = db.execute(
            "SELECT dependency_revision FROM graph_dependencies WHERE dependent_token=? "
            "AND dependency_token=?",
            (outbox_key.token, job_key.token),
        ).fetchone()
        if (valid != 1 or token != outbox_key.token
                or (expected[1], expected[2], expected[3], expected[4]) != (
                    job.activity_id, job.operation_id, job.job_id, outbox.outbox_id)
                or (outbox.bot_id, outbox.persona_id, outbox.activity_id,
                    outbox.operation_id, outbox.effect_id, outbox.job_ref,
                    outbox.phase) != (
                    namespace.bot_id, namespace.persona_id, job.activity_id,
                    job.operation_id, None, job_key.token, "pending")
                or dependencies != (job_row[0],)
                or receipt_row is None
                or outbox_key.token not in json.loads(receipt_row[0]).get("outbox_refs", ())):
            raise UnavailableGuard("encoding outbox lost its original business linkage")
        self._original_first_ingress_qualification_locked(
            namespace, job.operation_id, source_key_value.token)
        return (job, job_key, job_row[0], outbox, outbox_key,
                outbox_revision, GraphVersion(source_key_value, source_row[0]),
                GraphVersion(access_key_value, access_row[0]))

    def _original_first_ingress_qualification_locked(
        self, namespace: NamespaceId, operation_id: str, source_ref: str,
    ):
        """Read only the D06 qualification committed with the first bundle."""
        db = self.__store._db
        columns = {column[1] for column in db.execute(
            "PRAGMA table_info(runtime_ingress_issuance)")}
        if "source_qualification_json" not in columns:
            raise UnavailableGuard("original D06 source qualification absent; HOLD")
        row = db.execute(
            "SELECT source_qualification_json FROM runtime_ingress_issuance "
            "WHERE bot=? AND persona=? AND operation_id=?",
            namespace.as_tuple + (operation_id,),
        ).fetchone()
        if row is None or row[0] is None:
            raise UnavailableGuard("original D06 source qualification absent; HOLD")
        try:
            data = json.loads(row[0])
            data["source_refs"] = tuple(data["source_refs"])
            qualification = SourceQualification(**data)
            if (canonical_serialize(asdict(qualification)) != row[0]
                    or qualification.source_refs != (source_ref,)):
                raise ValueError("qualification identity differs")
        except (TypeError, ValueError, KeyError) as exc:
            raise UnavailableGuard(
                "original D06 source qualification invalid; HOLD") from exc
        return qualification

    def read_first_ingress_baseline_inputs_v1(
        self, authority: AuthorityContext, lease: object, job_id: str,
        original_operation_id: str,
    ):
        """Read queued C01 evidence for D04 without acquiring an encoding worker.

        This returns no D03 self perspective and grants no D04 write authority.
        """
        from datetime import datetime

        from .host.authority_profile import AdminIngressClockPolicy
        from .memory_types import SourceRecord
        from .runtime.first_ingress_baseline_inputs import FirstIngressBaselineInputsV1
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.issuers import D11BudgetJobIssuer

        if (not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or type(self.__d11_issuer) is not D11BudgetJobIssuer
                or type(self.__scene_clock_policy) is not AdminIngressClockPolicy):
            raise UnavailableGuard("installed first-ingress baseline read authorities required")
        self._authorize(lease, authority, frozenset({"d11"}), owner_read=True)
        namespace = authority.namespace
        if (authority.issuer_domain != "d11" or authority.actor != self.__holder
                or "activity" not in authority.owner_scope
                or authority.purpose != "context"
                or authority.worker_fence is not None
                or type(original_operation_id) is not str
                or authority.capability_ref != _operation_capability_ref(
                    namespace, authority.actor, "d11", frozenset({"d11"}),
                    authority.activation_generation, original_operation_id)):
            raise AuthorityDenied("baseline read requires the original job-bound D11 lease")
        try:
            now = trusted_upper(self.__content_fence_v2.read_ingress_clock(
                self.__scene_clock_policy))
        except Exception as exc:
            raise UnavailableGuard("baseline trusted clock unavailable; HOLD") from exc

        def reader():
            db = self.__store._db
            job, job_key, _, outbox, _, _, source_version, access_version = (
                self._first_ingress_encoding_job_locked(namespace, job_id))
            if (job.operation_id != original_operation_id
                    or job.phase != "queued" or job.fence != 0
                    or job.lease_holder is not None
                    or job.lease_expires_utc is not None
                    or job.cancel_epoch != 0 or job.result_ref is not None):
                raise UnavailableGuard("baseline job is no longer queued; HOLD")
            deadline = datetime.fromisoformat(
                job.deadline_utc.replace("Z", "+00:00")).timestamp()
            if now >= deadline:
                raise UnavailableGuard("baseline job deadline expired; HOLD")
            self.__d11_issuer.authorize_existing_encoding_job(db, job, now_utc=now)
            if (self.__d11_issuer.current_budget_grant(db, job.budget_ref).policy_ref
                    != authority.provider_policy_ref):
                raise UnavailableGuard("baseline D11 policy identity differs; HOLD")
            identity = db.execute(
                "SELECT source_ref,platform_ref,conversation_ref,sender_ref,"
                "message_id,visibility,identity_json,bundle_digest FROM "
                "graph_first_ingress_identity_v1 WHERE bot=? "
                "AND persona=? AND operation_id=?",
                namespace.as_tuple + (original_operation_id,),
            ).fetchone()
            intent = db.execute(
                "SELECT identity_json,requirements_json FROM "
                "graph_first_ingress_intents_v2 WHERE bot=? AND persona=? "
                "AND operation_id=?",
                namespace.as_tuple + (original_operation_id,),
            ).fetchone()
            bundle = db.execute(
                "SELECT digest,receipt_json FROM graph_bundle_operations WHERE bot=? "
                "AND persona=? AND operation_id=?",
                namespace.as_tuple + (original_operation_id,),
            ).fetchone()
            if identity is None or intent is None or bundle is None:
                raise UnavailableGuard("baseline original ingress identity absent; HOLD")
            original = json.loads(identity[6])
            original_intent = json.loads(intent[0])
            receipt = json.loads(bundle[1])
            if (identity[0] != outbox.payload_ref
                    or (original_intent["source_ref"],
                        original_intent["conversation_ref"]) != (identity[0], identity[2])
                    or (original["source_ref"], original["platform_ref"],
                        original["conversation_ref"], original["sender_ref"],
                        original["message_id"], original["visibility"],
                        original["operation_id"]) != (*identity[:6], original_operation_id)
                    or identity[7] != bundle[0]
                    or job_key.token not in receipt.get("ledger_refs", ())
                    or authority.audience != (identity[2],)):
                raise UnavailableGuard("baseline original ingress identity differs; HOLD")
            source_row = db.execute(
                "SELECT value FROM graph_atoms WHERE token=? AND revision=? AND valid=1",
                (source_version.key.token, source_version.revision),
            ).fetchone()
            access_row = db.execute(
                "SELECT value FROM graph_atoms WHERE token=? AND revision=? AND valid=1",
                (access_version.key.token, access_version.revision),
            ).fetchone()
            if source_row is None or access_row is None:
                raise UnavailableGuard("baseline current source/access disappeared; HOLD")
            source = SourceRecord.from_dict(json.loads(source_row[0]))
            access = json.loads(access_row[0])
            if (source.speaker_id != identity[3]
                    or "context" not in source.purposes
                    or "context" not in access["purposes"]
                    or identity[2] not in source.audiences
                    or identity[2] not in access["audiences"]):
                raise UnavailableGuard("baseline current source/access differs; HOLD")
            qualification = self._original_first_ingress_qualification_locked(
                namespace, original_operation_id, source_version.key.token)
            epochs = db.execute(
                "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                "WHERE bot=? AND persona=?", namespace.as_tuple,
            ).fetchone()
            if epochs is None:
                raise UnavailableGuard("baseline current authority epochs absent; HOLD")
            return (job, source_version, access_version, qualification, epochs,
                    json.loads(intent[1])["graph_incarnation"])

        prepared, anchor, metadata, graph_epoch = self._read_v2(
            authority, reader, return_recovery_context=True,
            durable_read_key="d04-baseline:" + original_operation_id)
        job, source_version, access_version, qualification, epochs, original_incarnation = prepared
        if metadata.requirements.graph_incarnation != original_incarnation:
            raise UnavailableGuard("baseline graph incarnation differs from original ingress; HOLD")
        return FirstIngressBaselineInputsV1(
            namespace, original_incarnation, metadata.graph_revision,
            graph_epoch.revision, *epochs, job_id, job.activity_id,
            original_operation_id, source_version.key.token,
            source_version.revision, access_version.revision, qualification,
            anchor)

    def read_first_ingress_encoding_job_v2(
        self, authority: AuthorityContext, lease: object, job_id: str,
        acquire_operation_id: str,
    ) -> PersistentJob:
        """Read one D11 job only through the current v2 Authority fence."""
        if not isinstance(self.__store, ProductionGraphStore) or self.__content_fence_v2 is None:
            raise UnavailableGuard("v2 job read requires the installed graph")
        self._authorize(lease, authority, frozenset({"d11"}), owner_read=True)
        if "activity" not in authority.owner_scope:
            raise AuthorityDenied("D11 job read requires activity owner scope")
        if (type(acquire_operation_id) is not str or not acquire_operation_id
                or authority.capability_ref != _operation_capability_ref(
                    authority.namespace, authority.actor, "d11", frozenset({"d11"}),
                    authority.activation_generation, acquire_operation_id)):
            raise AuthorityDenied("D11 job read lease is not scoped to this operation")
        def reader():
            job = self._first_ingress_encoding_job_locked(
                authority.namespace, job_id)[0]
            if not _job_acquire_id_matches(
                    acquire_operation_id, authority.namespace, job_id,
                    job.operation_id, authority.actor,
                    authority.activation_generation):
                raise AuthorityDenied("D11 job read lease names another job")
            return job

        return self._read_v2(authority, reader)

    def read_first_ingress_encoding_inputs_v2(
        self, authority: AuthorityContext, lease: object, job_id: str,
        acquire_operation_id: str,
    ) -> FirstIngressEncodingInputsV1:
        """Read the acquired job and its original source under one v2 fence.

        This is preparation only. A caller cannot turn this read into a model
        handoff or durable binding without the separate write admission.
        """
        from .memory_types import SourceRecord
        from .host.authority_profile import AdminIngressClockPolicy
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.issuers import D11BudgetJobIssuer

        if (not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or type(self.__d11_issuer) is not D11BudgetJobIssuer
                or type(self.__scene_clock_policy) is not AdminIngressClockPolicy):
            raise UnavailableGuard("v2 encoding input read requires the installed graph")
        self._authorize(lease, authority, frozenset({"d11"}), owner_read=True)
        if (authority.issuer_domain != "d11" or "activity" not in authority.owner_scope
                or type(acquire_operation_id) is not str
                or authority.capability_ref != _operation_capability_ref(
                    authority.namespace, authority.actor, "d11", frozenset({"d11"}),
                    authority.activation_generation, acquire_operation_id)):
            raise AuthorityDenied("encoding input read requires the job-bound D11 lease")
        try:
            now = trusted_upper(self.__content_fence_v2.read_ingress_clock(
                self.__scene_clock_policy))
        except Exception as exc:
            raise UnavailableGuard("encoding input trusted clock unavailable; HOLD") from exc

        def reader():
            (job, _, _, outbox, _, _, source_version, access_version) = (
                self._first_ingress_encoding_job_locked(authority.namespace, job_id))
            if not _job_acquire_id_matches(
                    acquire_operation_id, authority.namespace, job_id,
                    job.operation_id, authority.actor,
                    authority.activation_generation):
                raise AuthorityDenied("encoding input read lease names another job")
            if (job.phase != "running" or job.lease_holder != authority.actor
                    or job.cancel_epoch or job.fence < 1
                    or authority.worker_fence != job.fence):
                raise UnavailableGuard("encoding input job lease is not current; HOLD")
            from datetime import datetime
            expiry = datetime.fromisoformat(
                job.lease_expires_utc.replace("Z", "+00:00")).timestamp()
            if now >= expiry:
                raise UnavailableGuard("encoding input job lease expired; HOLD")
            self.__d11_issuer.authorize_existing_encoding_job(
                self.__store._db, job, now_utc=now)
            row = self.__store._db.execute(
                "SELECT value FROM graph_atoms WHERE token=? AND valid=1",
                (source_version.key.token,),
            ).fetchone()
            if row is None:
                raise UnavailableGuard("encoding source disappeared; HOLD")
            source = SourceRecord.from_dict(json.loads(row[0]))
            if source.source_id != outbox.payload_ref:
                raise UnavailableGuard("encoding source differs from original outbox")
            if self.__store._db.execute(
                    "SELECT 1 FROM runtime_encoding_call_redactions_v1 "
                    "WHERE bot=? AND persona=? AND source_id=? LIMIT 1",
                    authority.namespace.as_tuple + (source.source_id,),
            ).fetchone():
                raise UnavailableGuard("encoding source request was erased; HOLD")
            return FirstIngressEncodingInputsV1(
                job, source, source_version.revision, access_version.revision,
                job.budget_ref, job.operation_id)

        return self._read_v2(authority, reader)

    def read_first_ingress_encoding_binding_v2(
        self, authority: AuthorityContext, lease: object, job_id: str,
        acquire_operation_id: str,
    ):
        """Return the original frozen request to its current acquired D11 worker.

        This content read is fenced and requires current source access. Cost
        reconciliation must use an independent content-free terminal query.
        """
        from .host.authority_profile import AdminIngressClockPolicy
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.issuers import D11BudgetJobIssuer

        if (not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or type(self.__d11_issuer) is not D11BudgetJobIssuer
                or type(self.__scene_clock_policy) is not AdminIngressClockPolicy):
            raise UnavailableGuard("v2 encoding binding read requires the installed graph")
        self._authorize(lease, authority, frozenset({"d11"}), owner_read=True)
        if (authority.issuer_domain != "d11" or "activity" not in authority.owner_scope
                or type(acquire_operation_id) is not str
                or authority.capability_ref != _operation_capability_ref(
                    authority.namespace, authority.actor, "d11", frozenset({"d11"}),
                    authority.activation_generation, acquire_operation_id)):
            raise AuthorityDenied("encoding binding read requires the job-bound D11 lease")
        try:
            clock = self.__content_fence_v2.read_ingress_clock(
                self.__scene_clock_policy)
            now = trusted_upper(clock)
        except Exception as exc:
            raise UnavailableGuard("encoding binding trusted clock unavailable; HOLD") from exc

        def reader():
            return self._first_ingress_encoding_binding_locked(
                authority, job_id, acquire_operation_id, clock, now)[0]

        return self._read_v2(authority, reader)

    def _first_ingress_encoding_binding_locked(
        self, authority: AuthorityContext, job_id: str,
        acquire_operation_id: str, clock, now: float,
    ):
        """Qualify the original binding and current worker under the graph lock."""
        from datetime import datetime

        from .runtime.encoding_call_binding import binding_from_json, load_binding

        db = self.__store._db
        (job, _, _, outbox, outbox_key, _, source_version, access_version) = (
            self._first_ingress_encoding_job_locked(authority.namespace, job_id))
        if (not _job_acquire_id_matches(
                acquire_operation_id, authority.namespace, job_id,
                job.operation_id, authority.actor,
                authority.activation_generation)
                or job.phase != "running" or job.lease_holder != authority.actor
                or job.cancel_epoch or job.fence < 1 or job.result_ref is not None
                or authority.worker_fence != job.fence):
            raise UnavailableGuard("encoding binding job lease is not current; HOLD")
        expiry = datetime.fromisoformat(
            job.lease_expires_utc.replace("Z", "+00:00")).timestamp()
        if now >= expiry:
            raise UnavailableGuard("encoding binding job lease expired; HOLD")
        self.__d11_issuer.authorize_existing_encoding_job(db, job, now_utc=now)
        intent = db.execute(
            "SELECT encoding_binding_json FROM graph_job_acquire_intents_v2 "
            "WHERE bot=? AND persona=? AND acquire_operation_id=? "
            "AND job_id=? AND original_operation_id=? AND actor=?",
            authority.namespace.as_tuple + (
                acquire_operation_id, job_id, job.operation_id, authority.actor),
        ).fetchone()
        receipt = db.execute(
            "SELECT 1 FROM graph_job_acquire_receipts_v2 WHERE bot=? "
            "AND persona=? AND acquire_operation_id=?",
            authority.namespace.as_tuple + (acquire_operation_id,),
        ).fetchone()
        binding = load_binding(db, authority.namespace, job_id)
        if (intent is None or intent[0] is None or receipt is None
                or binding is None or binding != binding_from_json(intent[0])
                or binding.request.get("schema") not in {
                    "sylanne.first-ingress-encoding-call.v2",
                    "sylanne.first-ingress-encoding-call.v3"}):
            raise UnavailableGuard("committed original encoding binding is absent; HOLD")
        self._validate_first_ingress_encoding_binding_context(
            authority.namespace, job, outbox, source_version, access_version,
            authority, now, acquire_operation_id, clock, binding)
        return binding, job, outbox, outbox_key

    def commit_post_c02_attention_v1(
        self, bundle: DomainBundle, lease: object, installed_bundle,
    ) -> CommitReceipt:
        """Sign a bounded D07 quote inside its original fenced graph write."""
        from .host.authority_profile import (
            AdminD07AttentionPolicy, AdminInstallationBundle,
        )
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.reply_model_job import d07_attention_quote_id_v1
        from .runtime_contracts import VersionedRef

        if (type(bundle) is not DomainBundle
                or type(installed_bundle) is not AdminInstallationBundle
                or type(installed_bundle.d07_attention)
                is not AdminD07AttentionPolicy
                or installed_bundle.ingress_clock != self.__scene_clock_policy
                or not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None):
            raise UnavailableGuard("installed D07 attention issuance unavailable; HOLD")
        envelope = bundle.envelope
        namespace = envelope.authority.namespace
        quote_id = d07_attention_quote_id_v1(
            namespace, envelope.identity.operation_id)
        if (installed_bundle.installation_policy.namespace != namespace
                or envelope.identity.phase != "post_c02_attention"
                or envelope.authority.purpose != "expression"
                or len(envelope.authority.audience) != 1
                or len(envelope.source_qualification.source_refs) != 1
                or len(envelope.causation) != 1
                or len(bundle.proposals) != 1
                or bundle.proposals[0].domain != "d07"
                or {write.key.type_name for write in
                    bundle.proposals[0].typed_writes} != {
                        "d07.attention_ticket.v1", "d07.focus.v1"}
                or bundle.persistent_job_refs or bundle.outbox_refs
                or bundle.d02_settlement_refs or bundle.d11_cost_settlement_refs
                or envelope.version_guard.resource_lease_versions !=
                   (VersionedRef(quote_id, 1),)):
            raise AuthorityDenied("post-C02 attention bundle identity differs")
        now = trusted_upper(self.__content_fence_v2.read_ingress_clock(
            self.__scene_clock_policy))
        self._authorize(lease, envelope.authority, frozenset({"d07"}))
        return self._commit_domain_bundle_v2(
            bundle, lease, attention_issuance=(installed_bundle, now))

    def read_post_c02_attention_inputs_v1(
        self, bootstrap: object, namespace: NamespaceId,
        c02_operation_id: str, source_ref: str | None, installed_bundle,
    ):
        """Fenced current C02/source read for a separate D07 ticket proposal."""
        from .host.authority_profile import AdminInstallationBundle
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.reply_model_job import (
            read_settled_c02_reply_source_v1, source_key_from_ref,
        )
        from .runtime.c02_bundle_codec import c02_bundle_from_wire
        from .runtime.d12_current_d07_policy_v1 import (
            read_current_d07_attention_policy_v1,
        )
        from .runtime.d07_current_competitor_v2 import (
            read_current_d07_source_closure_in_transaction,
            read_current_primary_competitor_in_transaction,
        )
        from .domains.d12.types import active_scheme_head_key
        from .memory_types import access_key, source_key
        from .runtime_contracts import QueryEpoch, VersionGuard

        self._admin(bootstrap)
        store = self.__store
        port = self.__content_fence_v2
        if (not isinstance(store, ProductionGraphStore) or port is None
                or type(namespace) is not NamespaceId
                or type(installed_bundle) is not AdminInstallationBundle
                or installed_bundle.ingress_clock != self.__scene_clock_policy
                or installed_bundle.installation_policy.namespace != namespace):
            raise UnavailableGuard("installed post-C02 attention read unavailable; HOLD")
        reading = port.read_ingress_clock(self.__scene_clock_policy)
        now = trusted_upper(reading)
        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
            provision_row = self._provision_row(store._db, namespace)
            provision = (self._decode_provision_receipt(provision_row)
                         if provision_row is not None else None)
        target = metadata.requirements
        if (provision is None or target.namespace != namespace
                or provision.installation_id !=
                   installed_bundle.installation_policy.installation_id
                or provision.generation != target.activation_generation):
            raise UnavailableGuard("post-C02 attention installation differs; HOLD")
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("post-C02 attention anchor differs; HOLD")
        operation_id = "reply-attention-read-" + secrets.token_hex(24)
        permit = port.begin_fence(
            namespace=namespace,
            authority_namespace=target.authority_namespace,
            holder=self.__holder, generation=target.activation_generation,
            operation="read", operation_id=operation_id,
            expected_anchor=anchor)
        scope = FenceScope(
            namespace, target.authority_namespace, target.activation_generation,
            "read", operation_id, permit, anchor, epoch,
            metadata.graph_revision)
        try:
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("post-C02 attention read fence changed")
            with store._lock:
                db = store._db
                db.execute("BEGIN")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise StaleRead("post-C02 attention graph changed")
                    sealed = db.execute(
                        "SELECT bundle_json FROM graph_first_ingress_c02_committed_seals_v2 "
                        "WHERE bot=? AND persona=? AND operation_id=?",
                        namespace.as_tuple + (c02_operation_id,),
                    ).fetchone()
                    if sealed is None:
                        raise UnavailableGuard("original C02 seal absent; HOLD")
                    frozen_sources = c02_bundle_from_wire(
                        sealed[0]).envelope.source_qualification.source_refs
                    if (len(frozen_sources) != 1 or
                            (source_ref is not None and source_ref != frozen_sources[0])):
                        raise UnavailableGuard("post-C02 source differs from seal; HOLD")
                    source_ref = frozen_sources[0]
                    source_id = source_key_from_ref(source_ref, namespace)
                    keys = (source_key(*namespace.as_tuple, source_id),
                            access_key(*namespace.as_tuple, source_id),
                            AtomKey(Owner("persona", *namespace.as_tuple),
                                    "d07.focus.v1", namespace.persona_id))
                    atoms = []
                    for key in keys:
                        row = db.execute(
                            "SELECT revision,value,valid FROM graph_atoms "
                            "WHERE token=?", (key.token,),
                        ).fetchone()
                        atoms.append(GraphAtom(
                            key, row[0], json.loads(row[1]), bool(row[2]))
                            if row else GraphAtom(key, 0, {}, False))
                    snapshot = GraphSnapshot(tuple(atoms), (epoch,))
                    c02_row = db.execute(
                        "SELECT digest,activity_id,effect_id,commit_seq,receipt_json "
                        "FROM graph_bundle_operations WHERE bot=? AND persona=? "
                        "AND operation_id=?",
                        namespace.as_tuple + (c02_operation_id,),
                    ).fetchone()
                    if c02_row is None:
                        raise UnavailableGuard("original C02 receipt absent; HOLD")
                    event = db.execute(
                        "SELECT reads,revisions,epoch_revision FROM graph_events "
                        "WHERE bot=? AND persona=? AND session=? AND event_id=?",
                        namespace.as_tuple + (c02_row[1], c02_operation_id),
                    ).fetchone()
                    if event is None:
                        raise UnavailableGuard("original C02 graph event absent; HOLD")
                    detail = json.loads(c02_row[4])
                    receipt = CommitReceipt(
                        "committed", c02_operation_id, c02_row[0], c02_row[1],
                        c02_row[2], c02_row[3],
                        GraphStore._version_rows(event[0]),
                        GraphStore._version_rows(event[1]),
                        (NamespaceEpoch(*namespace.as_tuple, event[2]),),
                        tuple(detail["ledger_refs"]),
                        tuple(detail["outbox_refs"]))
                    current = read_settled_c02_reply_source_v1(
                        db, self.__d02_issuer, namespace, receipt,
                        source_ref, snapshot)
                    current_policy = read_current_d07_attention_policy_v1(
                        db, namespace)
                    head_key = active_scheme_head_key(namespace)
                    head_row = db.execute(
                        "SELECT revision,value,valid FROM graph_atoms "
                        "WHERE token=?", (head_key.token,),
                    ).fetchone()
                    if (head_row is None and
                            current_policy.active_head_ref.revision != 0):
                        raise UnavailableGuard("current D07 policy head changed")
                    if (head_row is not None and
                            (head_row[2] != 1 or head_row[0]
                             != current_policy.active_head_ref.revision)):
                        raise UnavailableGuard("current D07 policy head changed")
                    atoms.append(
                        GraphAtom(head_key, head_row[0], json.loads(head_row[1]), True)
                        if head_row else GraphAtom(head_key, 0, {}, False))
                    current_source_atoms = read_current_d07_source_closure_in_transaction(
                        db, namespace, (source_ref,),
                        audience=current.conversation_ref)
                    focus_atom = atoms[2]
                    competitor = read_current_primary_competitor_in_transaction(
                        db, namespace,
                        focus_atom.value["primary_ticket_ref"]
                        if focus_atom.valid and focus_atom.revision > 0 else None,
                        now_utc=now)
                    current_atoms = {atom.key: atom for atom in atoms}
                    for atom in current_source_atoms + (
                            competitor.atoms if competitor is not None else ()):
                        previous = current_atoms.setdefault(atom.key, atom)
                        if previous != atom:
                            raise StaleRead("post-C02 attention source changed")
                    snapshot = GraphSnapshot(tuple(current_atoms.values()), (epoch,))
                    access_epoch, delete_epoch = self._deletion_epochs_locked(
                        db, namespace)
                    guard = VersionGuard(
                        snapshot.versions,
                        (QueryEpoch(namespace, "all", epoch.revision),),
                        access_epoch, delete_epoch,
                        store._registry.catalogue_hash,
                        self._version(db, namespace, "scheme", "current"),
                        self._version(db, namespace, "operator", "current"),
                        self._version(db, namespace, "policy", "current"),
                        (), (), ())
                    db.execute("COMMIT")
                except BaseException:
                    db.execute("ROLLBACK")
                    raise
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("post-C02 attention read changed; HOLD")
            with store._lock:
                if self._v2_graph_stamp(namespace) != (metadata, epoch):
                    raise UnavailableGuard("post-C02 attention graph changed; HOLD")
            return (receipt, snapshot, current.source_qualification,
                    current.conversation_ref, guard, anchor, reading,
                    current_policy, competitor)
        finally:
            port.finish_fence(
                scope, request_id="finish:" + operation_id,
                request_digest="sha256:" + canonical_digest({
                    "action": "finish_reply_attention_read",
                    "operation_id": operation_id,
                    "permit_token": permit.token,
                }))

    def read_post_c02_attention_decision_v2(
            self, bootstrap: object, namespace: NamespaceId,
            c02_operation_id: str, installed_bundle,
    ) -> D07AttentionDecisionReadV2 | None:
        """Read the immutable attention decision after a current C02 fence.

        The decision is content-free.  A deferred inbound may enter paid work
        only through a later, separately verified release from the old focus.
        """
        self._admin(bootstrap)
        if type(c02_operation_id) is not str or not c02_operation_id:
            raise ValueError("original C02 operation ID required")
        (c02, snapshot, qualification, _conversation, _guard, _anchor,
         _clock, _policy, _competitor) = self.read_post_c02_attention_inputs_v1(
             bootstrap, namespace, c02_operation_id, None, installed_bundle)
        store = self.__store
        with store._lock:
            store._ensure_open()
            _metadata, epoch = self._v2_graph_stamp(namespace)
            if (c02.operation_id != c02_operation_id
                    or snapshot.epochs != (epoch,)
                    or len(qualification.source_refs) != 1):
                raise StaleRead("post-C02 attention decision read changed")
            db = store._db
            db.execute("BEGIN")
            try:
                row = db.execute(
                    "SELECT attention_operation_id,inbound_ticket_ref,"
                    "selected_ticket_ref,inbound_deferred,wake_at,bundle_digest "
                    "FROM graph_d07_attention_decisions_v2 WHERE bot=? AND "
                    "persona=? AND c02_operation_id=?",
                    namespace.as_tuple + (c02_operation_id,),
                ).fetchone()
                if row is None:
                    db.execute("COMMIT")
                    return None
                operation_id, inbound_ref, selected_ref, deferred, wake_at, digest = row
                original = db.execute(
                    "SELECT digest,activity_id FROM graph_bundle_operations WHERE bot=? "
                    "AND persona=? AND operation_id=?",
                    namespace.as_tuple + (operation_id,),
                ).fetchone()
                issuance = db.execute(
                    "SELECT source_ref,bundle_digest FROM "
                    "graph_d07_attention_issuance_v1 WHERE bot=? AND persona=? "
                    "AND operation_id=? AND c02_operation_id=?",
                    namespace.as_tuple + (operation_id, c02_operation_id),
                ).fetchone()
                event = (db.execute(
                    "SELECT reads,revisions,epoch_revision FROM graph_events WHERE "
                    "bot=? AND persona=? AND session=? AND event_id=?",
                    namespace.as_tuple + (original[1], operation_id),
                ).fetchone() if original is not None else None)
                revisions = ({version.key.token: version.revision
                              for version in GraphStore._version_rows(event[1])}
                             if event is not None else {})
                reads = ({version.key.token: version.revision
                          for version in GraphStore._version_rows(event[0])}
                         if event is not None else {})
                if (original is None or original[0] != digest
                        or issuance != (qualification.source_refs[0], digest)
                        or event is None or event[2] > epoch.revision
                        or AtomKey.from_token(inbound_ref).type_name
                           != "d07.attention_ticket.v1"
                        or AtomKey.from_token(selected_ref).type_name
                           != "d07.attention_ticket.v1"
                        or revisions.get(inbound_ref) != 1
                        or (deferred == 1 and reads.get(selected_ref, 0) < 1)
                        or deferred not in (0, 1)
                        or (bool(deferred) == (inbound_ref == selected_ref))
                        or (deferred == 1 and
                            (type(wake_at) not in (int, float)
                             or not math.isfinite(wake_at)))
                        or (deferred == 0 and wake_at is not None)):
                    raise UnavailableGuard("durable D07 attention decision differs")
                result = D07AttentionDecisionReadV2(
                    namespace, c02_operation_id, operation_id,
                    inbound_ref, selected_ref, bool(deferred), wake_at,
                    digest, event[2])
                db.execute("COMMIT")
                return result
            except BaseException:
                db.execute("ROLLBACK")
                raise

    def discover_released_post_c02_attention_v2(
            self, bootstrap: object, namespace: NamespaceId, installed_bundle,
            *, after: str | None = None, limit: int = 32,
    ) -> D07ReleasedAttentionPageV2:
        """Discover durable deferred C02 originals released by an accepted send."""
        self._admin(bootstrap)
        if (type(namespace) is not NamespaceId
                or (after is not None and (type(after) is not str or not after))
                or type(limit) is not int or not 1 <= limit <= 64):
            raise ValueError("invalid released attention page request")
        store = self.__store
        with store._lock:
            store._ensure_open()
            metadata, epoch = self._v2_graph_stamp(namespace)
            db = store._db
            if db.execute(
                    "SELECT 1 FROM sqlite_master WHERE type='table' AND "
                    "name='graph_d07_deferred_release_v2'").fetchone() is None:
                rows = ()
            else:
                rows = db.execute(
                    "SELECT r.deferred_c02_operation_id,r.final_operation_id,"
                    "r.ticket_ref,r.observation_digest,r.graph_epoch,"
                    "d.attention_operation_id,d.inbound_ticket_ref,"
                    "d.inbound_deferred,o.observed_digest,o.receipt_json "
                    "FROM graph_d07_deferred_release_v2 AS r "
                    "LEFT JOIN graph_d07_attention_decisions_v2 AS d ON "
                    "d.bot=r.bot AND d.persona=r.persona AND "
                    "d.c02_operation_id=r.deferred_c02_operation_id "
                    "LEFT JOIN graph_d07_observed_focus_v2 AS o ON "
                    "o.bot=r.bot AND o.persona=r.persona AND "
                    "o.final_operation_id=r.final_operation_id "
                    "WHERE r.bot=? AND r.persona=? AND "
                    "r.deferred_c02_operation_id>? "
                    "ORDER BY r.deferred_c02_operation_id LIMIT ?",
                    namespace.as_tuple + (after or "", limit + 1),
                ).fetchall()
            for (c02_id, final_id, ticket_ref, observed_digest, release_epoch,
                 attention_id, inbound_ref, deferred, recorded_digest,
                 receipt_json) in rows:
                completed = (json.loads(receipt_json)
                             if receipt_json is not None else None)
                if (attention_id is None or inbound_ref != ticket_ref
                        or deferred != 1 or recorded_digest != observed_digest
                        or type(completed) is not dict
                        or completed.get("status") != "committed"
                        or completed.get("final_operation_id") != final_id
                        or completed.get("promoted_c02_operation_id") != c02_id
                        or completed.get("promoted_ticket_ref") != ticket_ref
                        or release_epoch > epoch.revision
                        or AtomKey.from_token(ticket_ref).type_name
                           != "d07.attention_ticket.v1"):
                    raise UnavailableGuard("durable D07 release differs; HOLD")
        selected = rows[:limit]
        items: list[D07ReleasedAttentionItemV2] = []
        for c02_id, final_id, ticket_ref, _, _, attention_id, _, _, _, _ in selected:
            decision = self.read_post_c02_attention_decision_v2(
                bootstrap, namespace, c02_id, installed_bundle)
            if (decision is None or not decision.inbound_deferred
                    or decision.attention_operation_id != attention_id
                    or decision.inbound_ticket_ref != ticket_ref):
                raise UnavailableGuard("released D07 decision changed; HOLD")
            items.append(D07ReleasedAttentionItemV2(
                c02_id, attention_id, ticket_ref, final_id))
        with store._lock:
            if self._v2_graph_stamp(namespace) != (metadata, epoch):
                raise StaleRead("released attention page changed")
        return D07ReleasedAttentionPageV2(
            namespace, tuple(items), items[-1].c02_operation_id
            if len(rows) > limit else None,
            metadata.graph_revision, epoch.revision)

    def _natural_observed_attention_original_locked(
            self, namespace: NamespaceId, final_operation_id: str):
        """Follow committed final, P2 claim, generation and D07 issuance."""
        from .domains.d07 import attention_ticket_key
        from .host.post_c02_attention_driver import post_c02_attention_operation_id
        from .runtime.dispatch_graph_claim import dispatch_claim_key, dispatch_claim_type_spec
        from .runtime.natural_reply_job_v2 import read_original_preparation

        db = self.__store._db
        if not self.__store._lock._is_owned() or not db.in_transaction:
            raise RuntimeError("natural attention original requires graph transaction")
        recovered = self._get_natural_dispatch_candidate_evidence_locked(
            namespace, final_operation_id)
        if recovered is None:
            raise UnavailableGuard("committed natural final is absent; HOLD")
        effect_id = recovered.evidence.effect_id
        claim = db.execute(
            "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
            (dispatch_claim_key(namespace, effect_id).token,),
        ).fetchone()
        if claim is None or claim[0] != 1 or claim[2] != 1:
            raise UnavailableGuard("natural P2 graph claim is absent; HOLD")
        claim_value = json.loads(claim[1])
        dispatch_claim_type_spec().validator(claim_value)
        if (claim_value["operation_id"] != final_operation_id
                or claim_value["effect_id"] != effect_id):
            raise UnavailableGuard("natural P2 claim differs from final; HOLD")
        parents = db.execute(
            "SELECT parent_original_id FROM graph_natural_generation_preparations_v2 "
            "WHERE bot=? AND persona=? AND original_operation_id=?",
            namespace.as_tuple + (
                recovered.evidence.generation_original_operation_id,),
        ).fetchall()
        if len(parents) != 1:
            raise UnavailableGuard("natural generation lineage is ambiguous; HOLD")
        c02_operation_id = parents[0][0]
        generation = read_original_preparation(
            db, namespace, c02_operation_id, "generation")
        if (generation is None or generation.state != "terminal"
                or generation.seal.original_operation_id !=
                   recovered.evidence.generation_original_operation_id
                or generation.seal.c02_operation_id != c02_operation_id):
            raise UnavailableGuard("natural generation lineage differs; HOLD")
        attention_operation_id = post_c02_attention_operation_id(
            c02_operation_id, generation.seal.source_ref)
        rows = db.execute(
            "SELECT operation_id FROM graph_d07_attention_issuance_v1 "
            "WHERE bot=? AND persona=? AND c02_operation_id=? AND source_ref=?",
            namespace.as_tuple + (
                c02_operation_id, generation.seal.source_ref),
        ).fetchall()
        if rows != [(attention_operation_id,)]:
            raise UnavailableGuard("natural D07 original issuance differs; HOLD")
        ticket_id = "attention:" + canonical_digest({
            "operation_id": attention_operation_id,
        })[:48]
        ticket_ref = attention_ticket_key(namespace, ticket_id).token
        return c02_operation_id, ticket_ref, effect_id

    @staticmethod
    def _install_d07_observed_focus_schema_v2(db) -> None:
        db.execute("""CREATE TABLE IF NOT EXISTS graph_d07_observed_focus_v2(
            bot TEXT NOT NULL, persona TEXT NOT NULL,
            final_operation_id TEXT NOT NULL, c02_operation_id TEXT NOT NULL,
            effect_id TEXT NOT NULL, ticket_ref TEXT NOT NULL,
            observation_id TEXT NOT NULL, observed_digest TEXT NOT NULL,
            focus_revision INTEGER NOT NULL, graph_epoch INTEGER NOT NULL,
            attempt_id TEXT NOT NULL, permit_json TEXT NOT NULL,
            pre_graph_revision INTEGER NOT NULL, pre_graph_epoch INTEGER NOT NULL,
            finish_request_id TEXT NOT NULL, finish_request_digest TEXT NOT NULL,
            receipt_json TEXT NOT NULL,
            PRIMARY KEY(bot,persona,final_operation_id))""")
        db.execute("""CREATE TRIGGER IF NOT EXISTS graph_d07_observed_focus_no_update_v2
            BEFORE UPDATE ON graph_d07_observed_focus_v2 BEGIN
              SELECT RAISE(ABORT,'observed focus receipt is immutable'); END""")
        db.execute("""CREATE TRIGGER IF NOT EXISTS graph_d07_observed_focus_no_delete_v2
            BEFORE DELETE ON graph_d07_observed_focus_v2 BEGIN
              SELECT RAISE(ABORT,'observed focus receipt is immutable'); END""")
        db.execute("""CREATE TABLE IF NOT EXISTS graph_d07_deferred_release_v2(
            bot TEXT NOT NULL, persona TEXT NOT NULL,
            deferred_c02_operation_id TEXT NOT NULL,
            final_operation_id TEXT NOT NULL,
            ticket_ref TEXT NOT NULL,
            observation_digest TEXT NOT NULL,
            graph_epoch INTEGER NOT NULL,
            PRIMARY KEY(bot,persona,deferred_c02_operation_id),
            UNIQUE(bot,persona,final_operation_id))""")
        db.execute("""CREATE TRIGGER IF NOT EXISTS graph_d07_deferred_release_no_update_v2
            BEFORE UPDATE ON graph_d07_deferred_release_v2 BEGIN
              SELECT RAISE(ABORT,'D07 deferred release is immutable'); END""")
        db.execute("""CREATE TRIGGER IF NOT EXISTS graph_d07_deferred_release_no_delete_v2
            BEFORE DELETE ON graph_d07_deferred_release_v2 BEGIN
              SELECT RAISE(ABORT,'D07 deferred release is immutable'); END""")

    def record_natural_outbound_observation_v1(self, bootstrap, namespace, final_operation_id):
        from .runtime.d13_outbound_observation_v1 import commit_natural_outbound_observation_v1
        return commit_natural_outbound_observation_v1(self, bootstrap, namespace, final_operation_id)

    def complete_observed_natural_attention_v2(
            self, bootstrap: object, namespace: NamespaceId,
            final_operation_id: str) -> D07ObservedFocusCompletionV2:
        """Clear the served primary or promote one qualified deferred inbound."""
        from .authority_service.v2_contract import FencePermitV2, from_wire, to_wire
        from .authority_service.v2_execution_bridge import CurrentEffectReadV2
        from .domains.d07 import D07DomainProvider, FocusState, attention_ticket_key
        from .runtime.dispatch_graph_claim import dispatch_claim_key

        self._admin(bootstrap)
        store = self.__store
        port = self.__content_fence_v2
        if (type(namespace) is not NamespaceId or type(final_operation_id) is not str
                or not final_operation_id or not isinstance(store, ProductionGraphStore)
                or port is None or not callable(getattr(port, "read_current_effect", None))):
            raise UnavailableGuard("natural attention completion authority absent; HOLD")
        attempt_id = "d07-observed-focus:" + canonical_digest({
            "namespace": namespace.as_tuple,
            "final_operation_id": final_operation_id,
        })[:48]
        with store._lock:
            db = store._db
            db.execute("BEGIN")
            try:
                existing_table = db.execute(
                    "SELECT 1 FROM sqlite_master WHERE type='table' "
                    "AND name='graph_d07_observed_focus_v2'",
                ).fetchone()
                saved = (db.execute(
                    "SELECT c02_operation_id,effect_id,ticket_ref,observation_id,"
                    "observed_digest,focus_revision,graph_epoch,attempt_id,permit_json,"
                    "pre_graph_revision,pre_graph_epoch,finish_request_id,"
                    "finish_request_digest,receipt_json FROM graph_d07_observed_focus_v2 "
                    "WHERE bot=? AND persona=? AND final_operation_id=?",
                    namespace.as_tuple + (final_operation_id,),
                ).fetchone() if existing_table else None)
                saved_history = None
                saved_event = None
                released = None
                if saved is not None:
                    focus_key = AtomKey(
                        Owner("persona", *namespace.as_tuple),
                        "d07.focus.v1", namespace.persona_id)
                    saved_history = db.execute(
                        "SELECT value,valid,event_session,event_id FROM graph_history "
                        "WHERE token=? AND revision=?",
                        (focus_key.token, saved[5]),
                    ).fetchone()
                    saved_event = db.execute(
                        "SELECT epoch_revision,revisions FROM graph_events WHERE "
                        "bot=? AND persona=? AND session=? AND event_id=?",
                        namespace.as_tuple + (
                            "d07-observed-focus-v2", attempt_id),
                    ).fetchone()
                    if db.execute(
                            "SELECT 1 FROM sqlite_master WHERE type='table' AND "
                            "name='graph_d07_deferred_release_v2'",
                    ).fetchone():
                        released = db.execute(
                            "SELECT deferred_c02_operation_id,ticket_ref,"
                            "observation_digest,graph_epoch FROM "
                            "graph_d07_deferred_release_v2 WHERE bot=? AND "
                            "persona=? AND final_operation_id=?",
                            namespace.as_tuple + (final_operation_id,),
                        ).fetchone()
                c02_operation_id, ticket_ref, effect_id = (
                    self._natural_observed_attention_original_locked(
                        namespace, final_operation_id))
                metadata, epoch = self._v2_graph_stamp(namespace)
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise
        target = metadata.requirements
        if saved is not None:
            result = D07ObservedFocusCompletionV2(
                "committed", final_operation_id, saved[0], saved[1], saved[2],
                saved[3], saved[5], saved[6],
                released[1] if released else None,
                released[0] if released else None)
            if (saved[0:3] != (c02_operation_id, effect_id, ticket_ref)
                    or saved[7] != attempt_id
                    or saved[13] != canonical_json(asdict(result))
                    or saved_history is None
                    or saved_history[1:] != (
                        1, "d07-observed-focus-v2", attempt_id)
                    or json.loads(saved_history[0]).get("primary_ticket_ref")
                       != result.promoted_ticket_ref
                    or (released is not None and released[2:] != (
                        saved[4], saved[6]))
                    or saved_event is None or saved_event[0] != saved[6]
                    or GraphVersion(focus_key, saved[5]) not in
                       GraphStore._version_rows(saved_event[1])
                    or saved[6] > epoch.revision
                    or saved[9] >= metadata.graph_revision):
                raise UnavailableGuard("durable focus completion differs; HOLD")
            permit = from_wire(json.loads(saved[8]))
            observed_permit, state = port.get_fence_operation(
                namespace=namespace, authority_namespace=target.authority_namespace,
                operation_id=attempt_id)
            if (type(permit) is not FencePermitV2 or observed_permit != permit
                    or state not in {"active", "finished"}
                    or permit.operation != "write"
                    or permit.subject != port.installation_grant.subject
                    or saved[11] != "finish:" + attempt_id
                    or saved[12] != "sha256:" + canonical_digest({
                        "action": "finish_d07_observed_focus",
                        "attempt_id": attempt_id, "permit_token": permit.token,
                    })):
                raise UnavailableGuard("durable focus Authority fence differs; HOLD")
            if state == "active":
                if (metadata.graph_revision, epoch.revision) != (
                        saved[9] + 1, saved[10] + 1):
                    raise UnavailableGuard("active focus finish lost graph stamp; HOLD")
                scope = FenceScope(
                    namespace, target.authority_namespace,
                    target.activation_generation, "write", attempt_id,
                    permit, permit.pinned_anchor,
                    NamespaceEpoch(*namespace.as_tuple, saved[10]), saved[9])
                if port.validate_fence(scope) != permit:
                    raise UnavailableGuard("focus completion permit changed; HOLD")
                port.finish_fence(
                    scope, request_id=saved[11], request_digest=saved[12])
            original_effect = port.read_current_effect(
                namespace=namespace,
                authority_namespace=target.authority_namespace,
                effect_id=effect_id)
            if (type(original_effect) is not CurrentEffectReadV2
                    or original_effect.state != "observed"
                    or original_effect.observation_outcome != "accepted"
                    or original_effect.observation_id != saved[3]
                    or canonical_digest(original_effect) != saved[4]):
                raise UnavailableGuard("durable focus observation changed; HOLD")
            return replace(result, status="duplicate")
        observed = port.read_current_effect(
            namespace=namespace, authority_namespace=target.authority_namespace,
            effect_id=effect_id)
        if (type(observed) is not CurrentEffectReadV2
                or observed.state != "observed" or not observed.observation_id
                or getattr(observed, "observation_outcome", None) != "accepted"
                or observed.effect_id != effect_id
                or observed.authority_id != target.authority_id
                or observed.namespace != target.authority_namespace
                or observed.activation_generation != target.activation_generation):
            raise UnavailableGuard("natural effect has no original observation; HOLD")
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if (not self._accounting_anchor_covers(target, anchor)
                or (observed.execution_head_seq, observed.execution_head_digest)
                   != (anchor.execution_seq, anchor.execution_digest)):
            raise UnavailableGuard("observed effect current head changed; HOLD")
        from .runtime.first_ingress_v2 import trusted_upper
        now_utc = trusted_upper(port.read_ingress_clock(
            self.__scene_clock_policy))
        permit = port.begin_fence(
            namespace=namespace, authority_namespace=target.authority_namespace,
            holder=self.__holder, generation=target.activation_generation,
            operation="write", operation_id=attempt_id, expected_anchor=anchor,
            retain_on_unknown=True)
        scope = FenceScope(
            namespace, target.authority_namespace, target.activation_generation,
            "write", attempt_id, permit, anchor, epoch, metadata.graph_revision)
        finish_id = "finish:" + attempt_id
        finish_digest = "sha256:" + canonical_digest({
            "action": "finish_d07_observed_focus", "attempt_id": attempt_id,
            "permit_token": permit.token,
        })
        commit_started = False
        try:
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("natural attention write fence changed; HOLD")
            with store._lock:
                db = store._db
                db.execute("BEGIN IMMEDIATE")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise StaleRead("natural attention graph stamp changed")
                    if self._natural_observed_attention_original_locked(
                            namespace, final_operation_id) != (
                            c02_operation_id, ticket_ref, effect_id):
                        raise StaleRead("natural attention original changed")
                    focus_key = AtomKey(
                        Owner("persona", *namespace.as_tuple),
                        "d07.focus.v1", namespace.persona_id)
                    focus_row = db.execute(
                        "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                        (focus_key.token,),
                    ).fetchone()
                    if focus_row is None or focus_row[2] != 1:
                        raise UnavailableGuard("current natural focus is absent; HOLD")
                    focus_value = json.loads(focus_row[1])
                    next(spec for spec in D07DomainProvider.type_specs()
                         if spec.name == "d07.focus.v1").validator(focus_value)
                    focus = FocusState(
                        focus_value["persona_id"], focus_value["focus_epoch"],
                        focus_value["primary_ticket_ref"],
                        tuple(focus_value["auxiliary_ticket_refs"]),
                        focus_value["switch_reason"])
                    if focus.primary_ticket_ref != ticket_ref:
                        raise UnavailableGuard("natural focus primary changed; HOLD")
                    promoted = None
                    deferred_c02 = None
                    promoted_reads = ()
                    if focus.auxiliary_ticket_refs:
                        if len(focus.auxiliary_ticket_refs) != 1:
                            raise UnavailableGuard("natural focus has unsupported auxiliaries; HOLD")
                        from .runtime.d07_current_competitor_v2 import (
                            read_current_primary_competitor_in_transaction,
                        )
                        promoted = focus.auxiliary_ticket_refs[0]
                        original = read_current_primary_competitor_in_transaction(
                            db, namespace, promoted, now_utc=now_utc)
                        if (original is None or original.ticket.valid_until <= now_utc
                                or not original.ticket.eligible
                                or not original.ticket.resources_available
                                or original.ticket.cancel_refs
                                or original.ticket.served_fraction >= 1.0):
                            raise UnavailableGuard("deferred inbound is no longer runnable; HOLD")
                        deferred_c02 = original.c02_operation_id
                        decision = db.execute(
                            "SELECT selected_ticket_ref,inbound_deferred FROM "
                            "graph_d07_attention_decisions_v2 WHERE bot=? AND "
                            "persona=? AND c02_operation_id=? AND inbound_ticket_ref=?",
                            namespace.as_tuple + (deferred_c02, promoted),
                        ).fetchone()
                        if decision != (ticket_ref, 1):
                            raise UnavailableGuard("deferred inbound decision differs; HOLD")
                        promoted_reads = original.read_versions
                    ticket_key = attention_ticket_key(
                        namespace, AtomKey.from_token(ticket_ref).name)
                    ticket_row = db.execute(
                        "SELECT revision,valid FROM graph_atoms WHERE token=?",
                        (ticket_ref,),
                    ).fetchone()
                    claim_key = dispatch_claim_key(namespace, effect_id)
                    claim_row = db.execute(
                        "SELECT revision,valid FROM graph_atoms WHERE token=?",
                        (claim_key.token,),
                    ).fetchone()
                    if (ticket_key.token != ticket_ref or ticket_row is None
                            or ticket_row[1] != 1 or claim_row != (1, 1)):
                        raise UnavailableGuard("natural focus original heads changed; HOLD")
                    new_focus = {
                        **focus_value, "focus_epoch": focus.focus_epoch + 1,
                        "primary_ticket_ref": promoted,
                        "auxiliary_ticket_refs": [],
                        "switch_reason": (
                            "observed_natural_dispatch_promoted"
                            if promoted is not None else "observed_natural_dispatch"),
                    }
                    event = Event(
                        Scope(*namespace.as_tuple, "d07-observed-focus-v2"),
                        attempt_id, time.time(), "natural_attention_observed", {
                            "final_operation_id": final_operation_id,
                            "c02_operation_id": c02_operation_id,
                            "effect_id": effect_id, "ticket_ref": ticket_ref,
                            "promoted_ticket_ref": promoted,
                            "deferred_c02_operation_id": deferred_c02,
                            "observation_digest": canonical_digest(observed),
                        })
                    receipt = GraphStore._graph_commit_in_transaction(
                        store, GraphCandidate(event, (
                            GraphVersion(focus_key, focus_row[0]),
                            GraphVersion(ticket_key, ticket_row[0]),
                            GraphVersion(claim_key, 1), *promoted_reads),
                            (GraphWrite(focus_key, new_focus),), (epoch,)),
                        _capability=self.__graph_capability)
                    if (receipt.status != "committed"
                            or receipt.revisions != (
                                GraphVersion(focus_key, focus_row[0] + 1),)):
                        raise UnavailableGuard("natural focus CAS did not commit")
                    self._install_d07_observed_focus_schema_v2(db)
                    replacement = replace(
                        target, execution_seq=anchor.execution_seq,
                        execution_digest=anchor.execution_digest)
                    store.cas_graph_recovery_metadata(
                        metadata, replacement, _capability=self.__graph_capability)
                    result = D07ObservedFocusCompletionV2(
                        "committed", final_operation_id, c02_operation_id,
                        effect_id, ticket_ref, observed.observation_id,
                        focus_row[0] + 1, receipt.epoch.revision,
                        promoted, deferred_c02)
                    db.execute(
                        "INSERT INTO graph_d07_observed_focus_v2 "
                        "(bot,persona,final_operation_id,c02_operation_id,effect_id,"
                        "ticket_ref,observation_id,observed_digest,focus_revision,"
                        "graph_epoch,attempt_id,permit_json,pre_graph_revision,"
                        "pre_graph_epoch,finish_request_id,finish_request_digest,"
                        "receipt_json) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                        namespace.as_tuple + (
                            final_operation_id, c02_operation_id, effect_id,
                            ticket_ref, observed.observation_id,
                            canonical_digest(observed), focus_row[0] + 1,
                            receipt.epoch.revision, attempt_id,
                            canonical_json(to_wire(permit)), metadata.graph_revision,
                            epoch.revision, finish_id, finish_digest,
                            canonical_json(asdict(result))),
                    )
                    if promoted is not None:
                        db.execute(
                            "INSERT INTO graph_d07_deferred_release_v2 "
                            "VALUES(?,?,?,?,?,?,?)",
                            namespace.as_tuple + (
                                deferred_c02, final_operation_id, promoted,
                                canonical_digest(observed),
                                receipt.epoch.revision),
                        )
                    commit_started = True
                    db.execute("COMMIT")
                except BaseException:
                    if db.in_transaction:
                        db.execute("ROLLBACK")
                    raise
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("committed natural focus permit changed; HOLD")
            port.finish_fence(scope, request_id=finish_id,
                              request_digest=finish_digest)
            return result
        except BaseException:
            if not commit_started:
                port.finish_fence(scope, request_id=finish_id,
                                  request_digest=finish_digest)
            raise

    def _qualified_reply_attention_locked(
            self, namespace: NamespaceId, source_ref: str,
            now_utc: float, epoch: NamespaceEpoch):
        """Read the selected D07 ticket and complete D06 ancestry in one tx."""
        from .domains.d06 import source_correction_head_key
        from .domains.d07 import attention_ticket_key
        from .domains.d07.qualified_attention_read import (
            read_qualified_focus_attention_ticket,
        )
        from .memory_types import SourceRecord, access_key, source_key

        db = self.__store._db
        if not db.in_transaction:
            raise UnavailableGuard("qualified reply attention needs current graph tx")
        source_id = AtomKey.from_token(source_ref).owner.subject
        ingress = db.execute(
            "SELECT conversation_ref FROM graph_first_ingress_identity_v1 "
            "WHERE bot=? AND persona=? AND source_ref=?",
            namespace.as_tuple + (source_id,),
        ).fetchall()
        if len(ingress) != 1:
            raise UnavailableGuard("reply source has no unique original audience")
        focus_key = AtomKey(Owner("persona", *namespace.as_tuple),
                            "d07.focus.v1", namespace.persona_id)
        atoms = {}

        def load(key):
            if key not in atoms:
                row = db.execute(
                    "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                    (key.token,),
                ).fetchone()
                atoms[key] = (GraphAtom(key, row[0], json.loads(row[1]), bool(row[2]))
                              if row else GraphAtom(key, 0, {}, False))
            return atoms[key]

        focus = load(focus_key)
        if not focus.valid:
            raise UnavailableGuard("current D07 focus is absent")
        try:
            ticket_key = AtomKey.from_token(focus.value["primary_ticket_ref"])
            if ticket_key != attention_ticket_key(namespace, ticket_key.name):
                raise ValueError("ticket key differs")
            ticket = load(ticket_key)
            pending = list(ticket.value["source_refs"])
            if not pending or len(pending) > 256:
                raise ValueError("ticket source roots invalid")
            seen = set()
            while pending:
                ref = pending.pop()
                if ref in seen:
                    continue
                if len(seen) >= 256:
                    raise ValueError("source closure exceeds bound")
                key = AtomKey.from_token(ref)
                if key != source_key(*namespace.as_tuple, key.owner.subject or ""):
                    raise ValueError("ticket source key differs")
                seen.add(ref)
                atom = load(key)
                load(access_key(*namespace.as_tuple, key.owner.subject))
                load(source_correction_head_key(namespace, key.owner.subject))
                record = SourceRecord.from_dict(atom.value)
                pending.extend(source_key(*namespace.as_tuple, parent).token
                               for parent in record.parent_source_ids)
        except (KeyError, TypeError, ValueError, AttributeError) as exc:
            raise UnavailableGuard("qualified D07 source closure unavailable") from exc
        snapshot = GraphSnapshot(tuple(atoms.values()), (epoch,))
        qualified = read_qualified_focus_attention_ticket(
            snapshot, namespace, now=now_utc,
            audience=ingress[0][0], purpose="expression")
        if qualified is None:
            raise UnavailableGuard("qualified D07 attention is unavailable")
        return snapshot, qualified.attention

    def _current_post_c02_reply_inputs_locked(
        self, namespace: NamespaceId, c02_operation_id: str,
        source_ref: str, now_utc: float, epoch: NamespaceEpoch,
    ):
        """Read original C02 and current D06/D07 atoms in this graph tx."""
        from .runtime.reply_model_job import (
            ReplyModelJobHold, read_current_reply_model_inputs_v1,
        )

        db = self.__store._db
        snapshot, attention = self._qualified_reply_attention_locked(
            namespace, source_ref, now_utc, epoch)
        c02_row = db.execute(
            "SELECT digest,activity_id,effect_id,commit_seq,receipt_json "
            "FROM graph_bundle_operations WHERE bot=? AND persona=? "
            "AND operation_id=?",
            namespace.as_tuple + (c02_operation_id,),
        ).fetchone()
        if c02_row is None:
            raise ReplyModelJobHold("original C02 receipt is absent")
        c02_event = db.execute(
            "SELECT reads,revisions,epoch_revision FROM graph_events "
            "WHERE bot=? AND persona=? AND session=? AND event_id=?",
            namespace.as_tuple + (c02_row[1], c02_operation_id),
        ).fetchone()
        if c02_event is None:
            raise ReplyModelJobHold("original C02 graph event is absent")
        c02_detail = json.loads(c02_row[4])
        receipt = CommitReceipt(
            "committed", c02_operation_id, c02_row[0], c02_row[1],
            c02_row[2], c02_row[3],
            GraphStore._version_rows(c02_event[0]),
            GraphStore._version_rows(c02_event[1]),
            (NamespaceEpoch(*namespace.as_tuple, c02_event[2]),),
            tuple(c02_detail["ledger_refs"]),
            tuple(c02_detail["outbox_refs"]))
        return read_current_reply_model_inputs_v1(
            db, self.__d02_issuer, namespace, receipt,
            source_ref, snapshot, attention)

    def _current_post_c02_reply_route_locked(
        self, namespace: NamespaceId, c02_operation_id: str,
        source_ref: str, now_utc: float, epoch: NamespaceEpoch,
    ):
        """Pair current C02/source/D07 with the original sealed private route."""
        from .runtime.reply_model_job import read_current_reply_route_manifest_v2

        store = self.__store
        if not store._lock._is_owned() or not store._db.in_transaction:
            raise RuntimeError("reply route requires the held graph transaction")
        inputs = self._current_post_c02_reply_inputs_locked(
            namespace, c02_operation_id, source_ref, now_utc, epoch)
        route = read_current_reply_route_manifest_v2(
            store._db, namespace, inputs, source_ref)
        return inputs, route

    def _current_natural_generation_inputs_locked(
        self, namespace: NamespaceId, c02_operation_id: str,
        source_ref: str, now_utc: float, epoch: NamespaceEpoch,
    ):
        """Bind one private C02 reply to current D06/D07/D03 scope in one tx."""
        from .domains.d03.context import ContextProvider, RoleBindingRequest
        from .runtime.dispatch_current_projection import (
            derive_current_domain_reads, read_current_dispatch_projection,
        )
        from .runtime.reply_entity_route_v2 import (
            read_current_reply_entity_route_binding_v2,
        )
        from .runtime_contracts import VersionedRef

        store = self.__store
        db = store._db
        if not store._lock._is_owned() or not db.in_transaction:
            raise UnavailableGuard("natural generation needs current write tx")
        registration = self.__providers.get("d03")
        context = registration[0] if registration is not None else None
        if type(context) is not ContextProvider:
            raise UnavailableGuard("installed D03 role resolver unavailable; HOLD")
        inputs, route = self._current_post_c02_reply_route_locked(
            namespace, c02_operation_id, source_ref, now_utc, epoch)
        full, query = self._dispatch_full_graph_snapshot_locked(namespace)
        if query.revision != epoch.revision:
            raise StaleRead("natural generation graph epoch changed")
        # SQL's absence is a real D06 correction-head rev0 proof in this tx.
        atoms = {atom.key: atom for atom in full.atoms}
        for atom in inputs.graph_snapshot.atoms:
            if atom.key in atoms and atoms[atom.key] != atom:
                raise StaleRead("natural generation source closure changed")
            atoms[atom.key] = atom
        snapshot = GraphSnapshot(tuple(atoms.values()), full.epochs)
        binding = read_current_reply_entity_route_binding_v2(
            db, namespace, route, query, now_utc=now_utc)
        projection = read_current_dispatch_projection(db, namespace, snapshot, query)
        request = RoleBindingRequest(
            f"persona:{namespace.persona_id}", binding.target_entity_ref,
            None, route.scene_ref, "expression", "reply", now_utc, True,
        )
        role_read, boundary_read = derive_current_domain_reads(
            db, projection, request, context)
        if (role_read.status != "complete" or len(role_read.matched_bindings) != 1
                or projection.coverage != "full"
                or boundary_read.coverage != "full"):
            raise UnavailableGuard("current private scene role is not unique; HOLD")
        matched = role_read.matched_bindings[0]
        selected = tuple(atom for atom in projection.role_bindings
                         if atom.key.name == matched
                         and atom.value.get("scene_ref") == route.scene_ref)
        if len(selected) != 1:
            raise UnavailableGuard("current scene role proof is absent; HOLD")
        scene = VersionedRef(selected[0].key.token, selected[0].revision)
        audience = VersionedRef(binding.binding_version.key.token,
                                binding.binding_version.revision)
        return (inputs, route, binding, snapshot, query, role_read,
                boundary_read, scene, audience)

    def _prepare_natural_generation_scope_locked(
        self, namespace: NamespaceId, c02_operation_id: str,
        source_ref: str, installed_bundle, now_utc: float,
        epoch: NamespaceEpoch, *, original_deadline: float | None = None,
        frozen_original=None, history_decision_out=None, history_preflight_out=None, history_preflight=None,
    ):
        """Derive the first private source plan from current graph and budget."""
        from .domains.d06.qualified_expression import (
            QualifiedExpressionRequest, SourceTextSpan,
            prepare_qualified_expression_unit,
        )
        from .domains.d08.natural_plan import (
            NaturalPlanPreparationEvidenceV2, natural_final_effect_id_v2,
            natural_plan_id_v2, natural_plan_key_v2,
            natural_route_semantic_digest_v2,
            prepare_coordinator_natural_plan_write_v2,
            verify_current_natural_plan_v2,
        )
        from .domains.d09.natural_reply import (
            NaturalExpressionPlanV2, QualifiedExpressionUnitV2,
        )
        from .domains.d09 import ClaimKind
        from .host.post_c02_reply_driver import post_c02_reply_operation_id
        from .model_broker.context_reply import ContextReplyPartV1
        from .model_broker.natural_reply import (
            NaturalReplyInputV2, NaturalReplyInstallationV2,
            freeze_natural_reply_request_v2,
        )
        from .runtime.natural_scoped_query_proof_v2 import (
            assert_original_scoped_d06_projection_v2,
            natural_private_scope_from_binding_v2,
            read_natural_scoped_query_proof_v2,
        )
        from .runtime_contracts import VersionedRef

        db = self.__store._db
        (inputs, route, binding, snapshot, query, role_read,
         boundary_read, scene, audience) = self._current_natural_generation_inputs_locked(
             namespace, c02_operation_id, source_ref, now_utc, epoch)
        workflow = installed_bundle.model_workflows.natural_generation
        review = installed_bundle.model_workflows.natural_review
        if workflow is None or review is None:
            raise UnavailableGuard("both natural paid workflows must be installed; HOLD")
        grant = self.__d11_issuer.current_budget_grant(
            db, installed_bundle.installation_policy.root_lease.lease_id)
        if (grant != installed_bundle.installation_policy.root_grant
                or not {"natural_generation", "natural_review"}.issubset(
                    grant.allowed_work_kinds)
                or route.conversation_ref not in workflow.audiences
                or route.conversation_ref not in review.audiences):
            raise UnavailableGuard("natural budget or audience differs; HOLD")
        expiry = min(value for value in (
            inputs.attention.ticket.valid_until, binding.valid_until_utc,
            role_read.valid_until, grant.valid_until_utc,
            (original_deadline if original_deadline is not None
             else now_utc + 300.0)) if value is not None)
        if expiry <= now_utc + workflow.timeout_seconds + 1:
            raise UnavailableGuard("natural scope expires before paid generation")
        source = inputs.source.source
        barrier = db.execute(
            "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
            "WHERE bot=? AND persona=?", namespace.as_tuple,
        ).fetchone()
        if barrier is None:
            raise UnavailableGuard("natural source barrier absent")
        candidate = prepare_qualified_expression_unit(
            snapshot, namespace=namespace,
            request=QualifiedExpressionRequest(
                source_ref, "attributed_report", SourceTextSpan(0, len(source.text))),
            audiences=(route.conversation_ref,), access_epoch=barrier[0],
            deletion_epoch=barrier[1], valid_until=expiry,
        )
        source_versions = {row.key.token: row.revision
                           for row in candidate.read_versions}
        unit = QualifiedExpressionUnitV2(
            "basis:c02-report", ClaimKind.REPORTED_CLAIM,
            candidate.source_excerpt, None,
            tuple(VersionedRef(ref, source_versions[ref])
                  for ref in candidate.lineage_source_refs),
            tuple(VersionedRef(row.key.token, row.revision)
                  for row in candidate.read_versions
                  if row.key.type_name == "memory.access"),
            tuple(VersionedRef(row.key.token, row.revision)
                  for row in candidate.read_versions
                  if row.key.type_name == "d06.source_correction_head.v1"),
            route.conversation_ref, "expression", candidate.valid_until,
            speaker_id=candidate.speaker_id,
            content_reality="external_report",
            qualification_digest=candidate.qualification_digest,
            occurred_at=candidate.occurred_at, learned_at=candidate.learned_at,
            source_kind=candidate.source_kind,
            assertion_status=candidate.assertion_status,
            d06_claim_kind=candidate.claim_kind,
            attribution_required=candidate.attribution_required,
            polarity_status=candidate.polarity_status,
            source_excerpt=candidate.source_excerpt,
            evidence_span=(candidate.evidence_span.start,
                           candidate.evidence_span.end),
        )
        plan_id = natural_plan_id_v2(namespace, c02_operation_id, source_ref)
        plan_key = natural_plan_key_v2(
            namespace, inputs.c02_receipt.activity_id, plan_id)
        plan = NaturalExpressionPlanV2(
            namespace, VersionedRef(plan_key.token, 1), scene, audience,
            ("reply",), ("paraphrase",), (), (unit,), expiry,
            inputs.c02_receipt.activity_id,
            post_c02_reply_operation_id(c02_operation_id, source_ref),
            natural_final_effect_id_v2(namespace, c02_operation_id, source_ref),
            route.scene_ref, route.conversation_ref,
        )
        reads = tuple(dict.fromkeys((
            *inputs.graph_snapshot.versions, *role_read.read_versions,
            binding.anchor_version, binding.binding_version,
            binding.arrival_event_version,
            binding.binding_evidence_event_version,
            *binding.binding_scan_versions,
        )))
        semantic = natural_route_semantic_digest_v2(binding)
        evidence = NaturalPlanPreparationEvidenceV2(
            c02_operation_id,
            VersionedRef(source_ref, inputs.source.source_revision),
            VersionedRef(inputs.attention.focus_version.key.token,
                         inputs.attention.focus_version.revision),
            VersionedRef(inputs.attention.ticket_version.key.token,
                         inputs.attention.ticket_version.revision),
            canonical_digest({
                "schema": "sylanne.natural-preparation-evidence.v2",
                "c02_receipt": inputs.c02_receipt.operation_digest,
                "route": semantic,
                "read_versions": sorted((row.key.token, row.revision)
                                        for row in reads),
                "qualification": candidate.qualification_digest,
            }), semantic, grant.lease_id, grant.version,
            canonical_digest(grant),
            tuple(sorted(workflow.quote_ceiling.items())),
            tuple(sorted(review.quote_ceiling.items())),
        )
        if frozen_original is None:
            plan_write, plan_reads = prepare_coordinator_natural_plan_write_v2(
                plan=plan, evidence=evidence, snapshot=snapshot,
                d06_candidates=(candidate,), access_epoch=barrier[0],
                deletion_epoch=barrier[1], now_utc=now_utc,
            )
        else:
            adopted, plan_reads = verify_current_natural_plan_v2(
                plan=plan, evidence=evidence, snapshot=snapshot,
                d06_candidates=(candidate,), access_epoch=barrier[0],
                deletion_epoch=barrier[1], now_utc=now_utc,
            )
            plan_write = GraphWrite(
                plan_key, snapshot.get(plan_key).value)
        from .model_broker.natural_reply_history_v3 import (
            FrozenNaturalReplyRequestV3, TEMPLATE_VERSION as V3_TEMPLATE_VERSION,
        )
        from .model_broker.natural_reply import FrozenNaturalReplyRequestV2
        from .model_broker.natural_reply_history_v4 import FrozenNaturalReplyRequestV4, TEMPLATE_VERSION as V4_TEMPLATE_VERSION
        installation = NaturalReplyInstallationV2(
            installed_bundle.installation_policy.installation_id,
            workflow.provider_config_digest, workflow.provider_id,
            workflow.model_id, workflow.max_output_tokens)
        if type(frozen_original) is FrozenNaturalReplyRequestV2:
            # Old paid originals retain their V2 bytes and question reference.
            frozen = freeze_natural_reply_request_v2(
                NaturalReplyInputV2(ContextReplyPartV1("question", evidence.source_ref,
                    VersionedRef(route.conversation_ref, audience.version), expiry, source.text),
                    plan, (), now_utc, expiry), installation)
        elif type(frozen_original) is FrozenNaturalReplyRequestV4 or (frozen_original is None and workflow.template_version == V4_TEMPLATE_VERSION):
            from .runtime.installed_d13_natural_frame_v4 import freeze_current_natural_frame_v4
            metadata, _ = self._v2_graph_stamp(namespace)
            from .runtime.d13_natural_installed_ports_v1 import build_current_natural_d13_ports_v1
            wire_port, paid_verifier = build_current_natural_d13_ports_v1(db, bundle=installed_bundle,
                resource_issuer=self.__d02_issuer, budget_issuer=self.__d11_issuer,
                c02_operation_id=c02_operation_id, original=frozen_original,
                max_slots=(self.__d13_precompression_policy.max_slots if self.__d13_precompression_policy is not None else 64))
            if wire_port is None:
                wire_port = self.__d13_natural_wire_port
            frozen, history_reads, history_decision = freeze_current_natural_frame_v4(
                db, namespace=namespace, plan=plan,
                question=ContextReplyPartV1("question", evidence.source_ref, audience, expiry, source.text),
                installation=installation, now_utc=now_utc, expires_at_utc=expiry,
                activation_generation=metadata.requirements.activation_generation,
                max_slots=(self.__d13_precompression_policy.max_slots if self.__d13_precompression_policy is not None else 64),
                original=frozen_original, installed_wire_port=wire_port, paid_verifier=paid_verifier,
                preflight_out=history_preflight_out, preflight=history_preflight)
            reads = tuple(dict.fromkeys((*reads, *history_reads)))
            if history_decision.activation_write is not None and history_decision_out is None:
                raise UnavailableGuard("D13 standby activation is only allowed with first natural job CAS")
            if history_decision_out is not None:
                history_decision_out.append((history_decision, wire_port))
        elif type(frozen_original) is FrozenNaturalReplyRequestV3 or (frozen_original is None and workflow.template_version == V3_TEMPLATE_VERSION):
            from .runtime.installed_d13_natural_frame_v3 import freeze_current_raw_natural_frame_v3
            metadata, _ = self._v2_graph_stamp(namespace)
            max_slots = (self.__d13_precompression_policy.max_slots
                         if self.__d13_precompression_policy is not None else 64)
            frozen, history_reads, _history_decision = freeze_current_raw_natural_frame_v3(
                db, namespace=namespace, plan=plan,
                question=ContextReplyPartV1("question", evidence.source_ref, audience, expiry, source.text),
                installation=installation, now_utc=now_utc, expires_at_utc=expiry,
                activation_generation=metadata.requirements.activation_generation,
                max_slots=max_slots, original=frozen_original)
            reads = tuple(dict.fromkeys((*reads, *history_reads)))
        elif frozen_original is None:
            raise UnavailableGuard("new foreground originals require installed natural V3/V4 workflow")
        else:
            raise UnavailableGuard("natural frozen original and installed workflow version differ")
        scoped = read_natural_scoped_query_proof_v2(
            db, natural_private_scope_from_binding_v2(binding, frozen),
            now_utc=now_utc)
        assert_original_scoped_d06_projection_v2(scoped, frozen)
        return (plan_write, plan_reads, frozen, reads, query,
                role_read.query_epoch, boundary_read.query_epoch,
                barrier, scoped, candidate, snapshot)

    def _commit_natural_generation_locked(
        self, namespace: NamespaceId, c02_operation_id: str,
        source_ref: str, installed_bundle, now_utc: float,
        metadata, epoch: NamespaceEpoch, *, history_preflight=None,
    ):
        """One held Authority write tx: adopted plan and original paid job."""
        from .domains.d08.natural_plan import decode_natural_plan_v2
        from .runtime.d11_types import job_graph_write, runtime_job_key
        from .runtime.natural_generation_issue_v2 import (
            issue_original_natural_generation_in_transaction_v2,
            save_original_scoped_query_proof_v2,
        )
        from .runtime.natural_reply_job_v2 import (
            natural_job_ids_v2, read_original_preparation,
        )
        from .runtime_contracts import QueryEpoch

        store = self.__store
        db = store._db
        if not store._lock._is_owned() or not db.in_transaction:
            raise UnavailableGuard("natural generation requires held write fence")
        if self._v2_graph_stamp(namespace) != (metadata, epoch):
            raise StaleRead("natural generation graph changed before adoption")
        history_decisions = []
        (plan_write, plan_reads, frozen, current_reads, _all_query,
         _role_query, _boundary_query, barrier, scoped, _candidate,
         _snapshot) = (
            self._prepare_natural_generation_scope_locked(
                namespace, c02_operation_id, source_ref, installed_bundle,
                now_utc, epoch, history_decision_out=history_decisions,
                original_deadline=(history_preflight.raw.input.plan.valid_until_utc if history_preflight is not None else None),
                history_preflight=history_preflight))
        decision, history_wire_port = history_decisions[0] if history_decisions else (None, None)
        activation_write = decision.activation_write if decision is not None else None
        activation_expected = decision.activation_expected if decision is not None else None
        if (activation_write is None) != (activation_expected is None):
            raise UnavailableGuard("D13 activation write and CAS must be paired")
        plan = decode_natural_plan_v2(plan_write.value)
        job_id = natural_job_ids_v2(
            namespace, c02_operation_id, "generation")[0]
        job_key = runtime_job_key(
            *namespace.as_tuple, "natural-generation-activity:" +
            canonical_digest({
                "schema": "sylanne.d09.natural-generation-identity.v2",
                "namespace": namespace,
                "c02_operation_id": c02_operation_id,
                "source_ref": source_ref,
            })[:48], job_id)
        original_reads = tuple(dict.fromkeys((
            *current_reads, GraphVersion(plan_write.key, 1),
            GraphVersion(job_key, 1),
        )))
        if activation_expected is not None:
            original_reads = tuple(GraphVersion(version.key, activation_expected.revision + 1)
                if version.key == activation_expected.key else version for version in original_reads)
        query_epochs = tuple(QueryEpoch(namespace, scope, epoch.revision + 1)
                             for scope in ("all", "d03.role_binding",
                                           "d05.boundary"))
        job, quote, reservation_digest, seal = (
            issue_original_natural_generation_in_transaction_v2(
                db, namespace=namespace, plan=plan, frozen=frozen,
                read_versions=original_reads, query_epochs=query_epochs,
                graph_epoch=epoch.revision + 1,
                access_epoch=barrier[0], deletion_epoch=barrier[1],
                installed_bundle=installed_bundle,
                d02_issuer=self.__d02_issuer,
                d11_issuer=self.__d11_issuer, now_utc=now_utc,
                history_decision=decision, history_wire_port=history_wire_port))
        saved_original = read_original_preparation(
            db, namespace, c02_operation_id, "generation")
        if saved_original is None or saved_original.seal != seal:
            raise UnavailableGuard("natural generation original seal differs")
        save_original_scoped_query_proof_v2(db, saved_original, scoped)
        job_write = job_graph_write(job)
        if job_write.key != job_key:
            raise UnavailableGuard("natural generation job graph identity differs")
        reconcile_runtime_write(db, job_write)
        pre_reads = tuple(dict.fromkeys((
            *plan_reads, *current_reads, GraphVersion(job_key, 0),
        )))
        if activation_write is not None:
            pre_reads = tuple(version for version in pre_reads if version.key != activation_expected.key) + (activation_expected,)
        event_digest = canonical_digest({
            "schema": "sylanne.natural-generation-adoption.v2",
            "plan": plan_write.value, "seal": asdict(seal),
        })
        candidate = GraphCandidate(
            Event(Scope(*namespace.as_tuple, job.activity_id),
                  job.operation_id, now_utc, "domain_bundle",
                  {"bundle_digest": event_digest}),
            pre_reads,
            (plan_write,
             GraphWrite(job_write.key, job_write.value, (plan_write.key,)),
             *((activation_write,) if activation_write is not None else ())),
            (epoch,),
        )
        receipt = GraphStore._graph_commit_in_transaction(
            store, candidate, _capability=self.__graph_capability)
        if receipt.status != "committed":
            raise EventConflict("natural plan and job graph adoption failed")
        store.cas_graph_recovery_metadata(
            metadata, metadata.requirements,
            _capability=self.__graph_capability)
        seq_row = db.execute(
            "SELECT last_seq FROM graph_bundle_sequence "
            "WHERE bot=? AND persona=?", namespace.as_tuple,
        ).fetchone()
        seq = (seq_row[0] if seq_row else 0) + 1
        db.execute(
            "INSERT INTO graph_bundle_sequence(bot,persona,last_seq) "
            "VALUES(?,?,?) ON CONFLICT(bot,persona) DO UPDATE SET "
            "last_seq=excluded.last_seq", namespace.as_tuple + (seq + 1,),
        )
        db.execute(
            "INSERT INTO graph_bundle_operations"
            "(bot,persona,operation_id,digest,activity_id,effect_id,"
            "commit_seq,receipt_json) VALUES(?,?,?,?,?,?,?,?)",
            namespace.as_tuple + (
                job.operation_id, event_digest, job.activity_id, None, seq,
                canonical_json({
                    "c02_operation_id": c02_operation_id,
                    "source_ref": source_ref,
                    "plan_ref": plan_write.key.token,
                    "job_ref": job_write.key.token,
                    "quote_id": quote.quote_id,
                    "reservation_digest": reservation_digest,
                    "seal_digest": canonical_digest(asdict(seal)),
                    "ledger_refs": [plan_write.key.token,
                                    job_write.key.token],
                    "outbox_refs": [],
                }),
            ),
        )
        db.execute(
            "INSERT INTO graph_bundle_operations"
            "(bot,persona,operation_id,digest,activity_id,effect_id,"
            "commit_seq,receipt_json) VALUES(?,?,?,?,?,?,?,?)",
            namespace.as_tuple + (
                seal.reservation_operation_id, reservation_digest,
                job.activity_id, None, seq + 1,
                canonical_json({
                    "original_operation_id": job.operation_id,
                    "quote_id": quote.quote_id,
                    "job_ref": job_write.key.token,
                    "reservation_digest": reservation_digest,
                    "ledger_refs": [job_write.key.token],
                    "outbox_refs": [],
                }),
            ),
        )
        saved = read_original_preparation(
            db, namespace, c02_operation_id, "generation")
        if saved is None or saved.seal != seal:
            raise UnavailableGuard("natural original could not be read back")
        return saved

    def _commit_natural_review_locked(
        self, namespace: NamespaceId, parent_original_id: str,
        installed_bundle, content, now_utc: float, metadata,
        epoch: NamespaceEpoch,
    ):
        """Freeze the paid review input and its own budget/job in one graph tx."""
        from .domains.d08.natural_plan import decode_natural_plan_v2
        from .model_broker.natural_review import (
            NaturalReviewInstallationV1, REVIEW_TEMPLATE_VERSION,
            freeze_natural_reply_review_v1,
        )
        from .runtime.d11_types import job_graph_write, runtime_job_key
        from .runtime.natural_generation_issue_v2 import (
            read_original_scoped_query_proof_v2,
        )
        from .runtime.natural_reply_job_v2 import (
            natural_job_ids_v2, read_original_preparation,
        )
        from .runtime.natural_review_issue_v2 import (
            issue_original_natural_review_in_transaction_v2,
            verify_current_generation_content_for_review_v2,
        )
        from .runtime_contracts import QueryEpoch

        store, db = self.__store, self.__store._db
        if not store._lock._is_owned() or not db.in_transaction:
            raise UnavailableGuard("natural review requires held write fence")
        if self._v2_graph_stamp(namespace) != (metadata, epoch):
            raise StaleRead("natural review graph changed before adoption")
        generation = read_original_preparation(
            db, namespace, parent_original_id, "generation")
        if generation is None or generation.state != "terminal":
            raise UnavailableGuard("natural generation is not terminal; HOLD")
        (plan_write, _plan_reads, frozen_generation, current_reads,
         _all_query, _role_query, _boundary_query, barrier, scoped,
         _candidate, _snapshot) = (
            self._prepare_natural_generation_scope_locked(
                namespace, parent_original_id, generation.seal.source_ref,
                installed_bundle, now_utc, epoch,
                original_deadline=generation.frozen.input.plan.valid_until_utc,
                        frozen_original=generation.frozen))
        if (frozen_generation.input.plan != generation.frozen.input.plan
                or read_original_scoped_query_proof_v2(db, generation) != scoped):
            raise UnavailableGuard("natural review original scope changed; HOLD")
        adopted = decode_natural_plan_v2(plan_write.value)
        payload = verify_current_generation_content_for_review_v2(
            db, generation=generation, content=content,
            scoped_proof=scoped, adopted_plan=adopted, now_utc=now_utc)
        workflow = installed_bundle.model_workflows.natural_review
        review_frozen = freeze_natural_reply_review_v1(
            generation.seal, payload, generation.frozen.input.plan.units,
            tuple(ref.ref for ref in generation.frozen.input.plan.promise_grants),
            REVIEW_TEMPLATE_VERSION,
            NaturalReviewInstallationV1(
                installed_bundle.installation_policy.installation_id,
                workflow.provider_id, workflow.provider_config_digest,
                workflow.model_id, workflow.max_output_tokens),
        )
        job_id = natural_job_ids_v2(
            namespace, parent_original_id, "review")[0]
        review_identity = canonical_digest({
            "schema": "sylanne.d09.natural-review-identity.v2",
            "namespace": namespace, "parent_original_id": parent_original_id,
            "generation_output_digest": review_frozen.generation_output_digest,
        })[:48]
        job_key = runtime_job_key(
            *namespace.as_tuple, "natural-review-activity:" + review_identity,
            job_id)
        reads_by_key = {row.key.token: row for row in (
            *content.current_read_versions, *current_reads)}
        if any(reads_by_key[row.key.token] != row for row in
               content.current_read_versions):
            raise UnavailableGuard("natural review read closure differs; HOLD")
        original_reads = tuple((*reads_by_key.values(), GraphVersion(job_key, 1)))
        query_epochs = tuple(QueryEpoch(namespace, scope, epoch.revision + 1)
                             for scope in ("all", "d03.role_binding",
                                           "d05.boundary"))
        job, quote, reservation_digest, seal = (
            issue_original_natural_review_in_transaction_v2(
                db, generation=generation, adopted_plan=adopted,
                frozen=review_frozen,
                read_versions=original_reads, query_epochs=query_epochs,
                graph_epoch=epoch.revision + 1, access_epoch=barrier[0],
                deletion_epoch=barrier[1], installed_bundle=installed_bundle,
                d02_issuer=self.__d02_issuer,
                d11_issuer=self.__d11_issuer, now_utc=now_utc))
        job_write = job_graph_write(job)
        if job_write.key != job_key:
            raise UnavailableGuard("natural review job identity differs; HOLD")
        reconcile_runtime_write(db, job_write)
        event_digest = canonical_digest({
            "schema": "sylanne.natural-review-preparation.v2",
            "generation_seal": asdict(generation.seal),
            "review_seal": asdict(seal),
            "current_scope_digest": content.current_scope_digest,
        })
        receipt = GraphStore._graph_commit_in_transaction(
            store, GraphCandidate(
                Event(Scope(*namespace.as_tuple, job.activity_id),
                      job.operation_id, now_utc, "domain_bundle",
                      {"bundle_digest": event_digest}),
                tuple((*reads_by_key.values(), GraphVersion(job_key, 0))),
                (GraphWrite(job_write.key, job_write.value,
                            (plan_write.key,)),), (epoch,)),
            _capability=self.__graph_capability)
        if receipt.status != "committed":
            raise EventConflict("natural review job graph adoption failed")
        store.cas_graph_recovery_metadata(
            metadata, metadata.requirements,
            _capability=self.__graph_capability)
        seq_row = db.execute(
            "SELECT last_seq FROM graph_bundle_sequence "
            "WHERE bot=? AND persona=?", namespace.as_tuple,
        ).fetchone()
        seq = (seq_row[0] if seq_row else 0) + 1
        db.execute(
            "INSERT INTO graph_bundle_sequence(bot,persona,last_seq) "
            "VALUES(?,?,?) ON CONFLICT(bot,persona) DO UPDATE SET "
            "last_seq=excluded.last_seq", namespace.as_tuple + (seq + 1,),
        )
        for operation_id, digest, commit_seq, value in (
            (job.operation_id, event_digest, seq, {
                "generation_original_operation_id":
                    generation.seal.original_operation_id,
                "review_job_ref": job_write.key.token,
                "review_quote_id": quote.quote_id,
                "review_seal_digest": canonical_digest(asdict(seal)),
                "current_scope_digest": content.current_scope_digest,
                "ledger_refs": [job_write.key.token], "outbox_refs": [],
            }),
            (seal.reservation_operation_id, reservation_digest, seq + 1, {
                "original_operation_id": job.operation_id,
                "quote_id": quote.quote_id,
                "job_ref": job_write.key.token,
                "reservation_digest": reservation_digest,
                "ledger_refs": [job_write.key.token], "outbox_refs": [],
            }),
        ):
            db.execute(
                "INSERT INTO graph_bundle_operations"
                "(bot,persona,operation_id,digest,activity_id,effect_id,"
                "commit_seq,receipt_json) VALUES(?,?,?,?,?,?,?,?)",
                namespace.as_tuple + (operation_id, digest,
                                      job.activity_id, None, commit_seq,
                                      canonical_json(value)),
            )
        saved = read_original_preparation(
            db, namespace, parent_original_id, "review")
        if saved is None or saved.seal != seal:
            raise UnavailableGuard("natural review original could not be read back")
        return saved

    def prepare_post_c02_natural_generation_v2(
        self, bootstrap: object, namespace: NamespaceId,
        c02_operation_id: str, source_ref: str, installed_bundle,
    ):
        """Adopt the first natural scope and original generation job together."""
        from .authority_service.v2_contract import FencePermitV2
        from .authority_service.contract import AuthorityUnavailable
        from .host.authority_profile import (
            AdminIngressClockPolicy, AdminInstallationBundle,
        )
        from .model_broker.natural_reply import TEMPLATE_VERSION
        from .model_broker.natural_reply_history_v3 import TEMPLATE_VERSION as V3_TEMPLATE_VERSION
        from .model_broker.natural_reply_history_v4 import TEMPLATE_VERSION as V4_TEMPLATE_VERSION
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.issuers import D02ResourceIssuer, D11BudgetJobIssuer
        from .runtime.natural_generation_issue_v2 import (
            install_attempt_schema,
        )
        from .runtime.natural_reply_job_v2 import (
            install_schema as install_natural_schema, natural_job_ids_v2,
            read_original_preparation,
        )
        from .runtime.reply_model_job import source_key_from_ref

        self._admin(bootstrap)
        store = self.__store
        port = self.__content_fence_v2
        if (not isinstance(store, ProductionGraphStore) or port is None
                or type(namespace) is not NamespaceId
                or type(installed_bundle) is not AdminInstallationBundle
                or type(self.__scene_clock_policy) is not AdminIngressClockPolicy
                or installed_bundle.ingress_clock != self.__scene_clock_policy
                or type(self.__d02_issuer) is not D02ResourceIssuer
                or type(self.__d11_issuer) is not D11BudgetJobIssuer
                or self.__d11_issuer.resource_issuer is not self.__d02_issuer
                or installed_bundle.installation_policy.namespace != namespace):
            raise UnavailableGuard("natural installed graph authorities unavailable")
        source_key_from_ref(source_ref, namespace)
        now = trusted_upper(port.read_ingress_clock(self.__scene_clock_policy))
        workflows = installed_bundle.model_workflows
        generation = getattr(workflows, "natural_generation", None)
        review = getattr(workflows, "natural_review", None)
        if (generation is None or review is None
                or generation.template_version not in {TEMPLATE_VERSION, V3_TEMPLATE_VERSION, V4_TEMPLATE_VERSION}):
            raise UnavailableGuard("natural paid workflows unavailable; HOLD")
        original_id = natural_job_ids_v2(
            namespace, c02_operation_id, "generation")[1]
        input_digest = canonical_digest({
            "schema": "sylanne.natural-generation-preparation.v2",
            "namespace": namespace, "c02_operation_id": c02_operation_id,
            "source_ref": source_ref,
            "installation_id": installed_bundle.installation_policy.installation_id,
            "generation": {
                "provider_id": generation.provider_id,
                "model_id": generation.model_id,
                "provider_config_digest": generation.provider_config_digest,
                "template_version": generation.template_version,
                "quote_ceiling": dict(generation.quote_ceiling),
            },
            "review": {
                "provider_id": review.provider_id,
                "model_id": review.model_id,
                "provider_config_digest": review.provider_config_digest,
                "template_version": review.template_version,
                "quote_ceiling": dict(review.quote_ceiling),
            },
        })
        with store._lock:
            db = store._db
            install_attempt_schema(db)
            install_natural_schema(db)
            db.execute("BEGIN")
            try:
                saved = read_original_preparation(
                    db, namespace, c02_operation_id, "generation")
                attempt = db.execute(
                    "SELECT input_digest,attempt_id,anchor_json,graph_revision,"
                    "graph_epoch,state FROM graph_natural_generation_attempts_v2 "
                    "WHERE bot=? AND persona=? AND original_operation_id=?",
                    namespace.as_tuple + (original_id,),
                ).fetchone()
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise
            metadata, epoch = self._v2_graph_stamp(namespace)
            provision_row = self._provision_row(db, namespace)
            provision = (self._decode_provision_receipt(provision_row)
                         if provision_row is not None else None)
        target = metadata.requirements
        if (target.namespace != namespace or provision is None
                or provision.generation != target.activation_generation
                or provision.installation_id
                   != installed_bundle.installation_policy.installation_id
                or provision.authority_id != target.authority_id
                or provision.authority_namespace != target.authority_namespace):
            raise UnavailableGuard("natural graph activation differs; HOLD")
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("natural Authority anchor differs; HOLD")
        if attempt is not None and attempt[0] != input_digest:
            raise EventConflict("natural original reused with another profile")
        if saved is not None:
            if attempt is None or attempt[5] != "committed":
                raise UnavailableGuard("natural original lacks write fence; HOLD")
            self._finish_committed_post_c02_reply_fence_v1(
                namespace, metadata, epoch, anchor, attempt[1], attempt[2],
                attempt[3], attempt[4], "finish_natural_generation")
            return saved
        ready = getattr(port, "natural_paid_consumer_ready_v2", None)
        try:
            consumer_ready = (callable(ready) and ready(
                namespace=namespace, template_version=generation.template_version) is True)
        except Exception:
            consumer_ready = False
        if not consumer_ready:
            raise UnavailableGuard("installed natural paid consumer unavailable; HOLD")
        if attempt is not None and attempt[5] == "committed":
            raise UnavailableGuard("committed natural original lacks job; HOLD")
        if attempt is not None and attempt[5] == "open":
            if (attempt[2] != canonical_json(asdict(anchor))
                    or (attempt[3], attempt[4])
                       != (metadata.graph_revision, epoch.revision)):
                raise UnavailableGuard("pending natural anchor changed; HOLD")
            attempt_id = attempt[1]
            was_open = True
        else:
            attempt_id = "natural-generation-write-" + secrets.token_hex(24)
            was_open = False
            with store._lock:
                db.execute("BEGIN IMMEDIATE")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise StaleRead("natural graph changed before intent")
                    db.execute(
                        "INSERT INTO graph_natural_generation_attempts_v2"
                        "(bot,persona,original_operation_id,input_digest,"
                        "attempt_id,anchor_json,graph_revision,graph_epoch,state) "
                        "VALUES(?,?,?,?,?,?,?,?, 'open') "
                        "ON CONFLICT(bot,persona,original_operation_id) DO UPDATE SET "
                        "attempt_id=excluded.attempt_id,"
                        "anchor_json=excluded.anchor_json,"
                        "graph_revision=excluded.graph_revision,"
                        "graph_epoch=excluded.graph_epoch,state='open' "
                        "WHERE graph_natural_generation_attempts_v2.state='closed' "
                        "AND graph_natural_generation_attempts_v2.input_digest="
                        "excluded.input_digest",
                        namespace.as_tuple + (original_id, input_digest,
                        attempt_id, canonical_json(asdict(anchor)),
                        metadata.graph_revision, epoch.revision),
                    )
                    db.execute("COMMIT")
                except BaseException:
                    db.execute("ROLLBACK")
                    raise
        if was_open:
            try:
                observed_permit, observed_state = port.get_fence_operation(
                    namespace=namespace,
                    authority_namespace=target.authority_namespace,
                    operation_id=attempt_id)
            except AuthorityUnavailable:
                observed_permit, observed_state = None, "absent"
        else:
            observed_permit, observed_state = None, "absent"
        if observed_state == "absent":
            permit = port.begin_fence(
                namespace=namespace,
                authority_namespace=target.authority_namespace,
                holder=self.__holder,
                generation=target.activation_generation,
                operation="write", operation_id=attempt_id,
                expected_anchor=anchor)
        elif observed_state == "active":
            permit = observed_permit
        else:
            raise UnavailableGuard("natural write attempt unresolved; HOLD")
        if (type(permit) is not FencePermitV2 or permit.operation != "write"
                or permit.operation_id != attempt_id
                or permit.holder != self.__holder
                or permit.pinned_anchor != anchor):
            raise UnavailableGuard("natural write permit differs; HOLD")
        scope = FenceScope(
            namespace, target.authority_namespace,
            target.activation_generation, "write", attempt_id, permit,
            anchor, epoch, metadata.graph_revision)
        if port.validate_fence(scope) != permit:
            raise UnavailableGuard("natural write fence stale; HOLD")
        try:
            counted_history = None
            if generation.template_version == V4_TEMPLATE_VERSION and installed_bundle.d13_wire_counter is not None:
                preflights = []
                with store._lock:
                    db.execute("BEGIN")
                    try:
                        if self._v2_graph_stamp(namespace) != (metadata, epoch):
                            raise StaleRead("D13 preflight graph changed")
                        self._prepare_natural_generation_scope_locked(namespace, c02_operation_id,
                            source_ref, installed_bundle, now, epoch, history_preflight_out=preflights)
                        db.commit()
                    except BaseException:
                        db.rollback()
                        raise
                if preflights:
                    if len(preflights) != 1:
                        raise UnavailableGuard("D13 foreground preflight must select one original pair")
                    from .runtime.d13_natural_counter_preflight_v1 import count_installed_d13_preflight_v1
                    counted_history = count_installed_d13_preflight_v1(db, graph_lock=store._lock,
                        bundle=installed_bundle, preflight=preflights[0])
                now = trusted_upper(port.read_ingress_clock(self.__scene_clock_policy))
                if port.validate_fence(scope) != permit:
                    raise UnavailableGuard("D13 counting outlived the original write fence")
            with store._lock:
                db.execute("BEGIN IMMEDIATE")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise StaleRead("natural graph changed before write")
                    if counted_history is not None:
                        from .runtime.d13_natural_counter_preflight_v1 import record_counted_d13_preflight_v1
                        record_counted_d13_preflight_v1(db, bundle=installed_bundle, counted=counted_history)
                    saved = self._commit_natural_generation_locked(
                        namespace, c02_operation_id, source_ref,
                        installed_bundle, now, metadata, epoch,
                        history_preflight=(None if counted_history is None else counted_history.preflight))
                    db.execute(
                        "UPDATE graph_natural_generation_attempts_v2 "
                        "SET state='committed' WHERE bot=? AND persona=? "
                        "AND original_operation_id=? AND attempt_id=?",
                        namespace.as_tuple + (original_id, attempt_id),
                    )
                    db.execute("COMMIT")
                except BaseException:
                    db.execute("ROLLBACK")
                    raise
        except BaseException:
            try:
                port.finish_fence(
                    scope, request_id="finish:" + attempt_id,
                    request_digest="sha256:" + canonical_digest({
                        "action": "abort_natural_generation",
                        "attempt_id": attempt_id,
                        "permit_token": permit.token,
                    }))
                with store._lock:
                    db.execute(
                        "UPDATE graph_natural_generation_attempts_v2 "
                        "SET state='closed' WHERE bot=? AND persona=? "
                        "AND original_operation_id=? AND attempt_id=? "
                        "AND state='open'",
                        namespace.as_tuple + (original_id, attempt_id),
                    )
            except Exception:
                pass
            raise
        if port.validate_fence(scope) != permit:
            raise UnavailableGuard("natural committed fence outcome unknown; HOLD")
        port.finish_fence(
            scope, request_id="finish:" + attempt_id,
            request_digest="sha256:" + canonical_digest({
                "action": "finish_natural_generation",
                "attempt_id": attempt_id,
                "permit_token": permit.token,
            }))
        return saved

    def prepare_post_c02_natural_review_v2(
        self, authority: AuthorityContext, lease: object,
        parent_original_id: str, installed_bundle,
    ):
        """Reserve an independent paid review from Authority's current text."""
        from .authority_service.v2_contract import FencePermitV2
        from .authority_service.contract import AuthorityUnavailable
        from .authority_service.v2_natural_generation_content_contract import (
            NaturalGenerationCurrentContentV2,
        )
        from .host.authority_profile import AdminInstallationBundle
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.natural_reply_job_v2 import read_original_preparation
        from .runtime.natural_review_issue_v2 import install_review_attempt_schema

        store, port, namespace = (
            self.__store, self.__content_fence_v2, authority.namespace)
        if (not isinstance(store, ProductionGraphStore) or port is None
                or self.__natural_generation_content_port is None
                or type(installed_bundle) is not AdminInstallationBundle
                or installed_bundle.installation_policy.namespace != namespace
                or self.__d02_issuer is None or self.__d11_issuer is None):
            raise UnavailableGuard("natural paid review authorities absent; HOLD")
        self._authorize(lease, authority, frozenset({"d11"}))
        if (authority.issuer_domain != "d11" or authority.purpose != "proposal"):
            raise AuthorityDenied("natural review authority differs")
        ready = getattr(port, "natural_review_paid_consumer_ready_v2", None)
        try:
            consumer_ready = (callable(ready) and ready(
                namespace=namespace,
                template_version=installed_bundle.model_workflows.
                    natural_review.template_version) is True)
        except Exception:
            consumer_ready = False
        if not consumer_ready:
            raise UnavailableGuard("installed natural review consumer unavailable; HOLD")
        now = trusted_upper(port.read_ingress_clock(self.__scene_clock_policy))
        with store._lock:
            db = store._db
            install_review_attempt_schema(db)
            db.execute("BEGIN")
            try:
                generation = read_original_preparation(
                    db, namespace, parent_original_id, "generation")
                saved = read_original_preparation(
                    db, namespace, parent_original_id, "review")
                attempt = db.execute(
                    "SELECT input_digest,attempt_id,anchor_json,"
                    "graph_revision,graph_epoch,state FROM "
                    "graph_natural_review_attempts_v2 WHERE bot=? AND "
                    "persona=? AND parent_original_id=?",
                    namespace.as_tuple + (parent_original_id,),
                ).fetchone()
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise
        if generation is None or generation.state != "terminal":
            raise UnavailableGuard("natural generation original is not terminal; HOLD")
        input_digest = canonical_digest({
            "schema": "sylanne.natural-review-preparation-input.v2",
            "generation_seal": asdict(generation.seal),
            "generation_output_digest": generation.terminal_output_digest,
            "review_workflow": {
                "work_kind": installed_bundle.model_workflows.natural_review.work_kind,
                "provider_id": installed_bundle.model_workflows.natural_review.provider_id,
                "model_id": installed_bundle.model_workflows.natural_review.model_id,
                "provider_config_ref": installed_bundle.model_workflows.natural_review.provider_config_ref,
                "provider_config_digest": installed_bundle.model_workflows.natural_review.provider_config_digest,
                "purpose": installed_bundle.model_workflows.natural_review.purpose,
                "audiences": installed_bundle.model_workflows.natural_review.audiences,
                "privacy_tier": installed_bundle.model_workflows.natural_review.privacy_tier,
                "template_version": installed_bundle.model_workflows.natural_review.template_version,
                "required_capabilities": installed_bundle.model_workflows.natural_review.required_capabilities,
                "timeout_seconds": installed_bundle.model_workflows.natural_review.timeout_seconds,
                "max_output_tokens": installed_bundle.model_workflows.natural_review.max_output_tokens,
                "quote_ceiling": dict(installed_bundle.model_workflows.natural_review.quote_ceiling),
            },
        })
        metadata, epoch = self._v2_graph_stamp(namespace)
        target = metadata.requirements
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("natural review Authority anchor differs; HOLD")
        if attempt is not None and attempt[0] != input_digest:
            raise EventConflict("natural review original reused with another profile")
        if saved is not None:
            if attempt is None or attempt[5] != "committed":
                raise UnavailableGuard("natural review original lacks write fence; HOLD")
            self._finish_committed_post_c02_reply_fence_v1(
                namespace, metadata, epoch, anchor, attempt[1], attempt[2],
                attempt[3], attempt[4], "finish_natural_review")
            return saved
        if attempt is not None and attempt[5] == "open":
            if (attempt[2] != canonical_json(asdict(anchor))
                    or attempt[3:5] !=
                       (metadata.graph_revision, epoch.revision)):
                raise UnavailableGuard("natural review open graph changed; HOLD")
            try:
                prior_permit, prior_state = port.get_fence_operation(
                    namespace=namespace,
                    authority_namespace=target.authority_namespace,
                    operation_id=attempt[1])
            except AuthorityUnavailable:
                prior_permit, prior_state = None, "absent"
            except Exception as exc:
                raise UnavailableGuard(
                    "natural review fence recovery unknown; HOLD") from exc
            if prior_state == "active":
                if (type(prior_permit) is not FencePermitV2
                        or prior_permit.operation != "write"
                        or prior_permit.operation_id != attempt[1]
                        or prior_permit.pinned_anchor != anchor):
                    raise UnavailableGuard("natural review prior permit differs; HOLD")
                prior_scope = FenceScope(
                    namespace, target.authority_namespace,
                    target.activation_generation, "write", attempt[1],
                    prior_permit, anchor, epoch, metadata.graph_revision)
                port.finish_fence(
                    prior_scope, request_id="abort:" + attempt[1],
                    request_digest="sha256:" + canonical_digest({
                        "action": "abort_natural_review",
                        "attempt_id": attempt[1],
                        "permit_token": prior_permit.token,
                    }))
                with store._lock:
                    db.execute("BEGIN IMMEDIATE")
                    try:
                        db.execute(
                            "UPDATE graph_natural_review_attempts_v2 "
                            "SET state='closed' WHERE bot=? AND persona=? "
                            "AND parent_original_id=? AND attempt_id=? "
                            "AND state='open'",
                            namespace.as_tuple +
                            (parent_original_id, attempt[1]),
                        )
                        db.execute("COMMIT")
                    except BaseException:
                        db.execute("ROLLBACK")
                        raise
                attempt = (*attempt[:5], "closed")
            elif prior_state != "absent":
                raise UnavailableGuard("natural review write outcome unresolved; HOLD")
        with store._lock:
            db.execute("BEGIN IMMEDIATE")
            try:
                row = db.execute(
                    "SELECT last_attempt FROM graph_natural_review_content_reads_v2 "
                    "WHERE bot=? AND persona=? AND parent_original_id=?",
                    namespace.as_tuple + (parent_original_id,),
                ).fetchone()
                content_attempt = 1 if row is None else row[0] + 1
                if content_attempt > 64:
                    raise UnavailableGuard("natural review content attempts exhausted; HOLD")
                db.execute(
                    "INSERT INTO graph_natural_review_content_reads_v2"
                    "(bot,persona,parent_original_id,last_attempt) VALUES(?,?,?,?) "
                    "ON CONFLICT(bot,persona,parent_original_id) DO UPDATE SET "
                    "last_attempt=excluded.last_attempt",
                    namespace.as_tuple + (parent_original_id, content_attempt),
                )
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise
        request = self.read_natural_generation_content_request_v2(
            authority, lease, parent_original_id, installed_bundle,
            attempt=content_attempt)
        content = self.__natural_generation_content_port(request, now_utc=now)
        if (type(content) is not NaturalGenerationCurrentContentV2
                or content.request != request):
            raise UnavailableGuard("trusted natural review text unavailable; HOLD")
        attempt_id = (attempt[1] if attempt is not None
                      and attempt[5] == "open" else
                      "natural-review-write-" + secrets.token_hex(24))
        with store._lock:
            db.execute("BEGIN IMMEDIATE")
            try:
                if self._v2_graph_stamp(namespace) != (metadata, epoch):
                    raise StaleRead("natural review graph changed before intent")
                if attempt is None or attempt[5] == "closed":
                    db.execute(
                    "INSERT INTO graph_natural_review_attempts_v2"
                    "(bot,persona,parent_original_id,input_digest,attempt_id,"
                    "anchor_json,graph_revision,graph_epoch,state) "
                    "VALUES(?,?,?,?,?,?,?,?,'open') "
                    "ON CONFLICT(bot,persona,parent_original_id) DO UPDATE SET "
                    "attempt_id=excluded.attempt_id,anchor_json=excluded.anchor_json,"
                    "graph_revision=excluded.graph_revision,"
                    "graph_epoch=excluded.graph_epoch,state='open' "
                    "WHERE graph_natural_review_attempts_v2.state='closed' "
                    "AND graph_natural_review_attempts_v2.input_digest="
                    "excluded.input_digest",
                    namespace.as_tuple + (parent_original_id, input_digest,
                    attempt_id, canonical_json(asdict(anchor)),
                    metadata.graph_revision, epoch.revision),
                    )
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise
        try:
            permit = port.begin_fence(
                namespace=namespace,
                authority_namespace=target.authority_namespace,
                holder=self.__holder,
                generation=target.activation_generation,
                operation="write", operation_id=attempt_id,
                expected_anchor=anchor, retain_on_unknown=True)
        except Exception as exc:
            raise UnavailableGuard("natural review write begin unknown; HOLD") from exc
        if (type(permit) is not FencePermitV2 or permit.operation != "write"
                or permit.operation_id != attempt_id
                or permit.holder != self.__holder
                or permit.pinned_anchor != anchor):
            raise UnavailableGuard("natural review write permit differs; HOLD")
        scope = FenceScope(
            namespace, target.authority_namespace,
            target.activation_generation, "write", attempt_id, permit,
            anchor, epoch, metadata.graph_revision)
        if port.validate_fence(scope) != permit:
            raise UnavailableGuard("natural review write fence stale; HOLD")
        try:
            with store._lock:
                db.execute("BEGIN IMMEDIATE")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise StaleRead("natural review graph changed before write")
                    saved = self._commit_natural_review_locked(
                        namespace, parent_original_id, installed_bundle,
                        content, now, metadata, epoch)
                    changed = db.execute(
                        "UPDATE graph_natural_review_attempts_v2 "
                        "SET state='committed' WHERE bot=? AND persona=? "
                        "AND parent_original_id=? AND attempt_id=? "
                        "AND state='open'",
                        namespace.as_tuple + (parent_original_id, attempt_id),
                    ).rowcount
                    if changed != 1:
                        raise EventConflict("natural review write attempt differs")
                    db.execute("COMMIT")
                except BaseException:
                    db.execute("ROLLBACK")
                    raise
        except BaseException:
            port.finish_fence(
                scope, request_id="abort:" + attempt_id,
                request_digest="sha256:" + canonical_digest({
                    "action": "abort_natural_review", "attempt_id": attempt_id,
                    "permit_token": permit.token,
                }))
            with store._lock:
                db.execute(
                    "UPDATE graph_natural_review_attempts_v2 SET state='closed' "
                    "WHERE bot=? AND persona=? AND parent_original_id=? "
                    "AND attempt_id=? AND state='open'",
                    namespace.as_tuple + (parent_original_id, attempt_id),
                )
            raise
        port.finish_fence(
            scope, request_id="finish:" + attempt_id,
            request_digest="sha256:" + canonical_digest({
                "action": "finish_natural_review", "attempt_id": attempt_id,
                "permit_token": permit.token,
            }))
        return saved

    def acquire_post_c02_natural_generation_v2(
        self, authority: AuthorityContext, lease: object,
        c02_operation_id: str, installed_bundle, *, lease_seconds: int,
    ):
        return self._acquire_post_c02_natural_stage_v2(
            authority, lease, c02_operation_id, installed_bundle,
            lease_seconds=lease_seconds, stage="generation")

    def acquire_post_c02_natural_review_v2(
        self, authority: AuthorityContext, lease: object,
        parent_original_id: str, installed_bundle, *, lease_seconds: int,
    ):
        return self._acquire_post_c02_natural_stage_v2(
            authority, lease, parent_original_id, installed_bundle,
            lease_seconds=lease_seconds, stage="review")

    def _acquire_post_c02_natural_stage_v2(
        self, authority: AuthorityContext, lease: object,
        c02_operation_id: str, installed_bundle, *,
        lease_seconds: int, stage: str,
    ):
        """Acquire one sealed natural paid call under the current graph fence."""
        from .authority_service.v2_contract import FencePermitV2
        from .host.authority_profile import AdminInstallationBundle
        from .model_broker.broker import ModelCallRequest
        from .runtime.natural_original_v3 import natural_generation_template_digest
        from .model_broker.natural_review import REVIEW_TEMPLATE_DIGEST
        from .runtime.d11_types import job_graph_write
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.natural_generation_issue_v2 import (
            install_attempt_schema, read_original_scoped_query_proof_v2,
        )
        from .runtime.natural_review_issue_v2 import install_review_attempt_schema
        from .runtime.natural_reply_job_v2 import (
            bind_original_call, read_original_call_binding,
            read_original_preparation,
        )
        from .runtime_contracts import (
            CommandEnvelope, OperationIdentity, QueryEpoch, RUNTIME_SCHEMA,
        )

        store, port, namespace = self.__store, self.__content_fence_v2, authority.namespace
        if (not isinstance(store, ProductionGraphStore) or port is None
                or type(installed_bundle) is not AdminInstallationBundle
                or installed_bundle.installation_policy.namespace != namespace
                or type(lease_seconds) is not int
                or not 1 <= lease_seconds <= 3600):
            raise UnavailableGuard("natural generation acquire authorities unavailable")
        self._authorize(lease, authority, frozenset({"d11"}))
        if stage not in {"generation", "review"}:
            raise UnavailableGuard("natural paid stage differs; HOLD")
        workflow = getattr(installed_bundle.model_workflows, "natural_" + stage)
        if (workflow is None or authority.issuer_domain != "d11"
                or authority.purpose != "proposal"
                or "activity" not in authority.owner_scope
                or authority.provider_policy_ref != workflow.provider_config_ref
                or authority.worker_fence is not None):
            raise AuthorityDenied("natural generation worker identity differs")
        ready = getattr(port, (
            "natural_paid_consumer_ready_v2" if stage == "generation"
            else "natural_review_paid_consumer_ready_v2"), None)
        if not callable(ready) or ready(
                namespace=namespace,
                template_version=workflow.template_version) is not True:
            raise UnavailableGuard("natural paid consumer unavailable; HOLD")
        with store._lock:
            db = store._db
            install_attempt_schema(db)
            install_review_attempt_schema(db)
            db.execute("BEGIN")
            try:
                saved = read_original_preparation(
                    db, namespace, c02_operation_id, stage)
                if saved is None:
                    raise UnavailableGuard("natural original paid stage absent")
                generation = (saved if stage == "generation" else
                    read_original_preparation(
                        db, namespace, c02_operation_id, "generation"))
                if generation is None or (stage == "review" and
                        generation.state != "terminal"):
                    raise UnavailableGuard("natural generation terminal absent; HOLD")
                job = get_job(db, saved.seal.job_id)
                acquire_table = ("graph_natural_generation_acquires_v2"
                                 if stage == "generation" else
                                 "graph_natural_review_acquires_v2")
                acquire_row = db.execute(
                    "SELECT request_digest,attempt_id,anchor_json,"
                    "graph_revision,graph_epoch,state "
                    f"FROM {acquire_table} "
                    "WHERE bot=? AND persona=? AND acquire_operation_id=?",
                    namespace.as_tuple + (saved.seal.acquire_operation_id,),
                ).fetchone()
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise
            metadata, epoch = self._v2_graph_stamp(namespace)
        seal = saved.seal
        if (authority.capability_ref != _operation_capability_ref(
                    namespace, authority.actor, "d11", frozenset({"d11"}),
                    authority.activation_generation, seal.acquire_operation_id)
                or authority.audience !=
                   (generation.frozen.input.plan.audience_id,)
                or seal.installation_id
                   != installed_bundle.installation_policy.installation_id
                or (job.operation_id, job.work_kind)
                   != (seal.original_operation_id, "natural_" + stage)
                or (workflow.provider_id, workflow.model_id,
                    workflow.provider_config_digest,
                    workflow.max_output_tokens)
                   != (saved.frozen.installation.provider_id,
                       saved.frozen.installation.model_id,
                       saved.frozen.installation.provider_config_digest,
                       saved.frozen.installation.max_output_tokens)):
            raise AuthorityDenied("natural original worker binding differs")
        target = metadata.requirements
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("natural acquire Authority anchor differs")
        if saved.state == "acquired":
            with store._lock:
                db.execute("BEGIN")
                try:
                    binding = read_original_call_binding(db, saved)
                    db.execute("COMMIT")
                except BaseException:
                    db.execute("ROLLBACK")
                    raise
            if (binding is None or acquire_row is None
                    or acquire_row[5] != "committed"
                    or job.phase != "running"
                    or job.lease_holder != authority.actor
                    or job.fence != binding.worker_fence):
                raise UnavailableGuard("natural acquired call differs; HOLD")
            self._finish_committed_post_c02_reply_fence_v1(
                namespace, metadata, epoch, anchor, acquire_row[1],
                acquire_row[2], acquire_row[3], acquire_row[4],
                "finish_reply_acquire")
            return job, binding.request
        if saved.state != "queued" or job.phase != "queued":
            raise UnavailableGuard("natural original job is not queued")
        reading = port.read_ingress_clock(self.__scene_clock_policy)
        now = trusted_upper(reading)
        request_digest = canonical_digest({
            "schema": "sylanne.natural-" + stage + "-acquire.v2",
            "seal": asdict(seal), "actor": authority.actor,
            "lease_seconds": lease_seconds, "expected_fence": job.fence,
        })
        if acquire_row is not None and acquire_row[0] != request_digest:
            raise EventConflict("natural acquire identity reused")
        if acquire_row is not None and acquire_row[5] == "open":
            if (acquire_row[2] != canonical_json(asdict(anchor))
                    or acquire_row[3:5]
                       != (metadata.graph_revision, epoch.revision)):
                raise UnavailableGuard("natural acquire attempt changed; HOLD")
            attempt_id = acquire_row[1]
        else:
            attempt_id = "natural-" + stage + "-acquire-" + secrets.token_hex(24)
            with store._lock:
                db.execute("BEGIN IMMEDIATE")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise StaleRead("natural graph changed before acquire intent")
                    db.execute(
                        f"INSERT INTO {acquire_table}"
                        "(bot,persona,acquire_operation_id,request_digest,"
                        "attempt_id,anchor_json,graph_revision,graph_epoch,state) "
                        "VALUES(?,?,?,?,?,?,?,?, 'open')",
                        namespace.as_tuple + (seal.acquire_operation_id,
                        request_digest, attempt_id,
                        canonical_json(asdict(anchor)),
                        metadata.graph_revision, epoch.revision),
                    )
                    db.execute("COMMIT")
                except BaseException:
                    db.execute("ROLLBACK")
                    raise
        try:
            permit, state = port.get_fence_operation(
                namespace=namespace,
                authority_namespace=target.authority_namespace,
                operation_id=attempt_id)
        except Exception:
            permit = port.begin_fence(
                namespace=namespace,
                authority_namespace=target.authority_namespace,
                holder=self.__holder,
                generation=target.activation_generation,
                operation="write", operation_id=attempt_id,
                expected_anchor=anchor, retain_on_unknown=True)
            state = "active"
        if (type(permit) is not FencePermitV2 or state != "active"
                or permit.operation != "write"
                or permit.operation_id != attempt_id
                or permit.holder != self.__holder
                or permit.pinned_anchor != anchor):
            raise UnavailableGuard("natural acquire write permit differs; HOLD")
        scope = FenceScope(
            namespace, target.authority_namespace,
            target.activation_generation, "write", attempt_id, permit,
            anchor, epoch, metadata.graph_revision)
        if port.validate_fence(scope) != permit:
            raise UnavailableGuard("natural acquire fence stale; HOLD")
        now_text = datetime.fromtimestamp(now, timezone.utc).isoformat().replace(
            "+00:00", "Z")
        with store._lock:
            db.execute("BEGIN IMMEDIATE")
            try:
                if self._v2_graph_stamp(namespace) != (metadata, epoch):
                    raise StaleRead("natural graph changed before acquire")
                current = read_original_preparation(
                    db, namespace, c02_operation_id, stage)
                if current != saved or get_job(db, job.job_id) != job:
                    raise UnavailableGuard("natural original job changed; HOLD")
                (plan_write, _plan_reads, _current_frozen, current_reads,
                 _query, _role_query, _boundary_query, barrier, scoped,
                 _candidate, _snapshot) = (
                    self._prepare_natural_generation_scope_locked(
                        namespace, c02_operation_id, generation.seal.source_ref,
                        installed_bundle, now, epoch,
                        original_deadline=generation.frozen.input.plan.valid_until_utc,
                        frozen_original=generation.frozen))
                if (_current_frozen.input.plan != generation.frozen.input.plan
                        or generation.frozen.input.plan.plan_ref.ref
                           != plan_write.key.token):
                    raise UnavailableGuard("natural original plan changed; HOLD")
                if read_original_scoped_query_proof_v2(db, generation) != scoped:
                    raise UnavailableGuard("natural original private scope changed; HOLD")
                if ((barrier[0], barrier[1])
                        != (saved.access_epoch, saved.deletion_epoch)
                        or now >= generation.frozen.input.expires_at_utc
                        or (stage == "review" and (
                            generation.state != "terminal"
                            or saved.seal.generation_original_operation_id
                               != generation.seal.original_operation_id
                            or saved.seal.generation_output_digest
                               != generation.terminal_output_digest))):
                    raise StaleRead("natural source barrier or deadline changed")
                quote_ref = job.operator_versions["resource_quote"]
                quote_id, quote_version = quote_ref.rsplit(":", 1)
                quote = self.__d02_issuer.original_signed_quote(
                    db, quote_id, int(quote_version))
                reservation = db.execute(
                    "SELECT state FROM runtime_budget_reservations "
                    "WHERE lease_id=? AND operation_id=?",
                    (seal.parent_budget_lease_id,
                     seal.reservation_operation_id),
                ).fetchone()
                if (reservation != ("reserved",)
                        or quote.operation_id != seal.reservation_operation_id
                        or get_budget_lease(db, job.budget_ref).state != "active"
                        or self.__d11_issuer.current_budget_grant(
                            db, job.budget_ref)
                           != installed_bundle.installation_policy.root_grant):
                    raise UnavailableGuard("natural original budget changed; HOLD")
                planned = plan_job_acquire(
                    job, authority.actor, now_utc=now_text,
                    lease_seconds=lease_seconds)
                acquired = acquire_job(
                    db, job.job_id, authority.actor, now_utc=now_text,
                    lease_seconds=lease_seconds)
                if acquired != planned:
                    raise UnavailableGuard("natural D11 acquire CAS differed")
                worker = replace(authority, worker_fence=acquired.fence)
                job_write = job_graph_write(acquired)
                job_atom = db.execute(
                    "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                    (job_write.key.token,),
                ).fetchone()
                if (job_atom is None or job_atom[2] != 1
                        or job_atom[0] != 1):
                    raise UnavailableGuard("natural graph job changed; HOLD")
                reads = tuple(dict.fromkeys((
                    *current_reads, GraphVersion(plan_write.key, 1),
                    GraphVersion(job_write.key, 2),
                )))
                guard = VersionGuard(
                    reads, tuple(QueryEpoch(namespace, scope,
                                            epoch.revision + 1)
                                 for scope in ("all", "d03.role_binding",
                                               "d05.boundary")),
                    barrier[0], barrier[1],
                    store._registry.catalogue_hash,
                    self._version(db, namespace, "scheme", "current"),
                    self._version(db, namespace, "operator", "current"),
                    self._version(db, namespace, "policy", "current"),
                    (), (), (),
                )
                source_row = db.execute(
                    "SELECT value FROM graph_atoms WHERE token=?",
                    (generation.seal.source_ref,),
                ).fetchone()
                if source_row is None:
                    raise UnavailableGuard("natural original source absent")
                record = SourceRecord.from_dict(json.loads(source_row[0]))
                qualification = SourceQualification(
                    (generation.seal.source_ref,), "reported", record.occurred_at,
                    record.recorded_at, "external_report", "qualified",
                    None, "not_applicable")
                identity = OperationIdentity(
                    job.activity_id, None, attempt_id, "natural_" + stage,
                    seal.acquire_operation_id,
                    canonical_digest({"input_refs": [generation.seal.source_ref]}))
                deadline = min(
                    datetime.fromisoformat(
                        acquired.lease_expires_utc.replace("Z", "+00:00")
                    ).timestamp(),
                    datetime.fromisoformat(
                        acquired.deadline_utc.replace("Z", "+00:00")
                    ).timestamp(),
                )
                envelope = CommandEnvelope(
                    RUNTIME_SCHEMA, identity, worker, guard, qualification,
                    (generation.seal.source_ref,), job.budget_ref, deadline,
                    reading.monotonic_after_seconds + (deadline - now),
                    "natural-" + stage + ":" + c02_operation_id,
                    (c02_operation_id, seal.original_operation_id),
                )
                call = ModelCallRequest(
                    envelope, seal.call_id, workflow.provider_id,
                    workflow.model_id,
                    frozenset(workflow.required_capabilities),
                    workflow.privacy_tier, (natural_generation_template_digest(saved.frozen) if stage == "generation"
                                            else REVIEW_TEMPLATE_DIGEST),
                    json.loads(saved.frozen.canonical_wire),
                    workflow.timeout_seconds, workflow.max_output_tokens)
                bind_original_call(db, saved, acquired, call)
                reconcile_runtime_write(db, job_write)
                graph_candidate = GraphCandidate(
                    Event(Scope(*namespace.as_tuple, job.activity_id),
                          seal.acquire_operation_id, now, "domain_bundle",
                          {"bundle_digest": request_digest}),
                    (GraphVersion(job_write.key, 1), *current_reads,
                     GraphVersion(plan_write.key, 1)),
                    (GraphWrite(job_write.key, job_write.value,
                                (plan_write.key,)),), (epoch,),
                )
                receipt = GraphStore._graph_commit_in_transaction(
                    store, graph_candidate,
                    _capability=self.__graph_capability)
                if receipt.status != "committed":
                    raise EventConflict("natural acquire graph CAS failed")
                store.cas_graph_recovery_metadata(
                    metadata, metadata.requirements,
                    _capability=self.__graph_capability)
                seq_row = db.execute(
                    "SELECT last_seq FROM graph_bundle_sequence "
                    "WHERE bot=? AND persona=?", namespace.as_tuple,
                ).fetchone()
                seq = (seq_row[0] if seq_row else 0) + 1
                db.execute(
                    "INSERT INTO graph_bundle_sequence(bot,persona,last_seq) "
                    "VALUES(?,?,?) ON CONFLICT(bot,persona) DO UPDATE SET "
                    "last_seq=excluded.last_seq",
                    namespace.as_tuple + (seq,),
                )
                db.execute(
                    "INSERT INTO graph_bundle_operations"
                    "(bot,persona,operation_id,digest,activity_id,effect_id,"
                    "commit_seq,receipt_json) VALUES(?,?,?,?,?,?,?,?)",
                    namespace.as_tuple + (
                        seal.acquire_operation_id, request_digest,
                        job.activity_id, None, seq,
                        canonical_json({
                            "c02_operation_id": c02_operation_id,
                            "plan_ref": plan_write.key.token,
                            "job_ref": job_write.key.token,
                            "call_id": seal.call_id,
                            "typed_request_digest": call.digest,
                            "ledger_refs": [job_write.key.token],
                            "outbox_refs": [],
                        }),
                    ),
                )
                db.execute(
                    f"UPDATE {acquire_table} "
                    "SET state='committed' WHERE bot=? AND persona=? "
                    "AND acquire_operation_id=? AND attempt_id=?",
                    namespace.as_tuple + (
                        seal.acquire_operation_id, attempt_id),
                )
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise
        if port.validate_fence(scope) != permit:
            raise UnavailableGuard("natural acquired fence outcome unknown; HOLD")
        port.finish_fence(
            scope, request_id="finish:" + attempt_id,
            request_digest="sha256:" + canonical_digest({
                "action": "finish_reply_acquire", "attempt_id": attempt_id,
                "permit_token": permit.token,
            }))
        return acquired, call

    def read_natural_model_egress_preparation_v2(
        self, authority: AuthorityContext, lease: object,
        parent_original_id: str, stage: str, installed_bundle,
    ):
        """Read an acquired original call with fresh natural source closure."""
        from .authority_service.v2_model_egress_contract import ModelEgressDraftV1
        from .host.authority_profile import AdminInstallationBundle
        from .runtime.d11_types import job_graph_write
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.natural_generation_issue_v2 import (
            read_original_scoped_query_proof_v2,
        )
        from .runtime.natural_reply_job_v2 import (
            read_original_call_binding, read_original_preparation,
        )
        from .runtime_contracts import QueryEpoch

        store, port, namespace = self.__store, self.__content_fence_v2, authority.namespace
        if (stage not in {"generation", "review"}
                or not isinstance(store, ProductionGraphStore)
                or port is None or type(installed_bundle) is not AdminInstallationBundle
                or installed_bundle.installation_policy.namespace != namespace):
            raise UnavailableGuard("natural paid stage is unavailable; HOLD")
        self._authorize(lease, authority, frozenset({"d11"}))
        now = trusted_upper(port.read_ingress_clock(self.__scene_clock_policy))

        def reader():
            db = store._db
            db.execute("BEGIN")
            try:
                metadata, epoch = self._v2_graph_stamp(namespace)
                saved = read_original_preparation(
                    db, namespace, parent_original_id, stage)
                if saved is None or saved.state != "acquired":
                    raise UnavailableGuard("natural original call not acquired; HOLD")
                generation = (saved if stage == "generation" else
                    read_original_preparation(
                        db, namespace, parent_original_id, "generation"))
                if generation is None or (stage == "review" and
                        generation.state != "terminal"):
                    raise UnavailableGuard("natural generation terminal absent; HOLD")
                seal = saved.seal
                binding = read_original_call_binding(db, saved)
                job = get_job(db, seal.job_id)
                if binding is None:
                    raise UnavailableGuard("natural typed call binding absent; HOLD")
                request = binding.request
                (plan_write, _plan_reads, _current_frozen, current_reads,
                 _all_query, _role_query, _boundary_query, barrier, scoped,
                 _candidate, _snapshot) = (
                    self._prepare_natural_generation_scope_locked(
                        namespace, parent_original_id,
                        generation.seal.source_ref,
                        installed_bundle, now, epoch,
                        original_deadline=generation.frozen.input.plan.valid_until_utc,
                        frozen_original=generation.frozen))
                if read_original_scoped_query_proof_v2(db, generation) != scoped:
                    raise UnavailableGuard("natural private route changed; HOLD")
                if _current_frozen.input.plan != generation.frozen.input.plan:
                    raise UnavailableGuard("natural adopted plan changed; HOLD")
                job_key = job_graph_write(job).key
                atom = db.execute(
                    "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                    (job_key.token,),
                ).fetchone()
                expected_reads = tuple(dict.fromkeys((
                    *current_reads, GraphVersion(plan_write.key, 1),
                    GraphVersion(job_key, 2),
                )))
                guard = request.envelope.version_guard
                if ((barrier[0], barrier[1])
                        != (saved.access_epoch, saved.deletion_epoch)
                        or now >= generation.frozen.input.expires_at_utc
                        or job.phase != "running"
                        or job.lease_holder != authority.actor
                        or job.fence != binding.worker_fence
                        or job.operation_id != seal.original_operation_id
                        or job.work_kind != "natural_" + stage
                        or job.cancel_epoch != 0 or job.result_ref is not None
                        or atom is None or atom[2] != 1 or atom[0] != 2
                        or json.loads(atom[1]) != job_graph_write(job).value
                        or request.envelope.authority != authority
                        or request.identity.operation_id
                           != seal.acquire_operation_id
                        or set(guard.read_versions) != set(expected_reads)
                        or tuple(item.scope_ref for item in guard.query_epochs)
                           != ("all", "d03.role_binding", "d05.boundary")
                        or any(item.namespace != namespace
                               or not saved.graph_epoch < item.revision
                                      <= epoch.revision
                               for item in guard.query_epochs)
                        or (guard.access_epoch, guard.delete_epoch) != barrier
                        or authority.audience != (
                            generation.frozen.input.plan.audience_id,)):
                    raise UnavailableGuard("natural current paid egress changed; HOLD")
                quote_ref = job.operator_versions["resource_quote"]
                quote_id, quote_version = quote_ref.rsplit(":", 1)
                quote = self.__d02_issuer.original_signed_quote(
                    db, quote_id, int(quote_version))
                reservation = db.execute(
                    "SELECT digest,ceiling_json,state FROM "
                    "runtime_budget_reservations WHERE lease_id=? "
                    "AND operation_id=?",
                    (seal.parent_budget_lease_id,
                     seal.reservation_operation_id),
                ).fetchone()
                if (reservation is None or reservation[1:] != (
                        canonical_json(dict(quote.ceiling)), "reserved")
                        or quote.operation_id != seal.reservation_operation_id
                        or get_budget_lease(db, job.budget_ref).state != "active"
                        or self.__d11_issuer.current_budget_grant(
                            db, job.budget_ref)
                           != installed_bundle.installation_policy.root_grant):
                    raise UnavailableGuard("natural current budget changed; HOLD")
                source_atom = db.execute(
                    "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                    (generation.seal.source_ref,),
                ).fetchone()
                access_key_value = access_key(
                    *namespace.as_tuple,
                    AtomKey.from_token(generation.seal.source_ref).owner.subject)
                access_atom = db.execute(
                    "SELECT revision,valid FROM graph_atoms WHERE token=?",
                    (access_key_value.token,),
                ).fetchone()
                if (source_atom is None or source_atom[2] != 1
                        or access_atom is None or access_atom[1] != 1):
                    raise UnavailableGuard("natural source or access absent; HOLD")
                record = SourceRecord.from_dict(json.loads(source_atom[1]))
                result = (saved, request, reservation[0], quote,
                          ((record.source_id, source_atom[0]),),
                          ((record.source_id, access_atom[0]),),
                          metadata, epoch, job)
                db.execute("COMMIT")
                return result
            except BaseException:
                db.execute("ROLLBACK")
                raise

        (prepared, anchor, metadata, epoch) = self._read_v2(
            authority, reader, return_recovery_context=True)
        saved, request, reservation_digest, quote, sources, accesses, _, _, job = prepared
        target = metadata.requirements
        draft = ModelEgressDraftV1(
            target.authority_id, target.authority_namespace, authority.actor,
            request.identity.operation_id, request.call_id, request.digest,
            job.job_id, job.fence, tuple(source_id for source_id, _ in sources),
            sources, accesses, saved.access_epoch, saved.deletion_epoch,
            epoch.revision, metadata.graph_revision,
            target.activation_generation, target.revocation_epoch,
            target.deletion_seq, target.execution_seq,
            job.budget_ref, saved.seal.reservation_operation_id,
            reservation_digest, tuple(sorted(quote.ceiling.items())),
            request.provider_id, request.model_id,
            saved.seal.provider_config_digest,
            request.max_output_tokens,
            acquire_operation_id=request.identity.operation_id,
            binding_digest=canonical_digest({
                "original_seal_digest": canonical_digest(asdict(saved.seal)),
                "model_call_request_digest": request.digest,
                "worker_fence": job.fence,
            }),
        )
        return request, draft, anchor

    def read_natural_generation_output_request_v2(
        self, authority: AuthorityContext, lease: object,
        parent_original_id: str, installed_bundle, *, attempt: int = 1,
    ):
        """Select the sealed paid generation identity without model content."""
        from .authority_service.v2_natural_generation_output_contract import (
            NaturalGenerationOutputReadRequestV2,
            natural_generation_output_attempt_id_v2,
        )
        from .host.authority_profile import AdminInstallationBundle
        from .runtime.model_cost_settlement import original_model_cost_operation_id_v1
        from .runtime.natural_reply_job_v2 import (
            read_original_call_binding, read_original_preparation,
        )

        store, namespace = self.__store, authority.namespace
        if (not isinstance(store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or type(installed_bundle) is not AdminInstallationBundle
                or installed_bundle.installation_policy.namespace != namespace
                or installed_bundle.model_workflows is None
                or installed_bundle.model_workflows.natural_generation is None):
            raise UnavailableGuard("installed natural generation result unavailable; HOLD")
        self._authorize(lease, authority, frozenset({"d11"}), owner_read=True)
        if authority.issuer_domain != "d11" or authority.purpose != "proposal":
            raise AuthorityDenied("natural generation result reader differs")

        def reader():
            db = store._db
            db.execute("BEGIN")
            try:
                saved = read_original_preparation(
                    db, namespace, parent_original_id, "generation")
                if saved is None or saved.state != "acquired":
                    raise UnavailableGuard("natural generation original not acquired; HOLD")
                seal = saved.seal
                binding = read_original_call_binding(db, saved)
                job = get_job(db, seal.job_id)
                cost_id = original_model_cost_operation_id_v1(
                    namespace, seal.call_id)
                cost = db.execute(
                    "SELECT receipt_json FROM graph_bundle_operations "
                    "WHERE bot=? AND persona=? AND operation_id=?",
                    namespace.as_tuple + (cost_id,),
                ).fetchone()
                cost_data = json.loads(cost[0]) if cost is not None else {}
                committed = cost_data.get("original_model_cost", {})
                if (binding is None or job.phase != "running"
                        or job.operation_id != seal.original_operation_id
                        or job.fence != binding.worker_fence
                        or binding.request.digest != saved.typed_request_digest
                        or authority.audience !=
                           (saved.frozen.input.plan.audience_id,)
                        or seal.installation_id !=
                           installed_bundle.installation_policy.installation_id
                        or committed.get("status") != "committed"
                        or committed.get("operation_id") != cost_id
                        or committed.get("call_id") != seal.call_id
                        or not cost_data.get("original_intent_digest")
                        or not cost_data.get("terminal_receipt_digest")):
                    raise UnavailableGuard("natural generation original cost differs; HOLD")
                metadata, _ = self._v2_graph_stamp(namespace)
                result = NaturalGenerationOutputReadRequestV2(
                    metadata.requirements.authority_id,
                    metadata.requirements.authority_namespace,
                    namespace, seal.c02_operation_id, seal.source_ref,
                    seal.installation_id, seal.job_id,
                    seal.original_operation_id, seal.acquire_operation_id,
                    seal.call_id, binding.request.digest,
                    natural_generation_output_attempt_id_v2(
                        seal.original_operation_id, attempt),
                )
                db.execute("COMMIT")
                return result
            except BaseException:
                db.execute("ROLLBACK")
                raise

        return self._read_v2(authority, reader)

    def read_natural_review_output_request_v2(
        self, authority: AuthorityContext, lease: object,
        parent_original_id: str, installed_bundle, *, attempt: int = 1,
    ):
        """Derive the review result identity solely from its paid original."""
        from .authority_service.v2_natural_review_output_contract import (
            NaturalReviewOutputReadRequestV2,
            natural_review_output_attempt_id_v2,
        )
        from .host.authority_profile import AdminInstallationBundle
        from .runtime.model_cost_settlement import original_model_cost_operation_id_v1
        from .runtime.natural_reply_job_v2 import (
            read_original_call_binding, read_original_preparation,
        )

        store, namespace = self.__store, authority.namespace
        if (not isinstance(store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or type(installed_bundle) is not AdminInstallationBundle
                or installed_bundle.installation_policy.namespace != namespace
                or installed_bundle.model_workflows.natural_review is None):
            raise UnavailableGuard("installed natural review result unavailable; HOLD")
        self._authorize(lease, authority, frozenset({"d11"}), owner_read=True)
        if authority.issuer_domain != "d11" or authority.purpose != "proposal":
            raise AuthorityDenied("natural review result reader differs")

        def reader():
            db = store._db
            db.execute("BEGIN")
            try:
                generation = read_original_preparation(
                    db, namespace, parent_original_id, "generation")
                saved = read_original_preparation(
                    db, namespace, parent_original_id, "review")
                if (generation is None or generation.state != "terminal"
                        or saved is None
                        or saved.state not in {"acquired", "terminal"}):
                    raise UnavailableGuard("natural paid review original absent; HOLD")
                seal = saved.seal
                binding = read_original_call_binding(db, saved)
                job = get_job(db, seal.job_id)
                cost_id = original_model_cost_operation_id_v1(namespace, seal.call_id)
                row = db.execute(
                    "SELECT receipt_json FROM graph_bundle_operations "
                    "WHERE bot=? AND persona=? AND operation_id=?",
                    namespace.as_tuple + (cost_id,),
                ).fetchone()
                cost_data = json.loads(row[0]) if row is not None else {}
                committed = cost_data.get("original_model_cost", {})
                if (binding is None or job.phase != (
                        "running" if saved.state == "acquired" else "completed")
                        or job.operation_id != seal.original_operation_id
                        or job.work_kind != "natural_review"
                        or job.fence != binding.worker_fence
                        or binding.request.digest != saved.typed_request_digest
                        or authority.audience !=
                           (generation.frozen.input.plan.audience_id,)
                        or seal.installation_id !=
                           installed_bundle.installation_policy.installation_id
                        or seal.generation_original_operation_id !=
                           generation.seal.original_operation_id
                        or seal.generation_call_id != generation.seal.call_id
                        or seal.generation_output_digest !=
                           generation.terminal_output_digest
                        or committed.get("status") != "committed"
                        or committed.get("operation_id") != cost_id
                        or committed.get("call_id") != seal.call_id
                        or not cost_data.get("original_intent_digest")
                        or not cost_data.get("terminal_receipt_digest")):
                    raise UnavailableGuard("natural review original cost differs; HOLD")
                metadata, _ = self._v2_graph_stamp(namespace)
                result = NaturalReviewOutputReadRequestV2(
                    metadata.requirements.authority_id,
                    metadata.requirements.authority_namespace,
                    namespace, parent_original_id,
                    seal.generation_original_operation_id,
                    seal.generation_call_id,
                    seal.generation_output_digest,
                    seal.installation_id, seal.job_id,
                    seal.original_operation_id, seal.acquire_operation_id,
                    seal.call_id, binding.request.digest,
                    natural_review_output_attempt_id_v2(
                        seal.original_operation_id, attempt),
                )
                db.execute("COMMIT")
                return result
            except BaseException:
                db.execute("ROLLBACK")
                raise

        return self._read_v2(authority, reader)

    def read_natural_paid_review_request_v2(
        self, authority: AuthorityContext, lease: object,
        parent_original_id: str, installed_bundle,
    ):
        """Reserve a fresh read of both original paid calls, without text.

        The nested original requests are identity projections. Authority owns
        the paid observations and independently reads the current graph; its
        previous content/output attempts are never reopened here.
        """
        from .authority_service.v2_natural_paid_review_contract import (
            NaturalPaidReviewCurrentReadRequestV2,
            natural_paid_review_attempt_id_v2,
        )
        from .runtime.natural_reply_job_v2 import read_original_preparation
        from .runtime.natural_review_issue_v2 import install_review_attempt_schema

        generation_request = self.read_natural_generation_content_request_v2(
            authority, lease, parent_original_id, installed_bundle)
        review_request = self.read_natural_review_output_request_v2(
            authority, lease, parent_original_id, installed_bundle)
        review_output = self.read_natural_review_terminal_receipt_v2(
            authority, lease, parent_original_id, installed_bundle)
        namespace = authority.namespace
        if (review_output.request.original_operation_id !=
                review_request.original_operation_id
                or review_output.request.call_id != review_request.call_id
                or review_output.request.generation_output_digest !=
                   generation_request.output_digest):
            raise UnavailableGuard("natural paid review originals differ; HOLD")
        store = self.__store
        with store._lock:
            db = store._db
            install_review_attempt_schema(db)
            db.execute("BEGIN IMMEDIATE")
            try:
                generation = read_original_preparation(
                    db, namespace, parent_original_id, "generation")
                review = read_original_preparation(
                    db, namespace, parent_original_id, "review")
                if (generation is None or review is None
                        or generation.state != "terminal"
                        or review.state != "terminal"
                        or generation.seal.original_operation_id !=
                           generation_request.original_operation_id
                        or review.seal.original_operation_id !=
                           review_request.original_operation_id
                        or generation.terminal_output_digest !=
                           generation_request.output_digest
                        or review.terminal_output_digest !=
                           review_output.output_digest
                        or review.terminal_receipt_digest !=
                           review_output.terminal_receipt_digest):
                    raise UnavailableGuard("natural paid review terminal changed; HOLD")
                original_id = review.seal.original_operation_id
                row = db.execute(
                    "SELECT last_attempt FROM graph_natural_paid_review_reads_v2 "
                    "WHERE bot=? AND persona=? AND original_operation_id=?",
                    namespace.as_tuple + (original_id,),
                ).fetchone()
                attempt = 1 if row is None else row[0] + 1
                if attempt > 64:
                    raise UnavailableGuard("natural paid review read exhausted; HOLD")
                db.execute(
                    "INSERT INTO graph_natural_paid_review_reads_v2"
                    "(bot,persona,original_operation_id,last_attempt) "
                    "VALUES(?,?,?,?) ON CONFLICT(bot,persona,original_operation_id) "
                    "DO UPDATE SET last_attempt=excluded.last_attempt",
                    namespace.as_tuple + (original_id, attempt),
                )
                result = NaturalPaidReviewCurrentReadRequestV2(
                    generation_request, review_request,
                    canonical_digest(asdict(review.seal)),
                    review_output.terminal_receipt_digest,
                    review_output.output_digest,
                    natural_paid_review_attempt_id_v2(original_id, attempt),
                )
                db.execute("COMMIT")
                return result
            except BaseException:
                db.execute("ROLLBACK")
                raise

    def _verify_natural_paid_review_current_locked(
        self, namespace: NamespaceId, parent_original_id: str,
        installed_bundle, paid, now_utc: float, epoch: NamespaceEpoch,
    ):
        """Recheck Authority's two paid outputs in this graph transaction.

        This produces D09 material only. It creates no action, grant, outbox,
        or send permission; the eventual final write fence must call it again.
        """
        from .authority_service.v2_natural_generation_content_contract import (
            natural_generation_current_scope_digest_v2,
        )
        from .authority_service.v2_natural_paid_review_contract import (
            NaturalPaidReviewCurrentReadV2,
            natural_paid_review_current_scope_digest_v2,
        )
        from .domains.d08.natural_plan import decode_natural_plan_v2
        from .domains.d09.natural_reply import (
            assess_untrusted_natural_review_v2,
            prepare_natural_final_action_candidate_v2,
            verify_current_qualified_natural_reply_v2,
        )
        from .runtime.d11_types import job_graph_write
        from .runtime.model_cost_settlement import original_model_cost_operation_id_v1
        from .runtime.natural_generation_issue_v2 import (
            read_original_scoped_query_proof_v2,
        )
        from .runtime.d12_current_d09_policy_v1 import (
            read_current_d09_expression_policy_v1,
        )
        from .runtime.natural_reply_job_v2 import read_original_preparation

        db = self.__store._db
        if (not self.__store._lock._is_owned() or not db.in_transaction
                or type(paid) is not NaturalPaidReviewCurrentReadV2
                or paid.request.namespace != namespace
                or paid.request.review_output_request.parent_original_id
                   != parent_original_id
                or paid.graph_epoch != epoch.revision
                or now_utc >= paid.expires_at_utc):
            raise UnavailableGuard("natural paid current read lacks graph fence; HOLD")
        generation = read_original_preparation(
            db, namespace, parent_original_id, "generation")
        review = read_original_preparation(
            db, namespace, parent_original_id, "review")
        if (generation is None or review is None
                or generation.state != "terminal" or review.state != "terminal"
                or paid.request.generation_content_request.original_operation_id
                   != generation.seal.original_operation_id
                or paid.request.review_output_request.original_operation_id
                   != review.seal.original_operation_id
                or paid.request.review_original_seal_digest !=
                   canonical_digest(asdict(review.seal))
                or (review.terminal_receipt_digest,
                    review.terminal_output_digest) != (
                    paid.request.review_terminal_receipt_digest,
                    paid.request.review_output_digest)
                or (generation.terminal_receipt_digest,
                    generation.terminal_output_digest) != (
                    paid.request.generation_content_request.terminal_receipt_digest,
                    paid.request.generation_content_request.output_digest)):
            raise UnavailableGuard("natural paid originals differ; HOLD")
        (plan_write, plan_reads, frozen, current_reads, _query,
         _role_query, _boundary_query, barrier, scoped, candidate,
         snapshot) = self._prepare_natural_generation_scope_locked(
            namespace, parent_original_id, generation.seal.source_ref,
            installed_bundle, now_utc, epoch,
            original_deadline=generation.frozen.input.plan.valid_until_utc,
                        frozen_original=generation.frozen)
        if (frozen.input.plan != generation.frozen.input.plan
                or read_original_scoped_query_proof_v2(db, generation) != scoped
                or (paid.access_epoch, paid.delete_epoch) != barrier):
            raise UnavailableGuard("natural paid current plan changed; HOLD")
        adopted = decode_natural_plan_v2(plan_write.value)
        if (review.seal.generation_output_digest !=
                generation.terminal_output_digest
                or review.seal.qualified_units_digest !=
                   adopted.qualified_units_digest):
            raise UnavailableGuard("natural paid review basis changed; HOLD")
        paid_versions = {item.key.token: item
                         for item in paid.current_read_versions}
        for item in paid.current_read_versions:
            row = db.execute(
                "SELECT revision,valid FROM graph_atoms WHERE token=?",
                (item.key.token,),
            ).fetchone()
            if ((item.revision == 0 and row is not None)
                    or (item.revision > 0 and row != (item.revision, 1))):
                raise UnavailableGuard("natural paid graph read changed; HOLD")
        required = (*plan_reads, *candidate.read_versions,
                    GraphVersion(plan_write.key, frozen.input.plan.plan_ref.version))
        if any(paid_versions.get(item.key.token) != item for item in required):
            raise UnavailableGuard("natural qualified read closure differs; HOLD")
        review_job = get_job(db, review.seal.job_id)
        review_job_key = job_graph_write(review_job).key
        cost_id = original_model_cost_operation_id_v1(
            namespace, review.seal.call_id)
        cost_row = db.execute(
            "SELECT receipt_json FROM graph_bundle_operations WHERE bot=? "
            "AND persona=? AND operation_id=?",
            namespace.as_tuple + (cost_id,),
        ).fetchone()
        cost_data = json.loads(cost_row[0]) if cost_row is not None else {}
        cost_ref = cost_data.get("original_model_cost", {}).get("cost_ref")
        if (review_job.phase != "completed" or cost_ref is None
                or review_job_key.token not in paid_versions
                or cost_ref not in paid_versions):
            raise UnavailableGuard("natural paid review graph cost differs; HOLD")
        generation_versions = tuple(item for item in paid.current_read_versions
                                    if item.key.token not in {
                                        review_job_key.token, cost_ref})
        generation_scope = natural_generation_current_scope_digest_v2(
            original_seal_digest=canonical_digest(asdict(generation.seal)),
            scoped_proof_digest=scoped.semantic_digest,
            adopted_plan_digest=canonical_digest(asdict(adopted)),
            read_versions=generation_versions,
            graph_epoch=epoch.revision, access_epoch=barrier[0],
            delete_epoch=barrier[1],
            scene_id=frozen.input.plan.scene_id,
            audience_id=frozen.input.plan.audience_id)
        scope = natural_paid_review_current_scope_digest_v2(
            generation_scope_digest=generation_scope,
            review_seal_digest=canonical_digest(asdict(review.seal)),
            review_terminal_receipt_digest=review.terminal_receipt_digest,
            read_versions=paid.current_read_versions,
            graph_epoch=epoch.revision, access_epoch=barrier[0],
            delete_epoch=barrier[1])
        if scope != paid.current_scope_digest:
            raise UnavailableGuard("natural paid current scope differs; HOLD")
        expression_policy = read_current_d09_expression_policy_v1(db, namespace)
        mechanical = verify_current_qualified_natural_reply_v2(
            paid.generation_output, plan=frozen.input.plan,
            current_snapshot=snapshot, d06_candidates=(candidate,),
            current_reads=paid.current_read_versions,
            access_epoch=barrier[0], deletion_epoch=barrier[1],
            now_utc=now_utc, expression_policy=expression_policy.policy)
        review_candidate = assess_untrusted_natural_review_v2(
            mechanical, review.frozen, paid.parsed_review)

        class TrustedPaidRead:
            def verify_current_paid_review_v2(
                    self, receipt, *, plan, adopted, generation_output,
                    current_reads, now_utc):
                return (receipt == paid.paid_receipt
                        and current_reads == paid.current_read_versions
                        and generation_output == paid.generation_output
                        and now_utc < paid.expires_at_utc)

        final = prepare_natural_final_action_candidate_v2(
            plan=frozen.input.plan, adopted=adopted,
            generation_output=paid.generation_output,
            review=review_candidate, paid_receipt=paid.paid_receipt,
            current_snapshot=snapshot, d06_candidates=(candidate,),
            current_reads=paid.current_read_versions,
            access_epoch=barrier[0], deletion_epoch=barrier[1],
            now_utc=now_utc, paid_verifier=TrustedPaidRead(),
            expression_policy=expression_policy.policy)
        if (final.status != "candidate_hold_w01_final_admission"
                or final.material is None):
            raise UnavailableGuard("natural final D09 qualification unavailable; HOLD")
        # Authority attests the paid source/social closure. W01 separately
        # authenticates the active D09 head in this same graph transaction and
        # binds it to the committed batch, so P2 can reject a later policy edit.
        head_version = expression_policy.active_head_ref
        current = {item.key: item for item in final.material.current_reads}
        if head_version.key in current and current[head_version.key] != head_version:
            raise UnavailableGuard("natural expression policy head differs; HOLD")
        current[head_version.key] = head_version
        reads = tuple(current[key] for key in sorted(
            current, key=lambda item: item.token))
        return replace(final, material=replace(final.material, current_reads=reads))

    def read_current_natural_final_candidate_v2(
        self, authority: AuthorityContext, lease: object,
        parent_original_id: str, installed_bundle,
    ):
        """Read a current D09 candidate from both observed paid originals.

        This remains a non-sending HOLD. Final action/check/grant/admission
        adoption requires a separate Authority write fence and fresh recheck.
        """
        from .host.authority_profile import AdminInstallationBundle
        from .runtime.first_ingress_v2 import trusted_upper

        port = self.__natural_paid_review_current_port
        if (not callable(port) or self.__content_fence_v2 is None
                or type(installed_bundle) is not AdminInstallationBundle
                or installed_bundle.installation_policy.namespace !=
                   authority.namespace):
            raise UnavailableGuard("installed natural paid review reader absent; HOLD")
        self._authorize(lease, authority, frozenset({"d11"}), owner_read=True)
        if authority.issuer_domain != "d11" or authority.purpose != "proposal":
            raise AuthorityDenied("natural final paid reader differs")
        request = self.read_natural_paid_review_request_v2(
            authority, lease, parent_original_id, installed_bundle)
        now = trusted_upper(self.__content_fence_v2.read_ingress_clock(
            self.__scene_clock_policy))
        paid = port(request, now_utc=now)

        def reader():
            db = self.__store._db
            db.execute("BEGIN")
            try:
                _metadata, epoch = self._v2_graph_stamp(authority.namespace)
                if paid.request != request:
                    raise UnavailableGuard("natural paid current response differs; HOLD")
                result = self._verify_natural_paid_review_current_locked(
                    authority.namespace, parent_original_id,
                    installed_bundle, paid, now, epoch)
                db.execute("COMMIT")
                return result
            except BaseException:
                db.execute("ROLLBACK")
                raise

        return self._read_v2(authority, reader)

    def read_natural_original_progress_v2(
            self, authority: AuthorityContext, lease: object,
            parent_original_id: str, installed_bundle) -> NaturalOriginalProgressV2:
        """Read content-free durable generation/review/final progress."""
        from .host.authority_profile import AdminInstallationBundle
        from .runtime.natural_reply_job_v2 import read_original_preparation

        self._authorize(lease, authority, frozenset({"d11"}), owner_read=True)
        if (type(parent_original_id) is not str or not parent_original_id
                or type(installed_bundle) is not AdminInstallationBundle
                or installed_bundle.installation_policy.namespace
                   != authority.namespace):
            raise UnavailableGuard("natural original progress identity differs; HOLD")

        def reader():
            db = self.__store._db
            namespace = authority.namespace
            db.execute("BEGIN")
            try:
                metadata, epoch = self._v2_graph_stamp(namespace)
                stages = tuple(read_original_preparation(
                    db, namespace, parent_original_id, stage)
                    for stage in ("generation", "review"))

                def status(saved):
                    if saved is None:
                        return None
                    seal = saved.seal
                    return NaturalOriginalStageStatusV2(
                        saved.stage, saved.state, seal.job_id,
                        seal.original_operation_id,
                        seal.acquire_operation_id, seal.call_id,
                        saved.typed_request_digest,
                        saved.terminal_receipt_digest,
                        saved.terminal_output_digest)

                generation, review = stages
                if generation is not None and generation.seal.installation_id != (
                        installed_bundle.installation_policy.installation_id):
                    raise UnavailableGuard(
                        "natural progress installation differs; HOLD")
                if review is not None and review.seal.installation_id != (
                        installed_bundle.installation_policy.installation_id):
                    raise UnavailableGuard(
                        "natural review installation differs; HOLD")
                final_id = (generation.frozen.input.plan.final_operation_id
                            if generation is not None else None)
                if final_id is not None:
                    committed = self._get_operation_locked(namespace, final_id)
                    if committed is None:
                        final_id = None
                    elif self._get_natural_dispatch_candidate_evidence_locked(
                            namespace, final_id) is None:
                        raise UnavailableGuard(
                            "natural final committed identity differs; HOLD")
                result = NaturalOriginalProgressV2(
                    namespace, parent_original_id, status(generation),
                    status(review), final_id,
                    metadata.graph_revision, epoch.revision)
                db.execute("COMMIT")
                return result
            except BaseException:
                db.execute("ROLLBACK")
                raise

        return self._read_v2(authority, reader)

    def read_natural_original_stage_preparation_v2(
            self, authority: AuthorityContext, lease: object,
            parent_original_id: str, stage: str, installed_bundle):
        """Return one unchanged original sealed request to the installed driver.

        Its frozen text is historical model input, never a current-content or
        dispatch grant. Consumers must still use the current Authority ports.
        """
        from .host.authority_profile import AdminInstallationBundle
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.natural_generation_issue_v2 import (
            read_original_scoped_query_proof_v2,
        )
        from .runtime.natural_reply_job_v2 import read_original_preparation
        from .runtime.natural_scoped_query_proof_v2 import (
            assert_natural_scoped_query_current_v2,
        )

        self._authorize(lease, authority, frozenset({"d11"}), owner_read=True)
        if (stage not in {"generation", "review"}
                or type(parent_original_id) is not str or not parent_original_id
                or type(installed_bundle) is not AdminInstallationBundle
                or installed_bundle.installation_policy.namespace
                   != authority.namespace):
            raise UnavailableGuard("natural original stage identity differs; HOLD")
        now_utc = trusted_upper(self.__content_fence_v2.read_ingress_clock(
            self.__scene_clock_policy))

        def reader():
            db = self.__store._db
            db.execute("BEGIN")
            try:
                saved = read_original_preparation(
                    db, authority.namespace, parent_original_id, stage)
                if saved is not None and saved.seal.installation_id != (
                        installed_bundle.installation_policy.installation_id):
                    raise UnavailableGuard(
                        "natural stage installation differs; HOLD")
                if saved is not None:
                    generation = (saved if stage == "generation" else
                                  read_original_preparation(
                                      db, authority.namespace,
                                      parent_original_id, "generation"))
                    assert_natural_scoped_query_current_v2(
                        db, read_original_scoped_query_proof_v2(db, generation),
                        now_utc=now_utc)
                db.execute("COMMIT")
                return saved
            except BaseException:
                db.execute("ROLLBACK")
                raise

        return self._read_v2(authority, reader)

    def discover_pending_post_c02_natural_stages_v2(
            self, authority: AuthorityContext, lease: object, *,
            after: str | None = None, limit: int = 32,
            installed_bundle) -> NaturalPendingOriginalPageV2:
        """Page unfinished natural original identities for restart scheduling."""
        from .host.authority_profile import AdminInstallationBundle
        from .runtime.natural_reply_job_v2 import read_original_preparation

        self._authorize(lease, authority, frozenset({"d11"}), owner_read=True)
        if (after is not None and (type(after) is not str or not after)
                or type(limit) is not int or not 1 <= limit <= 64
                or type(installed_bundle) is not AdminInstallationBundle
                or installed_bundle.installation_policy.namespace
                   != authority.namespace):
            raise ValueError("invalid natural original discovery page")

        def reader():
            namespace = authority.namespace
            db = self.__store._db
            db.execute("BEGIN")
            try:
                metadata, epoch = self._v2_graph_stamp(namespace)
                table = db.execute(
                    "SELECT 1 FROM sqlite_master WHERE type='table' AND "
                    "name='graph_natural_generation_preparations_v2'"
                ).fetchone()
                if table is None:
                    result = NaturalPendingOriginalPageV2(
                        namespace, (), None, metadata.graph_revision,
                        epoch.revision)
                    db.execute("COMMIT")
                    return result
                rows = db.execute(
                    "SELECT g.parent_original_id,g.state,r.state FROM "
                    "graph_natural_generation_preparations_v2 g LEFT JOIN "
                    "graph_natural_review_preparations_v2 r ON "
                    "r.bot=g.bot AND r.persona=g.persona AND "
                    "r.parent_original_id=g.parent_original_id WHERE "
                    "g.bot=? AND g.persona=? AND g.parent_original_id>? "
                    "AND NOT EXISTS (SELECT 1 FROM graph_bundle_operations o "
                    "WHERE o.bot=g.bot AND o.persona=g.persona AND "
                    "o.operation_id=json_extract(g.frozen_json,"
                    "'$.input.plan.final_operation_id')) "
                    "ORDER BY g.parent_original_id LIMIT ?",
                    namespace.as_tuple + (after or "", limit + 1),
                ).fetchall()
                items = []
                for parent_id, gen_state, review_state in rows[:limit]:
                    generation = read_original_preparation(
                        db, namespace, parent_id, "generation")
                    review = read_original_preparation(
                        db, namespace, parent_id, "review")
                    if (generation is None or generation.state != gen_state
                            or generation.seal.installation_id !=
                            installed_bundle.installation_policy.installation_id
                            or (review.state if review is not None else None)
                               != review_state):
                        raise UnavailableGuard(
                            "natural pending original differs; HOLD")
                    items.append(NaturalPendingOriginalItemV2(
                        parent_id, generation.seal.source_ref,
                        gen_state, review_state))
                result = NaturalPendingOriginalPageV2(
                    namespace, tuple(items),
                    rows[limit - 1][0] if len(rows) > limit else None,
                    metadata.graph_revision, epoch.revision)
                db.execute("COMMIT")
                return result
            except BaseException:
                db.execute("ROLLBACK")
                raise

        return self._read_v2(authority, reader)

    def commit_post_c02_natural_final_v2(
            self, authority: AuthorityContext, lease: object,
            parent_original_id: str, installed_bundle) -> CommitReceipt:
        """Commit the reviewed natural reply and its dispatch admission once.

        Both paid outputs are read through the installed Authority port.  The
        graph write, D11 job/outbox, five current checks and admission share
        one SQLite transaction under the same Authority write permit.
        """
        from .authority_service.v2_contract import (
            AuthorityCurrentEffectSnapshotV2, FencePermitV2,
            canonical_digest as authority_canonical_digest, to_wire,
        )
        from .authority_service.v2_execution_bridge import CurrentEffectReadV2
        from .domains.d08.natural_plan import decode_natural_plan_v2
        from .host.authority_profile import AdminInstallationBundle
        from .host.v2_fence_port import VerifiedIngressClockV2
        from .runtime.dispatch_admission import insert_admission
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.natural_final_admission_v2 import (
            prepare_natural_final_bundle_v2,
        )
        from .runtime.natural_dispatch_admission_v2 import (
            issue_natural_dispatch_admission_v2,
        )
        from .runtime.natural_generation_issue_v2 import (
            read_original_scoped_query_proof_v2,
        )
        from .runtime.natural_reply_job_v2 import (
            read_original_call_binding, read_original_preparation,
        )
        from .runtime.d12_current_d09_policy_v1 import (
            read_current_d09_expression_policy_v1,
        )
        from .runtime.post_c02_reply_bundle_v2 import (
            post_c02_dispatch_runtime_refs_v2,
        )
        from .runtime_contracts import OperationIdentity, VersionedRef

        self._authorize(lease, authority, frozenset({"d08", "d09", "d11"}))
        store, port = self.__store, self.__content_fence_v2
        paid_port = self.__natural_paid_review_current_port
        if (not isinstance(store, ProductionGraphStore) or port is None
                or not callable(paid_port)
                or type(installed_bundle) is not AdminInstallationBundle
                or installed_bundle.installation_policy.namespace != authority.namespace
                or authority.issuer_domain != "d11"
                or authority.purpose != "expression"
                or type(parent_original_id) is not str or not parent_original_id):
            raise UnavailableGuard("natural final installation is unavailable; HOLD")
        namespace = authority.namespace
        recovered = self._recover_committed_natural_final_v2(
            authority, parent_original_id, installed_bundle)
        if recovered is not None:
            return recovered
        proposal_authority = replace(authority, purpose="proposal")
        paid_request = self.read_natural_paid_review_request_v2(
            proposal_authority, lease, parent_original_id, installed_bundle)
        clock = port.read_ingress_clock(self.__dispatch_clock_policy)
        if type(clock) is not VerifiedIngressClockV2:
            raise UnavailableGuard("natural final paired clock is absent; HOLD")
        now = trusted_upper(clock)
        paid = paid_port(paid_request, now_utc=now)
        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
            db = store._db
            db.execute("BEGIN")
            try:
                if paid.request != paid_request:
                    raise UnavailableGuard("natural paid response differs; HOLD")
                final = self._verify_natural_paid_review_current_locked(
                    namespace, parent_original_id, installed_bundle, paid,
                    now, epoch)
                material = final.material
                if material is None:
                    raise UnavailableGuard("natural final material is absent; HOLD")
                operation_id = material.final_operation_id
                previous = self._get_operation_fenced(authority, operation_id,
                                                      v2=True)
                if previous is not None:
                    raise UnavailableGuard(
                        "natural final committed during paid read; retry recovery")
                generation = read_original_preparation(
                    db, namespace, parent_original_id, "generation")
                if generation is None or generation.state != "terminal":
                    raise UnavailableGuard("natural generation original is absent; HOLD")
                call = read_original_call_binding(db, generation)
                if call is None:
                    raise UnavailableGuard("natural generation call is absent; HOLD")
                scoped = read_original_scoped_query_proof_v2(db, generation)
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise
        target = metadata.requirements
        anchor = port.current_anchor(
            namespace=namespace,
            authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("natural final Authority anchor differs; HOLD")
        attempt_id = "natural-final:" + canonical_digest({
            "namespace": namespace.as_tuple, "operation_id": operation_id,
        })[:48]
        try:
            permit, state = port.get_fence_operation(
                namespace=namespace,
                authority_namespace=target.authority_namespace,
                operation_id=attempt_id)
        except Exception:
            permit = port.begin_fence(
                namespace=namespace,
                authority_namespace=target.authority_namespace,
                holder=self.__holder,
                generation=target.activation_generation,
                operation="write", operation_id=attempt_id,
                expected_anchor=anchor, retain_on_unknown=True)
            state = "active"
        if (type(permit) is not FencePermitV2 or state != "active"
                or permit.pinned_anchor != anchor
                or permit.operation_id != attempt_id
                or permit.holder != self.__holder):
            raise UnavailableGuard("natural final write permit differs; HOLD")
        scope = FenceScope(
            namespace, target.authority_namespace,
            target.activation_generation, "write", attempt_id,
            permit, anchor, epoch, metadata.graph_revision)
        if port.validate_fence(scope) != permit:
            raise UnavailableGuard("natural final write fence changed; HOLD")
        owner_guard, owner_permit = port.get_current_owner_guard_for_fence(
            namespace=namespace,
            authority_namespace=target.authority_namespace, permit=permit)
        current_effect = port.read_current_effect(
            namespace=namespace,
            authority_namespace=target.authority_namespace,
            effect_id=material.final_effect_id)
        effect_snapshot = port.read_current_effect_snapshot_for_write_fence(
            namespace=namespace,
            authority_namespace=target.authority_namespace, permit=permit)
        if (type(owner_guard) is not OwnerAuthorizationGuardV1
                or owner_permit != permit
                or type(current_effect) is not CurrentEffectReadV2
                or current_effect.state != "absent"
                or type(effect_snapshot) is not AuthorityCurrentEffectSnapshotV2
                or effect_snapshot.coverage != "complete"
                or effect_snapshot.permit_digest
                   != authority_canonical_digest(permit)):
            raise UnavailableGuard("natural final current Authority proof differs; HOLD")
        finish_id = "finish:" + attempt_id
        finish_digest = "sha256:" + canonical_digest({
            "action": "finish_natural_final", "attempt_id": attempt_id,
            "permit_token": permit.token,
        })
        with store._lock:
            db.execute("BEGIN IMMEDIATE")
            try:
                if self._v2_graph_stamp(namespace) != (metadata, epoch):
                    raise StaleRead("natural final graph changed before commit")
                final = self._verify_natural_paid_review_current_locked(
                    namespace, parent_original_id, installed_bundle, paid,
                    now, epoch)
                if final.material != material:
                    raise UnavailableGuard("natural final paid material changed; HOLD")
                inputs, route = self._current_post_c02_reply_route_locked(
                    namespace, parent_original_id, material.source_ref.ref,
                    now, epoch)
                snapshot, query = self._dispatch_full_graph_snapshot_locked(
                    namespace)
                barrier = self._deletion_epochs_locked(db, namespace)
                grant = installed_bundle.installation_policy.root_grant
                identity = OperationIdentity(
                    material.final_activity_id, material.final_effect_id,
                    "natural-final-attempt:" + canonical_digest({
                        "operation_id": operation_id})[:40],
                    "post_c02_reply_dispatch", operation_id,
                    canonical_digest({"input_refs": [material.source_ref.ref]}))
                job_ref, outbox_ref, _ = post_c02_dispatch_runtime_refs_v2(
                    namespace, identity)
                deadline = min(
                    generation.frozen.input.plan.valid_until_utc,
                    now + installed_bundle.private_reply_dispatch.deadline_after_seconds,
                    grant.valid_until_utc)
                if now >= deadline:
                    raise UnavailableGuard("natural final deadline expired; HOLD")
                quote = self.__d11_issuer.issue_private_reply_dispatch_quote_v2(
                    db, policy=installed_bundle.private_reply_dispatch,
                    namespace=namespace, identity=identity,
                    parent_grant=grant, deadline_utc=deadline,
                    graph_job_ref=job_ref, outbox_refs=(outbox_ref,),
                    now_utc=now)
                db.execute(
                    "INSERT OR IGNORE INTO graph_guard_versions"
                    "(bot,persona,kind,ref,version) VALUES(?,?,?,?,?)",
                    namespace.as_tuple + (
                        "resource_lease", quote.quote_id, str(quote.version)))
                base = call.request.envelope
                expression_policy = read_current_d09_expression_policy_v1(
                    db, namespace)
                current_reads = {version.key: version
                                 for version in snapshot.versions}
                for version in material.current_reads:
                    previous = current_reads.get(version.key)
                    if previous is not None and previous != version:
                        raise StaleRead("natural paid read differs from current graph")
                    current_reads[version.key] = version
                policy_head = expression_policy.active_head_ref
                previous = current_reads.get(policy_head.key)
                if previous is not None and previous != policy_head:
                    raise StaleRead("natural expression policy head changed")
                current_reads[policy_head.key] = policy_head
                guard = replace(
                    base.version_guard,
                    read_versions=tuple(current_reads[key]
                                        for key in sorted(current_reads,
                                                          key=lambda item: item.token)),
                    query_epochs=(query,), access_epoch=barrier[0],
                    delete_epoch=barrier[1], focus_lease_versions=(),
                    resource_lease_versions=(VersionedRef(
                        quote.quote_id, quote.version),))
                envelope = replace(
                    base, identity=identity, authority=authority,
                    version_guard=guard,
                    input_refs=(material.source_ref.ref,),
                    parent_budget_lease_ref=grant.lease_id,
                    deadline_utc=deadline,
                    monotonic_deadline=time.monotonic() + 60,
                    causation=(parent_original_id,))
                reserve_budget(
                    db, grant.lease_id, operation_id,
                    budget_operation_digest(
                        envelope, grant.lease_id, dict(quote.ceiling)),
                    quote.ceiling)
                stage, checks, social, _d08, _original_binding, _staged_binding, projected = (
                    self._stage_natural_final_pregrant_locked(
                        envelope=envelope, final=final, route=route,
                        original_scope_proof=scoped,
                        budget_grant=grant, resource_quote=quote,
                        scope=scope, current_effect=current_effect,
                        effect_snapshot=effect_snapshot,
                        expected_access_delete_epoch=barrier,
                        now_utc=now))
                if social.status != "checks_candidate":
                    raise UnavailableGuard("natural final social checks absent; HOLD")
                adopted = decode_natural_plan_v2(next(
                    atom.value for atom in snapshot.atoms
                    if atom.key.token ==
                    generation.frozen.input.plan.plan_ref.ref))
                granted = self._freeze_natural_final_grant_locked(
                    final, generation.frozen.input.plan, adopted,
                    stage, checks, now_utc=now)
                job = replace(
                    self.__d11_issuer.job_for(envelope, db, now_utc=now),
                    phase="waiting", wake_condition={
                        "kind": "post_c02_reply_host_takeover",
                        "operation_id": operation_id})
                create_job(
                    db, job, "job:" + canonical_digest({
                        "natural_final_operation_id": operation_id,
                        "job_ref": job_ref})[:48], canonical_digest(job))
                prepared = prepare_natural_final_bundle_v2(
                    envelope=stage.proposal.envelope, final=final,
                    candidate=granted, schema=stage.schema,
                    checks=checks, staged_d08=stage.proposal,
                    quote=quote, budget_grant=grant,
                    pre_reserved_job=job, now_utc=now)
                if prepared.bundle is None:
                    raise UnavailableGuard("natural final bundle unavailable; HOLD")
                bound = prepared.bundle

                def issue(db, graph_receipt, evidence, _admissions):
                    runtime, binding, current_snapshot, current_query, projection = (
                        self._reissue_natural_final_after_graph_locked(
                            bundle=bound, final=final, paid=paid,
                            candidate=evidence, stage=stage, scope=scope,
                            route=route, original_scope_proof=scoped,
                            budget_grant=grant, resource_quote=quote,
                            current_effect=current_effect,
                            effect_snapshot=effect_snapshot,
                            provisional_checks=checks,
                            projected_check_versions=projected,
                            now_utc=now))
                    admission, request = issue_natural_dispatch_admission_v2(
                        db=db, bundle=bound, evidence=evidence,
                        final=final, runtime=runtime, checks=checks,
                        graph_receipt=graph_receipt, scope=scope,
                        clock_reading=clock,
                        clock_policy=self.__dispatch_clock_policy,
                        owner_guard=owner_guard,
                        current_effect=current_effect,
                        effect_snapshot=effect_snapshot,
                        route=binding, snapshot=current_snapshot,
                        query=current_query, projection=projection,
                        now_utc=now)
                    insert_admission(db, admission, request)
                    return admission, request

                receipt = self._commit_domain_bundle_fenced(
                    bound, lease, in_transaction=True,
                    v2_write=(metadata, epoch, finish_id, finish_digest,
                              canonical_json(to_wire(permit))),
                    now_utc=now, dispatch_clock_reading=clock,
                    natural_final_admission=issue)
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise
        if port.validate_fence(scope) != permit:
            raise UnavailableGuard("natural final permit changed after commit; HOLD")
        port.finish_fence(scope, request_id=finish_id,
                          request_digest=finish_digest)
        return receipt

    def _recover_committed_natural_final_v2(
            self, authority, parent_original_id, installed_bundle):
        """Finish only the original committed natural write after a lost ACK."""
        from .authority_service.v2_contract import FencePermitV2, from_wire
        from .runtime.natural_reply_job_v2 import read_original_preparation

        namespace = authority.namespace
        store, port = self.__store, self.__content_fence_v2
        with store._lock:
            db = store._db
            db.execute("BEGIN")
            try:
                generation = read_original_preparation(
                    db, namespace, parent_original_id, "generation")
                if generation is None:
                    db.execute("COMMIT")
                    return None
                if generation.seal.installation_id != (
                        installed_bundle.installation_policy.installation_id):
                    raise UnavailableGuard(
                        "natural final original installation differs; HOLD")
                plan = generation.frozen.input.plan
                operation_id = plan.final_operation_id
                receipt = self._get_operation_fenced(
                    authority, operation_id, v2=True)
                if receipt is None:
                    db.execute("COMMIT")
                    return None
                row = db.execute(
                    "SELECT digest,permit_json,pre_graph_revision,"
                    "pre_graph_epoch,post_graph_revision,post_graph_epoch,"
                    "finish_request_id,finish_request_digest FROM "
                    "graph_bundle_fences_v2 WHERE bot=? AND persona=? "
                    "AND operation_id=?",
                    namespace.as_tuple + (operation_id,),
                ).fetchone()
                recovered = self._get_natural_dispatch_candidate_evidence_locked(
                    namespace, operation_id)
                admission = db.execute(
                    "SELECT admission_ref FROM graph_dispatch_admissions "
                    "WHERE bot=? AND persona=? AND operation_id=? AND effect_id=?",
                    namespace.as_tuple + (operation_id, receipt.effect_id),
                ).fetchone()
                if (row is None or row[0] != receipt.digest
                        or row[4:6] != (
                            row[2] + 1, row[3] + 1)
                        or recovered is None or admission is None
                        or recovered.graph_epoch != row[5]
                        or recovered.evidence.generation_original_operation_id
                           != generation.seal.original_operation_id
                        or receipt.operation_id != operation_id):
                    raise UnavailableGuard(
                        "natural final committed recovery seal differs; HOLD")
                metadata, epoch = self._v2_graph_stamp(namespace)
                if (metadata.graph_revision < row[4]
                        or epoch.revision < row[5]):
                    raise UnavailableGuard(
                        "natural final recovery graph regressed; HOLD")
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise
        permit = from_wire(json.loads(row[1]))
        if (type(permit) is not FencePermitV2
                or permit.operation != "write"
                or permit.holder != self.__holder
                or permit.namespace != metadata.requirements.authority_namespace):
            raise UnavailableGuard("natural final original permit differs; HOLD")
        original, state = port.get_fence_operation(
            namespace=namespace,
            authority_namespace=metadata.requirements.authority_namespace,
            operation_id=permit.operation_id)
        if original != permit or state not in {"active", "finished"}:
            raise UnavailableGuard("natural final original fence differs; HOLD")
        if state == "active":
            if (metadata.graph_revision, epoch.revision) != (row[4], row[5]):
                raise UnavailableGuard(
                    "natural final active recovery stamp differs; HOLD")
            scope = FenceScope(
                namespace, metadata.requirements.authority_namespace,
                authority.activation_generation, "write", permit.operation_id,
                permit, permit.pinned_anchor,
                NamespaceEpoch(*namespace.as_tuple, row[3]), row[2])
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("natural final recovery fence changed; HOLD")
            port.finish_fence(
                scope, request_id=row[6], request_digest=row[7])
        return replace(receipt, status="duplicate")

    def _finish_committed_post_c02_reply_fence_v1(
        self, namespace: NamespaceId, metadata, epoch: NamespaceEpoch,
        anchor, attempt_id: str, anchor_json: str,
        prior_revision: int, prior_epoch: int, action: str,
    ) -> None:
        """Resolve only the original committed write after a lost finish ACK."""
        from .authority_service.v2_contract import FencePermitV2

        port = self.__content_fence_v2
        target = metadata.requirements
        if (port is None or anchor_json != canonical_json(asdict(anchor))
                or action not in {"finish_reply_job", "finish_reply_acquire",
                                  "finish_context_reply_terminal",
                                  "finish_natural_generation",
                                  "finish_natural_review"}):
            raise UnavailableGuard("reply committed write identity differs; HOLD")
        permit, state = port.get_fence_operation(
            namespace=namespace, authority_namespace=target.authority_namespace,
            operation_id=attempt_id)
        if (type(permit) is not FencePermitV2
                or permit.operation != "write"
                or permit.operation_id != attempt_id
                or permit.holder != self.__holder
                or permit.pinned_anchor != anchor
                or state not in {"active", "finished"}
                or metadata.graph_revision < prior_revision + 1
                or epoch.revision < prior_epoch + 1):
            raise UnavailableGuard("reply committed Authority write differs; HOLD")
        if state == "active":
            if (metadata.graph_revision, epoch.revision) != (
                    prior_revision + 1, prior_epoch + 1):
                raise UnavailableGuard("reply active write lost graph stamp; HOLD")
            scope = FenceScope(
                namespace, target.authority_namespace,
                target.activation_generation, "write", attempt_id,
                permit, anchor,
                NamespaceEpoch(*namespace.as_tuple, prior_epoch),
                prior_revision)
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("reply committed write permit changed; HOLD")
            port.finish_fence(
                scope, request_id="finish:" + attempt_id,
                request_digest="sha256:" + canonical_digest({
                    "action": action, "attempt_id": attempt_id,
                    "permit_token": permit.token,
                }))

    def prepare_post_c02_reply_model_job_v1(
        self, bootstrap: object, namespace: NamespaceId,
        c02_operation_id: str, source_ref: str, installed_bundle,
    ):
        """Commit one source-qualified reply job, quote and reserve together.

        The graph worker calls this synchronously. All Authority fence RPCs
        occur outside GraphStore's lock; the current C02/source/access/D07
        reads and all business writes occur inside one BEGIN IMMEDIATE.
        """
        from .authority_service.v2_contract import FencePermitV2
        from .authority_service.contract import AuthorityUnavailable
        from .domains.d07 import read_current_focus_attention_ticket
        from .host.authority_profile import AdminIngressClockPolicy, AdminInstallationBundle
        from .memory_types import access_key, source_key
        from .runtime.d11_types import job_graph_write, runtime_job_key
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.issuers import D02ResourceIssuer, D11BudgetJobIssuer
        from .runtime.reply_model_job import (
            ReplyModelJobHold, install_schema, issue_reply_job_in_transaction_v1,
            read_current_reply_model_inputs_v1, read_saved_reply_job_v1,
            reply_job_original_operation_id_v1, source_key_from_ref,
        )

        self._admin(bootstrap)
        store = self.__store
        port = self.__content_fence_v2
        if (not isinstance(store, ProductionGraphStore) or port is None
                or type(namespace) is not NamespaceId
                or type(installed_bundle) is not AdminInstallationBundle
                or type(self.__scene_clock_policy) is not AdminIngressClockPolicy
                or installed_bundle.ingress_clock != self.__scene_clock_policy
                or type(self.__d02_issuer) is not D02ResourceIssuer
                or type(self.__d11_issuer) is not D11BudgetJobIssuer
                or self.__d11_issuer.resource_issuer is not self.__d02_issuer
                or installed_bundle.installation_policy.namespace != namespace):
            raise UnavailableGuard("installed reply graph authorities are unavailable; HOLD")
        try:
            source_id = source_key_from_ref(source_ref, namespace)
            now = trusted_upper(port.read_ingress_clock(self.__scene_clock_policy))
        except Exception as exc:
            raise UnavailableGuard("reply source or trusted clock is unavailable; HOLD") from exc
        original_operation_id = reply_job_original_operation_id_v1(
            c02_operation_id, source_ref)
        input_digest = canonical_digest({
            "schema": "sylanne.post-c02-reply-preparation.v1",
            "namespace": list(namespace.as_tuple),
            "c02_operation_id": c02_operation_id,
            "source_ref": source_ref,
            "installation_id": installed_bundle.installation_policy.installation_id,
            "reply_workflow": ({
                "provider_id": installed_bundle.model_workflows.reply.provider_id,
                "model_id": installed_bundle.model_workflows.reply.model_id,
                "provider_config_digest": installed_bundle.model_workflows.reply.provider_config_digest,
                "template_version": installed_bundle.model_workflows.reply.template_version,
                "quote_ceiling": dict(installed_bundle.model_workflows.reply.quote_ceiling),
            } if installed_bundle.model_workflows is not None else None),
        })
        with store._lock:
            db = store._db
            install_schema(db)
            saved = read_saved_reply_job_v1(
                db, self.__d02_issuer, namespace, c02_operation_id, source_ref)
            attempt = db.execute(
                "SELECT input_digest,attempt_id,anchor_json,graph_revision,"
                "graph_epoch,state FROM graph_post_c02_reply_model_attempts_v1 "
                "WHERE bot=? AND persona=? AND original_operation_id=?",
                namespace.as_tuple + (original_operation_id,),
            ).fetchone()
            metadata, epoch = self._v2_graph_stamp(namespace)
        target = metadata.requirements
        provision_row = self._provision_row(store._db, namespace)
        provision = (self._decode_provision_receipt(provision_row)
                     if provision_row is not None else None)
        if (target.namespace != namespace or provision is None
                or provision.generation != target.activation_generation
                or provision.installation_id !=
                   installed_bundle.installation_policy.installation_id
                or provision.authority_id != target.authority_id
                or provision.authority_namespace != target.authority_namespace):
            raise UnavailableGuard("reply graph activation differs; HOLD")
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("reply Authority anchor differs; HOLD")
        if attempt is not None and attempt[0] != input_digest:
            raise EventConflict("reply preparation identity reused with another profile")
        if saved is not None:
            if attempt is None or attempt[5] != "committed":
                raise UnavailableGuard("reply preparation lacks its write fence; HOLD")
            self._finish_committed_post_c02_reply_fence_v1(
                namespace, metadata, epoch, anchor, attempt[1], attempt[2],
                attempt[3], attempt[4], "finish_reply_job")
            return saved
        if attempt is not None and attempt[5] == "committed":
            raise UnavailableGuard("reply committed fence lacks job; HOLD")
        if attempt is not None and attempt[5] == "open":
            if (attempt[2] != canonical_json(asdict(anchor))
                    or (attempt[3], attempt[4]) != (
                        metadata.graph_revision, epoch.revision)):
                raise UnavailableGuard("reply pending write anchor changed; HOLD")
            attempt_id = attempt[1]
            attempt_was_open = True
        else:
            attempt_id = "reply-job-write-" + secrets.token_hex(24)
            attempt_was_open = False
            with store._lock:
                db.execute("BEGIN IMMEDIATE")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise StaleRead("reply graph changed before write intent")
                    db.execute(
                        "INSERT INTO graph_post_c02_reply_model_attempts_v1"
                        "(bot,persona,original_operation_id,input_digest,attempt_id,"
                        "anchor_json,graph_revision,graph_epoch,state) "
                        "VALUES(?,?,?,?,?,?,?,?,'open') "
                        "ON CONFLICT(bot,persona,original_operation_id) DO UPDATE SET "
                        "attempt_id=excluded.attempt_id,anchor_json=excluded.anchor_json,"
                        "graph_revision=excluded.graph_revision,"
                        "graph_epoch=excluded.graph_epoch,state='open' "
                        "WHERE graph_post_c02_reply_model_attempts_v1.state='closed' "
                        "AND graph_post_c02_reply_model_attempts_v1.input_digest=excluded.input_digest",
                        namespace.as_tuple + (original_operation_id, input_digest,
                        attempt_id, canonical_json(asdict(anchor)),
                        metadata.graph_revision, epoch.revision),
                    )
                    db.execute("COMMIT")
                except BaseException:
                    db.execute("ROLLBACK")
                    raise
        if attempt_was_open:
            try:
                observed_permit, observed_state = port.get_fence_operation(
                    namespace=namespace,
                    authority_namespace=target.authority_namespace,
                    operation_id=attempt_id)
            except AuthorityUnavailable:
                # A crash may leave the local exact attempt before begin_fence.
                # Retry that same operation ID; Authority rejects any collision.
                observed_permit, observed_state = None, "absent"
        else:
            observed_permit, observed_state = None, "absent"
        if observed_state == "absent":
            permit = port.begin_fence(
                namespace=namespace,
                authority_namespace=target.authority_namespace,
                holder=self.__holder, generation=target.activation_generation,
                operation="write", operation_id=attempt_id,
                expected_anchor=anchor)
        elif observed_state == "active":
            permit = observed_permit
        else:
            raise UnavailableGuard("reply write attempt has unresolved Authority state; HOLD")
        if (type(permit) is not FencePermitV2 or permit.operation != "write"
                or permit.operation_id != attempt_id or permit.holder != self.__holder
                or permit.pinned_anchor != anchor):
            raise UnavailableGuard("reply write permit differs; HOLD")
        scope = FenceScope(
            namespace, target.authority_namespace, target.activation_generation,
            "write", attempt_id, permit, anchor, epoch, metadata.graph_revision)
        if port.validate_fence(scope) != permit:
            raise UnavailableGuard("reply write fence is stale; HOLD")
        try:
            with store._lock:
                db.execute("BEGIN IMMEDIATE")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise StaleRead("reply graph changed before business write")
                    source_key_value = source_key(*namespace.as_tuple, source_id)
                    access_key_value = access_key(*namespace.as_tuple, source_id)
                    snapshot, attention = self._qualified_reply_attention_locked(
                        namespace, source_ref, now, epoch)
                    focus_key, ticket_key = (attention.focus_version.key,
                                             attention.ticket_version.key)
                    c02_row = db.execute(
                        "SELECT digest,activity_id,effect_id,commit_seq,receipt_json "
                        "FROM graph_bundle_operations WHERE bot=? AND persona=? "
                        "AND operation_id=?",
                        namespace.as_tuple + (c02_operation_id,),
                    ).fetchone()
                    if c02_row is None:
                        raise ReplyModelJobHold("original C02 receipt is absent")
                    c02_event = db.execute(
                        "SELECT reads,revisions,epoch_revision FROM graph_events "
                        "WHERE bot=? AND persona=? AND session=? AND event_id=?",
                        namespace.as_tuple + (c02_row[1], c02_operation_id),
                    ).fetchone()
                    if c02_event is None:
                        raise ReplyModelJobHold("original C02 graph event is absent")
                    c02_detail = json.loads(c02_row[4])
                    c02_receipt = CommitReceipt(
                        "committed", c02_operation_id, c02_row[0], c02_row[1],
                        c02_row[2], c02_row[3],
                        GraphStore._version_rows(c02_event[0]),
                        GraphStore._version_rows(c02_event[1]),
                        (NamespaceEpoch(*namespace.as_tuple, c02_event[2]),),
                        tuple(c02_detail["ledger_refs"]),
                        tuple(c02_detail["outbox_refs"]))
                    inputs = read_current_reply_model_inputs_v1(
                        db, self.__d02_issuer, namespace, c02_receipt,
                        source_ref, snapshot, attention)
                    job, quote, reservation_digest = (
                        issue_reply_job_in_transaction_v1(
                            db, namespace=namespace, inputs=inputs,
                            installed_bundle=installed_bundle,
                            d02_issuer=self.__d02_issuer,
                            d11_issuer=self.__d11_issuer, now_utc=now))
                    write = job_graph_write(job)
                    reconcile_runtime_write(db, write)
                    candidate = GraphCandidate(
                        Event(Scope(*namespace.as_tuple, job.activity_id),
                              original_operation_id, now, "domain_bundle",
                              {"bundle_digest": input_digest}),
                        (GraphVersion(write.key, 0),) + snapshot.versions,
                        (GraphWrite(write.key, write.value,
                                    (source_key_value, access_key_value,
                                     ticket_key, focus_key)),), (epoch,))
                    graph_receipt = GraphStore._graph_commit_in_transaction(
                        store, candidate, _capability=self.__graph_capability)
                    if graph_receipt.status != "committed":
                        raise EventConflict("reply graph job did not commit")
                    store.cas_graph_recovery_metadata(
                        metadata, metadata.requirements,
                        _capability=self.__graph_capability)
                    seq_row = db.execute(
                        "SELECT last_seq FROM graph_bundle_sequence "
                        "WHERE bot=? AND persona=?",
                        namespace.as_tuple,
                    ).fetchone()
                    seq = (seq_row[0] if seq_row else 0) + 1
                    db.execute(
                        "INSERT INTO graph_bundle_sequence(bot,persona,last_seq) "
                        "VALUES(?,?,?) ON CONFLICT(bot,persona) DO UPDATE SET "
                        "last_seq=excluded.last_seq",
                        namespace.as_tuple + (seq,),
                    )
                    db.execute(
                        "INSERT INTO graph_bundle_operations"
                        "(bot,persona,operation_id,digest,activity_id,effect_id,"
                        "commit_seq,receipt_json) VALUES(?,?,?,?,?,?,?,?)",
                        namespace.as_tuple + (original_operation_id,
                        input_digest, job.activity_id, None, seq,
                        canonical_json({
                            "c02_operation_id": c02_operation_id,
                            "source_ref": source_ref,
                            "job_ref": write.key.token,
                            "quote_id": quote.quote_id,
                            "reservation_digest": reservation_digest,
                            "ledger_refs": [write.key.token],
                            "outbox_refs": [],
                        })),
                    )
                    db.execute(
                        "UPDATE graph_post_c02_reply_model_attempts_v1 "
                        "SET state='committed' WHERE bot=? AND persona=? "
                        "AND original_operation_id=? AND attempt_id=?",
                        namespace.as_tuple + (original_operation_id, attempt_id),
                    )
                    saved = read_saved_reply_job_v1(
                        db, self.__d02_issuer, namespace,
                        c02_operation_id, source_ref)
                    db.execute("COMMIT")
                except BaseException:
                    db.execute("ROLLBACK")
                    raise
        except BaseException:
            try:
                port.finish_fence(
                    scope, request_id="finish:" + attempt_id,
                    request_digest="sha256:" + canonical_digest({
                        "action": "abort_reply_job", "attempt_id": attempt_id,
                        "permit_token": permit.token,
                    }))
                with store._lock:
                    db.execute(
                        "UPDATE graph_post_c02_reply_model_attempts_v1 "
                        "SET state='closed' WHERE bot=? AND persona=? "
                        "AND original_operation_id=? AND attempt_id=? AND state='open'",
                        namespace.as_tuple + (original_operation_id, attempt_id),
                    )
            except Exception:
                pass
            raise
        if port.validate_fence(scope) != permit:
            raise UnavailableGuard("reply committed write fence outcome unknown; HOLD")
        port.finish_fence(
            scope, request_id="finish:" + attempt_id,
            request_digest="sha256:" + canonical_digest({
                "action": "finish_reply_job", "attempt_id": attempt_id,
                "permit_token": permit.token,
            }))
        return saved

    def prepare_post_c02_context_reply_model_job_v2(
        self, bootstrap: object, namespace: NamespaceId,
        c02_operation_id: str, source_ref: str, installed_bundle,
    ):
        """Atomically freeze the original context-reply input and D11 job.

        An existing source_reply.v1 attempt keeps its original identity. The
        independent V2 workflow is used only for a fresh C02/source pair.
        """
        from .authority_service.contract import AuthorityUnavailable
        from .authority_service.v2_contract import FencePermitV2
        from .host.authority_profile import AdminIngressClockPolicy, AdminInstallationBundle
        from .runtime.context_reply_job_v2 import (
            ContextReplyJobHold, context_reply_job_ids_v2,
            freeze_current_context_reply_v2,
            install_schema as install_context_schema,
            issue_context_reply_job_in_transaction_v2,
            legacy_reply_identity_exists_v1,
            read_original_context_reply_preparation_v2,
        )
        from .runtime.d11_types import job_graph_write
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.issuers import D02ResourceIssuer, D11BudgetJobIssuer
        from .runtime_contracts import QueryEpoch
        from .runtime.reply_model_job import (
            CurrentReplyModelInputsV1, install_schema as install_legacy_schema,
            read_current_reply_route_manifest_v2,
            read_settled_c02_reply_source_v1, source_key_from_ref,
        )
        from .runtime_contracts import (
            CONTEXT_REPLY_WORKFLOW_V1, QueryEpoch,
        )

        self._admin(bootstrap)
        store = self.__store
        port = self.__content_fence_v2
        if (not isinstance(store, ProductionGraphStore) or port is None
                or type(namespace) is not NamespaceId
                or type(installed_bundle) is not AdminInstallationBundle
                or type(self.__scene_clock_policy) is not AdminIngressClockPolicy
                or installed_bundle.ingress_clock != self.__scene_clock_policy
                or type(self.__d02_issuer) is not D02ResourceIssuer
                or type(self.__d11_issuer) is not D11BudgetJobIssuer
                or self.__d11_issuer.resource_issuer is not self.__d02_issuer
                or installed_bundle.installation_policy.namespace != namespace):
            raise UnavailableGuard("installed V2 reply authorities unavailable; HOLD")
        workflows = installed_bundle.model_workflows
        workflow = getattr(workflows, "context_reply", None)
        try:
            source_key_from_ref(source_ref, namespace)
            now = trusted_upper(port.read_ingress_clock(self.__scene_clock_policy))
        except Exception as exc:
            raise UnavailableGuard("context reply source or clock unavailable; HOLD") from exc
        _, original_id, _, _ = context_reply_job_ids_v2(
            namespace, c02_operation_id, source_ref)
        with store._lock:
            db = store._db
            install_legacy_schema(db)
            install_context_schema(db)
            legacy = legacy_reply_identity_exists_v1(
                db, namespace, c02_operation_id, source_ref)
            db.execute("BEGIN")
            try:
                saved = read_original_context_reply_preparation_v2(
                    db, namespace, c02_operation_id, source_ref)
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise
            attempt = db.execute(
                "SELECT input_digest,attempt_id,anchor_json,graph_revision,"
                "graph_epoch,state FROM graph_context_reply_attempts_v2 "
                "WHERE bot=? AND persona=? AND original_operation_id=?",
                namespace.as_tuple + (original_id,),
            ).fetchone()
            metadata, epoch = self._v2_graph_stamp(namespace)
        if legacy:
            if saved is not None or attempt is not None:
                raise UnavailableGuard("V1/V2 reply identities overlap; HOLD")
            return self.prepare_post_c02_reply_model_job_v1(
                bootstrap, namespace, c02_operation_id, source_ref,
                installed_bundle)
        if (workflow is None
                or workflow.template_version != CONTEXT_REPLY_WORKFLOW_V1):
            raise UnavailableGuard("installed context reply workflow unavailable; HOLD")
        input_digest = canonical_digest({
            "schema": "sylanne.post-c02-context-reply-preparation.v2",
            "namespace": namespace.as_tuple, "c02_operation_id": c02_operation_id,
            "source_ref": source_ref,
            "installation_id": installed_bundle.installation_policy.installation_id,
            "provider_config_digest": workflow.provider_config_digest,
            "template_version": workflow.template_version,
            "quote_ceiling": dict(workflow.quote_ceiling),
        })
        target = metadata.requirements
        provision_row = self._provision_row(store._db, namespace)
        provision = (self._decode_provision_receipt(provision_row)
                     if provision_row is not None else None)
        if (target.namespace != namespace or provision is None
                or provision.generation != target.activation_generation
                or provision.installation_id
                   != installed_bundle.installation_policy.installation_id
                or provision.authority_id != target.authority_id
                or provision.authority_namespace != target.authority_namespace):
            raise UnavailableGuard("context reply graph activation differs; HOLD")
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("context reply Authority anchor differs; HOLD")
        if attempt is not None and attempt[0] != input_digest:
            raise EventConflict("context reply identity reused with another profile")
        if saved is not None:
            if attempt is None or attempt[5] != "committed":
                raise UnavailableGuard("saved context reply lacks write fence; HOLD")
            self._finish_committed_post_c02_reply_fence_v1(
                namespace, metadata, epoch, anchor, attempt[1], attempt[2],
                attempt[3], attempt[4], "finish_reply_job")
            return saved
        ready = getattr(port, "context_reply_paid_consumer_ready_v2", None)
        try:
            consumer_ready = (callable(ready) and ready(
                namespace=namespace,
                template_version=CONTEXT_REPLY_WORKFLOW_V1) is True)
        except Exception:
            consumer_ready = False
        if not consumer_ready:
            raise UnavailableGuard("installed V2 paid consumer unavailable; HOLD")
        if attempt is not None and attempt[5] == "committed":
            raise UnavailableGuard("committed context reply lacks job; HOLD")
        if attempt is not None and attempt[5] == "open":
            if (attempt[2] != canonical_json(asdict(anchor))
                    or (attempt[3], attempt[4])
                       != (metadata.graph_revision, epoch.revision)):
                raise UnavailableGuard("pending V2 reply anchor changed; HOLD")
            attempt_id = attempt[1]
            was_open = True
        else:
            attempt_id = "context-reply-write-" + secrets.token_hex(24)
            was_open = False
            with store._lock:
                db.execute("BEGIN IMMEDIATE")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise StaleRead("context reply graph changed before intent")
                    db.execute(
                        "INSERT INTO graph_context_reply_attempts_v2"
                        "(bot,persona,original_operation_id,input_digest,attempt_id,"
                        "anchor_json,graph_revision,graph_epoch,state) "
                        "VALUES(?,?,?,?,?,?,?,?,'open') "
                        "ON CONFLICT(bot,persona,original_operation_id) DO UPDATE SET "
                        "attempt_id=excluded.attempt_id,anchor_json=excluded.anchor_json,"
                        "graph_revision=excluded.graph_revision,"
                        "graph_epoch=excluded.graph_epoch,state='open' "
                        "WHERE graph_context_reply_attempts_v2.state='closed' "
                        "AND graph_context_reply_attempts_v2.input_digest=excluded.input_digest",
                        namespace.as_tuple + (original_id, input_digest,
                        attempt_id, canonical_json(asdict(anchor)),
                        metadata.graph_revision, epoch.revision),
                    )
                    db.execute("COMMIT")
                except BaseException:
                    db.execute("ROLLBACK")
                    raise
        if was_open:
            try:
                observed_permit, observed_state = port.get_fence_operation(
                    namespace=namespace, authority_namespace=target.authority_namespace,
                    operation_id=attempt_id)
            except AuthorityUnavailable:
                observed_permit, observed_state = None, "absent"
        else:
            observed_permit, observed_state = None, "absent"
        if observed_state == "absent":
            permit = port.begin_fence(
                namespace=namespace, authority_namespace=target.authority_namespace,
                holder=self.__holder, generation=target.activation_generation,
                operation="write", operation_id=attempt_id,
                expected_anchor=anchor)
        elif observed_state == "active":
            permit = observed_permit
        else:
            raise UnavailableGuard("V2 reply write attempt unresolved; HOLD")
        if (type(permit) is not FencePermitV2 or permit.operation != "write"
                or permit.operation_id != attempt_id or permit.holder != self.__holder
                or permit.pinned_anchor != anchor):
            raise UnavailableGuard("V2 reply write permit differs; HOLD")
        scope = FenceScope(
            namespace, target.authority_namespace, target.activation_generation,
            "write", attempt_id, permit, anchor, epoch, metadata.graph_revision)
        if port.validate_fence(scope) != permit:
            raise UnavailableGuard("V2 reply write fence stale; HOLD")
        try:
            with store._lock:
                db.execute("BEGIN IMMEDIATE")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise StaleRead("context reply graph changed before write")
                    snapshot, attention = self._qualified_reply_attention_locked(
                        namespace, source_ref, now, epoch)
                    c02_row = db.execute(
                        "SELECT digest,activity_id,effect_id,commit_seq,receipt_json "
                        "FROM graph_bundle_operations WHERE bot=? AND persona=? "
                        "AND operation_id=?",
                        namespace.as_tuple + (c02_operation_id,),
                    ).fetchone()
                    if c02_row is None:
                        raise ContextReplyJobHold("original C02 receipt absent")
                    c02_event = db.execute(
                        "SELECT reads,revisions,epoch_revision FROM graph_events "
                        "WHERE bot=? AND persona=? AND session=? AND event_id=?",
                        namespace.as_tuple + (c02_row[1], c02_operation_id),
                    ).fetchone()
                    if c02_event is None:
                        raise ContextReplyJobHold("original C02 event absent")
                    detail = json.loads(c02_row[4])
                    c02_receipt = CommitReceipt(
                        "committed", c02_operation_id, c02_row[0], c02_row[1],
                        c02_row[2], c02_row[3],
                        GraphStore._version_rows(c02_event[0]),
                        GraphStore._version_rows(c02_event[1]),
                        (NamespaceEpoch(*namespace.as_tuple, c02_event[2]),),
                        tuple(detail["ledger_refs"]), tuple(detail["outbox_refs"]),
                    )
                    settled = read_settled_c02_reply_source_v1(
                        db, self.__d02_issuer, namespace, c02_receipt,
                        source_ref, snapshot)
                    inputs = CurrentReplyModelInputsV1(
                        c02_receipt, settled.source, attention,
                        settled.conversation_ref, snapshot)
                    route = read_current_reply_route_manifest_v2(
                        db, namespace, inputs, source_ref)
                    epochs = db.execute(
                        "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                        "WHERE bot=? AND persona=?", namespace.as_tuple,
                    ).fetchone()
                    grant = self.__d11_issuer.current_budget_grant(
                        db, installed_bundle.installation_policy.root_lease.lease_id)
                    if epochs is None:
                        raise ContextReplyJobHold("current access epochs absent")
                    expires = min(now + workflow.timeout_seconds + 60,
                                  attention.ticket.valid_until,
                                  grant.valid_until_utc)
                    frozen = freeze_current_context_reply_v2(
                        namespace, c02_operation_id, source_ref,
                        snapshot, attention, route, workflow,
                        installed_bundle.installation_policy.installation_id,
                        now_utc=now, expires_at_utc=expires,
                        access_epoch=epochs[0], delete_epoch=epochs[1],
                        activation_generation=target.activation_generation)
                    query = QueryEpoch(namespace, route.scene_ref, epoch.revision + 1)
                    job, quote, reservation_digest, _seal = (
                        issue_context_reply_job_in_transaction_v2(
                            db, namespace=namespace, c02_receipt=c02_receipt,
                            source_ref=source_ref, attention=attention,
                            frozen=frozen, read_versions=snapshot.versions,
                            query_epoch=query, graph_epoch=epoch.revision + 1,
                            installed_bundle=installed_bundle,
                            d02_issuer=self.__d02_issuer,
                            d11_issuer=self.__d11_issuer, now_utc=now))
                    write = job_graph_write(job)
                    reconcile_runtime_write(db, write)
                    deps = tuple(atom.key for atom in snapshot.atoms if atom.valid)
                    candidate = GraphCandidate(
                        Event(Scope(*namespace.as_tuple, job.activity_id),
                              original_id, now, "domain_bundle",
                              {"bundle_digest": input_digest}),
                        (GraphVersion(write.key, 0),) + snapshot.versions,
                        (GraphWrite(write.key, write.value, deps),), (epoch,))
                    graph_receipt = GraphStore._graph_commit_in_transaction(
                        store, candidate, _capability=self.__graph_capability)
                    if graph_receipt.status != "committed":
                        raise EventConflict("V2 reply graph job did not commit")
                    store.cas_graph_recovery_metadata(
                        metadata, metadata.requirements,
                        _capability=self.__graph_capability)
                    seq_row = db.execute(
                        "SELECT last_seq FROM graph_bundle_sequence "
                        "WHERE bot=? AND persona=?", namespace.as_tuple,
                    ).fetchone()
                    seq = (seq_row[0] if seq_row else 0) + 1
                    db.execute(
                        "INSERT INTO graph_bundle_sequence(bot,persona,last_seq) "
                        "VALUES(?,?,?) ON CONFLICT(bot,persona) DO UPDATE SET "
                        "last_seq=excluded.last_seq",
                        namespace.as_tuple + (seq,),
                    )
                    db.execute(
                        "INSERT INTO graph_bundle_operations"
                        "(bot,persona,operation_id,digest,activity_id,effect_id,"
                        "commit_seq,receipt_json) VALUES(?,?,?,?,?,?,?,?)",
                        namespace.as_tuple + (original_id, input_digest,
                        job.activity_id, None, seq, canonical_json({
                            "c02_operation_id": c02_operation_id,
                            "source_ref": source_ref, "job_ref": write.key.token,
                            "quote_id": quote.quote_id,
                            "reservation_digest": reservation_digest,
                            "seal_digest": canonical_digest(asdict(_seal)),
                            "ledger_refs": [write.key.token], "outbox_refs": [],
                        })),
                    )
                    db.execute(
                        "UPDATE graph_context_reply_attempts_v2 SET state='committed' "
                        "WHERE bot=? AND persona=? AND original_operation_id=? "
                        "AND attempt_id=?",
                        namespace.as_tuple + (original_id, attempt_id),
                    )
                    saved = read_original_context_reply_preparation_v2(
                        db, namespace, c02_operation_id, source_ref)
                    db.execute("COMMIT")
                except BaseException:
                    db.execute("ROLLBACK")
                    raise
        except BaseException:
            try:
                port.finish_fence(
                    scope, request_id="finish:" + attempt_id,
                    request_digest="sha256:" + canonical_digest({
                        "action": "abort_context_reply_job",
                        "attempt_id": attempt_id, "permit_token": permit.token,
                    }))
                with store._lock:
                    db.execute(
                        "UPDATE graph_context_reply_attempts_v2 SET state='closed' "
                        "WHERE bot=? AND persona=? AND original_operation_id=? "
                        "AND attempt_id=? AND state='open'",
                        namespace.as_tuple + (original_id, attempt_id),
                    )
            except Exception:
                pass
            raise
        if port.validate_fence(scope) != permit:
            raise UnavailableGuard("V2 reply committed write outcome unknown; HOLD")
        port.finish_fence(
            scope, request_id="finish:" + attempt_id,
            request_digest="sha256:" + canonical_digest({
                "action": "finish_reply_job", "attempt_id": attempt_id,
                "permit_token": permit.token,
            }))
        return saved

    def read_original_context_reply_preparation_v2(
            self, authority: AuthorityContext, lease: object, *,
            c02_operation_id: str, source_ref: str):
        """Read W01's sealed V2 original job through a current graph fence.

        This supplies host coordination data only. Authority independently
        rereads the sealed row and its own paid intent/terminal before any
        result can be adopted.
        """
        from .runtime.context_reply_job_v2 import (
            read_original_context_reply_preparation_v2,
        )
        from .runtime.jobs import get_job

        if (not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None):
            raise UnavailableGuard("original V2 reply needs current graph fence")
        self._authorize(lease, authority, frozenset({"d11"}), owner_read=True)
        if (authority.issuer_domain != "d11" or authority.actor != self.__holder
                or "activity" not in authority.owner_scope):
            raise AuthorityDenied("original V2 reply needs D11 activity authority")

        def reader():
            db = self.__store._db
            db.execute("BEGIN")
            try:
                saved = read_original_context_reply_preparation_v2(
                    db, authority.namespace, c02_operation_id, source_ref)
                if saved is None:
                    raise UnavailableGuard("original V2 reply seal absent; HOLD")
                job = get_job(db, saved.seal.job_id)
                if (job.operation_id != saved.seal.original_operation_id
                        or job.work_kind != "context_reply"
                        or (job.bot_id, job.persona_id)
                           != authority.namespace.as_tuple
                        or job.phase not in {"queued", "running", "completed",
                                             "failed", "cancelled"}
                        or db.execute(
                            "SELECT 1 FROM graph_bundle_operations WHERE bot=? "
                            "AND persona=? AND operation_id=?",
                            authority.namespace.as_tuple
                            + (saved.seal.original_operation_id,),
                        ).fetchone() is None):
                    raise UnavailableGuard("original V2 reply job differs; HOLD")
                return saved
            finally:
                db.execute("ROLLBACK")

        return self._read_v2(authority, reader)

    def acquire_post_c02_context_reply_model_job_v2(
            self, authority: AuthorityContext, lease: object,
            c02_operation_id: str, source_ref: str, installed_bundle, *,
            lease_seconds: int,
    ):
        """Acquire one sealed V2 job and persist its paid call before egress."""
        from .authority_service.v2_contract import FencePermitV2
        from .host.authority_profile import AdminInstallationBundle
        from .model_broker.broker import ModelCallRequest
        from .model_broker.context_reply import CONTEXT_REPLY_TEMPLATE_DIGEST
        from .runtime.context_reply_job_v2 import (
            ContextReplyJobHold, bind_original_context_reply_call_v2,
            install_schema as install_context_schema,
            read_original_context_reply_call_binding_v2,
            read_original_context_reply_preparation_v2,
        )
        from .runtime.d11_types import job_graph_write
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.issuers import D02ResourceIssuer, D11BudgetJobIssuer
        from .runtime_contracts import (
            CommandEnvelope, OperationIdentity, QueryEpoch, RUNTIME_SCHEMA,
        )

        store, port, namespace = self.__store, self.__content_fence_v2, authority.namespace
        if (not isinstance(store, ProductionGraphStore) or port is None
                or type(installed_bundle) is not AdminInstallationBundle
                or type(self.__d02_issuer) is not D02ResourceIssuer
                or type(self.__d11_issuer) is not D11BudgetJobIssuer
                or installed_bundle.installation_policy.namespace != namespace
                or installed_bundle.ingress_clock != self.__scene_clock_policy
                or type(lease_seconds) is not int
                or not 1 <= lease_seconds <= 3600):
            raise UnavailableGuard("installed V2 reply acquire authorities absent; HOLD")
        workflow = installed_bundle.model_workflows.context_reply
        if workflow is None:
            raise UnavailableGuard("context reply workflow unavailable; HOLD")
        self._authorize(lease, authority, frozenset({"d11"}))
        with store._lock:
            db = store._db
            install_context_schema(db)
            db.execute("BEGIN")
            try:
                saved = read_original_context_reply_preparation_v2(
                    db, namespace, c02_operation_id, source_ref)
                if saved is None:
                    raise ContextReplyJobHold("original V2 reply job absent")
                job = get_job(db, saved.seal.job_id)
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise
            metadata, epoch = self._v2_graph_stamp(namespace)
            acquire_row = db.execute(
                "SELECT request_digest,attempt_id,anchor_json,graph_revision,"
                "graph_epoch,state FROM graph_context_reply_acquires_v2 "
                "WHERE bot=? AND persona=? AND acquire_operation_id=?",
                namespace.as_tuple + (saved.seal.acquire_operation_id,),
            ).fetchone()
        seal = saved.seal
        if (authority.issuer_domain != "d11" or authority.purpose != "proposal"
                or "activity" not in authority.owner_scope
                or authority.worker_fence is not None
                or authority.capability_ref != _operation_capability_ref(
                    namespace, authority.actor, "d11", frozenset({"d11"}),
                    authority.activation_generation, seal.acquire_operation_id)
                or (seal.namespace, seal.c02_operation_id, seal.source_ref,
                    seal.job_id, seal.original_operation_id)
                   != (namespace, c02_operation_id, source_ref,
                       job.job_id, job.operation_id)
                or (workflow.provider_config_digest, workflow.provider_id,
                    workflow.model_id, workflow.max_output_tokens)
                   != (saved.frozen_request.installation.provider_config_digest,
                       saved.frozen_request.installation.provider_id,
                       saved.frozen_request.installation.model_id,
                       saved.frozen_request.installation.max_output_tokens)
                or seal.installation_id
                   != installed_bundle.installation_policy.installation_id):
            raise AuthorityDenied("context reply original worker identity differs")
        ready = getattr(port, "context_reply_paid_consumer_ready_v2", None)
        if not callable(ready) or ready(
                namespace=namespace, template_version=seal.template_version) is not True:
            raise UnavailableGuard("context reply paid consumer unavailable; HOLD")
        target = metadata.requirements
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("context reply acquire Authority anchor differs")
        if saved.state == "acquired":
            with store._lock:
                db.execute("BEGIN")
                try:
                    binding = read_original_context_reply_call_binding_v2(db, saved)
                    db.execute("COMMIT")
                except BaseException:
                    db.execute("ROLLBACK")
                    raise
            if (binding is None or acquire_row is None
                    or acquire_row[5] != "committed"
                    or job.phase != "running"
                    or job.lease_holder != authority.actor
                    or job.fence != binding.worker_fence):
                raise ContextReplyJobHold("acquired V2 call identity differs")
            self._finish_committed_post_c02_reply_fence_v1(
                namespace, metadata, epoch, anchor, acquire_row[1],
                acquire_row[2], acquire_row[3], acquire_row[4],
                "finish_reply_acquire")
            return job, binding.model_call_request
        if saved.state != "queued" or job.phase != "queued":
            raise ContextReplyJobHold("context reply original job is not queued")
        if (saved.graph_epoch != epoch.revision
                or saved.query_epoch.revision != epoch.revision):
            raise StaleRead("context reply original graph query changed")
        reading = port.read_ingress_clock(self.__scene_clock_policy)
        now = trusted_upper(reading)
        request_digest = canonical_digest({
            "schema": "sylanne.context-reply-acquire.v2",
            "seal": asdict(seal), "actor": authority.actor,
            "lease_seconds": lease_seconds, "expected_fence": job.fence,
        })
        if acquire_row is not None and acquire_row[0] != request_digest:
            raise EventConflict("context reply acquire identity reused")
        if acquire_row is not None and acquire_row[5] == "rejected":
            permit, state = port.get_fence_operation(
                namespace=namespace,
                authority_namespace=target.authority_namespace,
                operation_id=acquire_row[1],
            )
            if (type(permit) is not FencePermitV2
                    or state not in {"active", "finished"}
                    or permit.operation != "write"
                    or permit.operation_id != acquire_row[1]
                    or permit.holder != self.__holder
                    or permit.pinned_anchor != anchor):
                raise UnavailableGuard("context reply rejected fence differs; HOLD")
            if state == "active":
                scope = FenceScope(
                    namespace, target.authority_namespace,
                    authority.activation_generation, "write", acquire_row[1],
                    permit, anchor,
                    NamespaceEpoch(*namespace.as_tuple, acquire_row[4]),
                    acquire_row[3])
                port.finish_fence(
                    scope, request_id="abort:" + acquire_row[1],
                    request_digest="sha256:" + canonical_digest({
                        "action": "reject_context_reply_acquire",
                        "attempt_id": acquire_row[1],
                        "permit_token": permit.token,
                    }))
            raise ContextReplyJobHold("context reply acquire was rejected")
        with store._lock:
            db.execute("BEGIN IMMEDIATE")
            try:
                if self._v2_graph_stamp(namespace) != (metadata, epoch):
                    raise StaleRead("context reply graph changed before acquire intent")
                if acquire_row is None:
                    attempt_id = "context-reply-acquire-" + secrets.token_hex(24)
                    db.execute(
                        "INSERT INTO graph_context_reply_acquires_v2"
                        "(bot,persona,acquire_operation_id,request_digest,attempt_id,"
                        "anchor_json,graph_revision,graph_epoch,state) "
                        "VALUES(?,?,?,?,?,?,?,?,'open')",
                        namespace.as_tuple + (
                            seal.acquire_operation_id, request_digest, attempt_id,
                            canonical_json(asdict(anchor)),
                            metadata.graph_revision, epoch.revision),
                    )
                elif (acquire_row[2:5] == (
                        canonical_json(asdict(anchor)), metadata.graph_revision,
                        epoch.revision) and acquire_row[5] == "open"):
                    attempt_id = acquire_row[1]
                else:
                    raise ContextReplyJobHold("context reply acquire attempt unresolved")
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise
        try:
            permit, state = port.get_fence_operation(
                namespace=namespace, authority_namespace=target.authority_namespace,
                operation_id=attempt_id)
        except Exception:
            try:
                permit = port.begin_fence(
                    namespace=namespace,
                    authority_namespace=target.authority_namespace,
                    holder=self.__holder,
                    generation=authority.activation_generation,
                    operation="write", operation_id=attempt_id,
                    expected_anchor=anchor, retain_on_unknown=True)
                state = "active"
            except Exception:
                try:
                    permit, state = port.get_fence_operation(
                        namespace=namespace,
                        authority_namespace=target.authority_namespace,
                        operation_id=attempt_id)
                except Exception as exc:
                    raise UnavailableGuard(
                        "context reply acquire begin outcome unknown; HOLD") from exc
        if (type(permit) is not FencePermitV2 or state != "active"
                or permit.operation != "write" or permit.operation_id != attempt_id
                or permit.holder != self.__holder or permit.pinned_anchor != anchor):
            raise UnavailableGuard("context reply acquire write permit differs")
        scope = FenceScope(
            namespace, target.authority_namespace, authority.activation_generation,
            "write", attempt_id, permit, anchor, epoch, metadata.graph_revision)
        if port.validate_fence(scope) != permit:
            raise UnavailableGuard("context reply acquire write fence changed")
        now_text = datetime.fromtimestamp(now, timezone.utc).isoformat().replace(
            "+00:00", "Z")
        with store._lock:
            db.execute("BEGIN IMMEDIATE")
            commit_started = False
            try:
                if self._v2_graph_stamp(namespace) != (metadata, epoch):
                    raise StaleRead("context reply graph changed before acquire")
                current = read_original_context_reply_preparation_v2(
                    db, namespace, c02_operation_id, source_ref)
                if current != saved or get_job(db, job.job_id) != job:
                    raise ContextReplyJobHold("context reply original job changed")
                snapshot, attention = self._qualified_reply_attention_locked(
                    namespace, source_ref, now, epoch)
                if (set(snapshot.versions) != set(saved.read_versions)
                        or set(part.ref.ref for part in saved.frozen_request.input.evidence)
                           != set(attention.ticket.source_refs)
                        or now >= saved.frozen_request.input.expires_at_utc):
                    raise StaleRead("context reply current D06/D07 inputs changed")
                epochs = self._deletion_epochs_locked(db, namespace)
                if epochs != (saved.access_epoch, saved.delete_epoch):
                    raise StaleRead("context reply access barrier changed")
                reservation = db.execute(
                    "SELECT state FROM runtime_budget_reservations "
                    "WHERE lease_id=? AND operation_id=?",
                    (job.budget_ref, job.operation_id),
                ).fetchone()
                budget = get_budget_lease(db, job.budget_ref)
                if (reservation != ("reserved",) or budget.state != "active"
                        or (budget.bot_id, budget.persona_id) != namespace.as_tuple):
                    raise UnavailableGuard("context reply original budget unavailable")
                policy = installed_bundle.installation_policy
                if (policy.catalogue_hash != store._registry.catalogue_hash
                        or policy.scheme_version !=
                           self._version(db, namespace, "scheme", "current")
                        or policy.operator_version !=
                           self._version(db, namespace, "operator", "current")
                        or policy.policy_version !=
                           self._version(db, namespace, "policy", "current")):
                    raise StaleRead("context reply installed graph policy changed")
                if authority.audience != (
                        saved.frozen_request.input.conversation_ref,):
                    raise AuthorityDenied("context reply worker audience differs")
                planned = plan_job_acquire(
                    job, authority.actor, now_utc=now_text,
                    lease_seconds=lease_seconds)
                worker_authority = replace(authority, worker_fence=planned.fence)
                job_key = job_graph_write(job).key
                job_atom = db.execute(
                    "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                    (job_key.token,),
                ).fetchone()
                if (job_atom is None or job_atom[2] != 1
                        or json.loads(job_atom[1]) != job_graph_write(job).value):
                    raise ContextReplyJobHold("context reply graph job differs")
                reads = saved.read_versions + (
                    GraphVersion(job_key, job_atom[0] + 1),)
                guard = VersionGuard(
                    reads, (QueryEpoch(namespace, saved.query_epoch.scope_ref,
                                       epoch.revision + 1),),
                    saved.access_epoch, saved.delete_epoch,
                    store._registry.catalogue_hash,
                    self._version(db, namespace, "scheme", "current"),
                    self._version(db, namespace, "operator", "current"),
                    self._version(db, namespace, "policy", "current"),
                    (), (), (),
                )
                source_atom = snapshot.get(AtomKey.from_token(source_ref))
                record = SourceRecord.from_dict(source_atom.value)
                family, reality, eligibility = {
                    "observed": ("observed", "external_observation", "qualified"),
                    "reported": ("reported", "external_report", "qualified"),
                    "authored": ("authored", "authored_content", "ineligible"),
                    "internal": ("derived", "inference", "ineligible"),
                    "simulated": ("simulated", "simulation", "ineligible"),
                }[record.source_kind]
                refs = tuple(part.ref.ref
                             for part in saved.frozen_request.input.evidence)
                qualification = SourceQualification(
                    refs, family, record.occurred_at, record.recorded_at,
                    reality, eligibility, None, "not_applicable")
                identity = OperationIdentity(
                    job.activity_id, None, attempt_id, "context_reply",
                    seal.acquire_operation_id,
                    canonical_digest({"input_refs": list(refs)}))
                lease_deadline = datetime.fromisoformat(
                    planned.lease_expires_utc.replace("Z", "+00:00")).timestamp()
                job_deadline = datetime.fromisoformat(
                    planned.deadline_utc.replace("Z", "+00:00")).timestamp()
                deadline = min(lease_deadline, job_deadline)
                if now >= deadline:
                    raise ContextReplyJobHold("context reply acquire deadline expired")
                envelope = CommandEnvelope(
                    RUNTIME_SCHEMA, identity, worker_authority, guard,
                    qualification, refs, job.budget_ref, deadline,
                    reading.monotonic_after_seconds + (deadline - now),
                    "context-reply:" + c02_operation_id,
                    (c02_operation_id, seal.original_operation_id),
                )
                call = ModelCallRequest(
                    envelope, seal.call_id, workflow.provider_id,
                    workflow.model_id, frozenset(workflow.required_capabilities),
                    workflow.privacy_tier, CONTEXT_REPLY_TEMPLATE_DIGEST,
                    json.loads(saved.frozen_request.canonical_wire),
                    workflow.timeout_seconds, workflow.max_output_tokens)
                acquired = acquire_job(
                    db, job.job_id, authority.actor, now_utc=now_text,
                    lease_seconds=lease_seconds)
                if acquired != planned:
                    raise ContextReplyJobHold("context reply D11 acquire CAS differed")
                bind_original_context_reply_call_v2(db, saved, acquired, call)
                write = job_graph_write(acquired)
                reconcile_runtime_write(db, write)
                graph_candidate = GraphCandidate(
                    Event(Scope(*namespace.as_tuple, job.activity_id),
                          seal.acquire_operation_id, now, "domain_bundle",
                          {"bundle_digest": request_digest}),
                    (GraphVersion(job_key, job_atom[0]),) + saved.read_versions,
                    (GraphWrite(write.key, write.value,
                                tuple(atom.key for atom in snapshot.atoms
                                      if atom.valid)),),
                    (epoch,),
                )
                graph_receipt = GraphStore._graph_commit_in_transaction(
                    store, graph_candidate, _capability=self.__graph_capability)
                if graph_receipt.status != "committed":
                    raise EventConflict("context reply acquire graph event differs")
                store.cas_graph_recovery_metadata(
                    metadata, metadata.requirements,
                    _capability=self.__graph_capability)
                db.execute(
                    "UPDATE graph_context_reply_acquires_v2 SET state='committed' "
                    "WHERE bot=? AND persona=? AND acquire_operation_id=? "
                    "AND attempt_id=? AND state='open'",
                    namespace.as_tuple + (seal.acquire_operation_id, attempt_id),
                )
                if db.execute("SELECT changes()").fetchone() != (1,):
                    raise EventConflict("context reply acquire receipt differs")
                commit_started = True
                db.execute("COMMIT")
            except BaseException as exc:
                if db.in_transaction:
                    db.execute("ROLLBACK")
                if commit_started or not isinstance(exc, Exception):
                    raise
                failure = exc
            else:
                failure = None
        if failure is not None:
            with store._lock:
                db.execute(
                    "UPDATE graph_context_reply_acquires_v2 SET state='rejected' "
                    "WHERE bot=? AND persona=? AND acquire_operation_id=? "
                    "AND attempt_id=? AND state='open'",
                    namespace.as_tuple + (seal.acquire_operation_id, attempt_id),
                )
            port.finish_fence(
                scope, request_id="abort:" + attempt_id,
                request_digest="sha256:" + canonical_digest({
                    "action": "reject_context_reply_acquire",
                    "attempt_id": attempt_id, "permit_token": permit.token,
                }))
            raise failure
        port.finish_fence(
            scope, request_id="finish:" + attempt_id,
            request_digest="sha256:" + canonical_digest({
                "action": "finish_reply_acquire", "attempt_id": attempt_id,
                "permit_token": permit.token,
            }))
        return acquired, call

    def complete_natural_generation_model_job_v2(
        self, authority: AuthorityContext, lease: object,
        parent_original_id: str, original_intent, installed_bundle,
    ):
        return self._complete_natural_model_job_v2(
            authority, lease, parent_original_id, original_intent,
            installed_bundle, stage="generation")

    def complete_natural_review_model_job_v2(
        self, authority: AuthorityContext, lease: object,
        parent_original_id: str, original_intent, installed_bundle,
    ):
        return self._complete_natural_model_job_v2(
            authority, lease, parent_original_id, original_intent,
            installed_bundle, stage="review")

    def _complete_natural_model_job_v2(
        self, authority: AuthorityContext, lease: object,
        parent_original_id: str, original_intent, installed_bundle, *, stage: str,
    ):
        """Commit either paid natural stage and D11 terminal in one graph fence."""
        from .authority_service.v2_contract import FencePermitV2
        from .authority_service.v2_model_egress_contract import ModelEgressIntentV1
        from .authority_service.v2_natural_generation_output_contract import (
            NaturalGenerationOriginalOutputV2, from_wire as natural_output_from_wire,
        )
        from .authority_service.v2_natural_review_output_contract import (
            NaturalReviewOriginalOutputV2, from_wire as review_output_from_wire,
        )
        from .runtime.d11_types import job_graph_write
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.jobs import transition_job
        from .runtime.model_cost_settlement import (
            original_model_cost_operation_id_v1, read_original_model_cost,
        )
        from .runtime.natural_generation_issue_v2 import install_attempt_schema
        from .runtime.natural_review_issue_v2 import install_review_attempt_schema
        from .runtime.natural_reply_job_v2 import (
            read_original_call_binding, read_original_preparation,
            record_terminal,
        )

        store, port, namespace = self.__store, self.__content_fence_v2, authority.namespace
        output_port = (self.__natural_generation_output_port
                       if stage == "generation" else self.__natural_review_output_port)
        output_kind = (NaturalGenerationOriginalOutputV2
                       if stage == "generation" else NaturalReviewOriginalOutputV2)
        output_from_wire = (natural_output_from_wire
                            if stage == "generation" else review_output_from_wire)
        terminal_table = ("graph_natural_generation_terminals_v2"
                          if stage == "generation" else
                          "graph_natural_review_terminals_v2")
        output_reads_table = ("graph_natural_generation_output_reads_v2"
                              if stage == "generation" else
                              "graph_natural_review_output_reads_v2")
        if (stage not in {"generation", "review"}
                or not isinstance(store, ProductionGraphStore) or port is None
                or type(original_intent) is not ModelEgressIntentV1
                or self.__model_terminal_cost_port is None
                or output_port is None):
            raise UnavailableGuard("natural paid terminal authorities absent; HOLD")
        self._authorize(lease, authority, frozenset({"d11"}))
        fact = read_original_model_cost(self.__model_terminal_cost_port, original_intent)
        if fact.recovery.state != "observed":
            raise UnavailableGuard("unobserved natural generation call; HOLD")
        intent_digest = canonical_digest(asdict(original_intent))
        terminal_digest = canonical_digest(asdict(fact.receipt))
        with store._lock:
            db = store._db
            install_attempt_schema(db)
            install_review_attempt_schema(db)
            db.execute("BEGIN")
            try:
                prior = read_original_preparation(
                    db, namespace, parent_original_id, stage)
                if prior is None:
                    raise UnavailableGuard("natural paid original absent; HOLD")
                terminal_row = db.execute(
                    "SELECT request_digest,attempt_id,anchor_json,graph_revision,"
                    "graph_epoch,terminal_receipt_digest,output_digest,"
                    f"output_receipt_json,state FROM {terminal_table} WHERE bot=? AND "
                    "persona=? AND original_operation_id=?",
                    namespace.as_tuple + (prior.seal.original_operation_id,),
                ).fetchone()
                prior_job = get_job(db, prior.seal.job_id)
                metadata, epoch = self._v2_graph_stamp(namespace)
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise
        operation_id = "natural-" + stage + "-terminal-" + canonical_digest({
            "namespace": namespace.as_tuple,
            "original_operation_id": prior.seal.original_operation_id,
        })[:48]
        if (authority.issuer_domain != "d11" or authority.purpose != "proposal"
                or "activity" not in authority.owner_scope
                or authority.worker_fence is not None
                or authority.capability_ref != _operation_capability_ref(
                    namespace, authority.actor, "d11", frozenset({"d11"}),
                    authority.activation_generation, operation_id)):
            raise AuthorityDenied("natural paid terminal worker authority differs")
        if prior.state == "terminal":
            if (terminal_row is None or terminal_row[8] != "committed"
                    or terminal_row[5] != terminal_digest
                    or terminal_row[6] != prior.terminal_output_digest
                    or prior.terminal_receipt_digest != terminal_digest
                    or prior_job.phase != "completed"
                    or prior_job.result_ref != prior.seal.call_id):
                raise UnavailableGuard("natural paid terminal replay differs; HOLD")
            anchor = port.current_anchor(
                namespace=namespace,
                authority_namespace=metadata.requirements.authority_namespace)
            if not self._anchor_matches(metadata.requirements, anchor):
                raise UnavailableGuard("natural paid terminal anchor changed; HOLD")
            self._finish_committed_post_c02_reply_fence_v1(
                namespace, metadata, epoch, anchor, terminal_row[1],
                terminal_row[2], terminal_row[3], terminal_row[4],
                "finish_natural_" + stage)
            return prior_job
        now = trusted_upper(port.read_ingress_clock(self.__scene_clock_policy))
        if terminal_row is None:
            with store._lock:
                db.execute("BEGIN IMMEDIATE")
                try:
                    row = db.execute(
                        "SELECT last_attempt FROM "
                        f"{output_reads_table} WHERE bot=? "
                        "AND persona=? AND original_operation_id=?",
                        namespace.as_tuple + (prior.seal.original_operation_id,),
                    ).fetchone()
                    output_attempt = 1 if row is None else row[0] + 1
                    if output_attempt > 64:
                        raise UnavailableGuard(
                            "natural paid output attempts exhausted; HOLD")
                    db.execute(
                        f"INSERT INTO {output_reads_table}"
                        "(bot,persona,original_operation_id,last_attempt) "
                        "VALUES(?,?,?,?) ON CONFLICT(bot,persona,"
                        "original_operation_id) DO UPDATE SET "
                        "last_attempt=excluded.last_attempt",
                        namespace.as_tuple + (prior.seal.original_operation_id,
                                              output_attempt),
                    )
                    db.execute("COMMIT")
                except BaseException:
                    db.execute("ROLLBACK")
                    raise
            request = (self.read_natural_generation_output_request_v2(
                authority, lease, parent_original_id, installed_bundle,
                attempt=output_attempt) if stage == "generation" else
                self.read_natural_review_output_request_v2(
                    authority, lease, parent_original_id, installed_bundle,
                    attempt=output_attempt))
            output = output_port(request, now_utc=now)
        elif terminal_row[8] == "open":
            output = output_from_wire(
                json.loads(terminal_row[7]), output_kind)
            request = output.request
        else:
            raise UnavailableGuard("natural paid terminal attempt rejected; HOLD")
        if (type(output) is not output_kind
                or output.request != request
                or output.original_intent_digest != intent_digest
                or output.terminal_receipt_digest != terminal_digest):
            raise UnavailableGuard("original natural paid result unavailable; HOLD")

        def original_locked(db):
            saved = read_original_preparation(
                db, namespace, parent_original_id, stage)
            if saved is None or saved.state != "acquired":
                raise UnavailableGuard("natural paid original not acquired; HOLD")
            binding = read_original_call_binding(db, saved)
            seal = saved.seal
            job = get_job(db, seal.job_id)
            cost_id = original_model_cost_operation_id_v1(namespace, seal.call_id)
            cost = db.execute(
                "SELECT receipt_json FROM graph_bundle_operations WHERE bot=? "
                "AND persona=? AND operation_id=?",
                namespace.as_tuple + (cost_id,),
            ).fetchone()
            cost_data = json.loads(cost[0]) if cost is not None else {}
            committed = cost_data.get("original_model_cost", {})
            if (binding is None or output.original_seal_digest !=
                    canonical_digest(asdict(seal))
                    or output.typed_model_request_digest != binding.request.digest
                    or (original_intent.job_id, original_intent.operation_id,
                        original_intent.acquire_operation_id,
                        original_intent.call_id, original_intent.request_digest,
                        original_intent.worker_fence,
                        original_intent.budget_reservation_operation_id)
                       != (seal.job_id, seal.acquire_operation_id,
                           seal.acquire_operation_id, seal.call_id,
                           binding.request.digest, binding.worker_fence,
                           seal.reservation_operation_id)
                    or (job.operation_id, job.work_kind, job.phase,
                        job.lease_holder, job.fence) != (
                            seal.original_operation_id, "natural_" + stage,
                            "running", authority.actor, binding.worker_fence)
                    or cost_data.get("original_intent_digest") != intent_digest
                    or cost_data.get("terminal_receipt_digest") != terminal_digest
                    or committed.get("status") != "committed"
                    or committed.get("call_id") != seal.call_id
                    or committed.get("operation_id") != cost_id):
                raise UnavailableGuard("natural paid original differs; HOLD")
            return saved, job

        with store._lock:
            db = store._db
            install_attempt_schema(db)
            db.execute("BEGIN")
            try:
                saved, job = original_locked(db)
                metadata, epoch = self._v2_graph_stamp(namespace)
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise
        request_digest = canonical_digest({
            "operation_id": operation_id, "seal": asdict(saved.seal),
            "original_intent_digest": intent_digest,
            "terminal_receipt_digest": terminal_digest,
            "output_digest": output.output_digest,
        })
        target = metadata.requirements
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("natural paid terminal anchor differs; HOLD")
        if terminal_row is not None:
            if (terminal_row[8] != "open"
                    or terminal_row[0] != request_digest
                    or terminal_row[2:5] != (
                        canonical_json(asdict(anchor)), metadata.graph_revision,
                        epoch.revision)
                    or terminal_row[5:7] != (
                        terminal_digest, output.output_digest)):
                raise UnavailableGuard("natural paid terminal attempt differs; HOLD")
            attempt_id = terminal_row[1]
        else:
            attempt_id = "natural-" + stage + "-terminal-write-" + secrets.token_hex(24)
            with store._lock:
                db.execute("BEGIN IMMEDIATE")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise StaleRead("natural paid terminal graph changed")
                    db.execute(
                        f"INSERT INTO {terminal_table}"
                        "(bot,persona,original_operation_id,request_digest,attempt_id,"
                        "anchor_json,graph_revision,graph_epoch,terminal_receipt_digest,"
                        "output_digest,output_receipt_json,state) "
                        "VALUES(?,?,?,?,?,?,?,?,?,?,?,'open')",
                        namespace.as_tuple + (saved.seal.original_operation_id,
                        request_digest, attempt_id, canonical_json(asdict(anchor)),
                        metadata.graph_revision, epoch.revision,
                        terminal_digest, output.output_digest,
                        canonical_json(asdict(output))),
                    )
                    db.execute("COMMIT")
                except BaseException:
                    db.execute("ROLLBACK")
                    raise
        try:
            permit, state = port.get_fence_operation(
                namespace=namespace,
                authority_namespace=target.authority_namespace,
                operation_id=attempt_id)
        except Exception as exc:
            try:
                permit = port.begin_fence(
                    namespace=namespace,
                    authority_namespace=target.authority_namespace,
                    holder=self.__holder, generation=authority.activation_generation,
                    operation="write", operation_id=attempt_id,
                    expected_anchor=anchor, retain_on_unknown=True)
                state = "active"
            except Exception as begin_exc:
                raise UnavailableGuard(
                    "natural paid terminal begin unknown; HOLD") from begin_exc
        if state != "active":
            raise UnavailableGuard("natural paid terminal fence unresolved; HOLD")
        if (type(permit) is not FencePermitV2 or permit.operation != "write"
                or permit.operation_id != attempt_id or permit.holder != self.__holder
                or permit.pinned_anchor != anchor):
            raise UnavailableGuard("natural paid terminal permit differs; HOLD")
        scope = FenceScope(
            namespace, target.authority_namespace, authority.activation_generation,
            "write", attempt_id, permit, anchor, epoch, metadata.graph_revision)
        if port.validate_fence(scope) != permit:
            raise UnavailableGuard("natural paid terminal write fence changed; HOLD")
        with store._lock:
            db.execute("BEGIN IMMEDIATE")
            try:
                if self._v2_graph_stamp(namespace) != (metadata, epoch):
                    raise StaleRead("natural paid terminal graph changed")
                current, running = original_locked(db)
                if current != saved or running != job:
                    raise StaleRead("natural paid original changed")
                before = job_graph_write(job)
                atom = db.execute(
                    "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                    (before.key.token,),
                ).fetchone()
                if (atom is None or atom[2] != 1
                        or json.loads(atom[1]) != before.value):
                    raise UnavailableGuard("natural paid graph job differs; HOLD")
                completed = transition_job(
                    db, job.job_id, authority.actor, job.fence,
                    target_phase="completed", result_ref=saved.seal.call_id)
                write = job_graph_write(completed)
                reconcile_runtime_write(db, write)
                receipt = GraphStore._graph_commit_in_transaction(
                    store, GraphCandidate(
                        Event(Scope(*namespace.as_tuple, job.activity_id),
                              operation_id, now, "domain_bundle",
                              {"original_call_id": saved.seal.call_id,
                               "terminal_receipt_digest": terminal_digest,
                               "output_digest": output.output_digest}),
                        (GraphVersion(write.key, atom[0]),), (write,), (epoch,)),
                    _capability=self.__graph_capability)
                if receipt.status != "committed":
                    raise EventConflict("natural paid terminal graph event differs")
                store.cas_graph_recovery_metadata(
                    metadata, metadata.requirements,
                    _capability=self.__graph_capability)
                record_terminal(
                    db, saved, completed,
                    terminal_receipt_digest=terminal_digest,
                    output_digest=output.output_digest)
                changed = db.execute(
                    f"UPDATE {terminal_table} "
                    "SET state='committed' WHERE bot=? AND persona=? "
                    "AND original_operation_id=? AND attempt_id=? AND state='open'",
                    namespace.as_tuple + (saved.seal.original_operation_id,
                                          attempt_id),
                ).rowcount
                if changed != 1:
                    raise EventConflict("natural paid terminal receipt differs")
                db.execute("COMMIT")
            except BaseException as exc:
                db.execute("ROLLBACK")
                failure = exc
            else:
                failure = None
        if failure is not None:
            with store._lock:
                db.execute(
                    f"UPDATE {terminal_table} "
                    "SET state='rejected' WHERE bot=? AND persona=? "
                    "AND original_operation_id=? AND attempt_id=? AND state='open'",
                    namespace.as_tuple + (saved.seal.original_operation_id,
                                          attempt_id),
                )
            port.finish_fence(
                scope, request_id="abort:" + attempt_id,
                request_digest="sha256:" + canonical_digest({
                    "action": "reject_natural_" + stage + "_terminal",
                    "attempt_id": attempt_id, "permit_token": permit.token,
                }))
            raise failure
        port.finish_fence(
            scope, request_id="finish:" + attempt_id,
            request_digest="sha256:" + canonical_digest({
                "action": "finish_natural_" + stage,
                "attempt_id": attempt_id, "permit_token": permit.token,
            }))
        return completed

    def read_natural_generation_terminal_receipt_v2(
        self, authority: AuthorityContext, lease: object,
        parent_original_id: str, installed_bundle,
    ):
        return self._read_natural_terminal_receipt_v2(
            authority, lease, parent_original_id, installed_bundle,
            stage="generation")

    def read_natural_review_terminal_receipt_v2(
        self, authority: AuthorityContext, lease: object,
        parent_original_id: str, installed_bundle,
    ):
        return self._read_natural_terminal_receipt_v2(
            authority, lease, parent_original_id, installed_bundle,
            stage="review")

    def _read_natural_terminal_receipt_v2(
        self, authority: AuthorityContext, lease: object,
        parent_original_id: str, installed_bundle, *, stage: str,
    ):
        """Return the durable content-free original result after graph terminal."""
        from .authority_service.v2_natural_generation_output_contract import (
            NaturalGenerationOriginalOutputV2, from_wire as generation_from_wire,
        )
        from .authority_service.v2_natural_review_output_contract import (
            NaturalReviewOriginalOutputV2, from_wire as review_from_wire,
        )
        from .host.authority_profile import AdminInstallationBundle
        from .runtime.d11_types import job_graph_write
        from .runtime.natural_reply_job_v2 import read_original_preparation

        store, namespace = self.__store, authority.namespace
        terminal_table = ("graph_natural_generation_terminals_v2"
                          if stage == "generation" else
                          "graph_natural_review_terminals_v2")
        output_kind = (NaturalGenerationOriginalOutputV2 if stage == "generation"
                       else NaturalReviewOriginalOutputV2)
        output_from_wire = (generation_from_wire if stage == "generation"
                            else review_from_wire)
        if (stage not in {"generation", "review"}
                or not isinstance(store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or type(installed_bundle) is not AdminInstallationBundle
                or installed_bundle.installation_policy.namespace != namespace):
            raise UnavailableGuard("natural generation terminal reader unavailable; HOLD")
        self._authorize(lease, authority, frozenset({"d11"}), owner_read=True)
        if authority.issuer_domain != "d11" or authority.purpose != "proposal":
            raise AuthorityDenied("natural generation terminal reader differs")

        def reader():
            db = store._db
            db.execute("BEGIN")
            try:
                saved = read_original_preparation(
                    db, namespace, parent_original_id, stage)
                if saved is None or saved.state != "terminal":
                    raise UnavailableGuard("natural paid stage not terminal; HOLD")
                row = db.execute(
                    "SELECT terminal_receipt_digest,output_digest,"
                    f"output_receipt_json,state FROM {terminal_table} WHERE bot=? "
                    "AND persona=? AND original_operation_id=?",
                    namespace.as_tuple + (saved.seal.original_operation_id,),
                ).fetchone()
                job = get_job(db, saved.seal.job_id)
                job_atom = db.execute(
                    "SELECT value,valid FROM graph_atoms WHERE token=?",
                    (job_graph_write(job).key.token,),
                ).fetchone()
                if (row is None or row[3] != "committed"
                        or job.phase != "completed"
                        or job.result_ref != saved.seal.call_id
                        or job_atom is None or job_atom[1] != 1
                        or json.loads(job_atom[0]) != job_graph_write(job).value):
                    raise UnavailableGuard("natural generation terminal graph differs; HOLD")
                output = output_from_wire(json.loads(row[2]), output_kind)
                if (output.request.original_operation_id !=
                        saved.seal.original_operation_id
                        or output.request.job_id != saved.seal.job_id
                        or output.request.installation_id !=
                           installed_bundle.installation_policy.installation_id
                        or output.original_seal_digest !=
                           canonical_digest(asdict(saved.seal))
                        or (output.terminal_receipt_digest,
                            output.output_digest) != row[:2]
                        or (saved.terminal_receipt_digest,
                            saved.terminal_output_digest) != row[:2]):
                    raise UnavailableGuard("natural generation original result differs; HOLD")
                db.execute("COMMIT")
                return output
            except BaseException:
                db.execute("ROLLBACK")
                raise

        return self._read_v2(authority, reader)

    def read_natural_generation_content_request_v2(
        self, authority: AuthorityContext, lease: object,
        parent_original_id: str, installed_bundle, *, attempt: int = 1,
    ):
        """Derive a review-only content request from the paid terminal row."""
        from .authority_service.v2_natural_generation_content_contract import (
            NaturalGenerationContentReadRequestV2,
            natural_generation_content_attempt_id_v2,
        )
        from .authority_service.v2_natural_generation_output_contract import (
            NaturalGenerationOriginalOutputV2, from_wire,
        )
        from .host.authority_profile import AdminInstallationBundle
        from .runtime.d11_types import job_graph_write
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.model_cost_settlement import original_model_cost_operation_id_v1
        from .runtime.natural_generation_issue_v2 import (
            read_original_scoped_query_proof_v2,
        )
        from .runtime.natural_reply_job_v2 import (
            read_original_call_binding, read_original_preparation,
        )

        store, port, namespace = self.__store, self.__content_fence_v2, authority.namespace
        if (not isinstance(store, ProductionGraphStore) or port is None
                or type(installed_bundle) is not AdminInstallationBundle
                or installed_bundle.installation_policy.namespace != namespace):
            raise UnavailableGuard("natural review content reader unavailable; HOLD")
        self._authorize(lease, authority, frozenset({"d11"}), owner_read=True)
        if authority.issuer_domain != "d11" or authority.purpose != "proposal":
            raise AuthorityDenied("natural review content reader differs")
        now = trusted_upper(port.read_ingress_clock(self.__scene_clock_policy))

        def reader():
            db = store._db
            db.execute("BEGIN")
            try:
                metadata, epoch = self._v2_graph_stamp(namespace)
                saved = read_original_preparation(
                    db, namespace, parent_original_id, "generation")
                if saved is None or saved.state != "terminal":
                    raise UnavailableGuard("generation original is not terminal; HOLD")
                seal = saved.seal
                job = get_job(db, seal.job_id)
                binding = read_original_call_binding(db, saved)
                job_atom = db.execute(
                    "SELECT value,valid FROM graph_atoms WHERE token=?",
                    (job_graph_write(job).key.token,),
                ).fetchone()
                cost_id = original_model_cost_operation_id_v1(namespace, seal.call_id)
                cost = db.execute(
                    "SELECT receipt_json FROM graph_bundle_operations WHERE bot=? "
                    "AND persona=? AND operation_id=?",
                    namespace.as_tuple + (cost_id,),
                ).fetchone()
                cost_data = json.loads(cost[0]) if cost is not None else {}
                row = db.execute(
                    "SELECT terminal_receipt_digest,output_digest,"
                    "output_receipt_json,state FROM "
                    "graph_natural_generation_terminals_v2 WHERE bot=? "
                    "AND persona=? AND original_operation_id=?",
                    namespace.as_tuple + (seal.original_operation_id,),
                ).fetchone()
                if row is None or binding is None or row[3] != "committed":
                    raise UnavailableGuard("natural paid terminal absent; HOLD")
                output = from_wire(
                    json.loads(row[2]), NaturalGenerationOriginalOutputV2)
                (plan_write, _plan_reads, current_frozen, _reads,
                 _all_query, _role_query, _boundary_query, _barrier,
                 scoped, _candidate, _snapshot) = (
                    self._prepare_natural_generation_scope_locked(
                    namespace, parent_original_id, seal.source_ref,
                    installed_bundle, now, epoch,
                    original_deadline=saved.frozen.input.plan.valid_until_utc,
                    frozen_original=saved.frozen))
                if (output.status != "untrusted_content_candidate"
                        or output.request.original_operation_id !=
                           seal.original_operation_id
                        or output.request.typed_model_request_digest !=
                           binding.request.digest
                        or output.original_seal_digest !=
                           canonical_digest(asdict(seal))
                        or (output.terminal_receipt_digest,
                            output.output_digest) != row[:2]
                        or (saved.terminal_receipt_digest,
                            saved.terminal_output_digest) != row[:2]
                        or (job.phase, job.result_ref) !=
                           ("completed", seal.call_id)
                        or job_atom is None or job_atom[1] != 1
                        or json.loads(job_atom[0]) != job_graph_write(job).value
                        or cost_data.get("terminal_receipt_digest") != row[0]
                        or cost_data.get("original_model_cost", {}).get(
                            "status") != "committed"
                        or current_frozen.input.plan != saved.frozen.input.plan
                        or plan_write.key.token != saved.frozen.input.plan.plan_ref.ref
                        or read_original_scoped_query_proof_v2(db, saved) != scoped
                        or authority.audience !=
                           (saved.frozen.input.plan.audience_id,)):
                    raise UnavailableGuard("natural review content scope changed; HOLD")
                plan = saved.frozen.input.plan
                result = NaturalGenerationContentReadRequestV2(
                    metadata.requirements.authority_id,
                    metadata.requirements.authority_namespace,
                    namespace, seal.c02_operation_id, seal.source_ref,
                    seal.installation_id, seal.job_id,
                    seal.original_operation_id, seal.acquire_operation_id,
                    seal.call_id, binding.request.digest,
                    canonical_digest(asdict(seal)), row[0], row[1],
                    plan.scene_id, plan.audience_id, "review",
                    natural_generation_content_attempt_id_v2(
                        seal.original_operation_id, attempt),
                )
                db.execute("COMMIT")
                return result
            except BaseException:
                db.execute("ROLLBACK")
                raise

        return self._read_v2(authority, reader)

    def complete_post_c02_context_reply_model_job_v2(
            self, authority: AuthorityContext, lease: object,
            c02_operation_id: str, source_ref: str, original_intent):
        """Close one paid original call and its D11 job in a fenced graph txn."""
        from .authority_service.v2_contract import FencePermitV2
        from .authority_service.v2_model_egress_contract import ModelEgressIntentV1
        from .runtime.context_reply_job_v2 import (
            ContextReplyJobHold, install_schema as install_context_schema,
            read_original_context_reply_call_binding_v2,
            read_original_context_reply_preparation_v2,
        )
        from .runtime.d11_types import job_graph_write
        from .runtime.jobs import transition_job
        from .runtime.model_cost_settlement import (
            original_model_cost_operation_id_v1, read_original_model_cost,
        )

        store, port, namespace = self.__store, self.__content_fence_v2, authority.namespace
        if (not isinstance(store, ProductionGraphStore) or port is None
                or type(original_intent) is not ModelEgressIntentV1
                or self.__model_terminal_cost_port is None):
            raise UnavailableGuard("original V2 terminal authorities absent; HOLD")
        self._authorize(lease, authority, frozenset({"d11"}))
        fact = read_original_model_cost(self.__model_terminal_cost_port, original_intent)
        if fact.recovery.state != "observed":
            raise UnavailableGuard("unobserved original V2 call cannot complete")
        terminal_digest = canonical_digest(asdict(fact.receipt))
        intent_digest = canonical_digest(asdict(original_intent))
        operation_id = "context-reply-terminal-" + canonical_digest({
            "namespace": namespace.as_tuple,
            "original_operation_id": original_intent.budget_reservation_operation_id,
        })[:48]
        if (authority.issuer_domain != "d11" or authority.purpose != "proposal"
                or "activity" not in authority.owner_scope
                or authority.worker_fence is not None
                or authority.capability_ref != _operation_capability_ref(
                    namespace, authority.actor, "d11", frozenset({"d11"}),
                    authority.activation_generation, operation_id)):
            raise AuthorityDenied("original V2 terminal worker authority differs")

        def original_locked(db, *, completed=False):
            saved = read_original_context_reply_preparation_v2(
                db, namespace, c02_operation_id, source_ref)
            if saved is None:
                raise ContextReplyJobHold("original V2 preparation absent")
            seal = saved.seal
            binding = read_original_context_reply_call_binding_v2(db, saved)
            job = get_job(db, seal.job_id)
            frozen = saved.frozen_request
            if (binding is None
                    or (original_intent.job_id, original_intent.operation_id,
                        original_intent.acquire_operation_id,
                        original_intent.call_id, original_intent.request_digest,
                        original_intent.worker_fence,
                        original_intent.budget_reservation_operation_id,
                        original_intent.provider_config_digest)
                       != (seal.job_id, seal.acquire_operation_id,
                           seal.acquire_operation_id, seal.call_id,
                           binding.model_call_request_digest,
                           binding.worker_fence, seal.original_operation_id,
                           seal.provider_config_digest)
                    or (job.operation_id, job.work_kind, job.fence,
                        job.lease_holder, job.phase, saved.state)
                       != (seal.original_operation_id, "context_reply",
                           binding.worker_fence,
                           None if completed else authority.actor,
                           "completed" if completed else "running",
                           "terminal" if completed else "acquired")
                    or original_intent.subject != authority.actor
                    or original_intent.provider_id != frozen.installation.provider_id
                    or original_intent.model_id != frozen.installation.model_id
                    or original_intent.max_output_tokens !=
                       frozen.installation.max_output_tokens):
                raise ContextReplyJobHold("original V2 paid call or job differs")
            cost_id = original_model_cost_operation_id_v1(namespace, seal.call_id)
            cost = db.execute(
                "SELECT receipt_json FROM graph_bundle_operations WHERE bot=? "
                "AND persona=? AND operation_id=?",
                namespace.as_tuple + (cost_id,),
            ).fetchone()
            if cost is None:
                raise ContextReplyJobHold("original V2 cost is not durable")
            cost_data = json.loads(cost[0])
            committed = cost_data.get("original_model_cost", {})
            if (cost_data.get("original_intent_digest") != intent_digest
                    or cost_data.get("terminal_receipt_digest") != terminal_digest
                    or committed.get("status") != "committed"
                    or committed.get("call_id") != seal.call_id
                    or committed.get("operation_id") != cost_id):
                raise ContextReplyJobHold("original V2 cost identity differs")
            return saved, job

        with store._lock:
            db = store._db
            install_context_schema(db)
            db.execute("BEGIN")
            try:
                row = db.execute(
                    "SELECT request_digest,attempt_id,anchor_json,graph_revision,"
                    "graph_epoch,terminal_receipt_digest,state FROM "
                    "graph_context_reply_terminals_v2 WHERE bot=? AND persona=? "
                    "AND original_operation_id=?",
                    namespace.as_tuple +
                    (original_intent.budget_reservation_operation_id,),
                ).fetchone()
                if row is None:
                    saved, job = original_locked(db)
                else:
                    saved, job = original_locked(db, completed=row[6] == "committed")
                metadata, epoch = self._v2_graph_stamp(namespace)
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise
        request_digest = canonical_digest({
            "operation_id": operation_id, "seal": asdict(saved.seal),
            "original_intent_digest": intent_digest,
            "terminal_receipt_digest": terminal_digest,
            "worker_fence": job.fence,
        })
        target = metadata.requirements
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("original V2 terminal anchor differs; HOLD")
        if row is not None:
            if row[0] != request_digest or row[5] != terminal_digest:
                raise EventConflict("original V2 terminal identity reused")
            if row[6] == "committed":
                self._finish_committed_post_c02_reply_fence_v1(
                    namespace, metadata, epoch, anchor, row[1], row[2],
                    row[3], row[4], "finish_context_reply_terminal")
                return job
            if (row[6] != "open" or row[2:5] != (
                    canonical_json(asdict(anchor)), metadata.graph_revision,
                    epoch.revision)):
                raise UnavailableGuard("original V2 terminal attempt unresolved; HOLD")
            attempt_id = row[1]
        else:
            attempt_id = "context-reply-terminal-write-" + secrets.token_hex(24)
            with store._lock:
                db.execute("BEGIN IMMEDIATE")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise StaleRead("original V2 terminal graph changed")
                    db.execute(
                        "INSERT INTO graph_context_reply_terminals_v2"
                        "(bot,persona,original_operation_id,request_digest,attempt_id,"
                        "anchor_json,graph_revision,graph_epoch,terminal_receipt_digest,"
                        "state) VALUES(?,?,?,?,?,?,?,?,?,'open')",
                        namespace.as_tuple + (saved.seal.original_operation_id,
                        request_digest, attempt_id, canonical_json(asdict(anchor)),
                        metadata.graph_revision, epoch.revision, terminal_digest),
                    )
                    db.execute("COMMIT")
                except BaseException:
                    db.execute("ROLLBACK")
                    raise
        try:
            permit, state = port.get_fence_operation(
                namespace=namespace,
                authority_namespace=target.authority_namespace,
                operation_id=attempt_id)
        except Exception:
            try:
                permit = port.begin_fence(
                    namespace=namespace,
                    authority_namespace=target.authority_namespace,
                    holder=self.__holder, generation=authority.activation_generation,
                    operation="write", operation_id=attempt_id,
                    expected_anchor=anchor, retain_on_unknown=True)
                state = "active"
            except Exception as exc:
                raise UnavailableGuard("original V2 terminal begin unknown; HOLD") from exc
        if state != "active":
            raise UnavailableGuard("original V2 terminal fence unresolved; HOLD")
        if (type(permit) is not FencePermitV2 or permit.operation != "write"
                or permit.operation_id != attempt_id or permit.holder != self.__holder
                or permit.pinned_anchor != anchor):
            raise UnavailableGuard("original V2 terminal permit differs; HOLD")
        scope = FenceScope(
            namespace, target.authority_namespace, authority.activation_generation,
            "write", attempt_id, permit, anchor, epoch, metadata.graph_revision)
        if port.validate_fence(scope) != permit:
            raise UnavailableGuard("original V2 terminal write fence changed; HOLD")
        with store._lock:
            db.execute("BEGIN IMMEDIATE")
            try:
                if self._v2_graph_stamp(namespace) != (metadata, epoch):
                    raise StaleRead("original V2 terminal graph changed before commit")
                current, running = original_locked(db)
                if current != saved or running != job:
                    raise StaleRead("original V2 terminal original changed")
                before = job_graph_write(job)
                atom = db.execute(
                    "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                    (before.key.token,),
                ).fetchone()
                if (atom is None or atom[2] != 1
                        or json.loads(atom[1]) != before.value):
                    raise ContextReplyJobHold("original V2 graph job differs")
                completed = transition_job(
                    db, job.job_id, authority.actor, job.fence,
                    target_phase="completed", result_ref=saved.seal.call_id)
                write = job_graph_write(completed)
                reconcile_runtime_write(db, write)
                receipt = GraphStore._graph_commit_in_transaction(
                    store, GraphCandidate(
                        Event(Scope(*namespace.as_tuple, job.activity_id),
                              operation_id, time.time(), "domain_bundle",
                              {"original_call_id": saved.seal.call_id,
                               "terminal_receipt_digest": terminal_digest}),
                        (GraphVersion(write.key, atom[0]),), (write,), (epoch,)),
                    _capability=self.__graph_capability)
                if receipt.status != "committed":
                    raise EventConflict("original V2 terminal graph event differs")
                store.cas_graph_recovery_metadata(
                    metadata, metadata.requirements,
                    _capability=self.__graph_capability)
                changed = db.execute(
                    "UPDATE graph_context_reply_preparations_v2 SET state='terminal' "
                    "WHERE bot=? AND persona=? AND c02_operation_id=? "
                    "AND source_ref=? AND state='acquired' AND seal_json=?",
                    namespace.as_tuple + (c02_operation_id, source_ref,
                    canonical_serialize(asdict(saved.seal))),
                ).rowcount
                if changed != 1:
                    raise ContextReplyJobHold("original V2 terminal state CAS differs")
                db.execute(
                    "UPDATE graph_context_reply_terminals_v2 SET state='committed' "
                    "WHERE bot=? AND persona=? AND original_operation_id=? "
                    "AND attempt_id=? AND state='open'",
                    namespace.as_tuple +
                    (saved.seal.original_operation_id, attempt_id),
                )
                if db.execute("SELECT changes()").fetchone() != (1,):
                    raise EventConflict("original V2 terminal receipt differs")
                db.execute("COMMIT")
            except BaseException as exc:
                if db.in_transaction:
                    db.execute("ROLLBACK")
                failure = exc
            else:
                failure = None
        if failure is not None:
            with store._lock:
                db.execute(
                    "UPDATE graph_context_reply_terminals_v2 SET state='rejected' "
                    "WHERE bot=? AND persona=? AND original_operation_id=? "
                    "AND attempt_id=? AND state='open'",
                    namespace.as_tuple +
                    (saved.seal.original_operation_id, attempt_id),
                )
            port.finish_fence(
                scope, request_id="abort:" + attempt_id,
                request_digest="sha256:" + canonical_digest({
                    "action": "reject_context_reply_terminal",
                    "attempt_id": attempt_id, "permit_token": permit.token,
                }))
            raise failure
        port.finish_fence(
            scope, request_id="finish:" + attempt_id,
            request_digest="sha256:" + canonical_digest({
                "action": "finish_context_reply_terminal",
                "attempt_id": attempt_id, "permit_token": permit.token,
            }))
        return completed

    def read_post_c02_context_reply_model_egress_preparation_v2(
            self, authority: AuthorityContext, lease: object,
            c02_operation_id: str, source_ref: str, installed_bundle):
        """Return the original typed call and current paid egress draft."""
        from .authority_service.v2_model_egress_contract import ModelEgressDraftV1
        from .host.authority_profile import AdminInstallationBundle
        from .runtime.context_reply_job_v2 import (
            ContextReplyJobHold, read_original_context_reply_call_binding_v2,
            read_original_context_reply_preparation_v2,
        )
        from .runtime.d11_types import job_graph_write
        from .runtime.model_cost_settlement import original_model_cost_operation_id_v1
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.issuers import D02ResourceIssuer, D11BudgetJobIssuer
        from .runtime_contracts import QueryEpoch

        store, port, namespace = self.__store, self.__content_fence_v2, authority.namespace
        if (not isinstance(store, ProductionGraphStore) or port is None
                or type(installed_bundle) is not AdminInstallationBundle
                or type(self.__d02_issuer) is not D02ResourceIssuer
                or type(self.__d11_issuer) is not D11BudgetJobIssuer
                or installed_bundle.installation_policy.namespace != namespace):
            raise UnavailableGuard("installed V2 paid egress authorities absent; HOLD")
        self._authorize(lease, authority, frozenset({"d11"}))
        now = trusted_upper(port.read_ingress_clock(self.__scene_clock_policy))

        def reader():
            db = store._db
            db.execute("BEGIN")
            try:
                metadata, epoch = self._v2_graph_stamp(namespace)
                saved = read_original_context_reply_preparation_v2(
                    db, namespace, c02_operation_id, source_ref)
                if saved is None or saved.state != "acquired":
                    raise ContextReplyJobHold("original V2 paid call is not acquired")
                seal = saved.seal
                binding = read_original_context_reply_call_binding_v2(db, saved)
                job = get_job(db, seal.job_id)
                if binding is None:
                    raise ContextReplyJobHold("original V2 paid call binding absent")
                request = binding.model_call_request
                snapshot, attention = self._qualified_reply_attention_locked(
                    namespace, source_ref, now, epoch)
                access_epoch, delete_epoch = self._deletion_epochs_locked(db, namespace)
                if (set(snapshot.versions) != set(saved.read_versions)
                        or (access_epoch, delete_epoch)
                           != (saved.access_epoch, saved.delete_epoch)
                        or set(part.ref.ref for part in saved.frozen_request.input.evidence)
                           != set(attention.ticket.source_refs)
                        or now >= saved.frozen_request.input.expires_at_utc
                        or (job.phase, job.lease_holder, job.fence,
                            job.operation_id, job.work_kind)
                           != ("running", authority.actor, binding.worker_fence,
                               seal.original_operation_id, "context_reply")
                        or job.cancel_epoch != 0 or job.result_ref is not None
                        or request.envelope.authority != authority
                        or request.identity.operation_id != seal.acquire_operation_id
                        or request.envelope.version_guard.access_epoch != access_epoch
                        or request.envelope.version_guard.delete_epoch != delete_epoch
                        or request.envelope.version_guard.query_epochs != (
                            QueryEpoch(namespace, saved.query_epoch.scope_ref,
                                       epoch.revision),)
                        or authority.audience != (
                            saved.frozen_request.input.conversation_ref,)):
                    raise ContextReplyJobHold("original V2 paid egress inputs changed")
                job_key = job_graph_write(job).key
                atom = db.execute(
                    "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                    (job_key.token,),
                ).fetchone()
                if (atom is None or atom[2] != 1
                        or json.loads(atom[1]) != job_graph_write(job).value
                        or set(request.envelope.version_guard.read_versions)
                           != set(saved.read_versions +
                                  (GraphVersion(job_key, atom[0]),))):
                    raise ContextReplyJobHold("original V2 paid job graph differs")
                quote_id = "context-reply-quote:" + seal.job_id.split(":")[-1]
                quote = self.__d02_issuer.original_signed_quote(db, quote_id, 1)
                reservation = db.execute(
                    "SELECT digest,ceiling_json,state FROM runtime_budget_reservations "
                    "WHERE lease_id=? AND operation_id=?",
                    (job.budget_ref, job.operation_id),
                ).fetchone()
                if (reservation is None or reservation[1:] != (
                        canonical_json(dict(quote.ceiling)), "reserved")
                        or get_budget_lease(db, job.budget_ref).state != "active"
                        or self.__d11_issuer.current_budget_grant(
                            db, job.budget_ref)
                           != installed_bundle.installation_policy.root_grant):
                    raise ContextReplyJobHold("original V2 paid budget changed")
                source_versions = []
                access_versions = []
                for part in saved.frozen_request.input.evidence:
                    source_atom = snapshot.get(AtomKey.from_token(part.ref.ref))
                    record = SourceRecord.from_dict(source_atom.value)
                    source_versions.append((record.source_id, part.ref.version))
                    if part.access_ref is None:
                        raise ContextReplyJobHold("original V2 evidence access absent")
                    access_versions.append((record.source_id,
                                            part.access_ref.version))
                result = (saved, request, reservation[0], quote,
                          tuple(source_versions), tuple(access_versions),
                          metadata, epoch, job)
                db.execute("COMMIT")
                return result
            except BaseException:
                db.execute("ROLLBACK")
                raise

        (prepared, anchor, metadata, epoch) = self._read_v2(
            authority, reader, return_recovery_context=True)
        saved, request, reservation_digest, quote, sources, accesses, _, _, job = prepared
        target = metadata.requirements
        draft = ModelEgressDraftV1(
            target.authority_id, target.authority_namespace, authority.actor,
            request.identity.operation_id, request.call_id, request.digest,
            job.job_id, job.fence, tuple(source_id for source_id, _ in sources),
            sources, accesses, saved.access_epoch, saved.delete_epoch,
            epoch.revision, metadata.graph_revision,
            target.activation_generation, target.revocation_epoch,
            target.deletion_seq, target.execution_seq,
            job.budget_ref, job.operation_id, reservation_digest,
            tuple(sorted(quote.ceiling.items())), request.provider_id,
            request.model_id, saved.seal.provider_config_digest,
            request.max_output_tokens,
            acquire_operation_id=request.identity.operation_id,
            binding_digest=canonical_digest({
                "original_seal_digest": canonical_digest(asdict(saved.seal)),
                "model_call_request_digest": request.digest,
                "worker_fence": job.fence,
            }),
        )
        return request, draft, anchor

    def read_post_c02_context_reply_model_result_request_v2(
            self, authority: AuthorityContext, lease: object,
            c02_operation_id: str, source_ref: str, installed_bundle):
        """Read only the sealed original identity for Authority paid result lookup."""
        from .authority_service.v2_context_reply_result_contract import (
            ContextReplyResultReadRequestV1, context_reply_read_attempt_id_v1,
        )
        from .host.authority_profile import AdminInstallationBundle
        from .runtime.context_reply_job_v2 import (
            ContextReplyJobHold, read_original_context_reply_call_binding_v2,
            read_original_context_reply_preparation_v2,
        )
        from .runtime.d11_types import job_graph_write
        from .runtime.model_cost_settlement import original_model_cost_operation_id_v1

        store, port, namespace = self.__store, self.__content_fence_v2, authority.namespace
        if (not isinstance(store, ProductionGraphStore) or port is None
                or type(installed_bundle) is not AdminInstallationBundle
                or installed_bundle.installation_policy.namespace != namespace):
            raise UnavailableGuard("installed V2 paid result authorities absent; HOLD")
        self._authorize(lease, authority, frozenset({"d11"}), owner_read=True)
        if (authority.issuer_domain != "d11" or authority.purpose != "proposal"
                or installed_bundle.model_workflows is None
                or installed_bundle.model_workflows.context_reply is None):
            raise AuthorityDenied("original V2 result read authority differs")

        def reader():
            db = store._db
            db.execute("BEGIN")
            try:
                saved = read_original_context_reply_preparation_v2(
                    db, namespace, c02_operation_id, source_ref)
                if saved is None or saved.state != "terminal":
                    raise ContextReplyJobHold("original V2 paid call is not terminal")
                seal = saved.seal
                binding = read_original_context_reply_call_binding_v2(db, saved)
                job = get_job(db, seal.job_id)
                row = db.execute(
                    "SELECT terminal_receipt_digest,state FROM "
                    "graph_context_reply_terminals_v2 WHERE bot=? AND persona=? "
                    "AND original_operation_id=?",
                    namespace.as_tuple + (seal.original_operation_id,),
                ).fetchone()
                atom = db.execute(
                    "SELECT value,valid FROM graph_atoms WHERE token=?",
                    (job_graph_write(job).key.token,),
                ).fetchone()
                cost_id = original_model_cost_operation_id_v1(
                    namespace, seal.call_id)
                cost = db.execute(
                    "SELECT activity_id,receipt_json FROM graph_bundle_operations "
                    "WHERE bot=? AND persona=? AND operation_id=?",
                    namespace.as_tuple + (cost_id,),
                ).fetchone()
                cost_data = json.loads(cost[1]) if cost is not None else {}
                cost_receipt = cost_data.get("original_model_cost", {})
                cost_atom = db.execute(
                    "SELECT valid FROM graph_atoms WHERE token=?",
                    (cost_receipt.get("cost_ref", ""),),
                ).fetchone()
                settled = db.execute(
                    "SELECT 1 FROM runtime_budget_operations WHERE bot_id=? "
                    "AND persona_id=? AND operation_id=? AND phase='settle'",
                    namespace.as_tuple + (seal.original_operation_id,),
                ).fetchone()
                cost_event = (db.execute(
                    "SELECT 1 FROM graph_events WHERE bot=? AND persona=? "
                    "AND session=? AND event_id=?",
                    namespace.as_tuple + (cost[0], cost_id),
                ).fetchone() if cost is not None else None)
                if (binding is None or row is None or row[1] != "committed"
                        or authority.audience != (
                            saved.frozen_request.input.conversation_ref,)
                        or job.phase != "completed"
                        or job.operation_id != seal.original_operation_id
                        or job.result_ref != seal.call_id
                        or atom is None or atom[1] != 1
                        or json.loads(atom[0]) != job_graph_write(job).value
                        or cost_data.get("terminal_receipt_digest") != row[0]
                        or cost_receipt.get("terminal_receipt_digest") != row[0]
                        or cost_receipt.get("status") != "committed"
                        or cost_receipt.get("operation_id") != cost_id
                        or cost_receipt.get("call_id") != seal.call_id
                        or cost_atom != (1,) or settled is None
                        or cost_event is None
                        or seal.installation_id !=
                           installed_bundle.installation_policy.installation_id):
                    raise ContextReplyJobHold("original V2 paid terminal differs")
                metadata, _ = self._v2_graph_stamp(namespace)
                result = ContextReplyResultReadRequestV1(
                    metadata.requirements.authority_id,
                    metadata.requirements.authority_namespace,
                    namespace, c02_operation_id, source_ref,
                    seal.installation_id, seal.job_id,
                    seal.acquire_operation_id, seal.original_operation_id,
                    seal.call_id, seal.model_request_digest,
                    seal.frozen_input_digest,
                    context_reply_read_attempt_id_v1(
                        seal.original_operation_id, 1),
                )
                db.execute("COMMIT")
                return result
            except BaseException:
                db.execute("ROLLBACK")
                raise

        return self._read_v2(authority, reader)

    def acquire_post_c02_reply_model_job_v1(
        self, authority: AuthorityContext, lease: object,
        c02_operation_id: str, source_ref: str, installed_bundle,
        *, lease_seconds: int,
    ) -> PersistentJob:
        """Acquire the original queued reply job and freeze its exact call."""
        from .authority_service.v2_contract import FencePermitV2
        from .authority_service.contract import AuthorityUnavailable
        from .host.authority_profile import AdminInstallationBundle
        from .host.installed_reply_model_driver import reply_model_operation_id_v1
        from .runtime.d11_types import job_graph_write
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.issuers import D02ResourceIssuer, D11BudgetJobIssuer
        from .runtime.reply_model_job import (
            ReplyModelJobHold, freeze_acquired_reply_binding_v1,
            install_schema, read_saved_reply_job_v1,
        )

        store = self.__store
        port = self.__content_fence_v2
        namespace = authority.namespace
        acquire_operation_id = reply_model_operation_id_v1(
            c02_operation_id, source_ref)
        if (not isinstance(store, ProductionGraphStore) or port is None
                or type(installed_bundle) is not AdminInstallationBundle
                or type(self.__d02_issuer) is not D02ResourceIssuer
                or type(self.__d11_issuer) is not D11BudgetJobIssuer
                or installed_bundle.ingress_clock != self.__scene_clock_policy
                or installed_bundle.installation_policy.namespace != namespace
                or type(lease_seconds) is not int
                or not 1 <= lease_seconds <= 3600):
            raise UnavailableGuard("installed reply acquire authorities are absent; HOLD")
        self._authorize(lease, authority, frozenset({"d11"}))
        if (authority.issuer_domain != "d11"
                or authority.purpose != "proposal"
                or "activity" not in authority.owner_scope
                or authority.worker_fence is not None
                or authority.capability_ref != _operation_capability_ref(
                    namespace, authority.actor, "d11", frozenset({"d11"}),
                    authority.activation_generation, acquire_operation_id)):
            raise AuthorityDenied("reply acquire requires original D11 worker lease")
        reading = port.read_ingress_clock(self.__scene_clock_policy)
        now = trusted_upper(reading)
        now_text = __import__("datetime").datetime.fromtimestamp(
            now, __import__("datetime").timezone.utc).isoformat().replace(
                "+00:00", "Z")
        with store._lock:
            db = store._db
            install_schema(db)
            saved = read_saved_reply_job_v1(
                db, self.__d02_issuer, namespace, c02_operation_id, source_ref)
            if saved is None:
                raise ReplyModelJobHold("original queued reply job is absent")
            row = db.execute(
                "SELECT state,acquire_operation_id,actor,worker_fence,"
                "model_request_digest FROM graph_post_c02_reply_model_preparations_v1 "
                "WHERE bot=? AND persona=? AND c02_operation_id=? AND source_ref=?",
                namespace.as_tuple + (c02_operation_id, source_ref),
            ).fetchone()
            committed_attempt = db.execute(
                "SELECT attempt_id,anchor_json,graph_revision,graph_epoch,state "
                "FROM graph_post_c02_reply_model_acquires_v1 WHERE bot=? "
                "AND persona=? AND acquire_operation_id=?",
                namespace.as_tuple + (acquire_operation_id,),
            ).fetchone()
            metadata, epoch = self._v2_graph_stamp(namespace)
        if row[0] == "acquired":
            if (row[1] != acquire_operation_id or row[2] != authority.actor
                    or row[3] != saved.job.fence
                    or not row[4] or saved.job.phase != "running"
                    or saved.job.lease_holder != authority.actor
                    or committed_attempt is None
                    or committed_attempt[4] != "committed"):
                raise ReplyModelJobHold("original reply acquire identity differs")
            target = metadata.requirements
            anchor = port.current_anchor(
                namespace=namespace,
                authority_namespace=target.authority_namespace)
            if not self._anchor_matches(target, anchor):
                raise UnavailableGuard("reply acquire replay anchor differs; HOLD")
            self._finish_committed_post_c02_reply_fence_v1(
                namespace, metadata, epoch, anchor,
                committed_attempt[0], committed_attempt[1],
                committed_attempt[2], committed_attempt[3],
                "finish_reply_acquire")
            return saved.job
        if row[0] != "queued" or saved.job.phase != "queued":
            raise ReplyModelJobHold("reply job is not queued")
        target = metadata.requirements
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if (target.activation_generation != authority.activation_generation
                or not self._anchor_matches(target, anchor)):
            raise UnavailableGuard("reply acquire Authority anchor differs; HOLD")
        request_digest = canonical_digest({
            "schema": "sylanne.post-c02-reply-acquire.v1",
            "original_operation_id": saved.original_operation_id,
            "acquire_operation_id": acquire_operation_id,
            "job_id": saved.job.job_id, "actor": authority.actor,
            "lease_seconds": lease_seconds,
            "expected_fence": saved.job.fence,
        })
        with store._lock:
            db.execute("BEGIN IMMEDIATE")
            try:
                if self._v2_graph_stamp(namespace) != (metadata, epoch):
                    raise StaleRead("reply graph changed before acquire intent")
                attempt = db.execute(
                    "SELECT request_digest,attempt_id,anchor_json,graph_revision,"
                    "graph_epoch,state FROM graph_post_c02_reply_model_acquires_v1 "
                    "WHERE bot=? AND persona=? AND acquire_operation_id=?",
                    namespace.as_tuple + (acquire_operation_id,),
                ).fetchone()
                if attempt is not None and attempt[0] != request_digest:
                    raise EventConflict("reply acquire identity reused with different input")
                if attempt is None or attempt[5] == "closed":
                    attempt_id = "reply-acquire-write-" + secrets.token_hex(24)
                    attempt_was_open = False
                    db.execute(
                        "INSERT INTO graph_post_c02_reply_model_acquires_v1"
                        "(bot,persona,acquire_operation_id,original_operation_id,"
                        "request_digest,attempt_id,anchor_json,graph_revision,"
                        "graph_epoch,state) VALUES(?,?,?,?,?,?,?,?,?,'open') "
                        "ON CONFLICT(bot,persona,acquire_operation_id) DO UPDATE SET "
                        "attempt_id=excluded.attempt_id,anchor_json=excluded.anchor_json,"
                        "graph_revision=excluded.graph_revision,graph_epoch=excluded.graph_epoch,"
                        "state='open' WHERE graph_post_c02_reply_model_acquires_v1.state='closed' "
                        "AND graph_post_c02_reply_model_acquires_v1.request_digest=excluded.request_digest",
                        namespace.as_tuple + (acquire_operation_id,
                        saved.original_operation_id, request_digest,
                        attempt_id, canonical_json(asdict(anchor)),
                        metadata.graph_revision, epoch.revision),
                    )
                elif attempt[5] == "open" and (
                        attempt[2] == canonical_json(asdict(anchor))
                        and attempt[3:5] == (
                            metadata.graph_revision, epoch.revision)):
                    attempt_id = attempt[1]
                    attempt_was_open = True
                else:
                    raise ReplyModelJobHold("reply acquire attempt is unresolved")
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise
        if attempt_was_open:
            try:
                observed, state = port.get_fence_operation(
                    namespace=namespace,
                    authority_namespace=target.authority_namespace,
                    operation_id=attempt_id)
            except AuthorityUnavailable:
                # Keep the original durable attempt across an interrupted begin.
                observed, state = None, "absent"
        else:
            observed, state = None, "absent"
        if state == "absent":
            permit = port.begin_fence(
                namespace=namespace,
                authority_namespace=target.authority_namespace,
                holder=self.__holder, generation=target.activation_generation,
                operation="write", operation_id=attempt_id,
                expected_anchor=anchor)
        elif state == "active":
            permit = observed
        else:
            raise UnavailableGuard("reply acquire fence outcome unknown; HOLD")
        if (type(permit) is not FencePermitV2 or permit.operation != "write"
                or permit.operation_id != attempt_id
                or permit.pinned_anchor != anchor or permit.holder != self.__holder):
            raise UnavailableGuard("reply acquire write permit differs; HOLD")
        scope = FenceScope(
            namespace, target.authority_namespace, target.activation_generation,
            "write", attempt_id, permit, anchor, epoch, metadata.graph_revision)
        if port.validate_fence(scope) != permit:
            raise UnavailableGuard("reply acquire write fence stale; HOLD")
        try:
            with store._lock:
                db.execute("BEGIN IMMEDIATE")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise StaleRead("reply graph changed before acquire")
                    inputs = self._current_post_c02_reply_inputs_locked(
                        namespace, c02_operation_id, source_ref, now, epoch)
                    frozen = db.execute(
                        "SELECT source_revision,access_revision,attention_ticket_id,"
                        "focus_revision,audience,graph_job_revision "
                        "FROM graph_post_c02_reply_model_preparations_v1 "
                        "WHERE bot=? AND persona=? AND c02_operation_id=? AND source_ref=?",
                        namespace.as_tuple + (c02_operation_id, source_ref),
                    ).fetchone()
                    if frozen != (
                            inputs.source.source_revision,
                            inputs.source.access_revision,
                            inputs.attention.ticket.ticket_id,
                            inputs.attention.focus_version.revision,
                            inputs.conversation_ref, saved.graph_job_revision):
                        raise ReplyModelJobHold("queued reply source or attention changed")
                    if authority.audience != (inputs.conversation_ref,):
                        raise AuthorityDenied("reply worker audience differs")
                    if (installed_bundle.installation_policy.catalogue_hash
                            != store._registry.catalogue_hash
                            or installed_bundle.installation_policy.scheme_version
                            != self._version(db, namespace, "scheme", "current")
                            or installed_bundle.installation_policy.operator_version
                            != self._version(db, namespace, "operator", "current")
                            or installed_bundle.installation_policy.policy_version
                            != self._version(db, namespace, "policy", "current")):
                        raise ReplyModelJobHold("reply installed guard versions changed")
                    current = get_job(db, saved.job.job_id)
                    if current != saved.job:
                        raise ReplyModelJobHold("reply D11 job changed")
                    planned = plan_job_acquire(
                        current, authority.actor, now_utc=now_text,
                        lease_seconds=lease_seconds)
                    worker_authority = replace(authority, worker_fence=planned.fence)
                    quote = self.__d02_issuer.original_signed_quote(
                        db, saved.quote.quote_id, saved.quote.version)
                    access_epoch, delete_epoch = self._deletion_epochs_locked(
                        db, namespace)
                    envelope, installed, binding_digest, request_json = (
                        freeze_acquired_reply_binding_v1(
                            db, namespace=namespace, inputs=inputs,
                            job=planned, quote=quote, authority=worker_authority,
                            installed_bundle=installed_bundle,
                            graph_epoch=epoch.revision,
                            access_epoch=access_epoch,
                            delete_epoch=delete_epoch, now_utc=now,
                            monotonic_now=reading.monotonic_after_seconds,
                            acquire_operation_id=acquire_operation_id))
                    acquired = acquire_job(
                        db, current.job_id, authority.actor,
                        now_utc=now_text, lease_seconds=lease_seconds)
                    if acquired != planned:
                        raise ReplyModelJobHold("reply job acquire CAS differed")
                    write = job_graph_write(acquired)
                    reconcile_runtime_write(db, write)
                    candidate = GraphCandidate(
                        Event(Scope(*namespace.as_tuple, current.activity_id),
                              acquire_operation_id, now, "domain_bundle",
                              {"bundle_digest": request_digest}),
                        (GraphVersion(write.key, saved.graph_job_revision),)
                        + inputs.graph_snapshot.versions,
                        (GraphWrite(write.key, write.value,
                                    tuple(atom.key for atom in
                                          inputs.graph_snapshot.atoms)),),
                        (epoch,))
                    graph_receipt = GraphStore._graph_commit_in_transaction(
                        store, candidate, _capability=self.__graph_capability)
                    if graph_receipt.status != "committed":
                        raise EventConflict("reply acquire graph event differs")
                    store.cas_graph_recovery_metadata(
                        metadata, metadata.requirements,
                        _capability=self.__graph_capability)
                    changed = db.execute(
                        "UPDATE graph_post_c02_reply_model_preparations_v1 SET "
                        "state='acquired',acquire_operation_id=?,actor=?,worker_fence=?,"
                        "call_id=?,model_request_digest=?,binding_digest=?,"
                        "envelope_json=?,request_json=?,graph_job_revision=? "
                        "WHERE bot=? AND persona=? AND c02_operation_id=? "
                        "AND source_ref=? AND state='queued'",
                        (acquire_operation_id, authority.actor, acquired.fence,
                         installed.request.call_id, installed.request.digest,
                         binding_digest, canonical_serialize(envelope),
                         request_json, graph_receipt.revisions[0].revision)
                        + namespace.as_tuple + (c02_operation_id, source_ref),
                    ).rowcount
                    if changed != 1:
                        raise ReplyModelJobHold("reply acquire row CAS differs")
                    db.execute(
                        "UPDATE graph_post_c02_reply_model_acquires_v1 "
                        "SET state='committed' WHERE bot=? AND persona=? "
                        "AND acquire_operation_id=? AND attempt_id=?",
                        namespace.as_tuple + (acquire_operation_id, attempt_id),
                    )
                    db.execute("COMMIT")
                except BaseException:
                    db.execute("ROLLBACK")
                    raise
        except BaseException:
            try:
                port.finish_fence(
                    scope, request_id="finish:" + attempt_id,
                    request_digest="sha256:" + canonical_digest({
                        "action": "abort_reply_acquire", "attempt_id": attempt_id,
                        "permit_token": permit.token}))
                with store._lock:
                    db.execute(
                        "UPDATE graph_post_c02_reply_model_acquires_v1 SET state='closed' "
                        "WHERE bot=? AND persona=? AND acquire_operation_id=? "
                        "AND attempt_id=? AND state='open'",
                        namespace.as_tuple + (acquire_operation_id, attempt_id))
            except Exception:
                pass
            raise
        if port.validate_fence(scope) != permit:
            raise UnavailableGuard("reply acquire committed but finish unknown; HOLD")
        port.finish_fence(
            scope, request_id="finish:" + attempt_id,
            request_digest="sha256:" + canonical_digest({
                "action": "finish_reply_acquire", "attempt_id": attempt_id,
                "permit_token": permit.token}))
        return acquired

    def read_post_c02_reply_model_egress_preparation_v1(
        self, authority: AuthorityContext, lease: object,
        c02_operation_id: str, source_ref: str, installed_bundle,
    ):
        """Return a current reply draft; only Authority can issue its intent."""
        from datetime import datetime

        from .authority_service.v2_model_egress_contract import ModelEgressDraftV1
        from .host.authority_profile import AdminInstallationBundle
        from .host.installed_reply_model_driver import reply_model_operation_id_v1
        from .model_broker.reply_language import freeze_installed_reply_request_v1
        from .runtime.budget import get_budget_lease
        from .runtime.d11_types import job_graph_write
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.issuers import D02ResourceIssuer, D11BudgetJobIssuer
        from .runtime.reply_model_job import (
            ReplyModelJobHold, read_saved_reply_job_v1,
            reply_binding_digest_v1, reply_envelope_from_wire_v1,
            reply_request_wire_v1,
        )

        store = self.__store
        port = self.__content_fence_v2
        namespace = authority.namespace
        acquire_operation_id = reply_model_operation_id_v1(
            c02_operation_id, source_ref)
        if (not isinstance(store, ProductionGraphStore) or port is None
                or type(installed_bundle) is not AdminInstallationBundle
                or installed_bundle.ingress_clock != self.__scene_clock_policy
                or installed_bundle.installation_policy.namespace != namespace
                or type(self.__d02_issuer) is not D02ResourceIssuer
                or type(self.__d11_issuer) is not D11BudgetJobIssuer):
            raise UnavailableGuard("installed reply model preparation is unavailable; HOLD")
        self._authorize(lease, authority, frozenset({"d11"}))
        if (authority.issuer_domain != "d11"
                or authority.purpose != "proposal"
                or authority.worker_fence is None
                or authority.capability_ref != _operation_capability_ref(
                    namespace, authority.actor, "d11", frozenset({"d11"}),
                    authority.activation_generation, acquire_operation_id)):
            raise AuthorityDenied("reply model requires the original D11 worker")
        reading = port.read_ingress_clock(self.__scene_clock_policy)
        now = trusted_upper(reading)

        def reader():
            db = store._db
            db.execute("BEGIN")
            try:
                metadata, epoch = self._v2_graph_stamp(namespace)
                inputs = self._current_post_c02_reply_inputs_locked(
                    namespace, c02_operation_id, source_ref, now, epoch)
                saved = read_saved_reply_job_v1(
                    db, self.__d02_issuer, namespace,
                    c02_operation_id, source_ref)
                row = db.execute(
                    "SELECT c02_receipt_digest,source_id,source_revision,"
                    "access_revision,attention_ticket_id,focus_revision,audience,"
                    "state,acquire_operation_id,actor,worker_fence,call_id,"
                    "model_request_digest,binding_digest,envelope_json,request_json "
                    "FROM graph_post_c02_reply_model_preparations_v1 "
                    "WHERE bot=? AND persona=? AND c02_operation_id=? AND source_ref=?",
                    namespace.as_tuple + (c02_operation_id, source_ref),
                ).fetchone()
                if saved is None or row is None:
                    raise ReplyModelJobHold("acquired reply preparation is absent")
                job, quote = saved.job, saved.quote
                deadline = datetime.fromisoformat(
                    job.deadline_utc.replace("Z", "+00:00")).timestamp()
                expiry = datetime.fromisoformat(
                    job.lease_expires_utc.replace("Z", "+00:00")).timestamp()
                lease_state = get_budget_lease(db, job.budget_ref)
                grant = self.__d11_issuer.current_budget_grant(
                    db, job.budget_ref)
                reserve = db.execute(
                    "SELECT digest,ceiling_json,state FROM runtime_budget_reservations "
                    "WHERE lease_id=? AND operation_id=?",
                    (job.budget_ref, job.operation_id),
                ).fetchone()
                reserve_op = db.execute(
                    "SELECT digest FROM runtime_budget_operations WHERE bot_id=? "
                    "AND persona_id=? AND operation_id=? AND phase='reserve'",
                    namespace.as_tuple + (job.operation_id,),
                ).fetchone()
                acquire = db.execute(
                    "SELECT state FROM graph_post_c02_reply_model_acquires_v1 "
                    "WHERE bot=? AND persona=? AND acquire_operation_id=? "
                    "AND original_operation_id=?",
                    namespace.as_tuple + (acquire_operation_id,
                                          job.operation_id),
                ).fetchone()
                if (row[0] != canonical_digest(asdict(inputs.c02_receipt))
                        or row[1:7] != (
                            inputs.source.source.source_id,
                            inputs.source.source_revision,
                            inputs.source.access_revision,
                            inputs.attention.ticket.ticket_id,
                            inputs.attention.focus_version.revision,
                            inputs.conversation_ref)
                        or row[7:11] != (
                            "acquired", acquire_operation_id,
                            authority.actor, authority.worker_fence)
                        or acquire != ("committed",)
                        or job.phase != "running"
                        or job.lease_holder != authority.actor
                        or job.fence != authority.worker_fence
                        or job.cancel_epoch != 0 or job.result_ref is not None
                        or not now < min(expiry, deadline, quote.valid_until_utc)
                        or authority.audience != (inputs.conversation_ref,)
                        or grant != installed_bundle.installation_policy.root_grant
                        or lease_state.state != "active"
                        or reserve is None or reserve_op is None
                        or reserve != (
                            saved.reservation_digest,
                            canonical_json(dict(quote.ceiling)), "reserved")
                        or reserve_op != (saved.reservation_digest,)
                        or row[14] is None or row[15] is None):
                    raise ReplyModelJobHold("original reply model eligibility changed")
                envelope = reply_envelope_from_wire_v1(row[14])
                installed = freeze_installed_reply_request_v1(
                    envelope, inputs.source, bundle=installed_bundle)
                request = installed.request
                if (envelope.authority != authority
                        or row[11] != request.call_id
                        or row[12] != request.digest
                        or row[13] != reply_binding_digest_v1(
                            job, inputs, acquire_operation_id,
                            request.call_id, request.digest)
                        or row[15] != canonical_serialize(
                            reply_request_wire_v1(envelope, request))
                        or quote.ceiling != installed.quote_ceiling
                        or job_graph_write(job).key.token !=
                           saved.quote.graph_job_ref):
                    raise ReplyModelJobHold("frozen reply binding differs")
                epochs = self._deletion_epochs_locked(db, namespace)
                result = (inputs, saved, envelope, installed,
                          row[13], epochs, metadata, epoch)
                db.execute("COMMIT")
                return result
            except BaseException:
                db.execute("ROLLBACK")
                raise

        (prepared, anchor, metadata, epoch) = self._read_v2(
            authority, reader, return_recovery_context=True)
        inputs, saved, envelope, installed, binding_digest, epochs, _, _ = prepared
        target = metadata.requirements
        job = saved.job
        request = installed.request
        draft = ModelEgressDraftV1(
            target.authority_id, target.authority_namespace, authority.actor,
            acquire_operation_id, request.call_id, request.digest,
            job.job_id, job.fence,
            (inputs.source.source.source_id,),
            ((inputs.source.source.source_id, inputs.source.source_revision),),
            ((inputs.source.source.source_id, inputs.source.access_revision),),
            epochs[0], epochs[1], epoch.revision, metadata.graph_revision,
            target.activation_generation, target.revocation_epoch,
            target.deletion_seq, target.execution_seq,
            job.budget_ref, job.operation_id, saved.reservation_digest,
            tuple(sorted(saved.quote.ceiling.items())),
            request.provider_id, request.model_id,
            installed.provider_config_digest, request.max_output_tokens,
            acquire_operation_id=acquire_operation_id,
            binding_digest=binding_digest,
        )
        return (inputs.c02_receipt, envelope, inputs.source,
                inputs.attention.ticket, inputs.attention.focus_version.revision,
                draft, anchor)

    def read_post_c02_reply_model_result_request_v1(
        self, authority: AuthorityContext, lease: object,
        c02_operation_id: str, source_ref: str, installed_bundle,
    ):
        """Build the original reply result-read identity from a current graph read.

        This request carries no model body or read grant. The installed
        Authority reply worker endpoint must check the original terminal and
        graph again while holding its own result-read fence.
        """
        from .authority_service.v2_reply_worker_model_result_contract import (
            ReplyWorkerModelResultReadRequestV1,
            reply_worker_read_attempt_id_v1,
        )
        from .host.post_c02_reply_driver import post_c02_reply_operation_id

        (receipt, envelope, source, attention, focus_revision,
         draft, _) = self.read_post_c02_reply_model_egress_preparation_v1(
            authority, lease, c02_operation_id, source_ref, installed_bundle)
        consumer_id = post_c02_reply_operation_id(c02_operation_id, source_ref)
        grant = self.__content_fence_v2.installation_grant
        return ReplyWorkerModelResultReadRequestV1(
            draft.authority_id, draft.namespace, authority.namespace,
            grant.installation_id, draft.job_id, draft.acquire_operation_id,
            draft.budget_reservation_operation_id, draft.call_id,
            draft.binding_digest, draft.request_digest, consumer_id,
            reply_worker_read_attempt_id_v1(consumer_id, 1),
            receipt.operation_id, source.source_ref,
            source.source_revision, source.access_revision,
            attention.ticket_id, focus_revision, envelope.authority.audience,
        )

    def read_first_ingress_model_egress_preparation_v2(
        self, authority: AuthorityContext, lease: object, job_id: str,
        acquire_operation_id: str,
    ) -> tuple[EncodingCallBinding, ModelEgressDraftV1, RestoreAnchor]:
        """Return one current binding, Authority draft, and pinned restore anchor.

        The paired clock and all Authority fence RPCs run outside the graph
        lock. No graph version, budget ceiling, or Authority head is supplied by
        the host. The later Authority prepare independently verifies currentness.
        """
        from .authority_service.v2_model_egress_contract import ModelEgressDraftV1
        from .host.authority_profile import AdminIngressClockPolicy
        from .runtime.budget import get_budget_lease
        from .runtime.d11_types import runtime_job_key
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.issuers import D02ResourceIssuer, D11BudgetJobIssuer

        if (not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or type(self.__d11_issuer) is not D11BudgetJobIssuer
                or type(self.__d02_issuer) is not D02ResourceIssuer
                or type(self.__scene_clock_policy) is not AdminIngressClockPolicy):
            raise UnavailableGuard("v2 model preparation requires installed graph authorities")
        self._authorize(lease, authority, frozenset({"d11"}), owner_read=True)
        if (authority.issuer_domain != "d11" or "activity" not in authority.owner_scope
                or type(acquire_operation_id) is not str
                or authority.capability_ref != _operation_capability_ref(
                    authority.namespace, authority.actor, "d11", frozenset({"d11"}),
                    authority.activation_generation, acquire_operation_id)):
            raise AuthorityDenied("model preparation requires the job-bound D11 lease")
        try:
            clock = self.__content_fence_v2.read_ingress_clock(
                self.__scene_clock_policy)
            now = trusted_upper(clock)
        except Exception as exc:
            raise UnavailableGuard("model preparation trusted clock unavailable; HOLD") from exc

        def reader():
            db = self.__store._db
            binding, job, outbox, outbox_key = (
                self._first_ingress_encoding_binding_locked(
                    authority, job_id, acquire_operation_id, clock, now))
            quote_ref = job.operator_versions["resource_quote"]
            quote_id, version_text = quote_ref.rsplit(":", 1)
            quote = self.__d02_issuer.original_signed_quote(
                db, quote_id, int(version_text))
            reservation = db.execute(
                "SELECT digest,ceiling_json,state FROM runtime_budget_reservations "
                "WHERE lease_id=? AND operation_id=?",
                (job.budget_ref, job.operation_id),
            ).fetchone()
            reserve_receipt = db.execute(
                "SELECT digest FROM runtime_budget_operations WHERE bot_id=? "
                "AND persona_id=? AND operation_id=? AND phase='reserve'",
                authority.namespace.as_tuple + (job.operation_id,),
            ).fetchone()
            lease = get_budget_lease(db, job.budget_ref)
            epochs = db.execute(
                "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                "WHERE bot=? AND persona=?", authority.namespace.as_tuple,
            ).fetchone()
            ceiling = quote.ceiling
            if (reservation is None or reserve_receipt is None or epochs is None
                    or reservation[2] != "reserved"
                    or reservation[0] != reserve_receipt[0]
                    or reservation[1] != canonical_json(ceiling)
                    or (lease.bot_id, lease.persona_id)
                    != authority.namespace.as_tuple or lease.state != "active"
                    or any(lease.reserved.get(key, 0) < amount
                           for key, amount in ceiling.items())
                    or (quote.bot_id, quote.persona_id, quote.activity_id,
                        quote.operation_id, quote.effect_id, quote.graph_job_ref,
                        quote.outbox_refs, quote.parent_budget_lease_ref,
                        quote.work_kind, quote.snapshot_ref, quote.resource_ref)
                    != (*authority.namespace.as_tuple, job.activity_id,
                        job.operation_id, None,
                        runtime_job_key(*authority.namespace.as_tuple,
                                        job.activity_id, job.job_id).token,
                        (outbox_key.token,), job.budget_ref, job.work_kind,
                        job.snapshot_ref, job.resource_ref)
                    or binding.budget_lease_id != job.budget_ref
                    or binding.budget_reservation_operation_id != job.operation_id):
                raise UnavailableGuard("original model budget or quote changed; HOLD")
            return binding, job, reservation[0], tuple(sorted(ceiling.items())), epochs

        (prepared, anchor, metadata, epoch) = self._read_v2(
            authority, reader, return_recovery_context=True)
        binding, job, reservation_digest, ceiling, epochs = prepared
        target = metadata.requirements
        frozen = binding.request
        draft = ModelEgressDraftV1(
            target.authority_id, target.authority_namespace, authority.actor,
            acquire_operation_id, binding.call_id, binding.model_request_digest,
            job_id, job.fence, (binding.source_id,),
            ((binding.source_id, binding.source_revision),),
            ((binding.source_id, binding.access_revision),),
            epochs[0], epochs[1], epoch.revision, metadata.graph_revision,
            target.activation_generation, target.revocation_epoch,
            target.deletion_seq, target.execution_seq,
            job.budget_ref, job.operation_id, reservation_digest, ceiling,
            frozen["provider_id"], frozen["model_id"],
            frozen["provider_config_digest"], frozen["max_output_tokens"],
            acquire_operation_id=acquire_operation_id,
            binding_digest=binding.binding_digest,
        )
        return binding, draft, anchor

    def read_first_ingress_original_model_result_context_v1(
        self, authority: AuthorityContext, lease: object, job_id: str,
        acquire_operation_id: str,
    ):
        """Read historical model identity under a current worker content fence.

        This is a result-consumption context, not another model dispatch.
        Original D11 reservation, quote expiry, and current outbox phase are
        deliberately absent from its *current* eligibility checks.
        """
        from datetime import datetime

        from .host.authority_profile import AdminIngressClockPolicy
        from .memory_types import SourceRecord, access_key, source_key, validate_access
        from .runtime.d11_types import RuntimeOutboxValue, job_graph_write, runtime_job_key
        from .runtime.encoding_call_binding import (
            binding_from_json, binding_to_json, load_binding,
        )
        from .runtime.first_ingress_v2 import ingress_ids, trusted_upper
        from .runtime.issuers import D02ResourceIssuer, D11BudgetJobIssuer
        from .runtime.original_model_result_context import OriginalModelResultContextV1

        if (not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or type(self.__d02_issuer) is not D02ResourceIssuer
                or type(self.__d11_issuer) is not D11BudgetJobIssuer
                or type(self.__scene_clock_policy) is not AdminIngressClockPolicy):
            raise UnavailableGuard("installed worker result read authorities required")
        self._authorize(lease, authority, frozenset({"d11"}), owner_read=True)
        namespace = authority.namespace
        if (authority.issuer_domain != "d11" or "activity" not in authority.owner_scope
                or authority.purpose != "consolidation"
                or type(acquire_operation_id) is not str
                or authority.capability_ref != _operation_capability_ref(
                    namespace, authority.actor, "d11", frozenset({"d11"}),
                    authority.activation_generation, acquire_operation_id)):
            raise AuthorityDenied("original result read requires the job-bound D11 lease")
        try:
            now = trusted_upper(self.__content_fence_v2.read_ingress_clock(
                self.__scene_clock_policy))
        except Exception as exc:
            raise UnavailableGuard("worker result trusted clock unavailable; HOLD") from exc

        def reader():
            db = self.__store._db
            job = get_job(db, job_id)
            if ((job.bot_id, job.persona_id) != namespace.as_tuple
                    or job.work_kind != "d06.encode_source"
                    or job.effect_id is not None or job.phase != "running"
                    or job.lease_holder != authority.actor
                    or job.fence != authority.worker_fence or job.fence < 1
                    or job.cancel_epoch != 0 or job.result_ref is not None
                    or job.lease_expires_utc is None):
                raise UnavailableGuard("worker result job lease is not current; HOLD")
            expiry = datetime.fromisoformat(
                job.lease_expires_utc.replace("Z", "+00:00")).timestamp()
            deadline = datetime.fromisoformat(
                job.deadline_utc.replace("Z", "+00:00")).timestamp()
            if now >= min(expiry, deadline):
                raise UnavailableGuard("worker result lease or deadline expired; HOLD")
            if not _job_acquire_id_matches(
                    acquire_operation_id, namespace, job_id, job.operation_id,
                    authority.actor, authority.activation_generation):
                raise AuthorityDenied("original result acquire identity differs")

            job_key = runtime_job_key(*namespace.as_tuple, job.activity_id, job_id)
            job_atom = db.execute(
                "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                (job_key.token,),
            ).fetchone()
            if (job_atom is None or job_atom[2] != 1
                    or json.loads(job_atom[1]) != job_graph_write(job).value):
                raise UnavailableGuard("worker result job projection differs; HOLD")

            ingress = db.execute(
                "SELECT activity_id,effect_id,receipt_json FROM graph_bundle_operations "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (job.operation_id,),
            ).fetchone()
            if ingress is None or ingress[:2] != (job.activity_id, None):
                raise UnavailableGuard("original committed ingress is absent; HOLD")
            ingress_receipt = json.loads(ingress[2])
            outbox_refs = ingress_receipt.get("outbox_refs")
            if (job_key.token not in ingress_receipt.get("ledger_refs", ())
                    or type(outbox_refs) is not list or len(outbox_refs) != 1):
                raise UnavailableGuard("original ingress job/outbox identity differs; HOLD")
            outbox_token = outbox_refs[0]
            outbox_key = AtomKey.from_token(outbox_token)
            if (outbox_key.type_name != "runtime.outbox"
                    or outbox_key.owner != Owner(
                        "activity", *namespace.as_tuple, job.activity_id)):
                raise UnavailableGuard("original outbox identity differs; HOLD")
            # The ingress event's first outbox write is historical evidence.
            # Its present phase is irrelevant to result consumption.
            outbox_rows = db.execute(
                "SELECT value FROM graph_history WHERE token=? AND valid=1 "
                "AND event_bot=? AND event_persona=? AND event_session=? "
                "AND event_id=?",
                (outbox_token, *namespace.as_tuple, job.activity_id,
                 job.operation_id),
            ).fetchall()
            if len(outbox_rows) != 1:
                raise UnavailableGuard("original ingress outbox write is absent; HOLD")
            outbox = RuntimeOutboxValue(**json.loads(outbox_rows[0][0]))
            expected = ingress_ids(outbox.payload_ref)
            if ((outbox.bot_id, outbox.persona_id, outbox.activity_id,
                 outbox.operation_id, outbox.effect_id, outbox.job_id,
                 outbox.job_ref, outbox.outbox_id,
                 outbox.idempotency_key, outbox.phase) != (
                    *namespace.as_tuple, job.activity_id, job.operation_id,
                    None, job_id, job_key.token, expected[4], expected[5],
                    "pending")
                    or expected[1:5] != (
                        job.activity_id, job.operation_id, job_id,
                        outbox.outbox_id)):
                raise UnavailableGuard("original outbox does not bind this job; HOLD")

            acquire = db.execute(
                "SELECT i.job_id,i.original_operation_id,i.actor,"
                "i.encoding_binding_json,r.job_json,i.requirements_json,"
                "i.graph_revision,i.graph_epoch "
                "FROM graph_job_acquire_intents_v2 AS i "
                "JOIN graph_job_acquire_receipts_v2 AS r "
                "ON r.bot=i.bot AND r.persona=i.persona "
                "AND r.acquire_operation_id=i.acquire_operation_id "
                "WHERE i.bot=? AND i.persona=? AND i.acquire_operation_id=?",
                namespace.as_tuple + (acquire_operation_id,),
            ).fetchall()
            binding = load_binding(db, namespace, job_id)
            if len(acquire) != 1 or binding is None or acquire[0][3] is None:
                raise UnavailableGuard("original committed acquire/binding is absent; HOLD")
            frozen_job = json.loads(acquire[0][4])
            historical_requirements = json.loads(acquire[0][5])
            if (acquire[0][:4] != (
                    job_id, job.operation_id, authority.actor,
                    binding_to_json(binding))
                    or binding_from_json(acquire[0][3]) != binding
                    or frozen_job.get("job_id") != job_id
                    or frozen_job.get("fence") != job.fence
                    or frozen_job.get("lease_holder") != authority.actor
                    or frozen_job.get("lease_expires_utc") != job.lease_expires_utc
                    or historical_requirements.get("namespace") != asdict(namespace)
                    or not historical_requirements.get("graph_incarnation")):
                raise UnavailableGuard("original acquire differs from current worker; HOLD")
            if db.execute(
                    "SELECT 1 FROM runtime_encoding_call_redactions_v1 "
                    "WHERE bot=? AND persona=? AND "
                    "(call_id=? OR source_id=?) LIMIT 1",
                    namespace.as_tuple + (binding.call_id, binding.source_id),
            ).fetchone() is not None:
                raise UnavailableGuard("original encoding binding was redacted; HOLD")
            frozen = binding.request
            envelope_authority = frozen["envelope"]["authority"]
            if (frozen["schema"] not in {
                    "sylanne.first-ingress-encoding-call.v2",
                    "sylanne.first-ingress-encoding-call.v3"}
                    or frozen["acquire_operation_id"] != acquire_operation_id
                    or frozen["original_operation_id"] != job.operation_id
                    or frozen["worker_fence"] != job.fence
                    or frozen["worker_lease_expires_utc"] != job.lease_expires_utc
                    or frozen["source_id"] != outbox.payload_ref
                    or binding.source_id != outbox.payload_ref
                    or binding.budget_lease_id != job.budget_ref
                    or binding.budget_reservation_operation_id != job.operation_id
                    or envelope_authority["actor"] != authority.actor
                    or envelope_authority["worker_fence"] != job.fence
                    or envelope_authority["purpose"] != "consolidation"):
                raise UnavailableGuard("original model binding identity differs; HOLD")
            if frozen["schema"] == "sylanne.first-ingress-encoding-call.v3":
                current_metadata, current_epoch = self._v2_graph_stamp(namespace)
                baseline = self._committed_first_ingress_baseline_locked(
                    namespace, binding.source_id, current_metadata, current_epoch,
                    acquire_stamp=acquire[0][6:8])
                if frozen.get("baseline") != asdict(baseline):
                    raise UnavailableGuard("original V3 D04 baseline identity differs; HOLD")

            # Historical signatures remain checkable after D11 settlement or
            # grant/quote revocation. Neither is used as a new-work permit.
            quote_ref = job.operator_versions.get("resource_quote")
            if type(quote_ref) is not str or ":" not in quote_ref:
                raise UnavailableGuard("original encoding quote reference is absent; HOLD")
            quote_id, version_text = quote_ref.rsplit(":", 1)
            quote = self.__d02_issuer.original_signed_quote(
                db, quote_id, int(version_text))
            issuance = db.execute(
                "SELECT activation_generation,quote_id,grant_id "
                "FROM runtime_ingress_issuance WHERE bot=? AND persona=? "
                "AND operation_id=?",
                namespace.as_tuple + (job.operation_id,),
            ).fetchone()
            provision_row = self._provision_row(db, namespace)
            if provision_row is None:
                raise UnavailableGuard("original provisioning receipt is absent; HOLD")
            provision = self._decode_provision_receipt(provision_row)
            grant, signature = self.__d11_issuer.signed_budget_grant_at_version(
                db, provision.root_lease_id, provision.root_grant_version)
            if (issuance != (authority.activation_generation,
                            quote_id, grant.grant_id)
                    or (provision.authority_id, provision.authority_namespace,
                        provision.generation, provision.root_lease_id,
                        provision.root_grant_id,
                        provision.root_grant_signature) != (
                        historical_requirements["authority_id"],
                        historical_requirements["authority_namespace"],
                        authority.activation_generation, job.budget_ref,
                        grant.grant_id, signature)
                    or (grant.bot_id, grant.persona_id, grant.lease_id) != (
                        *namespace.as_tuple, job.budget_ref)
                    or job.work_kind not in grant.allowed_work_kinds
                    or (quote.bot_id, quote.persona_id, quote.activity_id,
                        quote.operation_id, quote.effect_id,
                        quote.parent_budget_lease_ref, quote.work_kind,
                        quote.graph_job_ref, quote.outbox_refs) != (
                        *namespace.as_tuple, job.activity_id,
                        job.operation_id, None, job.budget_ref, job.work_kind,
                        job_key.token, (outbox_token,))):
                raise UnavailableGuard("original signed encoding bounds differ; HOLD")
            original_reservation = db.execute(
                "SELECT digest,ceiling_json FROM runtime_budget_reservations "
                "WHERE lease_id=? AND operation_id=?",
                (job.budget_ref, job.operation_id),
            ).fetchone()
            original_reserve_receipt = db.execute(
                "SELECT digest FROM runtime_budget_operations WHERE bot_id=? "
                "AND persona_id=? AND operation_id=? AND phase='reserve'",
                namespace.as_tuple + (job.operation_id,),
            ).fetchone()
            if (original_reservation is None or original_reserve_receipt is None
                    or original_reservation != (
                        original_reserve_receipt[0], canonical_json(quote.ceiling))):
                raise UnavailableGuard("original reservation identity differs; HOLD")
            self._original_first_ingress_qualification_locked(
                namespace, job.operation_id,
                source_key(*namespace.as_tuple, binding.source_id).token)

            source_key_value = source_key(*namespace.as_tuple, binding.source_id)
            access_key_value = access_key(*namespace.as_tuple, binding.source_id)
            source_row = db.execute(
                "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                (source_key_value.token,),
            ).fetchone()
            access_row = db.execute(
                "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                (access_key_value.token,),
            ).fetchone()
            dependency = db.execute(
                "SELECT dependency_revision FROM graph_dependencies WHERE "
                "dependent_token=? AND dependency_token=?",
                (access_key_value.token, source_key_value.token),
            ).fetchone()
            if (source_row is None or access_row is None
                    or source_row[2] != 1 or access_row[2] != 1
                    or source_row[0] != binding.source_revision
                    or access_row[0] != binding.access_revision
                    or dependency != (source_row[0],)):
                raise UnavailableGuard("worker result source/access version changed; HOLD")
            source = SourceRecord.from_dict(json.loads(source_row[1]))
            access = json.loads(access_row[1])
            validate_access(access)
            audience = envelope_authority["audience"]
            if (source.source_id != binding.source_id
                    or access["source_id"] != binding.source_id
                    or access["status"] != "active"
                    or "consolidation" not in source.purposes
                    or "consolidation" not in access["purposes"]
                    or type(audience) is not list or not audience
                    or not set(audience).issubset(source.audiences)
                    or not set(audience).issubset(access["audiences"])):
                raise UnavailableGuard("worker result source access revoked; HOLD")
            epochs = db.execute(
                "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                "WHERE bot=? AND persona=?", namespace.as_tuple,
            ).fetchone()
            if epochs is None:
                raise UnavailableGuard("worker result authority epochs absent; HOLD")
            return (binding, job, epochs,
                    historical_requirements["graph_incarnation"],
                    provision.installation_id)

        (prepared, anchor, metadata, graph_epoch) = self._read_v2(
            authority, reader, return_recovery_context=True)
        binding, job, epochs, original_incarnation, installation_id = prepared
        target = metadata.requirements
        if (target.namespace != namespace
                or target.graph_incarnation != original_incarnation):
            raise UnavailableGuard("worker result graph recovery identity differs; HOLD")
        return OriginalModelResultContextV1(
            namespace, target.authority_id, target.authority_namespace,
            installation_id,
            target.graph_incarnation, metadata.graph_revision,
            graph_epoch.revision, *epochs, job_id, acquire_operation_id,
            job.operation_id, binding.call_id, binding.binding_digest,
            binding.model_request_digest, binding.source_id,
            binding.source_revision, binding.access_revision,
            authority.actor, job.fence, job.lease_expires_utc, anchor)

    def discover_pending_post_c02_reply_model_jobs_v1(
        self, bootstrap: object, namespace: NamespaceId, *,
        cursor: str | None = None, limit: int = 8, installed_bundle,
    ):
        """Page original queued/acquired reply identities under a current read fence.

        A HOLD item deliberately carries neither preparation nor conversation
        identity. Discovery itself never authorizes a new model call.
        """
        from datetime import datetime

        from .host.authority_profile import AdminIngressClockPolicy, AdminInstallationBundle
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.issuers import D02ResourceIssuer, D11BudgetJobIssuer
        from .runtime.reply_model_job import (
            ReplyModelJobHold, ReplyModelRecoveryItemV1,
            ReplyModelRecoveryPageV1, read_saved_reply_job_v1,
        )

        self._admin(bootstrap)
        store = self.__store
        port = self.__content_fence_v2
        if (type(namespace) is not NamespaceId or type(limit) is not int
                or not 1 <= limit <= 20
                or cursor is not None and (
                    type(cursor) is not str or not cursor or len(cursor) > 128)
                or not isinstance(store, ProductionGraphStore) or port is None
                or type(installed_bundle) is not AdminInstallationBundle
                or type(self.__scene_clock_policy) is not AdminIngressClockPolicy
                or installed_bundle.ingress_clock != self.__scene_clock_policy
                or installed_bundle.installation_policy.namespace != namespace
                or type(self.__d02_issuer) is not D02ResourceIssuer
                or type(self.__d11_issuer) is not D11BudgetJobIssuer
                or self.__d11_issuer.resource_issuer is not self.__d02_issuer):
            raise UnavailableGuard("installed bounded reply recovery required; HOLD")
        try:
            now = trusted_upper(port.read_ingress_clock(self.__scene_clock_policy))
        except Exception as exc:
            raise UnavailableGuard("reply recovery clock unavailable; HOLD") from exc
        with store._lock:
            metadata, _ = self._v2_graph_stamp(namespace)
        authority = AuthorityContext(
            self.__holder, "d11", "reply-recovery-discovery", namespace,
            ("activity",), "recovery", ("internal",),
            "reply-recovery-discovery-v1",
            metadata.requirements.activation_generation)

        def reader():
            db = store._db
            current, epoch = self._v2_graph_stamp(namespace)
            target = current.requirements
            provision_row = self._provision_row(db, namespace)
            if provision_row is None:
                raise UnavailableGuard("reply recovery provisioning absent; HOLD")
            provision = self._decode_provision_receipt(provision_row)
            installed = port.installation_grant
            policy = installed_bundle.installation_policy
            if (target.namespace != namespace
                    or provision.installation_id != installed.installation_id
                    or provision.installation_id != policy.installation_id
                    or provision.authority_id != installed.authority_id
                    or provision.authority_id != target.authority_id
                    or provision.authority_namespace != target.authority_namespace
                    or provision.generation != target.activation_generation):
                raise UnavailableGuard("reply recovery installation differs; HOLD")
            items = []
            last = cursor or ""
            if db.execute(
                    "SELECT 1 FROM sqlite_master WHERE type='table' AND "
                    "name='graph_post_c02_reply_model_preparations_v1'"
            ).fetchone() is None:
                return ReplyModelRecoveryPageV1(
                    namespace, provision.installation_id,
                    target.graph_incarnation, current.graph_revision,
                    epoch.revision, (), None)
            rows = db.execute(
                "SELECT job_id,c02_operation_id,source_ref,state FROM "
                "graph_post_c02_reply_model_preparations_v1 WHERE bot=? "
                "AND persona=? AND job_id>? AND state IN ('queued','acquired') "
                "ORDER BY job_id LIMIT ?",
                namespace.as_tuple + (last, limit + 1),
            ).fetchall()
            db.execute("BEGIN")
            try:
                for job_id, c02_operation_id, source_ref, state in rows[:limit]:
                    last = job_id
                    try:
                        if (policy.catalogue_hash != store._registry.catalogue_hash
                                or policy.scheme_version != self._version(
                                    db, namespace, "scheme", "current")
                                or policy.operator_version != self._version(
                                    db, namespace, "operator", "current")
                                or policy.policy_version != self._version(
                                    db, namespace, "policy", "current")):
                            raise ReplyModelJobHold("installed reply policy changed")
                        saved = read_saved_reply_job_v1(
                            db, self.__d02_issuer, namespace,
                            c02_operation_id, source_ref)
                        if saved is None or saved.job.job_id != job_id:
                            raise ReplyModelJobHold("original reply identity absent")
                        job = saved.job
                        if (job.cancel_epoch != 0 or job.result_ref is not None
                                or now >= datetime.fromisoformat(
                                    job.deadline_utc.replace("Z", "+00:00")
                                ).timestamp()
                                or state == "queued" and (
                                    job.phase != "queued" or job.fence != 0
                                    or job.lease_holder is not None
                                    or job.lease_expires_utc is not None)
                                or state == "acquired" and (
                                    job.phase != "running" or job.fence < 1
                                    or job.lease_holder is None
                                    or job.lease_expires_utc is None
                                    or now >= datetime.fromisoformat(
                                        job.lease_expires_utc.replace(
                                            "Z", "+00:00")
                                    ).timestamp())):
                            raise ReplyModelJobHold("original reply job is not recoverable")
                        inputs = self._current_post_c02_reply_inputs_locked(
                            namespace, c02_operation_id, source_ref, now, epoch)
                        frozen = db.execute(
                            "SELECT source_revision,access_revision,"
                            "attention_ticket_id,focus_revision,audience,"
                            "graph_job_revision FROM "
                            "graph_post_c02_reply_model_preparations_v1 "
                            "WHERE bot=? AND persona=? AND job_id=?",
                            namespace.as_tuple + (job_id,),
                        ).fetchone()
                        if frozen != (
                                inputs.source.source_revision,
                                inputs.source.access_revision,
                                inputs.attention.ticket.ticket_id,
                                inputs.attention.focus_version.revision,
                                inputs.conversation_ref, saved.graph_job_revision):
                            raise ReplyModelJobHold("reply source or attention changed")
                        if state == "acquired":
                            acquire = db.execute(
                                "SELECT state,worker_fence,call_id,"
                                "model_request_digest FROM "
                                "graph_post_c02_reply_model_preparations_v1 "
                                "WHERE bot=? AND persona=? AND job_id=?",
                                namespace.as_tuple + (job_id,),
                            ).fetchone()
                            if (acquire is None or acquire[0] != "acquired"
                                    or acquire[1] != job.fence
                                    or not acquire[2] or not acquire[3]):
                                raise ReplyModelJobHold("acquired reply binding differs")
                        items.append(ReplyModelRecoveryItemV1(
                            job_id, saved, inputs.conversation_ref, None))
                    except (ReplyModelJobHold, AuthorityDenied, UnavailableGuard,
                            EventConflict, KeyError, TypeError, ValueError) as exc:
                        items.append(ReplyModelRecoveryItemV1(
                            job_id, None, None, str(exc)))
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise
            return ReplyModelRecoveryPageV1(
                namespace, provision.installation_id,
                target.graph_incarnation, current.graph_revision,
                epoch.revision, tuple(items), last if len(rows) > limit else None)

        return self._read_v2(authority, reader)

    def discover_first_ingress_unacquired_v1(
        self, bootstrap: object, namespace: NamespaceId,
        after_job_id: str | None = None, limit: int = 8,
    ):
        """Find original queued C01 work under a fresh paired read fence.

        The keyset is only a traversal hint. Every returned row is requalified
        against the current graph, D06 grant, D11 job, and committed D03/D04
        baseline; the page carries no worker or model authority.
        """
        from datetime import datetime

        from .host.authority_profile import AdminIngressClockPolicy
        from .host.d06_ingress import ingress_content_fingerprint
        from .host.ingress import HostIngressEnvelope, SourceLineage
        from .memory_types import SourceRecord, validate_access
        from .runtime.first_ingress_unacquired import (
            FirstIngressUnacquiredItemV1, FirstIngressUnacquiredPageV1,
        )
        from .runtime.first_ingress_v2 import ingress_ids, trusted_upper
        from .runtime.ingress_observation import read_committed_ingress_identity

        self._admin(bootstrap)
        if (type(namespace) is not NamespaceId or type(limit) is not int
                or not 1 <= limit <= 8
                or after_job_id is not None and (
                    type(after_job_id) is not str or not after_job_id
                    or len(after_job_id) > 128)
                or not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or self.__d11_issuer is None
                or type(self.__scene_clock_policy) is not AdminIngressClockPolicy):
            raise UnavailableGuard("installed bounded ingress discovery required")
        try:
            now = trusted_upper(self.__content_fence_v2.read_ingress_clock(
                self.__scene_clock_policy))
        except Exception as exc:
            raise UnavailableGuard("ingress discovery clock unavailable; HOLD") from exc
        with self.__store._lock:
            metadata, _ = self._v2_graph_stamp(namespace)
        authority = AuthorityContext(
            self.__holder, "d11", "unacquired-discovery", namespace,
            ("activity",), "context", ("internal",),
            "unacquired-discovery-v1",
            metadata.requirements.activation_generation)

        def reader():
            db = self.__store._db
            current, epoch = self._v2_graph_stamp(namespace)
            target = current.requirements
            provision_row = self._provision_row(db, namespace)
            if provision_row is None:
                raise UnavailableGuard("ingress discovery provisioning absent; HOLD")
            provision = self._decode_provision_receipt(provision_row)
            installed = self.__content_fence_v2.installation_grant
            if (target.namespace != namespace
                    or provision.installation_id != installed.installation_id
                    or provision.authority_id != installed.authority_id
                    or provision.authority_namespace != target.authority_namespace
                    or provision.generation != target.activation_generation):
                raise UnavailableGuard("ingress discovery installation differs; HOLD")
            last = after_job_id or ""
            items = []
            while True:
                rows = db.execute(
                    "SELECT job_id FROM runtime_jobs WHERE bot_id=? AND "
                    "persona_id=? AND job_id>? AND work_kind='d06.encode_source' "
                    "ORDER BY job_id LIMIT ?",
                    namespace.as_tuple + (last, limit + 1),
                ).fetchall()
                if not rows:
                    break
                for (job_id,) in rows[:limit]:
                    last = job_id
                    try:
                        job, job_key, _, outbox, _, _, source_version, access_version = (
                            self._first_ingress_encoding_job_locked(namespace, job_id))
                        if (job.phase != "queued" or job.fence != 0
                                or job.lease_holder is not None
                                or job.lease_expires_utc is not None
                                or job.cancel_epoch != 0 or job.result_ref is not None
                                or now >= datetime.fromisoformat(
                                    job.deadline_utc.replace("Z", "+00:00")
                                ).timestamp()):
                            continue
                        self.__d11_issuer.authorize_existing_encoding_job(
                            db, job, now_utc=now)
                        source_id = outbox.payload_ref
                        if (job.operation_id != ingress_ids(source_id)[2]
                                or job_id != ingress_ids(source_id)[3]
                                or db.execute(
                                    "SELECT 1 FROM graph_job_acquire_intents_v2 "
                                    "WHERE bot=? AND persona=? AND job_id=? LIMIT 1",
                                    namespace.as_tuple + (job_id,),
                                ).fetchone() is not None):
                            continue
                        receipt = read_committed_ingress_identity(
                            db, namespace, source_id)
                        if receipt is None:
                            continue
                        identity = json.loads(receipt.identity_json)
                        intent = db.execute(
                            "SELECT identity_json,requirements_json FROM "
                            "graph_first_ingress_intents_v2 WHERE bot=? AND "
                            "persona=? AND operation_id=?",
                            namespace.as_tuple + (job.operation_id,),
                        ).fetchone()
                        bundle = db.execute(
                            "SELECT digest,receipt_json FROM graph_bundle_operations "
                            "WHERE bot=? AND persona=? AND operation_id=?",
                            namespace.as_tuple + (job.operation_id,),
                        ).fetchone()
                        if (intent is None or bundle is None
                                or bundle[0] != receipt.bundle_digest
                                or json.loads(intent[1]).get("graph_incarnation")
                                   != target.graph_incarnation
                                or job_key.token not in json.loads(bundle[1]).get(
                                    "ledger_refs", ())
                                or json.loads(intent[0]).get("source_ref")
                                   != source_id):
                            continue
                        source_row = db.execute(
                            "SELECT value FROM graph_atoms WHERE token=? AND "
                            "revision=? AND valid=1",
                            (source_version.key.token, source_version.revision),
                        ).fetchone()
                        access_row = db.execute(
                            "SELECT value FROM graph_atoms WHERE token=? AND "
                            "revision=? AND valid=1",
                            (access_version.key.token, access_version.revision),
                        ).fetchone()
                        if source_row is None or access_row is None:
                            continue
                        source = SourceRecord.from_dict(json.loads(source_row[0]))
                        access = json.loads(access_row[0])
                        validate_access(access)
                        if (source.source_id != source_id
                                or source.speaker_id != identity["sender_ref"]
                                or source.source_kind != "reported"
                                or "context" not in source.purposes
                                or "consolidation" not in source.purposes
                                or identity["conversation_ref"] not in source.audiences
                                or access["status"] != "active"
                                or access["source_id"] != source_id
                                or "context" not in access["purposes"]
                                or "consolidation" not in access["purposes"]
                                or identity["conversation_ref"] not in access["audiences"]):
                            continue
                        envelope = HostIngressEnvelope(
                            namespace, identity["platform_ref"],
                            identity["conversation_ref"], identity["sender_ref"],
                            identity["message_id"], source.text,
                            source.occurred_at, source.recorded_at,
                            identity["visibility"], SourceLineage(**identity["lineage"]),
                        )
                        if ingress_content_fingerprint(envelope) != receipt.content_fingerprint:
                            continue
                        self._committed_first_ingress_baseline_locked(
                            namespace, source_id, current, epoch)
                        item = FirstIngressUnacquiredItemV1(
                            namespace, provision.installation_id, job_id,
                            job.operation_id, envelope, receipt.content_fingerprint,
                            receipt.bundle_digest)
                    except (AuthorityDenied, UnavailableGuard, EventConflict,
                            KeyError, TypeError, ValueError):
                        continue
                    items.append(item)
                if len(rows) > limit:
                    return FirstIngressUnacquiredPageV1(
                        namespace, provision.installation_id,
                        target.graph_incarnation, current.graph_revision,
                        epoch.revision, tuple(items), last)
                break
            return FirstIngressUnacquiredPageV1(
                namespace, provision.installation_id,
                target.graph_incarnation, current.graph_revision,
                epoch.revision, tuple(items), None)

        return self._read_v2(authority, reader)

    def discover_first_ingress_recovery_v1(
        self, bootstrap: object, namespace: NamespaceId,
        cursor: str | None = None, limit: int = 20,
    ):
        """List original V3 call identities; this grants no new dispatch."""
        from .host.authority_profile import AdminIngressClockPolicy
        from .runtime.first_ingress_recovery import FirstIngressRecoveryPageV1
        from .runtime.first_ingress_v2 import trusted_upper

        self._admin(bootstrap)
        if (type(namespace) is not NamespaceId or type(limit) is not int
                or not 1 <= limit <= 50
                or cursor is not None and (type(cursor) is not str
                                           or len(cursor) > 1024)
                or not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or self.__d02_issuer is None
                or type(self.__scene_clock_policy) is not AdminIngressClockPolicy):
            raise UnavailableGuard("installed, bounded V3 recovery discovery required")
        parsed_cursor = self._parse_first_ingress_recovery_cursor_v1(cursor)
        try:
            now = trusted_upper(self.__content_fence_v2.read_ingress_clock(
                self.__scene_clock_policy))
        except Exception as exc:
            raise UnavailableGuard("recovery discovery clock unavailable") from exc
        with self.__store._lock:
            metadata, _ = self._v2_graph_stamp(namespace)
        authority = AuthorityContext(
            self.__holder, "d11", "recovery-discovery", namespace,
            ("activity",), "recovery", ("internal",),
            "recovery-discovery-v1",
            metadata.requirements.activation_generation)

        def reader():
            db = self.__store._db
            current, epoch = self._v2_graph_stamp(namespace)
            target = current.requirements
            provision_row = self._provision_row(db, namespace)
            if provision_row is None:
                raise UnavailableGuard("V3 recovery provisioning absent; HOLD")
            provision = self._decode_provision_receipt(provision_row)
            installed = self.__content_fence_v2.installation_grant
            if (provision.installation_id != installed.installation_id
                    or provision.authority_id != installed.authority_id
                    or provision.authority_namespace != target.authority_namespace
                    or provision.generation != target.activation_generation
                    or target.namespace != namespace):
                raise UnavailableGuard("V3 recovery installation differs; HOLD")
            stamp = {
                "schema": "sylanne3.runtime.first-ingress-recovery-cursor.v1",
                "namespace": asdict(namespace),
                "installation_id": provision.installation_id,
                "graph_incarnation": target.graph_incarnation,
                "graph_revision": current.graph_revision,
                "graph_epoch": epoch.revision,
            }
            last = ""
            if parsed_cursor is not None:
                if any(parsed_cursor.get(key) != value for key, value in stamp.items()):
                    raise UnavailableGuard("V3 recovery cursor lost graph stamp")
                last = parsed_cursor["last_acquire_operation_id"]
                if db.execute(
                    "SELECT 1 FROM graph_job_acquire_intents_v2 WHERE bot=? "
                    "AND persona=? AND acquire_operation_id=? AND "
                    "json_extract(json_extract(encoding_binding_json,"
                    "'$.request_json'),'$.schema')=?",
                    namespace.as_tuple + (last,
                        "sylanne.first-ingress-encoding-call.v3"),
                ).fetchone() is None:
                    raise UnavailableGuard("V3 recovery cursor row is absent")
            rows = db.execute(
                "SELECT i.acquire_operation_id,i.job_id,i.original_operation_id,"
                "i.actor,i.encoding_binding_json,i.requirements_json,"
                "i.graph_revision,i.graph_epoch,i.request_digest,"
                "r.request_digest,r.job_json "
                "FROM graph_job_acquire_intents_v2 AS i "
                "JOIN graph_job_acquire_receipts_v2 AS r "
                "ON r.bot=i.bot AND r.persona=i.persona "
                "AND r.acquire_operation_id=i.acquire_operation_id "
                "WHERE i.bot=? AND i.persona=? AND i.acquire_operation_id>? "
                "AND json_extract(json_extract(i.encoding_binding_json,"
                "'$.request_json'),'$.schema')=? "
                "ORDER BY i.acquire_operation_id LIMIT ?",
                namespace.as_tuple + (last,
                    "sylanne.first-ingress-encoding-call.v3", limit + 1),
            ).fetchall()
            items = []
            for row in rows[:limit]:
                if self._first_ingress_recovery_ineligible_locked_v1(
                        namespace, epoch, row):
                    continue
                items.append(self._first_ingress_recovery_item_locked_v1(
                    namespace, provision.installation_id, current, epoch, now,
                    row))
            next_cursor = None
            if len(rows) > limit:
                payload = {**stamp, "last_acquire_operation_id": rows[limit - 1][0]}
                next_cursor = canonical_json({
                    **payload, "digest": canonical_digest(payload)})
            return FirstIngressRecoveryPageV1(
                namespace, provision.installation_id,
                target.graph_incarnation, current.graph_revision,
                epoch.revision, tuple(items), next_cursor)

        return self._read_v2(authority, reader)

    def read_first_ingress_acquired_handoff_v1(
        self, bootstrap: object, namespace: NamespaceId,
        acquire_operation_id: str,
    ):
        """Rehydrate one live original V3 ingress under the current read fence.

        Discovery supplies only an operation key. This read requalifies the
        acquired job and the original C01 content; it grants no model send.
        """
        from .host.authority_profile import AdminIngressClockPolicy
        from .host.d06_ingress import ingress_content_fingerprint
        from .host.ingress import HostIngressEnvelope, SourceLineage
        from .memory_types import SourceRecord, source_key
        from .runtime.encoding_call_binding import load_binding
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.ingress_observation import read_committed_ingress_identity

        self._admin(bootstrap)
        if (type(namespace) is not NamespaceId
                or type(acquire_operation_id) is not str
                or not 1 <= len(acquire_operation_id) <= 128
                or not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or self.__d02_issuer is None
                or type(self.__scene_clock_policy) is not AdminIngressClockPolicy):
            raise UnavailableGuard("installed acquired ingress handoff required")
        try:
            now = trusted_upper(self.__content_fence_v2.read_ingress_clock(
                self.__scene_clock_policy))
        except Exception as exc:
            raise UnavailableGuard("acquired ingress clock unavailable; HOLD") from exc
        with self.__store._lock:
            metadata, _ = self._v2_graph_stamp(namespace)
        authority = AuthorityContext(
            self.__holder, "d11", "acquired-handoff", namespace,
            ("activity",), "context", ("internal",),
            "acquired-handoff-v1",
            metadata.requirements.activation_generation)

        def reader():
            db = self.__store._db
            current, epoch = self._v2_graph_stamp(namespace)
            target = current.requirements
            provision_row = self._provision_row(db, namespace)
            if provision_row is None:
                raise UnavailableGuard("acquired ingress installation absent; HOLD")
            provision = self._decode_provision_receipt(provision_row)
            installed = self.__content_fence_v2.installation_grant
            if (target.namespace != namespace
                    or provision.installation_id != installed.installation_id
                    or provision.authority_id != installed.authority_id
                    or provision.authority_namespace != target.authority_namespace
                    or provision.generation != target.activation_generation):
                raise UnavailableGuard("acquired ingress installation differs; HOLD")
            row = db.execute(
                "SELECT i.acquire_operation_id,i.job_id,i.original_operation_id,"
                "i.actor,i.encoding_binding_json,i.requirements_json,"
                "i.graph_revision,i.graph_epoch,i.request_digest,"
                "r.request_digest,r.job_json "
                "FROM graph_job_acquire_intents_v2 AS i "
                "JOIN graph_job_acquire_receipts_v2 AS r "
                "ON r.bot=i.bot AND r.persona=i.persona "
                "AND r.acquire_operation_id=i.acquire_operation_id "
                "WHERE i.bot=? AND i.persona=? AND i.acquire_operation_id=? "
                "AND json_extract(json_extract(i.encoding_binding_json,"
                "'$.request_json'),'$.schema')=?",
                namespace.as_tuple + (acquire_operation_id,
                    "sylanne.first-ingress-encoding-call.v3"),
            ).fetchone()
            if row is None or self._first_ingress_recovery_ineligible_locked_v1(
                    namespace, epoch, row):
                raise UnavailableGuard("original acquired ingress absent; HOLD")
            item = self._first_ingress_recovery_item_locked_v1(
                namespace, provision.installation_id, current, epoch, now, row)
            if item.recovery_state != "original_fence":
                raise UnavailableGuard("original acquired ingress is not live; HOLD")
            binding = load_binding(db, namespace, item.job_id)
            if binding is None:
                raise UnavailableGuard("original acquired binding absent; HOLD")
            receipt = read_committed_ingress_identity(
                db, namespace, binding.source_id)
            intent = db.execute(
                "SELECT identity_json,requirements_json FROM "
                "graph_first_ingress_intents_v2 WHERE bot=? AND persona=? "
                "AND operation_id=?",
                namespace.as_tuple + (item.original_operation_id,),
            ).fetchone()
            bundle = db.execute(
                "SELECT digest,receipt_json FROM graph_bundle_operations "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (item.original_operation_id,),
            ).fetchone()
            if (receipt is None or intent is None or bundle is None
                    or bundle[0] != receipt.bundle_digest
                    or json.loads(intent[1]).get("graph_incarnation")
                       != target.graph_incarnation
                    or json.loads(intent[0]).get("source_ref")
                       != binding.source_id):
                raise UnavailableGuard("original acquired C01 receipt differs; HOLD")
            identity = json.loads(receipt.identity_json)
            source_row = db.execute(
                "SELECT value FROM graph_atoms WHERE token=? AND revision=? "
                "AND valid=1",
                (source_key(*namespace.as_tuple, binding.source_id).token,
                 binding.source_revision),
            ).fetchone()
            if source_row is None:
                raise UnavailableGuard("original acquired source absent; HOLD")
            source = SourceRecord.from_dict(json.loads(source_row[0]))
            if (source.source_id != binding.source_id
                    or source.speaker_id != identity["sender_ref"]
                    or source.source_kind != "reported"
                    or identity["conversation_ref"] not in source.audiences):
                raise UnavailableGuard("original acquired source differs; HOLD")
            envelope = HostIngressEnvelope(
                namespace, identity["platform_ref"],
                identity["conversation_ref"], identity["sender_ref"],
                identity["message_id"], source.text, source.occurred_at,
                source.recorded_at, identity["visibility"],
                SourceLineage(**identity["lineage"]),
            )
            if ingress_content_fingerprint(envelope) != receipt.content_fingerprint:
                raise UnavailableGuard("original acquired content differs; HOLD")
            return item, envelope

        return self._read_v2(authority, reader)

    @staticmethod
    def _parse_first_ingress_recovery_cursor_v1(cursor):
        if cursor is None:
            return None
        try:
            parsed = json.loads(cursor)
            if (type(parsed) is not dict
                    or set(parsed) != {
                        "schema", "namespace", "installation_id",
                        "graph_incarnation", "graph_revision", "graph_epoch",
                        "last_acquire_operation_id", "digest"}
                    or parsed["schema"] !=
                    "sylanne3.runtime.first-ingress-recovery-cursor.v1"
                    or type(parsed["last_acquire_operation_id"]) is not str
                    or not 1 <= len(parsed["last_acquire_operation_id"]) <= 128
                    or cursor != canonical_json(parsed)
                    or parsed["digest"] != canonical_digest({
                        key: value for key, value in parsed.items()
                        if key != "digest"})):
                raise ValueError("recovery cursor differs")
        except (TypeError, ValueError, KeyError, AttributeError) as exc:
            raise UnavailableGuard("invalid V3 recovery cursor") from exc
        return parsed

    def _first_ingress_recovery_ineligible_locked_v1(
        self, namespace, epoch, row,
    ):
        """Skip only a graph-committed source/access withdrawal, never drift."""
        from .memory_types import access_key, source_key, validate_access
        from .runtime.encoding_call_binding import binding_from_json, load_binding

        db = self.__store._db
        acquire_id, job_id, original_id, actor, binding_json = row[:5]
        binding = binding_from_json(binding_json)
        request = binding.request
        if (binding.namespace != namespace or binding.job_id != job_id
                or binding != load_binding(db, namespace, job_id)
                or row[8] != row[9]
                or request.get("schema") !=
                "sylanne.first-ingress-encoding-call.v3"
                or request.get("acquire_operation_id") != acquire_id
                or request.get("original_operation_id") != original_id
                or request.get("envelope", {}).get("authority", {}).get(
                    "actor") != actor):
            raise UnavailableGuard("V3 recovery withdrawn row identity differs; HOLD")

        def proven_current_change(key, original_revision, *, access):
            current = db.execute(
                "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                (key.token,),
            ).fetchone()
            if current is None or current[0] <= original_revision:
                return False
            withdrawn = current[2] == 0
            if access and current[2] == 1:
                value = json.loads(current[1])
                validate_access(value)
                withdrawn = value["status"] == "withdrawn"
            if not withdrawn:
                return False
            original = db.execute(
                "SELECT valid FROM graph_history WHERE token=? AND revision=?",
                (key.token, original_revision),
            ).fetchone()
            history = db.execute(
                "SELECT value,valid,event_bot,event_persona,event_session,"
                "event_id FROM graph_history WHERE token=? AND revision=?",
                (key.token, current[0]),
            ).fetchone()
            if (original != (1,) or history is None
                    or history[:2] != (current[1], current[2])
                    or history[2:4] != namespace.as_tuple):
                raise UnavailableGuard("V3 recovery withdrawal has no graph history")
            event = db.execute(
                "SELECT revisions,invalidated,epoch_revision FROM graph_events "
                "WHERE bot=? AND persona=? AND session=? AND event_id=?",
                history[2:6],
            ).fetchone()
            expected = [key.token, current[0]]
            if (event is None or expected not in json.loads(
                    event[1] if current[2] == 0 else event[0])
                    or event[2] > epoch.revision):
                raise UnavailableGuard("V3 recovery withdrawal event differs")
            return True

        source = source_key(*namespace.as_tuple, binding.source_id)
        access = access_key(*namespace.as_tuple, binding.source_id)
        return (proven_current_change(source, binding.source_revision,
                                      access=False)
                or proven_current_change(access, binding.access_revision,
                                         access=True))

    def _first_ingress_recovery_item_locked_v1(
        self, namespace, installation_id, metadata, epoch, now, row,
    ):
        """Join one V3 receipt to its current graph without exposing content."""
        from datetime import datetime

        from .memory_types import access_key, episode_key, source_key, validate_access
        from .runtime.d11_types import RuntimeOutboxValue, job_graph_write, runtime_job_key
        from .runtime.encoding_call_binding import binding_from_json, load_binding
        from .runtime.first_ingress_c02_identity import (
            first_ingress_c02_consumer_operation_id_v1,
        )
        from .runtime.first_ingress_recovery import FirstIngressRecoveryItemV1
        from .runtime.first_ingress_v2 import ingress_ids

        (acquire_id, job_id, original_id, actor, binding_json,
         requirements_json, acquired_revision, acquired_epoch,
         intent_digest, receipt_digest, job_json) = row
        db = self.__store._db
        binding = binding_from_json(binding_json)
        frozen = binding.request
        original = PersistentJob(**json.loads(job_json))
        job = get_job(db, job_id)
        historical = json.loads(requirements_json)
        if (binding != load_binding(db, namespace, job_id)
                or binding.namespace != namespace
                or intent_digest != receipt_digest
                or historical.get("namespace") != asdict(namespace)
                or historical.get("graph_incarnation") !=
                metadata.requirements.graph_incarnation
                or historical.get("authority_id") !=
                metadata.requirements.authority_id
                or historical.get("authority_namespace") !=
                metadata.requirements.authority_namespace
                or frozen.get("schema") !=
                "sylanne.first-ingress-encoding-call.v3"
                or frozen.get("acquire_operation_id") != acquire_id
                or frozen.get("original_operation_id") != original_id
                or frozen.get("worker_fence") != original.fence
                or frozen.get("worker_lease_expires_utc") !=
                original.lease_expires_utc
                or frozen.get("baseline") is None
                or frozen.get("call_id") != binding.call_id
                or frozen.get("model_request_digest") !=
                binding.model_request_digest
                or (original.job_id, original.operation_id,
                    original.phase, original.lease_holder,
                    original.cancel_epoch) != (
                    job_id, original_id, "running", actor, 0)
                or (job.bot_id, job.persona_id, job.job_id,
                    job.operation_id, job.activity_id, job.budget_ref,
                    job.work_kind, job.fence, job.cancel_epoch) != (
                    *namespace.as_tuple, job_id, original_id,
                    original.activity_id, original.budget_ref,
                    "d06.encode_source", original.fence, 0)
                or job.phase not in {"running", "completed"}
                or not _job_acquire_id_matches(
                    acquire_id, namespace, job_id, original_id, actor,
                    metadata.requirements.activation_generation)):
            raise UnavailableGuard("V3 recovery original acquire differs; HOLD")
        if db.execute(
                "SELECT 1 FROM runtime_encoding_call_redactions_v1 "
                "WHERE bot=? AND persona=? AND "
                "(acquire_operation_id=? OR call_id=? OR source_id=?) LIMIT 1",
                namespace.as_tuple + (
                    acquire_id, binding.call_id, binding.source_id),
        ).fetchone() is not None:
            raise UnavailableGuard("V3 recovery original call was redacted; HOLD")
        job_key = runtime_job_key(*namespace.as_tuple, job.activity_id, job_id)
        current_job_atom = db.execute(
            "SELECT value,valid FROM graph_atoms WHERE token=?",
            (job_key.token,),
        ).fetchone()
        original_job_atom = db.execute(
            "SELECT value FROM graph_history WHERE token=? AND valid=1 "
            "AND event_bot=? AND event_persona=? AND event_session=? "
            "AND event_id=?",
            (job_key.token, *namespace.as_tuple, job.activity_id, acquire_id),
        ).fetchone()
        if (current_job_atom != (canonical_json(job_graph_write(job).value), 1)
                or original_job_atom != (
                    canonical_json(job_graph_write(original).value),)):
            raise UnavailableGuard("V3 recovery job graph history differs; HOLD")
        source_key_value = source_key(*namespace.as_tuple, binding.source_id)
        access_key_value = access_key(*namespace.as_tuple, binding.source_id)
        source_row = db.execute(
            "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
            (source_key_value.token,),
        ).fetchone()
        access_row = db.execute(
            "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
            (access_key_value.token,),
        ).fetchone()
        if (source_row is None or access_row is None
                or (source_row[0], source_row[2]) != (
                    binding.source_revision, 1)
                or (access_row[0], access_row[2]) != (
                    binding.access_revision, 1)
                or db.execute(
                    "SELECT dependency_revision FROM graph_dependencies "
                    "WHERE dependent_token=? AND dependency_token=?",
                    (access_key_value.token, source_key_value.token),
                ).fetchone() != (binding.source_revision,)):
            raise UnavailableGuard("V3 recovery source/access revoked; HOLD")
        source = SourceRecord.from_dict(json.loads(source_row[1]))
        access = json.loads(access_row[1])
        validate_access(access)
        frozen_authority = frozen["envelope"]["authority"]
        audience = frozen_authority["audience"]
        if (source.source_id != binding.source_id
                or access["source_id"] != binding.source_id
                or access["status"] != "active"
                or "consolidation" not in source.purposes
                or "consolidation" not in access["purposes"]
                or type(audience) is not list or not audience
                or not set(audience).issubset(source.audiences)
                or not set(audience).issubset(access["audiences"])
                or frozen_authority["actor"] != actor
                or frozen_authority["worker_fence"] != original.fence):
            raise UnavailableGuard("V3 recovery source scope differs; HOLD")
        baseline = self._committed_first_ingress_baseline_locked(
            namespace, binding.source_id, metadata, epoch,
            acquire_stamp=(acquired_revision, acquired_epoch))
        if frozen["baseline"] != asdict(baseline):
            raise UnavailableGuard("V3 recovery baseline differs; HOLD")
        receipt = db.execute(
            "SELECT activity_id,receipt_json FROM graph_bundle_operations "
            "WHERE bot=? AND persona=? AND operation_id=?",
            namespace.as_tuple + (original_id,),
        ).fetchone()
        expected = ingress_ids(binding.source_id)
        if (receipt is None or receipt[0] != job.activity_id
                or (expected[1], expected[2], expected[3]) != (
                    job.activity_id, original_id, job_id)
                or job_key.token not in json.loads(receipt[1]).get(
                    "ledger_refs", ())):
            raise UnavailableGuard("V3 recovery ingress receipt differs; HOLD")
        self._original_first_ingress_qualification_locked(
            namespace, original_id, source_key_value.token)
        outbox_refs = json.loads(receipt[1]).get("outbox_refs")
        if type(outbox_refs) is not list or len(outbox_refs) != 1:
            raise UnavailableGuard("V3 recovery original outbox differs; HOLD")
        outbox_token = outbox_refs[0]
        outbox_key = AtomKey.from_token(outbox_token)
        historical_outbox = db.execute(
            "SELECT value FROM graph_history WHERE token=? AND valid=1 "
            "AND event_bot=? AND event_persona=? AND event_session=? "
            "AND event_id=?",
            (outbox_token, *namespace.as_tuple, job.activity_id, original_id),
        ).fetchall()
        if len(historical_outbox) != 1:
            raise UnavailableGuard("V3 recovery original outbox absent; HOLD")
        outbox = RuntimeOutboxValue(**json.loads(historical_outbox[0][0]))
        if (outbox_key.type_name != "runtime.outbox"
                or outbox_key.owner != Owner(
                    "activity", *namespace.as_tuple, job.activity_id)
                or outbox.payload_ref != binding.source_id
                or outbox.job_ref != job_key.token
                or outbox.operation_id != original_id
                or outbox.job_id != job_id
                or outbox.phase != "pending"
                or outbox.outbox_id != expected[4]
                or outbox.idempotency_key != expected[5]):
            raise UnavailableGuard("V3 recovery original outbox changed; HOLD")
        quote_ref = job.operator_versions.get("resource_quote")
        if type(quote_ref) is not str or ":" not in quote_ref:
            raise UnavailableGuard("V3 recovery signed quote absent; HOLD")
        quote_id, version_text = quote_ref.rsplit(":", 1)
        quote = self.__d02_issuer.original_signed_quote(
            db, quote_id, int(version_text))
        reservation = db.execute(
            "SELECT digest,ceiling_json FROM runtime_budget_reservations "
            "WHERE lease_id=? AND operation_id=?",
            (job.budget_ref, original_id),
        ).fetchone()
        reserve_receipt = db.execute(
            "SELECT digest FROM runtime_budget_operations WHERE bot_id=? "
            "AND persona_id=? AND operation_id=? AND phase='reserve'",
            namespace.as_tuple + (original_id,),
        ).fetchone()
        if (quote.graph_job_ref != job_key.token
                or quote.operation_id != original_id
                or quote.activity_id != job.activity_id
                or quote.parent_budget_lease_ref != job.budget_ref
                or reservation is None or reserve_receipt is None
                or reservation != (reserve_receipt[0],
                                   canonical_json(quote.ceiling))):
            raise UnavailableGuard("V3 recovery original budget differs; HOLD")
        consumer_id = first_ingress_c02_consumer_operation_id_v1(
            namespace=namespace,
            authority_id=metadata.requirements.authority_id,
            authority_namespace=metadata.requirements.authority_namespace,
            installation_id=installation_id, job_id=job_id,
            acquire_operation_id=acquire_id,
            original_operation_id=original_id, call_id=binding.call_id,
            binding_digest=binding.binding_digest,
            model_request_digest=binding.model_request_digest)
        c02 = db.execute(
            "SELECT digest,commit_seq,receipt_json FROM "
            "graph_bundle_operations WHERE bot=? AND persona=? "
            "AND operation_id=?",
            namespace.as_tuple + (consumer_id,),
        ).fetchone()
        pending_c02 = db.execute(
            "SELECT digest FROM graph_bundle_intents_v2 WHERE bot=? "
            "AND persona=? AND operation_id=?",
            namespace.as_tuple + (consumer_id,),
        ).fetchone()
        if job.phase == "running":
            if (c02 is not None or job.lease_holder != actor
                    or job.lease_expires_utc != original.lease_expires_utc
                    or job.result_ref is not None):
                raise UnavailableGuard("V3 recovery original lease changed; HOLD")
            expires = datetime.fromisoformat(
                original.lease_expires_utc.replace("Z", "+00:00")).timestamp()
            state = ("c02_pending_hold" if pending_c02 is not None
                     else "expired_lease_hold" if now >= expires
                     else "original_fence")
            c02_digest = c02_seq = None
        else:
            if (c02 is None or job.lease_holder is not None
                    or job.lease_expires_utc is not None or not job.result_ref):
                raise UnavailableGuard("V3 recovery completion receipt absent; HOLD")
            detail = json.loads(c02[2]).get("first_ingress_c02")
            event = db.execute(
                "SELECT 1 FROM graph_events WHERE bot=? AND persona=? "
                "AND session=? AND event_id=?",
                namespace.as_tuple + (job.activity_id, consumer_id),
            ).fetchone()
            fence = db.execute(
                "SELECT digest FROM graph_bundle_fences_v2 WHERE bot=? "
                "AND persona=? AND operation_id=?",
                namespace.as_tuple + (consumer_id,),
            ).fetchone()
            episode = episode_key(*namespace.as_tuple, job.result_ref)
            episode_row = db.execute(
                "SELECT valid FROM graph_atoms WHERE token=?", (episode.token,),
            ).fetchone()
            if (type(detail) is not dict or event is None
                    or fence != (c02[0],) or episode_row != (1,)
                    or type(c02[1]) is not int or c02[1] < 1):
                raise UnavailableGuard("V3 recovery C02 receipt differs; HOLD")
            state, c02_digest, c02_seq = "c02_committed", c02[0], c02[1]
        return FirstIngressRecoveryItemV1(
            namespace, installation_id, job_id, acquire_id, original_id,
            binding.call_id, binding.binding_digest,
            binding.model_request_digest, consumer_id, job.phase, actor,
            original.fence, original.lease_expires_utc, state,
            c02_digest, c02_seq)

