    def _commit_original_model_cost_v1(
        self, bootstrap: object, namespace: NamespaceId, original_intent,
        *, quote_id: str, quote_version: int, work_kind: str,
    ):
        """Commit one original model cost bundle, independent of D06 content.

        The installed ports own mTLS credentials. Their calls happen only
        outside GraphStore's lock; the signed quote and D11 reservation are
        re-read in the single graph transaction. A fence attempt is durable
        before begin, while the business operation stays fixed to call_id.
        """
        from .authority_service.v2_accounting_contract import (
            AccountingMaintenanceGrantV1, AccountingMaintenanceRequestV1,
        )
        from .authority_service.v2_model_egress_contract import ModelEgressIntentV1
        from .runtime.restore_anchor import RestoreAnchor
        from .runtime.model_cost_settlement import (
            OriginalModelCostCommitV1, apply_original_model_budget_in_transaction,
            prepare_original_model_cost_plan, read_original_model_cost,
        )
        from .runtime.d11_types import (
            D11_PROPOSAL_SCHEMA, D11_PROPOSAL_SCHEMA_HASH, validate_d11_writes,
        )
        from .runtime_contracts import (
            CommandEnvelope, DependencySet, DomainProposal, OperationIdentity,
            RUNTIME_SCHEMA,
        )

        self._admin(bootstrap)
        if (type(namespace) is not NamespaceId
                or type(original_intent) is not ModelEgressIntentV1
                or not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or self.__model_terminal_cost_port is None
                or self.__accounting_maintenance_port is None
                or self.__d02_issuer is None or self.__d11_issuer is None):
            raise UnavailableGuard("installed original model accounting authorities required")
        store, port = self.__store, self.__accounting_maintenance_port
        # The receipt is an Authority fact, never a caller-supplied cost.
        fact = read_original_model_cost(self.__model_terminal_cost_port, original_intent)
        if fact.recovery.state != "observed":
            raise UnavailableGuard("unobserved model cost retains original upper bound; HOLD")
        intent_digest = canonical_digest(asdict(original_intent))
        terminal_digest = canonical_digest(asdict(fact.receipt))
        from .runtime.model_cost_settlement import original_model_cost_operation_id_v1
        operation_id = original_model_cost_operation_id_v1(
            namespace, original_intent.call_id)

        def business_receipt_locked():
            row = store._db.execute(
                "SELECT activity_id,commit_seq,receipt_json "
                "FROM graph_bundle_operations WHERE bot=? "
                "AND persona=? AND operation_id=?", namespace.as_tuple + (operation_id,),
            ).fetchone()
            if row is None:
                return None
            data = json.loads(row[2])
            signed_quote = self.__d02_issuer.original_signed_quote(
                store._db, quote_id, quote_version)
            if (data.get("original_intent_digest") != intent_digest
                    or data.get("terminal_receipt_digest") != terminal_digest
                    or data.get("quote_id") != quote_id
                    or data.get("quote_version") != quote_version
                    or signed_quote.work_kind != work_kind
                    or data.get("work_kind", work_kind) != work_kind):
                raise EventConflict("original model cost operation identity differs")
            committed = OriginalModelCostCommitV1(**data["original_model_cost"])
            graph_event = store._db.execute(
                "SELECT 1 FROM graph_events WHERE bot=? AND persona=? "
                "AND session=? AND event_id=?", namespace.as_tuple +
                (row[0], operation_id),
            ).fetchone()
            atom = store._db.execute(
                "SELECT 1 FROM graph_atoms WHERE token=? AND valid=1",
                (committed.cost_ref,),
            ).fetchone()
            budget = store._db.execute(
                "SELECT 1 FROM runtime_budget_operations WHERE bot_id=? "
                "AND persona_id=? AND operation_id=? AND phase='settle'",
                namespace.as_tuple + (original_intent.budget_reservation_operation_id,),
            ).fetchone()
            if (committed.status != "committed"
                    or committed.operation_id != operation_id
                    or committed.call_id != original_intent.call_id
                    or committed.quote_id != quote_id
                    or committed.quote_version != quote_version
                    or committed.terminal_receipt_digest != terminal_digest
                    or committed.commit_seq != row[1]
                    or graph_event is None or atom is None or budget is None):
                raise UnavailableGuard("original cost business receipt is incomplete")
            return committed

        with store._lock:
            committed = business_receipt_locked()
            metadata, _ = self._v2_graph_stamp(namespace)
            attempt = store._db.execute(
                "SELECT intent_digest,attempt_id,anchor_json,state FROM "
                "graph_original_model_cost_attempts_v1 WHERE bot=? AND persona=? "
                "AND call_id=?", namespace.as_tuple + (original_intent.call_id,),
            ).fetchone()
        if committed is not None:
            if attempt is None or attempt[0] != intent_digest or attempt[3] != "committed":
                raise UnavailableGuard("committed cost lacks original fence attempt")
            request = AccountingMaintenanceRequestV1(
                attempt[1], original_intent, RestoreAnchor(**json.loads(attempt[2])))
            port.recover_finish(request)
            return replace(committed, status="duplicate")
        target = metadata.requirements
        if (original_intent.authority_id != target.authority_id
                or original_intent.namespace != target.authority_namespace):
            raise UnavailableGuard("original model call belongs to another authority")

        if attempt is not None and attempt[3] == "open":
            if attempt[0] != intent_digest:
                raise EventConflict("original call ID reused with different intent")
            # A prior invocation may have rolled back after begin or lost its
            # finish reply. First prove no business receipt, then close it.
            old_request = AccountingMaintenanceRequestV1(
                attempt[1], original_intent, RestoreAnchor(**json.loads(attempt[2])))
            try:
                port.recover_finish(old_request)
            except Exception:
                # The durable local intent may precede Authority begin. The
                # exact same attempt ID is safe to begin or replay; any other
                # Authority failure remains HOLD rather than minting a new ID.
                old_grant = port.begin(old_request)
                port.finish(old_request, old_grant)
            with store._lock:
                if business_receipt_locked() is not None:
                    raise UnavailableGuard("cost committed during fence recovery; retry")
                store._db.execute(
                    "UPDATE graph_original_model_cost_attempts_v1 SET state='closed' "
                    "WHERE bot=? AND persona=? AND call_id=? AND attempt_id=? "
                    "AND state='open'", namespace.as_tuple +
                    (original_intent.call_id, attempt[1]),
                )

        # current_anchor is an Authority network read. It is outside the
        # graph lock and can advance past a completed source deletion.
        anchor = self.__content_fence_v2.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._accounting_anchor_covers(target, anchor):
            raise UnavailableGuard("accounting Authority anchor differs from graph history")
        attempt_id = "model-cost-fence-" + secrets.token_hex(24)
        request = AccountingMaintenanceRequestV1(attempt_id, original_intent, anchor)
        with store._lock:
            db = store._db
            db.execute("BEGIN IMMEDIATE")
            try:
                if business_receipt_locked() is not None or self._v2_graph_stamp(namespace)[0] != metadata:
                    raise StaleRead("original cost graph changed before accounting fence")
                row = db.execute(
                    "SELECT state FROM graph_original_model_cost_attempts_v1 "
                    "WHERE bot=? AND persona=? AND call_id=?",
                    namespace.as_tuple + (original_intent.call_id,),
                ).fetchone()
                if row is not None and row[0] != "closed":
                    raise UnavailableGuard("original cost fence attempt remains open")
                if attempt is not None and attempt[0] != intent_digest:
                    raise EventConflict("original call ID reused with different intent")
                db.execute(
                    "INSERT INTO graph_original_model_cost_attempts_v1"
                    "(bot,persona,call_id,intent_digest,attempt_id,anchor_json,state) "
                    "VALUES(?,?,?,?,?,?,'open') ON CONFLICT(bot,persona,call_id) "
                    "DO UPDATE SET intent_digest=excluded.intent_digest,"
                    "attempt_id=excluded.attempt_id,anchor_json=excluded.anchor_json,"
                    "state='open'", namespace.as_tuple +
                    (original_intent.call_id, intent_digest, attempt_id,
                     canonical_json(asdict(anchor))),
                )
                db.commit()
            except BaseException:
                db.rollback()
                raise
        grant = port.begin(request)
        if type(grant) is not AccountingMaintenanceGrantV1 or (
                grant.call_id != original_intent.call_id
                or grant.admission_id != fact.admission.admission_id
                or grant.reservation_digest != original_intent.budget_reservation_digest
                or grant.observation_digest != fact.recovery.observation_digest
                or grant.terminal_receipt_digest != terminal_digest
                or grant.permit.operation_id != attempt_id
                or grant.permit.pinned_anchor != anchor):
            raise UnavailableGuard("accounting grant differs from original Authority fact")
        port.validate(request, grant)

        result = None
        try:
            with store._lock:
                db = store._db
                db.execute("BEGIN IMMEDIATE")
                try:
                    current, epoch = self._v2_graph_stamp(namespace)
                    if current != metadata or not self._accounting_anchor_covers(
                            current.requirements, anchor):
                        raise StaleRead("accounting graph stamp changed")
                    row = db.execute(
                        "SELECT attempt_id,state FROM graph_original_model_cost_attempts_v1 "
                        "WHERE bot=? AND persona=? AND call_id=?",
                        namespace.as_tuple + (original_intent.call_id,),
                    ).fetchone()
                    if row != (attempt_id, "open") or business_receipt_locked() is not None:
                        raise StaleRead("original cost business operation changed")
                    plan = prepare_original_model_cost_plan(
                        db, self.__d02_issuer, namespace, fact,
                        quote_id=quote_id, quote_version=quote_version,
                        work_kind=work_kind)
                    if plan.bundle_operation_id != operation_id:
                        raise EventConflict("original cost operation differs")
                    application = apply_original_model_budget_in_transaction(
                        db, self.__d02_issuer, plan, fact)
                    write = application.cost_write
                    if not validate_d11_writes(
                            (write,), namespace, operation_id=operation_id,
                            activity_id=plan.quote.activity_id,
                            effect_id=plan.quote.effect_id):
                        raise UnavailableGuard("D11 cost write is invalid")
                    reconcile_runtime_write(db, write)
                    identity = OperationIdentity(
                        plan.quote.activity_id, plan.quote.effect_id,
                        original_intent.call_id, "accounting", operation_id,
                        canonical_digest({"input_refs": []}))
                    authority = AuthorityContext(
                        "host", "d11", "accounting:" + attempt_id,
                        namespace, ("activity",), "cost_accounting", ("internal",),
                        "original-model-cost-v1", target.activation_generation)
                    epochs = db.execute(
                        "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                        "WHERE bot=? AND persona=?", namespace.as_tuple,
                    ).fetchone() or (0, 0)
                    envelope = CommandEnvelope(
                        RUNTIME_SCHEMA, identity, authority,
                        VersionGuard((GraphVersion(write.key, 0),), (), *epochs,
                                     "accounting-v1", "accounting-v1",
                                     "accounting-v1", "accounting-v1", (), (), ()),
                        SourceQualification((), "derived", None, time.time(),
                                            "unknown", "ineligible", None,
                                            "not_applicable"),
                        (), plan.quote.parent_budget_lease_ref,
                        plan.quote.deadline_utc, 0.0, "accounting-v1",
                        (plan.original_operation_id,))
                    proposal = DomainProposal(
                        "d11", D11_PROPOSAL_SCHEMA, D11_PROPOSAL_SCHEMA_HASH,
                        envelope, (write,), DependencySet(), (), ("cost_settlement",))
                    bundle = DomainBundle(
                        envelope, (proposal,), (), (), (), (write.key.token,),
                        (), (), ())
                    event = Event(
                        Scope(*namespace.as_tuple, plan.quote.activity_id),
                        operation_id, time.time(), "domain_bundle",
                        {"bundle_digest": bundle.digest})
                    candidate = GraphCandidate(
                        event, (GraphVersion(write.key, 0),), (write,), (epoch,))
                    graph_receipt = GraphStore._graph_commit_in_transaction(
                        store, candidate, _capability=self.__graph_capability)
                    if graph_receipt.status != "committed":
                        raise EventConflict("original cost graph event already exists")
                    replacement = replace(
                        current.requirements,
                        deletion_seq=anchor.deletion_seq,
                        deletion_digest=anchor.deletion_digest,
                        execution_seq=anchor.execution_seq,
                        execution_digest=anchor.execution_digest,
                        revocation_epoch=anchor.revocation_epoch)
                    store.cas_graph_recovery_metadata(
                        current, replacement, _capability=self.__graph_capability)
                    seq_row = db.execute(
                        "SELECT last_seq FROM graph_bundle_sequence WHERE bot=? AND persona=?",
                        namespace.as_tuple).fetchone()
                    seq = (seq_row[0] if seq_row else 0) + 1
                    db.execute(
                        "INSERT INTO graph_bundle_sequence(bot,persona,last_seq) "
                        "VALUES(?,?,?) ON CONFLICT(bot,persona) DO UPDATE SET "
                        "last_seq=excluded.last_seq", namespace.as_tuple + (seq,))
                    result = OriginalModelCostCommitV1(
                        "committed", operation_id, original_intent.call_id,
                        quote_id, quote_version, terminal_digest, write.key.token,
                        canonical_digest(asdict(application.receipt)), seq,
                        current.graph_revision + 1, graph_receipt.epoch.revision)
                    receipt_data = {
                        "original_model_cost": asdict(result),
                        "original_intent_digest": intent_digest,
                        "terminal_receipt_digest": terminal_digest,
                        "quote_id": quote_id, "quote_version": quote_version,
                        "work_kind": work_kind,
                        "accounting_attempt_id": attempt_id,
                    }
                    db.execute(
                        "INSERT INTO graph_bundle_operations"
                        "(bot,persona,operation_id,digest,activity_id,effect_id,"
                        "commit_seq,receipt_json) VALUES(?,?,?,?,?,?,?,?)",
                        namespace.as_tuple + (
                            operation_id, bundle.digest, plan.quote.activity_id,
                            plan.quote.effect_id, seq, canonical_json(receipt_data)))
                    db.execute(
                        "UPDATE graph_original_model_cost_attempts_v1 "
                        "SET state='committed' WHERE bot=? AND persona=? "
                        "AND call_id=? AND attempt_id=?", namespace.as_tuple +
                        (original_intent.call_id, attempt_id))
                    db.commit()
                except BaseException:
                    db.rollback()
                    raise
        except BaseException:
            # The business transaction rolled back. Closing this *attempt*
            # leaves the fixed business operation and reservation untouched.
            with store._lock:
                committed = business_receipt_locked()
            if committed is not None:
                port.recover_finish(request)
                return replace(committed, status="duplicate")
            port.finish(request, grant)
            with store._lock:
                store._db.execute(
                    "UPDATE graph_original_model_cost_attempts_v1 SET state='closed' "
                    "WHERE bot=? AND persona=? AND call_id=? AND attempt_id=? "
                    "AND state='open'", namespace.as_tuple +
                    (original_intent.call_id, attempt_id))
            raise
        port.finish(request, grant)
        return result

    def _qualified_first_ingress_acquire_return(
        self, namespace: NamespaceId, job_id: str, expected: PersistentJob,
        actor: str, clock, lease_seconds: int, *,
        original_context_verified: bool = False,
    ) -> PersistentJob:
        from datetime import datetime, timezone

        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.issuers import IssuerAuthorityDenied

        try:
            now = trusted_upper(clock)
            now_text = datetime.fromtimestamp(now, timezone.utc).isoformat().replace(
                "+00:00", "Z")
            with self.__store._lock:
                current = self._first_ingress_encoding_job_locked(namespace, job_id)[0]
                if not original_context_verified:
                    self.__d11_issuer.authorize_existing_encoding_job(
                        self.__store._db, current, now_utc=now)
            if (current != expected or current.lease_holder != actor
                    or plan_job_acquire(current, actor, now_utc=now_text,
                                        lease_seconds=lease_seconds) != current):
                raise UnavailableGuard("job acquire result lost runnable eligibility; HOLD")
        except IssuerAuthorityDenied as exc:
            raise UnavailableGuard(
                "job acquire lost original signed authority; HOLD") from exc
        except Exception as exc:
            raise UnavailableGuard("job acquire result lost runnable eligibility; HOLD") from exc
        return current

    def _committed_first_ingress_baseline_locked(
        self, namespace, source_id, metadata, epoch, *, acquire_stamp=None,
    ):
        """Read the one previously committed D04 baseline in this graph snapshot."""
        from .authority_service.current_d04_baseline_graph_proof import (
            committed_baseline_current,
        )
        from .runtime.encoding_call_binding import CommittedEncodingBaselineV1

        db = self.__store._db
        opened = not db.in_transaction
        if opened:
            db.execute("BEGIN")
        try:
            source_ref = source_key(*namespace.as_tuple, source_id).token
            if db.execute(
                    "SELECT 1 FROM sqlite_master WHERE type='table' "
                    "AND name='graph_d04_baseline_issuance_v1'",
            ).fetchone() is None:
                raise UnavailableGuard("committed D04 baseline absent; HOLD")
            issued = db.execute(
                "SELECT operation_id,bundle_digest FROM "
                "graph_d04_baseline_issuance_v1 WHERE bot=? AND persona=? "
                "AND source_ref=?",
                namespace.as_tuple + (source_ref,),
            ).fetchall()
            if len(issued) != 1:
                raise UnavailableGuard("one committed D04 baseline required; HOLD")
            operation_id, bundle_digest = issued[0]
            writes = db.execute(
                "SELECT h.token,h.revision FROM graph_history AS h "
                "JOIN graph_atoms AS a ON a.token=h.token "
                "WHERE h.event_bot=? AND h.event_persona=? AND h.event_id=? "
                "AND a.type_name='d04.encoding_baseline.v1' AND h.valid=1",
                namespace.as_tuple + (operation_id,),
            ).fetchall()
            fence = db.execute(
                "SELECT post_graph_epoch FROM graph_bundle_fences_v2 "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone()
            if len(writes) != 1 or fence is None:
                raise UnavailableGuard("committed D04 baseline history absent; HOLD")
            baseline = CommittedEncodingBaselineV1(
                writes[0][0], writes[0][1], operation_id, bundle_digest,
                metadata.requirements.graph_incarnation, fence[0],
            )
            acquire_revision, acquire_epoch = (
                acquire_stamp if acquire_stamp is not None else
                (metadata.graph_revision, epoch.revision))
            if not committed_baseline_current(
                    db, namespace=namespace, baseline=baseline,
                    source_id=source_id, requirements=metadata.requirements,
                    current_graph_revision=metadata.graph_revision,
                    current_graph_epoch=epoch.revision,
                    acquire_graph_revision=acquire_revision,
                    acquire_graph_epoch=acquire_epoch,
                    issuer=self.__d11_issuer):
                raise UnavailableGuard("committed D04 baseline proof differs; HOLD")
            return baseline
        finally:
            if opened:
                db.execute("ROLLBACK")

    def _first_ingress_encoding_issue_context(
        self, namespace, planned, outbox, source_version, access_version,
        authority, now_utc, acquire_operation_id, clock_reading,
        frozen_binding=None, *, require_baseline_v3=False,
    ) -> FirstIngressEncodingIssueContextV2:
        """Gather current graph truth and the original D06 qualification."""
        from datetime import datetime
        with self.__store._lock:
            (current, _, _, current_outbox, _, _, current_source,
             current_access) = self._first_ingress_encoding_job_locked(
                 namespace, planned.job_id)
            if (current.operation_id != planned.operation_id
                    or current_outbox != outbox
                    or current_source != source_version
                    or current_access != access_version):
                raise UnavailableGuard("encoding source or access changed; HOLD")
            row = self.__store._db.execute(
                "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                (source_version.key.token,),
            ).fetchone()
            access_row = self.__store._db.execute(
                "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                (access_version.key.token,),
            ).fetchone()
            if (access_row is None or access_row[0] != access_version.revision
                    or access_row[2] != 1):
                raise UnavailableGuard("encoding current access changed; HOLD")
            try:
                access_value = json.loads(access_row[1])
                validate_access(access_value)
            except (TypeError, ValueError, KeyError) as exc:
                raise UnavailableGuard("encoding current access invalid; HOLD") from exc
            if (access_value["status"] != "active"
                    or access_value["source_id"] != outbox.payload_ref
                    or authority.purpose not in access_value["purposes"]
                    or not set(authority.audience).issubset(
                        access_value["audiences"])):
                raise UnavailableGuard(
                    "encoding worker exceeds current access grant; HOLD")
            epochs = self.__store._db.execute(
                "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                "WHERE bot=? AND persona=?", namespace.as_tuple,
            ).fetchone()
            if epochs is None:
                raise UnavailableGuard("encoding authority epochs absent; HOLD")
            needs_baseline = (require_baseline_v3 or frozen_binding is not None
                              and frozen_binding.request.get("schema") ==
                              "sylanne.first-ingress-encoding-call.v3")
            if needs_baseline:
                metadata, epoch = self._v2_graph_stamp(namespace)
                acquire_stamp = None
                if frozen_binding is not None:
                    acquire_stamp = self.__store._db.execute(
                        "SELECT graph_revision,graph_epoch FROM "
                        "graph_job_acquire_intents_v2 WHERE bot=? AND persona=? "
                        "AND acquire_operation_id=?",
                        namespace.as_tuple + (acquire_operation_id,),
                    ).fetchone()
                    if acquire_stamp is None:
                        raise UnavailableGuard("original V3 acquire stamp absent; HOLD")
                baseline = self._committed_first_ingress_baseline_locked(
                    namespace, outbox.payload_ref, metadata, epoch,
                    acquire_stamp=acquire_stamp)
                baseline_versions = (GraphVersion(
                    AtomKey.from_token(baseline.baseline_ref),
                    baseline.baseline_revision),)
            else:
                baseline = None
                baseline_versions = ()
            guard = VersionGuard(
                (source_version, access_version) + baseline_versions,
                (), epochs[0], epochs[1],
                self.__store._registry.catalogue_hash,
                self._version(self.__store._db, namespace, "scheme", "current"),
                self._version(self.__store._db, namespace, "operator", "current"),
                self._version(self.__store._db, namespace, "policy", "current"),
                (), (), (),
            )
            qualification = self._original_first_ingress_qualification_locked(
                namespace, planned.operation_id, source_version.key.token)
            issuance = self.__store._db.execute(
                "SELECT policy_json FROM runtime_ingress_issuance "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (planned.operation_id,),
            ).fetchone()
            if issuance is None:
                raise UnavailableGuard("original encoding interval absent; HOLD")
            try:
                character_interval_ref = IngressIssuancePolicy(
                    **json.loads(issuance[0])).character_interval_ref
            except (TypeError, ValueError, KeyError) as exc:
                raise UnavailableGuard("original encoding interval invalid; HOLD") from exc
        if row is None or row[0] != source_version.revision or row[2] != 1:
            raise UnavailableGuard("encoding source changed before request issue; HOLD")
        source = SourceRecord.from_dict(json.loads(row[1]))
        if source.source_id != outbox.payload_ref:
            raise UnavailableGuard("encoding source differs from original outbox")
        job_deadline = datetime.fromisoformat(
            planned.deadline_utc.replace("Z", "+00:00")).timestamp()
        worker_deadline = datetime.fromisoformat(
            planned.lease_expires_utc.replace("Z", "+00:00")).timestamp()
        deadline = min(job_deadline, worker_deadline)
        if now_utc >= deadline:
            raise UnavailableGuard("encoding request deadline expired; HOLD")
        try:
            clock_epoch = clock_reading.sample.epoch
            clock_source = clock_reading.sample.source_id
            if (type(clock_epoch) is not str or not clock_epoch
                    or clock_source != self.__scene_clock_policy.source_id):
                raise ValueError("paired clock identity is invalid")
            current_monotonic_deadline = clock_reading.monotonic_after_seconds + (
                deadline - clock_reading.utc_upper_bound_seconds)
            if (not math.isfinite(current_monotonic_deadline)
                    or time.monotonic() >= current_monotonic_deadline):
                raise ValueError("paired monotonic deadline expired")
            # The frozen envelope value is request identity. Every check uses
            # this process's freshly rebuilt deadline from the paired sample.
            monotonic_deadline = current_monotonic_deadline
            if frozen_binding is not None:
                frozen = frozen_binding.request
                if (frozen.get("schema") not in {
                        "sylanne.first-ingress-encoding-call.v2",
                        "sylanne.first-ingress-encoding-call.v3"}
                        or frozen.get("clock_epoch") != clock_epoch
                        or frozen.get("acquire_operation_id") != acquire_operation_id):
                    raise ValueError("frozen clock epoch or acquire differs")
                monotonic_deadline = frozen["envelope"]["monotonic_deadline"]
                if (type(monotonic_deadline) not in (int, float)
                        or not math.isfinite(monotonic_deadline)):
                    raise ValueError("frozen monotonic deadline invalid")
        except (AttributeError, KeyError, TypeError, ValueError) as exc:
            raise UnavailableGuard("paired encoding clock context unavailable; HOLD") from exc
        return FirstIngressEncodingIssueContextV2(
            planned, source, replace(authority, worker_fence=planned.fence),
            source_version.revision, access_version.revision,
            tuple(access_value["audiences"]), tuple(access_value["purposes"]),
            guard, qualification, now_utc, deadline, worker_deadline,
            acquire_operation_id, character_interval_ref, clock_epoch,
            monotonic_deadline, current_monotonic_deadline, baseline)

    def _issue_first_ingress_encoding_binding(
        self, namespace, planned, outbox, source_version, access_version,
        authority, now_utc, acquire_operation_id, clock_reading,
        frozen_binding=None, *, require_baseline_v3=False,
    ):
        """Freeze the installed pure issuer output for one planned worker fence."""
        from .runtime.encoding_call_binding import (
            EncodingRequestIssueV2, prepare_binding,
        )
        from .model_broker.first_ingress_encoding import (
            FIRST_INGRESS_ENCODING_TEMPLATE_VERSION,
        )

        context = self._first_ingress_encoding_issue_context(
            namespace, planned, outbox, source_version, access_version,
            authority, now_utc, acquire_operation_id, clock_reading,
            frozen_binding, require_baseline_v3=require_baseline_v3)
        issue = self.__encoding_request_issuer(context)
        if type(issue) is not EncodingRequestIssueV2:
            raise UnavailableGuard("production encoding requires a V2 request issuer; HOLD")
        request = issue.request
        if (request.envelope.identity.activity_id != planned.activity_id
                or request.envelope.authority != context.authority
                or request.envelope.version_guard != context.version_guard
                or request.envelope.source_qualification != context.source_qualification
                or request.envelope.identity.operation_id != acquire_operation_id
                or request.envelope.identity.phase != "encode"
                or request.envelope.monotonic_deadline != context.monotonic_deadline
                or request.envelope.character_interval_ref
                != context.character_interval_ref
                or request.envelope.deadline_utc != context.deadline_utc
                or request.envelope.deadline_utc <= context.now_utc):
            raise UnavailableGuard("encoding request differs from trusted issuance context")
        return prepare_binding(
            namespace, planned.job_id, context.source, source_version.revision,
            access_version.revision, planned.budget_ref, planned.operation_id,
            request, prompt_template_version=FIRST_INGRESS_ENCODING_TEMPLATE_VERSION,
            provider_config_ref=issue.provider_config_ref,
            provider_config_digest=issue.provider_config_digest,
            production_context=context,
            baseline=context.baseline,
        )

    def _validate_first_ingress_encoding_binding_context(
        self, namespace, job, outbox, source_version, access_version,
        authority, now_utc, acquire_operation_id, clock_reading, binding,
    ) -> None:
        """Recheck frozen issuer claims against current worker and graph truth."""
        context = self._first_ingress_encoding_issue_context(
            namespace, job, outbox, source_version, access_version,
            authority, now_utc, acquire_operation_id, clock_reading, binding,
            require_baseline_v3=(binding.request.get("schema") ==
                                 "sylanne.first-ingress-encoding-call.v3"))
        envelope = binding.request["envelope"]
        if (binding.request.get("schema") not in {
                "sylanne.first-ingress-encoding-call.v2",
                "sylanne.first-ingress-encoding-call.v3"}
                or (context.baseline is not None and
                    binding.request.get("baseline") != asdict(context.baseline))
                or binding.request.get("original_operation_id")
                != context.job.operation_id
                or binding.request.get("worker_fence") != context.job.fence
                or binding.request.get("worker_lease_expires_utc")
                != context.job.lease_expires_utc
                or envelope.get("character_interval_ref")
                != context.character_interval_ref
                or envelope.get("monotonic_deadline")
                != context.monotonic_deadline
                or binding.source_revision != context.source_revision
                or binding.access_revision != context.access_revision
                or canonical_serialize(envelope["authority"])
                != canonical_serialize(context.authority)
                or canonical_serialize(envelope["version_guard"])
                != canonical_serialize(context.version_guard)
                or canonical_serialize(envelope["source_qualification"])
                != canonical_serialize(context.source_qualification)
                or not context.now_utc < envelope["deadline_utc"]
                <= context.deadline_utc):
            raise UnavailableGuard("encoding binding lost trusted issuance context; HOLD")

    def acquire_first_ingress_encoding_job_v3(
        self, authority: AuthorityContext, lease: object, job_id: str,
        acquire_operation_id: str, *, lease_seconds: int,
    ) -> PersistentJob:
        """Acquire new first-ingress work only with a committed D04 baseline."""
        return self.acquire_first_ingress_encoding_job_v2(
            authority, lease, job_id, acquire_operation_id,
            lease_seconds=lease_seconds, _require_baseline_v3=True)

    def _acquire_source_correction_job_v1(
        self, authority: AuthorityContext, lease: object, job_id: str,
        acquire_operation_id: str, *, lease_seconds: int,
    ) -> PersistentJob:
        """Acquire a committed correction job; leave its head and outbox pending.

        The caller is a trusted D11 scheduler. Authority RPCs occur outside the
        graph lock; the job mutation, graph projection and V2 receipt share one
        GraphStore transaction. This is not a reevaluation or cost settlement.
        """
        from datetime import datetime, timezone

        from .authority_service.v2_contract import FencePermitV2, from_wire, to_wire
        from .host.authority_profile import AdminIngressClockPolicy
        from .runtime.d11_types import (
            RuntimeOutboxValue, job_graph_write, outbox_graph_write,
        )
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.issuers import D11BudgetJobIssuer
        from .runtime.source_correction_job import (
            SourceCorrectionJobHold, acquire_source_correction_job_in_transaction,
            plan_source_correction_job_acquire, read_source_correction_job_snapshot,
        )

        store = self.__store
        port = self.__content_fence_v2
        namespace = authority.namespace
        if (not isinstance(store, ProductionGraphStore) or port is None
                or type(self.__d11_issuer) is not D11BudgetJobIssuer
                or type(self.__scene_clock_policy) is not AdminIngressClockPolicy):
            raise UnavailableGuard("installed V2 D11 job and trusted clock are required; HOLD")
        self._authorize(lease, authority, frozenset({"d11"}))
        if (authority.issuer_domain != "d11" or "activity" not in authority.owner_scope
                or authority.worker_fence is not None
                or type(lease_seconds) is not int or not 1 <= lease_seconds <= 3600
                or type(acquire_operation_id) is not str
                or not acquire_operation_id or len(acquire_operation_id) > 128
                or authority.capability_ref != _operation_capability_ref(
                    namespace, authority.actor, "d11", frozenset({"d11"}),
                    authority.activation_generation, acquire_operation_id)):
            raise AuthorityDenied("D11 correction activity capability differs")
        try:
            clock = port.read_ingress_clock(self.__scene_clock_policy)
            now = trusted_upper(clock)
            now_text = datetime.fromtimestamp(now, timezone.utc).isoformat().replace(
                "+00:00", "Z")
        except Exception as exc:
            raise UnavailableGuard("correction trusted clock is unavailable; HOLD") from exc

        def read_snapshot():
            db = store._db
            db.execute("BEGIN")
            try:
                snapshot = read_source_correction_job_snapshot(
                    db, self.__d11_issuer, namespace, job_id, now_utc=now)
                db.execute("COMMIT")
                return snapshot
            except BaseException:
                db.execute("ROLLBACK")
                raise

        with store._lock:
            pre_intent = store._db.execute(
                "SELECT fence_attempt_id,graph_revision,graph_epoch FROM "
                "graph_job_acquire_intents_v2 WHERE bot=? AND persona=? "
                "AND acquire_operation_id=?",
                namespace.as_tuple + (acquire_operation_id,),
            ).fetchone()
            pre_receipt = store._db.execute(
                "SELECT post_graph_revision,post_graph_epoch FROM "
                "graph_job_acquire_receipts_v2 WHERE bot=? AND persona=? "
                "AND acquire_operation_id=?",
                namespace.as_tuple + (acquire_operation_id,),
            ).fetchone()
            pre_metadata, _ = self._v2_graph_stamp(namespace)
        active_scope = None
        if pre_intent is not None:
            pre_target = pre_metadata.requirements
            try:
                pre_anchor = port.current_anchor(
                    namespace=namespace,
                    authority_namespace=pre_target.authority_namespace)
                observed_permit, observed_state = port.get_fence_operation(
                    namespace=namespace,
                    authority_namespace=pre_target.authority_namespace,
                    operation_id=pre_intent[0])
            except Exception as exc:
                raise JobAcquireOutcomeUnknown(
                    acquire_operation_id,
                    "correction acquire Authority recovery unknown; HOLD") from exc
            if not self._anchor_matches(pre_target, pre_anchor):
                raise UnavailableGuard("correction recovery anchor changed; HOLD")
            if observed_state == "active":
                if (type(observed_permit) is not FencePermitV2
                        or observed_permit.operation != "write"
                        or observed_permit.operation_id != pre_intent[0]
                        or observed_permit.holder != self.__holder
                        or observed_permit.subject != port.installation_grant.subject
                        or observed_permit.pinned_anchor != pre_anchor):
                    raise UnavailableGuard("correction active write permit differs; HOLD")
                try:
                    active_scope = FenceScope(
                        namespace, pre_target.authority_namespace,
                        pre_target.activation_generation, "write", pre_intent[0],
                        observed_permit, pre_anchor,
                        NamespaceEpoch(*namespace.as_tuple, pre_intent[2]),
                        pre_intent[1])
                except (TypeError, ValueError) as exc:
                    raise UnavailableGuard(
                        "correction recovery write scope differs; HOLD") from exc
            elif observed_state not in {"absent", "finished"}:
                raise UnavailableGuard("correction acquire Authority state differs; HOLD")
        try:
            if active_scope is None:
                snapshot, anchor, metadata, epoch = self._read_v2(
                    authority, read_snapshot, return_recovery_context=True)
            else:
                # A durable write fence may block a new read fence after an
                # unknown begin or finish. It is independently validated before
                # and after the pinned SQLite read, without an RPC under lock.
                if port.validate_fence(active_scope) != active_scope.permit:
                    raise UnavailableGuard("correction recovery write permit changed; HOLD")
                with store._lock:
                    metadata, epoch = self._v2_graph_stamp(namespace)
                    if (pre_receipt is None and (metadata.graph_revision,
                                                epoch.revision) != pre_intent[1:3]
                            or pre_receipt is not None and (
                                metadata.graph_revision < pre_receipt[0]
                                or epoch.revision < pre_receipt[1])):
                        raise UnavailableGuard("correction recovery graph stamp differs; HOLD")
                    snapshot = read_snapshot()
                if port.validate_fence(active_scope) != active_scope.permit:
                    raise UnavailableGuard("correction recovery write permit changed; HOLD")
                anchor = pre_anchor
        except (UnavailableGuard, SourceCorrectionJobHold) as exc:
            raise UnavailableGuard("correction V2 read or identity unavailable; HOLD") from exc
        try:
            expected_acquire_id = source_correction_acquire_operation_id(
                namespace, job_id, snapshot.job.operation_id, authority.actor,
                authority.activation_generation, acquire_operation_id[-32:])
        except ValueError as exc:
            raise AuthorityDenied("correction acquire operation is invalid") from exc
        if acquire_operation_id != expected_acquire_id:
            raise AuthorityDenied("correction acquire operation names another job")
        target = metadata.requirements
        if (target.namespace != namespace
                or target.activation_generation != authority.activation_generation
                or snapshot.activation_generation != target.activation_generation):
            raise UnavailableGuard("correction activation changed; HOLD")
        requirements_json = canonical_json(asdict(target))
        anchor_json = canonical_json(asdict(anchor))

        def digest_for(*, fixed_now: str, expected_revision: int,
                       expected_fence: int, expected_cancel: int,
                       graph_revision: int, graph_epoch: int) -> str:
            return canonical_digest({
                "schema": "sylanne.d06-source-correction-job-acquire.v1",
                "namespace": list(namespace.as_tuple), "job_id": job_id,
                "original_operation_id": snapshot.job.operation_id,
                "original_bundle_digest": snapshot.original_digest,
                "original_graph_revision": snapshot.original_graph_revision,
                "request_digest": snapshot.request_digest,
                "correction_source_ref": snapshot.correction_source_ref,
                "source_refs": list(snapshot.source_refs),
                "head_refs": list(snapshot.head_refs),
                "target_refs": list(snapshot.target_refs),
                "outbox_ref": snapshot.outbox_ref,
                "quote_id": snapshot.quote.quote_id,
                "quote_version": snapshot.quote.version,
                "quote_ceiling": dict(snapshot.quote.ceiling),
                "reservation_digest": snapshot.reservation_digest,
                "acquire_operation_id": acquire_operation_id,
                "actor": authority.actor,
                "activation_generation": authority.activation_generation,
                "expected_job_revision": expected_revision,
                "expected_fence": expected_fence,
                "expected_cancel_epoch": expected_cancel,
                "fixed_now_utc": fixed_now,
                "lease_seconds": lease_seconds,
                "graph_revision": graph_revision, "graph_epoch": graph_epoch,
            })

        with store._lock:
            db = store._db
            intent = db.execute(
                "SELECT request_digest,job_id,original_operation_id,actor,"
                "fixed_now_utc,lease_seconds,expected_job_revision,expected_fence,"
                "expected_cancel_epoch,fence_attempt_id,requirements_json,anchor_json,"
                "graph_revision,graph_epoch,encoding_binding_json "
                "FROM graph_job_acquire_intents_v2 WHERE bot=? AND persona=? "
                "AND acquire_operation_id=?",
                namespace.as_tuple + (acquire_operation_id,),
            ).fetchone()
            receipt = db.execute(
                "SELECT request_digest,job_json,permit_json,pre_graph_revision,"
                "pre_graph_epoch,post_graph_revision,post_graph_epoch,"
                "finish_request_id,finish_request_digest "
                "FROM graph_job_acquire_receipts_v2 WHERE bot=? AND persona=? "
                "AND acquire_operation_id=?",
                namespace.as_tuple + (acquire_operation_id,),
            ).fetchone()
            rejection = db.execute(
                "SELECT status,permit_json,graph_revision,graph_epoch,"
                "finish_request_id,finish_request_digest "
                "FROM graph_job_acquire_rejections_v2 WHERE bot=? AND persona=? "
                "AND acquire_operation_id=?",
                namespace.as_tuple + (acquire_operation_id,),
            ).fetchone()
        if intent is None:
            if snapshot.job.phase != "queued":
                raise UnavailableGuard("correction job already has a worker lease; HOLD")
            try:
                planned = plan_source_correction_job_acquire(
                    snapshot, authority.actor, now_utc=now,
                    lease_seconds=lease_seconds)
            except SourceCorrectionJobHold as exc:
                raise UnavailableGuard(str(exc)) from exc
            if planned == snapshot.job:
                raise UnavailableGuard("correction job already acquired; HOLD")
            request_digest = digest_for(
                fixed_now=now_text, expected_revision=snapshot.job_revision,
                expected_fence=snapshot.job.fence,
                expected_cancel=snapshot.job.cancel_epoch,
                graph_revision=metadata.graph_revision, graph_epoch=epoch.revision)
            attempt_id = "d06-acquire-write-" + request_digest[:48]
            expected_intent = (
                request_digest, job_id, snapshot.job.operation_id, authority.actor,
                now_text, lease_seconds, snapshot.job_revision, snapshot.job.fence,
                snapshot.job.cancel_epoch, attempt_id, requirements_json, anchor_json,
                metadata.graph_revision, epoch.revision, None,
            )
            with store._lock:
                db = store._db
                db.execute("BEGIN IMMEDIATE")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise StaleRead("correction acquire pre-stamp changed")
                    db.execute(
                        "INSERT OR IGNORE INTO graph_job_acquire_intents_v2"
                        "(bot,persona,acquire_operation_id,request_digest,job_id,"
                        "original_operation_id,actor,fixed_now_utc,lease_seconds,"
                        "expected_job_revision,expected_fence,expected_cancel_epoch,"
                        "fence_attempt_id,requirements_json,anchor_json,"
                        "graph_revision,graph_epoch,encoding_binding_json) "
                        "VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                        namespace.as_tuple + (acquire_operation_id,) + expected_intent,
                    )
                    observed = db.execute(
                        "SELECT request_digest,job_id,original_operation_id,actor,"
                        "fixed_now_utc,lease_seconds,expected_job_revision,expected_fence,"
                        "expected_cancel_epoch,fence_attempt_id,requirements_json,anchor_json,"
                        "graph_revision,graph_epoch,encoding_binding_json "
                        "FROM graph_job_acquire_intents_v2 WHERE bot=? AND persona=? "
                        "AND acquire_operation_id=?",
                        namespace.as_tuple + (acquire_operation_id,),
                    ).fetchone()
                    if observed != expected_intent:
                        raise EventConflict("correction acquire identity was reused")
                    db.execute("COMMIT")
                    intent = observed
                except BaseException:
                    db.execute("ROLLBACK")
                    raise
        if (intent[1:4] != (job_id, snapshot.job.operation_id, authority.actor)
                or intent[5] != lease_seconds or intent[10:12]
                != (requirements_json, anchor_json) or intent[14] is not None):
            raise UnavailableGuard("correction acquire intent differs; HOLD")
        request_digest = digest_for(
            fixed_now=intent[4], expected_revision=intent[6],
            expected_fence=intent[7], expected_cancel=intent[8],
            graph_revision=intent[12], graph_epoch=intent[13])
        attempt_id = "d06-acquire-write-" + request_digest[:48]
        if intent[0] != request_digest or intent[9] != attempt_id:
            raise UnavailableGuard("correction acquire digest differs; HOLD")
        if receipt is not None and rejection is not None:
            raise UnavailableGuard("correction acquire terminal ledgers disagree; HOLD")

        def finish_identity(permit, *, rejected=False):
            finish_id = ("abort:" if rejected else "finish:") + attempt_id
            finish_digest = "sha256:" + canonical_digest({
                "operation_id": attempt_id, "permit_token": permit.token,
                "action": "rejected_no_commit" if rejected else
                          "finish_source_correction_job_acquire",
                "business_operation_id": acquire_operation_id,
                "request_digest": request_digest,
            })
            return finish_id, finish_digest

        if receipt is not None or rejection is not None:
            terminal = receipt if receipt is not None else rejection
            permit = from_wire(json.loads(terminal[2] if receipt is not None
                                          else terminal[1]))
            if (type(permit) is not FencePermitV2
                    or permit.operation_id != attempt_id
                    or permit.operation != "write" or permit.holder != self.__holder
                    or permit.subject != port.installation_grant.subject
                    or permit.pinned_anchor != anchor):
                raise UnavailableGuard("correction acquire durable permit differs; HOLD")
            try:
                observed, state = port.get_fence_operation(
                    namespace=namespace,
                    authority_namespace=target.authority_namespace,
                    operation_id=attempt_id)
            except Exception as exc:
                raise JobAcquireOutcomeUnknown(
                    acquire_operation_id,
                    "correction acquire Authority state unknown; HOLD") from exc
            if observed != permit or state not in {"active", "finished"}:
                raise UnavailableGuard("correction acquire Authority state differs; HOLD")
            if receipt is None:
                if (rejection[0] != "rejected_no_commit"
                        or rejection[2:4] != intent[12:14]
                        or rejection[4:6] != finish_identity(permit, rejected=True)):
                    raise UnavailableGuard("correction acquire rejection differs; HOLD")
                if state == "active":
                    scope = FenceScope(
                        namespace, target.authority_namespace,
                        target.activation_generation, "write", attempt_id,
                        permit, anchor, NamespaceEpoch(*namespace.as_tuple,
                                                       intent[13]), intent[12])
                    if port.validate_fence(scope) != permit:
                        raise UnavailableGuard("correction acquire permit changed; HOLD")
                    port.finish_fence(scope, request_id=rejection[4],
                                      request_digest=rejection[5])
                raise UnavailableGuard("correction acquire was rejected; HOLD")
            if (receipt[0] != request_digest
                    or receipt[3:5] != intent[12:14]
                    or receipt[5:7] != (intent[12] + 1, intent[13] + 1)
                    or receipt[7:9] != finish_identity(permit)):
                raise UnavailableGuard("correction acquire receipt differs; HOLD")
            try:
                historical = PersistentJob(**json.loads(receipt[1]))
                current_is_live = plan_source_correction_job_acquire(
                    snapshot, authority.actor, now_utc=now,
                    lease_seconds=lease_seconds) == snapshot.job
            except Exception as exc:
                raise UnavailableGuard("correction acquired lease expired; HOLD") from exc
            if (historical != snapshot.job or not current_is_live
                    or historical.lease_holder != authority.actor
                    or snapshot.graph_revision < receipt[5]
                    or snapshot.graph_epoch < receipt[6]):
                raise UnavailableGuard("correction acquired job is no longer current; HOLD")
            if state == "active":
                if ((snapshot.graph_revision, snapshot.graph_epoch)
                        != receipt[5:7]):
                    raise UnavailableGuard("unresolved correction acquire stamp changed; HOLD")
                scope = FenceScope(
                    namespace, target.authority_namespace,
                    target.activation_generation, "write", attempt_id,
                    permit, anchor, NamespaceEpoch(*namespace.as_tuple,
                                                   receipt[4]), receipt[3])
                if port.validate_fence(scope) != permit:
                    raise UnavailableGuard("correction acquire permit changed; HOLD")
                port.finish_fence(scope, request_id=receipt[7],
                                  request_digest=receipt[8])
            return historical

        if ((metadata.graph_revision, epoch.revision) != intent[12:14]
                or (snapshot.job_revision, snapshot.job.fence,
                    snapshot.job.cancel_epoch) != intent[6:9]):
            raise UnavailableGuard("uncommitted correction acquire prestate changed; HOLD")
        fixed_now = datetime.fromisoformat(intent[4].replace("Z", "+00:00")).timestamp()
        try:
            planned = plan_source_correction_job_acquire(
                snapshot, authority.actor, now_utc=fixed_now,
                lease_seconds=lease_seconds)
            plan_source_correction_job_acquire(
                snapshot, authority.actor, now_utc=now,
                lease_seconds=lease_seconds)
        except SourceCorrectionJobHold as exc:
            raise UnavailableGuard(str(exc)) from exc
        if planned == snapshot.job:
            raise UnavailableGuard("correction acquire has no new worker lease; HOLD")
        try:
            permit = port.begin_fence(
                namespace=namespace,
                authority_namespace=target.authority_namespace,
                holder=self.__holder, generation=target.activation_generation,
                operation="write", operation_id=attempt_id,
                expected_anchor=anchor, retain_on_unknown=True)
        except Exception as exc:
            raise JobAcquireOutcomeUnknown(
                acquire_operation_id,
                "correction acquire begin outcome unknown; HOLD") from exc
        scope = FenceScope(namespace, target.authority_namespace,
                           target.activation_generation, "write", attempt_id,
                           permit, anchor, epoch, metadata.graph_revision)
        if port.validate_fence(scope) != permit:
            raise UnavailableGuard("correction acquire write permit changed; HOLD")
        finish_id, finish_digest = finish_identity(permit)
        job_key = AtomKey.from_token(snapshot.quote.graph_job_ref)
        outbox_key = AtomKey.from_token(snapshot.outbox_ref)
        with store._lock:
            if self._v2_graph_stamp(namespace) != (metadata, epoch):
                raise UnavailableGuard("correction acquire graph stamp changed; HOLD")
            guarded_refs = (snapshot.correction_source_ref, *snapshot.source_refs,
                            *snapshot.head_refs, *snapshot.target_refs)
            rows = store._db.execute(
                "SELECT token,revision FROM graph_atoms WHERE token IN (" +
                ",".join("?" for _ in guarded_refs) + ")", guarded_refs,
            ).fetchall()
            outbox_row = store._db.execute(
                "SELECT value FROM graph_atoms WHERE token=?",
                (snapshot.outbox_ref,),
            ).fetchone()
        if len(rows) != len(set(guarded_refs)):
            raise UnavailableGuard("correction acquire graph reads absent; HOLD")
        if outbox_row is None:
            raise UnavailableGuard("correction acquire outbox is absent; HOLD")
        pending_outbox = RuntimeOutboxValue(**json.loads(outbox_row[0]))
        candidate = GraphCandidate(
            Event(Scope(*namespace.as_tuple, snapshot.job.activity_id),
                  acquire_operation_id, fixed_now,
                  "source_correction_job_acquire_v1",
                  {"request_digest": request_digest}),
            (GraphVersion(job_key, snapshot.job_revision),
             GraphVersion(outbox_key, snapshot.outbox_revision),
             *(GraphVersion(AtomKey.from_token(ref), revision)
               for ref, revision in rows)),
            (job_graph_write(planned),
             outbox_graph_write(pending_outbox, job_key)), (epoch,),
        )
        transaction_state = {"phase": "before_transaction"}

        def guard(db):
            try:
                commit_now = trusted_upper(clock)
                expires = datetime.fromisoformat(
                    planned.lease_expires_utc.replace("Z", "+00:00")).timestamp()
            except Exception as exc:
                raise UnavailableGuard("correction acquire trusted clock expired; HOLD") from exc
            if commit_now >= expires:
                raise UnavailableGuard("correction frozen worker lease expired; HOLD")
            if self._v2_graph_stamp(namespace) != (metadata, epoch):
                raise StaleRead("correction acquire graph stamp changed")
            if db.execute(
                    "SELECT 1 FROM graph_job_acquire_receipts_v2 WHERE bot=? "
                    "AND persona=? AND acquire_operation_id=?",
                    namespace.as_tuple + (acquire_operation_id,),
            ).fetchone():
                raise UnavailableGuard("correction acquire receipt appeared before commit")
            current = read_source_correction_job_snapshot(
                db, self.__d11_issuer, namespace, job_id, now_utc=commit_now)
            if current != snapshot:
                raise StaleRead("correction original identity changed")
            acquired = acquire_source_correction_job_in_transaction(
                db, self.__d11_issuer, snapshot, scope, authority.actor,
                fence_holder=self.__holder, now_utc=fixed_now,
                lease_seconds=lease_seconds)
            if acquired != planned:
                raise StaleRead("correction acquired job differs from frozen plan")
            reconcile_runtime_write(db, candidate.writes[0])
            reconcile_runtime_write(db, candidate.writes[1])

        def receipt_hook(db, graph_receipt):
            if (graph_receipt.status != "committed"
                    or len(graph_receipt.revisions) != 2
                    or {item.key for item in graph_receipt.revisions}
                    != {job_key, outbox_key}):
                raise UnavailableGuard("correction job graph write was not committed")
            store.cas_graph_recovery_metadata(
                metadata, metadata.requirements,
                _capability=self.__graph_capability)
            db.execute(
                "INSERT INTO graph_job_acquire_receipts_v2"
                "(bot,persona,acquire_operation_id,request_digest,job_json,"
                "permit_json,pre_graph_revision,pre_graph_epoch,"
                "post_graph_revision,post_graph_epoch,finish_request_id,"
                "finish_request_digest) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",
                namespace.as_tuple + (acquire_operation_id, request_digest,
                    canonical_json(asdict(planned)), canonical_json(to_wire(permit)),
                    metadata.graph_revision, epoch.revision,
                    metadata.graph_revision + 1, graph_receipt.epoch.revision,
                    finish_id, finish_digest),
            )

        try:
            GraphStore.graph_commit(
                store, candidate, _guard=guard, _receipt_hook=receipt_hook,
                _capability=self.__graph_capability,
                _transaction_state=transaction_state)
        except Exception as exc:
            if transaction_state["phase"] not in {"before_transaction", "rolled_back"}:
                raise JobAcquireOutcomeUnknown(
                    acquire_operation_id,
                    "correction acquire commit outcome unknown; HOLD") from exc
            abort_id, abort_digest = finish_identity(permit, rejected=True)
            with store._lock:
                db = store._db
                db.execute("BEGIN IMMEDIATE")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise UnavailableGuard("correction acquire rollback cannot be proven")
                    db.execute(
                        "INSERT OR IGNORE INTO graph_job_acquire_rejections_v2"
                        "(bot,persona,acquire_operation_id,status,permit_json,"
                        "graph_revision,graph_epoch,finish_request_id,"
                        "finish_request_digest) VALUES(?,?,?,?,?,?,?,?,?)",
                        namespace.as_tuple + (acquire_operation_id,
                            "rejected_no_commit", canonical_json(to_wire(permit)),
                            metadata.graph_revision, epoch.revision,
                            abort_id, abort_digest),
                    )
                    db.execute("COMMIT")
                except BaseException:
                    db.execute("ROLLBACK")
                    raise
            try:
                port.finish_fence(scope, request_id=abort_id,
                                  request_digest=abort_digest)
            except Exception as finish_exc:
                raise JobAcquireOutcomeUnknown(
                    acquire_operation_id,
                    "correction acquire rejection finish unknown; HOLD") from finish_exc
            raise
        try:
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("correction acquire permit changed after commit")
            with store._lock:
                current, current_epoch = self._v2_graph_stamp(namespace)
                if (current.graph_revision != metadata.graph_revision + 1
                        or current_epoch.revision != epoch.revision + 1):
                    raise UnavailableGuard("correction acquire committed stamp differs")
            port.finish_fence(scope, request_id=finish_id,
                              request_digest=finish_digest)
        except Exception as exc:
            raise JobAcquireOutcomeUnknown(
                acquire_operation_id,
                "correction acquire finish outcome unknown; HOLD") from exc
        return planned

    def acquire_first_ingress_encoding_job_v2(
        self, authority: AuthorityContext, lease: object, job_id: str,
        acquire_operation_id: str, *, lease_seconds: int,
        _require_baseline_v3: bool = False,
    ) -> PersistentJob:
        """Acquire exactly one original encoding job under a recoverable v2 write fence."""
        from datetime import datetime, timezone

        from .authority_service.v2_contract import FencePermitV2, from_wire, to_wire
        from .host.authority_profile import AdminIngressClockPolicy
        from .runtime.d11_types import job_graph_write, outbox_graph_write
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.issuers import D11BudgetJobIssuer
        from .runtime.encoding_call_binding import (
            binding_from_json, binding_to_json, insert_binding, load_binding,
        )

        store = self.__store
        port = self.__content_fence_v2
        namespace = authority.namespace
        if (not isinstance(store, ProductionGraphStore) or port is None
                or type(self.__d11_issuer) is not D11BudgetJobIssuer
                or type(self.__scene_clock_policy) is not AdminIngressClockPolicy):
            raise UnavailableGuard("installed v2 D11 job and trusted clock are required")
        self._authorize(lease, authority, frozenset({"d11"}))
        if (authority.issuer_domain != "d11" or "activity" not in authority.owner_scope
                or type(acquire_operation_id) is not str
                or not acquire_operation_id or len(acquire_operation_id) > 128
                or type(lease_seconds) is not int or not 1 <= lease_seconds <= 3600):
            raise AuthorityDenied("D11 activity capability and bounded acquire identity required")
        if authority.capability_ref != _operation_capability_ref(
                namespace, authority.actor, "d11", frozenset({"d11"}),
                authority.activation_generation, acquire_operation_id):
            raise AuthorityDenied("D11 acquire lease is not scoped to this operation")

        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
            intent = store._db.execute(
                "SELECT request_digest,job_id,original_operation_id,actor,"
                "fixed_now_utc,lease_seconds,expected_job_revision,expected_fence,"
                "expected_cancel_epoch,fence_attempt_id,requirements_json,anchor_json,"
                "graph_revision,graph_epoch,encoding_binding_json "
                "FROM graph_job_acquire_intents_v2 "
                "WHERE bot=? AND persona=? AND acquire_operation_id=?",
                namespace.as_tuple + (acquire_operation_id,),
            ).fetchone()
            receipt = store._db.execute(
                "SELECT request_digest,job_json,permit_json,pre_graph_revision,"
                "pre_graph_epoch,post_graph_revision,post_graph_epoch,"
                "finish_request_id,finish_request_digest "
                "FROM graph_job_acquire_receipts_v2 WHERE bot=? AND persona=? "
                "AND acquire_operation_id=?",
                namespace.as_tuple + (acquire_operation_id,),
            ).fetchone()
            rejection = store._db.execute(
                "SELECT status,permit_json,graph_revision,graph_epoch,"
                "finish_request_id,finish_request_digest "
                "FROM graph_job_acquire_rejections_v2 WHERE bot=? AND persona=? "
                "AND acquire_operation_id=?",
                namespace.as_tuple + (acquire_operation_id,),
            ).fetchone()
            erased = store._db.execute(
                "SELECT 1 FROM runtime_encoding_call_redactions_v1 "
                "WHERE bot=? AND persona=? AND acquire_operation_id=?",
                namespace.as_tuple + (acquire_operation_id,),
            ).fetchone()
            if intent is None:
                (job, job_key, job_revision, outbox, outbox_key,
                 outbox_revision, source_version, access_version) = (
                    self._first_ingress_encoding_job_locked(namespace, job_id))
                if store._db.execute(
                        "SELECT 1 FROM runtime_encoding_call_redactions_v1 "
                        "WHERE bot=? AND persona=? AND source_id=? LIMIT 1",
                        namespace.as_tuple + (outbox.payload_ref,),
                ).fetchone():
                    raise UnavailableGuard("encoding source request was erased; HOLD")
            else:
                job = None
        if erased is not None:
            raise UnavailableGuard("encoding request was erased; HOLD")
        if _require_baseline_v3 and (
                self.__encoding_request_issuer is None or
                intent is not None and (intent[14] is None or
                binding_from_json(intent[14]).request.get("schema") !=
                "sylanne.first-ingress-encoding-call.v3")):
            raise UnavailableGuard("V3 acquire requires original committed baseline; HOLD")
        original_operation_id = job.operation_id if intent is None else intent[2]
        if not _job_acquire_id_matches(
                acquire_operation_id, namespace, job_id,
                original_operation_id, authority.actor,
                authority.activation_generation):
            raise AuthorityDenied("D11 acquire lease names another job")
        target = metadata.requirements
        if (target.namespace != namespace
                or target.activation_generation != authority.activation_generation):
            raise UnavailableGuard("job acquire activation or namespace changed")
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("job acquire Authority anchor differs")
        try:
            clock = port.read_ingress_clock(self.__scene_clock_policy)
            now = trusted_upper(clock)
            now_text = datetime.fromtimestamp(now, timezone.utc).isoformat().replace(
                "+00:00", "Z")
        except Exception as exc:
            raise UnavailableGuard("paired job clock is unavailable; HOLD") from exc
        requirements_json = canonical_json(asdict(target))
        anchor_json = canonical_json(asdict(anchor))
        if intent is None:
            if acquire_operation_id == job.operation_id:
                raise AuthorityDenied("acquire operation must differ from original ingress")
            try:
                planned = plan_job_acquire(
                    job, authority.actor, now_utc=now_text,
                    lease_seconds=lease_seconds)
            except Exception as exc:
                raise UnavailableGuard("encoding job is not runnable; HOLD") from exc
            if planned == job or job.cancel_epoch:
                raise UnavailableGuard("encoding job has an active or cancelled lease; HOLD")
            binding = (self._issue_first_ingress_encoding_binding(
                namespace, planned, outbox, source_version, access_version,
                authority, now, acquire_operation_id, clock,
                require_baseline_v3=_require_baseline_v3)
                if self.__encoding_request_issuer is not None else None)
            binding_json = binding_to_json(binding) if binding is not None else None
            request_digest = canonical_digest({
                "schema": "sylanne.job-acquire.v2",
                "namespace": list(namespace.as_tuple), "job_id": job_id,
                "original_operation_id": job.operation_id,
                "acquire_operation_id": acquire_operation_id,
                "actor": authority.actor,
                "activation_generation": authority.activation_generation,
                "expected_job_revision": job_revision, "expected_fence": job.fence,
                "expected_cancel_epoch": job.cancel_epoch,
                "fixed_now_utc": now_text, "lease_seconds": lease_seconds,
            })
            attempt_id = "job-acquire-" + request_digest[:48]
            expected_intent = (
                request_digest, job_id, job.operation_id, authority.actor,
                now_text, lease_seconds, job_revision, job.fence, job.cancel_epoch,
                attempt_id, requirements_json, anchor_json,
                metadata.graph_revision, epoch.revision, binding_json,
            )
            with store._lock:
                db = store._db
                db.execute("BEGIN IMMEDIATE")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise StaleRead("job acquire pre-stamp changed")
                    db.execute(
                        "INSERT OR IGNORE INTO graph_job_acquire_intents_v2"
                        "(bot,persona,acquire_operation_id,request_digest,job_id,"
                        "original_operation_id,actor,fixed_now_utc,lease_seconds,"
                        "expected_job_revision,expected_fence,expected_cancel_epoch,"
                        "fence_attempt_id,requirements_json,anchor_json,"
                        "graph_revision,graph_epoch,encoding_binding_json) "
                        "VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                        namespace.as_tuple + (acquire_operation_id,) + expected_intent,
                    )
                    intent = db.execute(
                        "SELECT request_digest,job_id,original_operation_id,actor,"
                        "fixed_now_utc,lease_seconds,expected_job_revision,expected_fence,"
                        "expected_cancel_epoch,fence_attempt_id,requirements_json,anchor_json,"
                        "graph_revision,graph_epoch,encoding_binding_json "
                        "FROM graph_job_acquire_intents_v2 "
                        "WHERE bot=? AND persona=? AND acquire_operation_id=?",
                        namespace.as_tuple + (acquire_operation_id,),
                    ).fetchone()
                    db.execute("COMMIT")
                except BaseException:
                    db.execute("ROLLBACK")
                    raise
            if intent != expected_intent:
                raise EventConflict("acquire operation identity was reused")
        else:
            if (intent[1] != job_id or intent[3] != authority.actor
                    or intent[5] != lease_seconds
                    or intent[10] != requirements_json
                    or intent[11] != anchor_json):
                raise UnavailableGuard("original job acquire identity differs; HOLD")
            attempt_id = intent[9]
            request_digest = intent[0]
        if request_digest != canonical_digest({
            "schema": "sylanne.job-acquire.v2",
            "namespace": list(namespace.as_tuple), "job_id": intent[1],
            "original_operation_id": intent[2],
            "acquire_operation_id": acquire_operation_id,
            "actor": intent[3],
            "activation_generation": target.activation_generation,
            "expected_job_revision": intent[6], "expected_fence": intent[7],
            "expected_cancel_epoch": intent[8],
            "fixed_now_utc": intent[4], "lease_seconds": intent[5],
        }) or attempt_id != "job-acquire-" + request_digest[:48]:
            raise UnavailableGuard("job acquire intent digest differs")
        if receipt is not None and rejection is not None:
            raise UnavailableGuard("job acquire terminal ledgers disagree")

        def finish_identity(permit, *, rejected=False):
            finish_id = ("abort:" if rejected else "finish:") + attempt_id
            finish_digest = "sha256:" + canonical_digest({
                "operation_id": attempt_id, "permit_token": permit.token,
                "action": "rejected_no_commit" if rejected else "finish_job_acquire",
                "business_operation_id": acquire_operation_id,
                "request_digest": request_digest,
            })
            return finish_id, finish_digest

        if receipt is not None or rejection is not None:
            row = receipt if receipt is not None else rejection
            permit = from_wire(json.loads(row[2] if receipt is not None else row[1]))
            if (type(permit) is not FencePermitV2
                    or permit.operation_id != attempt_id or permit.operation != "write"
                    or permit.holder != self.__holder
                    or permit.subject != port.installation_grant.subject
                    or permit.pinned_anchor != anchor):
                raise UnavailableGuard("job acquire durable permit differs")
            try:
                observed, state = port.get_fence_operation(
                    namespace=namespace, authority_namespace=target.authority_namespace,
                    operation_id=attempt_id)
            except Exception as exc:
                raise JobAcquireOutcomeUnknown(
                    acquire_operation_id, "job acquire Authority state unknown; HOLD") from exc
            if observed != permit or state not in {"active", "finished"}:
                raise UnavailableGuard("job acquire Authority state differs")
            if receipt is not None:
                if (receipt[0] != request_digest
                        or receipt[3:5] != intent[12:14]
                        or receipt[5] != receipt[3] + 1
                        or receipt[8] != finish_identity(permit)[1]
                        or receipt[7] != finish_identity(permit)[0]):
                    raise UnavailableGuard("job acquire receipt identity differs")
                historical = PersistentJob(**json.loads(receipt[1]))
                with store._lock:
                    durable_binding = load_binding(store._db, namespace, job_id)
                frozen_binding = (binding_from_json(intent[14])
                                  if intent[14] is not None else None)
                if durable_binding != frozen_binding:
                    raise UnavailableGuard("replayed job binding differs from frozen intent; HOLD")
                replay_now = trusted_upper(clock)
                replay_now_text = datetime.fromtimestamp(
                    replay_now, timezone.utc).isoformat().replace("+00:00", "Z")
                with store._lock:
                    (current, _, _, current_outbox, _, _, current_source,
                     current_access) = self._first_ingress_encoding_job_locked(
                         namespace, job_id)
                    current_stamp = self._v2_graph_stamp(namespace)
                    if frozen_binding is not None:
                        self._validate_first_ingress_encoding_binding_context(
                            namespace, current, current_outbox,
                            current_source, current_access, authority,
                            replay_now, acquire_operation_id, clock,
                            frozen_binding)
                try:
                    current_is_live = plan_job_acquire(
                        current, authority.actor, now_utc=replay_now_text,
                        lease_seconds=lease_seconds) == current
                except Exception as exc:
                    raise UnavailableGuard("replayed job lease expired; HOLD") from exc
                if (current != historical or current.lease_holder != authority.actor
                        or not current_is_live):
                    raise UnavailableGuard("replayed job lease is no longer current; HOLD")
                if state == "active":
                    if current_stamp != (metadata, epoch) and (
                            current_stamp[0].graph_revision != receipt[5]
                            or current_stamp[1].revision != receipt[6]):
                        raise UnavailableGuard("unresolved job acquire stamp changed")
                    scope = FenceScope(namespace, target.authority_namespace,
                        target.activation_generation, "write", attempt_id, permit,
                        anchor, NamespaceEpoch(*namespace.as_tuple, receipt[4]),
                        receipt[3])
                    if port.validate_fence(scope) != permit:
                        raise UnavailableGuard("job acquire permit changed")
                    port.finish_fence(scope, request_id=receipt[7],
                                      request_digest=receipt[8])
                if frozen_binding is not None and frozen_binding.request.get(
                        "schema") == "sylanne.first-ingress-encoding-call.v3":
                    # Replaying V3 is not new budget admission. Its model cost
                    # may have settled the reservation. The result context
                    # rechecks signed provenance and current content under a
                    # new read fence without requiring reserved state.
                    original_context = (
                        self.read_first_ingress_original_model_result_context_v1(
                            replace(authority, worker_fence=historical.fence),
                            lease, job_id, acquire_operation_id))
                    if (original_context.original_operation_id
                            != historical.operation_id
                            or original_context.worker_actor != authority.actor
                            or original_context.worker_fence != historical.fence
                            or original_context.call_id != durable_binding.call_id):
                        raise UnavailableGuard("replayed job original context differs; HOLD")
                return self._qualified_first_ingress_acquire_return(
                    namespace, job_id, historical, authority.actor, clock,
                    lease_seconds, original_context_verified=(
                        frozen_binding is not None and frozen_binding.request.get(
                            "schema") == "sylanne.first-ingress-encoding-call.v3"))
            if (rejection[0] != "rejected_no_commit"
                    or rejection[2:4] != intent[12:14]
                    or rejection[4:6] != finish_identity(permit, rejected=True)):
                raise UnavailableGuard("job acquire rejection identity differs")
            if state == "active":
                scope = FenceScope(namespace, target.authority_namespace,
                    target.activation_generation, "write", attempt_id, permit,
                    anchor, NamespaceEpoch(*namespace.as_tuple, intent[13]), intent[12])
                if port.validate_fence(scope) != permit:
                    raise UnavailableGuard("rejected job acquire permit changed")
                port.finish_fence(scope, request_id=rejection[4],
                                  request_digest=rejection[5])
            raise UnavailableGuard("job acquire is terminal rejected_no_commit")

        if (metadata.graph_revision, epoch.revision) != intent[12:14]:
            raise UnavailableGuard("uncommitted job acquire graph stamp changed")
        if job is None:
            with store._lock:
                (job, job_key, job_revision, outbox, outbox_key,
                 outbox_revision, source_version, access_version) = (
                    self._first_ingress_encoding_job_locked(namespace, job_id))
        if (job.operation_id != intent[2] or job_revision != intent[6]
                or job.fence != intent[7] or job.cancel_epoch != intent[8]):
            raise UnavailableGuard("uncommitted job acquire prestate changed")
        try:
            planned = plan_job_acquire(
                job, authority.actor, now_utc=intent[4], lease_seconds=lease_seconds)
            plan_job_acquire(job, authority.actor, now_utc=now_text,
                             lease_seconds=lease_seconds)
        except Exception as exc:
            raise UnavailableGuard("encoding job acquire deadline expired; HOLD") from exc
        if planned == job or job.cancel_epoch:
            raise UnavailableGuard("encoding job is no longer runnable; HOLD")
        frozen_binding = (binding_from_json(intent[14])
                          if intent[14] is not None else None)
        if frozen_binding is not None:
            if self.__encoding_request_issuer is None:
                raise UnavailableGuard("original encoding request issuer is unavailable; HOLD")
            current_binding = self._issue_first_ingress_encoding_binding(
                namespace, planned, outbox, source_version, access_version,
                authority, now, acquire_operation_id, clock,
                frozen_binding, require_baseline_v3=_require_baseline_v3)
            if current_binding != frozen_binding:
                raise UnavailableGuard("encoding request configuration changed; HOLD")
        elif self.__encoding_request_issuer is not None:
            # The original intent predates this issuer. It cannot gain a
            # request after its Authority operation identity was frozen.
            raise UnavailableGuard("original job acquire has no encoding request; HOLD")

        try:
            permit = port.begin_fence(
                namespace=namespace, authority_namespace=target.authority_namespace,
                holder=self.__holder, generation=target.activation_generation,
                operation="write", operation_id=attempt_id,
                expected_anchor=anchor, retain_on_unknown=True)
        except Exception as exc:
            raise JobAcquireOutcomeUnknown(
                acquire_operation_id, "job acquire begin outcome unknown; HOLD") from exc
        scope = FenceScope(namespace, target.authority_namespace,
            target.activation_generation, "write", attempt_id, permit,
            anchor, epoch, metadata.graph_revision)
        if port.validate_fence(scope) != permit:
            raise UnavailableGuard("job acquire write permit changed")
        finish_id, finish_digest = finish_identity(permit)
        from .runtime.d11_types import RuntimeOutboxValue

        pending = RuntimeOutboxValue(**asdict(outbox))
        candidate = GraphCandidate(
            Event(Scope(*namespace.as_tuple, job.activity_id),
                  acquire_operation_id,
                  datetime.fromisoformat(intent[4].replace("Z", "+00:00")).timestamp(),
                  "job_acquire_v2", {"request_digest": request_digest}),
            (GraphVersion(job_key, job_revision),
             GraphVersion(outbox_key, outbox_revision),
             source_version, access_version),
            (job_graph_write(planned), outbox_graph_write(pending, job_key)),
            (epoch,),
        )
        transaction_state = {"phase": "before_transaction"}

        def guard(db):
            try:
                commit_now = trusted_upper(clock)
                commit_now_text = datetime.fromtimestamp(
                    commit_now, timezone.utc).isoformat().replace("+00:00", "Z")
                plan_job_acquire(job, authority.actor, now_utc=commit_now_text,
                                 lease_seconds=lease_seconds)
                planned_expires = datetime.fromisoformat(
                    planned.lease_expires_utc.replace("Z", "+00:00")).timestamp()
            except Exception as exc:
                raise UnavailableGuard("job acquire trusted clock expired; HOLD") from exc
            if commit_now >= planned_expires:
                raise UnavailableGuard("job acquire frozen lease expired; HOLD")
            if self._v2_graph_stamp(namespace) != (metadata, epoch):
                raise StaleRead("job acquire graph stamp changed")
            if db.execute(
                    "SELECT 1 FROM graph_job_acquire_receipts_v2 WHERE bot=? "
                    "AND persona=? AND acquire_operation_id=?",
                    namespace.as_tuple + (acquire_operation_id,),
            ).fetchone():
                raise UnavailableGuard("job acquire receipt appeared before commit")
            current = self._first_ingress_encoding_job_locked(namespace, job_id)[0]
            if current != job:
                raise StaleRead("job acquire durable prestate changed")
            self.__d11_issuer.authorize_existing_encoding_job(
                db, job, now_utc=commit_now)
            if frozen_binding is not None:
                self._validate_first_ingress_encoding_binding_context(
                    namespace, planned, outbox, source_version,
                    access_version, authority, commit_now,
                    acquire_operation_id, clock, frozen_binding)
                if (self.__encoding_request_issuer is None
                        or self._issue_first_ingress_encoding_binding(
                            namespace, planned, outbox, source_version,
                            access_version, authority, commit_now,
                            acquire_operation_id, clock, frozen_binding,
                            require_baseline_v3=_require_baseline_v3)
                        != frozen_binding):
                    raise UnavailableGuard(
                        "encoding request configuration changed; HOLD")
            if acquire_job(db, job_id, authority.actor,
                           now_utc=intent[4], lease_seconds=lease_seconds) != planned:
                raise StaleRead("job acquire mutation differed from frozen plan")
            reconcile_runtime_write(db, candidate.writes[0])
            reconcile_runtime_write(db, candidate.writes[1])
            if frozen_binding is not None:
                insert_binding(db, frozen_binding)

        def receipt_hook(db, graph_receipt):
            if graph_receipt.status != "committed" or len(graph_receipt.revisions) != 2:
                raise UnavailableGuard("job acquire graph event was not committed")
            if load_binding(db, namespace, job_id) != frozen_binding:
                raise UnavailableGuard("job acquire binding did not match frozen intent")
            store.cas_graph_recovery_metadata(
                metadata, metadata.requirements,
                _capability=self.__graph_capability)
            db.execute(
                "INSERT INTO graph_job_acquire_receipts_v2"
                "(bot,persona,acquire_operation_id,request_digest,job_json,"
                "permit_json,pre_graph_revision,pre_graph_epoch,"
                "post_graph_revision,post_graph_epoch,finish_request_id,"
                "finish_request_digest) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",
                namespace.as_tuple + (acquire_operation_id, request_digest,
                    canonical_json(asdict(planned)), canonical_json(to_wire(permit)),
                    metadata.graph_revision, epoch.revision,
                    metadata.graph_revision + 1, graph_receipt.epoch.revision,
                    finish_id, finish_digest),
            )

        try:
            GraphStore.graph_commit(
                store, candidate, _guard=guard, _receipt_hook=receipt_hook,
                _capability=self.__graph_capability,
                _transaction_state=transaction_state)
        except Exception as exc:
            if transaction_state["phase"] not in {"before_transaction", "rolled_back"}:
                raise JobAcquireOutcomeUnknown(
                    acquire_operation_id, "job acquire commit outcome unknown; HOLD") from exc
            abort_id, abort_digest = finish_identity(permit, rejected=True)
            with store._lock:
                db = store._db
                db.execute("BEGIN IMMEDIATE")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise UnavailableGuard("job acquire rollback cannot be proven")
                    db.execute(
                        "INSERT OR IGNORE INTO graph_job_acquire_rejections_v2"
                        "(bot,persona,acquire_operation_id,status,permit_json,"
                        "graph_revision,graph_epoch,finish_request_id,"
                        "finish_request_digest) VALUES(?,?,?,?,?,?,?,?,?)",
                        namespace.as_tuple + (acquire_operation_id,
                            "rejected_no_commit", canonical_json(to_wire(permit)),
                            metadata.graph_revision, epoch.revision,
                            abort_id, abort_digest),
                    )
                    db.execute("COMMIT")
                except BaseException:
                    db.execute("ROLLBACK")
                    raise
            try:
                port.finish_fence(scope, request_id=abort_id,
                                  request_digest=abort_digest)
            except Exception as finish_exc:
                raise JobAcquireOutcomeUnknown(
                    acquire_operation_id, "job acquire rejection finish unknown; HOLD"
                ) from finish_exc
            raise
        try:
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("job acquire permit changed after commit")
            with store._lock:
                current, current_epoch = self._v2_graph_stamp(namespace)
                if (current.graph_revision != metadata.graph_revision + 1
                        or current_epoch.revision != epoch.revision + 1):
                    raise UnavailableGuard("job acquire committed stamp differs")
            port.finish_fence(scope, request_id=finish_id,
                              request_digest=finish_digest)
        except Exception as exc:
            raise JobAcquireOutcomeUnknown(
                acquire_operation_id, "job acquire finish outcome unknown; HOLD") from exc
        return self._qualified_first_ingress_acquire_return(
            namespace, job_id, planned, authority.actor, clock, lease_seconds)

    def cancel_persistent_job(self, authority: AuthorityContext, lease: object,
                              job_id: str, operation_id: str,
                              digest: str) -> PersistentJob:
        self._authorize(lease, authority, frozenset())
        return self._mutate_job(authority, job_id, lambda db: cancel_job(
            db, job_id, operation_id, digest))

    def _mutate_job(self, authority: AuthorityContext, job_id: str, mutation):
        namespace = authority.namespace
        store = self.__store
        with self._content_fence(namespace, authority.activation_generation, "write"):
            with store._lock:
                store._ensure_open()
                self._admit_content(namespace, authority.activation_generation, "write")
                store._db.execute("BEGIN IMMEDIATE")
                try:
                    if self._version(store._db, namespace, "activation", "current") != str(
                            authority.activation_generation):
                        raise StaleRead("activation generation changed")
                    job = get_job(store._db, job_id)
                    if (job.bot_id, job.persona_id) != namespace.as_tuple:
                        raise AuthorityDenied("job crosses namespace")
                    result = mutation(store._db)
                    store._db.execute("COMMIT")
                    return result
                except BaseException:
                    store._db.execute("ROLLBACK")
                    raise

    def _admit_runtime_bundle(self, db, bundle: DomainBundle, *,
                              now_utc: float | None = None,
                              require_arrival_quote: bool = False,
                              c02_terminal_recovery: _C02TerminalRecovery | None = None,
                              c02_terminal_bundle_json: str | None = None,
                              c02_terminal_quote_json: str | None = None) -> RuntimeAdmission:
        """Apply D02/D11 decisions in the graph's existing SQLite transaction."""
        from .runtime.issuers import (
            D03_ARRIVAL_WORK_KIND, D03_SELF_IDENTITY_PROJECTION_WORK_KIND,
            D04_BASELINE_WORK_KIND, D06_FIRST_INGRESS_C02_WORK_KIND,
        )

        if self.__d02_issuer is None or self.__d11_issuer is None:
            raise UnavailableGuard("D02 and D11 runtime issuers are required")
        time_kwargs = {} if now_utc is None else {"now_utc": now_utc}
        if self.__d02_issuer.authorize_resources(
                bundle, db, **time_kwargs) is not True:
            raise AuthorityDenied("D02 resource admission did not approve the bundle")
        qualified_quote = getattr(self.__d02_issuer, "qualified_quote", None)
        if require_arrival_quote and not callable(qualified_quote):
            raise AuthorityDenied("D03 arrival requires a qualified resource quote")
        quote = (qualified_quote(bundle.envelope, db, **time_kwargs)
                 if callable(qualified_quote) else None)
        if require_arrival_quote and (quote is None or
                                      quote.work_kind != D03_ARRIVAL_WORK_KIND):
            raise AuthorityDenied("D03 arrival requires its signed resource quote")
        if quote is not None and quote.work_kind == D03_ARRIVAL_WORK_KIND:
            if db.execute(
                    "SELECT 1 FROM sqlite_master WHERE type='table' "
                    "AND name='graph_d03_arrival_issuance_v2'",
            ).fetchone() is None:
                raise AuthorityDenied("D03 arrival quote lacks sealed graph issuance")
            row = db.execute(
                "SELECT source_ref,quote_id,bundle_digest FROM "
                "graph_d03_arrival_issuance_v2 WHERE bot=? AND persona=? "
                "AND operation_id=?",
                bundle.envelope.authority.namespace.as_tuple
                + (bundle.envelope.identity.operation_id,),
            ).fetchone()
            source_refs = bundle.envelope.source_qualification.source_refs
            if (len(bundle.proposals) != 1 or bundle.proposals[0].domain != "d03"
                    or len(source_refs) != 1
                    or row != (AtomKey.from_token(source_refs[0]).owner.subject,
                               quote.quote_id, bundle.digest)
                    or bundle.persistent_job_refs or bundle.outbox_refs
                    or bundle.d02_settlement_refs or bundle.d11_cost_settlement_refs):
                raise AuthorityDenied("D03 arrival quote cannot authorize a mixed bundle")
        if quote is not None and quote.work_kind == "d07.attention":
            row = db.execute(
                "SELECT c02_operation_id,source_ref,quote_id,bundle_digest "
                "FROM graph_d07_attention_issuance_v1 WHERE bot=? AND persona=? "
                "AND operation_id=?",
                bundle.envelope.authority.namespace.as_tuple
                + (bundle.envelope.identity.operation_id,),
            ).fetchone() if db.execute(
                "SELECT 1 FROM sqlite_master WHERE type='table' "
                "AND name='graph_d07_attention_issuance_v1'",
            ).fetchone() else None
            if (row != (
                    bundle.envelope.causation[0],
                    bundle.envelope.source_qualification.source_refs[0],
                    quote.quote_id, bundle.digest)
                    or len(bundle.proposals) != 1
                    or bundle.proposals[0].domain != "d07"
                    or {write.key.type_name for write in
                        bundle.proposals[0].typed_writes} != {
                            "d07.attention_ticket.v1", "d07.focus.v1"}
                    or bundle.persistent_job_refs or bundle.outbox_refs
                    or bundle.d02_settlement_refs
                    or bundle.d11_cost_settlement_refs):
                raise AuthorityDenied("D07 attention quote lacks sealed issuance")
        if quote is not None and quote.work_kind == D04_BASELINE_WORK_KIND:
            if db.execute(
                    "SELECT 1 FROM sqlite_master WHERE type='table' "
                    "AND name='graph_d04_baseline_issuance_v1'",
            ).fetchone() is None:
                raise AuthorityDenied("D04 baseline quote lacks sealed graph issuance")
            row = db.execute(
                "SELECT source_ref,event_ref,quote_id,bundle_digest FROM "
                "graph_d04_baseline_issuance_v1 WHERE bot=? AND persona=? "
                "AND operation_id=?",
                bundle.envelope.authority.namespace.as_tuple
                + (bundle.envelope.identity.operation_id,),
            ).fetchone()
            if (len(bundle.proposals) != 1 or bundle.proposals[0].domain != "d04"
                    or len(bundle.proposals[0].typed_writes) != 1
                    or bundle.proposals[0].typed_writes[0].key.type_name
                    != "d04.encoding_baseline.v1"
                    or row != (*bundle.envelope.input_refs, quote.quote_id, bundle.digest)
                    or bundle.persistent_job_refs or bundle.outbox_refs
                    or bundle.d02_settlement_refs or bundle.d11_cost_settlement_refs):
                raise AuthorityDenied("D04 baseline quote cannot authorize a mixed bundle")
        if quote is not None and quote.work_kind == D03_SELF_IDENTITY_PROJECTION_WORK_KIND:
            if db.execute(
                    "SELECT 1 FROM sqlite_master WHERE type='table' "
                    "AND name='graph_d03_self_projection_issuance_v1'",
            ).fetchone() is None:
                raise AuthorityDenied("D03 self projection lacks sealed graph issuance")
            row = db.execute(
                "SELECT source_ref,certification_ref,quote_id,bundle_digest "
                "FROM graph_d03_self_projection_issuance_v1 WHERE bot=? AND persona=? "
                "AND operation_id=?",
                bundle.envelope.authority.namespace.as_tuple
                + (bundle.envelope.identity.operation_id,),
            ).fetchone()
            if (len(bundle.proposals) != 1 or bundle.proposals[0].domain != "d03"
                    or not bundle.proposals[0].typed_writes
                    or bundle.proposals[0].typed_writes[-1].key.type_name
                    != "d03.self_perspective.v1"
                    or len(bundle.envelope.input_refs) != 1
                    or row is None
                    or row[0] != bundle.envelope.input_refs[0]
                    or row[2:] != (quote.quote_id, bundle.digest)
                    or bundle.persistent_job_refs or bundle.outbox_refs
                    or bundle.d02_settlement_refs or bundle.d11_cost_settlement_refs):
                raise AuthorityDenied("D03 self projection quote cannot authorize a mixed bundle")
        if c02_terminal_recovery is None:
            admission = self.__d11_issuer.admit_runtime(bundle, db, **time_kwargs)
        else:
            admission = self.__d11_issuer.admit_terminal_d06_first_ingress_c02_v2(
                db, bundle, seal=c02_terminal_recovery.seal,
                bundle_json=c02_terminal_bundle_json,
                quote_json=c02_terminal_quote_json, now_utc=now_utc)
        if not isinstance(admission, RuntimeAdmission):
            raise AuthorityDenied("D11 did not issue a typed runtime admission")
        envelope = bundle.envelope
        identity = envelope.identity
        budget = admission.budget
        if not isinstance(budget, BudgetAdmission):
            raise AuthorityDenied("D11 budget admission is missing")
        if budget.lease_id != envelope.parent_budget_lease_ref:
            raise AuthorityDenied("D11 budget lease differs from the command parent")
        lease = get_budget_lease(db, budget.lease_id)
        if (lease.state != "active" or
                (lease.bot_id, lease.persona_id) != envelope.authority.namespace.as_tuple
                or type(budget.expected_version) is not int
                or budget.expected_version != lease.version):
            raise StaleRead("D11 budget admission has stale lease version")
        budget_operation_id = budget.reservation_operation_id or identity.operation_id
        budget_digest = budget_operation_digest(envelope, budget.lease_id,
                                                budget.ceiling)
        if budget.pre_reserved:
            row = db.execute(
                "SELECT digest,ceiling_json,state FROM runtime_budget_reservations "
                "WHERE lease_id=? AND operation_id=?",
                (budget.lease_id, budget_operation_id),
            ).fetchone()
            if (row is None or row[0] != budget_digest
                    or json.loads(row[1]) != budget.ceiling
                    or row[2] not in {"reserved", "unknown"}):
                raise UnavailableGuard("matching durable budget reservation is absent")
        else:
            if budget.reservation_operation_id is not None:
                raise AuthorityDenied("inline reserve must use the bundle operation ID")
            reserve_budget(db, budget.lease_id, budget_operation_id,
                           budget_digest, budget.ceiling)
        if budget.settle_now:
            if len(bundle.d11_cost_settlement_refs) != 1:
                raise AuthorityDenied("settlement requires one D11 graph cost receipt")
            cost_receipt = settle_budget(db, budget.lease_id, budget_operation_id,
                                         budget_digest, budget.actual,
                                         execution_revoked=budget.execution_revoked)
            self._verify_cost_atom(db, bundle, lease, budget, budget_operation_id,
                                   cost_receipt)
        elif bundle.d11_cost_settlement_refs:
            raise AuthorityDenied("D11 graph cost receipt lacks budget settlement")
        jobs = admission.jobs
        if (not isinstance(jobs, tuple) or
                any(not isinstance(binding, JobBinding) for binding in jobs)):
            raise AuthorityDenied("D11 job bindings must be typed")
        if (len({item.graph_job_ref for item in jobs}) != len(jobs)
                or {item.graph_job_ref for item in jobs}
                != set(bundle.persistent_job_refs)):
            raise AuthorityDenied("durable jobs do not match graph job refs")
        outbox_refs = tuple(ref for item in jobs for ref in item.outbox_refs)
        if len(set(outbox_refs)) != len(outbox_refs) or set(outbox_refs) != set(bundle.outbox_refs):
            raise AuthorityDenied("outbox refs lack a unique durable job binding")
        for binding in jobs:
            job = binding.job
            if (job.operation_id != identity.operation_id
                    or job.activity_id != identity.activity_id
                    or job.effect_id != identity.effect_id
                    or (job.bot_id, job.persona_id) != envelope.authority.namespace.as_tuple
                    or job.budget_ref != budget.lease_id):
                raise AuthorityDenied("D11 durable job identity differs from bundle")
            if budget.pre_reserved:
                existing = get_job(db, job.job_id)
                if (existing.operation_id != job.operation_id
                        or existing.activity_id != job.activity_id
                        or existing.budget_ref != job.budget_ref
                        or (existing.bot_id, existing.persona_id)
                        != (job.bot_id, job.persona_id)
                        or existing.phase in {"draining", "cancelled", "failed"}):
                    raise UnavailableGuard("pre-reserved job is stale or cancelled")
            else:
                if job.phase not in {"queued", "waiting"}:
                    raise AuthorityDenied("new durable job must start queued or waiting")
                job_operation = "job:" + hashlib.sha256(
                    (bundle.digest + job.job_id).encode("utf-8")).hexdigest()[:32]
                create_job(db, job, job_operation, bundle.digest)
                existing = job
            if envelope.authority.worker_fence is not None and (
                    existing.phase != "running"
                    or existing.lease_holder != envelope.authority.actor
                    or existing.fence != envelope.authority.worker_fence
                    or existing.cancel_epoch != 0):
                raise UnavailableGuard("worker result lost its job fence")
        if (envelope.authority.worker_fence is not None and not jobs
                and (quote is None or quote.work_kind !=
                     D06_FIRST_INGRESS_C02_WORK_KIND)):
            raise UnavailableGuard("worker result has no durable job to fence")
        return admission

    @staticmethod
    def _verify_cost_atom(db, bundle, lease, budget, operation_id, receipt):
        """The graph cost atom must agree with the committed budget receipt."""
        ref = bundle.d11_cost_settlement_refs[0]
        writes = (write for proposal in bundle.proposals
                  for write in proposal.typed_writes)
        value = next((write.value for write in writes if write.key.token == ref), None)
        if not isinstance(value, dict):
            raise AuthorityDenied("D11 cost graph atom is missing")
        row = db.execute(
            "SELECT receipt_json FROM runtime_budget_operations WHERE bot_id=? "
            "AND persona_id=? AND operation_id=? AND phase='settle'",
            (lease.bot_id, lease.persona_id, operation_id),
        ).fetchone()
        if row is None:
            raise UnavailableGuard("D11 budget settlement receipt is missing")
        receipt_digest = hashlib.sha256(row[0].encode("utf-8")).hexdigest()
        identity = bundle.envelope.identity
        expected = {
            "bot_id": lease.bot_id, "persona_id": lease.persona_id,
            "activity_id": identity.activity_id,
            "bundle_operation_id": identity.operation_id,
            "effect_id": identity.effect_id,
            "lease_id": lease.lease_id, "currency": lease.currency,
            "cost_operation_id": operation_id,
            "status": receipt.status, "ceiling": budget.ceiling,
            "actual": budget.actual,
            "unconfirmed": budget.ceiling if budget.actual is None else {},
            "budget_phase": "settle", "budget_operation_id": operation_id,
            "budget_receipt_digest": receipt_digest,
        }
        if any(value.get(key) != item for key, item in expected.items()):
            raise AuthorityDenied("D11 cost graph atom differs from budget settlement")

    @staticmethod
    def _deletion_epochs_locked(db, namespace: NamespaceId) -> tuple[int, int]:
        row = db.execute(
            "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
            "WHERE bot=? AND persona=?", namespace.as_tuple).fetchone()
        if row is None or row[0] < 1 or row[1] < 0:
            raise UnavailableGuard("deletion access/delete epochs are unavailable")
        return row[0], row[1]

    def issue_current_c09_erasure_plan_v1(
            self, authority: AuthorityContext, lease: object, *,
            operation_id: str, source_ref: str):
        """Freeze one D06 source erase basis with current signed Owner authority.

        This is a request plan, not an Authority pending or completed deletion.
        """
        from uuid import UUID

        from .runtime.c09_erasure_plan_original_v1 import (
            C09_SOURCE_ERASURE_POLICY_REF, C09ErasurePlanOriginalV1,
            current_c09_source_read_versions_v1,
            read_c09_erasure_plan_original_v1,
            record_c09_erasure_plan_original_v1,
        )

        store, port = self.__store, self.__content_fence_v2
        if (type(authority) is not AuthorityContext
                or authority.issuer_domain != "d12"
                or not isinstance(store, ProductionGraphStore) or port is None):
            raise UnavailableGuard("installed C09 Owner plan issuer unavailable")
        try:
            parsed = UUID(operation_id)
            key = AtomKey.from_token(source_ref)
        except (TypeError, ValueError) as exc:
            raise ValueError("canonical C09 operation and source required") from exc
        namespace = authority.namespace
        if (parsed.version != 4 or str(parsed) != operation_id
                or key != source_key(*namespace.as_tuple, key.owner.subject)):
            raise AuthorityDenied("C09 plan source or operation differs")
        self._authorize(lease, authority, frozenset(("d06",)), owner_read=True)
        binding = self.__owner_leases.get(lease)
        proof = self.__owner_session_proofs.get(lease)
        if (binding is None or proof is None
                or "workbench.erase" not in binding.capabilities
                or binding.actor != authority.actor
                or binding.namespace != namespace
                or binding.purpose != authority.purpose
                or authority.audience != (binding.audience,)):
            raise AuthorityDenied("current signed Owner erase capability required")
        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
        target = metadata.requirements
        if target.activation_generation != authority.activation_generation:
            raise StaleRead("C09 activation changed before plan")
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("C09 plan Authority anchor differs")

        def current_basis():
            db = store._db
            rights = db.execute(
                "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                "WHERE bot=? AND persona=?", namespace.as_tuple,
            ).fetchone()
            if (rights is None or self._v2_graph_stamp(namespace) != (metadata, epoch)):
                raise StaleRead("C09 source graph stamp changed")
            versions = current_c09_source_read_versions_v1(
                db, namespace, key.owner.subject)
            return C09ErasurePlanOriginalV1(
                namespace, operation_id, "one_source", (key.owner.subject,),
                key.owner.subject, source_ref,
                C09_SOURCE_ERASURE_POLICY_REF, 1, target.graph_incarnation,
                epoch.revision,
                rights[0], rights[1], binding.grant_digest, versions,
                canonical_digest((
                    namespace, operation_id, "one_source", (key.owner.subject,),
                    key.owner.subject, source_ref,
                    C09_SOURCE_ERASURE_POLICY_REF, 1, target.graph_incarnation,
                    epoch.revision,
                    rights[0], rights[1], binding.grant_digest, versions)),
            )

        attempt_id = "c09-plan-" + canonical_digest(
            (namespace, operation_id, epoch.revision))[:48]
        with store._lock:
            db = store._db
            db.execute("BEGIN")
            try:
                prior = read_c09_erasure_plan_original_v1(
                    db, namespace, operation_id)
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise
        if prior is not None:
            if prior.source_ref != source_ref:
                raise StaleRead("C09 plan operation source changed")
            lookup = getattr(port, "get_fence_operation", None)
            if not callable(lookup):
                raise UnavailableGuard("C09 plan replay fence reader unavailable")
            saved_permit, state = lookup(
                namespace=namespace, authority_namespace=target.authority_namespace,
                operation_id="c09-plan-" + canonical_digest(
                    (namespace, operation_id, prior.graph_epoch))[:48])
            if (state not in {"active", "finished"}
                    or saved_permit.operation != "write"
                    or saved_permit.holder != self.__holder):
                raise UnavailableGuard("C09 plan replay fence differs")
            if state == "active":
                saved_scope = FenceScope(
                    namespace, target.authority_namespace,
                    authority.activation_generation, "write",
                    saved_permit.operation_id, saved_permit,
                    saved_permit.pinned_anchor, epoch, metadata.graph_revision)
                if port.validate_fence(saved_scope) != saved_permit:
                    raise UnavailableGuard("C09 plan replay permit changed")
                port.finish_fence(
                    saved_scope, request_id="finish:" + saved_permit.operation_id,
                    request_digest="sha256:" + canonical_digest({
                        "action": "record_c09_erasure_plan",
                        "attempt_id": saved_permit.operation_id,
                        "permit_token": saved_permit.token,
                    }))
            return self.read_current_c09_erasure_plan_v1(
                authority, lease, operation_id=operation_id)
        permit = port.begin_fence(
            namespace=namespace, authority_namespace=target.authority_namespace,
            holder=self.__holder, generation=authority.activation_generation,
            operation="write", operation_id=attempt_id,
            expected_anchor=anchor)
        scope = FenceScope(
            namespace, target.authority_namespace,
            authority.activation_generation, "write", attempt_id,
            permit, anchor, epoch, metadata.graph_revision)
        committed = False
        try:
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("C09 plan write fence changed")
            self._owner_binding_in_fence(
                authority, scope, binding.principal, binding,
                owner_session_proof=proof)
            with store._lock:
                db = store._db
                db.execute("BEGIN IMMEDIATE")
                try:
                    original = current_basis()
                    record_c09_erasure_plan_original_v1(db, original)
                    db.execute("COMMIT")
                    committed = True
                except BaseException:
                    db.execute("ROLLBACK")
                    raise
        finally:
            port.finish_fence(
                scope, request_id=("finish:" if committed else "abort:") + attempt_id,
                request_digest="sha256:" + canonical_digest({
                    "action": "record_c09_erasure_plan" if committed
                              else "reject_c09_erasure_plan",
                    "attempt_id": attempt_id, "permit_token": permit.token,
                }))
        return self.read_current_c09_erasure_plan_v1(
            authority, lease, operation_id=operation_id)

    def read_current_c09_erasure_plan_v1(
            self, authority: AuthorityContext, lease: object, *,
            operation_id: str):
        """Reread an immutable plan against current Owner and D06 heads."""
        from .runtime.c09_erasure_plan_original_v1 import (
            current_c09_source_read_versions_v1,
            read_c09_erasure_plan_original_v1,
        )

        store = self.__store
        if (type(authority) is not AuthorityContext
                or authority.issuer_domain != "d12"
                or not isinstance(store, ProductionGraphStore)
                or self.__content_fence_v2 is None):
            raise UnavailableGuard("installed C09 Owner plan reader unavailable")
        self._authorize(lease, authority, frozenset(("d06",)), owner_read=True)
        binding = self.__owner_leases.get(lease)
        proof = self.__owner_session_proofs.get(lease)
        if (binding is None or proof is None
                or "workbench.erase" not in binding.capabilities):
            raise AuthorityDenied("current signed Owner erase capability required")
        namespace = authority.namespace

        def reader():
            db = store._db
            db.execute("BEGIN")
            try:
                original = read_c09_erasure_plan_original_v1(
                    db, namespace, operation_id)
                if original is None or original.owner_grant_digest != binding.grant_digest:
                    raise UnavailableGuard("C09 Owner plan original absent")
                _, epoch = self._v2_graph_stamp(namespace)
                rights = self._deletion_epochs_locked(db, namespace)
                if (original.graph_epoch != epoch.revision
                        or original.graph_incarnation !=
                           self._v2_graph_stamp(namespace)[0].requirements.graph_incarnation
                        or (original.access_epoch, original.delete_epoch) != rights
                        or original.read_versions !=
                           current_c09_source_read_versions_v1(
                               db, namespace, original.source_id)):
                    raise StaleRead("C09 plan source or rights changed")
                db.execute("COMMIT")
                return original
            except BaseException:
                db.execute("ROLLBACK")
                raise

        return self._read_v2(
            authority, reader, owner_binding=binding,
            owner_session_proof=proof)

    def read_current_c09_graph_barrier_v1(
            self, bootstrap: object, *, namespace: NamespaceId,
            deletion_operation_id: str, permit: object):
        """Reread one graph barrier against the live Authority deletion head.

        A caller cannot provide a graph attestation or a pending receipt. The
        paired Authority port authenticates the updated live delete permit and
        returns the original pending mutation before and after the graph read.
        """
        from .authority_service.v2_contract import (
            DeletionMutationReceiptV1, FencePermitV2,
        )
        from .runtime.c09_erasure_barrier_store_v1 import (
            verify_c09_graph_barrier_v1,
        )

        store = self.__store
        port = self.__content_fence_v2
        if (bootstrap is not self.__bootstrap
                or not isinstance(store, ProductionGraphStore)
                or port is None or type(namespace) is not NamespaceId
                or type(deletion_operation_id) is not str
                or not deletion_operation_id or type(permit) is not FencePermitV2
                or permit.operation != "delete"):
            raise AuthorityDenied("installed C09 graph barrier reader required")
        reader = getattr(port, "get_pending_deletion_for_graph_write", None)
        if not callable(reader):
            raise UnavailableGuard("paired deletion pending reader unavailable")
        with store._lock:
            metadata, _ = self._v2_graph_stamp(namespace)
            target = metadata.requirements
        if (target.namespace != namespace
                or permit.namespace != target.authority_namespace
                or permit.authority_id != target.authority_id
                or permit.generation != target.activation_generation):
            raise AuthorityDenied("C09 deletion permit crosses graph identity")
        args = dict(namespace=namespace,
                    authority_namespace=target.authority_namespace,
                    deletion_operation_id=deletion_operation_id,
                    permit=permit)
        pending = reader(**args)
        if (type(pending) is not DeletionMutationReceiptV1
                or pending.pending.deletion_operation_id != deletion_operation_id
                or pending.pending.target_phase != "pending"
                or pending.pending.source_phase != "absent"
                or pending.pending.evidence.issuer_id != "authority-owner-graph-plan-v2"
                or pending.after_anchor != permit.pinned_anchor
                or pending.updated_revision != permit.revision
                or not self._anchor_matches(target, pending.after_anchor)):
            raise UnavailableGuard("current C09 Authority pending differs")
        roots = tuple(sorted(source_key(*namespace.as_tuple, source_id).token
                             for source_id in pending.pending.closure_roots))
        with store._lock:
            graph = verify_c09_graph_barrier_v1(
                store._db, namespace, deletion_operation_id,
                request_digest=pending.pending.request_digest.removeprefix("sha256:"),
                pending_receipt_digest=canonical_digest(pending),
            )
            if (graph is None or graph.root_source_refs != roots
                    or graph.closure_digest !=
                       pending.pending.evidence.scope_digest.removeprefix("sha256:")
                    or graph.delete_epoch_after != pending.pending.deletion_epoch
                    or graph.graph_incarnation != target.graph_incarnation):
                raise UnavailableGuard("current C09 graph barrier differs")
        if reader(**args) != pending:
            raise UnavailableGuard("C09 Authority pending changed during graph read")
        return graph

    def commit_current_c09_source_barrier_v1(
            self, bootstrap: object, *, namespace: NamespaceId,
            deletion_operation_id: str, permit: object):
        """Withdraw the exact current source descendant closure under delete fence.

        This is the graph barrier only. It does not attest deletion of historical
        graph values, indexes, process caches, jobs, or backups.
        """
        from .authority_service.v2_contract import (
            DeletionMutationReceiptV1, FencePermitV2, deletion_scope_digest,
        )
        from .runtime.c09_erasure_plan_original_v1 import (
            authority_c09_plan_request_identity_v1, read_c09_erasure_plan_original_v1,
            current_c09_source_read_versions_v1,
        )
        from .runtime.c09_erasure_barrier_store_v1 import (
            read_c09_erasure_barrier_v1,
            record_c09_erasure_barrier_after_graph_v1,
            verify_c09_graph_barrier_v1,
        )

        store = self.__store
        port = self.__content_fence_v2
        reader = getattr(port, "get_pending_deletion_for_graph_write", None)
        if (bootstrap is not self.__bootstrap
                or not isinstance(store, ProductionGraphStore)
                or not callable(reader) or type(namespace) is not NamespaceId
                or type(deletion_operation_id) is not str
                or not deletion_operation_id or type(permit) is not FencePermitV2
                or permit.operation != "delete"):
            raise AuthorityDenied("installed C09 delete fence required")
        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
        target = metadata.requirements
        if (target.namespace != namespace
                or permit.namespace != target.authority_namespace
                or permit.authority_id != target.authority_id
                or permit.generation != target.activation_generation):
            raise AuthorityDenied("C09 delete permit crosses graph identity")
        args = dict(namespace=namespace,
                    authority_namespace=target.authority_namespace,
                    deletion_operation_id=deletion_operation_id,
                    permit=permit)
        pending = reader(**args)
        if (type(pending) is not DeletionMutationReceiptV1
                or pending.pending.source_phase != "absent"
                or pending.pending.target_phase != "pending"
                or pending.pending.deletion_operation_id != deletion_operation_id
                or pending.pending.evidence.issuer_id != "authority-owner-graph-plan-v2"
                or pending.after_anchor != permit.pinned_anchor
                or pending.updated_revision != permit.revision):
            raise UnavailableGuard("C09 pending original differs from graph")
        expected_request = pending.pending.request_digest.removeprefix("sha256:")
        pending_digest = canonical_digest(pending)
        if self._has_c09_source_barrier(namespace, deletion_operation_id):
            if not self._anchor_matches(target, pending.after_anchor):
                raise UnavailableGuard("C09 replay recovery anchor differs")
            return self.read_current_c09_graph_barrier_v1(
                bootstrap, namespace=namespace,
                deletion_operation_id=deletion_operation_id, permit=permit,
            )
        if not self._anchor_matches(target, pending.pending.before_anchor):
            raise UnavailableGuard("C09 pre-barrier recovery anchor differs")
        with store._lock:
            db = store._db
            db.execute("BEGIN IMMEDIATE")
            try:
                if self._v2_graph_stamp(namespace) != (metadata, epoch):
                    raise StaleRead("C09 graph changed before barrier")
                if read_c09_erasure_barrier_v1(
                        db, namespace, deletion_operation_id) is not None:
                    raise StaleRead("C09 barrier appeared before commit")
                owner = db.execute(
                    "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                    (owner_grant_key(*namespace.as_tuple).token,),
                ).fetchone()
                issue = db.execute(
                    "SELECT grant_digest FROM graph_owner_issue_operations_v1 "
                    "WHERE bot=? AND persona=?", namespace.as_tuple,
                ).fetchone()
                if owner is None or owner[0] != 1 or owner[2] != 1 or issue is None:
                    raise UnavailableGuard("C09 current graph Owner is unavailable")
                grant = json.loads(owner[1])
                validate_owner_grant_v1(grant)
                if (grant["state"] != "pending_authority"
                        or grant["authority_id"] != target.authority_id
                        or grant["installation_id"] !=
                           port.installation_grant.installation_id
                        or canonical_json(grant) != owner[1]):
                    raise AuthorityDenied("C09 graph Owner differs from Authority")
                rights = db.execute(
                    "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                    "WHERE bot=? AND persona=?", namespace.as_tuple,
                ).fetchone()
                if (rights is None or rights[0] < 1
                        or pending.pending.deletion_epoch != rights[1] + 1):
                    raise StaleRead("C09 deletion epoch changed")
                plan = read_c09_erasure_plan_original_v1(db, namespace, deletion_operation_id)
                if (plan is None or plan.root_source_ids != pending.pending.closure_roots
                        or plan.policy_ref != pending.pending.policy_ref
                        or plan.policy_version != 1
                        or plan.graph_incarnation != target.graph_incarnation
                        or plan.graph_epoch != epoch.revision
                        or (plan.access_epoch, plan.delete_epoch) != rights
                        or plan.delete_epoch + 1 != pending.pending.deletion_epoch
                        or "sha256:" + canonical_digest(grant) != plan.owner_grant_digest
                        or issue != (plan.owner_grant_digest,)
                        or plan.read_versions != current_c09_source_read_versions_v1(db, namespace, plan.source_id)):
                    raise UnavailableGuard("C09 actual authorized plan or immutable Owner origin differs")
                import hashlib
                plan_request = "sha256:" + hashlib.sha256(json.dumps(
                    authority_c09_plan_request_identity_v1(target.authority_namespace, plan),
                    sort_keys=True, separators=(",", ":"), ensure_ascii=True).encode()).hexdigest()
                if (pending.pending.request_digest != plan_request
                        or pending.pending.evidence.scope_digest != deletion_scope_digest(
                            plan.root_source_ids, plan.delete_epoch + 1, plan.policy_ref)):
                    raise AuthorityDenied("C09 independent pending does not authorize this exact plan")
                source_rows = db.execute(
                    "SELECT token,revision,value FROM graph_atoms "
                    "WHERE bot=? AND persona=? AND type_name='memory.source' "
                    "AND valid=1 ORDER BY token LIMIT 4097", namespace.as_tuple,
                ).fetchall()
                if len(source_rows) > 4096:
                    raise UnavailableGuard("C09 source inventory exceeds bound")
                sources = {}
                for token, revision, value in source_rows:
                    source = SourceRecord.from_dict(json.loads(value))
                    if source_key(*namespace.as_tuple, source.source_id).token != token:
                        raise UnavailableGuard("C09 source identity differs")
                    sources[token] = (revision, source)
                roots = tuple(sorted(source_key(*namespace.as_tuple, source_id).token
                                     for source_id in pending.pending.closure_roots))
                affected = set(roots)
                if not affected.issubset(sources):
                    raise UnavailableGuard("C09 requested source root is absent")
                while True:
                    expanded = affected | {
                        token for token, (_, source) in sources.items()
                        if any(source_key(*namespace.as_tuple, parent).token
                               in affected for parent in source.parent_source_ids)
                    }
                    if expanded == affected:
                        break
                    affected = expanded
                affected_refs = tuple(sorted(affected))
                read_versions = {version.key: version for version in plan.read_versions}
                read_versions[owner_grant_key(*namespace.as_tuple)] = GraphVersion(owner_grant_key(*namespace.as_tuple), owner[0])
                read_versions.update({AtomKey.from_token(token): GraphVersion(AtomKey.from_token(token), sources[token][0])
                                      for token in affected_refs})
                writes = []
                for token in affected_refs:
                    source = AtomKey.from_token(token)
                    key = access_key(*namespace.as_tuple, source.owner.subject)
                    row = db.execute(
                        "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                        (key.token,),
                    ).fetchone()
                    if row is None or row[2] != 1:
                        raise UnavailableGuard("C09 current source access is absent")
                    value = json.loads(row[1])
                    validate_access(value)
                    if (value["source_id"] != source.owner.subject
                            or value["status"] != "active"):
                        raise UnavailableGuard("C09 source access is not active")
                    read_versions[key] = GraphVersion(key, row[0])
                    writes.append(GraphWrite(key, {**value, "status": "withdrawn"}))
                event = Event(
                    Scope(*namespace.as_tuple, "c09-source-barrier-v1"),
                    deletion_operation_id, 0.0, "source_access_withdrawn",
                    {"pending_receipt_digest": pending_digest,
                     "affected_source_refs": list(affected_refs)},
                )
                graph_receipt = GraphStore._graph_commit_in_transaction(
                    store, GraphCandidate(event, tuple(read_versions[key] for key in sorted(read_versions, key=lambda value:value.token)), tuple(writes),
                                          (epoch,)),
                    _capability=self.__graph_capability,
                )
                if graph_receipt.status != "committed":
                    raise UnavailableGuard("C09 graph barrier was not newly committed")
                barrier = record_c09_erasure_barrier_after_graph_v1(
                    db, namespace, operation_id=deletion_operation_id,
                    request_digest=expected_request,
                    pending_receipt_digest=pending_digest,
                    closure_digest=pending.pending.evidence.scope_digest.removeprefix(
                        "sha256:"),
                    root_source_refs=roots, affected_source_refs=affected_refs,
                    graph_incarnation=target.graph_incarnation,
                    graph_epoch_before=epoch.revision,
                    access_epoch_before=rights[0], delete_epoch_before=rights[1],
                    event_session="c09-source-barrier-v1",
                    graph_receipt=graph_receipt,
                )
                from .runtime.source_attachment_graph_v2 import scrub_media_blobs
                for token in affected_refs:
                    scrub_media_blobs(
                        db, namespace, AtomKey.from_token(token).owner.subject)
                verify_c09_graph_barrier_v1(
                    db, namespace, deletion_operation_id,
                    request_digest=expected_request,
                    pending_receipt_digest=pending_digest,
                )
                after = pending.after_anchor
                store.cas_graph_recovery_metadata(
                    metadata, replace(
                        target, deletion_seq=after.deletion_seq,
                        deletion_digest=after.deletion_digest,
                        revocation_epoch=after.revocation_epoch),
                    _capability=self.__graph_capability,
                )
                db.execute("COMMIT")
            except BaseException:
                if db.in_transaction:
                    db.execute("ROLLBACK")
                raise
        return self.read_current_c09_graph_barrier_v1(
            bootstrap, namespace=namespace,
            deletion_operation_id=deletion_operation_id, permit=permit,
        )

    def _has_c09_source_barrier(self, namespace: NamespaceId,
                                operation_id: str) -> bool:
        from .runtime.c09_erasure_barrier_store_v1 import read_c09_erasure_barrier_v1
        with self.__store._lock:
            return read_c09_erasure_barrier_v1(
                self.__store._db, namespace, operation_id) is not None

    def read_deletion_snapshot_candidate(
            self, authority: AuthorityContext, lease: object,
            keys: tuple[AtomKey, ...], *, page_limit: int = 128,
            max_pages: int = 16) -> DeletionSnapshotCandidate:
        """Collect bounded namespace history under one v2 Authority read fence.

        The caller supplies no cursor or completion flag. A partial result is
        evidence for more work only; deletion still needs independent admission.
        """
        if not isinstance(authority, AuthorityContext):
            raise TypeError("authority required")
        if (not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None):
            raise UnavailableGuard("v2 deletion read fence is unavailable")
        if (lease not in self.__deletion_read_leases
                or authority.issuer_domain != "d06"
                or authority.purpose != "deletion_cleanup"
                or authority.audience != ("internal",)
                or authority.provider_policy_ref != "d06-deletion-closure-v1"
                or authority.activation_generation != self.__leases[lease][6]):
            raise AuthorityDenied("host-minted deletion read lease required")
        keys = tuple(keys)
        if not keys or len(keys) > 512 or len(set(keys)) != len(keys):
            raise ValueError("deletion read requires 1 to 512 unique keys")
        if (type(page_limit) is not int or not 1 <= page_limit <= 512
                or type(max_pages) is not int or not 1 <= max_pages <= 32):
            raise ValueError("deletion history page bounds are invalid")
        if any(not isinstance(key, AtomKey)
               or NamespaceId.from_key(key) != authority.namespace
               for key in keys):
            raise AuthorityDenied("deletion key crosses namespace")
        specs = self.__store._registry.specs
        if not specs or any(spec.writer_domain is None for spec in specs):
            raise UnavailableGuard("deletion read requires complete type ownership")
        domains = frozenset(spec.writer_domain for spec in specs)
        owner_kinds = frozenset(kind for spec in specs for kind in spec.owner_kinds)
        if not owner_kinds.issubset(authority.owner_scope):
            raise AuthorityDenied("deletion read owner scope is incomplete")
        self._authorize(lease, authority, domains, owner_read=True)

        store = self.__store
        namespace = authority.namespace
        candidate_sql = (
            "SELECT c.operation_id,c.schema,c.bundle_digest,c.fence_attempt_id,"
            "c.bundle_json,c.evidence_json,i.digest,i.fence_attempt_id,"
            "o.operation_id,r.operation_id "
            "FROM graph_first_ingress_c02_candidates_v1 c "
            "LEFT JOIN graph_bundle_intents_v2 i ON i.bot=c.bot "
            "AND i.persona=c.persona AND i.operation_id=c.operation_id "
            "LEFT JOIN graph_bundle_operations o ON o.bot=c.bot "
            "AND o.persona=c.persona AND o.operation_id=c.operation_id "
            "LEFT JOIN graph_bundle_rejections_v2 r ON r.bot=c.bot "
            "AND r.persona=c.persona AND r.operation_id=c.operation_id "
            "WHERE c.bot=? AND c.persona=? ORDER BY c.operation_id LIMIT ?"
        )
        candidate_args = namespace.as_tuple + (page_limit * max_pages + 1,)
        candidate_rows_at_read = None

        def reader():
            nonlocal candidate_rows_at_read
            from .runtime.c02_bundle_codec import c02_bundle_from_wire

            access_epoch, delete_epoch = self._deletion_epochs_locked(
                store._db, namespace)
            candidate_rows = store._db.execute(
                candidate_sql, candidate_args).fetchall()
            candidate_rows_at_read = candidate_rows
            if len(candidate_rows) > page_limit * max_pages:
                raise UnavailableGuard("pending C02 inventory exceeds read bounds; HOLD")
            pending_c02_sources = []
            for (operation_id, schema, digest, attempt_id, bundle_json,
                 evidence_json, intent_digest, intent_attempt, committed,
                 rejected) in candidate_rows:
                try:
                    bundle = c02_bundle_from_wire(bundle_json)
                    evidence = json.loads(evidence_json)
                    source = AtomKey.from_token(bundle.envelope.input_refs[0])
                    d06_writes = bundle.proposals[0].typed_writes
                    if (type(operation_id) is not str or not operation_id
                            or schema != "sylanne.first-ingress-c02-candidate.v1"
                            or digest != intent_digest or digest != bundle.digest
                            or attempt_id != intent_attempt
                            or committed is not None or rejected is not None
                            or bundle.envelope.identity.operation_id != operation_id
                            or bundle.envelope.authority.namespace != namespace
                            or len(bundle.envelope.input_refs) != 3
                            or bundle.envelope.source_qualification.source_refs
                            != (source.token,)
                            or len(d06_writes) != 2
                            or d06_writes[0].key.type_name != "memory.episode.v1"
                            or d06_writes[1].key.type_name != "memory.subjective_trace.v2"
                            or NamespaceId.from_key(d06_writes[0].key) != namespace
                            or NamespaceId.from_key(d06_writes[1].key) != namespace
                            or d06_writes[0].value.get("source_refs") != [source.token]
                            or d06_writes[1].value.get("episode_ref")
                            != d06_writes[0].key.token
                            or source.type_name != "memory.source"
                            or source.owner.kind != "event" or source.name != "record"
                            or NamespaceId.from_key(source) != namespace
                            or type(evidence) is not dict
                            or type(evidence.get("source_ref")) is not str
                            or evidence["source_ref"] != source.owner.subject
                            or canonical_json(evidence) != evidence_json):
                        raise ValueError("pending C02 source identity differs")
                except (ValueError, TypeError, KeyError, IndexError) as exc:
                    raise UnavailableGuard("pending C02 source is unreadable; HOLD") from exc
                pending_c02_sources.append((operation_id, source.token))
            cursor = None
            epoch = None
            first = None
            rows = {}
            edges = []
            pages_scanned = 0
            complete = False
            for _ in range(max_pages):
                page = GraphStore._deletion_snapshot_page(
                    store, namespace, keys, after=cursor, expected_epoch=epoch,
                    limit=page_limit, _capability=self.__graph_capability)
                pages_scanned += 1
                if first is None:
                    first = page
                    epoch = page.epoch
                for row in page.history_rows:
                    rows.setdefault((row.atom.key, row.atom.revision), row)
                edges.extend(page.history_edges)
                complete = page.complete
                if complete:
                    break
                cursor = page.next_after
            if (access_epoch, delete_epoch) != self._deletion_epochs_locked(
                    store._db, namespace):
                raise UnavailableGuard("deletion access/delete epochs changed during read")
            return DeletionSnapshotCandidate(
                first.snapshot, first.read_set, first.current_reverse_edges,
                tuple(rows.values()), tuple(edges), access_epoch, delete_epoch,
                complete, pages_scanned, tuple(pending_c02_sources))

        def final_check(candidate):
            if (candidate.access_epoch, candidate.delete_epoch) != (
                    self._deletion_epochs_locked(store._db, namespace)):
                raise UnavailableGuard("deletion access/delete epochs changed during read")
            if store._db.execute(candidate_sql, candidate_args).fetchall() != candidate_rows_at_read:
                raise UnavailableGuard("pending C02 inventory changed during read; HOLD")

        return self._read_v2(authority, reader, final_check=final_check)

    def read_snapshot(self, authority: AuthorityContext, lease: object,
                      keys) -> GraphSnapshot:
        if not isinstance(authority, AuthorityContext):
            raise TypeError("authority required")
        keys = tuple(keys)
        if not keys:
            raise ValueError("read_snapshot requires explicit keys")
        if any(NamespaceId.from_key(key) != authority.namespace
               or key.owner.kind not in authority.owner_scope for key in keys):
            raise AuthorityDenied("read key is outside authorized namespace or owner scope")
        domains = frozenset(self.__store._registry.spec(key.type_name).writer_domain
                            for key in keys)
        self._authorize(lease, authority, domains, owner_read=True)
        if isinstance(self.__store, ProductionGraphStore) and self.__content_fence_v2 is not None:
            return self._read_v2(authority, lambda: GraphStore.graph_snapshot(
                self.__store, keys, _capability=self.__graph_capability),
                owner_binding=self.__owner_leases.get(lease),
                owner_session_proof=self.__owner_session_proofs.get(lease))
        with self._content_fence(authority.namespace, authority.activation_generation, "read"):
            store = self.__store
            with store._lock:
                self._admit_content(authority.namespace, authority.activation_generation,
                                    "read", tuple(key.token for key in keys))
                return GraphStore.graph_snapshot(
                    store, keys, _capability=self.__graph_capability)

    def with_current_creator_draft_v1(
            self, authority: AuthorityContext, lease: object, *,
            draft_ref: str, required_capability: str, project):
        """Project D12's current draft and head under the signed Owner read fence.

        The callback receives only graph values read inside this fence.  Its
        creator flag is derived from the current paired Owner grant, never from
        a browser or the D12 caller.
        """
        from .domains.d12.scheme_command import D12CurrentCreatorDraftV1
        from .domains.d12.types import (
            ActiveSchemeHeadV1, CharacterDraft, active_scheme_head_key,
            character_draft_key,
        )

        if (type(authority) is not AuthorityContext
                or authority.issuer_domain != "d12"
                or "persona" not in authority.owner_scope
                or required_capability not in {
                    "workbench.create", "workbench.compile",
                    "workbench.experiment", "workbench.activate",
                }
                or not callable(project)):
            raise AuthorityDenied("current creator draft authority required")
        if (not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None):
            raise UnavailableGuard("current creator draft requires v2 read fence")
        draft_key = character_draft_key(authority.namespace)
        head_key = active_scheme_head_key(authority.namespace)
        if draft_ref != draft_key.token:
            raise AuthorityDenied("current creator draft ref differs")
        self._authorize(lease, authority, frozenset(("d12",)), owner_read=True)
        binding = self.__owner_leases.get(lease)
        proof = self.__owner_session_proofs.get(lease)
        if (binding is None or proof is None
                or required_capability not in binding.capabilities
                or binding.actor != authority.actor
                or binding.namespace != authority.namespace
                or binding.purpose != authority.purpose
                or authority.audience != (binding.audience,)):
            raise UnavailableGuard("current signed creator grant is unavailable")

        store = self.__store

        def read_and_project():
            current = self.__owner_leases.get(lease)
            if (current != binding or self.__owner_session_proofs.get(lease) != proof
                    or required_capability not in current.capabilities):
                raise UnavailableGuard("creator lease changed during read")
            snapshot = GraphStore.graph_snapshot(
                store, (draft_key, head_key),
                _capability=self.__graph_capability)
            draft_atom, head_atom = snapshot.atoms
            if (draft_atom.revision < 1 or not draft_atom.valid
                    or head_atom.revision > 0 and not head_atom.valid
                    or len(snapshot.epochs) != 1):
                raise UnavailableGuard("current creator draft or head unavailable")
            try:
                payload = dict(draft_atom.value)
                if payload.pop("schema") != draft_key.type_name:
                    raise ValueError("draft schema differs")
                draft = CharacterDraft(**payload)
                if (draft.scope != authority.namespace.persona_id
                        or draft.revision != draft_atom.revision):
                    raise ValueError("draft revision differs")
                if head_atom.revision:
                    head_payload = dict(head_atom.value)
                    if head_payload.pop("schema") != head_key.type_name:
                        raise ValueError("active head schema differs")
                    head = ActiveSchemeHeadV1(**head_payload)
                    if (head.scope != authority.namespace.persona_id
                            or head.generation != head_atom.revision):
                        raise ValueError("active head revision differs")
            except (TypeError, ValueError, KeyError) as exc:
                raise UnavailableGuard("current creator draft or head is invalid") from exc
            metadata, graph_epoch = self._v2_graph_stamp(authority.namespace)
            if graph_epoch != snapshot.epochs[0]:
                raise StaleRead("creator draft graph revision changed")
            epochs = store._db.execute(
                "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                "WHERE bot=? AND persona=?", authority.namespace.as_tuple,
            ).fetchone()
            if (epochs is None or any(type(value) is not int or value < 0
                                       for value in epochs)):
                raise UnavailableGuard("creator graph authority epochs unavailable")
            frame = D12CurrentCreatorDraftV1(
                authority.namespace, draft_ref, draft_atom.revision, draft,
                head_key.token, head_atom.revision, metadata.graph_revision,
                epochs[0], epochs[1], True,
            )
            return project(frame)

        return self._read_v2(
            authority, read_and_project, owner_binding=binding,
            owner_session_proof=proof,
        )

    def initialize_current_d09_scheme_draft_v1(
            self, authority: AuthorityContext, lease: object, *,
            operation_id: str, policy):
        """Create the first D12 draft/head from a signed Owner D09 edit."""
        from uuid import UUID

        from .domains.d09.expression_policy import D09ExpressionPolicyV1
        from .domains.d12.scheme_command import D12SchemeHold
        from .domains.d12.types import (
            ActiveSchemeHeadV1, CharacterDraft, active_scheme_head_key,
            character_draft_key,
        )
        from .runtime.first_ingress_v2 import trusted_upper

        try:
            parsed = UUID(operation_id)
        except (TypeError, ValueError) as exc:
            raise D12SchemeHold("canonical initial draft operation required") from exc
        if (parsed.version != 4 or str(parsed) != operation_id
                or type(policy) is not D09ExpressionPolicyV1
                or type(authority) is not AuthorityContext
                or authority.issuer_domain != "d12"
                or not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None):
            raise D12SchemeHold("installed D12 initial draft authority unavailable")
        self._authorize(lease, authority, frozenset(("d12",)), owner_read=True)
        binding = self.__owner_leases.get(lease)
        owner_proof = self.__owner_session_proofs.get(lease)
        namespace = authority.namespace
        if (binding is None or owner_proof is None
                or "workbench.create" not in binding.capabilities
                or binding.actor != authority.actor
                or binding.namespace != namespace
                or binding.purpose != authority.purpose
                or authority.audience != (binding.audience,)):
            raise D12SchemeHold("current signed Owner draft capability unavailable")
        store, port = self.__store, self.__content_fence_v2
        draft_key = character_draft_key(namespace)
        head_key = active_scheme_head_key(namespace)
        draft = CharacterDraft(
            namespace.persona_id, 1,
            {"d09.expression_policy": asdict(policy)},
            {"d09.expression_policy": "owner"})
        head = ActiveSchemeHeadV1(
            namespace.persona_id, 1,
            canonical_digest(("initial_d12_head", namespace)),
            draft_key.token, 1, canonical_digest(draft), None,
            operation_id, "initial")
        request_digest = canonical_digest((namespace, operation_id, draft, head))
        attempt_id = "d12-draft-" + request_digest[:48]
        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
            rows = store._db.execute(
                "SELECT token,revision,value,valid FROM graph_atoms "
                "WHERE token IN (?,?)", (draft_key.token, head_key.token),
            ).fetchall()
        target = metadata.requirements
        if (target.namespace != namespace
                or target.activation_generation != authority.activation_generation):
            raise StaleRead("D12 draft activation changed")
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("D12 draft recovery anchor differs")
        existing = {row[0]: row[1:] for row in rows}
        if existing:
            if set(existing) != {draft_key.token, head_key.token}:
                raise D12SchemeHold("D12 draft/head is only partly initialized")
            expected = {
                draft_key.token: {"schema": draft_key.type_name, **asdict(draft)},
                head_key.token: {"schema": head_key.type_name, **asdict(head)},
            }
            if any((existing[token][0] != 1 or existing[token][2] != 1
                    or json.loads(existing[token][1]) != value)
                   for token, value in expected.items()):
                raise D12SchemeHold("D12 initial draft operation differs")
            lookup = getattr(port, "get_fence_operation", None)
            if not callable(lookup):
                raise UnavailableGuard("D12 draft replay fence reader unavailable")
            permit, state = lookup(
                namespace=namespace, authority_namespace=target.authority_namespace,
                operation_id=attempt_id)
            if (permit is None or state not in {"active", "finished"}
                    or permit.operation != "write"
                    or permit.operation_id != attempt_id
                    or permit.pinned_anchor != anchor):
                raise UnavailableGuard("D12 draft replay fence differs")
            scope = FenceScope(
                namespace, target.authority_namespace,
                authority.activation_generation, "write", attempt_id,
                permit, anchor, epoch, metadata.graph_revision)
            if state == "active":
                port.finish_fence(
                    scope, request_id="finish:" + attempt_id,
                    request_digest="sha256:" + canonical_digest({
                        "action": "finish_d12_initial_draft",
                        "operation_id": attempt_id,
                        "permit_token": permit.token,
                    }))
            return GraphVersion(draft_key, 1), GraphVersion(head_key, 1)

        now = trusted_upper(port.read_ingress_clock(self.__scene_clock_policy))
        permit = port.begin_fence(
            namespace=namespace, authority_namespace=target.authority_namespace,
            holder=self.__holder, generation=authority.activation_generation,
            operation="write", operation_id=attempt_id, expected_anchor=anchor)
        if (permit is None or permit.operation != "write"
                or permit.operation_id != attempt_id
                or permit.pinned_anchor != anchor
                or permit.holder != self.__holder):
            raise UnavailableGuard("D12 draft write permit differs")
        scope = FenceScope(
            namespace, target.authority_namespace, authority.activation_generation,
            "write", attempt_id, permit, anchor, epoch, metadata.graph_revision)
        try:
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("D12 draft write permit changed")
            self._owner_binding_in_fence(
                authority, scope, binding.principal, binding,
                owner_session_proof=owner_proof)
            with store._lock:
                db = store._db
                db.execute("BEGIN IMMEDIATE")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise StaleRead("D12 initial draft graph changed")
                    if any(db.execute(
                            "SELECT 1 FROM graph_atoms WHERE token=?", (key.token,),
                    ).fetchone() is not None for key in (draft_key, head_key)):
                        raise D12SchemeHold("D12 current draft already exists")
                    event = Event(
                        Scope(*namespace.as_tuple, "d12.initial_d09_draft.v1"),
                        operation_id, now, "scheme_initial_draft",
                        {"draft_digest": canonical_digest(draft)})
                    candidate = GraphCandidate(
                        event, (GraphVersion(draft_key, 0),
                                GraphVersion(head_key, 0)),
                        (GraphWrite(draft_key, {
                            "schema": draft_key.type_name, **asdict(draft)}),
                         GraphWrite(head_key, {
                            "schema": head_key.type_name, **asdict(head)})),
                        (epoch,))
                    def record(_db, graph_receipt):
                        if (graph_receipt.status != "committed"
                                or graph_receipt.revisions != (
                                    GraphVersion(draft_key, 1),
                                    GraphVersion(head_key, 1))):
                            raise D12SchemeHold("D12 initial draft graph CAS differs")
                        replacement = replace(
                            target, deletion_seq=anchor.deletion_seq,
                            deletion_digest=anchor.deletion_digest,
                            execution_seq=anchor.execution_seq,
                            execution_digest=anchor.execution_digest,
                            revocation_epoch=anchor.revocation_epoch)
                        store.cas_graph_recovery_metadata(
                            metadata, replacement,
                            _capability=self.__graph_capability)
                    receipt = GraphStore._graph_commit_in_transaction(
                        store, candidate, _receipt_hook=record,
                        _capability=self.__graph_capability)
                    if receipt.status != "committed":
                        raise D12SchemeHold("D12 initial draft did not commit")
                    db.execute("COMMIT")
                except BaseException:
                    if db.in_transaction:
                        db.execute("ROLLBACK")
                    raise
            return GraphVersion(draft_key, 1), GraphVersion(head_key, 1)
        finally:
            port.finish_fence(
                scope, request_id="finish:" + attempt_id,
                request_digest="sha256:" + canonical_digest({
                    "action": "finish_d12_initial_draft",
                    "operation_id": attempt_id, "permit_token": permit.token,
                }))

    def compile_current_scheme_for_operation_v1(
            self, authority: AuthorityContext, lease: object, *,
            operation_id: str, draft_ref: str, budget_ref: str):
        """Persist typed D12 compilation and its original under one Owner write fence.

        This deterministic compilation consumes no paid model/experiment cost.
        Its budget digest identifies the current signed D11 authorization only.
        """
        from dataclasses import replace as dataclass_replace
        from uuid import UUID

        from .domains.d12.scheme_command import (
            D12CompiledSchemeV1, D12CurrentCreatorDraftV1,
            D12DomainCompileRejectionV1, D12SchemeHold,
            compiled_scheme_digest_v1,
        )
        from .domains.d12.types import (
            ActiveSchemeHeadV1, CharacterDraft, active_scheme_head_key,
            character_draft_key,
        )
        from .runtime.d12_compiled_candidate_store_v1 import (
            install_d12_compiled_candidate_store_v1,
            record_d12_domain_candidate_v1,
        )
        from .runtime.d12_domain_scheme_compile_v1 import (
            compile_d12_domain_scheme_candidate_v1,
        )
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.scheme_original_store_v1 import (
            CompilationOriginalV1, install_scheme_original_store_v1,
            read_compilation_original_for_operation_v1,
            record_compilation_original_for_operation_v1,
        )

        store, port, namespace = self.__store, self.__content_fence_v2, authority.namespace
        try:
            parsed_operation = UUID(operation_id)
        except (TypeError, ValueError) as exc:
            raise D12SchemeHold("canonical compile operation is required") from exc
        if (parsed_operation.version != 4 or str(parsed_operation) != operation_id
                or type(budget_ref) is not str or not budget_ref
                or type(authority) is not AuthorityContext
                or authority.issuer_domain != "d12"
                or not isinstance(store, ProductionGraphStore) or port is None
                or self.__d11_issuer is None):
            raise D12SchemeHold("installed D12 compilation authority is unavailable")
        self._authorize(lease, authority, frozenset(("d12", "d11")), owner_read=True)
        binding = self.__owner_leases.get(lease)
        proof = self.__owner_session_proofs.get(lease)
        if (binding is None or proof is None
                or "workbench.compile" not in binding.capabilities
                or binding.actor != authority.actor
                or binding.namespace != namespace
                or binding.purpose != authority.purpose
                or authority.audience != (binding.audience,)):
            raise D12SchemeHold("current Owner compile capability is unavailable")
        if draft_ref != character_draft_key(namespace).token:
            raise D12SchemeHold("current creator draft ref differs")
        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
        target = metadata.requirements
        if (target.namespace != namespace
                or target.activation_generation != authority.activation_generation):
            raise StaleRead("D12 current activation changed before compilation")
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("D12 compilation recovery anchor differs")
        now = trusted_upper(port.read_ingress_clock(self.__scene_clock_policy))
        attempt_id = "d12-compile-" + canonical_digest(
            (namespace, operation_id, draft_ref, budget_ref))[:48]
        request_digest = canonical_digest(
            (namespace, operation_id, draft_ref, budget_ref))
        with store._lock:
            db = store._db
            db.execute("BEGIN IMMEDIATE")
            try:
                from .runtime.d12_installed_graph_schema_v1 import install_d12_compile_attempt_schema_v1
                install_d12_compile_attempt_schema_v1(db)
                previous = db.execute(
                    "SELECT request_digest,attempt_id FROM graph_d12_compile_attempts_v1 "
                    "WHERE bot=? AND persona=? AND operation_id=?",
                    (*namespace.as_tuple, operation_id),
                ).fetchone()
                if previous is not None and previous != (request_digest, attempt_id):
                    raise D12SchemeHold("compile operation identity changed")
                if previous is None:
                    db.execute(
                        "INSERT INTO graph_d12_compile_attempts_v1 VALUES(?,?,?,?,?)",
                        (*namespace.as_tuple, operation_id, request_digest, attempt_id),
                    )
                db.execute("COMMIT")
            except BaseException:
                if db.in_transaction:
                    db.execute("ROLLBACK")
                raise
        with store._lock:
            try:
                prior_original = store._db.execute(
                    "SELECT 1 FROM graph_d12_compilation_operations_v1 "
                    "WHERE bot=? AND persona=? AND operation_id=?",
                    (*namespace.as_tuple, operation_id),
                ).fetchone()
            except sqlite3.OperationalError as exc:
                if "no such table" not in str(exc):
                    raise
                prior_original = None
        if prior_original is None:
            # The Authority begin is idempotent while active; a lost begin ACK
            # must not make this prepared original permanently unavailable.
            permit = port.begin_fence(
                namespace=namespace, authority_namespace=target.authority_namespace,
                holder=self.__holder, generation=authority.activation_generation,
                operation="write", operation_id=attempt_id, expected_anchor=anchor,
            )
            state = "active"
        else:
            lookup = getattr(port, "get_fence_operation", None)
            if not callable(lookup):
                raise UnavailableGuard("D12 compile replay fence reader is unavailable")
            saved_permit, state = lookup(
                namespace=namespace, authority_namespace=target.authority_namespace,
                operation_id=attempt_id)
            if state not in {"active", "finished"}:
                raise UnavailableGuard("D12 compile replay fence state differs")
            permit = saved_permit
        if (permit is None or permit.operation != "write"
                or permit.operation_id != attempt_id
                or permit.pinned_anchor != anchor
                or permit.holder != self.__holder):
            raise UnavailableGuard("D12 compile original fence differs")
        scope = FenceScope(
            namespace, target.authority_namespace, authority.activation_generation,
            "write", attempt_id, permit, anchor, epoch, metadata.graph_revision,
        )
        if state == "finished":
            with store._lock:
                db = store._db
                db.execute("BEGIN")
                try:
                    row = db.execute(
                        "SELECT compiled_digest FROM graph_d12_compilation_operations_v1 "
                        "WHERE bot=? AND persona=? AND operation_id=?",
                        (*namespace.as_tuple, operation_id),
                    ).fetchone()
                    original = (read_compilation_original_for_operation_v1(
                        db, namespace, compiled_digest=row[0]) if row else None)
                finally:
                    db.execute("ROLLBACK")
            if original is None:
                raise UnavailableGuard("D12 compile fence finished without original")
            if self.read_compilation_original_v1(
                    authority, lease,
                    compiled_digest=original.compiled.compiled_digest) != original.compiled:
                raise UnavailableGuard("D12 compile replay Owner read differs")
            return original
        try:
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("D12 compile write permit changed")
            guard, _ = self._owner_binding_in_fence(
                authority, scope, binding.principal, binding,
                owner_session_proof=proof)
            with store._lock:
                db = store._db
                db.execute("BEGIN IMMEDIATE")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise StaleRead("D12 draft graph changed during compilation")
                    draft_key = character_draft_key(namespace)
                    head_key = active_scheme_head_key(namespace)
                    draft_row = db.execute(
                        "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                        (draft_key.token,),
                    ).fetchone()
                    head_row = db.execute(
                        "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                        (head_key.token,),
                    ).fetchone()
                    if (draft_row is None or draft_row[0] < 1
                            or draft_row[2] != 1
                            or head_row is not None and head_row[2] != 1):
                        raise UnavailableGuard("D12 current draft or active head absent")
                    raw_draft = json.loads(draft_row[1])
                    if raw_draft.pop("schema", None) != draft_key.type_name:
                        raise UnavailableGuard("D12 current draft schema differs")
                    draft = CharacterDraft(**raw_draft)
                    if (draft.scope != namespace.persona_id
                            or draft.revision != draft_row[0]):
                        raise UnavailableGuard("D12 current draft revision differs")
                    if head_row is not None:
                        raw_head = json.loads(head_row[1])
                        if raw_head.pop("schema", None) != head_key.type_name:
                            raise UnavailableGuard("D12 current active head invalid")
                        head = ActiveSchemeHeadV1(**raw_head)
                        if (head.scope != namespace.persona_id
                                or head.generation != head_row[0]):
                            raise UnavailableGuard("D12 current active head differs")
                    barrier = db.execute(
                        "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                        "WHERE bot=? AND persona=?", namespace.as_tuple,
                    ).fetchone()
                    if (barrier is None or any(type(value) is not int or value < 0
                                              for value in barrier)):
                        raise UnavailableGuard("D12 current authority epochs absent")
                    frame = D12CurrentCreatorDraftV1(
                        namespace, draft_ref, draft_row[0], draft,
                        head_key.token, head_row[0] if head_row else 0,
                        metadata.graph_revision, barrier[0], barrier[1], True,
                    )
                    budget = get_budget_lease(db, budget_ref)
                    grant = self.__d11_issuer.current_budget_grant(db, budget_ref)
                    if (budget.state != "active"
                            or budget.bot_id != namespace.bot_id
                            or budget.persona_id != namespace.persona_id
                            or grant.lease_id != budget_ref
                            or (grant.bot_id, grant.persona_id) != namespace.as_tuple
                            or "scheme_compile" not in grant.allowed_work_kinds
                            or grant.valid_until_utc <= now):
                        raise D12SchemeHold("current signed compile budget unavailable")
                    budget_digest = canonical_digest({
                        "kind": "signed_budget_authorization_no_paid_cost",
                        "budget_ref": budget_ref, "lease_version": budget.version,
                        "grant": grant,
                    })
                    draft_digest = canonical_digest(frame.draft)
                    receipts = []
                    install_d12_compiled_candidate_store_v1(db)
                    install_scheme_original_store_v1(db)
                    fields_by_domain = {}
                    for path, value in frame.draft.fields.items():
                        domain, separator, _ = path.partition(".")
                        if not separator or domain not in {
                                "d01", "d02", "d03", "d04", "d05", "d06",
                                "d07", "d08", "d09", "d10"}:
                            raise D12SchemeHold("draft field has no D01-D10 owner")
                        fields_by_domain.setdefault(domain, []).append((
                            path, value, frame.draft.field_sources[path],
                        ))
                    if not fields_by_domain:
                        raise D12SchemeHold("empty draft cannot be compiled")
                    for domain, values in sorted(fields_by_domain.items()):
                        frozen = tuple(sorted(values, key=lambda item: item[0]))
                        field_digest = canonical_digest((draft_digest, domain, frozen))
                        candidate = compile_d12_domain_scheme_candidate_v1(
                            namespace=namespace, draft_digest=draft_digest,
                            domain=domain, fields=frozen,
                            field_input_digest=field_digest,
                        )
                        if type(candidate) is D12DomainCompileRejectionV1:
                            raise D12SchemeHold(
                                "domain compiler rejected scheme fields",
                                code="domain_compile_rejected",
                                diagnostics=candidate.diagnostics,
                            )
                        receipts.append(record_d12_domain_candidate_v1(
                            db, namespace, candidate))
                    source_digest = canonical_digest((
                        namespace, draft_ref, frame.draft_revision, draft_digest,
                        frame.active_head_ref, frame.active_head_revision,
                        frame.graph_revision, frame.access_epoch,
                        frame.delete_epoch, budget_ref, budget_digest,
                    ))
                    compiled = D12CompiledSchemeV1(
                        namespace, draft_ref, frame.draft_revision, draft_digest,
                        frame.active_head_ref, frame.active_head_revision,
                        frame.graph_revision, frame.access_epoch,
                        frame.delete_epoch, tuple(receipts), "", "",
                    )
                    digest = compiled_scheme_digest_v1(compiled)
                    compiled = dataclass_replace(
                        compiled, compiled_digest=digest,
                        issuer_seal="w01:" + canonical_digest((
                            operation_id, digest, guard.authorization_head,
                            budget_digest,
                        )),
                    )
                    original = CompilationOriginalV1(
                        operation_id, compiled, source_digest, budget_digest)
                    record_compilation_original_for_operation_v1(db, original)
                    db.execute("COMMIT")
                except BaseException:
                    if db.in_transaction:
                        db.execute("ROLLBACK")
                    raise
            return original
        finally:
            port.finish_fence(
                scope, request_id="finish:" + attempt_id,
                request_digest="sha256:" + canonical_digest({
                    "action": "finish_d12_local_compilation",
                    "operation_id": operation_id, "permit_token": permit.token,
                }),
            )

    def preview_current_scheme_for_operation_v1(
            self, authority: AuthorityContext, lease: object, *,
            operation_id: str, compiled_digest: str, budget_ref: str):
        """Run one supported domain preview with durable D11 cost and Owner proof.

        A claimed preview never executes again. Failed or uncertain execution
        retains its actual bill or ceiling and cannot issue a preview original.
        """
        from dataclasses import asdict as dataclass_asdict
        from uuid import UUID

        from .domains.d12.scheme_command import (
            D12IsolatedPreviewV1, D12PreviewCertificateV1, D12SchemeHold,
        )
        from .runtime.d12_current_preview_plan_v1 import (
            read_current_d12_preview_plan_v1,
        )
        from .domains.d12.d09_current_preview_plan import (
            D12CurrentD09PreviewPlanV1, read_current_d09_preview_plan_v1,
        )
        from .domains.d12.d09_preview import run_d12_d09_preview_v1
        from .domains.d12.d09_preview_original import (
            install_d09_preview_original_v1, read_d09_preview_original_v1,
            record_d09_preview_original_v1,
        )
        from .runtime.d12_preview_behavior_original_v1 import (
            install_d12_preview_behavior_original_v1,
            read_d12_preview_behavior_original_v1,
            record_d12_preview_behavior_original_v1,
        )
        from .runtime.d12_preview_budget_v1 import (
            D12PreviewWorkEvidenceV1, begin_d12_preview_cost_v1,
            claim_d12_preview_run_v1, d12_preview_sandbox_namespace_v1,
            install_d12_preview_budget_schema_v1,
            mark_d12_preview_unknown_v1, read_d12_preview_cost_v1,
            run_d12_preview_once_v1, settle_d12_preview_cost_v1,
        )
        from .runtime.d12_scheme_behavior_preview_v1 import (
            run_d12_scheme_behavior_preview_v1,
        )
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.scheme_original_store_v1 import (
            PreviewOriginalV1, install_scheme_original_store_v1,
            read_compilation_original_for_operation_v1,
            read_preview_original_for_operation_v1,
            record_preview_original_for_operation_v1,
        )

        try:
            parsed_operation = UUID(operation_id)
        except (TypeError, ValueError) as exc:
            raise D12SchemeHold("canonical preview operation required") from exc
        if (parsed_operation.version != 4 or str(parsed_operation) != operation_id
                or type(compiled_digest) is not str or len(compiled_digest) != 64
                or type(budget_ref) is not str or not budget_ref
                or type(authority) is not AuthorityContext
                or authority.issuer_domain != "d12"
                or not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or self.__d11_issuer is None):
            raise D12SchemeHold("installed D12 preview authority unavailable")
        self._authorize(lease, authority, frozenset(("d12", "d11")), owner_read=True)
        binding = self.__owner_leases.get(lease)
        proof = self.__owner_session_proofs.get(lease)
        namespace = authority.namespace
        if (binding is None or proof is None
                or "workbench.experiment" not in binding.capabilities
                or binding.actor != authority.actor
                or binding.namespace != namespace
                or binding.purpose != authority.purpose
                or authority.audience != (binding.audience,)):
            raise D12SchemeHold("current Owner preview capability unavailable")
        store, port = self.__store, self.__content_fence_v2
        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
        target = metadata.requirements
        if (target.namespace != namespace
                or target.activation_generation != authority.activation_generation):
            raise StaleRead("D12 preview activation changed")
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("D12 preview recovery anchor differs")
        now = trusted_upper(port.read_ingress_clock(self.__scene_clock_policy))
        with store._lock:
            try:
                row = store._db.execute(
                    "SELECT preview_seal FROM graph_d12_preview_operations_v1 "
                    "WHERE bot=? AND persona=? AND operation_id=?",
                    (*namespace.as_tuple, operation_id),
                ).fetchone()
            except sqlite3.OperationalError as exc:
                if "no such table" not in str(exc):
                    raise
                row = None
        if row is not None:
            with store._lock:
                db = store._db
                db.execute("BEGIN")
                try:
                    prior = read_preview_original_for_operation_v1(
                        db, namespace, preview_seal=row[0])
                    cost = (read_d12_preview_cost_v1(
                        db, self.__d11_issuer, namespace=namespace,
                        operation_id=operation_id,
                        cost_ref=prior.certificate.actual_cost_receipt_ref,
                    ) if prior is not None else None)
                finally:
                    db.execute("ROLLBACK")
            if (prior is None
                    or prior.certificate.compiled_digest != compiled_digest
                    or cost is None or cost.state != "settled"
                    or cost.intent.budget_ref != budget_ref
                    or self.read_preview_original_v1(
                        authority, lease,
                        preview_seal=prior.certificate.issuer_seal,
                    ) != prior.certificate):
                raise D12SchemeHold("preview replay original differs")
            return prior
        # A fence can finish after the D11 reservation commits but before the
        # one-shot preview run is claimed. Persist a bounded new fence identity
        # for each continuation; the D11 operation and run claim remain the
        # same, so a retry never authorizes a second preview execution.
        with store._lock:
            db = store._db
            db.execute("BEGIN IMMEDIATE")
            try:
                db.execute("""CREATE TABLE IF NOT EXISTS graph_d12_preview_fence_attempts_v1 (
                    bot TEXT NOT NULL, persona TEXT NOT NULL,
                    operation_id TEXT NOT NULL, compiled_digest TEXT NOT NULL,
                    budget_ref TEXT NOT NULL, next_attempt INTEGER NOT NULL,
                    PRIMARY KEY(bot,persona,operation_id))""")
                row = db.execute(
                    "SELECT compiled_digest,budget_ref,next_attempt "
                    "FROM graph_d12_preview_fence_attempts_v1 "
                    "WHERE bot=? AND persona=? AND operation_id=?",
                    (*namespace.as_tuple, operation_id),
                ).fetchone()
                if row is None:
                    attempt = 1
                    db.execute(
                        "INSERT INTO graph_d12_preview_fence_attempts_v1 "
                        "VALUES(?,?,?,?,?,?)",
                        (*namespace.as_tuple, operation_id, compiled_digest,
                         budget_ref, 2),
                    )
                else:
                    if row[:2] != (compiled_digest, budget_ref):
                        raise D12SchemeHold("preview continuation identity differs")
                    attempt = row[2]
                    if type(attempt) is not int or not 1 <= attempt <= 64:
                        raise D12SchemeHold("preview fence retry limit reached")
                    db.execute(
                        "UPDATE graph_d12_preview_fence_attempts_v1 "
                        "SET next_attempt=? WHERE bot=? AND persona=? "
                        "AND operation_id=? AND next_attempt=?",
                        (attempt + 1, *namespace.as_tuple, operation_id, attempt),
                    )
                db.execute("COMMIT")
            except BaseException:
                if db.in_transaction:
                    db.execute("ROLLBACK")
                raise
        attempt_id = "d12-preview-" + canonical_digest(
            (namespace, operation_id, compiled_digest, budget_ref, attempt))[:48]
        permit = port.begin_fence(
            namespace=namespace, authority_namespace=target.authority_namespace,
            holder=self.__holder, generation=authority.activation_generation,
            operation="write", operation_id=attempt_id, expected_anchor=anchor)
        if (permit is None or permit.operation != "write"
                or permit.operation_id != attempt_id
                or permit.pinned_anchor != anchor
                or permit.holder != self.__holder):
            raise UnavailableGuard("D12 preview write permit differs")
        scope = FenceScope(
            namespace, target.authority_namespace, authority.activation_generation,
            "write", attempt_id, permit, anchor, epoch, metadata.graph_revision,
        )

        def transaction(callback):
            with store._lock:
                db = store._db
                db.execute("BEGIN IMMEDIATE")
                try:
                    result = callback(db)
                    db.execute("COMMIT")
                    return result
                except BaseException:
                    if db.in_transaction:
                        db.execute("ROLLBACK")
                    raise

        def current_plan(db):
            if self._v2_graph_stamp(namespace) != (metadata, epoch):
                raise StaleRead("D12 preview graph changed")
            barrier = db.execute(
                "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                "WHERE bot=? AND persona=?", namespace.as_tuple,
            ).fetchone()
            if barrier is None:
                raise UnavailableGuard("D12 preview authority epochs unavailable")
            original = read_compilation_original_for_operation_v1(
                db, namespace, compiled_digest=compiled_digest)
            if original is None or len(original.compiled.domain_receipts) != 1:
                raise D12SchemeHold("preview compilation original unavailable")
            reader = (read_current_d09_preview_plan_v1
                      if original.compiled.domain_receipts[0].domain == "d09"
                      else read_current_d12_preview_plan_v1)
            return reader(
                db, namespace, operation_id=operation_id,
                compiled_digest=compiled_digest,
                graph_revision=metadata.graph_revision,
                access_epoch=barrier[0], delete_epoch=barrier[1],
            )

        try:
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("D12 preview write permit changed")
            guard, _ = self._owner_binding_in_fence(
                authority, scope, binding.principal, binding,
                owner_session_proof=proof)

            def reserve(db):
                plan = current_plan(db)
                install_d12_preview_budget_schema_v1(db)
                if type(plan) is D12CurrentD09PreviewPlanV1:
                    install_d09_preview_original_v1(db)
                else:
                    install_d12_preview_behavior_original_v1(db)
                install_scheme_original_store_v1(db)
                sandbox = d12_preview_sandbox_namespace_v1(namespace, operation_id)
                intent = begin_d12_preview_cost_v1(
                    db, self.__d11_issuer, namespace=namespace,
                    operation_id=operation_id, sandbox_namespace=sandbox,
                    compiled_digest=compiled_digest,
                    source_snapshot_digest=plan.original.compiled.draft_digest,
                    production_revision=plan.graph_revision,
                    budget_ref=budget_ref, ceiling_thread_cpu_ms=1000,
                    max_wall_ms=1000, run_intent_digest=plan.plan_digest,
                    experiment_digest=canonical_digest(plan.spec),
                )
                return plan, intent

            plan, intent = transaction(reserve)

            def claim_or_read(db):
                current = current_plan(db)
                if current.plan_digest != plan.plan_digest:
                    raise StaleRead("D12 preview plan changed before claim")
                claimed = claim_d12_preview_run_v1(
                    db, self.__d11_issuer, namespace=namespace,
                    operation_id=operation_id)
                return claimed, read_d12_preview_cost_v1(
                    db, self.__d11_issuer, namespace=namespace,
                    operation_id=operation_id)

            claimed, cost_state = transaction(claim_or_read)
            if claimed is not None:
                produced = []

                def fixed_domain_preview():
                    with store._lock:
                        before = self._v2_graph_stamp(namespace)[0].graph_revision
                    report = (run_d12_d09_preview_v1(
                        plan.spec, plan.baseline, plan.candidate)
                        if type(plan) is D12CurrentD09PreviewPlanV1 else
                        run_d12_scheme_behavior_preview_v1(
                            plan.spec, plan.baseline, plan.candidate))
                    produced.append(report)
                    with store._lock:
                        after = self._v2_graph_stamp(namespace)[0].graph_revision
                    return D12PreviewWorkEvidenceV1(
                        compiled_digest, intent.sandbox_namespace,
                        plan.original.compiled.draft_digest, before, after,
                        (), (), (),
                    )

                execution = run_d12_preview_once_v1(
                    self.__d11_issuer, claimed, max_wall_ms=claimed.max_wall_ms,
                    run_preview=fixed_domain_preview)

                def settle(db):
                    # Settle real CPU even when Owner or graph became stale.
                    receipt = settle_d12_preview_cost_v1(
                        db, self.__d11_issuer, namespace=namespace,
                        operation_id=operation_id, report=execution)
                    if (receipt.status == "settled" and produced
                            and produced[0].status == "isolated_behavior_only"):
                        seal = canonical_digest((
                            operation_id, compiled_digest, receipt.cost_ref,
                            plan.plan_digest, produced[0].report_digest,
                        ))
                        record_behavior = (
                            record_d09_preview_original_v1
                            if type(plan) is D12CurrentD09PreviewPlanV1 else
                            record_d12_preview_behavior_original_v1)
                        record_behavior(
                            db, namespace, operation_id=operation_id,
                            compiled_digest=compiled_digest, preview_seal=seal,
                            cost_ref=receipt.cost_ref,
                            plan_digest=plan.plan_digest, report=produced[0],
                        )
                    return receipt

                cost_receipt = transaction(settle)
            else:
                if cost_state.state == "running":
                    transaction(lambda db: mark_d12_preview_unknown_v1(
                        db, self.__d11_issuer, namespace=namespace,
                        operation_id=operation_id))
                    raise D12SchemeHold("preview result unknown; original ceiling retained")
                cost_receipt = cost_state.receipt
            if cost_receipt is None or cost_receipt.status != "settled":
                raise D12SchemeHold("D12 preview cost did not settle successfully")
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("D12 preview write permit changed")
            current_guard, _ = self._owner_binding_in_fence(
                authority, scope, binding.principal, binding,
                owner_session_proof=proof)
            if current_guard != guard:
                raise UnavailableGuard("D12 preview Owner guard changed")

            def publish(db):
                current = current_plan(db)
                if current.plan_digest != plan.plan_digest:
                    raise StaleRead("D12 preview current plan changed")
                cost = read_d12_preview_cost_v1(
                    db, self.__d11_issuer, namespace=namespace,
                    operation_id=operation_id, cost_ref=cost_receipt.cost_ref)
                if cost is None or cost.receipt != cost_receipt:
                    raise UnavailableGuard("D12 preview cost original changed")
                behavior_reader = (
                    read_d09_preview_original_v1
                    if type(current) is D12CurrentD09PreviewPlanV1 else
                    read_d12_preview_behavior_original_v1)
                behavior = behavior_reader(
                    db, namespace, operation_id=operation_id)
                if (behavior is None or behavior[0] != compiled_digest
                        or behavior[2] != cost_receipt.cost_ref
                        or behavior[3] != plan.plan_digest
                        or behavior[4].spec != current.spec):
                    raise UnavailableGuard("D12 preview behavior original changed")
                seal = behavior[1]
                isolated = D12IsolatedPreviewV1(
                    compiled_digest, intent.sandbox_namespace,
                    current.original.compiled.draft_digest,
                    current.graph_revision, current.graph_revision,
                    (), (), (), cost_receipt.cost_ref,
                )
                certificate = D12PreviewCertificateV1(
                    compiled_digest, intent.sandbox_namespace,
                    cost_receipt.cost_ref, seal,
                )
                original = PreviewOriginalV1(
                    operation_id, certificate, isolated,
                    current.plan_digest, canonical_digest(cost_receipt),
                    canonical_digest(isolated),
                )
                record_preview_original_for_operation_v1(
                    db, current.original.compiled, original)
                return original

            return transaction(publish)
        finally:
            port.finish_fence(
                scope, request_id="finish:" + attempt_id,
                request_digest="sha256:" + canonical_digest({
                    "action": "finish_d12_preview",
                    "operation_id": attempt_id, "permit_token": permit.token,
                }),
            )

    def adopt_current_scheme_for_operation_v1(
            self, authority: AuthorityContext, lease: object, *,
            operation_id: str, compiled_digest: str, preview_seal: str):
        """Atomically adopt one paid, current D09-only scheme for this Owner."""
        from uuid import UUID

        from .domains.d12.d09_current_preview_plan import (
            read_current_d09_preview_plan_v1,
        )
        from .domains.d12.d09_preview import run_d12_d09_preview_v1
        from .domains.d12.d09_preview_original import (
            read_d09_preview_original_v1,
        )
        from .domains.d12.scheme_command import (
            D12SchemeAdoptionIntentV1, D12SchemeAdoptionReceiptV1,
            D12SchemeHold,
        )
        from .domains.d12.scheme_installation import (
            scheme_adoption_graph_candidate_v1, scheme_adoption_receipt_v1,
        )
        from .domains.d12.types import active_scheme_head_key
        from .runtime.d12_preview_budget_v1 import read_d12_preview_cost_v1
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.scheme_original_store_v1 import (
            read_compilation_original_for_operation_v1,
            read_preview_original_for_operation_v1,
        )
        from .runtime.scheme_port_v1 import (
            D12SchemeAdoptionCandidateV1,
            read_current_scheme_adoption_candidate_v1,
        )

        try:
            parsed = UUID(operation_id)
        except (TypeError, ValueError) as exc:
            raise D12SchemeHold("canonical adoption operation required") from exc
        if (parsed.version != 4 or str(parsed) != operation_id
                or type(compiled_digest) is not str or len(compiled_digest) != 64
                or type(preview_seal) is not str or len(preview_seal) != 64
                or type(authority) is not AuthorityContext
                or authority.issuer_domain != "d12"
                or not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or self.__d11_issuer is None):
            raise D12SchemeHold("installed D12 adoption authority unavailable")
        self._authorize(lease, authority, frozenset(("d12",)), owner_read=True)
        binding = self.__owner_leases.get(lease)
        owner_proof = self.__owner_session_proofs.get(lease)
        namespace = authority.namespace
        if (binding is None or owner_proof is None
                or "workbench.activate" not in binding.capabilities
                or binding.actor != authority.actor
                or binding.namespace != namespace
                or binding.purpose != authority.purpose
                or authority.audience != (binding.audience,)):
            raise D12SchemeHold("current Owner adoption capability unavailable")
        store, port = self.__store, self.__content_fence_v2
        request_digest = canonical_digest((
            namespace, operation_id, compiled_digest, preview_seal))
        attempt_id = "d12-adopt-" + request_digest[:48]

        def install(db):
            from .runtime.d12_installed_graph_schema_v1 import install_d12_adoption_schema_v1
            install_d12_adoption_schema_v1(db)

        def previous(db):
            row = db.execute(
                "SELECT request_digest,attempt_id,receipt_json,receipt_sha256 "
                "FROM graph_d12_adoption_operations_v1 WHERE bot=? AND persona=? "
                "AND operation_id=?", (*namespace.as_tuple, operation_id),
            ).fetchone()
            if row is None:
                return None
            if row[:2] != (request_digest, attempt_id):
                raise D12SchemeHold("adoption operation identity changed")
            try:
                raw = json.loads(row[2])
                ns = raw.pop("namespace")
                receipt = D12SchemeAdoptionReceiptV1(
                    raw["operation_id"], NamespaceId(**ns),
                    raw["compiled_digest"], raw["previous_head_ref"],
                    raw["previous_head_revision"], raw["active_head_ref"],
                    raw["active_head_revision"], raw["graph_revision"],
                    raw["status"],
                )
            except (TypeError, ValueError, KeyError) as exc:
                raise D12SchemeHold("adoption receipt is malformed") from exc
            encoded = json.dumps(asdict(receipt), sort_keys=True,
                                 separators=(",", ":"), ensure_ascii=False)
            head = db.execute(
                "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                (active_scheme_head_key(namespace).token,),
            ).fetchone()
            try:
                head_value = json.loads(head[1]) if head is not None else None
            except (TypeError, ValueError) as exc:
                raise D12SchemeHold("committed adoption head is malformed") from exc
            if (receipt.namespace != namespace or receipt.operation_id != operation_id
                    or receipt.compiled_digest != compiled_digest
                    or row[2] != encoded or row[3] != canonical_digest(receipt)
                    or head is None or head[0] != receipt.active_head_revision
                    or head[2] != 1 or type(head_value) is not dict
                    or head_value.get("compiled_digest") != compiled_digest
                    or head_value.get("adopted_operation_id") != operation_id):
                raise D12SchemeHold("committed adoption original differs")
            return receipt

        with store._lock:
            db = store._db
            db.execute("BEGIN IMMEDIATE")
            try:
                install(db)
                committed = previous(db)
                db.execute("COMMIT")
            except BaseException:
                if db.in_transaction:
                    db.execute("ROLLBACK")
                raise
        metadata, epoch = self._v2_graph_stamp(namespace)
        target = metadata.requirements
        if (target.namespace != namespace
                or target.activation_generation != authority.activation_generation):
            raise StaleRead("D12 adoption activation changed")
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("D12 adoption recovery anchor differs")
        if committed is not None:
            lookup = getattr(port, "get_fence_operation", None)
            if not callable(lookup):
                raise UnavailableGuard("D12 adoption replay fence reader unavailable")
            permit, state = lookup(
                namespace=namespace, authority_namespace=target.authority_namespace,
                operation_id=attempt_id)
            if (permit is None or state not in {"active", "finished"}
                    or permit.operation != "write"
                    or permit.operation_id != attempt_id
                    or permit.pinned_anchor != anchor):
                raise UnavailableGuard("D12 adoption replay fence differs")
            scope = FenceScope(
                namespace, target.authority_namespace,
                authority.activation_generation, "write", attempt_id,
                permit, anchor, epoch, metadata.graph_revision)
            if state == "active":
                port.finish_fence(
                    scope, request_id="finish:" + attempt_id,
                    request_digest="sha256:" + canonical_digest({
                        "action": "finish_d12_adoption",
                        "operation_id": attempt_id,
                        "permit_token": permit.token,
                    }),
                )
            return committed

        now = trusted_upper(port.read_ingress_clock(self.__scene_clock_policy))
        permit = port.begin_fence(
            namespace=namespace, authority_namespace=target.authority_namespace,
            holder=self.__holder, generation=authority.activation_generation,
            operation="write", operation_id=attempt_id, expected_anchor=anchor)
        if (permit is None or permit.operation != "write"
                or permit.operation_id != attempt_id
                or permit.pinned_anchor != anchor
                or permit.holder != self.__holder):
            raise UnavailableGuard("D12 adoption write permit differs")
        scope = FenceScope(
            namespace, target.authority_namespace, authority.activation_generation,
            "write", attempt_id, permit, anchor, epoch, metadata.graph_revision)
        try:
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("D12 adoption write permit changed")
            guard, _ = self._owner_binding_in_fence(
                authority, scope, binding.principal, binding,
                owner_session_proof=owner_proof)
            with store._lock:
                db = store._db
                db.execute("BEGIN IMMEDIATE")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise StaleRead("D12 adoption graph changed")
                    barrier = db.execute(
                        "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                        "WHERE bot=? AND persona=?", namespace.as_tuple,
                    ).fetchone()
                    if barrier is None:
                        raise UnavailableGuard("D12 adoption epochs unavailable")
                    compilation = read_compilation_original_for_operation_v1(
                        db, namespace, compiled_digest=compiled_digest)
                    preview = read_preview_original_for_operation_v1(
                        db, namespace, preview_seal=preview_seal)
                    if (compilation is None or preview is None
                            or len(compilation.compiled.domain_receipts) != 1
                            or compilation.compiled.domain_receipts[0].domain != "d09"):
                        raise D12SchemeHold("D09-only paid adoption originals unavailable")
                    plan = read_current_d09_preview_plan_v1(
                        db, namespace, operation_id=preview.operation_id,
                        compiled_digest=compiled_digest,
                        graph_revision=metadata.graph_revision,
                        access_epoch=barrier[0], delete_epoch=barrier[1])
                    behavior = read_d09_preview_original_v1(
                        db, namespace, operation_id=preview.operation_id)
                    cost = read_d12_preview_cost_v1(
                        db, self.__d11_issuer, namespace=namespace,
                        operation_id=preview.operation_id,
                        cost_ref=preview.certificate.actual_cost_receipt_ref)
                    expected_report = run_d12_d09_preview_v1(
                        plan.spec, plan.baseline, plan.candidate)
                    if (behavior is None or cost is None or cost.state != "settled"
                            or behavior != (compiled_digest, preview_seal,
                                            cost.receipt.cost_ref, plan.plan_digest,
                                            expected_report)
                            or preview.source_input_digest != plan.plan_digest
                            or preview.budget_receipt_digest
                               != canonical_digest(cost.receipt)
                            or preview.isolated_result.production_revision_before
                               != metadata.graph_revision
                            or preview.isolated_result.production_revision_after
                               != metadata.graph_revision):
                        raise D12SchemeHold("D09 preview report or real cost changed")
                    compiled = compilation.compiled
                    intent = D12SchemeAdoptionIntentV1(
                        operation_id, namespace, compiled_digest,
                        compiled.draft_ref, compiled.draft_revision,
                        compiled.active_head_ref, compiled.active_head_revision,
                        compiled.graph_revision, compiled.access_epoch,
                        compiled.delete_epoch, preview_seal,
                        "w01:" + canonical_digest((request_digest, guard.authorization_head)),
                    )
                    adoption = read_current_scheme_adoption_candidate_v1(
                        db, namespace, compiled, intent,
                        expected_graph_epoch=epoch.revision,
                        expected_access_epoch=barrier[0],
                        expected_delete_epoch=barrier[1])
                    if type(adoption) is not D12SchemeAdoptionCandidateV1:
                        raise D12SchemeHold("D09 adoption current scheme changed")
                    graph_candidate = scheme_adoption_graph_candidate_v1(
                        adoption, occurred_at=now)
                    def record(_db, graph_receipt):
                        receipt = scheme_adoption_receipt_v1(adoption, graph_receipt)
                        replacement = replace(
                            target, deletion_seq=anchor.deletion_seq,
                            deletion_digest=anchor.deletion_digest,
                            execution_seq=anchor.execution_seq,
                            execution_digest=anchor.execution_digest,
                            revocation_epoch=anchor.revocation_epoch)
                        store.cas_graph_recovery_metadata(
                            metadata, replacement,
                            _capability=self.__graph_capability)
                        encoded = json.dumps(asdict(receipt), sort_keys=True,
                                             separators=(",", ":"), ensure_ascii=False)
                        db.execute(
                            "INSERT INTO graph_d12_adoption_operations_v1 "
                            "VALUES(?,?,?,?,?,?,?)",
                            (*namespace.as_tuple, operation_id, request_digest,
                             attempt_id, encoded, canonical_digest(receipt)),
                        )
                    graph_receipt = GraphStore._graph_commit_in_transaction(
                        store, graph_candidate, _receipt_hook=record,
                        _capability=self.__graph_capability)
                    if graph_receipt.status != "committed":
                        raise D12SchemeHold("D09 active head CAS did not commit")
                    receipt = previous(db)
                    db.execute("COMMIT")
                except BaseException:
                    if db.in_transaction:
                        db.execute("ROLLBACK")
                    raise
            return receipt
        finally:
            port.finish_fence(
                scope, request_id="finish:" + attempt_id,
                request_digest="sha256:" + canonical_digest({
                    "action": "finish_d12_adoption",
                    "operation_id": attempt_id, "permit_token": permit.token,
                }),
            )

    def read_preview_original_v1(
            self, authority: AuthorityContext, lease: object, *,
            preview_seal: str):
        return self._read_current_preview_original_v1(
            authority, lease, preview_seal=preview_seal,
            return_report=False)

    def read_current_preview_report_v1(
            self, authority: AuthorityContext, lease: object, *,
            preview_seal: str):
        """Read the original typed D07/D09 experiment under its current fence."""
        return self._read_current_preview_original_v1(
            authority, lease, preview_seal=preview_seal,
            return_report=True)

    def _read_current_preview_original_v1(
            self, authority: AuthorityContext, lease: object, *,
            preview_seal: str, return_report: bool):
        """Read a settled supported preview with its current and paid originals."""
        from .domains.d12.scheme_command import D12SchemeHold
        from .domains.d12.d09_current_preview_plan import (
            D12CurrentD09PreviewPlanV1, read_current_d09_preview_plan_v1,
        )
        from .domains.d12.d09_preview_original import (
            read_d09_preview_original_v1,
        )
        from .runtime.d12_current_preview_plan_v1 import (
            read_current_d12_preview_plan_v1,
        )
        from .runtime.d12_preview_behavior_original_v1 import (
            read_d12_preview_behavior_original_v1,
        )
        from .runtime.d12_preview_budget_v1 import read_d12_preview_cost_v1
        from .runtime.scheme_original_store_v1 import (
            read_compilation_original_for_operation_v1,
            read_preview_original_for_operation_v1,
        )

        if (type(authority) is not AuthorityContext
                or authority.issuer_domain != "d12"
                or type(preview_seal) is not str or not preview_seal
                or not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or self.__d11_issuer is None):
            raise UnavailableGuard("D12 preview original reader unavailable")
        self._authorize(lease, authority, frozenset(("d12",)), owner_read=True)
        binding = self.__owner_leases.get(lease)
        proof = self.__owner_session_proofs.get(lease)
        if (binding is None or proof is None
                or not {"workbench.experiment", "workbench.activate"}
                    .intersection(binding.capabilities)
                or binding.actor != authority.actor
                or binding.namespace != authority.namespace
                or binding.purpose != authority.purpose
                or authority.audience != (binding.audience,)):
            raise UnavailableGuard("current signed D12 preview read unavailable")

        def reader():
            namespace = authority.namespace
            db = self.__store._db
            db.execute("BEGIN")
            try:
                original = read_preview_original_for_operation_v1(
                    db, namespace, preview_seal=preview_seal)
                if original is None:
                    return None
                metadata, _ = self._v2_graph_stamp(namespace)
                barrier = db.execute(
                    "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                    "WHERE bot=? AND persona=?", namespace.as_tuple,
                ).fetchone()
                if barrier is None:
                    raise UnavailableGuard("D12 current epochs unavailable")
                compilation = read_compilation_original_for_operation_v1(
                    db, namespace,
                    compiled_digest=original.certificate.compiled_digest)
                if (compilation is None
                        or len(compilation.compiled.domain_receipts) != 1):
                    raise D12SchemeHold("preview compilation original changed")
                plan_reader = (read_current_d09_preview_plan_v1
                    if compilation.compiled.domain_receipts[0].domain == "d09"
                    else read_current_d12_preview_plan_v1)
                plan = plan_reader(
                    db, namespace, operation_id=original.operation_id,
                    compiled_digest=original.certificate.compiled_digest,
                    graph_revision=metadata.graph_revision,
                    access_epoch=barrier[0], delete_epoch=barrier[1],
                )
                behavior_reader = (read_d09_preview_original_v1
                    if type(plan) is D12CurrentD09PreviewPlanV1 else
                    read_d12_preview_behavior_original_v1)
                behavior = behavior_reader(
                    db, namespace, operation_id=original.operation_id)
                cost = read_d12_preview_cost_v1(
                    db, self.__d11_issuer, namespace=namespace,
                    operation_id=original.operation_id,
                    cost_ref=original.certificate.actual_cost_receipt_ref,
                )
                if (behavior is None or cost is None or cost.state != "settled"
                        or behavior[0] != original.certificate.compiled_digest
                        or behavior[1] != preview_seal
                        or behavior[2] != cost.receipt.cost_ref
                        or behavior[3] != plan.plan_digest
                        or behavior[4].spec != plan.spec
                        or original.source_input_digest != plan.plan_digest
                        or original.budget_receipt_digest
                           != canonical_digest(cost.receipt)
                        or preview_seal != canonical_digest((
                            original.operation_id,
                            original.certificate.compiled_digest,
                            cost.receipt.cost_ref, plan.plan_digest,
                            behavior[4].report_digest,
                        ))):
                    raise D12SchemeHold("current paid preview original changed")
                return behavior[4] if return_report else original.certificate
            finally:
                db.execute("ROLLBACK")

        return self._read_v2(
            authority, reader, owner_binding=binding,
            owner_session_proof=proof,
        )

    def read_compilation_original_v1(
            self, authority: AuthorityContext, lease: object, *,
            compiled_digest: str):
        """Read W01's immutable compilation only under the signed Owner fence."""
        from .runtime.scheme_original_store_v1 import (
            read_compilation_original_for_operation_v1,
        )

        if (type(authority) is not AuthorityContext
                or authority.issuer_domain != "d12"
                or not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None):
            raise UnavailableGuard("D12 compilation original reader unavailable")
        self._authorize(lease, authority, frozenset(("d12",)), owner_read=True)
        binding = self.__owner_leases.get(lease)
        proof = self.__owner_session_proofs.get(lease)
        if (binding is None or proof is None
                or "workbench.compile" not in binding.capabilities
                or binding.actor != authority.actor
                or binding.namespace != authority.namespace
                or binding.purpose != authority.purpose
                or authority.audience != (binding.audience,)):
            raise UnavailableGuard("current signed D12 Owner read unavailable")

        def reader():
            db = self.__store._db
            db.execute("BEGIN")
            try:
                original = read_compilation_original_for_operation_v1(
                    db, authority.namespace, compiled_digest=compiled_digest)
                return original.compiled if original is not None else None
            except sqlite3.OperationalError as exc:
                if "no such table" not in str(exc):
                    raise
                return None
            finally:
                db.execute("ROLLBACK")

        return self._read_v2(
            authority, reader, owner_binding=binding, owner_session_proof=proof)

    def revoke_source_access_v1(
            self, authority: AuthorityContext, lease: object, request,
    ) -> SourceAccessRevocationReceiptV1:
        """Withdraw one D06 access head and advance its barrier in one Owner write."""
        from .authority_service.v2_contract import FencePermitV2, from_wire, to_wire
        from .domains.d06 import D06DomainAdapter
        from .domains.d06.source_access_revocation import (
            REVOCATION_PHASE, SourceAccessRevocationRequest,
            compile_source_access_revocation, revocation_operation_id,
        )
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime_contracts import (
            CommandEnvelope, OperationIdentity, RUNTIME_SCHEMA,
        )

        store, port = self.__store, self.__content_fence_v2
        if (type(request) is not SourceAccessRevocationRequest
                or type(authority) is not AuthorityContext
                or not isinstance(store, ProductionGraphStore) or port is None):
            raise UnavailableGuard("installed source revocation authorities absent; HOLD")
        self._authorize(lease, authority, frozenset({"d06"}), owner_read=True)
        binding = self.__owner_leases.get(lease)
        proof = self.__owner_session_proofs.get(lease)
        namespace = authority.namespace
        if (binding is None or proof is None
                or "workbench.correct" not in binding.capabilities
                or authority.issuer_domain != "d12" or authority.purpose != "audit"
                or authority.audience != ("owner",)
                or request.owner_actor != authority.actor
                or binding.actor != authority.actor
                or binding.namespace != namespace
                or binding.purpose != authority.purpose
                or binding.audience != "owner"):
            raise AuthorityDenied("current Owner correction grant required")
        operation_id = revocation_operation_id(namespace, request)
        request_json = canonical_json(asdict(request))
        request_digest = "sha256:" + canonical_digest({
            "namespace": namespace.as_tuple, "request": asdict(request),
        })
        attempt_id = "d06-revoke-" + canonical_digest({
            "namespace": namespace.as_tuple, "operation_id": operation_id,
            "request_digest": request_digest,
        })[:48]
        source = source_key(*namespace.as_tuple, request.source_id)
        access = access_key(*namespace.as_tuple, request.source_id)
        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
        target = metadata.requirements
        if (target.namespace != namespace
                or target.activation_generation != authority.activation_generation):
            raise UnavailableGuard("revocation activation or recovery identity differs")
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("revocation recovery anchor differs")
        anchor_json = canonical_json(asdict(anchor))
        requirements_json = canonical_json(asdict(target))
        try:
            now = trusted_upper(port.read_ingress_clock(self.__scene_clock_policy))
        except Exception as exc:
            raise UnavailableGuard("revocation trusted clock unavailable; HOLD") from exc
        if request.recorded_at > now:
            raise AuthorityDenied("revocation time exceeds trusted clock")

        def saved_row(db):
            return db.execute(
                "SELECT operation_id,request_digest,request_json,attempt_id,"
                "anchor_json,requirements_json,pre_graph_revision,pre_graph_epoch,"
                "permit_json,finish_request_id,finish_request_digest,receipt_json,"
                "rejected FROM graph_source_access_revocations_v1 "
                "WHERE bot=? AND persona=? AND request_id=?",
                namespace.as_tuple + (request.request_id,),
            ).fetchone()

        with store._lock:
            db = store._db
            db.execute("BEGIN IMMEDIATE")
            try:
                row = saved_row(db)
                identity = (operation_id, request_digest, request_json, attempt_id)
                if row is None:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise StaleRead("revocation graph changed before intent")
                    db.execute(
                        "INSERT INTO graph_source_access_revocations_v1"
                        "(bot,persona,request_id,operation_id,request_digest,"
                        "request_json,attempt_id,anchor_json,requirements_json,"
                        "pre_graph_revision,pre_graph_epoch) "
                        "VALUES(?,?,?,?,?,?,?,?,?,?,?)",
                        namespace.as_tuple + (request.request_id, *identity,
                                              anchor_json, requirements_json,
                                              metadata.graph_revision, epoch.revision),
                    )
                    row = saved_row(db)
                elif row[:4] != identity:
                    raise EventConflict("revocation request ID has another identity")
                db.execute("COMMIT")
            except BaseException:
                if db.in_transaction:
                    db.execute("ROLLBACK")
                raise
        if row[4:6] != (anchor_json, requirements_json):
            raise UnavailableGuard("revocation original Authority anchor changed; HOLD")
        if (row[6:8] != (metadata.graph_revision, epoch.revision)
                and row[11] is None):
            raise UnavailableGuard("revocation original graph stamp changed; HOLD")

        def original_permit():
            try:
                permit, state = port.get_fence_operation(
                    namespace=namespace,
                    authority_namespace=target.authority_namespace,
                    operation_id=attempt_id)
            except Exception:
                if row[8] is not None:
                    raise UnavailableGuard("revocation saved permit unavailable; HOLD")
                try:
                    permit = port.begin_fence(
                        namespace=namespace,
                        authority_namespace=target.authority_namespace,
                        holder=self.__holder,
                        generation=authority.activation_generation,
                        operation="write", operation_id=attempt_id,
                        expected_anchor=anchor, retain_on_unknown=True)
                    state = "active"
                except Exception:
                    try:
                        permit, state = port.get_fence_operation(
                            namespace=namespace,
                            authority_namespace=target.authority_namespace,
                            operation_id=attempt_id)
                    except Exception as exc:
                        raise UnavailableGuard(
                            "revocation original begin outcome unknown; HOLD") from exc
            if (type(permit) is not FencePermitV2 or state not in {"active", "finished"}
                    or permit.operation != "write" or permit.operation_id != attempt_id
                    or permit.holder != self.__holder or permit.pinned_anchor != anchor
                    or permit.subject != port.installation_grant.subject
                    or permit.authority_id != port.installation_grant.authority_id):
                raise UnavailableGuard("revocation original write permit differs; HOLD")
            return permit, state

        permit, state = original_permit()
        finish_id = "finish:" + attempt_id
        finish_digest = "sha256:" + canonical_digest({
            "action": "finish_source_access_revocation",
            "operation_id": operation_id, "permit_token": permit.token,
        })
        permit_json = canonical_json(to_wire(permit))
        original_epoch = NamespaceEpoch(*namespace.as_tuple, row[7])
        original_scope = FenceScope(
            namespace, target.authority_namespace, authority.activation_generation,
            "write", attempt_id, permit, anchor, original_epoch, row[6])
        if row[12]:
            if row[8:11] != (permit_json, finish_id, finish_digest):
                raise UnavailableGuard("revocation rejected permit differs; HOLD")
            if state == "active":
                port.finish_fence(
                    original_scope, request_id="abort:" + attempt_id,
                    request_digest="sha256:" + canonical_digest({
                        "action": "reject_source_access_revocation",
                        "operation_id": operation_id, "permit_token": permit.token,
                    }))
            raise UnavailableGuard("revocation original attempt rejected; HOLD")
        with store._lock:
            db = store._db
            db.execute("BEGIN IMMEDIATE")
            try:
                current = saved_row(db)
                if current[:8] != row[:8] or current[12]:
                    raise UnavailableGuard("revocation original intent changed; HOLD")
                if current[8] is None:
                    db.execute(
                        "UPDATE graph_source_access_revocations_v1 SET "
                        "permit_json=?,finish_request_id=?,finish_request_digest=? "
                        "WHERE bot=? AND persona=? AND request_id=? AND permit_json IS NULL",
                        (permit_json, finish_id, finish_digest,
                         *namespace.as_tuple, request.request_id),
                    )
                elif current[8:11] != (permit_json, finish_id, finish_digest):
                    raise UnavailableGuard("revocation saved permit differs; HOLD")
                row = saved_row(db)
                db.execute("COMMIT")
            except BaseException:
                if db.in_transaction:
                    db.execute("ROLLBACK")
                raise
        if row[11] is not None:
            payload = json.loads(row[11])
            receipt = SourceAccessRevocationReceiptV1(
                NamespaceId(**payload["namespace"]),
                **{key: value for key, value in payload.items() if key != "namespace"},
            )
            if (receipt.namespace != namespace or receipt.operation_id != operation_id
                    or receipt.request_digest != request_digest
                    or receipt.source_id != request.source_id):
                raise UnavailableGuard("revocation saved receipt differs; HOLD")
            if state == "active":
                port.finish_fence(original_scope, request_id=finish_id,
                                  request_digest=finish_digest)
            return receipt
        if state != "active":
            raise UnavailableGuard("revocation finished without graph receipt; HOLD")
        scope = original_scope
        def reject_no_commit():
            with store._lock:
                db = store._db
                db.execute("BEGIN IMMEDIATE")
                try:
                    db.execute(
                        "UPDATE graph_source_access_revocations_v1 SET rejected=1 "
                        "WHERE bot=? AND persona=? AND request_id=? "
                        "AND receipt_json IS NULL AND rejected=0",
                        namespace.as_tuple + (request.request_id,),
                    )
                    if db.execute("SELECT changes()").fetchone() != (1,):
                        raise UnavailableGuard("revocation rejection state differs; HOLD")
                    db.execute("COMMIT")
                except BaseException:
                    if db.in_transaction:
                        db.execute("ROLLBACK")
                    raise
            port.finish_fence(
                scope, request_id="abort:" + attempt_id,
                request_digest="sha256:" + canonical_digest({
                    "action": "reject_source_access_revocation",
                    "operation_id": operation_id, "permit_token": permit.token,
                }))

        if port.validate_fence(scope) != permit:
            raise UnavailableGuard("revocation write fence changed; HOLD")
        try:
            self._owner_binding_in_fence(
                authority, scope, binding.principal, binding,
                owner_session_proof=proof)
        except (AuthorityDenied, StaleRead, UnavailableGuard):
            reject_no_commit()
            raise

        with store._lock:
            db = store._db
            db.execute("BEGIN IMMEDIATE")
            commit_started = False
            try:
                if self._v2_graph_stamp(namespace) != (metadata, epoch):
                    raise StaleRead("revocation graph changed before commit")
                if saved_row(db) != row:
                    raise UnavailableGuard("revocation original intent changed; HOLD")
                atoms = []
                for key in (source, access):
                    current = db.execute(
                        "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                        (key.token,),
                    ).fetchone()
                    atoms.append(
                        GraphAtom(key, current[0], json.loads(current[1]),
                                  bool(current[2])) if current else
                        GraphAtom(key, 0, {}, False))
                snapshot = GraphSnapshot(tuple(atoms), (epoch,))
                source_atom, access_atom = snapshot.atoms
                if (source_atom.revision < 1 or not source_atom.valid
                        or access_atom.revision < 1 or not access_atom.valid):
                    raise UnavailableGuard("revocation source or access absent; HOLD")
                original = SourceRecord.from_dict(source_atom.value)
                epochs = db.execute(
                    "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                    "WHERE bot=? AND persona=?", namespace.as_tuple,
                ).fetchone()
                if epochs is None:
                    raise UnavailableGuard("revocation authority epochs absent; HOLD")
                inputs = (source.token, access.token, f"owner:{authority.actor}",
                          f"revocation-request:{request.request_id}")
                identity = OperationIdentity(
                    request.request_id, operation_id, attempt_id,
                    REVOCATION_PHASE, operation_id,
                    canonical_digest({"input_refs": list(inputs)}),
                )
                d06_authority = replace(authority, issuer_domain="d06")
                guard = VersionGuard(
                    (GraphVersion(source, source_atom.revision),
                     GraphVersion(access, access_atom.revision)), (),
                    epochs[0], epochs[1], store._registry.catalogue_hash,
                    self._version(db, namespace, "scheme", "current"),
                    self._version(db, namespace, "operator", "current"),
                    self._version(db, namespace, "policy", "current"),
                    (), (), (),
                )
                family, reality, eligibility = {
                    "observed": ("observed", "external_observation", "qualified"),
                    "reported": ("reported", "external_report", "qualified"),
                    "authored": ("authored", "authored_content", "ineligible"),
                    "internal": ("derived", "inference", "ineligible"),
                    "simulated": ("simulated", "simulation", "ineligible"),
                }[original.source_kind]
                qualification = SourceQualification(
                    (source.token,), family, original.occurred_at,
                    original.recorded_at, reality, eligibility, None,
                    "not_applicable",
                )
                envelope = CommandEnvelope(
                    RUNTIME_SCHEMA, identity, d06_authority, guard, qualification,
                    inputs, authority.capability_ref, now, now,
                    "owner-source-access-revocation", (request.request_id,),
                )
                candidate = compile_source_access_revocation(
                    D06DomainAdapter(namespace), envelope, request, snapshot)
                if (candidate.operation_id != operation_id
                        or candidate.proposal.required_bundle_parts
                        or candidate.proposal.typed_writes != (
                            GraphWrite(access, {**access_atom.value,
                                                "status": "withdrawn",
                                                "recorded_at": float(request.recorded_at)},
                                       (source,)),)):
                    raise UnavailableGuard("D06 revocation candidate differs; HOLD")
                graph_candidate = GraphCandidate(
                    Event(Scope(*namespace.as_tuple, "source-access-revocation"),
                          operation_id, now, "d06.source_access_revoked",
                          {"request_digest": request_digest,
                           "source_token": source.token}),
                    (candidate.source_version, candidate.access_version),
                    candidate.proposal.typed_writes, (epoch,),
                )
                sealed = []

                def seal(db, graph_receipt):
                    if (graph_receipt.status != "committed"
                            or graph_receipt.revisions !=
                            (GraphVersion(access, access_atom.revision + 1),)
                            or graph_receipt.epoch.revision != epoch.revision + 1):
                        raise UnavailableGuard("revocation graph seal differs; HOLD")
                    store.cas_graph_recovery_metadata(
                        metadata, metadata.requirements,
                        _capability=self.__graph_capability)
                    db.execute(
                        "UPDATE graph_authority_epochs SET access_epoch=access_epoch+1 "
                        "WHERE bot=? AND persona=? AND access_epoch=? "
                        "AND delete_epoch=?",
                        namespace.as_tuple + epochs,
                    )
                    if db.execute("SELECT changes()").fetchone() != (1,):
                        raise StaleRead("revocation access barrier changed")
                    from .runtime.source_attachment_graph_v2 import scrub_media_blobs
                    scrub_media_blobs(db, namespace, request.source_id)
                    receipt = SourceAccessRevocationReceiptV1(
                        namespace, request.source_id, operation_id, request_digest,
                        source_atom.revision, access_atom.revision + 1,
                        metadata.graph_revision + 1, graph_receipt.epoch.revision,
                        epochs[0] + 1, epochs[1],
                    )
                    db.execute(
                        "UPDATE graph_source_access_revocations_v1 SET receipt_json=? "
                        "WHERE bot=? AND persona=? AND request_id=? "
                        "AND receipt_json IS NULL AND rejected=0",
                        (canonical_json(asdict(receipt)), *namespace.as_tuple,
                         request.request_id),
                    )
                    if db.execute("SELECT changes()").fetchone() != (1,):
                        raise EventConflict("revocation operation receipt differs")
                    sealed.append(receipt)

                GraphStore._graph_commit_in_transaction(
                    store, graph_candidate, _receipt_hook=seal,
                    _capability=self.__graph_capability)
                commit_started = True
                db.execute("COMMIT")
            except BaseException as exc:
                if db.in_transaction:
                    db.execute("ROLLBACK")
                if commit_started or not isinstance(exc, Exception):
                    raise
                failure = exc
            else:
                failure = None
        if failure is not None:
            reject_no_commit()
            raise failure
        port.finish_fence(scope, request_id=finish_id,
                          request_digest=finish_digest)
        return sealed[0]

    def project_workbench_snapshot_v1(
            self, authority: AuthorityContext, lease: object, *,
            view_registry: object, view_type: str, audience: str,
            purpose: str) -> WorkbenchProjectionSnapshotV1:
        """Read and project one complete D12 view inside one v2 read fence.

        Raw atoms remain inside the coordinator callback. Internal pages are
        pinned to one namespace epoch, and only the registry-validated field
        projection is returned to the D12 issuer.
        """
        from .workbench_api.domain_registry import (
            CurrentDomainViewRegistry, PROJECTION_CONTEXT_V2,
        )

        if not isinstance(authority, AuthorityContext):
            raise TypeError("authority required")
        if (authority.issuer_domain != "d12"
                or type(view_registry) is not CurrentDomainViewRegistry
                or not isinstance(view_type, str) or not view_type
                or not isinstance(audience, str) or audience not in authority.audience
                or purpose != authority.purpose):
            raise AuthorityDenied("complete D12 projection authority required")
        if (not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None):
            raise UnavailableGuard("complete workbench snapshot requires v2 read fence")
        try:
            types = view_registry.view_types(authority).get(view_type)
            owner_kind = view_registry.view_owner_kind(authority, view_type)
            context_version = view_registry.projection_context_version(authority, view_type)
        except Exception as exc:
            raise UnavailableGuard("complete workbench view is unavailable") from exc
        if (not isinstance(types, tuple) or not types or owner_kind not in authority.owner_scope
                or context_version != PROJECTION_CONTEXT_V2):
            raise AuthorityDenied("view does not require complete fenced projection")
        if (len(set(types)) != len(types)
                or any(not isinstance(name, str) or not name for name in types)):
            raise AuthorityDenied("view has invalid graph type scope")
        specs = tuple(self.__store._registry.spec(name) for name in types)
        if any(owner_kind not in spec.owner_kinds or not spec.writer_domain for spec in specs):
            raise AuthorityDenied("view type ownership is incomplete")
        domains = frozenset(spec.writer_domain for spec in specs)
        self._authorize(lease, authority, domains, owner_read=True)

        store = self.__store

        def read_and_project():
            page_after = None
            expected_epoch = None
            atoms = []
            while True:
                page = GraphStore.graph_query(
                    store, *authority.namespace.as_tuple, type_names=types,
                    owner_kind=owner_kind, after=page_after,
                    expected_epoch=expected_epoch, limit=512,
                    _capability=self.__graph_capability,
                )
                if not isinstance(page, GraphPage) or len(page.snapshot.epochs) != 1:
                    raise UnavailableGuard("complete workbench page is invalid")
                epoch = page.snapshot.epochs[0]
                if ((epoch.bot, epoch.persona) != authority.namespace.as_tuple
                        or (expected_epoch is not None and epoch != expected_epoch)):
                    raise StaleRead("complete workbench snapshot changed between pages")
                if expected_epoch is None:
                    expected_epoch = epoch
                previous_token = page_after.token if page_after is not None else None
                for atom in page.snapshot.atoms:
                    if (atom.key.owner.kind != owner_kind
                            or (atom.key.owner.bot, atom.key.owner.persona)
                            != authority.namespace.as_tuple
                            or atom.key.type_name not in types
                            or (previous_token is not None and atom.key.token <= previous_token)):
                        raise UnavailableGuard("complete workbench atoms are invalid")
                    atoms.append({
                        "key": atom.key.token, "type": atom.key.type_name,
                        "name": atom.key.name, "revision": atom.revision,
                        "value": atom.value,
                    })
                    previous_token = atom.key.token
                if page.next_after is None:
                    break
                if (not page.snapshot.atoms
                        or page.next_after != page.snapshot.atoms[-1].key
                        or page.next_after == page_after):
                    raise UnavailableGuard("complete workbench continuation is invalid")
                page_after = page.next_after

            proof = CompleteProjectionSnapshotV1(
                authority.namespace, expected_epoch, authority.activation_generation,
                view_type, types, owner_kind, audience, purpose,
                _seal=_COMPLETE_PROJECTION_SEAL,
            )
            projection = view_registry.project_workbench(
                authority, view_type, tuple(atoms), audience=audience,
                purpose=purpose, snapshot_proof=proof,
            )
            return WorkbenchProjectionSnapshotV1(authority.namespace, projection)

        return self._read_v2(
            authority, read_and_project,
            owner_binding=self.__owner_leases.get(lease),
            owner_session_proof=self.__owner_session_proofs.get(lease),
        )

    def query(self, authority: AuthorityContext, lease: object, *,
              type_names: tuple[str, ...], owner_kind: str, **filters):
        if not isinstance(authority, AuthorityContext):
            raise TypeError("authority required")
        if not type_names or owner_kind not in authority.owner_scope:
            raise AuthorityDenied("query must select authorized types and owner kind")
        if filters.get("include_invalid"):
            raise AuthorityDenied("ordinary content query cannot include invalid atoms")
        domains = frozenset(self.__store._registry.spec(name).writer_domain
                            for name in type_names)
        self._authorize(lease, authority, domains, owner_read=True)
        if isinstance(self.__store, ProductionGraphStore) and self.__content_fence_v2 is not None:
            return self._read_v2(authority, lambda: GraphStore.graph_query(
                self.__store, *authority.namespace.as_tuple, type_names=type_names,
                owner_kind=owner_kind, _capability=self.__graph_capability, **filters),
                owner_binding=self.__owner_leases.get(lease),
                owner_session_proof=self.__owner_session_proofs.get(lease))
        with self._content_fence(authority.namespace, authority.activation_generation, "read"):
            store = self.__store
            with store._lock:
                # A range query has no finite content reference set. After any
                # deletion it remains closed until a D06 range-closure proof exists.
                self._admit_content(authority.namespace, authority.activation_generation,
                                    "read")
                return GraphStore.graph_query(
                    store, *authority.namespace.as_tuple, type_names=type_names,
                    owner_kind=owner_kind, _capability=self.__graph_capability, **filters)

    def get_operation(self, authority: AuthorityContext, lease: object,
                      operation_id: str) -> CommitReceipt | None:
        """Resolve an uncertain commit from the durable business operation ledger."""
        if not isinstance(authority, AuthorityContext) or not operation_id:
            raise ValueError("valid authority and operation ID are required")
        self._authorize(lease, authority, frozenset())
        if isinstance(self.__store, ProductionGraphStore) and self.__content_fence_v2 is not None:
            return self._read_v2(authority, lambda: self._get_operation_fenced(
                authority, operation_id, v2=True))
        with self._content_fence(authority.namespace, authority.activation_generation, "read"):
            return self._get_operation_fenced(authority, operation_id)

    def get_dispatch_candidate_evidence(self, authority: AuthorityContext,
                                        lease: object, operation_id: str):
        """Rebuild a source-HOLD candidate from committed historical graph atoms."""
        if not isinstance(authority, AuthorityContext) or not operation_id:
            raise ValueError("authority and operation ID are required")
        self._authorize(lease, authority, frozenset({"d08", "d09"}))
        reader = lambda: self._get_dispatch_candidate_evidence_locked(
            authority.namespace, operation_id)
        if (isinstance(self.__store, ProductionGraphStore)
                and self.__content_fence_v2 is not None):
            return self._read_v2(authority, reader)
        with self._content_fence(authority.namespace, authority.activation_generation, "read"):
            with self.__store._lock:
                self._admit_content(authority.namespace,
                                    authority.activation_generation, "read")
                return reader()

    def _get_dispatch_candidate_evidence_locked(self, namespace, operation_id):
        from .domains.d08 import GoalExecutionProvider
        from .graph_types import AtomKey, GraphWrite

        store = self.__store
        db = store._db
        row = db.execute(
            "SELECT activity_id,effect_id,receipt_json FROM graph_bundle_operations "
            "WHERE bot=? AND persona=? AND operation_id=?",
            namespace.as_tuple + (operation_id,),
        ).fetchone()
        if row is None:
            return None
        data = json.loads(row[2]).get("dispatch_candidate")
        if data is None:
            return None
        if (type(data) is not dict or data.get("schema") != "sylanne.d11.dispatch_candidate.v1"
                or data.get("status") not in {"source_hold", "source_qualified"}
                or type(data.get("refs")) is not list or len(data["refs"]) != 4):
            raise UnavailableGuard("durable dispatch candidate receipt is invalid")
        event = db.execute(
            "SELECT revisions,epoch_revision,reads FROM graph_events WHERE bot=? "
            "AND persona=? AND session=? AND event_id=?",
            namespace.as_tuple + (row[0], operation_id),
        ).fetchone()
        if event is None or event[1] != data.get("graph_epoch"):
            raise UnavailableGuard("dispatch candidate graph event is missing")
        revisions = {item.key.token: item.revision
                     for item in GraphStore._version_rows(event[0])}
        typed_writes = []
        for position, item in enumerate(data["refs"]):
            if (type(item) is not list or len(item) != 2
                    or type(item[0]) is not str or type(item[1]) is not int
                    or item[1] < 1 or revisions.get(item[0]) != item[1]):
                raise UnavailableGuard("dispatch candidate write version differs")
            key = AtomKey.from_token(item[0])
            expected_type = (
                "d08.action_intent.v1", "d08.action_schema.v1",
                "d08.communication_intent_grant.v1", "d09.verified_segment_batch.v1",
            )[position]
            if key.type_name != expected_type:
                raise UnavailableGuard("dispatch candidate graph type differs")
            history = db.execute(
                "SELECT value,valid FROM graph_history WHERE token=? AND revision=? "
                "AND event_bot=? AND event_persona=? AND event_session=? AND event_id=?",
                (item[0], item[1]) + namespace.as_tuple + (row[0], operation_id),
            ).fetchone()
            if history is None or history[1] != 1:
                raise UnavailableGuard("dispatch candidate history is unavailable")
            typed_writes.append(("d09" if position == 3 else "d08",
                                 GraphWrite(key, json.loads(history[0]))))
        action = next(spec for spec in GoalExecutionProvider().register_types()
                      if spec.name == "d08.action_intent.v1").validator(
                          typed_writes[0][1].value)
        if (action.identity.operation_id != operation_id
                or action.identity.activity_id != row[0]
                or action.identity.effect_id != row[1]):
            raise UnavailableGuard("dispatch candidate operation identity differs")
        candidate = validate_dispatch_candidate_writes(
            tuple(typed_writes), namespace=namespace, identity=action.identity,
            read_versions=GraphStore._version_rows(event[2]),
            source_refs=tuple(data.get("source_refs", ())),
            access_epoch=data.get("access_epoch"),
            delete_epoch=data.get("delete_epoch"),
            query_epoch=data.get("query_epoch"),
        )
        if candidate is not None and data["status"] == "source_qualified":
            read_versions = GraphStore._version_rows(event[2])
            if (data.get("graph_epoch") != candidate.query_epoch + 1
                    or type(data.get("source_audience")) is not list
                    or type(data.get("source_proof_versions")) is not list):
                raise UnavailableGuard("dispatch source proof graph epoch differs")
            atoms = []
            for read in read_versions:
                if read.revision == 0:
                    atoms.append(GraphAtom(read.key, 0, {}, False))
                    continue
                history = db.execute(
                    "SELECT value,valid FROM graph_history WHERE token=? AND revision=?",
                    (read.key.token, read.revision),
                ).fetchone()
                if history is None:
                    raise UnavailableGuard("dispatch source proof history is unavailable")
                atoms.append(GraphAtom(read.key, read.revision, json.loads(history[0]),
                                       bool(history[1])))
            candidate = qualify_dispatch_candidate_sources(
                candidate, action, GraphSnapshot(tuple(atoms), (
                    NamespaceEpoch(*namespace.as_tuple, candidate.query_epoch),)),
                audience=tuple(data["source_audience"]),
                batch_audiences=tuple(typed_writes[3][1].value["audiences"]),
                current_barrier_confirmed=True,
                valid_until=typed_writes[3][1].value["valid_until"],
            )
            if (candidate.status != "source_qualified"
                    or [list(item) for item in candidate.source_proof_versions]
                    != data["source_proof_versions"]
                    or candidate.source_proof_digest != data.get("source_proof_digest")):
                raise UnavailableGuard("dispatch source proof differs from graph history")
        if candidate is None or candidate.digest != data.get("digest"):
            raise UnavailableGuard("dispatch candidate digest differs")
        if isinstance(store, ProductionGraphStore):
            metadata = self._v2_graph_stamp(namespace)[0]
            if (data.get("graph_incarnation") != metadata.requirements.graph_incarnation
                    or type(data.get("graph_revision")) is not int
                    or data["graph_revision"] > metadata.graph_revision):
                raise UnavailableGuard("dispatch candidate recovery stamp differs")
        return DispatchCandidateRecoveryV1(
            candidate, tuple((ref, revision) for ref, revision in data["refs"]),
            data["graph_epoch"], data["graph_incarnation"], data["graph_revision"],
        )

    def _get_natural_dispatch_candidate_evidence_locked(
            self, namespace: NamespaceId, operation_id: str
    ) -> NaturalDispatchCandidateRecoveryV2 | None:
        """Use the same original-event decoder as the pinned dispatch proof."""
        from .runtime.natural_dispatch_current_read_v2 import (
            NaturalDispatchCurrentHold,
            recover_natural_dispatch_candidate_in_transaction_v2,
        )

        try:
            return recover_natural_dispatch_candidate_in_transaction_v2(
                self.__store._db, namespace, operation_id)
        except NaturalDispatchCurrentHold as exc:
            raise UnavailableGuard(str(exc)) from exc

    def _get_operation_fenced(self, authority: AuthorityContext,
                              operation_id: str, *, v2: bool = False) -> CommitReceipt | None:
        namespace = authority.namespace
        store = self.__store
        with store._lock:
            store._ensure_open()
            if not v2:
                self._admit_content(namespace, authority.activation_generation, "read")
                if self._version(store._db, namespace, "activation", "current") != str(
                        authority.activation_generation):
                    raise StaleRead("activation generation changed")
            return self._get_operation_locked(namespace, operation_id)

    def _get_operation_locked(
            self, namespace: NamespaceId,
            operation_id: str) -> CommitReceipt | None:
        """Read the original graph event while the caller owns the graph lock."""
        store = self.__store
        if not store._lock._is_owned():
            raise RuntimeError("operation read requires graph lock")
        row = store._db.execute(
                "SELECT digest,activity_id,effect_id,commit_seq,receipt_json "
                "FROM graph_bundle_operations WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone()
        if row is None:
            return None
        graph = store._db.execute(
                "SELECT reads,revisions,epoch_revision FROM graph_events WHERE bot=? "
                "AND persona=? AND session=? AND event_id=?",
                namespace.as_tuple + (row[1], operation_id),
            ).fetchone()
        if graph is None:
            raise EventConflict("bundle operation has no graph event")
        data = json.loads(row[4])
        return CommitReceipt(
                "committed", operation_id, row[0], row[1], row[2], row[3],
                GraphStore._version_rows(graph[0]), GraphStore._version_rows(graph[1]),
                (NamespaceEpoch(*namespace.as_tuple, graph[2]),),
                tuple(data["ledger_refs"]), tuple(data["outbox_refs"]),
            )

    def _check_product_advance(self, db, bundle: DomainBundle,
                               snapshot: GraphSnapshot, writes: tuple) -> dict | None:
        """Bind an advance to current D04 state before any business write."""
        if not isinstance(self.__store, ProductionGraphStore):
            if bundle.product_advance is not None:
                raise UnavailableGuard("product advance evidence requires production graph authority")
            return None
        state_items = tuple(write for write in writes if write.key.type_name in {
            "d04.feeling_state.v1", "d04.mood_field.v1"})
        state_writes = {write.key.type_name: write for write in state_items}
        if len(state_writes) != len(state_items):
            raise AuthorityDenied("multiple D04 state writes of the same type")
        advance = False
        for write in state_writes.values():
            current = snapshot.get(write.key)
            if current is None:
                raise StaleRead("D04 write key is absent from the complete read set")
            if current.revision == 0:
                raise UnavailableGuard(
                    "initial D04 state needs an authenticated authored root; HOLD")
            if not current.valid:
                raise StaleRead("D04 state is invalid")
            old, new = current.value, write.value
            if new["revision"] != old["revision"] + 1:
                raise StaleRead("D04 state revision is not the next revision")
            if new["cursor"] < old["cursor"]:
                raise StaleRead("D04 state cursor moved backwards")
            if new["cursor"] == old["cursor"]:
                semantic_fields = ({"meaning_refs", "interpretation_refs",
                                    "active_driver_refs", "historical_source_refs", "revision"}
                                   if write.key.type_name == "d04.feeling_state.v1"
                                   else {"source_refs", "revision"})
                if any(new.get(name) != old.get(name)
                       for name in set(old) | set(new) if name not in semantic_fields):
                    raise AuthorityDenied("same-cursor D04 correction changed numerical state")
            else:
                advance = True
        evidence = bundle.product_advance
        if not advance:
            if evidence is not None:
                raise AuthorityDenied("product advance evidence has no existing interval to advance")
            if bundle.envelope.identity.phase == "d11.product_advance_candidate.v1":
                raise AuthorityDenied("product advance phase has no numerical interval")
            return None
        if evidence is None:
            raise UnavailableGuard("D04 time advance requires product numeric evidence")
        if (type(evidence) is not ProductAdvanceEvidenceV1
                or bundle.envelope.identity.phase != "d11.product_advance_candidate.v1"
                or set(state_writes) != {"d04.feeling_state.v1", "d04.mood_field.v1"}):
            raise AuthorityDenied("product advance requires one feeling and one mood write")
        feeling = state_writes["d04.feeling_state.v1"]
        mood = state_writes["d04.mood_field.v1"]
        if (feeling.key.token != evidence.feeling_ref
                or mood.key.token != evidence.mood_ref):
            raise AuthorityDenied("product advance refs differ from D04 writes")
        old_feeling, old_mood = snapshot.get(feeling.key), snapshot.get(mood.key)
        if (old_feeling is None or old_mood is None
                or not old_feeling.valid or not old_mood.valid
                or old_feeling.revision == 0 or old_mood.revision == 0
                or old_feeling.value["cursor"] != evidence.from_cursor
                or old_mood.value["cursor"] != evidence.from_cursor
                or feeling.value["cursor"] != evidence.to_cursor
                or mood.value["cursor"] != evidence.to_cursor
                or feeling.value["process_id"] != old_feeling.value["process_id"]
                or mood.value["mood_id"] != old_mood.value["mood_id"]):
            raise StaleRead("product advance does not follow the current joint state")
        candidate_digest = canonical_digest({
            "schema": "sylanne.d04.product.advance.candidate.v1",
            "feeling": {"ref": feeling.key.token, "value": feeling.value},
            "mood": {"ref": mood.key.token, "value": mood.value},
        })
        if evidence.candidate_digest != candidate_digest:
            raise AuthorityDenied("product evidence does not bind the exact D04 writes")
        namespace = bundle.envelope.authority.namespace
        parent = db.execute(
            "SELECT process_id,feeling_ref,mood_ref,to_cursor,next_error_bound "
            "FROM graph_product_advances WHERE bot=? AND persona=? AND operation_id=?",
            namespace.as_tuple + (evidence.parent_operation_id,),
        ).fetchone()
        if (parent is None or parent[0] != old_feeling.value["process_id"]
                or (parent[1], parent[2]) != (evidence.feeling_ref, evidence.mood_ref)
                or parent[3] != evidence.from_cursor
                or parent[4] != evidence.previous_error_bound):
            raise StaleRead("product advance has no matching committed error predecessor")
        parent_event = db.execute(
            "SELECT e.revisions FROM graph_events e JOIN graph_bundle_operations b "
            "ON b.bot=e.bot AND b.persona=e.persona AND b.activity_id=e.session "
            "AND b.operation_id=e.event_id WHERE b.bot=? AND b.persona=? "
            "AND b.operation_id=?", namespace.as_tuple + (evidence.parent_operation_id,),
        ).fetchone()
        if parent_event is None:
            raise StaleRead("product advance parent graph receipt is missing")
        parent_versions = dict(json.loads(parent_event[0]))
        if (parent_versions.get(evidence.feeling_ref) != old_feeling.revision
                or parent_versions.get(evidence.mood_ref) != old_mood.revision):
            raise StaleRead("product advance parent is not the current joint state")
        conflict = db.execute(
            "SELECT 1 FROM graph_product_advances WHERE bot=? AND persona=? "
            "AND process_id=? AND (replay_key=? OR "
            "(from_cursor<? AND to_cursor>?)) LIMIT 1",
            namespace.as_tuple + (old_feeling.value["process_id"], evidence.replay_key,
                                  evidence.to_cursor, evidence.from_cursor),
        ).fetchone()
        if conflict is not None:
            raise EventConflict("product advance replay or interval already committed")
        issuer = self.__product_advance_issuer
        if issuer is None:
            raise UnavailableGuard("trusted product numeric issuer is unavailable")
        # Future issuer verification must be a local, pure check; FFI runs outside
        # this transaction and binds the complete joint input/output digests.
        if issuer.verify(evidence, bundle) is not True:
            raise AuthorityDenied("product numeric issuer did not verify evidence")
        return {**asdict(evidence), "process_id": old_feeling.value["process_id"]}

    def _current_joint_state_predecessors_v2(
            self, db, namespace: NamespaceId, evidence, current,
            snapshot: GraphSnapshot):
        """Freeze the exact preceding D04 states and committed receipt heads."""
        from .domains.d04.joint_state_output_v1 import (
            JointStateFrozenPredecessorsV1, JointStatePredecessorV1,
        )
        from .domains.d04.authored_lineage_v3 import AuthoredNumericCheckpointV2
        from .domains.d04.root import encode_numeric_checkpoint
        from .runtime.d04_joint_advance_v2 import read_joint_advance_v2
        from .runtime.d04_root_original_store_v1 import _receipt as graph_receipt
        from .runtime.d04_root_original_store_v3 import read_d04_root_original_v3

        versions = {version.key.token: version.revision
                    for version in current.component.read_versions}
        predecessors = []
        for member, checkpoint in zip(evidence.members, current.checkpoints):
            checkpoint_atom = snapshot.get(AtomKey.from_token(member.checkpoint_ref))
            state_atom = snapshot.get(AtomKey.from_token(member.predecessor_state_ref))
            if (checkpoint_atom is None or state_atom is None
                    or versions.get(member.checkpoint_ref) != member.predecessor_revision
                    or versions.get(member.predecessor_state_ref)
                       != member.predecessor_state_revision
                    or checkpoint_atom.revision != member.predecessor_revision
                    or state_atom.revision != member.predecessor_state_revision
                    or canonical_digest(checkpoint_atom.value)
                       != member.predecessor_value_digest
                    or canonical_digest(state_atom.value)
                       != member.predecessor_state_value_digest
                    or checkpoint.commit_operation_id
                       != member.predecessor_operation_id):
                raise StaleRead("D04 joint predecessor values changed")
            state = self.__store._registry.spec(
                AtomKey.from_token(member.predecessor_state_ref).type_name,
            ).validator(state_atom.value)
            if (type(checkpoint) is AuthoredNumericCheckpointV2
                    and checkpoint.status
                       == "trusted_initial_box_pending_w01_v3_adoption"):
                original = read_d04_root_original_v3(
                    db, namespace=namespace,
                    operation_id=member.predecessor_operation_id)
                if (original is None
                        or original.original_digest
                           != current.component.root_original_digest
                        or checkpoint.root_candidate_digest
                           != canonical_digest(json.loads(original.candidate_json))):
                    raise UnavailableGuard("D04 authored root predecessor differs; HOLD")
                predecessor_digest = original.graph_receipt_digest
            elif (type(checkpoint) is not AuthoredNumericCheckpointV2
                  and checkpoint.predecessor_kind == "none"):
                row = db.execute(
                    "SELECT original_json,checkpoints_json,receipt_digest,"
                    "replay_digests_json,record_digest "
                    "FROM graph_d04_root_originals_v1 WHERE bot=? AND persona=? "
                    "AND operation_id=?",
                    namespace.as_tuple + (member.predecessor_operation_id,),
                ).fetchone()
                if row is None:
                    raise UnavailableGuard("D04 root predecessor original absent; HOLD")
                original_json, checkpoints_json, receipt_digest, replay_json, record = row
                expected = canonical_digest({
                    "schema": "d04.root-original-record.v1",
                    "operation_id": member.predecessor_operation_id,
                    "original": original_json, "checkpoints": checkpoints_json,
                    "receipt": receipt_digest, "replays": replay_json,
                })
                if (expected != record or canonical_json(json.loads(checkpoints_json))
                        != checkpoints_json
                        or encode_numeric_checkpoint(checkpoint)
                           not in json.loads(checkpoints_json)):
                    raise UnavailableGuard("D04 root predecessor original changed; HOLD")
                predecessor_digest = canonical_digest(asdict(graph_receipt(
                    db, namespace, member.predecessor_operation_id)))
                if predecessor_digest != receipt_digest:
                    raise UnavailableGuard("D04 root commit receipt changed; HOLD")
            else:
                prior = read_joint_advance_v2(
                    db, namespace, member.predecessor_operation_id)
                if prior is None or not any(
                        item.checkpoint_ref == member.checkpoint_ref
                        and item.next_revision == member.predecessor_revision
                        and item.next_value_digest == member.predecessor_value_digest
                        and item.output_state_ref == member.predecessor_state_ref
                        and item.output_state_revision == member.predecessor_state_revision
                        and item.output_state_digest == member.predecessor_state_value_digest
                        for item in prior.members):
                    raise UnavailableGuard("D04 joint predecessor original changed; HOLD")
                receipt = graph_receipt(
                    db, namespace, member.predecessor_operation_id)
                if receipt.operation_digest != prior.bundle_digest:
                    raise UnavailableGuard("D04 joint commit receipt changed; HOLD")
                predecessor_digest = canonical_digest(asdict(receipt))
            predecessors.append(JointStatePredecessorV1(
                member.checkpoint_ref, member.predecessor_revision, checkpoint,
                member.predecessor_state_ref, member.predecessor_state_revision,
                state, predecessor_digest,
            ))
        return JointStateFrozenPredecessorsV1(
            namespace, evidence.operation_id, tuple(predecessors))

    def _check_joint_product_advance_v2(self, db, bundle: DomainBundle,
                                        snapshot: GraphSnapshot, writes: tuple,
                                        installed_replay, installed_output, v2_write, authored_topology_verifier=None, numeric_issuance=None):
        """Preflight a complete installed joint result before graph mutation."""
        from .domains.d04.trusted_joint_replay import (
            D04InstalledJointNumericReplayV1,
            is_package_bound_joint_numeric_replay_v1,
        )
        from .runtime.d04_current_joint_replay_input_v2 import (
            read_current_joint_replay_input_in_transaction_v2,
        )
        from .runtime.d04_joint_advance_v2 import (
            ProductAdvanceEvidenceV2, preflight_joint_advance_v2,
            preflight_joint_numeric_original_v1,
            verification_from_installed_joint_replay_v1,
        )
        from .runtime_contracts import QueryEpoch
        from .domains.d04.joint_state_output_v1 import (
            JointStateOutputOriginalV1,
            joint_checkpoint_payload_v1, joint_state_payload_v1,
            verify_current_joint_state_output_original_v1,
        )

        from .runtime.d04_numeric_adoption_v3 import require_current_numeric_commit_witness_v3
        require_current_numeric_commit_witness_v3(self, db, bundle, numeric_issuance)
        evidence = bundle.product_advance
        envelope = bundle.envelope
        namespace = envelope.authority.namespace
        assembly = self.__d04_installed_joint_assembly
        output_policy = self.__d04_installed_joint_output_policy
        if (type(evidence) is not ProductAdvanceEvidenceV2
                or type(installed_replay) is not D04InstalledJointNumericReplayV1
                or not is_package_bound_joint_numeric_replay_v1(installed_replay)
                or type(installed_output) is not JointStateOutputOriginalV1
                or assembly is None or output_policy is None or v2_write is None
                or evidence.namespace != namespace
                or evidence.operation_id != envelope.identity.operation_id
                or evidence.bundle_digest != bundle.digest
                or evidence.native_manifest_sha256
                   != assembly.installation_policy.manifest_digest
                or evidence.graph_epoch != v2_write[1].revision
                or evidence.graph_revision != v2_write[0].graph_revision
                or evidence.graph_incarnation
                   != v2_write[0].requirements.graph_incarnation
                or (evidence.access_epoch, evidence.delete_epoch) != (
                    envelope.version_guard.access_epoch,
                    envelope.version_guard.delete_epoch)):
            raise UnavailableGuard("installed D04 joint advance identity unavailable; HOLD")
        required = {member.checkpoint_ref for member in evidence.members}
        required.update(member.output_state_ref for member in evidence.members)
        d04_writes = {write.key.token: write for write in writes
                      if self.__store._registry.spec(write.key.type_name).writer_domain == "d04"
                      and write.key.type_name != "d04.contribution_ledger.v1"}
        if (set(d04_writes) != required or len(required) != 2 * len(evidence.members)
                or tuple(sorted(member.checkpoint_ref for member in evidence.members))
                   != installed_replay.component.checkpoint_refs):
            raise AuthorityDenied("D04 joint advance member write set differs")
        for member in evidence.members:
            for ref, revision, digest in (
                    (member.checkpoint_ref, member.next_revision,
                     member.next_value_digest),
                    (member.output_state_ref, member.output_state_revision,
                     member.output_state_digest)):
                key = AtomKey.from_token(ref)
                current = snapshot.get(key)
                if (current is None or current.revision != revision - 1
                        or not current.valid
                        or canonical_digest(d04_writes[ref].value) != digest):
                    raise StaleRead("D04 joint member current or output differs")
        registration = self.__providers.get("d04")
        from .domains.d04.affect import AffectProvider, AffectScheme

        if (registration is None or type(registration[0]) is not AffectProvider
                or type(registration[0]._active_scheme) is not AffectScheme):
            raise UnavailableGuard("installed D04 affect scheme unavailable")
        current = read_current_joint_replay_input_in_transaction_v2(
            db, namespace=namespace, registry=self.__store._registry,
            authored_topology_verifier=authored_topology_verifier,
            scheme=registration[0]._active_scheme,
            root_ref=evidence.members[0].checkpoint_ref,
            role_start=evidence.role_start, role_end=evidence.role_end,
            expected_query_epoch=QueryEpoch(namespace, "all", evidence.graph_epoch),
            expected_graph_incarnation=evidence.graph_incarnation,
            expected_graph_revision=evidence.graph_revision,
            expected_access_epoch=evidence.access_epoch,
            expected_delete_epoch=evidence.delete_epoch,
            audience=envelope.authority.audience,
            purpose=envelope.authority.purpose,
        )
        if (current.component != installed_replay.component
                or current.checkpoints != installed_replay.checkpoints
                or current.drives != installed_replay.drives
                or current.families != installed_replay.families
                or not set(current.component.read_versions).issubset(
                    envelope.version_guard.read_versions)):
            raise StaleRead("D04 installed joint replay premise changed")
        frozen = self._current_joint_state_predecessors_v2(
            db, namespace, evidence, current, snapshot)
        if not verify_current_joint_state_output_original_v1(
                installed_output, installed_replay, frozen, output_policy):
            raise UnavailableGuard("installed D04 joint output derivation unavailable; HOLD")
        output_rows = []
        for member in installed_output.members:
            output_rows.append((
                member.checkpoint_ref,
                member.predecessor_checkpoint_revision + 1,
                joint_checkpoint_payload_v1(member.next_checkpoint),
            ))
            output_rows.append((
                member.predecessor_state_ref,
                member.predecessor_state_revision + 1,
                joint_state_payload_v1(member.next_state),
            ))
        output_rows = tuple(sorted(output_rows, key=lambda row: row[0]))
        if (installed_output.operation_id != evidence.operation_id
                or installed_output.write_set_digest != evidence.output_write_set_digest
                or canonical_digest(output_rows) != evidence.output_write_set_digest
                or set(d04_writes) != {row[0] for row in output_rows}
                or any(d04_writes[ref].value != value
                       for ref, _, value in output_rows)):
            raise AuthorityDenied("D04 joint graph writes differ from issued ABI2 output")
        joint = preflight_joint_advance_v2(
            db, evidence, trusted_local_verifier=lambda _db, _evidence:
            current.component == installed_replay.component,
        )
        numeric = preflight_joint_numeric_original_v1(
            db, evidence, installed_replay.candidate, joint_preflight=joint,
            trusted_local_numeric_verifier=lambda current_db, current_evidence, receipt:
            verification_from_installed_joint_replay_v1(
                current_db, current_evidence, receipt, installed_replay,
                current_component=current.component),
        )
        closure_rows = []
        for version in current.component.read_versions:
            ref = version.key.token
            if ref in required:
                continue  # These predecessors become the issued output writes.
            row = db.execute(
                "SELECT revision,value,valid FROM graph_atoms WHERE token=?", (ref,),
            ).fetchone()
            if version.revision == 0:
                if row is not None:
                    raise StaleRead("D04 joint negative read became present")
                closure_rows.append((ref, 0, False, canonical_digest({})))
            else:
                if row is None or row[0] != version.revision:
                    raise StaleRead("D04 joint source closure changed")
                value = json.loads(row[1])
                if canonical_serialize(value) != row[1]:
                    raise StaleRead("D04 joint source closure is noncanonical")
                closure_rows.append((ref, row[0], bool(row[2]), canonical_digest(value)))
        closure_rows = tuple(sorted(closure_rows, key=lambda item: item[0]))
        return (evidence, installed_replay.candidate, installed_output,
                joint, numeric, closure_rows, envelope.authority.audience,
                envelope.authority.purpose)

    def get_dispatch_admission(self, authority: AuthorityContext, lease: object,
                               admission_ref: str) -> DispatchAdmissionReceiptV1 | None:
        """Read a committed D11 admission identity through the normal content fence."""
        self._authorize(lease, authority, frozenset({"d11"}))
        reader = lambda: load_admission(
            self.__store._db, authority.namespace, admission_ref)
        if (isinstance(self.__store, ProductionGraphStore)
                and self.__content_fence_v2 is not None):
            return self._read_v2(authority, reader)
        with self._content_fence(authority.namespace,
                                 authority.activation_generation, "read"):
            with self.__store._lock:
                self._admit_content(authority.namespace,
                                    authority.activation_generation, "read")
                return reader()

    def get_committed_dispatch_action_job_binding(
            self, authority: AuthorityContext, lease: object,
            admission_ref: str):
        """Read an admission's historical D08/D11 job identity, never send authority."""
        from .runtime.dispatch_action_job_binding import load_action_job_binding

        self._authorize(lease, authority, frozenset({"d08", "d09", "d11"}))

        def reader():
            db = self.__store._db
            binding = load_action_job_binding(db, authority.namespace, admission_ref)
            if binding is None:
                return None
            if self._get_committed_dispatch_request_locked(
                    authority.namespace, admission_ref) is None:
                raise UnavailableGuard("dispatch action/job binding lacks its command")
            row = db.execute(
                "SELECT receipt_json FROM graph_bundle_operations WHERE bot=? "
                "AND persona=? AND operation_id=? AND effect_id=?",
                authority.namespace.as_tuple + (
                    binding.operation_id, binding.effect_id),
            ).fetchone()
            recorded = (json.loads(row[0]).get("dispatch_action_job_binding")
                        if row else None)
            if recorded != {
                    "schema": binding.schema, "ref": binding.admission_ref,
                    "digest": binding.digest, "job_id": binding.job_id}:
                raise UnavailableGuard("dispatch action/job binding differs from graph receipt")
            return binding

        if (isinstance(self.__store, ProductionGraphStore)
                and self.__content_fence_v2 is not None):
            return self._read_v2(authority, reader)
        with self._content_fence(authority.namespace,
                                 authority.activation_generation, "read"):
            with self.__store._lock:
                self._admit_content(authority.namespace,
                                    authority.activation_generation, "read")
                return reader()

    def get_committed_dispatch_request(self, authority: AuthorityContext,
                                       lease: object, admission_ref: str):
        """Recover a historical D11 command, never a current platform send permit."""
        self._authorize(lease, authority, frozenset({"d08", "d09", "d11"}))
        reader = lambda: self._get_committed_dispatch_request_locked(
            authority.namespace, admission_ref)
        if (isinstance(self.__store, ProductionGraphStore)
                and self.__content_fence_v2 is not None):
            return self._read_v2(authority, reader)
        with self._content_fence(authority.namespace,
                                 authority.activation_generation, "read"):
            with self.__store._lock:
                self._admit_content(authority.namespace,
                                    authority.activation_generation, "read")
                return reader()

    def get_committed_dispatch_for_operation_v2(
            self, authority: AuthorityContext, lease: object,
            operation_id: str):
        """Find one durable admission and request by the original operation.

        Recovery may discover this identity; it still needs the separate
        current final-claim and platform handoff checks before any send.
        """
        self._authorize(lease, authority, frozenset({"d08", "d09", "d11"}))
        if type(operation_id) is not str or not operation_id:
            raise ValueError("dispatch operation identity required")

        def reader():
            db = self.__store._db
            if db.execute(
                    "SELECT 1 FROM sqlite_master WHERE type='table' "
                    "AND name='graph_dispatch_admissions'").fetchone() is None:
                return None
            rows = db.execute(
                "SELECT admission_ref FROM graph_dispatch_admissions "
                "WHERE bot=? AND persona=? AND operation_id=?",
                authority.namespace.as_tuple + (operation_id,)).fetchall()
            if not rows:
                return None
            if len(rows) != 1:
                raise UnavailableGuard("dispatch operation has ambiguous admissions; HOLD")
            admission_ref = rows[0][0]
            receipt = load_admission(db, authority.namespace, admission_ref)
            request = self._get_committed_dispatch_request_locked(
                authority.namespace, admission_ref)
            if (receipt is None or request is None
                    or receipt.admission.operation_id != operation_id
                    or request.operation_id != operation_id):
                raise UnavailableGuard("dispatch operation admission differs; HOLD")
            return receipt, request

        if (isinstance(self.__store, ProductionGraphStore)
                and self.__content_fence_v2 is not None):
            return self._read_v2(authority, reader)
        with self._content_fence(authority.namespace,
                                 authority.activation_generation, "read"):
            with self.__store._lock:
                self._admit_content(authority.namespace,
                                    authority.activation_generation, "read")
                return reader()

    def _get_committed_dispatch_request_locked(self, namespace, admission_ref):
        db = self.__store._db
        loaded = load_request(db, namespace, admission_ref)
        if loaded is None:
            return None
        receipt, request = loaded
        admission = receipt.admission
        candidate = self._get_dispatch_candidate_evidence_locked(
            namespace, request.operation_id)
        row = db.execute(
            "SELECT receipt_json FROM graph_bundle_operations "
            "WHERE bot=? AND persona=? AND operation_id=? AND effect_id=?",
            namespace.as_tuple + (request.operation_id, request.effect_id),
        ).fetchone()
        graph_admission = json.loads(row[0]).get("dispatch_admission") if row else None
        if (candidate is None or candidate.evidence.status != "source_qualified"
                or graph_admission != {
                    "schema": admission.schema, "ref": admission_ref,
                    "digest": receipt.receipt_digest,
                }
                or admission.candidate_digest != candidate.evidence.digest
                or admission.batch_digest != candidate.evidence.batch_digest
                or receipt.graph_epoch != candidate.graph_epoch
                or receipt.graph_revision != (
                    candidate.graph_revision if candidate.graph_revision is not None
                    else candidate.graph_epoch)
                or admission.graph_incarnation != (
                    candidate.graph_incarnation or "nonproduction-graphstore")
                or request.payload_ref != dispatch_segment_payload_ref(
                    candidate.evidence.batch_ref, request.segment_index)):
            raise UnavailableGuard("stored dispatch request differs from graph receipt")
        batch_ref, batch_revision = candidate.write_versions[3]
        batch_row = db.execute(
            "SELECT value,valid FROM graph_history WHERE token=? AND revision=? "
            "AND event_bot=? AND event_persona=? AND event_session=? AND event_id=?",
            (batch_ref, batch_revision) + namespace.as_tuple + (
                request.activity_id, request.operation_id),
        ).fetchone()
        if batch_row is None or batch_row[1] != 1:
            raise UnavailableGuard("stored dispatch request batch is unavailable")
        batch = json.loads(batch_row[0])
        index = request.segment_index
        if (type(index) is not int or not 0 <= index < len(batch["segments"])
                or batch["batch_digest"] != admission.batch_digest
                or batch["segments"][index]["effect_id"] != request.effect_id
                or batch["segments"][index]["payload_digest"] != request.payload_digest
                or batch["segments"][index]["segment_authorization_ref"]
                != request.segment_authorization_ref
                or batch["grant_manifest_digest"] != request.segment_manifest_digest
                or len(batch["segments"]) != request.segment_count):
            raise UnavailableGuard("stored dispatch request segment differs")
        return request

    def _read_dispatch_final_claim_prerequisite_locked(
            self, namespace: NamespaceId, binding, claimed_receipt,
            handoff_id: str, *, now_utc: float):
        """Read durable W01/D11 facts inside the caller's business transaction.

        This returns an explicit HOLD. It cannot be installed as Authority's
        final_handoff_authorizer: no current P2 or complete domain check is
        established here, and it does not write a graph claim or stamp.
        """
        from .authority_service.v2_contract import ExecutionBindingV2
        from .runtime.dispatch_current_source_budget import CurrentDispatchHold
        from .runtime.dispatch_final_claim import read_final_claim_prerequisite

        db = self.__store._db
        if not db.in_transaction:
            raise CurrentDispatchHold("final claim prerequisite needs a held business transaction")
        if type(binding) is not ExecutionBindingV2:
            raise CurrentDispatchHold("final claim prerequisite requires a V2 binding")
        command = self._get_committed_dispatch_request_locked(
            namespace, binding.origin.admission_ref)
        if command is None:
            raise CurrentDispatchHold("committed graph dispatch command is absent")
        if command.operation_id.startswith("post-c02-reply:"):
            owned = db.execute(
                "SELECT state,reply_operation_id,effect_id,admission_ref,"
                "admission_digest,ack_digest FROM "
                "graph_post_c02_reply_ownership_v1 WHERE bot=? AND persona=? "
                "AND admission_ref=?",
                namespace.as_tuple + (binding.origin.admission_ref,),
            ).fetchall()
            admission = load_admission(
                db, namespace, binding.origin.admission_ref)
            if (len(owned) != 1 or admission is None
                    or owned[0][:5] != (
                        "sylanne_owned", command.operation_id,
                        command.effect_id, binding.origin.admission_ref,
                        admission.admission.digest)
                    or not owned[0][5]):
                raise CurrentDispatchHold(
                    "original reply lacks durable host ownership")
        return read_final_claim_prerequisite(
            db, namespace, binding, claimed_receipt, handoff_id,
            now_utc=now_utc,
        )

    def _read_current_post_c02_final_route_locked(
            self, namespace: NamespaceId, admission, action, segment,
            snapshot, query,
            *, now_utc: float):
        """Rejoin the original private ingress to its current account entity."""
        from .runtime.first_ingress_v2 import scene_ref_for_conversation
        from .runtime.dispatch_source_correction_barrier import (
            read_source_correction_barrier,
        )
        from .runtime.reply_entity_route_v2 import (
            ReplyEntityRouteHold, read_current_reply_entity_route_binding_v2,
        )
        from .runtime.reply_model_job import CurrentReplyRouteManifestV2

        db = self.__store._db
        if not db.in_transaction or not self.__store._lock._is_owned():
            raise UnavailableGuard("final reply route needs current graph transaction; HOLD")
        rows = db.execute(
            "SELECT ingress_operation_id,c02_operation_id,source_ref,"
            "target_entity_ref,account_ref,destination_ref,admission_digest,"
            "state,ack_digest FROM graph_post_c02_reply_ownership_v1 "
            "WHERE bot=? AND persona=? AND admission_ref=?",
            namespace.as_tuple + (admission.admission_ref,),
        ).fetchall()
        if len(rows) != 1:
            raise UnavailableGuard("final reply has no unique host ownership; HOLD")
        (ingress_operation_id, c02_operation_id, source_ref,
         target_entity_ref, account_ref, destination_ref,
         admission_digest, state, ack_digest) = rows[0]
        original = self._reply_ingress_identity_locked(
            namespace, ingress_operation_id)
        scene_ref = scene_ref_for_conversation(
            namespace, account_ref, destination_ref)
        route = CurrentReplyRouteManifestV2(
            namespace, c02_operation_id, source_ref, account_ref,
            destination_ref, scene_ref, canonical_digest({
                "account_ref": account_ref,
                "destination_ref": destination_ref,
                "scene_ref": scene_ref,
            }),
        )
        if (state != "sylanne_owned" or not ack_digest
                or admission_digest != admission.digest
                or (original["platform_ref"], original["conversation_ref"])
                   != (account_ref, destination_ref)
                or (admission.account_ref, admission.destination_ref,
                    admission.scene_ref, admission.object_ref,
                    admission.audience) != (
                        account_ref, destination_ref, scene_ref,
                        target_entity_ref, (destination_ref,))
                or action.target_ref != target_entity_ref
                or route.route_digest != segment.route_digest):
            raise UnavailableGuard("final reply route or account target differs; HOLD")
        try:
            current = read_current_reply_entity_route_binding_v2(
                db, namespace, route, query, now_utc=now_utc)
        except ReplyEntityRouteHold as exc:
            raise UnavailableGuard("final reply account binding unavailable; HOLD") from exc
        if (current.target_entity_ref != target_entity_ref
                or current.conversation_ref != destination_ref
                or current.scene_ref != scene_ref):
            raise UnavailableGuard("final reply current account route changed; HOLD")
        pending = [AtomKey.from_token(source_ref).owner.subject]
        seen = set()
        while pending:
            source_id = pending.pop()
            key = source_key(*namespace.as_tuple, source_id)
            access = access_key(*namespace.as_tuple, source_id)
            source_atom, access_atom = snapshot.get(key), snapshot.get(access)
            if (source_atom is None or access_atom is None
                    or not source_atom.valid or not access_atom.valid):
                raise UnavailableGuard("final reply source ancestor is absent; HOLD")
            if key.token in seen:
                continue
            record = SourceRecord.from_dict(source_atom.value)
            validate_access(access_atom.value)
            if record.source_id != source_id:
                raise UnavailableGuard("final reply source ancestry changed; HOLD")
            seen.add(key.token)
            pending.extend(record.parent_source_ids)
        source_closure = tuple(sorted(seen))
        barrier = read_source_correction_barrier(
            db, namespace, query, source_closure, dependent_ref=source_ref)
        if not barrier.clear:
            raise UnavailableGuard("final reply source correction changed; HOLD")
        return current, source_closure

    def _dispatch_full_graph_snapshot_locked(self, namespace: NamespaceId):
        """Read the complete namespace at one epoch in the final write transaction.

        GraphStore.graph_query starts its own transaction, so it cannot be
        nested in the final BEGIN IMMEDIATE. This reader is intentionally
        private and does not authorize a claim by itself.
        """
        from .runtime_contracts import QueryEpoch

        store = self.__store
        db = store._db
        if not store._lock._is_owned() or not db.in_transaction:
            raise RuntimeError("final graph snapshot requires held write transaction")
        epoch = GraphStore.graph_epoch(
            store, *namespace.as_tuple, _capability=self.__graph_capability)
        rows = db.execute(
            "SELECT token,revision,value,valid FROM graph_atoms "
            "WHERE bot=? AND persona=? ORDER BY token", namespace.as_tuple,
        ).fetchall()
        atoms = []
        for token, revision, encoded, valid in rows:
            key = AtomKey.from_token(token)
            if (NamespaceId.from_key(key) != namespace
                    or type(revision) is not int or revision < 1
                    or valid not in (0, 1)):
                raise UnavailableGuard("final graph snapshot row is invalid")
            store._validate_key(key)
            atoms.append(GraphAtom(key, revision, json.loads(encoded), bool(valid)))
        count = db.execute(
            "SELECT COUNT(*) FROM graph_atoms WHERE bot=? AND persona=?",
            namespace.as_tuple,
        ).fetchone()[0]
        if count != len(atoms):
            raise StaleRead("final graph snapshot coverage changed")
        return GraphSnapshot(tuple(atoms), (epoch,)), QueryEpoch(
            namespace, "all", epoch.revision)

    def _read_dispatch_d08_scope_locked(
            self, namespace: NamespaceId, scope, current_effect,
            effect_snapshot, intent, schema, route_binding, *,
            audience: tuple[str, ...],
            purpose: str, now_utc: float, valid_until_utc: float,
            expected_action_kind: str = "message"):
        """Read D08 from the actual staged or final SQL head, never a DTO PASS.

        The caller owns the ordinary write fence and the GraphStore transaction.
        A provisional invocation remains a candidate until this exact reader is
        invoked again in the final graph receipt hook.
        """
        from .domains.d08 import read_dispatch_check_scope_v2

        if (scope.namespace != namespace or scope.operation != "write"
                or not self.__store._lock._is_owned()
                or not self.__store._db.in_transaction):
            raise UnavailableGuard("current D08 write projection unavailable; HOLD")
        snapshot, query = self._dispatch_full_graph_snapshot_locked(namespace)
        try:
            return read_dispatch_check_scope_v2(
                self.__store._db, snapshot, query, scope, current_effect,
                effect_snapshot, intent, schema,
                route_binding=route_binding, audience=audience,
                purpose=purpose, now_utc=now_utc,
                valid_until_utc=valid_until_utc,
                expected_action_kind=expected_action_kind)
        except (TypeError, ValueError) as exc:
            raise UnavailableGuard("current D08 dispatch check unavailable; HOLD") from exc

    def _read_post_c02_prebatch_checks_locked(
            self, namespace: NamespaceId, scope, current_effect,
            effect_snapshot, intent, schema, expression, route,
            original_route_binding, current_route_binding, *,
            resource_quote, now_utc: float, valid_until_utc: float):
        """Issue only check candidates from one staged E+1 SQL projection.

        This private reader is called before a communication grant or batch
        exists. The final receipt hook must run the same readers again against
        the actual sealed rows and compare their entire relevant closures.
        """
        from .domains.d03.context import ContextProvider
        from .domains.d03.prebatch_social import issue_prebatch_private_social_v1
        from .domains.d08 import ActionSchemaRecord
        from .domains.d06 import SourceGrantRead, provide_source_grant_check
        from .authority_service.v2_contract import (
            AuthorityCurrentEffectSnapshotV2,
            canonical_digest as authority_canonical_digest,
        )
        from .authority_service.v2_execution_bridge import CurrentEffectReadV2
        from .runtime.installed_dispatch_admission_issuer import (
            InstalledDispatchAdmissionIssuer, inspect_current_d11_dispatch_budget,
        )

        issuer = self.__dispatch_admission_issuer
        context = (issuer._context
                   if type(issuer) is InstalledDispatchAdmissionIssuer else None)
        if type(context) is not ContextProvider:
            raise UnavailableGuard("installed social check provider unavailable; HOLD")
        if (resource_quote.deadline_utc != valid_until_utc
                or resource_quote.valid_until_utc < valid_until_utc
                or not now_utc < valid_until_utc):
            raise UnavailableGuard("signed reply dispatch deadline differs; HOLD")
        snapshot, query = self._dispatch_full_graph_snapshot_locked(namespace)
        d08 = self._read_dispatch_d08_scope_locked(
            namespace, scope, current_effect, effect_snapshot, intent, schema,
            current_route_binding,
            audience=(route.conversation_ref,), purpose=intent.purpose,
            now_utc=now_utc, valid_until_utc=valid_until_utc)
        social = issue_prebatch_private_social_v1(
            self.__store._db, snapshot, query, intent,
            ActionSchemaRecord.bind(intent, schema), expression, route=route,
            route_binding=original_route_binding,
            context=context, scope=scope,
            now_utc=now_utc, valid_until_utc=valid_until_utc)
        if (social.status != "checks_candidate" or social.role_receipt is None
                or social.boundary_receipt is None
                or social.manifest is None
                or social.manifest.audience != (route.conversation_ref,)):
            raise UnavailableGuard("current D03/D05 prebatch checks unavailable; HOLD")
        metadata = self.__store.graph_recovery_metadata(
            namespace, _capability=self.__graph_capability)
        epoch_row = self.__store._db.execute(
            "SELECT revision FROM graph_epochs WHERE bot=? AND persona=?",
            namespace.as_tuple).fetchone()
        access_delete_row = self.__store._db.execute(
            "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
            "WHERE bot=? AND persona=?", namespace.as_tuple).fetchone()
        coverage = (
            query.namespace == namespace and query.scope_ref == "all"
            and snapshot.epochs == (NamespaceEpoch(
                *namespace.as_tuple, query.revision),)
            and epoch_row == (query.revision,)
            and len(snapshot.atoms) == len({atom.key for atom in snapshot.atoms})
            and len(snapshot.atoms) == self.__store._db.execute(
                "SELECT COUNT(*) FROM graph_atoms WHERE bot=? AND persona=?",
                namespace.as_tuple).fetchone()[0]
        )
        barrier = (
            metadata is not None
            and self._anchor_matches(metadata.requirements, scope.pinned_anchor)
            and metadata.graph_revision == scope.graph_revision
            and scope.graph_epoch.revision + 1 == query.revision
            and access_delete_row is not None
            and all(type(value) is int and value >= 0
                    for value in access_delete_row)
            and scope.operation_id == scope.permit.operation_id
            and scope.permit.pinned_anchor == scope.pinned_anchor
            and type(effect_snapshot) is AuthorityCurrentEffectSnapshotV2
            and effect_snapshot.anchor == scope.pinned_anchor
            and effect_snapshot.permit_digest
                == authority_canonical_digest(scope.permit)
            and effect_snapshot.coverage == "complete"
            and not effect_snapshot.unresolved_effects
            and type(current_effect) is CurrentEffectReadV2
            and current_effect.state == "absent"
            and (current_effect.execution_head_seq,
                 current_effect.execution_head_digest) == (
                 scope.pinned_anchor.execution_seq,
                 scope.pinned_anchor.execution_digest)
        )
        if not coverage or not barrier:
            raise UnavailableGuard("current D06 source coverage or Authority barrier unavailable; HOLD")
        source_check = provide_source_grant_check(
            intent, SourceGrantRead(
                snapshot, (route.conversation_ref,), "expression",
                coverage, barrier),
            valid_until=valid_until_utc)
        budget = inspect_current_d11_dispatch_budget(
            self.__store._db, intent, d11_issuer=self.__d11_issuer,
            d02_issuer=self.__d02_issuer, now_utc=now_utc)
        if ((source_check.result, source_check.coverage) != ("pass", "full")
                or budget.status != "check_pass" or budget.receipt is None
                or (budget.receipt.result, budget.receipt.coverage)
                != ("pass", "full")
                or budget.receipt.valid_until < valid_until_utc):
            raise UnavailableGuard("current D06/D11 prebatch checks unavailable; HOLD")
        return d08, social, source_check, budget.receipt

    def _read_natural_pregrant_checks_locked(
            self, namespace: NamespaceId, scope: FenceScope,
            current_effect, effect_snapshot, final, intent, schema,
            route_binding, original_scope_proof, resource_quote, *,
            expected_access_delete_epoch: tuple[int, int],
            now_utc: float, valid_until_utc: float):
        """Issue five current checks before any natural grant or batch exists.

        The caller has provisionally staged the four D08 action atoms at E+1.
        A final graph receipt hook must issue these checks again after commit.
        """
        from .authority_service.v2_contract import (
            AuthorityCurrentEffectSnapshotV2,
            canonical_digest as authority_canonical_digest,
        )
        from .authority_service.v2_execution_bridge import CurrentEffectReadV2
        from .domains.d03.context import ContextProvider
        from .domains.d06 import SourceGrantRead, provide_source_grant_check
        from .runtime.installed_dispatch_admission_issuer import (
            InstalledDispatchAdmissionIssuer, inspect_current_d11_dispatch_budget,
        )
        from .runtime.issuers import ResourceQuote
        from .runtime.natural_prebatch_receipts_v2 import (
            issue_natural_pregrant_social_receipts_v2,
        )

        db = self.__store._db
        issuer = self.__dispatch_admission_issuer
        context = (issuer._context
                   if type(issuer) is InstalledDispatchAdmissionIssuer else None)
        if (not self.__store._lock._is_owned() or not db.in_transaction
                or scope.namespace != namespace or scope.operation != "write"
                or type(context) is not ContextProvider
                or type(resource_quote) is not ResourceQuote
                or type(expected_access_delete_epoch) is not tuple
                or len(expected_access_delete_epoch) != 2
                or resource_quote.deadline_utc != valid_until_utc
                or resource_quote.valid_until_utc < valid_until_utc
                or not now_utc < valid_until_utc):
            raise UnavailableGuard("natural pregrant current scope absent; HOLD")
        snapshot, query = self._dispatch_full_graph_snapshot_locked(namespace)
        d08 = self._read_dispatch_d08_scope_locked(
            namespace, scope, current_effect, effect_snapshot,
            intent, schema, route_binding,
            audience=(final.material.audience_id,), purpose="expression",
            now_utc=now_utc, valid_until_utc=valid_until_utc,
            expected_action_kind="communication")
        social = issue_natural_pregrant_social_receipts_v2(
            db, snapshot, query, final, intent, schema, route_binding,
            original_scope_proof, context, scope, now_utc=now_utc,
            valid_until_utc=valid_until_utc)
        metadata = self.__store.graph_recovery_metadata(
            namespace, _capability=self.__graph_capability)
        barrier = db.execute(
            "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
            "WHERE bot=? AND persona=?", namespace.as_tuple,
        ).fetchone()
        covered = (
            query.scope_ref == "all"
            and snapshot.epochs == (NamespaceEpoch(
                *namespace.as_tuple, query.revision),)
            and len(snapshot.atoms) == db.execute(
                "SELECT COUNT(*) FROM graph_atoms WHERE bot=? AND persona=?",
                namespace.as_tuple).fetchone()[0]
            and len(snapshot.atoms) == len({atom.key for atom in snapshot.atoms})
        )
        authority_current = (
            metadata is not None
            and self._anchor_matches(metadata.requirements, scope.pinned_anchor)
            and metadata.graph_revision == scope.graph_revision
            and scope.graph_epoch.revision + 1 == query.revision
            and barrier == expected_access_delete_epoch
            and scope.permit.pinned_anchor == scope.pinned_anchor
            and type(effect_snapshot) is AuthorityCurrentEffectSnapshotV2
            and effect_snapshot.anchor == scope.pinned_anchor
            and effect_snapshot.permit_digest
                == authority_canonical_digest(scope.permit)
            and effect_snapshot.coverage == "complete"
            and not effect_snapshot.unresolved_effects
            and type(current_effect) is CurrentEffectReadV2
            and current_effect.state == "absent"
        )
        if not covered or not authority_current:
            raise UnavailableGuard("natural source or Authority barrier differs; HOLD")
        source = provide_source_grant_check(
            intent, SourceGrantRead(
                snapshot, (final.material.audience_id,), "expression",
                covered, authority_current),
            valid_until=valid_until_utc)
        budget = inspect_current_d11_dispatch_budget(
            db, intent, d11_issuer=self.__d11_issuer,
            d02_issuer=self.__d02_issuer, now_utc=now_utc,
            natural_communication=True)
        checks = (social.role_receipt, social.boundary_receipt,
                  source, d08.receipt, budget.receipt)
        if (social.status != "checks_candidate"
                or budget.status != "check_pass"
                or any(item is None or (item.result, item.coverage)
                       != ("pass", "full") or item.valid_until < valid_until_utc
                       for item in checks)
                or tuple(item.check_kind for item in checks)
                   != tuple(spec.check_kind for spec in intent.required_checks)):
            raise UnavailableGuard("natural pregrant five checks unavailable; HOLD")
        return checks, social, d08

    def _read_post_c02_check_versions_locked(
            self, namespace: NamespaceId, route, route_binding, source_ref: str,
            c02_operation_id: str, budget_grant, resource_quote, anchor, *,
            expected_query, now_utc: float, projected: bool,
            action_kind: str = "message"):
        """Freeze raw provider input versions from this SQL head, never PASS.

        ``projected`` predicts only E+1 query versions from the current E
        rows so D08's immutable action can be staged. The same reader must be
        called again on actual E+1 rows and the resulting action compared.
        """
        from .domains.d03 import ContextProvider, RoleBindingRequest
        from .memory_types import SourceRecord, access_key, source_key
        from .runtime.budget import get_budget_lease
        from .runtime.dispatch_budget_check import _observed_versions
        from .runtime.dispatch_current_projection import (
            derive_current_domain_reads, read_current_dispatch_projection,
        )
        from .runtime.dispatch_source_correction_barrier import (
            read_source_correction_barrier,
        )
        from .runtime.installed_dispatch_admission_issuer import (
            InstalledDispatchAdmissionIssuer,
        )
        from .runtime.post_c02_reply_action_v2 import (
            CurrentReplyCheckVersionV2, CurrentReplyCheckVersionsV2,
            post_c02_reply_action_ids_v2,
        )
        from .runtime_contracts import VersionedRef
        from .runtime.restore_anchor import RestoreAnchor

        store = self.__store
        db = store._db
        if (not store._lock._is_owned() or not db.in_transaction
                or route.namespace != namespace or route.source_ref != source_ref
                or route_binding.namespace != namespace
                or route_binding.source_ref != source_ref
                or route.c02_operation_id != c02_operation_id
                or type(anchor) is not RestoreAnchor
                or anchor.namespace != namespace_ref(namespace)):
            raise UnavailableGuard("current reply check versions lack graph transaction; HOLD")
        snapshot, query = self._dispatch_full_graph_snapshot_locked(namespace)
        if (route_binding.query != query
                or expected_query.namespace != namespace
                or expected_query.scope_ref != "all"
                or expected_query.revision != query.revision + int(projected)
                or action_kind not in {"message", "communication"}):
            raise UnavailableGuard("reply check query epoch differs; HOLD")
        issuer = self.__dispatch_admission_issuer
        context = (issuer._context
                   if type(issuer) is InstalledDispatchAdmissionIssuer else None)
        if type(context) is not ContextProvider:
            raise UnavailableGuard("installed D03 context provider unavailable; HOLD")
        projection = read_current_dispatch_projection(
            db, namespace, snapshot, query)
        request = RoleBindingRequest(
            f"persona:{namespace.persona_id}",
            route_binding.target_entity_ref,
            None, route.scene_ref, action_kind, "expression", now_utc, True)
        role_read, boundary_read = derive_current_domain_reads(
            db, projection, request, context)
        if (projection.coverage != "full" or role_read.status != "complete"
                or boundary_read.coverage != "full"):
            raise UnavailableGuard("current D03/D05 reply versions unavailable; HOLD")
        graph = {atom.key: atom for atom in snapshot.atoms}
        source = AtomKey.from_token(source_ref)
        if source != source_key(
                *namespace.as_tuple, source.owner.subject or ""):
            raise UnavailableGuard("reply source is not canonical; HOLD")
        pending = [source.owner.subject or ""]
        source_versions = {}
        while pending:
            source_id = pending.pop()
            key = source_key(*namespace.as_tuple, source_id)
            access = access_key(*namespace.as_tuple, source_id)
            source_atom, access_atom = graph.get(key), graph.get(access)
            if (source_atom is None or access_atom is None
                    or not source_atom.valid or not access_atom.valid):
                raise UnavailableGuard("reply source ancestor or access absent; HOLD")
            if key.token in source_versions:
                continue
            record = SourceRecord.from_dict(source_atom.value)
            if record.source_id != source_id:
                raise UnavailableGuard("reply source ancestor identity differs; HOLD")
            source_versions[key.token] = source_atom.revision
            source_versions[access.token] = access_atom.revision
            pending.extend(record.parent_source_ids)
        barrier = read_source_correction_barrier(
            db, namespace, query, tuple(sorted(
                ref for ref in source_versions if AtomKey.from_token(ref).type_name
                == "memory.source")), dependent_ref=source_ref)
        if barrier.missing_sources:
            raise UnavailableGuard("reply source correction barrier changed; HOLD")
        source_revision = source_versions[source_ref]
        role_versions = (
            VersionedRef(source_ref, source_revision),
            VersionedRef("d03.role_binding", expected_query.revision),
        ) + tuple(sorted((
            VersionedRef(item.key.name, item.revision)
            for item in role_read.read_versions
            if item.key.name in set(role_read.matched_bindings)),
            key=lambda item: item.ref))
        boundary_versions = (
            VersionedRef(source_ref, source_revision),
            VersionedRef("d05.boundary", expected_query.revision),
        ) + tuple(VersionedRef(rule.rule_id, rule.scope_version)
                  for rule in boundary_read.rules)
        goal_id, action_id, _ = post_c02_reply_action_ids_v2(
            c02_operation_id, source_ref)
        d08_versions = (
            VersionedRef("d08.commitment_conflict.criteria.v1", 1),
            VersionedRef(goal_id, 1),
            VersionedRef(f"commitments-query:persona:{namespace.persona_id}",
                         expected_query.revision),
            VersionedRef(f"execution-epoch:{action_id}", anchor.execution_seq),
            VersionedRef(f"cancellation-epoch:{action_id}", 1),
        )
        if (self.__d11_issuer.current_budget_grant(
                db, budget_grant.lease_id) != budget_grant
                or self.__d02_issuer._load_quote(
                    db, resource_quote.quote_id,
                    resource_quote.version) != resource_quote):
            raise UnavailableGuard("reply signed D02/D11 issuer state differs; HOLD")
        reservation = db.execute(
            "SELECT digest,state FROM runtime_budget_reservations "
            "WHERE lease_id=? AND operation_id=?",
            (budget_grant.lease_id, resource_quote.operation_id)).fetchone()
        if reservation is None or reservation[1] != "reserved":
            raise UnavailableGuard("reply dispatch reservation unavailable; HOLD")
        lease = get_budget_lease(db, budget_grant.lease_id)
        observed_budget = _observed_versions(
            db, lease, resource_quote.operation_id, reservation[0])
        budget_versions = (
            VersionedRef(f"d02.resource_quote:{resource_quote.quote_id}",
                         resource_quote.version),
        ) + observed_budget + (
            VersionedRef(f"d11.budget.grant:{budget_grant.lease_id}",
                         budget_grant.version),)
        return CurrentReplyCheckVersionsV2(
            namespace, expected_query, source_ref, resource_quote.quote_id,
            resource_quote.version, budget_grant.grant_id,
            budget_grant.version, reservation[0], (
                CurrentReplyCheckVersionV2(
                    "role_binding", source_ref, role_versions),
                CurrentReplyCheckVersionV2(
                    "boundary", source_ref, boundary_versions),
                CurrentReplyCheckVersionV2(
                    "source_grant", source_ref,
                    tuple(VersionedRef(ref, version)
                          for ref, version in sorted(source_versions.items()))),
                CurrentReplyCheckVersionV2(
                    "commitment_conflict",
                    "d08.commitment_conflict.criteria.v1", d08_versions),
                CurrentReplyCheckVersionV2(
                    "dispatch_budget",
                    f"d02.resource_quote:{resource_quote.quote_id}",
                    budget_versions),
            ))

    def _stage_natural_final_pregrant_locked(
            self, *, envelope, final, route, original_scope_proof,
            budget_grant, resource_quote, scope, current_effect,
            effect_snapshot, expected_access_delete_epoch: tuple[int, int],
            now_utc: float):
        """Stage D08 at E+1 and issue five checks before freezing a grant.

        The provisional graph savepoint is rolled back before return. The
        final bundle's receipt hook must reissue every check on committed E+1.
        """
        from .runtime.natural_final_admission_v2 import (
            prepare_natural_final_action_stage_v2,
        )
        from .runtime.reply_entity_route_v2 import (
            read_current_reply_entity_route_binding_v2,
        )
        from .runtime_contracts import QueryEpoch

        namespace = envelope.authority.namespace
        db = self.__store._db
        if (not self.__store._lock._is_owned() or not db.in_transaction
                or scope.namespace != namespace or scope.operation != "write"
                or final.material is None
                or envelope.identity.operation_id !=
                   final.material.final_operation_id):
            raise UnavailableGuard("natural final stage lacks write fence; HOLD")
        snapshot, query = self._dispatch_full_graph_snapshot_locked(namespace)
        if query.revision != scope.graph_epoch.revision:
            raise UnavailableGuard("natural final stage graph epoch changed; HOLD")
        original_binding = read_current_reply_entity_route_binding_v2(
            db, namespace, route, query, now_utc=now_utc)
        next_query = QueryEpoch(namespace, "all", query.revision + 1)
        projected = self._read_post_c02_check_versions_locked(
            namespace, route, original_binding,
            final.material.source_ref.ref, final.material.c02_operation_id,
            budget_grant, resource_quote, scope.pinned_anchor,
            expected_query=next_query, now_utc=now_utc, projected=True,
            action_kind="communication")
        stage = prepare_natural_final_action_stage_v2(
            envelope=envelope, final=final,
            current_check_versions=projected,
            route_binding=original_binding, quote=resource_quote,
            grant=budget_grant, anchor=scope.pinned_anchor,
            now_utc=now_utc)
        if (stage.status != "candidate_hold_w01_current_five_checks"
                or stage.proposal is None or stage.intent is None
                or stage.schema is None
                or len(stage.proposal.typed_writes) != 4
                or stage.proposal.envelope.version_guard.query_epochs
                   != (query,)):
            raise UnavailableGuard("natural final D08 stage unavailable; HOLD")
        candidate = GraphCandidate(
            Event(Scope(*namespace.as_tuple, envelope.identity.activity_id),
                  envelope.identity.operation_id, float(now_utc),
                  "domain_bundle", {"natural_provisional_action":
                                    canonical_digest(stage.intent)}),
            stage.proposal.envelope.version_guard.read_versions,
            stage.proposal.typed_writes, snapshot.epochs)
        with self.__store._provisional_graph_stage_in_transaction(
                candidate, _capability=self.__graph_capability):
            staged_snapshot, staged_query = self._dispatch_full_graph_snapshot_locked(
                namespace)
            staged_binding = read_current_reply_entity_route_binding_v2(
                db, namespace, route, staged_query, now_utc=now_utc)
            actual = self._read_post_c02_check_versions_locked(
                namespace, route, staged_binding,
                final.material.source_ref.ref, final.material.c02_operation_id,
                budget_grant, resource_quote, scope.pinned_anchor,
                expected_query=staged_query, now_utc=now_utc,
                projected=False, action_kind="communication")
            if (staged_query != next_query or actual != projected
                    or staged_binding.binding_scan_versions !=
                       original_binding.binding_scan_versions):
                raise UnavailableGuard("natural final E+1 scope changed; HOLD")
            access_delete = db.execute(
                "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                "WHERE bot=? AND persona=?", namespace.as_tuple,
            ).fetchone()
            if access_delete != expected_access_delete_epoch:
                raise UnavailableGuard("natural paid access barrier changed; HOLD")
            checks, social, d08 = self._read_natural_pregrant_checks_locked(
                namespace, scope, current_effect, effect_snapshot,
                final, stage.intent, stage.schema, staged_binding,
                original_scope_proof, resource_quote,
                expected_access_delete_epoch=expected_access_delete_epoch,
                now_utc=now_utc,
                valid_until_utc=envelope.deadline_utc)
        return (stage, checks, social, d08, original_binding,
                staged_binding, projected)

    def _freeze_natural_final_grant_locked(
            self, final, plan, adopted, stage, checks, *, now_utc: float):
        """Freeze the payload grant from five checks issued in this graph tx.

        This only creates D08 graph material. Dispatch still needs the final
        graph receipt hook, signed D11 admission and later P2 effect claim.
        """
        from .domains.d08 import RequiredCheckRegistry
        from .domains.d08.natural_final import (
            prepare_natural_final_communication_candidate_v2,
        )

        if (not self.__store._lock._is_owned()
                or not self.__store._db.in_transaction
                or stage.intent is None or stage.schema is None
                or stage.proposal is None):
            raise UnavailableGuard("natural final grant lacks staged D08; HOLD")
        registry = RequiredCheckRegistry()
        registry.register(stage.schema)
        decision = registry.qualify(stage.intent, checks, now=now_utc)
        if decision.status != "qualified" or decision.valid_until is None:
            raise UnavailableGuard("natural final five checks unqualified; HOLD")
        intent_write = next((write for write in stage.proposal.typed_writes
                             if write.key.type_name == "d08.action_intent.v1"), None)
        if intent_write is None:
            raise UnavailableGuard("natural final action ref is absent; HOLD")
        refs = tuple("check:" + canonical_digest({
            "kind": spec.check_kind, "provider": spec.provider_id,
            "subject": spec.subject_ref, "action": spec.action_ref,
            "purpose": spec.purpose,
            "criteria_version": spec.criteria_version,
            "input_versions": spec.required_input_versions,
        }) for spec in stage.intent.required_checks)
        identity = {
            "schema": "sylanne.natural-final-communication.v2",
            "operation_id": final.material.final_operation_id,
            "effect_id": final.material.final_effect_id,
        }
        prefix = canonical_digest(identity)
        grant_id = "communication-grant:" + canonical_digest({
            **identity, "decision": decision.receipt_digest,
            "payload": final.material.payload_digest,
            "route": final.material.route_binding_digest,
        })
        candidate = prepare_natural_final_communication_candidate_v2(
            final, plan=plan, adopted=adopted, intent=stage.intent,
            intent_ref=intent_write.key.token, schema=stage.schema,
            contact_id="contact:" + prefix,
            communication_action_id="communication:" + prefix,
            grant_id=grant_id, batch_revision=1, cancellation_epoch=0,
            required_check_refs=refs,
            qualification_receipt_digest=decision.receipt_digest,
            valid_until=decision.valid_until)
        if candidate.status != "candidate_hold_w01_final_admission":
            raise UnavailableGuard("natural payload grant scope differs; HOLD")
        return candidate

    def _reissue_natural_final_after_graph_locked(
            self, *, bundle, final, paid, candidate, stage, scope, route,
            original_scope_proof, budget_grant, resource_quote,
            current_effect, effect_snapshot, provisional_checks,
            projected_check_versions, now_utc: float):
        """Recheck the committed E+1 natural batch before issuing admission.

        This runs in the graph receipt hook, before the outer SQLite COMMIT.
        The original paid review remains a historical fact; current source,
        private-route predicates, five checks and signed D11 state are fresh.
        """
        from .runtime.dispatch_current_projection import (
            read_current_dispatch_projection,
        )
        from .runtime.natural_final_issuer_v2 import (
            inspect_natural_final_d11_v2,
        )
        from .runtime.d12_current_d09_policy_v1 import (
            read_current_d09_expression_policy_v1,
        )
        from .runtime.natural_scoped_query_proof_v2 import (
            assert_natural_scoped_query_current_v2,
        )
        from .runtime.reply_entity_route_v2 import (
            read_current_reply_entity_route_binding_v2,
        )

        namespace = bundle.envelope.authority.namespace
        db = self.__store._db
        if (not self.__store._lock._is_owned() or not db.in_transaction
                or scope.namespace != namespace or scope.operation != "write"
                or final.material is None or stage.intent is None
                or stage.schema is None
                or candidate.operation_id != final.material.final_operation_id):
            raise UnavailableGuard("natural final receipt lacks write fence; HOLD")
        snapshot, query = self._dispatch_full_graph_snapshot_locked(namespace)
        if query.revision != scope.graph_epoch.revision + 1:
            raise UnavailableGuard("natural final receipt graph epoch differs; HOLD")
        expression_policy = read_current_d09_expression_policy_v1(db, namespace)
        if (expression_policy.active_head_ref not in
                bundle.envelope.version_guard.read_versions
                or (expression_policy.policy is not None
                    and len(final.material.segment.body) >
                    expression_policy.policy.max_visible_chars)):
            raise UnavailableGuard("natural expression policy changed; HOLD")
        assert_natural_scoped_query_current_v2(
            db, original_scope_proof, now_utc=now_utc)
        binding = read_current_reply_entity_route_binding_v2(
            db, namespace, route, query, now_utc=now_utc)
        from .domains.d08.natural_plan import natural_route_semantic_digest_v2
        if natural_route_semantic_digest_v2(binding) != (
                final.material.route_binding_digest):
            raise UnavailableGuard("natural final route semantic changed; HOLD")
        actual_versions = self._read_post_c02_check_versions_locked(
            namespace, route, binding, final.material.source_ref.ref,
            final.material.c02_operation_id, budget_grant, resource_quote,
            scope.pinned_anchor, expected_query=query, now_utc=now_utc,
            projected=False, action_kind="communication")
        if actual_versions != projected_check_versions:
            raise UnavailableGuard("natural final check inputs changed; HOLD")
        graph_atoms = {atom.key.token: atom for atom in snapshot.atoms}
        for item in paid.current_read_versions:
            if item.revision == 0:
                if db.execute(
                    "SELECT 1 FROM graph_atoms WHERE token=? AND bot=? AND persona=?",
                    (item.key.token, *namespace.as_tuple),
                ).fetchone() is not None:
                    raise UnavailableGuard("natural paid absent head changed; HOLD")
            elif (graph_atoms.get(item.key.token) is None
                  or not graph_atoms[item.key.token].valid
                  or graph_atoms[item.key.token].revision != item.revision):
                raise UnavailableGuard("natural paid source head changed; HOLD")
        checks, social, _d08 = self._read_natural_pregrant_checks_locked(
            namespace, scope, current_effect, effect_snapshot,
            final, stage.intent, stage.schema, binding,
            original_scope_proof, resource_quote,
            expected_access_delete_epoch=(paid.access_epoch, paid.delete_epoch),
            now_utc=now_utc, valid_until_utc=bundle.envelope.deadline_utc)
        if checks != provisional_checks or social.status != "checks_candidate":
            raise UnavailableGuard("natural final five checks changed; HOLD")
        runtime = inspect_natural_final_d11_v2(
            db, bundle, candidate, final, paid, checks,
            d11_issuer=self.__d11_issuer, now_utc=now_utc)
        projection = read_current_dispatch_projection(
            db, namespace, snapshot, query)
        return runtime, binding, snapshot, query, projection

    def _prepare_post_c02_reply_action_stage_locked(
            self, envelope, action_candidate, snapshot: GraphSnapshot,
            *, now_utc: float):
        """Build only the four D08 rows needed by the E+1 check readers.

        The returned graph candidate is suitable for the provisional savepoint.
        It carries no checks, communication grant, batch, or dispatch authority.
        """
        from .domains.d08 import GoalExecutionProvider
        from .runtime.post_c02_reply_action_v2 import PostC02ReplyActionCandidateV2
        from .runtime_contracts import DependencySet, DomainProposal, QueryEpoch

        store = self.__store
        if (not store._lock._is_owned() or not store._db.in_transaction
                or type(action_candidate) is not PostC02ReplyActionCandidateV2
                or action_candidate.status != "provisional"
                or action_candidate.goal is None
                or action_candidate.intent is None
                or action_candidate.schema is None
                or type(snapshot) is not GraphSnapshot
                or len(snapshot.epochs) != 1
                or type(now_utc) not in (int, float)
                or not math.isfinite(now_utc)):
            raise UnavailableGuard("provisional reply action stage is unavailable; HOLD")
        namespace = envelope.authority.namespace
        epoch = snapshot.epochs[0]
        if ((epoch.bot, epoch.persona) != namespace.as_tuple
                or envelope.identity != action_candidate.intent.identity
                or envelope.source_qualification.source_refs !=
                   action_candidate.intent.source_refs
                or envelope.version_guard.query_epochs !=
                   (QueryEpoch(namespace, "all", epoch.revision),)
                or set(snapshot.versions) -
                   set(envelope.version_guard.read_versions)):
            raise UnavailableGuard("provisional reply action read set differs; HOLD")
        provider = GoalExecutionProvider()
        empty = DomainProposal(
            "d08", "d08.proposal.v1", provider.descriptor.request_schema_hash,
            envelope, (), DependencySet(), (), ())
        goal = provider.prepare_goal_candidate(
            empty, action_candidate.goal,
            source_ref=envelope.source_qualification.source_refs[0])
        action = provider.prepare_action_candidate(
            goal, action_candidate.intent, action_candidate.schema)
        if (len(action.typed_writes) != 4
                or {item.key.type_name for item in action.typed_writes} != {
                    "d08.goal.v1", "d08.action_intent.v1",
                    "d08.action_schema.v1", "d08.action_cancellation.v1"
                } or any(item.key in {atom.key for atom in snapshot.atoms}
                         for item in action.typed_writes)):
            raise UnavailableGuard("provisional reply action writes differ; HOLD")
        graph_candidate = GraphCandidate(
            Event(Scope(*namespace.as_tuple, envelope.identity.activity_id),
                  envelope.identity.operation_id, float(now_utc),
                  "domain_bundle", {"provisional_action_digest":
                                    canonical_digest(action_candidate)}),
            action.envelope.version_guard.read_versions,
            action.typed_writes, (epoch,))
        return action.envelope, action, graph_candidate

    def _stage_post_c02_reply_prebatch_locked(
            self, *, envelope, c02_receipt, route, source_ref,
            attention, focus, budget_grant, resource_quote, expression,
            anchor, scope, current_effect, effect_snapshot, now_utc: float):
        """Read a provisional E+1 action and five non-authorizing checks.

        The savepoint is gone before this method returns. Its output must be
        reissued from the final sealed rows in the receipt hook; no consumer
        may treat this result as a dispatch check or communication grant.
        """
        from .runtime.post_c02_reply_action_v2 import (
            issue_post_c02_reply_action_v2,
            prepare_post_c02_reply_action_provisional_v2,
        )
        from .runtime.reply_entity_route_v2 import (
            read_current_reply_entity_route_binding_v2,
        )
        from .runtime_contracts import QueryEpoch

        namespace = envelope.authority.namespace
        snapshot, query = self._dispatch_full_graph_snapshot_locked(namespace)
        original_route_binding = read_current_reply_entity_route_binding_v2(
            self.__store._db, namespace, route, query, now_utc=now_utc)
        projected_query = QueryEpoch(namespace, "all", query.revision + 1)
        projected = self._read_post_c02_check_versions_locked(
            namespace, route, original_route_binding, source_ref,
            c02_receipt.operation_id,
            budget_grant, resource_quote, anchor,
            expected_query=projected_query, now_utc=now_utc, projected=True)
        common = dict(
            envelope=envelope, c02_receipt=c02_receipt, route=route,
            route_binding=original_route_binding,
            source_ref=source_ref, attention=attention, focus=focus,
            budget_grant=budget_grant, resource_quote=resource_quote,
            expression=expression, anchor=anchor, now_utc=now_utc)
        provisional = prepare_post_c02_reply_action_provisional_v2(
            **common, snapshot=snapshot, expected_query=projected_query,
            projected_check_inputs=projected)
        if provisional.status != "provisional":
            raise UnavailableGuard(
                "provisional private reply action cannot be staged; HOLD")
        staged_envelope, action, graph_candidate = (
            self._prepare_post_c02_reply_action_stage_locked(
                envelope, provisional, snapshot, now_utc=now_utc))
        with self.__store._provisional_graph_stage_in_transaction(
                graph_candidate,
                _capability=self.__graph_capability):
            staged_snapshot, staged_query = (
                self._dispatch_full_graph_snapshot_locked(namespace))
            staged_route_binding = read_current_reply_entity_route_binding_v2(
                self.__store._db, namespace, route, staged_query,
                now_utc=now_utc)
            actual = self._read_post_c02_check_versions_locked(
                namespace, route, staged_route_binding, source_ref,
                c02_receipt.operation_id,
                budget_grant, resource_quote, anchor,
                expected_query=staged_query, now_utc=now_utc, projected=False)
            issued = issue_post_c02_reply_action_v2(
                **common, snapshot=staged_snapshot, query=staged_query,
                check_inputs=actual)
            if (issued.status != "candidate"
                    or issued != replace(provisional, status="candidate")):
                raise UnavailableGuard(
                    "actual staged reply action differs from provisional; HOLD")
            d08, social, source_check, budget_check = (
                self._read_post_c02_prebatch_checks_locked(
                    namespace, scope, current_effect, effect_snapshot,
                    issued.intent, issued.schema, expression, route,
                    original_route_binding, staged_route_binding,
                    resource_quote=resource_quote, now_utc=now_utc,
                    valid_until_utc=envelope.deadline_utc))
            checks = (social.role_receipt, social.boundary_receipt,
                      source_check, d08.receipt, budget_check)
            if (any(item is None or (item.result, item.coverage) !=
                    ("pass", "full") for item in checks)
                    or tuple(item.check_kind for item in checks) !=
                    tuple(spec.check_kind for spec in issued.intent.required_checks)):
                raise UnavailableGuard(
                    "actual staged reply checks are incomplete; HOLD")
            staged_grant = self._freeze_post_c02_reply_route_grant_locked(
                issued, checks, staged_route_binding, scope,
                staged_snapshot, now_utc)
            candidate = self._post_c02_check_candidate_from_reads(
                envelope, staged_query, anchor, scope, d08, social,
                staged_route_binding, checks)
        return (staged_envelope, action, issued, social, candidate,
                original_route_binding, staged_route_binding, staged_grant)

    def _freeze_post_c02_reply_route_grant_locked(
            self, action, checks, route_binding, scope, snapshot,
            now_utc: float):
        """Qualify five current SQL receipts and freeze one bound candidate."""
        from .domains.d08 import RequiredCheckRegistry

        if (not self.__store._lock._is_owned()
                or not self.__store._db.in_transaction
                or snapshot.epochs != (NamespaceEpoch(
                    *scope.namespace.as_tuple,
                    scope.graph_epoch.revision + 1),)):
            raise UnavailableGuard("reply route grant lacks staged graph head; HOLD")
        registry = RequiredCheckRegistry()
        registry.register(action.schema)
        decision = registry.qualify(action.intent, checks, now=now_utc)
        if decision.status != "qualified":
            raise UnavailableGuard("reply route checks are unqualified; HOLD")
        try:
            return registry.freeze_communication_grant_v2(
                action.intent, decision, action.communication,
                route_binding=route_binding, db=self.__store._db,
                snapshot=snapshot, scope=scope, now=now_utc)
        except (TypeError, ValueError) as exc:
            raise UnavailableGuard("current private route grant unavailable; HOLD") from exc

    @staticmethod
    def _post_c02_check_candidate_from_reads(
            envelope, query, anchor, scope, d08, social,
            route_binding, checks):
        from .runtime.dispatch_check_reissue import (
            NegativeQueryClosureV1, ProvisionalCheckCandidateV1,
        )
        from .runtime_contracts import VersionedRef

        positive = tuple(sorted(set(
            (*d08.positive_reads,
             *(VersionedRef(item.key.token, item.revision)
               for item in social.positive_reads),
             *(VersionedRef(item.key.token, item.revision)
               for item in (
                   route_binding.anchor_version,
                   route_binding.binding_version,
                   route_binding.arrival_event_version,
                   route_binding.binding_evidence_event_version,
                   route_binding.source_version,
                   route_binding.access_version,
                   *route_binding.binding_scan_versions)))),
            key=lambda item: (item.ref, item.version)))
        negative = tuple(NegativeQueryClosureV1(
            item.predicate_ref, item.query, item.scanned_versions,
            len(item.matching_refs), "full")
            for item in d08.negative_queries)
        return ProvisionalCheckCandidateV1(
            envelope.identity.activity_id, envelope.identity.operation_id,
            query.revision, anchor, d08.authority_snapshot_digest,
            scope.permit.token, positive, negative, checks)

    def _reissue_post_c02_reply_final_checks_locked(
            self, db, graph_receipt, scope, now_utc, *, envelope,
            c02_receipt, route, source_ref, attention, focus,
            budget_grant, resource_quote, expression, anchor,
            current_effect, effect_snapshot, expected_action,
            expected_social, expected_original_binding,
            expected_staged_binding, expected_grant, batch_ref):
        """Re-read five checks from the final graph rows, inside the seal hook."""
        from .domains.d03.prebatch_social import match_prebatch_batch_v1
        from .runtime.post_c02_reply_action_v2 import issue_post_c02_reply_action_v2
        from .runtime.reply_entity_route_v2 import (
            read_current_reply_entity_route_binding_v2,
        )

        namespace = envelope.authority.namespace
        if (db is not self.__store._db
                or not self.__store._lock._is_owned()
                or not db.in_transaction
                or graph_receipt.status != "committed"):
            raise UnavailableGuard("final reply check transaction is unavailable; HOLD")
        snapshot, query = self._dispatch_full_graph_snapshot_locked(namespace)
        final_route_binding = read_current_reply_entity_route_binding_v2(
            db, namespace, route, query, now_utc=now_utc)
        if (final_route_binding != expected_staged_binding
                or final_route_binding.query.revision !=
                   expected_original_binding.query.revision + 1
                or tuple((v.key, v.revision) for v in (
                    final_route_binding.anchor_version,
                    final_route_binding.binding_version,
                    final_route_binding.arrival_event_version,
                    final_route_binding.binding_evidence_event_version,
                    final_route_binding.source_version,
                    final_route_binding.access_version)) != tuple(
                    (v.key, v.revision) for v in (
                        expected_original_binding.anchor_version,
                        expected_original_binding.binding_version,
                        expected_original_binding.arrival_event_version,
                        expected_original_binding.binding_evidence_event_version,
                        expected_original_binding.source_version,
                        expected_original_binding.access_version))
                or final_route_binding.binding_scan_versions !=
                   expected_original_binding.binding_scan_versions):
            raise UnavailableGuard("final reply account route differs; HOLD")
        actual = self._read_post_c02_check_versions_locked(
            namespace, route, final_route_binding, source_ref,
            c02_receipt.operation_id,
            budget_grant, resource_quote, anchor,
            expected_query=query, now_utc=now_utc, projected=False)
        issued = issue_post_c02_reply_action_v2(
            envelope=envelope, c02_receipt=c02_receipt, route=route,
            route_binding=expected_original_binding,
            source_ref=source_ref, snapshot=snapshot, query=query,
            attention=attention, focus=focus, budget_grant=budget_grant,
            resource_quote=resource_quote, expression=expression,
            anchor=anchor, now_utc=now_utc, check_inputs=actual)
        if issued != expected_action:
            raise UnavailableGuard("final reply action differs from staged input; HOLD")
        d08, social, source_check, budget_check = (
            self._read_post_c02_prebatch_checks_locked(
                namespace, scope, current_effect, effect_snapshot,
                issued.intent, issued.schema, expression, route,
                expected_original_binding, final_route_binding,
                resource_quote=resource_quote, now_utc=now_utc,
                valid_until_utc=envelope.deadline_utc))
        batch_key = AtomKey.from_token(batch_ref)
        batch = snapshot.get(batch_key)
        if (social != expected_social or batch is None or not batch.valid
                or not match_prebatch_batch_v1(social, batch.value)):
            raise UnavailableGuard("final reply social batch differs; HOLD")
        checks = (social.role_receipt, social.boundary_receipt,
                  source_check, d08.receipt, budget_check)
        if (any(item is None or (item.result, item.coverage) !=
                ("pass", "full") for item in checks)
                or tuple(item.check_kind for item in checks) !=
                tuple(spec.check_kind for spec in issued.intent.required_checks)):
            raise UnavailableGuard("final reply check set differs; HOLD")
        final_grant = self._freeze_post_c02_reply_route_grant_locked(
            issued, checks, final_route_binding, scope, snapshot, now_utc)
        if final_grant != expected_grant:
            raise UnavailableGuard("final reply route grant differs; HOLD")
        from .runtime.dispatch_check_reissue import PostC02FinalReissueV2

        return PostC02FinalReissueV2(
            self._post_c02_check_candidate_from_reads(
                envelope, query, anchor, scope, d08, social,
                final_route_binding, checks),
            final_route_binding, social, d08, final_grant, issued,
            graph_receipt,
        )

    def _prepare_post_c02_reply_dispatch_locked(
            self, *, authority: AuthorityContext, scope: FenceScope,
            installed_bundle, progress, clock_reading, current_effect,
            effect_snapshot, now_utc: float,
            frozen_deadline_utc: float | None = None):
        """Reserve one graph-derived message candidate in the outer write tx.

        The staged checks returned here have no dispatch authority. Failure
        must roll back the caller's entire transaction, including quote, job,
        and reservation rows.
        """
        from .host.authority_profile import (
            AdminInstallationBundle, AdminPrivateReplyDispatchPolicy,
        )
        from .host.installed_reply_model_driver import (
            InstalledReplyProgressV1,
            issue_installed_post_c02_source_expression_v1,
        )
        from .host.post_c02_reply_driver import post_c02_reply_operation_id
        from .host.v2_fence_port import VerifiedIngressClockV2
        from .runtime.jobs import create_job
        from .runtime.issuers import D02ResourceIssuer, D11BudgetJobIssuer
        from .runtime.post_c02_reply_bundle_v2 import (
            post_c02_dispatch_runtime_refs_v2,
            prepare_post_c02_reply_bundle_candidate_v2,
        )
        from .runtime.reply_model_job import read_saved_reply_job_v1
        from .runtime_contracts import OperationIdentity, QueryEpoch, VersionedRef

        store = self.__store
        db = store._db
        policy = (installed_bundle.private_reply_dispatch
                  if type(installed_bundle) is AdminInstallationBundle else None)
        if (not store._lock._is_owned() or not db.in_transaction
                or type(scope) is not FenceScope or scope.operation != "write"
                or type(progress) is not InstalledReplyProgressV1
                or type(policy) is not AdminPrivateReplyDispatchPolicy
                or type(clock_reading) is not VerifiedIngressClockV2
                or type(self.__d02_issuer) is not D02ResourceIssuer
                or type(self.__d11_issuer) is not D11BudgetJobIssuer
                or progress.cost is None or progress.candidate is None
                or progress.result_read is None
                or type(now_utc) not in (int, float)
                or not math.isfinite(now_utc)
                or authority.namespace != scope.namespace
                or authority.purpose != "expression"
                or installed_bundle.installation_policy.namespace !=
                   authority.namespace):
            raise UnavailableGuard("installed private reply assembly inputs absent; HOLD")
        prep = progress.run.preparation
        source_ref = prep.source.source_ref
        c02_operation_id = prep.c02_receipt.operation_id
        operation_id = post_c02_reply_operation_id(c02_operation_id, source_ref)
        if (progress.cost.status != "committed"
                or progress.cost.call_id != prep.installed.request.call_id
                or progress.candidate.model_request_digest !=
                   prep.installed.request.digest
                or progress.result_read.request.consumer_operation_id !=
                   operation_id
                or (scope.graph_epoch.bot, scope.graph_epoch.persona)
                   != authority.namespace.as_tuple
                or scope.pinned_anchor.namespace !=
                   namespace_ref(authority.namespace)):
            raise UnavailableGuard("original reply result or write scope differs; HOLD")
        epoch = scope.graph_epoch
        inputs, route = self._current_post_c02_reply_route_locked(
            authority.namespace, c02_operation_id, source_ref, now_utc, epoch)
        if (inputs.c02_receipt != prep.c02_receipt
                or inputs.source != prep.source
                or inputs.attention.ticket != prep.attention
                or inputs.attention.focus_version.revision != prep.focus_revision
                or prep.envelope.version_guard.focus_lease_versions != (
                    VersionedRef(inputs.attention.ticket_version.key.token,
                                 inputs.attention.ticket_version.revision),)
                or authority.audience != (route.conversation_ref,)):
            raise UnavailableGuard("original C02 source, attention or route changed; HOLD")
        snapshot, query = self._dispatch_full_graph_snapshot_locked(
            authority.namespace)
        access_delete = db.execute(
            "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
            "WHERE bot=? AND persona=?", authority.namespace.as_tuple,
        ).fetchone()
        if (query.revision != epoch.revision or access_delete is None
                or tuple(access_delete) != (
                    prep.envelope.version_guard.access_epoch,
                    prep.envelope.version_guard.delete_epoch)):
            raise UnavailableGuard("reply access/delete epoch changed; HOLD")
        deadline = (frozen_deadline_utc if frozen_deadline_utc is not None else
                    min(now_utc + policy.deadline_after_seconds,
                        installed_bundle.installation_policy.root_grant.valid_until_utc))
        if (type(deadline) not in (int, float) or not math.isfinite(deadline)
                or deadline > now_utc + policy.deadline_after_seconds
                or deadline > installed_bundle.installation_policy.root_grant.valid_until_utc):
            raise UnavailableGuard("reply dispatch frozen deadline differs; HOLD")
        monotonic_deadline = (clock_reading.monotonic_after_seconds
                              + deadline - clock_reading.utc_upper_bound_seconds)
        if (not now_utc < deadline or not time.monotonic() < monotonic_deadline):
            raise UnavailableGuard("installed reply dispatch deadline elapsed; HOLD")
        identity = OperationIdentity(
            prep.c02_receipt.activity_id, None,
            "post-c02-reply-attempt:" + canonical_digest({
                "operation_id": operation_id,
                "model_request": prep.installed.request.digest,
            })[:40],
            "post_c02_reply_dispatch", operation_id,
            canonical_digest({"input_refs": [source_ref]}))
        guard = replace(
            prep.envelope.version_guard,
            read_versions=snapshot.versions,
            query_epochs=(query,),
            # The model proposal's focus ref names a D07 graph ticket, not a
            # separately issued focus lease.  The current ticket and focus
            # are guarded by the full graph read set for this expression.
            focus_lease_versions=(),
            resource_lease_versions=(),
        )
        preliminary = replace(
            prep.envelope, identity=identity, authority=authority,
            version_guard=guard,
            source_qualification=prep.envelope.source_qualification,
            input_refs=(source_ref,),
            parent_budget_lease_ref=
                installed_bundle.installation_policy.root_grant.lease_id,
            deadline_utc=deadline,
            monotonic_deadline=monotonic_deadline,
            causation=(c02_operation_id,))
        queued = read_saved_reply_job_v1(
            db, self.__d02_issuer, authority.namespace,
            c02_operation_id, source_ref)
        if queued is None:
            raise UnavailableGuard("original signed reply job absent; HOLD")
        self._verify_paid_reply_model_cost_locked(
            authority.namespace, queued, progress)
        try:
            expression = issue_installed_post_c02_source_expression_v1(
                queued, progress, current_source=inputs.source,
                current_envelope=preliminary, scene_ref=route.scene_ref,
                covered_slots=("reply",), max_chars=policy.segment_max_chars)
        except ValueError as exc:
            raise UnavailableGuard(
                "paid original reply result differs from graph job; HOLD") from exc
        if (len(expression.segments) != 1
                or not expression.segments[0].effect_id):
            raise UnavailableGuard("reply expression effect identity absent; HOLD")
        identity = replace(identity, effect_id=expression.segments[0].effect_id)
        job_ref, outbox_ref, _ = post_c02_dispatch_runtime_refs_v2(
            authority.namespace, identity)
        grant = installed_bundle.installation_policy.root_grant
        quote = self.__d11_issuer.issue_private_reply_dispatch_quote_v2(
            db, policy=policy, namespace=authority.namespace,
            identity=identity, parent_grant=grant,
            deadline_utc=deadline, graph_job_ref=job_ref,
            outbox_refs=(outbox_ref,), now_utc=now_utc)
        db.execute(
            "INSERT OR IGNORE INTO graph_guard_versions"
            "(bot,persona,kind,ref,version) VALUES(?,?,?,?,?)",
            authority.namespace.as_tuple + (
                "resource_lease", quote.quote_id, str(quote.version)),
        )
        if self._version(db, authority.namespace, "resource_lease",
                         quote.quote_id) != str(quote.version):
            raise UnavailableGuard("reply signed quote graph guard differs; HOLD")
        final_guard = replace(
            guard, resource_lease_versions=(VersionedRef(
                quote.quote_id, quote.version),))
        envelope = replace(preliminary, identity=identity,
                           version_guard=final_guard)
        budget_digest = budget_operation_digest(
            envelope, grant.lease_id, dict(quote.ceiling))
        reserve_budget(db, grant.lease_id, operation_id,
                       budget_digest, quote.ceiling)
        job = replace(
            self.__d11_issuer.job_for(envelope, db, now_utc=now_utc),
            phase="waiting", wake_condition={
                "kind": "post_c02_reply_host_takeover",
                "operation_id": operation_id,
            })
        if job_ref != AtomKey(
                Owner("activity", *authority.namespace.as_tuple,
                      identity.activity_id), "runtime.job", job.job_id).token:
            raise UnavailableGuard("reply reserved job ref differs; HOLD")
        create_job(
            db, job, "job:" + canonical_digest({
                "reply_operation_id": operation_id, "job_ref": job_ref,
            })[:48], canonical_digest(job))
        staged = self._stage_post_c02_reply_prebatch_locked(
            envelope=envelope, c02_receipt=inputs.c02_receipt,
            route=route, source_ref=source_ref,
            attention=inputs.attention.ticket, focus=inputs.attention.focus,
            budget_grant=grant, resource_quote=quote, expression=expression,
            anchor=scope.pinned_anchor, scope=scope,
            current_effect=current_effect, effect_snapshot=effect_snapshot,
            now_utc=now_utc)
        (staged_envelope, staged_d08, action, social, candidate,
         original_route_binding, staged_route_binding,
         staged_grant) = staged
        bundle_candidate = prepare_post_c02_reply_bundle_candidate_v2(
            envelope=staged_envelope, action=action,
            staged_d08=staged_d08, checks=candidate.checks,
            expression=expression, route=route,
            route_binding=staged_route_binding,
            pre_frozen_grant=staged_grant, quote=quote,
            budget_grant=grant, pre_reserved_job=job,
            now_utc=now_utc, conversation_epoch=candidate.graph_epoch)
        if (bundle_candidate.status != "candidate"
                or bundle_candidate.job != job
                or bundle_candidate.job_ref != job_ref
                or bundle_candidate.outbox_ref != outbox_ref):
            raise UnavailableGuard("reply bundle candidate differs; HOLD")
        return (inputs, route, envelope, expression, grant, quote,
                job, staged, bundle_candidate)

    def _preview_post_c02_reply_effect_locked(
            self, *, authority: AuthorityContext, progress,
            installed_bundle, clock_reading, now_utc: float,
            epoch: NamespaceEpoch, frozen_deadline_utc: float):
        """Read a non-authorizing effect/input fingerprint before P2.

        The eventual write transaction must re-read and reproduce this exact
        source expression.  No check receipt or dispatch authority is issued.
        """
        from .host.authority_profile import (
            AdminInstallationBundle, AdminPrivateReplyDispatchPolicy,
        )
        from .host.installed_reply_model_driver import (
            InstalledReplyProgressV1,
            issue_installed_post_c02_source_expression_v1,
        )
        from .host.post_c02_reply_driver import post_c02_reply_operation_id
        from .runtime.reply_model_job import read_saved_reply_job_v1
        from .runtime.reply_entity_route_v2 import (
            read_current_reply_entity_route_binding_v2,
        )
        from .runtime_contracts import OperationIdentity, VersionedRef

        store = self.__store
        db = store._db
        policy = (installed_bundle.private_reply_dispatch
                  if type(installed_bundle) is AdminInstallationBundle else None)
        if (not store._lock._is_owned() or not db.in_transaction
                or type(progress) is not InstalledReplyProgressV1
                or type(policy) is not AdminPrivateReplyDispatchPolicy
                or authority.namespace.as_tuple != (epoch.bot, epoch.persona)
                or authority.purpose != "expression"
                or progress.candidate is None or progress.result_read is None
                or progress.cost is None):
            raise UnavailableGuard("reply effect preview lacks current inputs; HOLD")
        prep = progress.run.preparation
        source_ref = prep.source.source_ref
        c02_op = prep.c02_receipt.operation_id
        inputs, route = self._current_post_c02_reply_route_locked(
            authority.namespace, c02_op, source_ref, now_utc, epoch)
        snapshot, query = self._dispatch_full_graph_snapshot_locked(
            authority.namespace)
        binding = read_current_reply_entity_route_binding_v2(
            db, authority.namespace, route, query, now_utc=now_utc)
        queued = read_saved_reply_job_v1(
            db, self.__d02_issuer, authority.namespace, c02_op, source_ref)
        if (queued is None or prep.c02_receipt != inputs.c02_receipt
                or prep.source != inputs.source
                or prep.attention != inputs.attention.ticket
                or prep.focus_revision != inputs.attention.focus_version.revision
                or prep.envelope.version_guard.focus_lease_versions != (
                    VersionedRef(inputs.attention.ticket_version.key.token,
                                 inputs.attention.ticket_version.revision),)
                or authority.audience != (route.conversation_ref,)):
            raise UnavailableGuard("reply effect preview changed original route; HOLD")
        self._verify_paid_reply_model_cost_locked(
            authority.namespace, queued, progress)
        operation_id = post_c02_reply_operation_id(c02_op, source_ref)
        identity = OperationIdentity(
            prep.c02_receipt.activity_id, None,
            "post-c02-reply-attempt:" + canonical_digest({
                "operation_id": operation_id,
                "model_request": prep.installed.request.digest,
            })[:40],
            "post_c02_reply_dispatch", operation_id,
            canonical_digest({"input_refs": [source_ref]}))
        deadline = frozen_deadline_utc
        if (type(deadline) not in (int, float) or not math.isfinite(deadline)
                or not now_utc < deadline
                or deadline > now_utc + policy.deadline_after_seconds
                or deadline > installed_bundle.installation_policy.root_grant.valid_until_utc):
            raise UnavailableGuard("reply effect preview deadline changed; HOLD")
        monotonic_deadline = (clock_reading.monotonic_after_seconds + deadline
                              - clock_reading.utc_upper_bound_seconds)
        preliminary = replace(
            prep.envelope, identity=identity, authority=authority,
            version_guard=replace(
                prep.envelope.version_guard,
                read_versions=snapshot.versions, query_epochs=(query,),
                focus_lease_versions=(),
                resource_lease_versions=()),
            source_qualification=prep.envelope.source_qualification,
            input_refs=(source_ref,),
            parent_budget_lease_ref=
                installed_bundle.installation_policy.root_grant.lease_id,
            deadline_utc=deadline, monotonic_deadline=monotonic_deadline,
            causation=(c02_op,))
        try:
            expression = issue_installed_post_c02_source_expression_v1(
                queued, progress, current_source=inputs.source,
                current_envelope=preliminary, scene_ref=route.scene_ref,
                covered_slots=("reply",), max_chars=policy.segment_max_chars)
        except ValueError as exc:
            raise UnavailableGuard("reply effect preview content differs; HOLD") from exc
        if (len(expression.segments) != 1
                or not expression.segments[0].effect_id):
            raise UnavailableGuard("reply effect preview has no single effect; HOLD")
        return (inputs, route, binding, expression)

    def _verify_paid_reply_model_cost_locked(
            self, namespace: NamespaceId, queued, progress) -> None:
        """Join host result-read to the original durable D11 cost seal."""
        from .runtime.model_cost_settlement import (
            OriginalModelCostCommitV1, original_model_cost_operation_id_v1,
        )
        from .runtime.d11_types import runtime_cost_settlement_key

        db = self.__store._db
        if not self.__store._lock._is_owned() or not db.in_transaction:
            raise UnavailableGuard("reply cost lacks graph transaction; HOLD")
        prep = progress.run.preparation
        cost = progress.cost
        cost_operation_id = original_model_cost_operation_id_v1(
            namespace, prep.intent.call_id)
        if (type(cost) is not OriginalModelCostCommitV1
                or cost.status != "committed"
                or cost.operation_id != cost_operation_id
                or cost.call_id != prep.intent.call_id
                or (cost.quote_id, cost.quote_version) != (
                    queued.quote.quote_id, queued.quote.version)):
            raise UnavailableGuard("original reply cost identity differs; HOLD")
        row = db.execute(
            "SELECT activity_id,commit_seq,receipt_json FROM "
            "graph_bundle_operations WHERE bot=? AND persona=? "
            "AND operation_id=?",
            namespace.as_tuple + (cost_operation_id,),
        ).fetchone()
        if row is None:
            raise UnavailableGuard("original reply cost ledger absent; HOLD")
        data = json.loads(row[2])
        event = db.execute(
            "SELECT revisions,epoch_revision FROM graph_events WHERE bot=? "
            "AND persona=? AND session=? AND event_id=?",
            namespace.as_tuple + (row[0], cost_operation_id),
        ).fetchone()
        cost_versions = (tuple(item.revision
                               for item in GraphStore._version_rows(event[0])
                               if item.key.token == cost.cost_ref)
                         if event is not None else ())
        atom = db.execute(
            "SELECT revision,valid,type_name,value FROM graph_atoms WHERE token=? "
            "AND bot=? AND persona=?",
            (cost.cost_ref, *namespace.as_tuple),
        ).fetchone()
        budget = db.execute(
            "SELECT receipt_json FROM runtime_budget_operations WHERE "
            "bot_id=? AND persona_id=? AND operation_id=? AND phase='settle'",
            namespace.as_tuple + (queued.original_operation_id,),
        ).fetchone()
        metadata, epoch = self._v2_graph_stamp(namespace)
        cost_value = (json.loads(atom[3]) if atom is not None else None)
        expected_cost_ref = runtime_cost_settlement_key(
            *namespace.as_tuple, row[0], cost_operation_id).token
        if (data.get("original_model_cost") != asdict(cost)
                or data.get("original_intent_digest") !=
                   canonical_digest(asdict(prep.intent))
                or data.get("terminal_receipt_digest") !=
                   cost.terminal_receipt_digest
                or row[1] != cost.commit_seq
                or metadata.graph_revision < cost.graph_revision
                or epoch.revision < cost.graph_epoch
                or event is None or event[1] != cost.graph_epoch
                or len(cost_versions) != 1
                or atom is None or atom[:3] != (
                    cost_versions[0], 1, "runtime.cost_settlement")
                or cost.cost_ref != expected_cost_ref
                or budget is None
                or not isinstance(cost_value, dict)
                or canonical_digest(json.loads(budget[0])) !=
                   cost.budget_receipt_digest
                or cost_value.get("bundle_operation_id") != cost_operation_id
                or cost_value.get("settlement_id") != cost_operation_id
                or cost_value.get("cost_operation_id") !=
                   queued.original_operation_id
                or cost_value.get("budget_operation_id") !=
                   queued.original_operation_id
                or cost_value.get("budget_phase") != "settle"
                or cost_value.get("lease_id") !=
                   queued.quote.parent_budget_lease_ref
                or cost_value.get("activity_id") != row[0]
                or cost_value.get("effect_id") != queued.quote.effect_id
                or cost_value.get("budget_receipt_digest") !=
                   hashlib.sha256(budget[0].encode("utf-8")).hexdigest()):
            raise UnavailableGuard("original reply cost graph or budget differs; HOLD")

    def _open_post_c02_reply_dispatch_attempt_locked(
            self, *, namespace: NamespaceId, operation_id: str,
            ingress_operation_id: str,
            handler_invocation_id: str, request_digest: str,
            input_digest: str,
            handler_deadline_utc: float, frozen_deadline_utc: float,
            metadata, epoch: NamespaceEpoch,
            anchor) -> str:
        """Persist a pre-P2 identity without pretending the bundle exists yet.

        A prior open attempt is intentionally HOLD until exact same-permit
        recovery is implemented.  It must never mint a second P2 permit.
        """
        store = self.__store
        db = store._db
        if (not store._lock._is_owned() or db.in_transaction
                or not isinstance(store, ProductionGraphStore)
                or not operation_id or not handler_invocation_id
                or len(request_digest) != 64
                or len(input_digest) != 64
                or not math.isfinite(handler_deadline_utc)
                or not math.isfinite(frozen_deadline_utc)
                or frozen_deadline_utc > handler_deadline_utc
                or self._v2_graph_stamp(namespace) != (metadata, epoch)
                or not self._anchor_matches(metadata.requirements, anchor)):
            raise UnavailableGuard("reply dispatch attempt lacks frozen pre-P2 head; HOLD")
        attempt_id = "post-c02-dispatch-write:" + canonical_digest({
            "namespace": list(namespace.as_tuple),
            "operation_id": operation_id,
            "input_digest": input_digest,
        })[:48]
        db.execute("BEGIN IMMEDIATE")
        try:
            self._require_reply_host_available_locked(
                namespace, ingress_operation_id, handler_invocation_id)
            db.execute("""CREATE TABLE IF NOT EXISTS graph_post_c02_reply_dispatch_attempts_v2(
                bot TEXT NOT NULL, persona TEXT NOT NULL,
                operation_id TEXT NOT NULL, handler_invocation_id TEXT NOT NULL,
                request_digest TEXT NOT NULL, input_digest TEXT NOT NULL,
                attempt_id TEXT NOT NULL,
                handler_deadline_utc REAL NOT NULL,
                frozen_deadline_utc REAL NOT NULL, anchor_json TEXT NOT NULL,
                pre_graph_revision INTEGER NOT NULL, pre_graph_epoch INTEGER NOT NULL,
                state TEXT NOT NULL, bundle_digest TEXT,
                permit_json TEXT, finish_request_id TEXT,
                finish_request_digest TEXT,
                PRIMARY KEY(bot,persona,operation_id))""")
            prior = db.execute(
                "SELECT handler_invocation_id,request_digest,input_digest,attempt_id,"
                "handler_deadline_utc,frozen_deadline_utc,anchor_json,pre_graph_revision,"
                "pre_graph_epoch,state FROM graph_post_c02_reply_dispatch_attempts_v2 "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone()
            expected = (handler_invocation_id, request_digest,
                        input_digest, attempt_id,
                        handler_deadline_utc, frozen_deadline_utc,
                        canonical_json(asdict(anchor)),
                        metadata.graph_revision, epoch.revision)
            if prior is not None:
                if prior[:9] != expected:
                    raise EventConflict("reply dispatch attempt identity changed")
                raise UnavailableGuard(
                    "reply dispatch attempt awaits same-permit recovery; HOLD")
            if self._v2_graph_stamp(namespace) != (metadata, epoch):
                raise StaleRead("reply dispatch graph moved before P2 intent")
            db.execute(
                "INSERT INTO graph_post_c02_reply_dispatch_attempts_v2"
                "(bot,persona,operation_id,handler_invocation_id,"
                "request_digest,input_digest,"
                "attempt_id,handler_deadline_utc,frozen_deadline_utc,"
                "anchor_json,pre_graph_revision,"
                "pre_graph_epoch,state,bundle_digest) "
                "VALUES(?,?,?,?,?,?,?,?,?,?,?,?,'open',NULL)",
                namespace.as_tuple + (operation_id,) + expected,
            )
            db.execute("COMMIT")
        except BaseException:
            db.execute("ROLLBACK")
            raise
        return attempt_id

    @staticmethod
    def _post_c02_reply_progress_digest_v2(progress) -> str:
        """Freeze the paid original reply without deepcopying installed maps."""
        from .authority_service.v2_reply_worker_model_result_contract import (
            to_wire as reply_result_to_wire,
        )
        from .host.installed_reply_model_driver import InstalledReplyProgressV1

        if (type(progress) is not InstalledReplyProgressV1
                or progress.cost is None or progress.candidate is None
                or progress.result_read is None):
            raise UnavailableGuard("complete original reply progress required; HOLD")
        frozen = progress.run.preparation
        return canonical_digest({
            "schema": "sylanne.post_c02_reply_progress.v2",
            "c02_receipt": asdict(frozen.c02_receipt),
            "model_envelope": asdict(frozen.envelope),
            "source": asdict(frozen.source),
            "attention": asdict(frozen.attention),
            "focus_revision": frozen.focus_revision,
            "original_intent": asdict(frozen.intent),
            "expected_anchor": asdict(frozen.expected_anchor),
            "model_request_digest": frozen.installed.request.digest,
            "provider_config_ref": frozen.installed.provider_config_ref,
            "provider_config_digest": frozen.installed.provider_config_digest,
            "quote_ceiling": dict(frozen.installed.quote_ceiling),
            "terminal": asdict(progress.run.terminal),
            "cost": asdict(progress.cost),
            "candidate": asdict(progress.candidate),
            "authority_result_read": reply_result_to_wire(progress.result_read),
        })

    @staticmethod
    def _post_c02_reply_dispatch_request_digest_v2(
            *, installed_bundle, handler_invocation_id: str,
            handler_deadline_utc: float, progress) -> str:
        return canonical_digest({
            "schema": "sylanne.post_c02_reply_dispatch_request.v2",
            "installation_id":
                installed_bundle.installation_policy.installation_id,
            "handler_invocation_id": handler_invocation_id,
            "handler_deadline_utc": handler_deadline_utc,
            "paid_reply_progress_digest":
                GraphCoordinator._post_c02_reply_progress_digest_v2(progress),
        })

    @staticmethod
    def _post_c02_reply_dispatch_input_digest_v2(
            *, installation_id: str, handler_invocation_id: str,
            handler_deadline_utc: float, frozen_deadline_utc: float,
            progress, inputs, route,
            route_binding, expression) -> str:
        """Freeze original ingress, destination and claims before write P2."""
        return canonical_digest({
            "schema": "sylanne.post_c02_reply_dispatch_input.v2",
            "installation_id": installation_id,
            "handler_invocation_id": handler_invocation_id,
            "handler_deadline_utc": handler_deadline_utc,
            "frozen_deadline_utc": frozen_deadline_utc,
            "c02_receipt": asdict(inputs.c02_receipt),
            "current_source": asdict(inputs.source),
            "attention": asdict(inputs.attention),
            "route": asdict(route),
            "account_entity_route": asdict(route_binding),
            "expression": asdict(expression),
            "original_model_request_digest":
                progress.run.preparation.installed.request.digest,
            "paid_reply_progress_digest":
                GraphCoordinator._post_c02_reply_progress_digest_v2(progress),
        })

    def _mark_post_c02_reply_dispatch_committed_locked(
            self, *, namespace: NamespaceId, operation_id: str,
            handler_invocation_id: str, input_digest: str, attempt_id: str,
            scope: FenceScope, receipt: CommitReceipt,
            ingress_operation_id: str, handler_deadline_utc: float,
            installation_id: str, account_ref: str,
            destination_ref: str, c02_operation_id: str,
            source_ref: str, target_entity_ref: str) -> None:
        """Bind the pre-P2 attempt to the sealed bundle in its SQLite tx."""
        from .authority_service.v2_contract import to_wire

        db = self.__store._db
        if (not self.__store._lock._is_owned() or not db.in_transaction
                or receipt.status != "committed"
                or receipt.operation_id != operation_id
                or scope.namespace != namespace
                or scope.operation_id != attempt_id):
            raise UnavailableGuard("reply dispatch attempt commit identity differs; HOLD")
        row = db.execute(
            "SELECT handler_invocation_id,input_digest,attempt_id,state,"
            "bundle_digest FROM graph_post_c02_reply_dispatch_attempts_v2 "
            "WHERE bot=? AND persona=? AND operation_id=?",
            namespace.as_tuple + (operation_id,),
        ).fetchone()
        fence = db.execute(
            "SELECT digest,permit_json,post_graph_epoch FROM graph_bundle_fences_v2 "
            "WHERE bot=? AND persona=? AND operation_id=?",
            namespace.as_tuple + (operation_id,),
        ).fetchone()
        if (row != (handler_invocation_id, input_digest, attempt_id,
                    "open", None)
                or fence != (receipt.operation_digest,
                             canonical_json(to_wire(scope.permit)),
                             receipt.invalidated_epochs[0].revision)):
            raise UnavailableGuard("reply dispatch attempt lacks exact seal; HOLD")
        db.execute(
            "UPDATE graph_post_c02_reply_dispatch_attempts_v2 SET "
            "state='committed',bundle_digest=? WHERE bot=? AND persona=? "
            "AND operation_id=? AND state='open' AND attempt_id=?",
            (receipt.operation_digest, *namespace.as_tuple, operation_id, attempt_id),
        )
        if db.execute("SELECT changes()").fetchone()[0] != 1:
            raise UnavailableGuard("reply dispatch attempt CAS failed; HOLD")
        self._require_reply_host_available_locked(
            namespace, ingress_operation_id, handler_invocation_id)
        admissions = db.execute(
            "SELECT admission_ref FROM graph_dispatch_admissions WHERE "
            "bot=? AND persona=? AND operation_id=?",
            namespace.as_tuple + (operation_id,),
        ).fetchall()
        if len(admissions) != 1:
            raise UnavailableGuard("reply seal has no unique admission; HOLD")
        issued = load_request(db, namespace, admissions[0][0])
        if issued is None:
            raise UnavailableGuard("reply seal lacks stored command; HOLD")
        admission = issued[0].admission
        if (admission.operation_id != operation_id
                or admission.account_ref != account_ref
                or admission.destination_ref != destination_ref
                or admission.object_ref != target_entity_ref
                or admission.audience != (destination_ref,)):
            raise UnavailableGuard("reply admission route differs; HOLD")
        prior = db.execute(
            "SELECT 1 FROM graph_post_c02_reply_ownership_v1 WHERE "
            "bot=? AND persona=? AND ingress_operation_id=?",
            namespace.as_tuple + (ingress_operation_id,),
        ).fetchone()
        if prior is not None:
            raise UnavailableGuard("reply host ownership was already decided; HOLD")
        db.execute(
            "INSERT INTO graph_post_c02_reply_ownership_v1("
            "bot,persona,ingress_operation_id,handler_invocation_id,state,"
            "reply_operation_id,effect_id,admission_ref,admission_digest,"
            "c02_operation_id,source_ref,target_entity_ref,"
            "installation_id,account_ref,destination_ref,handler_deadline_utc) "
            "VALUES(?,?,?,?, 'awaiting_host_takeover',?,?,?,?,?,?,?,?,?,?,?)",
            namespace.as_tuple + (ingress_operation_id, handler_invocation_id,
                                  operation_id, admission.effect_id,
                                  admission.admission_ref, admission.digest,
                                  c02_operation_id, source_ref,
                                  target_entity_ref,
                                  installation_id, account_ref,
                                  destination_ref, handler_deadline_utc),
        )

    def _reply_ingress_identity_locked(self, namespace: NamespaceId,
                                       ingress_operation_id: str) -> dict:
        """Recover one original committed private host identity from SQL."""
        from .runtime.ingress_observation import read_committed_ingress_identity

        db = self.__store._db
        rows = db.execute(
            "SELECT source_ref FROM graph_first_ingress_identity_v1 "
            "WHERE bot=? AND persona=? AND operation_id=?",
            namespace.as_tuple + (ingress_operation_id,),
        ).fetchall()
        if len(rows) != 1:
            raise UnavailableGuard("original private ingress is absent; HOLD")
        receipt = read_committed_ingress_identity(db, namespace, rows[0][0])
        if receipt is None:
            raise UnavailableGuard("original private ingress is uncommitted; HOLD")
        identity = json.loads(receipt.identity_json)
        if (identity["operation_id"] != ingress_operation_id
                or identity["visibility"] != "private"):
            raise UnavailableGuard("original ingress is not private; HOLD")
        return identity

    def _require_reply_host_available_locked(
            self, namespace: NamespaceId, ingress_operation_id: str,
            handler_invocation_id: str) -> None:
        identity = self._reply_ingress_identity_locked(
            namespace, ingress_operation_id)
        if identity["operation_id"] != ingress_operation_id:
            raise UnavailableGuard("reply original ingress changed; HOLD")
        row = self.__store._db.execute(
            "SELECT handler_invocation_id,state FROM "
            "graph_post_c02_reply_ownership_v1 WHERE "
            "bot=? AND persona=? AND ingress_operation_id=?",
            namespace.as_tuple + (ingress_operation_id,),
        ).fetchone()
        if row is not None:
            if row[0] != handler_invocation_id:
                raise EventConflict("original reply handler invocation changed")
            raise UnavailableGuard("original reply host ownership is closed; HOLD")

    @staticmethod
    def _reply_ownership_receipt(namespace: NamespaceId, row):
        from .runtime.post_c02_reply_ownership_v1 import ReplyOwnershipReceiptV1

        return ReplyOwnershipReceiptV1(namespace, *row)

    def _verify_saved_owned_reply_locked(self, namespace: NamespaceId,
                                         row, identity: dict) -> None:
        """Check a recovered ownership row against its durable reply seal.

        This is a historical recovery check.  A sender still needs the current
        Authority and dispatch checks before handing a segment to the host.
        """
        db = self.__store._db
        if (not db.in_transaction or row[2] != "sylanne_owned"
                or row[8:10] != (identity["platform_ref"],
                                  identity["conversation_ref"])
                or any(type(value) is not str or not value for value in
                       (*row[3:10], row[11]))
                or not row[11].startswith("sha256:")
                or len(row[11]) != 71):
            raise UnavailableGuard("recovered reply ownership is incomplete; HOLD")
        issued = load_request(db, namespace, row[5])
        operation = db.execute(
            "SELECT digest,effect_id FROM graph_bundle_operations WHERE bot=? "
            "AND persona=? AND operation_id=?",
            namespace.as_tuple + (row[3],),
        ).fetchone()
        attempt = db.execute(
            "SELECT state,bundle_digest FROM "
            "graph_post_c02_reply_dispatch_attempts_v2 WHERE bot=? "
            "AND persona=? AND operation_id=?",
            namespace.as_tuple + (row[3],),
        ).fetchone()
        fence = db.execute(
            "SELECT digest FROM graph_bundle_fences_v2 WHERE bot=? "
            "AND persona=? AND operation_id=?",
            namespace.as_tuple + (row[3],),
        ).fetchone()
        if (issued is None or operation is None
                or attempt != ("committed", operation[0])
                or fence != (operation[0],)):
            raise UnavailableGuard("recovered reply bundle seal differs; HOLD")
        admission = issued[0].admission
        if (operation[1] != row[4]
                or (admission.operation_id, admission.effect_id,
                    admission.admission_ref, admission.digest,
                    admission.account_ref, admission.destination_ref,
                    admission.audience) !=
                   (row[3], row[4], row[5], row[6], row[8], row[9],
                    (row[9],))):
            raise UnavailableGuard("recovered reply admission differs; HOLD")

    def close_host_default_v1(
            self, authority: AuthorityContext, lease: object, *,
            ingress_operation_id: str,
            handler_invocation_id: str):
        """Terminally return an original private ingress to its host handler.

        This CAS does not authorize host output.  It prevents a late worker
        from creating or activating a Sylanne reply for the same ingress.
        """
        self._authorize(lease, authority, frozenset(("d08", "d09", "d11")))
        namespace = authority.namespace
        if (not isinstance(self.__store, ProductionGraphStore)
                or authority.purpose != "expression"
                or type(ingress_operation_id) is not str
                or not ingress_operation_id
                or type(handler_invocation_id) is not str
                or not handler_invocation_id):
            raise UnavailableGuard("original reply host identity unavailable; HOLD")
        db = self.__store._db
        with self.__store._lock:
            db.execute("BEGIN IMMEDIATE")
            try:
                self._reply_ingress_identity_locked(
                    namespace, ingress_operation_id)
                row = db.execute(
                    "SELECT ingress_operation_id,handler_invocation_id,state,"
                    "reply_operation_id,effect_id,admission_ref,admission_digest,"
                    "installation_id,account_ref,destination_ref,"
                    "handler_deadline_utc,ack_digest FROM "
                    "graph_post_c02_reply_ownership_v1 WHERE bot=? AND persona=? "
                    "AND ingress_operation_id=?",
                    namespace.as_tuple + (ingress_operation_id,),
                ).fetchone()
                if row is None:
                    db.execute(
                        "INSERT INTO graph_post_c02_reply_ownership_v1("
                        "bot,persona,ingress_operation_id,handler_invocation_id,"
                        "state) VALUES(?,?,?,?,'host_default')",
                        namespace.as_tuple + (
                            ingress_operation_id, handler_invocation_id),
                    )
                elif row[1] != handler_invocation_id:
                    raise EventConflict("original reply handler invocation differs")
                elif row[2] == "awaiting_host_takeover":
                    db.execute(
                        "UPDATE graph_post_c02_reply_ownership_v1 SET "
                        "state='host_default' WHERE bot=? AND persona=? "
                        "AND ingress_operation_id=? AND "
                        "handler_invocation_id=? AND "
                        "state='awaiting_host_takeover'",
                        namespace.as_tuple + (
                            ingress_operation_id, handler_invocation_id),
                    )
                    if db.execute("SELECT changes()").fetchone()[0] != 1:
                        raise EventConflict("original reply host decision raced")
                elif row[2] != "host_default":
                    raise UnavailableGuard("reply already taken over; HOLD")
                final = db.execute(
                    "SELECT ingress_operation_id,handler_invocation_id,state,"
                    "reply_operation_id,effect_id,admission_ref,admission_digest,"
                    "installation_id,account_ref,destination_ref,"
                    "handler_deadline_utc,ack_digest FROM "
                    "graph_post_c02_reply_ownership_v1 WHERE bot=? AND persona=? "
                    "AND ingress_operation_id=?",
                    namespace.as_tuple + (ingress_operation_id,),
                ).fetchone()
                if final is None or final[2] != "host_default":
                    raise UnavailableGuard("reply host default CAS failed; HOLD")
                result = self._reply_ownership_receipt(namespace, final)
                db.execute("COMMIT")
                return result
            except BaseException:
                db.execute("ROLLBACK")
                raise

    def read_reply_ownership_v1(
            self, authority: AuthorityContext, lease: object, *,
            ingress_operation_id: str,
            handler_invocation_id: str):
        """Read a committed takeover after the activation response was lost.

        This historical receipt is not a dispatch claim.  The final sender
        must still obtain its own current Authority and graph decision.
        """
        self._authorize(lease, authority, frozenset(("d08", "d09", "d11")))
        namespace = authority.namespace
        if (not isinstance(self.__store, ProductionGraphStore)
                or authority.purpose != "expression"):
            raise UnavailableGuard("reply ownership read unavailable")
        with self.__store._lock:
            db = self.__store._db
            db.execute("BEGIN")
            try:
                identity = self._reply_ingress_identity_locked(
                    namespace, ingress_operation_id)
                row = db.execute(
                    "SELECT ingress_operation_id,handler_invocation_id,state,"
                    "reply_operation_id,effect_id,admission_ref,admission_digest,"
                    "installation_id,account_ref,destination_ref,"
                    "handler_deadline_utc,ack_digest FROM "
                    "graph_post_c02_reply_ownership_v1 WHERE bot=? AND persona=? "
                    "AND ingress_operation_id=?",
                    namespace.as_tuple + (ingress_operation_id,),
                ).fetchone()
                if row is not None and row[1] != handler_invocation_id:
                    raise EventConflict("original reply handler invocation differs")
                if row is not None and row[2] == "sylanne_owned":
                    self._verify_saved_owned_reply_locked(namespace, row, identity)
                result = (None if row is None else
                          self._reply_ownership_receipt(namespace, row))
                db.execute("COMMIT")
                return result
            except BaseException:
                db.execute("ROLLBACK")
                raise

    def grant_owned_reply_dispatch_scope_v1(
            self, bootstrap: object, installed_bundle, *,
            ingress_operation_id: str, handler_invocation_id: str):
        """Mint one route-scoped lease from the original owned private ingress.

        The installed host supplies no audience.  A current read fence checks
        the durable ownership, original ingress, sealed admission and attempt
        before the coordinator selects the sole delivery audience.
        """
        from .host.authority_profile import AdminInstallationBundle

        self._admin(bootstrap)
        port = self.__content_fence_v2
        if (not isinstance(self.__store, ProductionGraphStore) or port is None
                or type(installed_bundle) is not AdminInstallationBundle
                or type(ingress_operation_id) is not str or not ingress_operation_id
                or type(handler_invocation_id) is not str or not handler_invocation_id):
            raise UnavailableGuard("installed private reply scope unavailable; HOLD")
        policy = installed_bundle.installation_policy
        namespace = policy.namespace
        installation = port.installation_grant
        if policy.installation_id != installation.installation_id:
            raise UnavailableGuard("private reply installation differs; HOLD")
        with self.__store._lock:
            metadata, _ = self._v2_graph_stamp(namespace)
        generation = metadata.requirements.activation_generation
        if (metadata.requirements.authority_id != installation.authority_id
                or metadata.requirements.authority_namespace
                   != policy.authority_namespace):
            raise UnavailableGuard("private reply recovery identity differs; HOLD")
        read_authority = AuthorityContext(
            installation.administrator_holder, "d11", "reply-scope-read-v1",
            namespace, ("activity",), "expression", ("internal",),
            policy.root_grant.policy_ref, generation)

        def reader():
            db = self.__store._db
            if db.in_transaction:
                raise UnavailableGuard("reply scope needs an idle graph connection")
            db.execute("BEGIN")
            try:
                identity = self._reply_ingress_identity_locked(
                    namespace, ingress_operation_id)
                rows = db.execute(
                    "SELECT ingress_operation_id,handler_invocation_id,state,"
                    "reply_operation_id,effect_id,admission_ref,admission_digest,"
                    "installation_id,account_ref,destination_ref,"
                    "handler_deadline_utc,ack_digest FROM "
                    "graph_post_c02_reply_ownership_v1 WHERE bot=? AND persona=? "
                    "AND ingress_operation_id=?",
                    namespace.as_tuple + (ingress_operation_id,),
                ).fetchall()
                if len(rows) != 1:
                    raise UnavailableGuard("original reply has no owned handler; HOLD")
                row = rows[0]
                if (row[1] != handler_invocation_id
                        or row[2] != "sylanne_owned" or not row[11]
                        or row[7] != installation.installation_id
                        or row[8:10] != (identity["platform_ref"],
                                          identity["conversation_ref"])):
                    raise UnavailableGuard("original reply ownership or route differs; HOLD")
                issued = load_request(db, namespace, row[5])
                operation = db.execute(
                    "SELECT digest FROM graph_bundle_operations WHERE bot=? "
                    "AND persona=? AND operation_id=?",
                    namespace.as_tuple + (row[3],),
                ).fetchone()
                attempt = db.execute(
                    "SELECT state,bundle_digest FROM "
                    "graph_post_c02_reply_dispatch_attempts_v2 WHERE bot=? "
                    "AND persona=? AND operation_id=?",
                    namespace.as_tuple + (row[3],),
                ).fetchone()
                fence = db.execute(
                    "SELECT digest FROM graph_bundle_fences_v2 WHERE bot=? "
                    "AND persona=? AND operation_id=?",
                    namespace.as_tuple + (row[3],),
                ).fetchone()
                if issued is None or operation is None or fence is None:
                    raise UnavailableGuard("original reply seal is absent; HOLD")
                admission = issued[0].admission
                if (attempt != ("committed", operation[0])
                        or fence[0] != operation[0]
                        or (admission.operation_id, admission.effect_id,
                            admission.admission_ref, admission.digest)
                        != (row[3], row[4], row[5], row[6])
                        or admission.account_ref != row[8]
                        or admission.destination_ref != row[9]
                        or admission.purpose != "expression"
                        or admission.audience != (row[9],)):
                    raise UnavailableGuard("original reply admission differs; HOLD")
                receipt = self._reply_ownership_receipt(namespace, row)
                db.execute("COMMIT")
                return receipt
            except BaseException:
                db.execute("ROLLBACK")
                raise

        ownership = self._read_v2(read_authority, reader)
        lease, capability = self._grant_registered(
            actor=installation.administrator_holder, issuer_domain="d11",
            namespace=namespace, domains=("d08", "d09", "d11"),
            activation_generation=generation,
            operation_id=ownership.reply_operation_id)
        authority = AuthorityContext(
            installation.administrator_holder, "d11", capability, namespace,
            ("activity",), "expression", (ownership.destination_ref,),
            policy.root_grant.policy_ref, generation)
        return authority, lease, ownership

    def require_reply_owned_before_dispatch_p2_v1(
            self, authority: AuthorityContext, lease: object, *,
            ingress_operation_id: str, admission_ref: str,
            effect_id: str):
        """Read the terminal host takeover before starting Authority P2.

        The result proves only original handler suppression ownership.  The
        later P2, final graph claim and sender each require current guards.
        """
        self._authorize(lease, authority, frozenset(("d08", "d09", "d11")))
        namespace = authority.namespace
        if (not isinstance(self.__store, ProductionGraphStore)
                or authority.purpose != "expression"
                or any(type(value) is not str or not value for value in (
                    ingress_operation_id, admission_ref, effect_id))):
            raise UnavailableGuard("reply P2 ownership identity unavailable")
        with self.__store._lock:
            db = self.__store._db
            db.execute("BEGIN")
            try:
                identity = self._reply_ingress_identity_locked(
                    namespace, ingress_operation_id)
                rows = db.execute(
                    "SELECT ingress_operation_id,handler_invocation_id,state,"
                    "reply_operation_id,effect_id,admission_ref,admission_digest,"
                    "installation_id,account_ref,destination_ref,"
                    "handler_deadline_utc,ack_digest FROM "
                    "graph_post_c02_reply_ownership_v1 WHERE bot=? AND persona=? "
                    "AND ingress_operation_id=?",
                    namespace.as_tuple + (ingress_operation_id,),
                ).fetchall()
                if len(rows) != 1:
                    raise UnavailableGuard("original reply has no host takeover")
                row = rows[0]
                if (row[2] != "sylanne_owned" or not row[11]
                        or row[4:6] != (effect_id, admission_ref)
                        or row[8:10] != (identity["platform_ref"],
                                          identity["conversation_ref"])):
                    raise UnavailableGuard("original reply is not durably owned")
                issued = load_request(db, namespace, admission_ref)
                operation = db.execute(
                    "SELECT digest FROM graph_bundle_operations WHERE bot=? "
                    "AND persona=? AND operation_id=?",
                    namespace.as_tuple + (row[3],),
                ).fetchone()
                attempt = db.execute(
                    "SELECT state,bundle_digest FROM "
                    "graph_post_c02_reply_dispatch_attempts_v2 WHERE bot=? "
                    "AND persona=? AND operation_id=?",
                    namespace.as_tuple + (row[3],),
                ).fetchone()
                if (issued is None or operation is None
                        or attempt != ("committed", operation[0])
                        or issued[0].admission.digest != row[6]
                        or issued[0].admission.operation_id != row[3]
                        or issued[0].admission.effect_id != effect_id
                        or issued[0].admission.account_ref != row[8]
                        or issued[0].admission.destination_ref != row[9]):
                    raise UnavailableGuard("original reply is not durably owned")
                result = self._reply_ownership_receipt(namespace, row)
                db.execute("COMMIT")
                return result
            except BaseException:
                db.execute("ROLLBACK")
                raise

    def wait_for_durable_admission_v1(
            self, authority: AuthorityContext, lease: object, *,
            ingress_operation_id: str,
            handler_invocation_id: str):
        """Return a durable ready hint only after original P2 is finished."""
        from .authority_service.v2_contract import FencePermitV2, from_wire
        from .host.reply_takeover import HostReplyTakeoverReadyV1

        self._authorize(lease, authority, frozenset(("d08", "d09", "d11")))
        namespace = authority.namespace
        port = self.__content_fence_v2
        if (not isinstance(self.__store, ProductionGraphStore)
                or port is None or authority.purpose != "expression"):
            raise UnavailableGuard("reply durable host read unavailable; HOLD")
        with self.__store._lock:
            db = self.__store._db
            db.execute("BEGIN")
            try:
                identity = self._reply_ingress_identity_locked(
                    namespace, ingress_operation_id)
                row = db.execute(
                    "SELECT handler_invocation_id,state,reply_operation_id,"
                    "effect_id,admission_ref,admission_digest,installation_id,"
                    "account_ref,destination_ref FROM "
                    "graph_post_c02_reply_ownership_v1 WHERE bot=? AND persona=? "
                    "AND ingress_operation_id=?",
                    namespace.as_tuple + (ingress_operation_id,),
                ).fetchone()
                if row is None or row[1] == "host_default":
                    db.execute("COMMIT")
                    return None
                if row[0] != handler_invocation_id or row[1] != "awaiting_host_takeover":
                    raise UnavailableGuard("reply host decision differs; HOLD")
                operation_id, effect_id, admission_ref = row[2:5]
                issued = load_request(db, namespace, admission_ref)
                attempt = db.execute(
                    "SELECT attempt_id,state,bundle_digest "
                    "FROM graph_post_c02_reply_dispatch_attempts_v2 "
                    "WHERE bot=? AND persona=? AND operation_id=?",
                    namespace.as_tuple + (operation_id,),
                ).fetchone()
                seal = db.execute(
                    "SELECT digest,permit_json FROM graph_bundle_fences_v2 "
                    "WHERE bot=? AND persona=? AND operation_id=?",
                    namespace.as_tuple + (operation_id,),
                ).fetchone()
                if (issued is None or attempt is None or seal is None
                        or attempt[1] != "committed"
                        or seal[0] != attempt[2]
                        or issued[0].admission.operation_id != operation_id
                        or issued[0].admission.effect_id != effect_id
                        or issued[0].admission.digest != row[5]
                        or issued[0].admission.account_ref != identity["platform_ref"]
                        or issued[0].admission.destination_ref
                           != identity["conversation_ref"]
                        or row[7:9] != (identity["platform_ref"],
                                        identity["conversation_ref"])):
                    raise UnavailableGuard("reply durable admission differs; HOLD")
                metadata, _ = self._v2_graph_stamp(namespace)
                permit = from_wire(json.loads(seal[1]))
                if (type(permit) is not FencePermitV2
                        or permit.operation_id != attempt[0]
                        or not self._anchor_matches(
                            metadata.requirements, permit.pinned_anchor)):
                    raise UnavailableGuard("reply original write permit differs; HOLD")
                ready = HostReplyTakeoverReadyV1(
                    ingress_operation_id, admission_ref, row[5], row[6],
                    row[7], row[8])
                target = metadata.requirements.authority_namespace
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise
        observed, state = port.get_fence_operation(
            namespace=namespace, authority_namespace=target,
            operation_id=permit.operation_id)
        if observed != permit or state not in {"active", "finished"}:
            raise UnavailableGuard("reply P2 has not finished; HOLD")
        if state == "active":
            return None
        return ready

    def _verify_current_reply_ownership_locked(
            self, *, namespace: NamespaceId, ingress_operation_id: str,
            handler_invocation_id: str, ready, guard,
            anchor, now_utc: float, expected_state: str):
        """Re-read the sealed reply, original route and Owner under one read P2."""
        from .authority_service.v2_owner_contract import (
            OwnerGraphCommitProofV1, canonical_digest as owner_digest,
        )
        from .runtime.first_ingress_v2 import scene_ref_for_conversation
        from .runtime.reply_entity_route_v2 import (
            read_current_reply_entity_route_binding_v2,
        )
        from .runtime.reply_model_job import CurrentReplyRouteManifestV2
        from .runtime_contracts import QueryEpoch

        db = self.__store._db
        if not db.in_transaction:
            raise UnavailableGuard("reply ownership requires current graph read")
        identity = self._reply_ingress_identity_locked(
            namespace, ingress_operation_id)
        row = db.execute(
            "SELECT ingress_operation_id,handler_invocation_id,state,"
            "reply_operation_id,effect_id,admission_ref,admission_digest,"
            "installation_id,account_ref,destination_ref,"
            "handler_deadline_utc,ack_digest,c02_operation_id,source_ref,"
            "target_entity_ref FROM graph_post_c02_reply_ownership_v1 "
            "WHERE bot=? AND persona=? AND ingress_operation_id=?",
            namespace.as_tuple + (ingress_operation_id,),
        ).fetchone()
        if (row is None or row[1] != handler_invocation_id
                or row[2] != expected_state
                or row[8:10] != (identity["platform_ref"],
                                  identity["conversation_ref"])
                or not now_utc < row[10]):
            raise UnavailableGuard("reply ownership state, route or deadline differs")
        admission_pair = load_request(db, namespace, row[5])
        if admission_pair is None:
            raise UnavailableGuard("reply admission command is absent")
        admission = admission_pair[0].admission
        operation = db.execute(
            "SELECT digest FROM graph_bundle_operations WHERE bot=? AND "
            "persona=? AND operation_id=?",
            namespace.as_tuple + (row[3],),
        ).fetchone()
        attempt = db.execute(
            "SELECT attempt_id,state,bundle_digest FROM "
            "graph_post_c02_reply_dispatch_attempts_v2 WHERE bot=? "
            "AND persona=? AND operation_id=?",
            namespace.as_tuple + (row[3],),
        ).fetchone()
        fence = db.execute(
            "SELECT digest FROM graph_bundle_fences_v2 WHERE bot=? AND "
            "persona=? AND operation_id=?",
            namespace.as_tuple + (row[3],),
        ).fetchone()
        if (admission.operation_id != row[3]
                or admission.effect_id != row[4]
                or admission.digest != row[6]
                or admission.admission_ref != row[5]
                or admission.account_ref != row[8]
                or admission.destination_ref != row[9]
                or admission.object_ref != row[14]
                or admission.audience != (row[9],)
                or operation is None or attempt is None
                or attempt[1] != "committed"
                or fence != operation
                or attempt[2] != operation[0]):
            raise UnavailableGuard("reply sealed admission or bundle differs")
        route = CurrentReplyRouteManifestV2(
            namespace, row[12], row[13], row[8], row[9],
            scene_ref_for_conversation(namespace, row[8], row[9]),
            canonical_digest({
                "account_ref": row[8], "destination_ref": row[9],
                "scene_ref": scene_ref_for_conversation(
                    namespace, row[8], row[9]),
            }),
        )
        _, epoch = self._v2_graph_stamp(namespace)
        binding = read_current_reply_entity_route_binding_v2(
            db, namespace, route, QueryEpoch(namespace, "all", epoch.revision),
            now_utc=now_utc)
        if (binding.target_entity_ref != row[14]
                or route.scene_ref != admission.scene_ref):
            raise UnavailableGuard("reply current account route changed")
        grant_row = db.execute(
            "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
            (owner_grant_key(*namespace.as_tuple).token,),
        ).fetchone()
        proof_row = db.execute(
            "SELECT operation_id,request_digest,grant_id,grant_digest,"
            "graph_incarnation,graph_access_epoch,graph_epoch,"
            "graph_receipt_digest,proof_json FROM "
            "graph_owner_issue_operations_v1 WHERE bot=? AND persona=?",
            namespace.as_tuple,
        ).fetchone()
        metadata, _ = self._v2_graph_stamp(namespace)
        if grant_row is None or proof_row is None:
            raise UnavailableGuard("reply current Owner proof is absent")
        grant = json.loads(grant_row[1])
        validate_owner_grant_v1(grant)
        proof = OwnerGraphCommitProofV1(
            namespace, proof_row[0], proof_row[1], proof_row[2],
            proof_row[3], proof_row[4], grant["grant_revision"],
            proof_row[5], proof_row[6], proof_row[7])
        if (grant_row != (1, canonical_json(grant), 1)
                or proof_row[8] != canonical_json(asdict(proof))
                or "sha256:" + canonical_digest(grant) != proof.grant_digest
                or proof.graph_incarnation
                   != metadata.requirements.graph_incarnation
                or grant["grant_id"] != admission.owner_head_ref
                or grant["grant_id"] != proof.grant_id
                or guard.namespace != namespace
                or guard.authority_id != anchor.authority_id
                or guard.installation_id != row[7]
                or guard.authorization_revision != grant["grant_revision"]
                or guard.authorization_head != owner_digest(proof)
                or guard.minimum_revocation_revision != 0
                or guard.minimum_revocation_epoch != 0
                or guard.pending_revoke_operation_id is not None
                or anchor.revocation_epoch != 0
                or "expression" not in grant["purposes"]
                or row[9] not in grant["audiences"]):
            raise UnavailableGuard("reply current Owner authorization changed")
        if ready is not None and (
                ready.ingress_operation_id != ingress_operation_id
                or ready.admission_ref != row[5]
                or ready.admission_digest != row[6]
                or ready.installation_id != row[7]
                or ready.account_ref != row[8]
                or ready.destination_ref != row[9]):
            raise UnavailableGuard("reply host ready hint differs")
        return row

    def activate_reply_ownership_v1(
            self, authority: AuthorityContext, lease: object, *,
            ready, evidence):
        """CAS one sealed reply only after a live original handler stopped.

        The installed verifier consumes an in-memory capability outside the
        graph lock. A directly constructed evidence DTO is never sufficient.
        """
        from .authority_service.v2_contract import FencePermitV2
        from .host.authority_profile import AdminIngressClockPolicy
        from .host.reply_suppression import (
            HostReplySuppressionAckV1, HostReplySuppressionEvidenceV1,
        )
        from .host.reply_takeover import HostReplyTakeoverReadyV1
        from .host.v2_fence_port import VerifiedIngressClockV2
        from .runtime.first_ingress_v2 import trusted_upper

        self._authorize(lease, authority, frozenset(("d08", "d09", "d11")))
        namespace = authority.namespace
        store, port = self.__store, self.__content_fence_v2
        verifier = self.__reply_suppression_ack_verifier
        if (not isinstance(store, ProductionGraphStore) or port is None
                or type(self.__dispatch_clock_policy) is not AdminIngressClockPolicy
                or not callable(verifier)
                or type(ready) is not HostReplyTakeoverReadyV1
                or type(evidence) is not HostReplySuppressionEvidenceV1
                or authority.purpose != "expression"):
            raise UnavailableGuard("live reply host suppression verifier unavailable")
        ingress_operation_id = ready.ingress_operation_id
        handler_invocation_id = evidence.handler_invocation_id
        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
        target = metadata.requirements
        anchor = port.current_anchor(
            namespace=namespace,
            authority_namespace=target.authority_namespace)
        if (target.activation_generation != authority.activation_generation
                or not self._anchor_matches(target, anchor)):
            raise UnavailableGuard("reply host Authority anchor differs")
        attempt_id = "reply-owner-read-" + secrets.token_hex(16)
        permit = port.begin_fence(
            namespace=namespace, authority_namespace=target.authority_namespace,
            holder=self.__holder, generation=authority.activation_generation,
            operation="read", operation_id=attempt_id, expected_anchor=anchor)
        scope = FenceScope(
            namespace, target.authority_namespace,
            authority.activation_generation, "read", attempt_id,
            permit, anchor, epoch, metadata.graph_revision)
        finish_id = "finish:" + attempt_id
        finish_digest = "sha256:" + canonical_digest({
            "action": "finish_reply_owner_read", "permit_token": permit.token,
            "operation_id": attempt_id,
        })
        try:
            guarded = port.get_current_owner_guard_for_fence(
                namespace=namespace,
                authority_namespace=target.authority_namespace,
                permit=permit)
            clock = port.read_ingress_clock(self.__dispatch_clock_policy)
            if (type(permit) is not FencePermitV2
                    or port.validate_fence(scope) != permit
                    or type(guarded) is not tuple or len(guarded) != 2
                    or type(guarded[0]) is not OwnerAuthorizationGuardV1
                    or guarded[1] != permit
                    or type(clock) is not VerifiedIngressClockV2):
                raise UnavailableGuard("reply host current read fence unavailable")
            now = trusted_upper(clock)
            with store._lock:
                db = store._db
                db.execute("BEGIN")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise StaleRead("reply host graph changed")
                    row = self._verify_current_reply_ownership_locked(
                        namespace=namespace,
                        ingress_operation_id=ingress_operation_id,
                        handler_invocation_id=handler_invocation_id,
                        ready=ready, guard=guarded[0], anchor=anchor,
                        now_utc=now,
                        expected_state="awaiting_host_takeover")
                    db.execute("COMMIT")
                except BaseException:
                    db.execute("ROLLBACK")
                    raise
            ack = verifier(
                evidence, namespace=namespace,
                ingress_operation_id=ingress_operation_id,
                handler_invocation_id=handler_invocation_id,
                admission_ref=row[5], admission_digest=row[6],
                installation_id=row[7], account_ref=row[8],
                destination_ref=row[9], handler_deadline_utc=row[10])
            if (type(ack) is not HostReplySuppressionAckV1
                    or (ack.namespace, ack.ingress_operation_id,
                        ack.ingress_envelope_digest,
                        ack.handler_invocation_id, ack.installation_id,
                        ack.admission_ref, ack.admission_digest,
                        ack.account_ref, ack.destination_ref,
                        ack.stopped_at_utc) != (
                        namespace, ingress_operation_id,
                        evidence.ingress_envelope_digest,
                        handler_invocation_id, row[7], row[5], row[6],
                        row[8], row[9], evidence.stopped_at_utc)
                    or evidence.stop_confirmed is not True
                    or not ack.proof_digest.startswith("sha256:")
                    or len(ack.proof_digest) != 71):
                raise UnavailableGuard("reply live stop Ack identity differs")
            try:
                stopped_at = datetime.fromisoformat(
                    ack.stopped_at_utc.replace("Z", "+00:00"))
            except ValueError as exc:
                raise UnavailableGuard("reply live stop time invalid") from exc
            if (stopped_at.tzinfo is None
                    or stopped_at.timestamp() > row[10]):
                raise UnavailableGuard("reply live stop missed handler deadline")
            renewed_guard = port.get_current_owner_guard_for_fence(
                namespace=namespace,
                authority_namespace=target.authority_namespace,
                permit=permit)
            fresh_clock = port.read_ingress_clock(self.__dispatch_clock_policy)
            if (renewed_guard != guarded
                    or type(fresh_clock) is not VerifiedIngressClockV2
                    or port.validate_fence(scope) != permit):
                raise UnavailableGuard("reply Authority changed after host stop")
            final_now = trusted_upper(fresh_clock)
            with store._lock:
                db = store._db
                db.execute("BEGIN IMMEDIATE")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise StaleRead("reply graph changed after host stop")
                    final = self._verify_current_reply_ownership_locked(
                        namespace=namespace,
                        ingress_operation_id=ingress_operation_id,
                        handler_invocation_id=handler_invocation_id,
                        ready=ready, guard=guarded[0], anchor=anchor,
                        now_utc=final_now,
                        expected_state="awaiting_host_takeover")
                    if final != row:
                        raise UnavailableGuard("reply ownership changed after stop")
                    db.execute(
                        "UPDATE graph_post_c02_reply_ownership_v1 SET "
                        "state='sylanne_owned',ack_digest=? WHERE bot=? AND "
                        "persona=? AND ingress_operation_id=? AND "
                        "handler_invocation_id=? AND "
                        "state='awaiting_host_takeover'",
                        (ack.proof_digest, *namespace.as_tuple,
                         ingress_operation_id, handler_invocation_id),
                    )
                    if db.execute("SELECT changes()").fetchone()[0] != 1:
                        raise EventConflict("reply host ownership CAS raced")
                    final = db.execute(
                        "SELECT ingress_operation_id,handler_invocation_id,"
                        "state,reply_operation_id,effect_id,admission_ref,"
                        "admission_digest,installation_id,account_ref,"
                        "destination_ref,handler_deadline_utc,ack_digest "
                        "FROM graph_post_c02_reply_ownership_v1 WHERE "
                        "bot=? AND persona=? AND ingress_operation_id=?",
                        namespace.as_tuple + (ingress_operation_id,),
                    ).fetchone()
                    result = self._reply_ownership_receipt(namespace, final)
                    db.execute("COMMIT")
                except BaseException:
                    db.execute("ROLLBACK")
                    raise
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("reply owner read fence changed after CAS")
            return result
        finally:
            port.finish_fence(
                scope, request_id=finish_id,
                request_digest=finish_digest)

    def assemble_post_c02_reply_v2(
            self, authority: AuthorityContext, lease: object, progress,
            installed_bundle, *, handler_invocation_id: str,
            handler_deadline_utc: float) -> CommitReceipt:
        """Atomically seal one paid private reply, ending at host takeover HOLD.

        The original ingress handler supplies a deadline, bounded by the
        installed policy.  This is not host suppression evidence: a later
        durable ownership CAS must still precede final claim or send.
        """
        from .authority_service.v2_contract import (
            AuthorityCurrentEffectSnapshotV2, FencePermitV2,
            canonical_digest as authority_canonical_digest,
        )
        from .authority_service.v2_execution_bridge import CurrentEffectReadV2
        from .host.authority_profile import (
            AdminIngressClockPolicy, AdminInstallationBundle,
            AdminPrivateReplyDispatchPolicy,
        )
        from .host.installed_reply_model_driver import InstalledReplyProgressV1
        from .host.post_c02_reply_driver import post_c02_reply_operation_id
        from .host.v2_fence_port import VerifiedIngressClockV2
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.first_ingress_v2 import ingress_ids
        from .runtime.reply_model_job import source_key_from_ref

        self._authorize(lease, authority, frozenset(("d08", "d09", "d11")))
        store, port = self.__store, self.__content_fence_v2
        policy = (installed_bundle.private_reply_dispatch
                  if type(installed_bundle) is AdminInstallationBundle else None)
        if (not isinstance(store, ProductionGraphStore) or port is None
                or type(progress) is not InstalledReplyProgressV1
                or type(policy) is not AdminPrivateReplyDispatchPolicy
                or type(self.__dispatch_clock_policy) is not AdminIngressClockPolicy
                or installed_bundle.ingress_clock != self.__dispatch_clock_policy
                or installed_bundle.installation_policy.namespace
                   != authority.namespace
                or self.__dispatch_admission_issuer is None
                or authority.purpose != "expression"
                or type(handler_invocation_id) is not str
                or not handler_invocation_id
                or type(handler_deadline_utc) not in (int, float)
                or not math.isfinite(handler_deadline_utc)):
            raise UnavailableGuard("installed reply assembly authority unavailable; HOLD")
        clock = port.read_ingress_clock(self.__dispatch_clock_policy)
        if type(clock) is not VerifiedIngressClockV2:
            raise UnavailableGuard("reply assembly lacks paired current clock; HOLD")
        now = trusted_upper(clock)
        if (not now < handler_deadline_utc
                or handler_deadline_utc > now + policy.host_takeover_wait_seconds):
            raise UnavailableGuard("reply original handler deadline elapsed; HOLD")
        deadline = min(
            handler_deadline_utc, now + policy.deadline_after_seconds,
            installed_bundle.installation_policy.root_grant.valid_until_utc)
        if not now < deadline:
            raise UnavailableGuard("reply dispatch policy window elapsed; HOLD")
        namespace = authority.namespace
        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
        target = metadata.requirements
        if (target.namespace != namespace
                or target.activation_generation !=
                   authority.activation_generation):
            raise UnavailableGuard("reply graph recovery identity differs; HOLD")
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("reply Authority anchor differs; HOLD")
        with store._lock:
            db = store._db
            db.execute("BEGIN")
            try:
                if self._v2_graph_stamp(namespace) != (metadata, epoch):
                    raise StaleRead("reply graph changed before effect preview")
                preview = self._preview_post_c02_reply_effect_locked(
                    authority=authority, progress=progress,
                    installed_bundle=installed_bundle, clock_reading=clock,
                    now_utc=now, epoch=epoch,
                    frozen_deadline_utc=deadline)
                inputs, route, binding, expression = preview
                ingress_operation_id = ingress_ids(source_key_from_ref(
                    inputs.source.source_ref, namespace))[2]
                self._require_reply_host_available_locked(
                    namespace, ingress_operation_id, handler_invocation_id)
                operation_id = post_c02_reply_operation_id(
                    inputs.c02_receipt.operation_id,
                    inputs.source.source_ref)
                input_digest = self._post_c02_reply_dispatch_input_digest_v2(
                    installation_id=
                        installed_bundle.installation_policy.installation_id,
                    handler_invocation_id=handler_invocation_id,
                    handler_deadline_utc=handler_deadline_utc,
                    frozen_deadline_utc=deadline, progress=progress,
                    inputs=inputs, route=route, route_binding=binding,
                    expression=expression)
                request_digest = self._post_c02_reply_dispatch_request_digest_v2(
                    installed_bundle=installed_bundle,
                    handler_invocation_id=handler_invocation_id,
                    handler_deadline_utc=handler_deadline_utc,
                    progress=progress)
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise
            attempt_id = self._open_post_c02_reply_dispatch_attempt_locked(
                namespace=namespace, operation_id=operation_id,
                ingress_operation_id=ingress_operation_id,
                handler_invocation_id=handler_invocation_id,
                request_digest=request_digest, input_digest=input_digest,
                handler_deadline_utc=handler_deadline_utc,
                frozen_deadline_utc=deadline,
                metadata=metadata, epoch=epoch, anchor=anchor)
        permit = port.begin_fence(
            namespace=namespace, authority_namespace=target.authority_namespace,
            holder=self.__holder, generation=target.activation_generation,
            operation="write", operation_id=attempt_id,
            expected_anchor=anchor, retain_on_unknown=True)
        scope = FenceScope(
            namespace, target.authority_namespace,
            target.activation_generation, "write", attempt_id,
            permit, anchor, epoch, metadata.graph_revision)
        if (type(permit) is not FencePermitV2
                or port.validate_fence(scope) != permit):
            raise UnavailableGuard("reply write permit is unqualified; HOLD")
        owner_reader = getattr(port, "get_current_owner_guard_for_fence", None)
        effect_reader = getattr(port, "read_current_effect", None)
        snapshot_reader = getattr(
            port, "read_current_effect_snapshot_for_write_fence", None)
        if (not callable(owner_reader) or not callable(effect_reader)
                or not callable(snapshot_reader)):
            raise UnavailableGuard("reply Authority current readers unavailable; HOLD")
        guarded = owner_reader(
            namespace=namespace, authority_namespace=target.authority_namespace,
            permit=permit)
        current_effect = effect_reader(
            namespace=namespace, authority_namespace=target.authority_namespace,
            effect_id=expression.segments[0].effect_id)
        effect_snapshot = snapshot_reader(
            namespace=namespace, authority_namespace=target.authority_namespace,
            permit=permit)
        if (type(guarded) is not tuple or len(guarded) != 2
                or type(guarded[0]) is not OwnerAuthorizationGuardV1
                or guarded[1] != permit
                or type(current_effect) is not CurrentEffectReadV2
                or current_effect.effect_id != expression.segments[0].effect_id
                or current_effect.state != "absent"
                or type(effect_snapshot) is not AuthorityCurrentEffectSnapshotV2
                or effect_snapshot.authority_id != permit.authority_id
                or effect_snapshot.namespace != permit.namespace
                or effect_snapshot.anchor != permit.pinned_anchor
                or effect_snapshot.permit_digest
                   != authority_canonical_digest(permit)
                or effect_snapshot.coverage != "complete"
                or port.validate_fence(scope) != permit):
            raise UnavailableGuard("reply current Authority proof differs; HOLD")
        with store._lock:
            db = store._db
            db.execute("BEGIN IMMEDIATE")
            try:
                self._require_reply_host_available_locked(
                    namespace, ingress_operation_id, handler_invocation_id)
                if self._v2_graph_stamp(namespace) != (metadata, epoch):
                    raise StaleRead("reply graph changed before final assembly")
                prepared = self._prepare_post_c02_reply_dispatch_locked(
                    authority=authority, scope=scope,
                    installed_bundle=installed_bundle, progress=progress,
                    clock_reading=clock, current_effect=current_effect,
                    effect_snapshot=effect_snapshot, now_utc=now,
                    frozen_deadline_utc=deadline)
                current_inputs, current_route, _, current_expression = prepared[:4]
                original_binding = prepared[7][5]
                if (current_expression != expression
                        or current_inputs != inputs or current_route != route
                        or original_binding != binding
                        or self._post_c02_reply_dispatch_input_digest_v2(
                            installation_id=
                                installed_bundle.installation_policy.installation_id,
                            handler_invocation_id=handler_invocation_id,
                            handler_deadline_utc=handler_deadline_utc,
                            frozen_deadline_utc=deadline, progress=progress,
                            inputs=current_inputs, route=current_route,
                            route_binding=original_binding,
                            expression=current_expression) != input_digest):
                    raise UnavailableGuard("reply frozen pre-P2 inputs changed; HOLD")
                bundle = prepared[8].bundle
                finish_id = "finish:" + attempt_id
                finish_digest = "sha256:" + canonical_digest({
                    "action": "finish_post_c02_reply_dispatch",
                    "attempt_id": attempt_id,
                    "permit_token": permit.token,
                    "bundle_digest": bundle.digest,
                })
                receipt = self._seal_post_c02_reply_dispatch_locked(
                    lease=lease, scope=scope, metadata=metadata,
                    clock_reading=clock, owner_guard=guarded[0],
                    current_effect=current_effect,
                    effect_snapshot=effect_snapshot, now_utc=now,
                    prepared=prepared, finish_id=finish_id,
                    finish_digest=finish_digest)
                self._mark_post_c02_reply_dispatch_committed_locked(
                    namespace=namespace, operation_id=operation_id,
                    handler_invocation_id=handler_invocation_id,
                    input_digest=input_digest, attempt_id=attempt_id,
                    scope=scope, receipt=receipt,
                    ingress_operation_id=ingress_operation_id,
                    handler_deadline_utc=handler_deadline_utc,
                    installation_id=
                        installed_bundle.installation_policy.installation_id,
                    account_ref=route.platform_ref,
                    destination_ref=route.conversation_ref,
                    c02_operation_id=inputs.c02_receipt.operation_id,
                    source_ref=inputs.source.source_ref,
                    target_entity_ref=binding.target_entity_ref)
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise
        if port.validate_fence(scope) != permit:
            raise UnavailableGuard("reply write permit changed after commit; HOLD")
        with store._lock:
            current, current_epoch = self._v2_graph_stamp(namespace)
            if (current.requirements != metadata.requirements
                    or current.graph_revision != metadata.graph_revision + 1
                    or current_epoch.revision != epoch.revision + 1):
                raise UnavailableGuard("reply final graph stamp differs; HOLD")
        port.finish_fence(
            scope, request_id=finish_id, request_digest=finish_digest)
        return receipt

    def recover_committed_post_c02_reply_dispatch_v2(
            self, authority: AuthorityContext, lease: object, progress,
            installed_bundle, *, handler_invocation_id: str,
            handler_deadline_utc: float) -> CommitReceipt:
        """Resolve only a sealed K03 attempt after a lost finish response.

        An open attempt without a committed graph seal remains HOLD.  This
        method never begins another write permit or reconstructs content.
        """
        from .authority_service.v2_contract import FencePermitV2, from_wire
        from .runtime.first_ingress_v2 import ingress_ids
        from .runtime.reply_model_job import source_key_from_ref
        from .runtime.restore_anchor import RestoreAnchor

        self._authorize(lease, authority, frozenset(("d08", "d09", "d11")))
        store, port = self.__store, self.__content_fence_v2
        if (not isinstance(store, ProductionGraphStore) or port is None
                or authority.purpose != "expression"):
            raise UnavailableGuard("reply dispatch recovery authority absent; HOLD")
        prep = progress.run.preparation
        namespace = authority.namespace
        operation_id = self._post_c02_reply_operation_id_for_recovery(
            prep.c02_receipt.operation_id, prep.source.source_ref)
        request_digest = self._post_c02_reply_dispatch_request_digest_v2(
            installed_bundle=installed_bundle,
            handler_invocation_id=handler_invocation_id,
            handler_deadline_utc=handler_deadline_utc, progress=progress)
        with store._lock:
            db = store._db
            table = db.execute(
                "SELECT 1 FROM sqlite_master WHERE type='table' AND "
                "name='graph_post_c02_reply_dispatch_attempts_v2'"
            ).fetchone()
            if table is None:
                raise UnavailableGuard("reply dispatch attempt absent; HOLD")
            saved = db.execute(
                "SELECT handler_invocation_id,request_digest,input_digest,"
                "attempt_id,handler_deadline_utc,frozen_deadline_utc,"
                "anchor_json,pre_graph_revision,pre_graph_epoch,state,"
                "bundle_digest FROM graph_post_c02_reply_dispatch_attempts_v2 "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone()
            if (saved is None or saved[:2] != (
                    handler_invocation_id, request_digest)
                    or saved[4] != handler_deadline_utc):
                raise UnavailableGuard("reply dispatch original request differs; HOLD")
            if saved[9] != "committed" or saved[10] is None:
                raise UnavailableGuard(
                    "reply dispatch open attempt awaits same-permit recovery; HOLD")
            fence = db.execute(
                "SELECT digest,permit_json,pre_graph_revision,pre_graph_epoch,"
                "post_graph_revision,post_graph_epoch,finish_request_id,"
                "finish_request_digest FROM graph_bundle_fences_v2 "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone()
            operation = db.execute(
                "SELECT digest,activity_id,effect_id,commit_seq,receipt_json "
                "FROM graph_bundle_operations WHERE bot=? AND persona=? "
                "AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone()
            if (fence is None or operation is None
                    or fence[0] != saved[10] or operation[0] != saved[10]
                    or fence[2:4] != saved[7:9]
                    or fence[4:6] != (saved[7] + 1, saved[8] + 1)):
                raise UnavailableGuard("reply dispatch committed seal differs; HOLD")
            event = db.execute(
                "SELECT reads,revisions,epoch_revision FROM graph_events "
                "WHERE bot=? AND persona=? AND session=? AND event_id=?",
                namespace.as_tuple + (operation[1], operation_id),
            ).fetchone()
            detail = json.loads(operation[4])
            admission = detail.get("dispatch_admission")
            issued = (load_request(db, namespace, admission["ref"])
                      if isinstance(admission, dict) and admission.get("ref")
                      else None)
            if (event is None or event[2] != fence[5]
                    or not isinstance(admission, dict)
                    or not admission.get("ref")
                    or issued is None
                    or issued[0].receipt_digest != admission.get("digest")
                    or issued[0].admission.operation_id != operation_id
                    or issued[0].admission.effect_id != operation[2]
                    or len(detail.get("outbox_refs", ())) != 1):
                raise UnavailableGuard("reply dispatch admission or event absent; HOLD")
            ingress_operation_id = ingress_ids(source_key_from_ref(
                prep.source.source_ref, namespace))[2]
            self._reply_ingress_identity_locked(namespace, ingress_operation_id)
            ownership = db.execute(
                "SELECT handler_invocation_id,state,reply_operation_id,"
                "effect_id,admission_ref,admission_digest,installation_id,"
                "handler_deadline_utc FROM graph_post_c02_reply_ownership_v1 "
                "WHERE bot=? AND persona=? AND ingress_operation_id=?",
                namespace.as_tuple + (ingress_operation_id,),
            ).fetchone()
            if (ownership is None or ownership[0] != handler_invocation_id
                    or ownership[1] not in (
                        "awaiting_host_takeover", "host_default", "sylanne_owned")
                    or ownership[2:6] != (
                        operation_id, operation[2], admission["ref"],
                        issued[0].admission.digest)
                    or ownership[6] !=
                       installed_bundle.installation_policy.installation_id
                    or ownership[7] != handler_deadline_utc):
                raise UnavailableGuard("reply dispatch host ownership differs; HOLD")
            metadata, epoch = self._v2_graph_stamp(namespace)
            if (metadata.requirements.namespace != namespace
                    or metadata.graph_revision < fence[4]
                    or epoch.revision < fence[5]):
                raise UnavailableGuard("reply dispatch recovery graph regressed; HOLD")
            receipt = CommitReceipt(
                "duplicate", operation_id, saved[10], operation[1],
                operation[2], operation[3],
                GraphStore._version_rows(event[0]),
                GraphStore._version_rows(event[1]),
                (NamespaceEpoch(*namespace.as_tuple, event[2]),),
                tuple(detail["ledger_refs"]), tuple(detail["outbox_refs"]))
        permit = from_wire(json.loads(fence[1]))
        anchor = RestoreAnchor(**json.loads(saved[6]))
        if (type(permit) is not FencePermitV2
                or permit.operation_id != saved[3]
                or permit.pinned_anchor != anchor
                or permit.namespace != metadata.requirements.authority_namespace
                or permit.authority_id != metadata.requirements.authority_id
                or permit.holder != self.__holder
                or permit.subject != port.installation_grant.subject
                or permit.generation !=
                   metadata.requirements.activation_generation
                or permit.operation != "write"):
            raise UnavailableGuard("reply dispatch original permit differs; HOLD")
        observed, state = port.get_fence_operation(
            namespace=namespace,
            authority_namespace=metadata.requirements.authority_namespace,
            operation_id=saved[3])
        if observed != permit or state not in {"active", "finished"}:
            raise UnavailableGuard("reply dispatch Authority attempt differs; HOLD")
        if state == "active":
            scope = FenceScope(
                namespace, metadata.requirements.authority_namespace,
                authority.activation_generation, "write", saved[3],
                permit, anchor,
                NamespaceEpoch(*namespace.as_tuple, saved[8]), saved[7])
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("reply dispatch recovery permit stale; HOLD")
            port.finish_fence(
                scope, request_id=fence[6], request_digest=fence[7])
        return receipt

    def close_expired_post_c02_reply_dispatch_attempt_v2(
            self, authority: AuthorityContext, lease: object, progress,
            installed_bundle, *, handler_invocation_id: str,
            handler_deadline_utc: float) -> str:
        """Close one uncommitted expired attempt under its original P2 permit.

        This is a terminal no-send rejection.  It never retries with a new
        handler window, effect or Authority permit.
        """
        from .authority_service.v2_contract import (
            FenceNeverBegunReceiptV2, FencePermitV2, to_wire,
        )
        from .host.authority_profile import AdminIngressClockPolicy
        from .host.v2_fence_port import VerifiedIngressClockV2
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.restore_anchor import RestoreAnchor

        self._authorize(lease, authority, frozenset(("d08", "d09", "d11")))
        store, port = self.__store, self.__content_fence_v2
        if (not isinstance(store, ProductionGraphStore) or port is None
                or type(self.__dispatch_clock_policy) is not AdminIngressClockPolicy
                or installed_bundle.ingress_clock != self.__dispatch_clock_policy):
            raise UnavailableGuard("reply dispatch abort authority unavailable; HOLD")
        clock = port.read_ingress_clock(self.__dispatch_clock_policy)
        if type(clock) is not VerifiedIngressClockV2:
            raise UnavailableGuard("reply abort lacks paired current clock; HOLD")
        now = trusted_upper(clock)
        if now < handler_deadline_utc:
            raise UnavailableGuard("reply handler window remains active; HOLD")
        prep = progress.run.preparation
        namespace = authority.namespace
        operation_id = self._post_c02_reply_operation_id_for_recovery(
            prep.c02_receipt.operation_id, prep.source.source_ref)
        request_digest = self._post_c02_reply_dispatch_request_digest_v2(
            installed_bundle=installed_bundle,
            handler_invocation_id=handler_invocation_id,
            handler_deadline_utc=handler_deadline_utc, progress=progress)
        with store._lock:
            db = store._db
            row = db.execute(
                "SELECT handler_invocation_id,request_digest,input_digest,"
                "attempt_id,handler_deadline_utc,anchor_json,"
                "pre_graph_revision,pre_graph_epoch,state,permit_json,"
                "finish_request_id,finish_request_digest "
                "FROM graph_post_c02_reply_dispatch_attempts_v2 "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone()
            if (row is None or row[:2] != (
                    handler_invocation_id, request_digest)
                    or row[4] != handler_deadline_utc
                    or row[8] not in {"open", "rejected_no_commit"}):
                raise UnavailableGuard("reply uncommitted attempt identity differs; HOLD")
            metadata, epoch = self._v2_graph_stamp(namespace)
            anchor = RestoreAnchor(**json.loads(row[5]))
            if (self._v2_graph_stamp(namespace) != (metadata, epoch)
                    or (metadata.graph_revision, epoch.revision) != row[6:8]
                    or not self._anchor_matches(metadata.requirements, anchor)):
                raise UnavailableGuard("reply uncommitted graph head moved; HOLD")
        try:
            observed, state = port.get_fence_operation(
                namespace=namespace,
                authority_namespace=metadata.requirements.authority_namespace,
                operation_id=row[3])
        except Exception:
            # A failed lookup proves nothing. The Authority CAS below must
            # durably prevent a delayed begin for this exact operation ID.
            reject = getattr(port, "reject_unbegun_content_fence_v2", None)
            if not callable(reject):
                raise UnavailableGuard(
                    "reply original permit and never-begun CAS unavailable; HOLD")
            request_id = "abort-unbegun:" + row[3]
            request_digest = "sha256:" + canonical_digest({
                "action": "post_c02_reply_never_begun",
                "namespace": list(namespace.as_tuple),
                "operation_id": operation_id,
                "attempt_id": row[3],
                "handler_invocation_id": handler_invocation_id,
                "handler_deadline_utc": handler_deadline_utc,
                "input_digest": row[2],
                "anchor": asdict(anchor),
            })
            receipt = reject(
                namespace, metadata.requirements.authority_namespace,
                holder=self.__holder,
                generation=metadata.requirements.activation_generation,
                operation_id=row[3], expected_anchor=anchor,
                request_id=request_id, request_digest=request_digest)
            if (type(receipt) is not FenceNeverBegunReceiptV2
                    or receipt.authority_id != metadata.requirements.authority_id
                    or receipt.namespace != metadata.requirements.authority_namespace
                    or receipt.subject != port.installation_grant.subject
                    or receipt.installation_id !=
                       port.installation_grant.installation_id
                    or receipt.holder != self.__holder
                    or receipt.generation !=
                       metadata.requirements.activation_generation
                    or receipt.operation_id != row[3]
                    or receipt.pinned_anchor != anchor
                    or receipt.request_id != request_id
                    or receipt.request_digest != request_digest
                    or receipt.state != "rejected_before_begin"):
                raise UnavailableGuard(
                    "reply never-begun Authority receipt differs; HOLD")
            rejection = (row[2], "rejected_no_commit",
                         canonical_json(to_wire(receipt)), row[6], row[7],
                         request_id, request_digest)
            with store._lock:
                db = store._db
                db.execute("BEGIN IMMEDIATE")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise UnavailableGuard(
                            "reply never-begun graph head moved; HOLD")
                    current = db.execute(
                        "SELECT state,permit_json,finish_request_id,"
                        "finish_request_digest FROM "
                        "graph_post_c02_reply_dispatch_attempts_v2 "
                        "WHERE bot=? AND persona=? AND operation_id=?",
                        namespace.as_tuple + (operation_id,),
                    ).fetchone()
                    exact = ("rejected_no_commit", rejection[2],
                             request_id, request_digest)
                    if current not in {("open", None, None, None), exact}:
                        raise UnavailableGuard(
                            "reply never-begun attempt changed; HOLD")
                    for table in (
                        "graph_bundle_operations", "graph_bundle_fences_v2",
                        "graph_dispatch_admissions", "graph_bundle_outbox",
                        "graph_outbox_jobs", "runtime_budget_reservations",
                        "runtime_jobs",
                    ):
                        if db.execute(
                            "SELECT 1 FROM sqlite_master WHERE type='table' "
                            "AND name=?", (table,),
                        ).fetchone() and db.execute(
                            f"SELECT 1 FROM {table} WHERE operation_id=? LIMIT 1",
                            (operation_id,),
                        ).fetchone() is not None:
                            raise UnavailableGuard(
                                "reply never-begun business fact exists; HOLD")
                    if db.execute(
                        "SELECT 1 FROM graph_events WHERE bot=? AND persona=? "
                        "AND event_id=? LIMIT 1",
                        namespace.as_tuple + (operation_id,),
                    ).fetchone() is not None:
                        raise UnavailableGuard(
                            "reply never-begun graph event exists; HOLD")
                    db.execute(
                        "INSERT OR IGNORE INTO graph_bundle_rejections_v2"
                        "(bot,persona,operation_id,digest,status,permit_json,"
                        "graph_revision,graph_epoch,finish_request_id,"
                        "finish_request_digest) VALUES(?,?,?,?,?,?,?,?,?,?)",
                        namespace.as_tuple + (operation_id,) + rejection,
                    )
                    saved_rejection = db.execute(
                        "SELECT digest,status,permit_json,graph_revision,"
                        "graph_epoch,finish_request_id,finish_request_digest "
                        "FROM graph_bundle_rejections_v2 WHERE bot=? "
                        "AND persona=? AND operation_id=?",
                        namespace.as_tuple + (operation_id,),
                    ).fetchone()
                    if saved_rejection != rejection:
                        raise UnavailableGuard(
                            "reply never-begun rejection differs; HOLD")
                    if current[0] == "open":
                        db.execute(
                            "UPDATE graph_post_c02_reply_dispatch_attempts_v2 "
                            "SET state='rejected_no_commit',permit_json=?,"
                            "finish_request_id=?,finish_request_digest=? "
                            "WHERE bot=? AND persona=? AND operation_id=? "
                            "AND state='open'",
                            exact[1:] + namespace.as_tuple + (operation_id,),
                        )
                        if db.execute("SELECT changes()").fetchone()[0] != 1:
                            raise UnavailableGuard(
                                "reply never-begun CAS failed; HOLD")
                    db.execute("COMMIT")
                except BaseException:
                    db.execute("ROLLBACK")
                    raise
            return "rejected_no_commit"
        if (type(observed) is not FencePermitV2
                or observed.operation_id != row[3]
                or observed.operation != "write"
                or observed.holder != self.__holder
                or observed.subject != port.installation_grant.subject
                or observed.authority_id != metadata.requirements.authority_id
                or observed.namespace != metadata.requirements.authority_namespace
                or observed.generation !=
                   metadata.requirements.activation_generation
                or observed.pinned_anchor != anchor
                or state not in {"active", "finished"}):
            raise UnavailableGuard("reply original write permit differs; HOLD")
        scope = FenceScope(
            namespace, metadata.requirements.authority_namespace,
            metadata.requirements.activation_generation, "write", row[3],
            observed, anchor,
            NamespaceEpoch(*namespace.as_tuple, row[7]), row[6])
        if state == "active" and port.validate_fence(scope) != observed:
            raise UnavailableGuard("reply original write permit is stale; HOLD")
        finish_id = "abort:" + row[3]
        finish_digest = "sha256:" + canonical_digest({
            "action": "post_c02_reply_rejected_no_commit",
            "operation_id": operation_id,
            "attempt_id": row[3], "permit_token": observed.token,
            "input_digest": row[2],
        })
        with store._lock:
            db = store._db
            db.execute("BEGIN IMMEDIATE")
            try:
                if self._v2_graph_stamp(namespace) != (metadata, epoch):
                    raise UnavailableGuard("reply abort graph head moved; HOLD")
                current = db.execute(
                    "SELECT state,permit_json,finish_request_id,"
                    "finish_request_digest FROM "
                    "graph_post_c02_reply_dispatch_attempts_v2 "
                    "WHERE bot=? AND persona=? AND operation_id=?",
                    namespace.as_tuple + (operation_id,),
                ).fetchone()
                exact = ("rejected_no_commit",
                         canonical_json(to_wire(observed)),
                         finish_id, finish_digest)
                if current not in {("open", None, None, None), exact}:
                    raise UnavailableGuard("reply abort state changed; HOLD")
                for table, predicate in (
                    ("graph_bundle_operations", "operation_id"),
                    ("graph_bundle_fences_v2", "operation_id"),
                    ("graph_dispatch_admissions", "operation_id"),
                    ("graph_bundle_outbox", "operation_id"),
                    ("graph_outbox_jobs", "operation_id"),
                    ("runtime_budget_reservations", "operation_id"),
                    ("runtime_jobs", "operation_id"),
                ):
                    if db.execute(
                        "SELECT 1 FROM sqlite_master WHERE type='table' "
                        "AND name=?", (table,),
                    ).fetchone() and db.execute(
                        f"SELECT 1 FROM {table} WHERE {predicate}=? LIMIT 1",
                        (operation_id,),
                    ).fetchone() is not None:
                        raise UnavailableGuard(
                            "reply abort found committed business side effect; HOLD")
                if db.execute(
                    "SELECT 1 FROM graph_events WHERE bot=? AND persona=? "
                    "AND event_id=? LIMIT 1",
                    namespace.as_tuple + (operation_id,),
                ).fetchone() is not None:
                    raise UnavailableGuard("reply abort found graph event; HOLD")
                rejection = (
                    row[2], "rejected_no_commit", exact[1], row[6], row[7],
                    finish_id, finish_digest,
                )
                db.execute(
                    "INSERT OR IGNORE INTO graph_bundle_rejections_v2"
                    "(bot,persona,operation_id,digest,status,permit_json,"
                    "graph_revision,graph_epoch,finish_request_id,"
                    "finish_request_digest) VALUES(?,?,?,?,?,?,?,?,?,?)",
                    namespace.as_tuple + (operation_id,) + rejection,
                )
                recorded = db.execute(
                    "SELECT digest,status,permit_json,graph_revision,"
                    "graph_epoch,finish_request_id,finish_request_digest "
                    "FROM graph_bundle_rejections_v2 WHERE bot=? AND "
                    "persona=? AND operation_id=?",
                    namespace.as_tuple + (operation_id,),
                ).fetchone()
                if recorded != rejection:
                    raise UnavailableGuard("reply abort rejection proof differs; HOLD")
                if current[0] == "open":
                    db.execute(
                        "UPDATE graph_post_c02_reply_dispatch_attempts_v2 "
                        "SET state='rejected_no_commit',permit_json=?,"
                        "finish_request_id=?,finish_request_digest=? "
                        "WHERE bot=? AND persona=? AND operation_id=? "
                        "AND state='open'",
                        exact[1:] + namespace.as_tuple + (operation_id,),
                    )
                    if db.execute("SELECT changes()").fetchone()[0] != 1:
                        raise UnavailableGuard("reply abort CAS failed; HOLD")
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise
        port.finish_fence(scope, request_id=finish_id,
                          request_digest=finish_digest)
        return "rejected_no_commit"

    @staticmethod
    def _post_c02_reply_operation_id_for_recovery(
            c02_operation_id: str, source_ref: str) -> str:
        from .host.post_c02_reply_driver import post_c02_reply_operation_id

        return post_c02_reply_operation_id(c02_operation_id, source_ref)

    def _seal_post_c02_reply_dispatch_locked(
            self, *, lease, scope: FenceScope, metadata, clock_reading,
            owner_guard, current_effect, effect_snapshot, now_utc: float,
            prepared, finish_id: str, finish_digest: str) -> CommitReceipt:
        """Seal only a locally assembled reply under the caller's write tx.

        The provisional check tuple is never an admission.  The normal graph
        receipt hook reissues all five checks against final E+1 rows and lets
        the installed dispatch issuer independently validate the command.
        """
        from .authority_service.v2_contract import to_wire
        from .runtime.post_c02_reply_bundle_v2 import (
            PostC02DispatchBundleCandidateV2,
        )

        store = self.__store
        if (not store._lock._is_owned() or not store._db.in_transaction
                or type(scope) is not FenceScope or scope.operation != "write"
                or type(prepared) is not tuple or len(prepared) != 9
                or type(finish_id) is not str or not finish_id
                or type(finish_digest) is not str or not finish_digest
                or self._v2_graph_stamp(scope.namespace) != (
                    metadata, scope.graph_epoch)):
            raise UnavailableGuard("reply final seal lost its write transaction; HOLD")
        (inputs, route, envelope, expression, grant, quote,
         job, staged, bundle_candidate) = prepared
        if (type(bundle_candidate) is not PostC02DispatchBundleCandidateV2
                or bundle_candidate.status != "candidate"
                or bundle_candidate.bundle.envelope.authority.namespace
                   != scope.namespace
                or bundle_candidate.bundle.envelope.identity.operation_id
                   != envelope.identity.operation_id
                or bundle_candidate.job != job):
            raise UnavailableGuard("reply final bundle is not locally assembled; HOLD")
        (staged_envelope, staged_d08, action, social, candidate,
         original_binding, staged_binding, route_grant) = staged
        if (replace(bundle_candidate.bundle.envelope,
                    version_guard=staged_envelope.version_guard)
                != staged_envelope
                or not set(staged_envelope.version_guard.read_versions)
                   .issubset(bundle_candidate.bundle.envelope.version_guard.read_versions)):
            raise UnavailableGuard("reply final envelope differs from staged checks; HOLD")
        batch_refs = tuple(
            write.key.token for proposal in bundle_candidate.bundle.proposals
            for write in proposal.typed_writes
            if write.key.type_name == "d09.verified_segment_batch.v1")
        if len(batch_refs) != 1:
            raise UnavailableGuard("reply final batch identity differs; HOLD")

        def reissue(db, graph_receipt, read_scope, final_now):
            return self._reissue_post_c02_reply_final_checks_locked(
                db, graph_receipt, read_scope, final_now,
                envelope=envelope, c02_receipt=inputs.c02_receipt,
                route=route, source_ref=inputs.source.source_ref,
                attention=inputs.attention.ticket, focus=inputs.attention.focus,
                budget_grant=grant, resource_quote=quote,
                expression=expression, anchor=scope.pinned_anchor,
                current_effect=current_effect, effect_snapshot=effect_snapshot,
                expected_action=action, expected_social=social,
                expected_original_binding=original_binding,
                expected_staged_binding=staged_binding,
                expected_grant=route_grant, batch_ref=batch_refs[0])

        return self._commit_domain_bundle_fenced(
            bundle_candidate.bundle, lease,
            v2_write=(metadata, scope.graph_epoch, finish_id, finish_digest,
                      canonical_json(to_wire(scope.permit))),
            in_transaction=True, now_utc=now_utc,
            dispatch_clock_reading=clock_reading,
            dispatch_clock_frozen_now_utc=now_utc,
            dispatch_admission_scope=scope,
            dispatch_admission_owner_guard=owner_guard,
            dispatch_admission_current_effect=current_effect,
            dispatch_admission_effect_snapshot=effect_snapshot,
            provisional_check_candidate=candidate,
            installed_final_check_reissuer=reissue)

    def _verify_dispatch_owner_graph_locked(
            self, namespace, witness, admission, graph_epoch,
            installed_installation_id):
        """Join the current Owner head to its durable graph issue proof."""
        from .authority_service.v2_owner_contract import (
            OwnerGraphCommitProofV1, canonical_digest as owner_digest,
        )

        db = self.__store._db
        metadata, epoch = self._v2_graph_stamp(namespace)
        grant_row = db.execute(
            "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
            (owner_grant_key(*namespace.as_tuple).token,),
        ).fetchone()
        proof_row = db.execute(
            "SELECT operation_id,request_digest,grant_id,grant_digest,"
            "graph_incarnation,graph_access_epoch,graph_epoch,"
            "graph_receipt_digest,proof_json "
            "FROM graph_owner_issue_operations_v1 WHERE bot=? AND persona=?",
            namespace.as_tuple,
        ).fetchone()
        epochs = db.execute(
            "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
            "WHERE bot=? AND persona=?", namespace.as_tuple,
        ).fetchone()
        if (grant_row is None or proof_row is None or epochs is None
                or epoch.revision != graph_epoch):
            raise UnavailableGuard("current dispatch Owner graph proof absent; HOLD")
        try:
            grant = json.loads(grant_row[1])
            validate_owner_grant_v1(grant)
            proof = OwnerGraphCommitProofV1(
                namespace, proof_row[0], proof_row[1], proof_row[2],
                proof_row[3], proof_row[4], grant["grant_revision"],
                proof_row[5], proof_row[6], proof_row[7])
        except (TypeError, ValueError, KeyError) as exc:
            raise UnavailableGuard("current dispatch Owner graph proof invalid; HOLD") from exc
        guard = witness.guard
        if (grant_row != (1, canonical_json(grant), 1)
                or proof_row[8] != canonical_json(asdict(proof))
                or "sha256:" + canonical_digest(grant) != proof.grant_digest
                or (witness.issue_operation_id, witness.grant_id,
                    witness.grant_digest) != (
                        proof.operation_id, proof.grant_id, proof.grant_digest)
                or (grant["issue_operation_id"], grant["grant_id"]) != (
                    proof.operation_id, proof.grant_id)
                or (grant["graph_incarnation"], proof.graph_incarnation,
                    admission.graph_incarnation) != (
                        metadata.requirements.graph_incarnation,) * 3
                or grant["activation_generation"]
                != metadata.requirements.activation_generation
                or grant["scope"] != "/".join(namespace.as_tuple)
                or proof.graph_access_epoch > epochs[0]
                or proof.graph_epoch > epoch.revision
                or (admission.access_epoch, admission.delete_epoch)
                != epochs
                or admission.owner_head_ref != grant["grant_id"]
                or admission.purpose not in grant["purposes"]
                or not set(admission.audience).issubset(grant["audiences"])
                or guard.namespace != namespace
                or guard.authority_id != metadata.requirements.authority_id
                or guard.authority_id != grant["authority_id"]
                or guard.installation_id != grant["installation_id"]
                or guard.installation_id != installed_installation_id
                or guard.authorization_revision != grant["grant_revision"]
                or guard.authorization_head != owner_digest(proof)
                or guard.minimum_revocation_revision != 0
                or guard.minimum_revocation_epoch != 0
                or guard.pending_revoke_operation_id is not None
                or metadata.requirements.revocation_epoch != 0):
            raise UnavailableGuard("current dispatch Owner authorization differs; HOLD")
        return epochs

    def _commit_dispatch_claim_atom_in_transaction(
            self, namespace: NamespaceId, value, claimed_receipt):
        """Persist an already verified final claim and recovery stamp atomically.

        This is a private transaction primitive, not the handoff authorizer.
        Its caller must have checked every current guard in this same write
        transaction. No public route invokes it until that verifier exists.
        """
        from .authority_service.v2_contract import (
            MutationReceiptV2, canonical_digest as authority_digest,
        )
        from .runtime.dispatch_graph_claim import (
            DispatchGraphClaimValueV1, dispatch_claim_graph_write,
        )

        store = self.__store
        db = store._db
        if not store._lock._is_owned() or not db.in_transaction:
            raise RuntimeError("dispatch claim requires the final graph transaction")
        if (type(namespace) is not NamespaceId
                or type(value) is not DispatchGraphClaimValueV1
                or type(claimed_receipt) is not MutationReceiptV2
                or namespace.as_tuple != (value.bot_id, value.persona_id)):
            raise UnavailableGuard("dispatch claim typed identity differs")
        pending = claimed_receipt.pending
        anchor = claimed_receipt.after_anchor
        if (claimed_receipt.durable_state != "committed"
                or pending.phase != "claimed"
                or pending.binding.operation_id != value.operation_id
                or pending.binding.origin.effect_id != value.effect_id
                or pending.binding.origin.activity_id != value.activity_id
                or pending.binding.origin.admission_ref != value.admission_ref
                or pending.binding.graph_incarnation != value.graph_incarnation
                or pending.permit.namespace != value.authority_namespace
                or pending.permit.fence_epoch != value.p2_fence_epoch
                or claimed_receipt.updated_revision != value.p2_revision
                or anchor.execution_seq != value.p2_execution_seq
                or anchor.execution_digest != value.p2_execution_digest
                or authority_digest(pending.binding) != value.binding_digest
                or authority_digest(claimed_receipt)
                != value.claimed_receipt_digest
                or authority_digest(replace(
                    pending.permit, revision=claimed_receipt.updated_revision,
                    pinned_anchor=anchor)) != value.p2_permit_digest):
            raise UnavailableGuard("dispatch claim differs from committed P2")
        metadata, epoch = self._v2_graph_stamp(namespace)
        requirements = metadata.requirements
        if (requirements.graph_incarnation != value.graph_incarnation
                or requirements.authority_namespace != value.authority_namespace
                or not self._accounting_anchor_covers(requirements, anchor)):
            raise StaleRead("dispatch claim recovery watermark differs from P2")
        write = dispatch_claim_graph_write(value)
        event_id = "dispatch-claim:" + value.effect_id
        existing = db.execute(
            "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
            (write.key.token,),
        ).fetchone()
        if existing is not None:
            if (requirements.deletion_seq != anchor.deletion_seq
                    or requirements.deletion_digest != anchor.deletion_digest
                    or requirements.execution_seq != anchor.execution_seq
                    or requirements.execution_digest != anchor.execution_digest
                    or requirements.revocation_epoch != anchor.revocation_epoch):
                raise StaleRead("dispatch claim replay lacks its P2 recovery stamp")
            if (existing[0] != 1 or existing[2] != 1
                    or json.loads(existing[1]) != write.value):
                raise EventConflict("dispatch effect already has a different graph claim")
            event_row = db.execute(
                "SELECT epoch_revision FROM graph_events WHERE bot=? AND persona=? "
                "AND session=? AND event_id=?",
                namespace.as_tuple + (value.activity_id, event_id),
            ).fetchone()
            if event_row is None or event_row[0] > epoch.revision:
                raise UnavailableGuard("dispatch claim event is unavailable")
            return GraphVersion(write.key, 1), event_row[0], False
        event = Event(
            Scope(*namespace.as_tuple, value.activity_id), event_id, time.time(),
            "dispatch_graph_claim_v1", {"claim_digest": canonical_digest(write.value)},
        )
        from .runtime.d13_outbound_observation_v1 import reserve_natural_outbound_slot_at_claim_v1
        turn_writes, turn_reads = reserve_natural_outbound_slot_at_claim_v1(
            db, namespace, pending.binding.origin.operation_id)
        candidate = GraphCandidate(
            event, (GraphVersion(write.key, 0), *turn_reads), (write, *turn_writes), (epoch,))
        replacement = replace(
            requirements,
            deletion_seq=anchor.deletion_seq,
            deletion_digest=anchor.deletion_digest,
            execution_seq=anchor.execution_seq,
            execution_digest=anchor.execution_digest,
            revocation_epoch=anchor.revocation_epoch,
        )

        def stamp_claim(_db, receipt):
            if (receipt.status != "committed"
                    or GraphVersion(write.key, 1) not in receipt.revisions
                    or {item.key for item in receipt.revisions} != {item.key for item in candidate.writes}):
                raise EventConflict("dispatch claim graph commit differs")
            store.cas_graph_recovery_metadata(
                metadata, replacement, _capability=self.__graph_capability)

        receipt = GraphStore._graph_commit_in_transaction(
            store, candidate, _receipt_hook=stamp_claim,
            _capability=self.__graph_capability)
        return GraphVersion(write.key, 1), receipt.epoch.revision, True

    def register_dispatch_final_claim_writer_v1(
            self, bootstrap: object, *, route_port=None, issuer_id=None):
        """Give trusted host composition one synchronous GraphWorker callback.

        The reverse mTLS listener registers this callback in its exclusive
        window. Merely receiving the five Authority DTOs never grants a claim.
        """
        self._admin(bootstrap)
        from .host.authority_profile import AdminIngressClockPolicy
        from .host.installed_dispatch_route import InstalledDispatchRoutePort

        port = self.__content_fence_v2
        if (not isinstance(self.__store, ProductionGraphStore)
                or port is None
                or type(route_port) is not InstalledDispatchRoutePort
                or type(issuer_id) is not str or not issuer_id
                or type(self.__dispatch_clock_policy) is not AdminIngressClockPolicy
                or not callable(getattr(port, "read_ingress_clock", None))
                or getattr(type(port), "installation_grant", None) is None):
            raise UnavailableGuard("installed final dispatch authorities unavailable; HOLD")
        return _InstalledDispatchFinalClaimWriterV1(
            self, port, self.__dispatch_clock_policy, route_port, issuer_id)

    def register_natural_dispatch_final_claim_writer_v2(
            self, bootstrap: object, *, route_port=None, issuer_id=None):
        """Install the separate V2 P2 claim callback for one-shot host send."""
        self._admin(bootstrap)
        from .host.authority_profile import AdminIngressClockPolicy
        from .host.installed_dispatch_route import InstalledDispatchRoutePort

        port = self.__content_fence_v2
        if (not isinstance(self.__store, ProductionGraphStore)
                or port is None
                or type(route_port) is not InstalledDispatchRoutePort
                or type(issuer_id) is not str or not issuer_id
                or type(self.__dispatch_clock_policy) is not AdminIngressClockPolicy
                or not callable(getattr(port, "read_ingress_clock", None))
                or getattr(type(port), "installation_grant", None) is None):
            raise UnavailableGuard("natural final claim installation absent; HOLD")
        return _InstalledNaturalDispatchFinalClaimWriterV2(
            self, port, self.__dispatch_clock_policy, route_port, issuer_id)

    def _commit_natural_dispatch_final_claim_v2(
            self, context, binding, claimed, witness, authority_snapshot,
            route_port=None, issuer_id=None, *, frozen_clock=None,
            frozen_installation_id=None):
        """Recheck one V2 paid batch and current private route at the P2 fence."""
        from .authority_service.reverse_handoff import (
            require_exact_authority_snapshot,
            require_exact_reverse_handoff_identity,
        )
        from .authority_service.v2_contract import (
            AuthorityDispatchSnapshotV1, DispatchGraphClaimReceiptV1,
            DispatchHandoffContextV1, ExecutionBindingV2, MutationReceiptV2,
            OwnerDispatchWitnessV1,
            canonical_digest as authority_digest,
        )
        from .host.authority_profile import AdminIngressClockPolicy
        from .host.installed_dispatch_route import (
            InstalledDispatchRoutePort, InstalledDispatchRouteReadV1,
        )
        from .host.v2_fence_port import VerifiedIngressClockV2
        from .runtime.dispatch_admission import load_admission, load_request
        from .runtime.dispatch_budget_check import (
            evaluate_dispatch_budget_authority_snapshot,
        )
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.natural_dispatch_claim_v2 import (
            prepare_natural_dispatch_claim_v2,
        )
        from .runtime.natural_generation_issue_v2 import (
            read_original_scoped_query_proof_v2,
        )
        from .runtime.natural_reply_job_v2 import read_original_preparation
        from .runtime.reply_entity_route_v2 import (
            read_current_reply_entity_route_binding_v2,
        )

        if (type(context) is not DispatchHandoffContextV1
                or type(binding) is not ExecutionBindingV2
                or type(claimed) is not MutationReceiptV2
                or type(witness) is not OwnerDispatchWitnessV1
                or type(authority_snapshot) is not AuthorityDispatchSnapshotV1):
            raise UnavailableGuard("natural P2 typed evidence required; HOLD")
        try:
            namespace = NamespaceId(*binding.graph_namespace.split("/"))
            require_exact_reverse_handoff_identity(
                namespace_ref(namespace), context, binding, claimed)
            require_exact_authority_snapshot(
                context, witness, authority_snapshot)
        except (TypeError, ValueError, RuntimeError) as exc:
            raise UnavailableGuard("natural P2 chain differs; HOLD") from exc
        permit = context.permit
        if (type(frozen_clock) is not VerifiedIngressClockV2
                or type(frozen_installation_id) is not str
                or frozen_clock.sample.installation_id != frozen_installation_id
                or frozen_clock.sample.authority_id != permit.authority_id
                or type(self.__dispatch_clock_policy) is not AdminIngressClockPolicy
                or frozen_clock.sample.source_id
                   != self.__dispatch_clock_policy.source_id
                or witness.guard.installation_id != frozen_installation_id
                or type(route_port) is not InstalledDispatchRoutePort):
            raise UnavailableGuard("natural P2 installed clock or route absent; HOLD")
        now_utc = trusted_upper(frozen_clock)
        store = self.__store
        with store._lock:
            db = store._db
            db.execute("BEGIN")
            try:
                admission_receipt = load_admission(
                    db, namespace, binding.origin.admission_ref)
                issued = (load_request(
                    db, namespace, binding.origin.admission_ref)
                          if admission_receipt is not None else None)
                recovered = self._get_natural_dispatch_candidate_evidence_locked(
                    namespace, binding.operation_id)
                if (issued is None or recovered is None
                        or issued[0] != admission_receipt):
                    raise UnavailableGuard("natural original admission absent; HOLD")
                request = issued[1]
                segment = self._get_natural_dispatch_text_segment_locked(
                    namespace, request, now_utc=now_utc)
                if segment is None or segment[1] != recovered.evidence:
                    raise UnavailableGuard("natural original segment absent; HOLD")
                selectors = (
                    admission_receipt.admission.account_ref,
                    admission_receipt.admission.destination_ref,
                    admission_receipt.admission.scene_ref)
                route_digest = canonical_digest({
                    "account_ref": selectors[0],
                    "destination_ref": selectors[1],
                    "scene_ref": selectors[2]})
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise
        live_route = route_port.read_live_host_scene_only(
            namespace=namespace, account_ref=selectors[0],
            destination_ref=selectors[1], scene_ref=selectors[2],
            route_digest=route_digest)
        if (type(live_route) is not InstalledDispatchRouteReadV1
                or live_route.status != "verified_route"
                or live_route.route_digest != route_digest
                or live_route.current_scene is None):
            raise UnavailableGuard("natural live host route unavailable; HOLD")
        with store._lock:
            db.execute("BEGIN IMMEDIATE")
            try:
                metadata, epoch = self._v2_graph_stamp(namespace)
                anchor = authority_snapshot.anchor
                if (metadata.requirements.graph_incarnation
                    != binding.graph_incarnation
                        or metadata.requirements.authority_namespace
                        != permit.namespace
                        or not self._accounting_anchor_covers(
                            metadata.requirements, anchor)):
                    raise UnavailableGuard("natural P2 graph stamp differs; HOLD")
                admission_receipt = load_admission(
                    db, namespace, binding.origin.admission_ref)
                issued = (load_request(
                    db, namespace, binding.origin.admission_ref)
                          if admission_receipt is not None else None)
                recovered = self._get_natural_dispatch_candidate_evidence_locked(
                    namespace, binding.operation_id)
                if issued is None or recovered is None:
                    raise UnavailableGuard("natural P2 original absent; HOLD")
                request = issued[1]
                if issued[0] != admission_receipt or (
                        admission_receipt.admission.account_ref,
                        admission_receipt.admission.destination_ref,
                        admission_receipt.admission.scene_ref) != selectors:
                    raise UnavailableGuard("natural P2 route changed; HOLD")
                segment = self._get_natural_dispatch_text_segment_locked(
                    namespace, request, now_utc=now_utc)
                if segment is None or segment[1] != recovered.evidence:
                    raise UnavailableGuard("natural P2 segment changed; HOLD")
                if (live_route.current_scene.scene_ref != selectors[2]
                        or live_route.current_scene.namespace != namespace):
                    raise UnavailableGuard("natural live scene changed; HOLD")
                operation = self._get_operation_locked(
                    namespace, request.operation_id)
                if operation is None:
                    raise UnavailableGuard("natural P2 operation absent; HOLD")
                batch_row = db.execute(
                    "SELECT value,valid FROM graph_history WHERE token=? "
                    "AND event_bot=? AND event_persona=? "
                    "AND event_session=? AND event_id=?",
                    (recovered.evidence.batch_ref,) + namespace.as_tuple + (
                        request.activity_id, request.operation_id),
                ).fetchone()
                if batch_row is None or batch_row[1] != 1:
                    raise UnavailableGuard("natural P2 batch history absent; HOLD")
                batch = json.loads(batch_row[0])
                parent_row = db.execute(
                    "SELECT parent_original_id FROM "
                    "graph_natural_generation_preparations_v2 WHERE bot=? "
                    "AND persona=? AND original_operation_id=?",
                    namespace.as_tuple + (
                        recovered.evidence.generation_original_operation_id,),
                ).fetchone()
                if parent_row is None:
                    raise UnavailableGuard("natural P2 generation original absent; HOLD")
                generation = read_original_preparation(
                    db, namespace, parent_row[0], "generation")
                if generation is None:
                    raise UnavailableGuard("natural P2 generation seal absent; HOLD")
                scoped = read_original_scoped_query_proof_v2(db, generation)
                _inputs, route = self._current_post_c02_reply_route_locked(
                    namespace, generation.seal.c02_operation_id,
                    generation.seal.source_ref, now_utc, epoch)
                _snapshot, query = self._dispatch_full_graph_snapshot_locked(
                    namespace)
                binding_route = read_current_reply_entity_route_binding_v2(
                    db, namespace, route, query, now_utc=now_utc)
                if evaluate_dispatch_budget_authority_snapshot(
                        context, witness, authority_snapshot,
                        namespace=namespace,
                        proposed_footprint=binding.origin.footprint):
                    raise UnavailableGuard("natural P2 Authority budget conflicts; HOLD")
                owner_epochs = self._verify_dispatch_owner_graph_locked(
                    namespace, witness, admission_receipt.admission,
                    query.revision, frozen_installation_id)
                prepared = prepare_natural_dispatch_claim_v2(
                    db=db, namespace=namespace,
                    admission_receipt=admission_receipt,
                    request=request, evidence=recovered.evidence,
                    operation=operation, batch=batch,
                    original_scope_proof=scoped,
                    current_route=binding_route, context=context,
                    binding=binding, claimed=claimed, witness=witness,
                    authority_snapshot=authority_snapshot,
                    now_utc=now_utc)
                version, graph_epoch, _ = (
                    self._commit_dispatch_claim_atom_in_transaction(
                        namespace, prepared.value, claimed))
                claim_receipt = DispatchGraphClaimReceiptV1(
                    authority_digest(context), binding.graph_namespace,
                    binding.graph_incarnation, f"graph:{version.revision}",
                    graph_epoch, owner_epochs[0], owner_epochs[1],
                    "dispatch-claim:" + binding.origin.effect_id,
                    "sha256:" + canonical_digest(asdict(prepared.value)),
                    issuer_id)
                db.execute("COMMIT")
                return claim_receipt
            except BaseException:
                db.execute("ROLLBACK")
                raise

    def _commit_dispatch_final_claim_v1(
            self, context, binding, claimed, witness, authority_snapshot,
            route_port=None, issuer_id=None, *, frozen_clock=None,
            frozen_installation_id=None):
        """Recheck the exact P2 and current graph in one write transaction.

        All Authority reads precede the GraphStore lock. Incomplete domain
        checks explicitly HOLD before the private claim atom can be written.
        """
        from .authority_service.reverse_handoff import (
            require_exact_authority_snapshot,
            require_exact_reverse_handoff_identity,
        )
        from .authority_service.v2_contract import (
            AuthorityDispatchSnapshotV1, DispatchHandoffContextV1,
            ExecutionBindingV2, MutationReceiptV2, OwnerDispatchWitnessV1,
            canonical_digest as authority_digest,
        )
        from .authority_service.v2_execution_bridge import CurrentEffectReadV2
        from .runtime.dispatch_budget_check import (
            evaluate_dispatch_budget_authority_snapshot,
        )
        from .runtime.dispatch_current_commitments import (
            read_current_d08_action_conflict_evidence,
            read_current_d08_conflict_facts,
        )
        from .runtime.dispatch_current_commitment_check import (
            read_current_commitment_criteria_v1,
        )
        from .runtime.dispatch_admission import check_receipts_against_specs
        from .runtime.dispatch_graph_claim import DispatchGraphClaimValueV1
        from .authority_service.v2_contract import DispatchGraphClaimReceiptV1
        from .runtime.dispatch_current_projection import (
            read_current_dispatch_projection,
        )
        from .runtime.dispatch_current_social_checks import (
            verify_current_social_checks,
        )
        from .runtime.dispatch_current_segment import read_current_dispatch_segment
        from .runtime.installed_dispatch_admission_issuer import (
            inspect_current_d11_dispatch_budget,
        )
        from .domains.d06 import SourceGrantRead, provide_source_grant_check
        from .domains.d08 import GoalExecutionProvider
        from .domains.d03.context import ContextProvider
        from .domains.d05.relationship import RelationshipProvider
        from .runtime.first_ingress_v2 import trusted_upper
        from .host.v2_fence_port import VerifiedIngressClockV2
        from .host.authority_profile import AdminIngressClockPolicy
        from .host.installed_dispatch_route import (
            InstalledDispatchRoutePort, InstalledDispatchRouteReadV1,
        )

        if (type(context) is not DispatchHandoffContextV1
                or type(binding) is not ExecutionBindingV2
                or type(claimed) is not MutationReceiptV2
                or type(witness) is not OwnerDispatchWitnessV1
                or type(authority_snapshot) is not AuthorityDispatchSnapshotV1):
            raise UnavailableGuard("typed final dispatch P2 evidence required; HOLD")
        try:
            namespace = NamespaceId(*binding.graph_namespace.split("/"))
            require_exact_reverse_handoff_identity(
                namespace_ref(namespace), context, binding, claimed)
            require_exact_authority_snapshot(context, witness, authority_snapshot)
        except (TypeError, ValueError, RuntimeError) as exc:
            raise UnavailableGuard("final dispatch P2 chain differs; HOLD") from exc
        permit = context.permit
        if (witness.context_digest != authority_digest(context)
                or witness.authority_namespace != permit.namespace
                or witness.graph_namespace != binding.graph_namespace
                or witness.guard.authority_id != permit.authority_id
                or witness.guard.namespace != namespace):
            raise UnavailableGuard("final dispatch Owner witness differs; HOLD")

        # Authority supplied this complete current snapshot in its reverse
        # callback and rechecks it after the graph claim. Re-entering the
        # Authority service here would deadlock the synchronous handoff.
        if (type(frozen_clock) is not VerifiedIngressClockV2
                or type(frozen_installation_id) is not str
                or frozen_clock.sample.installation_id != frozen_installation_id
                or frozen_clock.sample.authority_id != permit.authority_id
                or type(self.__dispatch_clock_policy) is not AdminIngressClockPolicy
                or frozen_clock.sample.source_id
                    != self.__dispatch_clock_policy.source_id
                or witness.guard.installation_id != frozen_installation_id):
            raise UnavailableGuard("prepared paired final claim clock absent; HOLD")
        anchor = authority_snapshot.anchor
        now_utc = trusted_upper(frozen_clock)
        own = tuple(item for item in authority_snapshot.unresolved_effects
                    if item.effect_id == permit.effect_id)
        if (len(own) != 1 or own[0].phase != "claimed"
                or own[0].operation_id != permit.operation_id
                or own[0].mutation_id != claimed.pending.mutation_id
                or own[0].execution_seq != anchor.execution_seq
                or own[0].append_digest != anchor.execution_digest
                or claimed.pending.expected_append_digest != anchor.execution_digest):
            raise UnavailableGuard("current Authority P2 effect differs; HOLD")
        effect = CurrentEffectReadV2(
            permit.authority_id, permit.namespace, permit.effect_id,
            permit.generation, "unresolved", anchor.execution_seq,
            anchor.execution_digest, own[0].execution_seq,
            claimed.pending.expected_append_id, own[0].append_digest,
            own[0].mutation_id)

        # Lock order: release the short graph selector read before the host
        # loop verifies the live AstrBot scene. Re-read that selector under the
        # final BEGIN IMMEDIATE; no host or Authority call occurs under it.
        store = self.__store
        if type(route_port) is not InstalledDispatchRoutePort:
            raise UnavailableGuard("installed final dispatch route reader unavailable; HOLD")
        with store._lock:
            db = store._db
            db.execute("BEGIN")
            try:
                from .runtime.dispatch_admission import load_admission
                receipt = load_admission(db, namespace, binding.origin.admission_ref)
                if receipt is None:
                    raise UnavailableGuard("final dispatch admission is absent; HOLD")
                frozen = receipt.admission
                from .runtime.dispatch_current_segment import read_current_dispatch_segment
                pre_route = read_current_dispatch_segment(
                    db, namespace, frozen.admission_ref, now_utc=now_utc)
                selectors = (frozen.account_ref, frozen.destination_ref,
                             frozen.scene_ref, pre_route.route_digest)
            finally:
                db.execute("ROLLBACK")
        live_route = route_port.read_live_host_scene_only(
            namespace=namespace, account_ref=selectors[0],
            destination_ref=selectors[1], scene_ref=selectors[2],
            route_digest=selectors[3])
        if (type(live_route) is not InstalledDispatchRouteReadV1
                or live_route.status != "verified_route"
                or live_route.route_digest != selectors[3]
                or live_route.graph_epoch is not None
                or live_route.current_scene is None):
            raise UnavailableGuard("current installed AstrBot route unavailable; HOLD")

        with store._lock:
            db = store._db
            db.execute("BEGIN IMMEDIATE")
            try:
                metadata, _ = self._v2_graph_stamp(namespace)
                requirements = metadata.requirements
                if (requirements.namespace != namespace
                        or requirements.graph_incarnation != binding.graph_incarnation
                        or requirements.authority_namespace != permit.namespace
                        or requirements.deletion_seq != anchor.deletion_seq
                        or requirements.revocation_epoch != anchor.revocation_epoch
                        or not self._accounting_anchor_covers(requirements, anchor)):
                    raise UnavailableGuard("final dispatch graph/Authority stamp differs; HOLD")
                provision_row = self._provision_row(db, namespace)
                if (provision_row is None or
                        self._decode_provision_receipt(provision_row).installation_id
                        != witness.guard.installation_id):
                    raise UnavailableGuard("final dispatch Owner installation differs; HOLD")
                prerequisite = self._read_dispatch_final_claim_prerequisite_locked(
                    namespace, binding, claimed, context.handoff_id,
                    now_utc=now_utc)
                from .runtime.dispatch_admission import load_admission
                admission_receipt = load_admission(
                    db, namespace, prerequisite.admission_ref)
                if (admission_receipt is None
                        or admission_receipt.admission.clock_policy_ref
                        != self.__dispatch_clock_policy.source_id
                        or admission_receipt.admission.clock_policy_digest
                        != canonical_digest(asdict(self.__dispatch_clock_policy))):
                    raise UnavailableGuard("final dispatch installed clock differs; HOLD")
                graph, query = self._dispatch_full_graph_snapshot_locked(namespace)
                segment = read_current_dispatch_segment(
                    db, namespace, prerequisite.admission_ref, now_utc=now_utc)
                if ((admission_receipt.admission.account_ref,
                     admission_receipt.admission.destination_ref,
                     admission_receipt.admission.scene_ref,
                     segment.route_digest) != selectors):
                    raise UnavailableGuard("final dispatch route changed during host read; HOLD")
                projection = read_current_dispatch_projection(
                    db, namespace, graph, query)
                blockers = evaluate_dispatch_budget_authority_snapshot(
                    context, witness, authority_snapshot, namespace=namespace,
                    proposed_footprint=binding.origin.footprint)
                if blockers:
                    raise UnavailableGuard(
                        "final dispatch Authority budget conflicts: "
                        + ",".join(blockers) + "; HOLD")
                facts = read_current_d08_conflict_facts(
                    db, namespace, graph, query)
                actions = tuple(item for item in facts.action_intents
                                if item.identity.operation_id == binding.operation_id
                                and item.identity.effect_id == binding.origin.effect_id)
                if len(actions) != 1:
                    raise UnavailableGuard("current D08 action is absent or ambiguous; HOLD")
                current_reply_route = None
                if binding.operation_id.startswith("post-c02-reply:"):
                    current_reply_route = self._read_current_post_c02_final_route_locked(
                        namespace, admission_receipt.admission, actions[0],
                        segment, graph, query, now_utc=now_utc)
                action = read_current_d08_action_conflict_evidence(
                    db, namespace, graph, query, actions[0].action_id,
                    permit, effect)
                if (action.effect_state != "unresolved"
                        or action.action_cancellation_state != "clear"
                        or action.job_cancellation_state != "clear"
                        or projection.coverage != "full"
                        or projection.missing_sources):
                    raise UnavailableGuard("current D08/graph checks incomplete; HOLD")
                candidate = self._get_dispatch_candidate_evidence_locked(
                    namespace, binding.operation_id)
                if candidate is None:
                    raise UnavailableGuard("current D08 schema candidate absent; HOLD")
                schema_ref, schema_revision = candidate.write_versions[1]
                schema_atom = graph.get(AtomKey.from_token(schema_ref))
                if (schema_atom is None or not schema_atom.valid
                        or schema_atom.revision != schema_revision):
                    raise UnavailableGuard("current D08 action schema differs; HOLD")
                schema = next(spec for spec in GoalExecutionProvider().register_types()
                              if spec.name == "d08.action_schema.v1").validator(
                                  schema_atom.value)
                commitment = read_current_commitment_criteria_v1(
                    db, namespace, graph, query, actions[0], schema,
                    claimed, context, witness, authority_snapshot, effect,
                    now_utc=now_utc)
                d03 = self.__providers.get("d03")
                d05 = self.__providers.get("d05")
                if (d03 is None or d05 is None
                        or type(d03[0]) is not ContextProvider
                        or type(d05[0]) is not RelationshipProvider
                        or len(admission_receipt.admission.audience) != 1):
                    raise UnavailableGuard("current D03/D05 provider or scope absent; HOLD")
                try:
                    catalogue_current = all(
                        store._registry.spec(spec.name) == spec
                        for provider in (d03[0], d05[0])
                        for spec in provider.type_specs())
                except (AttributeError, KeyError, TypeError, ValueError):
                    catalogue_current = False
                receipts = {
                    item.check_kind: item
                    for item in admission_receipt.admission.check_receipts}
                if set(receipts) != {item.check_kind for item in schema.required_checks}:
                    raise UnavailableGuard("current RequiredCheck set is incomplete; HOLD")
                role = receipts.get("role_binding")
                boundary = receipts.get("boundary")
                if role is None or boundary is None:
                    raise UnavailableGuard("current D03/D05 receipts absent; HOLD")
                social = verify_current_social_checks(
                    db, graph, projection, actions[0], schema, role, boundary,
                    context=d03[0], scene_ref=admission_receipt.admission.scene_ref,
                    audience_scope=admission_receipt.admission.audience[0],
                    now_utc=now_utc,
                    current_catalogue_confirmed=catalogue_current)
                if social.status != "verified" or social.verified is not True:
                    raise UnavailableGuard(
                        "current D03/D05 check incomplete: " + social.reason + "; HOLD")
                from .domains.d08.execution import BASE_REQUIRED_PROVIDERS
                if (schema.proactive or binding.origin.proactive_contact
                        or schema.action_kind != "message"
                        or {(item.check_kind, item.provider_id)
                            for item in schema.required_checks}
                        != set(BASE_REQUIRED_PROVIDERS)
                        or len(schema.required_checks) != len(BASE_REQUIRED_PROVIDERS)
                        or schema.required_checks != actions[0].required_checks):
                    raise UnavailableGuard(
                        "final dispatch action needs an unavailable current check; HOLD")
                if current_reply_route is not None:
                    source_receipt = receipts.get("source_grant")
                    budget_receipt = receipts.get("dispatch_budget")
                    source_coverage = (
                        query.scope_ref == "all"
                        and graph.epochs == (NamespaceEpoch(
                            *namespace.as_tuple, query.revision),)
                        and len(graph.atoms) == db.execute(
                            "SELECT COUNT(*) FROM graph_atoms WHERE bot=? AND persona=?",
                            namespace.as_tuple).fetchone()[0]
                    )
                    source_barrier = (
                        source_coverage
                        and anchor == context.permit.pinned_anchor
                        and metadata.requirements.deletion_seq == anchor.deletion_seq
                        and metadata.requirements.revocation_epoch == anchor.revocation_epoch
                        and db.execute(
                            "SELECT access_epoch,delete_epoch "
                            "FROM graph_authority_epochs WHERE bot=? AND persona=?",
                            namespace.as_tuple).fetchone() == (
                            admission_receipt.admission.access_epoch,
                            admission_receipt.admission.delete_epoch)
                        and set(actions[0].source_refs).issubset(
                            current_reply_route[1])
                    )
                    if source_receipt is None or budget_receipt is None:
                        raise UnavailableGuard("final reply D06/D11 check is absent; HOLD")
                    current_source_check = provide_source_grant_check(
                        actions[0], SourceGrantRead(
                            graph, admission_receipt.admission.audience,
                            "expression", source_coverage, source_barrier),
                        valid_until=source_receipt.valid_until)
                    current_budget_check = inspect_current_d11_dispatch_budget(
                        db, actions[0], d11_issuer=self.__d11_issuer,
                        d02_issuer=self.__d02_issuer, now_utc=now_utc)
                    if (current_source_check != source_receipt
                            or current_source_check.result != "pass"
                            or current_source_check.coverage != "full"
                            or current_budget_check.status != "check_pass"
                            or current_budget_check.receipt != budget_receipt):
                        raise UnavailableGuard(
                            "final reply current D06/D11 checks differ; HOLD")
                try:
                    check_receipts_against_specs(
                        admission_receipt.admission, schema.required_checks,
                        now_utc)
                except ValueError as exc:
                    raise UnavailableGuard(
                        "final dispatch frozen RequiredCheck differs; HOLD") from exc
                owner_epochs = self._verify_dispatch_owner_graph_locked(
                    namespace, witness, admission_receipt.admission,
                    query.revision, frozen_installation_id)
                if (live_route.route_digest != segment.route_digest
                        or live_route.current_scene.scene_ref
                        != admission_receipt.admission.scene_ref
                        or live_route.current_scene.namespace != namespace):
                    raise UnavailableGuard("final dispatch live scene differs; HOLD")
                evidence_digest = "sha256:" + canonical_digest({
                    "prerequisite": prerequisite,
                    "graph_epoch": query.revision,
                    "segment": segment,
                    "reply_account_route": current_reply_route,
                    "route": live_route,
                    "projection": projection.digest,
                    "social": social,
                    "commitment": commitment,
                    "current_source_check": (
                        current_source_check if current_reply_route is not None else None),
                    "current_budget_check": (
                        current_budget_check if current_reply_route is not None else None),
                    "action": action,
                    "owner_witness": witness,
                    "owner_epochs": owner_epochs,
                    "authority_snapshot": authority_snapshot,
                })
                value = DispatchGraphClaimValueV1(
                    namespace.bot_id, namespace.persona_id,
                    binding.graph_incarnation, binding.origin.activity_id,
                    binding.origin.effect_id, binding.operation_id,
                    context.handoff_id, prerequisite.admission_ref,
                    permit.namespace, authority_digest(context.permit),
                    permit.fence_epoch, claimed.updated_revision,
                    anchor.execution_seq, anchor.execution_digest,
                    authority_digest(context), authority_digest(witness),
                    authority_digest(binding), authority_digest(claimed),
                    evidence_digest,
                )
                version, graph_epoch, _ = self._commit_dispatch_claim_atom_in_transaction(
                    namespace, value, claimed)
                claim_receipt = DispatchGraphClaimReceiptV1(
                    authority_digest(context), binding.graph_namespace,
                    binding.graph_incarnation, f"graph:{version.revision}",
                    graph_epoch, owner_epochs[0], owner_epochs[1],
                    "dispatch-claim:" + binding.origin.effect_id,
                    "sha256:" + canonical_digest(asdict(value)), issuer_id,
                )
                db.execute("COMMIT")
                return claim_receipt
            except BaseException:
                db.execute("ROLLBACK")
                raise

    def get_dispatch_text_segment(self, authority: AuthorityContext,
                                  lease: object, request):
        """Read one D09 body through its committed D11 admission and graph fence.

        The route is limited to the AstrBot ingress identity profile. This
        read is content provenance, not a current host send permit.
        """
        from .dispatch_runtime import DispatchRequest

        if type(request) is not DispatchRequest or request.namespace != "/".join(
                authority.namespace.as_tuple):
            raise ValueError("dispatch request namespace differs")
        self._authorize(lease, authority, frozenset({"d08", "d09", "d11"}))
        reader = lambda: self._get_dispatch_text_segment_locked(
            authority.namespace, request)
        if (isinstance(self.__store, ProductionGraphStore)
                and self.__content_fence_v2 is not None):
            return self._read_v2(authority, reader)
        with self._content_fence(authority.namespace,
                                 authority.activation_generation, "read"):
            with self.__store._lock:
                self._admit_content(authority.namespace,
                                    authority.activation_generation, "read")
                return reader()

    def get_natural_dispatch_text_segment_v2(
            self, authority: AuthorityContext, lease: object, request):
        """Read one committed natural V2 segment before the separate P2 claim.

        Only the original graph batch and admission supply text.  This read
        never authorizes the external send by itself.
        """
        from .dispatch_runtime import DispatchRequest

        if (type(request) is not DispatchRequest
                or request.namespace != "/".join(authority.namespace.as_tuple)):
            raise ValueError("natural dispatch request namespace differs")
        self._authorize(lease, authority, frozenset({"d08", "d09", "d11"}))
        from .runtime.first_ingress_v2 import trusted_upper

        if self.__content_fence_v2 is None:
            raise UnavailableGuard("natural current dispatch clock is absent")
        now_utc = trusted_upper(self.__content_fence_v2.read_ingress_clock(
            self.__dispatch_clock_policy))
        def reader():
            db = self.__store._db
            db.execute("BEGIN")
            try:
                result = self._get_natural_dispatch_text_segment_locked(
                    authority.namespace, request, now_utc=now_utc)
                db.execute("COMMIT")
                return result
            except BaseException:
                db.execute("ROLLBACK")
                raise
        if (isinstance(self.__store, ProductionGraphStore)
                and self.__content_fence_v2 is not None):
            return self._read_v2(authority, reader)
        with self._content_fence(authority.namespace,
                                 authority.activation_generation, "read"):
            with self.__store._lock:
                self._admit_content(authority.namespace,
                                    authority.activation_generation, "read")
                return reader()

    def read_committed_natural_dispatch_v2(
            self, authority: AuthorityContext, lease: object,
            operation_id: str):
        """Recover only an admitted V2 outbox identity for the P2 handoff."""
        from .dispatch_runtime import DispatchRequest

        if type(operation_id) is not str or not operation_id:
            raise ValueError("natural dispatch operation ID required")
        self._authorize(lease, authority, frozenset({"d08", "d09", "d11"}))
        from .runtime.first_ingress_v2 import trusted_upper

        if self.__content_fence_v2 is None:
            raise UnavailableGuard("natural current dispatch clock is absent")
        now_utc = trusted_upper(self.__content_fence_v2.read_ingress_clock(
            self.__dispatch_clock_policy))

        def reader():
            namespace = authority.namespace
            db = self.__store._db
            db.execute("BEGIN")
            try:
                recovered = self._get_natural_dispatch_candidate_evidence_locked(
                    namespace, operation_id)
                if recovered is None:
                    db.execute("COMMIT")
                    return None
                admission_row = db.execute(
                    "SELECT admission_ref FROM graph_dispatch_admissions "
                    "WHERE bot=? AND persona=? AND operation_id=? AND effect_id=?",
                    namespace.as_tuple + (
                        operation_id, recovered.evidence.effect_id),
                ).fetchone()
                if admission_row is None:
                    raise UnavailableGuard("natural dispatch admission is absent")
                issued = load_request(db, namespace, admission_row[0])
                if issued is None:
                    raise UnavailableGuard("natural dispatch command is absent")
                admission_receipt, request = issued
                if (type(request) is not DispatchRequest
                        or admission_receipt.admission.candidate_digest
                           != recovered.evidence.digest
                        or admission_receipt.admission.batch_digest
                           != recovered.evidence.batch_digest
                        or (request.operation_id, request.effect_id,
                            request.payload_digest) != (
                            operation_id, recovered.evidence.effect_id,
                            recovered.evidence.payload_digest)):
                    raise UnavailableGuard("natural dispatch command differs")
                # The content reader independently checks batch history,
                # scoped predicates and the AstrBot route before text release.
                segment = self._get_natural_dispatch_text_segment_locked(
                    namespace, request, now_utc=now_utc)
                if segment is None or segment[1] != recovered.evidence:
                    raise UnavailableGuard("natural dispatch content is unavailable")
                committed = self._get_operation_fenced(
                    authority, operation_id, v2=True)
                if (committed is None or committed.status != "committed"
                        or len(committed.outbox_refs) != 1):
                    raise UnavailableGuard("natural dispatch outbox is absent")
                db.execute("COMMIT")
                return (admission_receipt, request, recovered.evidence, committed)
            except BaseException:
                db.execute("ROLLBACK")
                raise

        if (isinstance(self.__store, ProductionGraphStore)
                and self.__content_fence_v2 is not None):
            return self._read_v2(authority, reader)
        with self._content_fence(authority.namespace,
                                 authority.activation_generation, "read"):
            with self.__store._lock:
                self._admit_content(authority.namespace,
                                    authority.activation_generation, "read")
                return reader()

    def discover_pending_post_c02_natural_dispatch_v2(
            self, authority: AuthorityContext, lease: object, *,
            after: str | None = None, limit: int = 32
    ) -> NaturalPendingDispatchPageV2:
        """Page only committed natural outbox identities for restart recovery."""
        self._authorize(lease, authority, frozenset({"d08", "d09", "d11"}),
                        owner_read=True)
        if (after is not None and (type(after) is not str or not after)
                or type(limit) is not int or not 1 <= limit <= 64):
            raise ValueError("invalid natural dispatch recovery page")

        def reader():
            namespace = authority.namespace
            db = self.__store._db
            db.execute("BEGIN")
            try:
                metadata, epoch = self._v2_graph_stamp(namespace)
                rows = db.execute(
                    "SELECT b.operation_id,o.effect_id,b.outbox_ref "
                    "FROM graph_bundle_outbox b JOIN graph_bundle_operations o "
                    "ON o.bot=b.bot AND o.persona=b.persona "
                    "AND o.operation_id=b.operation_id WHERE b.bot=? "
                    "AND b.persona=? AND b.operation_id>? "
                    "AND b.phase='pending' AND json_extract(o.receipt_json,"
                    "'$.natural_dispatch_candidate.schema')="
                    "'sylanne.d11.natural_dispatch_candidate.v2' "
                    "ORDER BY b.operation_id LIMIT ?",
                    namespace.as_tuple + (after or "", limit + 1),
                ).fetchall()
                items = []
                for operation_id, effect_id, outbox_ref in rows:
                    recovered = self._get_natural_dispatch_candidate_evidence_locked(
                        namespace, operation_id)
                    if recovered is None:
                        continue
                    admission = db.execute(
                        "SELECT admission_ref FROM graph_dispatch_admissions "
                        "WHERE bot=? AND persona=? AND operation_id=? "
                        "AND effect_id=?",
                        namespace.as_tuple + (operation_id, effect_id),
                    ).fetchone()
                    if admission is None:
                        raise UnavailableGuard(
                            "pending natural outbox lacks admission; HOLD")
                    items.append(NaturalPendingDispatchItemV2(
                        operation_id, effect_id, outbox_ref))
                result = NaturalPendingDispatchPageV2(
                    namespace, tuple(items[:limit]),
                    rows[limit - 1][0] if len(rows) > limit else None,
                    metadata.graph_revision, epoch.revision)
                db.execute("COMMIT")
                return result
            except BaseException:
                db.execute("ROLLBACK")
                raise

        return self._read_v2(authority, reader)

    def _get_natural_dispatch_text_segment_locked(
            self, namespace, request, *, now_utc: float):
        """Use the shared current proof before exposing the committed body."""
        from .runtime.natural_dispatch_current_read_v2 import (
            NaturalDispatchCurrentHold,
            read_current_natural_dispatch_segment_in_transaction_v2,
        )

        try:
            return read_current_natural_dispatch_segment_in_transaction_v2(
                self.__store._db, namespace, request, now_utc=now_utc)
        except NaturalDispatchCurrentHold as exc:
            raise UnavailableGuard(str(exc)) from exc

    def _get_dispatch_text_segment_locked(self, namespace, request):
        from .domains.d09 import ClaimKind, ClaimUse, D09ExpressionProvider
        from .runtime.dispatch_candidate import GraphDispatchTextSegmentV1

        db = self.__store._db
        row = db.execute(
            "SELECT admission_ref FROM graph_dispatch_admissions "
            "WHERE bot=? AND persona=? AND operation_id=? AND effect_id=?",
            namespace.as_tuple + (request.operation_id, request.effect_id),
        ).fetchone() if db.execute(
            "SELECT 1 FROM sqlite_master WHERE type='table' "
            "AND name='graph_dispatch_admissions'"
        ).fetchone() else None
        if row is None:
            return None
        receipt = load_admission(db, namespace, row[0])
        candidate = self._get_dispatch_candidate_evidence_locked(
            namespace, request.operation_id)
        if receipt is None or candidate is None:
            raise UnavailableGuard("dispatch admission or candidate is absent")
        admission = receipt.admission
        evidence = candidate.evidence
        if (evidence.status != "source_qualified"
                or admission.request_digest != canonical_digest(request)
                or admission.candidate_digest != evidence.digest
                or admission.batch_digest != evidence.batch_digest
                or admission.segment_index != request.segment_index
                or admission.payload_digest != request.payload_digest
                or admission.dispatch_generation != request.dispatch_generation
                or admission.graph_incarnation != (
                    candidate.graph_incarnation or "nonproduction-graphstore")
                or receipt.graph_epoch != candidate.graph_epoch
                or request.payload_ref != dispatch_segment_payload_ref(
                    evidence.batch_ref, request.segment_index)):
            raise UnavailableGuard("dispatch text admission differs from graph candidate")
        batch_ref, batch_revision = candidate.write_versions[3]
        batch_row = db.execute(
            "SELECT value,valid FROM graph_history WHERE token=? AND revision=? "
            "AND event_bot=? AND event_persona=? AND event_session=? AND event_id=?",
            (batch_ref, batch_revision) + namespace.as_tuple + (
                request.activity_id, request.operation_id),
        ).fetchone()
        if batch_row is None or batch_row[1] != 1:
            raise UnavailableGuard("committed D09 batch is unavailable")
        batch = json.loads(batch_row[0])
        next(spec for spec in D09ExpressionProvider.register_types()
             if spec.name == "d09.verified_segment_batch.v1").validator(batch)
        index = request.segment_index
        if (type(index) is not int or not 0 <= index < len(batch["segments"])
                or batch_ref != evidence.batch_ref
                or batch["batch_digest"] != evidence.batch_digest
                or batch["scene_ref"] != admission.scene_ref
                or tuple(batch["audiences"]) != admission.audience
                or len(admission.audience) != 1):
            raise UnavailableGuard("D09 batch scope differs from dispatch admission")
        segment = batch["segments"][index]
        if (segment["effect_id"] != request.effect_id
                or segment["payload_digest"] != request.payload_digest
                or segment["segment_authorization_ref"] != request.segment_authorization_ref
                or batch["grant_manifest_digest"] != request.segment_manifest_digest
                or len(batch["segments"]) != request.segment_count):
            raise UnavailableGuard("D09 text segment differs from dispatch command")
        # Ingress freezes platform_ref=[platform_id,platform_name,self_id] and
        # conversation_ref=[UMO,conversation_id]. Rebuild its bot and scene.
        try:
            account = json.loads(admission.account_ref)
            route = json.loads(admission.audience[0])
        except (TypeError, ValueError) as exc:
            raise UnavailableGuard("AstrBot route encoding is unavailable") from exc
        from .host.identity import astrbot_namespace

        if (type(account) is not list or len(account) != 3
                or type(route) is not list or len(route) != 2
                or any(type(item) is not str or not item for item in (*account, *route))
                or admission.destination_ref != admission.audience[0]
                or json.dumps(account, ensure_ascii=True, separators=(",", ":"))
                != admission.account_ref
                or json.dumps(route, ensure_ascii=True, separators=(",", ":")) != admission.audience[0]):
            raise UnavailableGuard("dispatch route is not bound to AstrBot ingress")
        if astrbot_namespace(account[0], account[2], "route-check").bot_id != namespace.bot_id:
            raise UnavailableGuard("dispatch account differs from AstrBot graph namespace")
        from .runtime.first_ingress_v2 import scene_ref_for_conversation

        if scene_ref_for_conversation(
                namespace, admission.account_ref, admission.destination_ref,
        ) != admission.scene_ref:
            raise UnavailableGuard("dispatch scene differs from AstrBot ingress")
        uses = tuple(ClaimUse(item["claim_ref"], item["start"], item["end"],
                              ClaimKind(item["asserted_as"]))
                     for item in segment["claim_uses"])
        return GraphDispatchTextSegmentV1(
            segment["body"], tuple(segment["media_refs"]), uses,
            account[0], account[1], account[2], route[0], route[1],
            admission.scene_ref,
        )

    @staticmethod
    def _dispatch_clock_upper(reading) -> float:
        from .host.v2_fence_port import VerifiedIngressClockV2
        from .runtime.first_ingress_v2 import trusted_upper

        if type(reading) is not VerifiedIngressClockV2:
            raise UnavailableGuard("paired dispatch admission clock is unqualified")
        try:
            return trusted_upper(reading)
        except ValueError as exc:
            raise UnavailableGuard("paired dispatch admission clock is unqualified") from exc

    def _issue_dispatch_admission(self, db, bundle, snapshot, candidate,
                                  action, schema, grant, batch, *,
                                  graph_receipt, v2_write, now_utc, projection,
                                  clock_reading=None, dispatch_scope=None,
                                  dispatch_owner_guard=None,
                                  dispatch_current_effect=None,
                                  dispatch_effect_snapshot=None,
                                  provisional_check_candidate=None,
                                  installed_final_check_reissuer=None):
        """Fail closed unless a host issuer supplies and proves every current fact.

        This is called from the graph receipt hook, after D11's reservation,
        while the ordinary graph write transaction and fence remain active.
        """
        issuer = self.__dispatch_admission_issuer
        if issuer is None:
            return None
        if (isinstance(self.__store, ProductionGraphStore)
                and provisional_check_candidate is None):
            raise UnavailableGuard(
                "production dispatch admission requires final check reissue; HOLD")
        if (candidate.status != "source_qualified"
                or (isinstance(self.__store, ProductionGraphStore)
                    and v2_write is None)):
            raise UnavailableGuard("dispatch admission requires current D06 proof and write fence")
        if projection is None:
            raise UnavailableGuard("dispatch admission lacks complete D03/D05 graph projection")
        for method in ("issue_dispatch_admission", "verify_required_check",
                       "verify_command_provenance", "verify_journal_constraints",
                       "verify_domain_context"):
            if not callable(getattr(issuer, method, None)):
                raise UnavailableGuard("trusted dispatch admission issuer is incomplete")
        envelope = bundle.envelope
        identity = envelope.identity
        graph_incarnation = (
            v2_write[0].requirements.graph_incarnation
            if v2_write is not None else "nonproduction-graphstore"
        )
        if now_utc is None:
            raise UnavailableGuard("trusted dispatch admission clock is unavailable")
        if type(now_utc) not in (int, float) or not math.isfinite(now_utc):
            raise UnavailableGuard("trusted dispatch admission clock is invalid")
        now = float(now_utc)
        trusted_context = None
        if isinstance(self.__store, ProductionGraphStore):
            from .authority_service.v2_contract import (
                AuthorityCurrentEffectSnapshotV2, FencePermitV2,
            )
            from .authority_service.v2_execution_bridge import CurrentEffectReadV2
            from .authority_service.v2_owner_contract import OwnerAuthorizationGuardV1
            from .host.authority_profile import AdminIngressClockPolicy
            from .host.v2_fence_port import VerifiedIngressClockV2
            from .runtime_contracts import FenceScope
            from .runtime.installed_dispatch_admission_issuer import (
                TrustedDispatchAdmissionContextV1,
            )

            if (type(dispatch_scope) is not FenceScope
                    or type(dispatch_scope.permit) is not FencePermitV2
                    or dispatch_scope.permit.operation != "write"
                    or type(clock_reading) is not VerifiedIngressClockV2
                    or type(self.__dispatch_clock_policy) is not AdminIngressClockPolicy
                    or type(dispatch_owner_guard) is not OwnerAuthorizationGuardV1
                    or type(dispatch_current_effect) is not CurrentEffectReadV2
                    or type(dispatch_effect_snapshot)
                    is not AuthorityCurrentEffectSnapshotV2
                    or dispatch_scope.permit.pinned_anchor != dispatch_scope.pinned_anchor
                    or dispatch_scope.graph_revision != v2_write[0].graph_revision
                    or dispatch_scope.graph_epoch != v2_write[1]):
                raise UnavailableGuard("trusted dispatch admission fence evidence unavailable; HOLD")
            trusted_context = TrustedDispatchAdmissionContextV1(
                dispatch_scope, clock_reading, self.__dispatch_clock_policy,
                projection, graph_receipt, dispatch_owner_guard,
                dispatch_current_effect, dispatch_effect_snapshot)
        issuer_options = ({"trusted_context": trusted_context}
                          if trusted_context is not None else {})
        final_reissue = None
        if provisional_check_candidate is not None:
            from .runtime.dispatch_check_reissue import (
                DispatchCheckReissueHold, ProvisionalCheckCandidateV1,
                reissue_and_require_identical_checks,
            )

            reissuer = installed_final_check_reissuer
            if (type(provisional_check_candidate) is not ProvisionalCheckCandidateV1
                    or not callable(reissuer)
                    or type(dispatch_scope) is not FenceScope):
                raise UnavailableGuard(
                    "installed final dispatch check reissuer unavailable; HOLD")
            try:
                final_reissue = reissue_and_require_identical_checks(
                    db, provisional_check_candidate, graph_receipt,
                    dispatch_scope, now_utc=now, installed_reissuer=reissuer)
            except DispatchCheckReissueHold as exc:
                raise UnavailableGuard(
                    "final dispatch check closure differs; HOLD") from exc
        if grant.route_binding_digest is not None:
            from .runtime.dispatch_check_reissue import PostC02FinalReissueV2

            if (type(final_reissue) is not PostC02FinalReissueV2
                    or final_reissue.grant != grant
                    or final_reissue.action.intent != action
                    or final_reissue.candidate != provisional_check_candidate):
                raise UnavailableGuard(
                    "route-bound dispatch lacks installed final reissue; HOLD")
        issuer_snapshot = snapshot
        if final_reissue is not None:
            if trusted_context is None:
                raise UnavailableGuard(
                    "final dispatch admission trusted context absent; HOLD")
            # The guard snapshot is pinned to E, before graph_commit writes.
            # K03's final checks were reissued from the actual sealed E+1
            # rows, so admission must inspect that same current SQL head.
            issuer_snapshot, issuer_query = (
                self._dispatch_full_graph_snapshot_locked(
                    bundle.envelope.authority.namespace))
            if (issuer_query.revision != graph_receipt.epoch.revision
                    or issuer_snapshot.epochs != (graph_receipt.epoch,)
                    or final_reissue.candidate.graph_epoch
                       != issuer_query.revision):
                raise UnavailableGuard(
                    "final dispatch admission graph head differs; HOLD")
            from .runtime.dispatch_current_projection import (
                read_current_dispatch_projection,
            )

            try:
                issuer_projection = read_current_dispatch_projection(
                    db, bundle.envelope.authority.namespace,
                    issuer_snapshot, issuer_query)
            except ValueError as exc:
                raise UnavailableGuard(
                    "final dispatch admission social projection differs; HOLD"
                ) from exc
            if issuer_projection.coverage != "full":
                raise UnavailableGuard(
                    "final dispatch admission social projection incomplete; HOLD")
            # The scope/permit and Authority observations are pinned to the
            # ordinary write attempt. Only graph-derived rows move to E+1.
            issuer_options["trusted_context"] = replace(
                trusted_context, projection=issuer_projection)
        issue_options = dict(issuer_options)
        if final_reissue is not None:
            issue_options["post_c02_final_reissue"] = final_reissue
        issued = issuer.issue_dispatch_admission(
            bundle, issuer_snapshot, candidate, db,
            graph_incarnation=graph_incarnation,
            now_utc=now, **issue_options,
        )
        if (type(issued) is not tuple or len(issued) != 2
                or type(issued[1]) is not DispatchAdmissionV1):
            raise UnavailableGuard("trusted issuer did not produce typed dispatch admission")
        request, admission = issued
        if provisional_check_candidate is not None:
            if tuple(admission.check_receipts) != provisional_check_candidate.checks:
                raise UnavailableGuard(
                    "final dispatch admission checks differ from reissue; HOLD")
        from .domains.d03 import RoleBinding

        current_bindings = []
        for atom in projection.role_bindings:
            value = atom.value
            binding = RoleBinding(**{
                **value, "norm_refs": tuple(value["norm_refs"]),
                "source_refs": tuple(value["source_refs"]),
            })
            if (atom.key.name == binding.role_binding_id
                    and atom.revision == binding.binding_version
                    and binding.status == "active"
                    and binding.scene_ref == batch["scene_ref"]
                    and binding.effective_from <= now
                    and (binding.effective_until is None or now <= binding.effective_until)):
                current_bindings.append(binding)
        if not any(binding.role_binding_id == admission.binding_ref
                   for binding in current_bindings):
            raise UnavailableGuard("dispatch admission lacks a current D03 scene binding")
        from .domains.d05 import BoundaryRule, RelationshipProvider

        current_rules = tuple(BoundaryRule(**{
            **atom.value,
            "source_refs": tuple(atom.value["source_refs"]),
            "communicated_refs": tuple(atom.value["communicated_refs"]),
            "acknowledged_refs": tuple(atom.value["acknowledged_refs"]),
            "exception_refs": tuple(atom.value["exception_refs"]),
        }) for atom in projection.boundary_rules)
        if any(atom.key.name != rule.rule_id
               for atom, rule in zip(projection.boundary_rules, current_rules)):
            raise UnavailableGuard("current D05 boundary identity differs")
        # The transaction-checked projection proves read coverage. This only
        # vetoes explicit deny/conflict; the issuer still owns full D05 approval.
        for audience in envelope.authority.audience:
            boundary = RelationshipProvider().provide_required_check(
                subject_persona_ref=f"persona:{envelope.authority.namespace.persona_id}",
                target_entity_ref=action.target_ref,
                action_kind=action.action_kind,
                audience_scope=audience,
                scene_ref=batch["scene_ref"], at_time=now,
                rules=current_rules, coverage_complete=True,
            )
            if boundary.result in {"deny", "conflict"}:
                raise UnavailableGuard("current D05 boundary vetoed dispatch admission")
        if isinstance(self.__store, ProductionGraphStore):
            policy = self.__dispatch_clock_policy
            if (clock_reading is None or policy is None
                    or admission.clock_policy_ref != policy.source_id
                    or admission.clock_policy_digest != canonical_digest(asdict(policy))):
                raise UnavailableGuard("dispatch admission clock evidence differs")
        from .dispatch_runtime import DispatchRequest

        if type(request) is not DispatchRequest:
            raise UnavailableGuard("trusted issuer did not produce typed dispatch command")
        if request.payload_ref != dispatch_segment_payload_ref(
                candidate.batch_ref, request.segment_index):
            raise UnavailableGuard("dispatch payload reference differs from D09 graph segment")
        preflight = preflight_dispatch_admission(
            schema, action, batch, request, admission.check_receipts,
            now_utc=now, trusted_check_verifier=lambda spec, receipt: (
                issuer.verify_required_check(
                    spec, receipt, issuer_snapshot, db,
                    **issuer_options) is True),
        )
        if set(preflight.missing) != {
            "d09.source_qualification", "dispatch.command_provenance",
            "graph.current_admission",
        }:
            raise UnavailableGuard("dispatch admission candidate or checks are incomplete")
        check_receipts_against_specs(admission, schema.required_checks, now)
        admission.require_current(now)
        if (issuer.verify_domain_context(
                    admission, issuer_snapshot, db,
                    **issuer_options) is not True
                or issuer.verify_command_provenance(
                    request, admission, db, **issuer_options) is not True
                or issuer.verify_journal_constraints(
                    request, admission, **issuer_options) is not True):
            raise UnavailableGuard("dispatch domain, command, or journal is unverified")
        reads = tuple((item.key.token, item.revision)
                      for item in issuer_snapshot.versions)
        parts = (action.identity.activity_id, action.identity.effect_id,
                 action.identity.attempt_id, action.identity.operation_id)
        segment = batch["segments"][request.segment_index]
        if (
            admission.namespace != "/".join(envelope.authority.namespace.as_tuple)
            or admission.graph_incarnation != graph_incarnation
            or (admission.activity_id, admission.effect_id,
                admission.attempt_id, admission.operation_id) != parts
            or admission.dispatch_generation != request.dispatch_generation
            or request.activation_generation != envelope.authority.activation_generation
            or admission.dispatch_generation != envelope.authority.activation_generation
            or admission.candidate_digest != candidate.digest
            or admission.request_digest != canonical_digest(request)
            or admission.action_intent_digest != candidate.action_digest
            or admission.action_schema_digest != candidate.schema_digest
            or admission.required_checks_digest != canonical_digest(schema.required_checks)
            or admission.grant_digest != candidate.grant_digest
            or admission.batch_digest != candidate.batch_digest
            or admission.segment_index != request.segment_index
            or admission.payload_digest != segment["payload_digest"]
            or admission.scene_ref != batch["scene_ref"]
            or admission.object_ref != action.target_ref
            or admission.action_ref != action.action_id
            or admission.purpose != action.purpose
            or admission.audience != envelope.authority.audience
            or admission.graph_reads != reads
            or admission.query_epoch != issuer_snapshot.epochs[0].revision
            or (admission.access_epoch, admission.delete_epoch) != (
                envelope.version_guard.access_epoch,
                envelope.version_guard.delete_epoch)
            or admission.budget_parent_lease_ref != envelope.parent_budget_lease_ref
            or admission.budget_lease_ref != envelope.parent_budget_lease_ref
            or admission.budget_reservation_operation_id != identity.operation_id
            or admission.budget_reservation_digest != budget_operation_digest(
                envelope, admission.budget_lease_ref, dict(admission.budget_ceiling))
            or not any(
                item.parent_budget_ref == admission.budget_lease_ref
                and item.upper_bound is not None
                for item in request.footprint.budgets
            )
        ):
            raise UnavailableGuard("dispatch admission differs from current graph candidate")
        if (admission.action_intent_schema_version != "d08.action_intent.v1"
                or admission.action_schema_version != "d08.action_schema.v1"
                or admission.required_checks_schema_version != "d08.required_check_spec.v1"):
            raise UnavailableGuard("dispatch contract schema version differs")
        lease = get_budget_lease(db, admission.budget_lease_ref)
        reservation = db.execute(
            "SELECT digest,ceiling_json,state FROM runtime_budget_reservations "
            "WHERE lease_id=? AND operation_id=?",
            (admission.budget_lease_ref, admission.budget_reservation_operation_id),
        ).fetchone()
        if (lease.state != "active" or lease.version != admission.budget_version
                or lease.currency != admission.budget_currency
                or (lease.bot_id, lease.persona_id) != envelope.authority.namespace.as_tuple
                or reservation is None
                or reservation[0] != admission.budget_reservation_digest
                or json.loads(reservation[1]) != dict(admission.budget_ceiling)
                or reservation[2] != "reserved"):
            raise UnavailableGuard("dispatch budget reservation changed before admission")
        if request.proactive_contact and admission.contact_reservation_ref is None:
            raise UnavailableGuard("proactive contact has no durable occupation")
        graph_revision = (v2_write[0].graph_revision + 1 if v2_write is not None
                          else graph_receipt.epoch.revision)
        receipt = DispatchAdmissionReceiptV1(
            admission, graph_revision, graph_receipt.epoch.revision,
            canonical_digest({
                "admission_digest": admission.digest,
                "graph_revision": graph_revision,
                "graph_epoch": graph_receipt.epoch.revision,
            }),
        )
        insert_admission(db, receipt, request)
        return receipt

    def commit_d03_message_arrival_v2(
            self, bootstrap: object, namespace: NamespaceId, source_ref: str,
            installation_policy, arrival_policy, clock_policy) -> CommitReceipt:
        """Adopt one committed ingress as a D03 fact with an installed price.

        The source ID selects an existing trusted ingress receipt. Identity,
        content, scene and source/access guards are rebuilt from this store;
        no caller candidate or quote is accepted. A committed receipt reports
        only the graph fact and a D11 reservation, never settled cost.
        """
        from .authority_service.v2_contract import FencePermitV2, from_wire
        from .domains.d03.message_arrival import (
            build_message_arrival_candidate, build_message_arrival_proposal,
        )
        from .host.authority_profile import (
            AdminD03ArrivalPolicy, AdminIngressClockPolicy,
        )
        from .host.ingress import HostIngressEnvelope, SourceLineage
        from .installation_policy import AdminInstallationPolicy
        from .runtime.first_ingress_v2 import (
            scene_ref_for_conversation, trusted_upper,
        )
        from .runtime.ingress_observation import read_committed_ingress_identity
        from .runtime.issuers import D03_ARRIVAL_WORK_KIND, d03_arrival_quote_id
        from .runtime_contracts import (
            CommandEnvelope, OperationIdentity, QueryEpoch, RUNTIME_SCHEMA,
            VersionedRef,
        )

        self._admin(bootstrap)
        if (type(namespace) is not NamespaceId
                or type(installation_policy) is not AdminInstallationPolicy
                or type(arrival_policy) is not AdminD03ArrivalPolicy
                or type(clock_policy) is not AdminIngressClockPolicy):
            raise UnavailableGuard("installed D03 arrival policies are required; HOLD")
        if (namespace != installation_policy.namespace
                or type(source_ref) is not str or len(source_ref) != 64
                or any(ch not in "0123456789abcdef" for ch in source_ref)
                or not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or self.__d02_issuer is None or self.__d11_issuer is None):
            raise UnavailableGuard("D03 arrival v2 identity or authorities unavailable")
        policy = installation_policy
        grant = policy.root_grant
        if (D03_ARRIVAL_WORK_KIND not in grant.allowed_work_kinds
                or any(amount > grant.max_ceiling.get(name, 0)
                       for name, amount in arrival_policy.quote_ceiling.items())):
            raise UnavailableGuard("installed grant does not price D03 arrival")
        operation_id = "d03-arrival-" + canonical_digest({
            "namespace": list(namespace.as_tuple), "source_ref": source_ref,
        })[:40]
        activity_id = "d03-activity-" + canonical_digest({
            "namespace": list(namespace.as_tuple), "source_ref": source_ref,
            "kind": D03_ARRIVAL_WORK_KIND,
        })[:40]
        quote_id = d03_arrival_quote_id(namespace, operation_id)
        policy_digest = canonical_digest(arrival_policy.digest_payload())
        store = self.__store
        port = self.__content_fence_v2
        with store._lock:
            provision = self._provision_row(store._db, namespace)
            if provision is None:
                raise UnavailableGuard("D03 arrival namespace is not provisioned")
            genesis = self._decode_provision_receipt(provision)
            signed_grant, signature = self.__d11_issuer.signed_budget_grant_at_version(
                store._db, grant.lease_id, grant.version)
            if (signed_grant != grant or signature != genesis.root_grant_signature
                    or genesis.root_grant_id != grant.grant_id
                    or genesis.root_lease_id != grant.lease_id
                    or genesis.installation_id != policy.installation_id
                    or genesis.manifest_digest != policy.manifest_digest):
                raise UnavailableGuard("D03 arrival installed root grant differs")
            metadata, epoch = self._v2_graph_stamp(namespace)
            prior_authority = AuthorityContext(
                "host", "d11", "audit", namespace, ("persona", "event"),
                "context", (), grant.policy_ref,
                metadata.requirements.activation_generation)
            prior = self._get_operation_fenced(prior_authority, operation_id, v2=True)
            binding = store._db.execute(
                "SELECT source_ref,quote_id,policy_digest,bundle_digest "
                "FROM graph_d03_arrival_issuance_v2 WHERE bot=? AND persona=? "
                "AND operation_id=?", namespace.as_tuple + (operation_id,),
            ).fetchone() if store._db.execute(
                "SELECT 1 FROM sqlite_master WHERE type='table' "
                "AND name='graph_d03_arrival_issuance_v2'",
            ).fetchone() else None
            saved = store._db.execute(
                "SELECT digest,permit_json,pre_graph_revision,pre_graph_epoch,"
                "post_graph_revision,post_graph_epoch,finish_request_id,"
                "finish_request_digest FROM graph_bundle_fences_v2 WHERE bot=? "
                "AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone()
        target = metadata.requirements
        if (target.namespace != namespace
                or target.authority_id != policy.expected_authority_id
                or target.authority_namespace != policy.authority_namespace
                or target.activation_generation != genesis.generation):
            raise UnavailableGuard("D03 arrival v2 recovery identity differs")
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("D03 arrival Authority anchor differs")
        if prior is not None:
            if (binding != (source_ref, quote_id, policy_digest,
                            prior.operation_digest)
                    or saved is None or saved[0] != prior.operation_digest
                    or saved[4] != saved[2] + 1
                    or saved[5] != prior.invalidated_epochs[0].revision):
                raise UnavailableGuard("D03 arrival replay receipt differs")
            attempt_id = domain_bundle_write_attempt_id_v1(
                namespace, operation_id, prior.operation_digest)
            permit = from_wire(json.loads(saved[1]))
            if (type(permit) is not FencePermitV2
                    or permit.operation_id != attempt_id
                    or permit.pinned_anchor != anchor
                    or permit.holder != self.__holder):
                raise UnavailableGuard("D03 arrival replay permit differs")
            with store._lock:
                quote = self.__d02_issuer._load_quote(store._db, quote_id, 1)
                policy_ref = quote.snapshot_ref.split(":")
                if len(policy_ref) != 3 or policy_ref[0] != "d03snap":
                    raise UnavailableGuard("D03 arrival replay policy binding differs")
                signed_policy = self.__d02_issuer._load_d03_arrival_policy(
                    store._db, policy_ref[1])
                original, _ = self.__d11_issuer.signed_budget_grant_at_version(
                    store._db, grant.lease_id, grant.version)
                budget = get_budget_lease(store._db, grant.lease_id)
                if (original != grant or quote.operation_id != operation_id
                        or quote.activity_id != activity_id
                        or quote.parent_budget_lease_ref != grant.lease_id
                        or quote.work_kind != D03_ARRIVAL_WORK_KIND
                        or dict(quote.ceiling) != dict(arrival_policy.quote_ceiling)
                        or signed_policy.installation_id != policy.installation_id
                        or signed_policy.grant_id != grant.grant_id
                        or signed_policy.grant_version != grant.version
                        or signed_policy.lease_id != grant.lease_id
                        or signed_policy.provider_policy_ref != grant.policy_ref
                        or signed_policy.snapshot_ref != arrival_policy.snapshot_ref
                        or signed_policy.resource_ref != arrival_policy.resource_ref
                        or signed_policy.deadline_after_seconds
                        != arrival_policy.deadline_after_seconds
                        or dict(signed_policy.quote_ceiling)
                        != dict(arrival_policy.quote_ceiling)
                        or budget.state != "active"
                        or (budget.bot_id, budget.persona_id) != namespace.as_tuple):
                    raise UnavailableGuard("D03 arrival replay quote or lease differs")
            expected_finish = "sha256:" + canonical_digest({
                "operation_id": attempt_id, "permit_token": permit.token,
                "action": "finish_domain_bundle",
                "business_operation_id": operation_id,
                "bundle_digest": prior.operation_digest,
            })
            if saved[6:] != ("finish:" + attempt_id, expected_finish):
                raise UnavailableGuard("D03 arrival replay finish receipt differs")
            observed, state = port.get_fence_operation(
                namespace=namespace,
                authority_namespace=target.authority_namespace,
                operation_id=attempt_id)
            if observed != permit or state not in {"active", "finished"}:
                raise UnavailableGuard("D03 arrival replay Authority fence differs")
            if state == "active":
                if (metadata.graph_revision, epoch.revision) != saved[4:6]:
                    raise UnavailableGuard("D03 arrival replay graph stamp differs")
                scope = FenceScope(
                    namespace, target.authority_namespace,
                    target.activation_generation, "write", attempt_id,
                    permit, anchor,
                    NamespaceEpoch(*namespace.as_tuple, saved[3]), saved[2])
                if port.validate_fence(scope) != permit:
                    raise UnavailableGuard("D03 arrival replay permit changed")
                port.finish_fence(scope, request_id=saved[6],
                                  request_digest=saved[7])
            elif (metadata.graph_revision < saved[4]
                  or epoch.revision < saved[5]):
                raise UnavailableGuard("D03 arrival finished graph stamp regressed")
            return replace(prior, status="duplicate")
        if binding is not None or saved is not None:
            raise UnavailableGuard("D03 arrival lacks a complete replay receipt")

        try:
            reading = port.read_ingress_clock(clock_policy)
            now_utc = trusted_upper(reading)
        except Exception as exc:
            raise UnavailableGuard("paired D03 arrival clock unavailable; HOLD") from exc
        deadline = min(
            math.nextafter(math.fsum((now_utc, arrival_policy.deadline_after_seconds)),
                           -math.inf), grant.valid_until_utc)
        if deadline <= now_utc:
            raise UnavailableGuard("D03 arrival deadline is unavailable")
        monotonic_deadline = reading.monotonic_after_seconds + (
            deadline - reading.utc_upper_bound_seconds)
        if not math.isfinite(monotonic_deadline):
            raise UnavailableGuard("D03 arrival monotonic deadline is invalid")
        with store._lock:
            if self._v2_graph_stamp(namespace) != (metadata, epoch):
                raise StaleRead("D03 arrival graph stamp changed")
            db = store._db
            receipt = read_committed_ingress_identity(db, namespace, source_ref)
            if receipt is None:
                raise UnavailableGuard("D03 arrival lacks committed host ingress")
            identity = json.loads(receipt.identity_json)
            source_atom_key = source_key(*namespace.as_tuple, source_ref)
            access_atom_key = access_key(*namespace.as_tuple, source_ref)
            source_row = db.execute(
                "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                (source_atom_key.token,),
            ).fetchone()
            access_row = db.execute(
                "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                (access_atom_key.token,),
            ).fetchone()
            if (source_row is None or access_row is None
                    or not source_row[2] or not access_row[2]):
                raise UnavailableGuard("D03 arrival current source or access is unavailable")
            source = SourceRecord.from_dict(json.loads(source_row[1]))
            access = json.loads(access_row[1])
            ingress = HostIngressEnvelope(
                namespace, identity["platform_ref"], identity["conversation_ref"],
                identity["sender_ref"], identity["message_id"], source.text,
                source.occurred_at, source.recorded_at, identity["visibility"],
                SourceLineage(**identity["lineage"]),
            )
            scene = SimpleNamespace(
                namespace=namespace, platform_ref=ingress.platform_ref,
                conversation_ref=ingress.conversation_ref,
                visibility=ingress.visibility,
                scene_ref=scene_ref_for_conversation(
                    namespace, ingress.platform_ref, ingress.conversation_ref),
            )
            qualification = SourceQualification(
                (source_atom_key.token,), "reported", source.occurred_at,
                source.recorded_at, "external_report", "qualified", 0.5,
                "not_applicable",
            )
            candidate = build_message_arrival_candidate(
                ingress, scene, source, access, qualification,
                source_version=GraphVersion(source_atom_key, source_row[0]),
                access_version=GraphVersion(access_atom_key, access_row[0]),
            )
            sender_row = db.execute(
                "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                (candidate.sender_key.token,),
            ).fetchone()
            binding_row = db.execute(
                "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                (candidate.account_binding_key.token,),
            ).fetchone()
            event_row = db.execute(
                "SELECT 1 FROM graph_atoms WHERE token=?",
                (candidate.event_key.token,),
            ).fetchone()
            if event_row is not None:
                raise UnavailableGuard("D03 arrival event exists without this operation")
            sender_atom = (GraphAtom(candidate.sender_key, sender_row[0],
                                     json.loads(sender_row[1]), bool(sender_row[2]))
                           if sender_row else None)
            binding_atom = (
                GraphAtom(candidate.account_binding_key, binding_row[0],
                          json.loads(binding_row[1]), bool(binding_row[2]))
                if binding_row else None
            )
            prior_binding_event_version = None
            if binding_atom is not None:
                try:
                    prior_binding_event_key = AtomKey.from_token(
                        binding_atom.value["verification_ref"])
                except (KeyError, TypeError, ValueError) as exc:
                    raise UnavailableGuard(
                        "D03 existing account binding event is invalid; HOLD") from exc
                if (prior_binding_event_key.type_name != "d03.world_event"
                        or prior_binding_event_key.owner.kind != "event"
                        or (prior_binding_event_key.owner.bot,
                            prior_binding_event_key.owner.persona) != namespace.as_tuple):
                    raise UnavailableGuard(
                        "D03 existing account binding event crosses scope; HOLD")
                prior_event_row = db.execute(
                    "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                    (prior_binding_event_key.token,),
                ).fetchone()
                if (prior_event_row is None or not prior_event_row[2]
                        or prior_event_row[0] < 1):
                    raise UnavailableGuard(
                        "D03 existing account binding event is unavailable; HOLD")
                prior_binding_event_version = GraphVersion(
                    prior_binding_event_key, prior_event_row[0])
            guard_versions = dict(db.execute(
                "SELECT kind,version FROM graph_guard_versions WHERE bot=? "
                "AND persona=? AND ref='current'", namespace.as_tuple,
            ).fetchall())
            authority_epochs = db.execute(
                "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                "WHERE bot=? AND persona=?", namespace.as_tuple,
            ).fetchone() or (0, 0)
        lease, capability = self.grant(
            bootstrap, actor="host", issuer_domain="d11", namespace=namespace,
            domains=("d03",), activation_generation=target.activation_generation,
            operation_id=operation_id)
        authority = AuthorityContext(
            "host", "d11", capability, namespace, ("persona", "event"),
            "context", (ingress.conversation_ref,), grant.policy_ref,
            target.activation_generation)
        envelope = CommandEnvelope(
            RUNTIME_SCHEMA,
            OperationIdentity(
                activity_id, None, "arrival-attempt", "arrival", operation_id,
                canonical_digest({"input_refs": [source_atom_key.token]})),
            authority,
            VersionGuard(
                (GraphVersion(source_atom_key, source_row[0]),
                 GraphVersion(access_atom_key, access_row[0]),
                 GraphVersion(candidate.sender_key,
                              sender_row[0] if sender_row else 0),
                 GraphVersion(candidate.account_binding_key,
                              binding_row[0] if binding_row else 0),
                 GraphVersion(candidate.event_key, 0)) + (
                     (prior_binding_event_version,)
                     if prior_binding_event_version is not None else ()),
                (QueryEpoch(namespace, "all", epoch.revision),),
                *authority_epochs, store._registry.catalogue_hash,
                guard_versions["scheme"], guard_versions["operator"],
                guard_versions["policy"], (), (),
                (VersionedRef(quote_id, 1),)),
            qualification, (source_atom_key.token,), grant.lease_id,
            deadline, monotonic_deadline, "character-v1", (ingress.message_id,),
        )
        proposal = build_message_arrival_proposal(
            envelope, candidate, sender_atom=sender_atom,
            binding_atom=binding_atom)
        bundle = DomainBundle(envelope, (proposal,), (), (), (), (), (), (), ())
        return self._commit_domain_bundle_v2(
            bundle, lease, arrival_issuance=(
                arrival_policy, policy.installation_id, now_utc, source_ref,
                policy_digest))

    def _recover_d03_self_projection_before_read(
        self, namespace, original_operation_id, installation_policy,
        admin_policy,
    ) -> CommitReceipt | None:
        """Resolve the original stage fence before opening another content read."""
        from .authority_service.v2_contract import from_wire

        store, port = self.__store, self.__content_fence_v2
        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
            identity = store._db.execute(
                "SELECT source_ref FROM graph_first_ingress_identity_v1 WHERE bot=? "
                "AND persona=? AND operation_id=?",
                namespace.as_tuple + (original_operation_id,),
            ).fetchone()
            if identity is None:
                raise UnavailableGuard("D03 original ingress is unavailable; HOLD")
            source_ref = source_key(*namespace.as_tuple, identity[0]).token
            has_index = store._db.execute(
                "SELECT 1 FROM sqlite_master WHERE type='table' "
                "AND name='graph_d03_self_projection_intents_v1'",
            ).fetchone() is not None
            indexed = (store._db.execute(
                "SELECT operation_id,bundle_digest FROM "
                "graph_d03_self_projection_intents_v1 WHERE bot=? AND persona=? "
                "AND source_ref=? AND original_operation_id=?",
                namespace.as_tuple + (source_ref, original_operation_id),
            ).fetchone() if has_index else None)
            has_issued = store._db.execute(
                "SELECT 1 FROM sqlite_master WHERE type='table' "
                "AND name='graph_d03_self_projection_issuance_v1'",
            ).fetchone() is not None
            issued = (store._db.execute(
                "SELECT operation_id,certification_ref,quote_id,bundle_digest "
                "FROM graph_d03_self_projection_issuance_v1 WHERE bot=? "
                "AND persona=? AND source_ref=?",
                namespace.as_tuple + (source_ref,),
            ).fetchall() if has_issued else [])
            if len(issued) > 1:
                raise UnavailableGuard("D03 self projection has multiple original receipts")
            if not issued and indexed is None:
                return None
            operation_id = issued[0][0] if issued else indexed[0]
            intent = store._db.execute(
                "SELECT digest,fence_attempt_id,requirements_json,anchor_json,"
                "graph_revision,graph_epoch FROM graph_bundle_intents_v2 "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone()
            if intent is None or (indexed is not None
                                  and indexed != (operation_id, intent[0])):
                raise UnavailableGuard("D03 self projection durable intent differs")
            saved = store._db.execute(
                "SELECT digest,permit_json,pre_graph_revision,pre_graph_epoch,"
                "post_graph_revision,post_graph_epoch,finish_request_id,"
                "finish_request_digest FROM graph_bundle_fences_v2 "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone()
            prior = self._get_operation_fenced(
                AuthorityContext("host", "d11", "recovery", namespace,
                                 ("persona", "event"), "context", (),
                                 installation_policy.root_grant.policy_ref,
                                 metadata.requirements.activation_generation),
                operation_id, v2=True)
            if issued:
                quote = self.__d02_issuer._load_quote(store._db, issued[0][2], 1)
                if (prior is None or saved is None
                        or issued[0][3] != prior.operation_digest
                        or saved[0] != prior.operation_digest
                        or quote.operation_id != operation_id
                        or quote.work_kind != "d03.self_identity_projection"
                        or dict(quote.ceiling) != dict(admin_policy.quote_ceiling)
                        or not any(item.key.type_name == "d03.self_perspective.v1"
                                   for item in prior.write_versions)):
                    raise UnavailableGuard("D03 self projection receipt differs")
            elif prior is not None or saved is not None:
                raise UnavailableGuard("D03 self projection lacks sealed issuance")
        target = metadata.requirements
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("D03 self projection recovery anchor differs")
        if issued:
            original_permit = from_wire(json.loads(saved[1]))
            observed, state = port.get_fence_operation(
                namespace=namespace, authority_namespace=target.authority_namespace,
                operation_id=intent[1])
            if (observed != original_permit or state not in {"active", "finished"}
                    or original_permit.operation_id != intent[1]
                    or original_permit.pinned_anchor != anchor
                    or saved[4] != saved[2] + 1
                    or saved[5] != prior.invalidated_epochs[0].revision):
                raise UnavailableGuard("D03 self projection original fence differs")
            if state == "active":
                if (metadata.graph_revision, epoch.revision) != saved[4:6]:
                    raise UnavailableGuard("D03 self projection active graph changed")
                scope = FenceScope(
                    namespace, target.authority_namespace,
                    target.activation_generation, "write", intent[1],
                    original_permit, anchor,
                    NamespaceEpoch(*namespace.as_tuple, saved[3]), saved[2])
                if port.validate_fence(scope) != original_permit:
                    raise UnavailableGuard("D03 self projection original permit changed")
                port.finish_fence(scope, request_id=saved[6],
                                  request_digest=saved[7])
            elif (metadata.graph_revision < saved[4]
                  or epoch.revision < saved[5]):
                raise UnavailableGuard("D03 self projection graph receipt regressed")
            return replace(prior, status="duplicate")
        return self._reconcile_stage_retry(
            namespace, "d03", source_ref, original_operation_id,
            operation_id, intent, metadata, epoch, anchor)

    def _reconcile_stage_retry(self, namespace, stage, source_ref,
                               original_operation_id, operation_id,
                               intent, metadata, epoch, anchor) -> _StageRetry:
        """Finish the frozen no-commit attempt before pricing a new operation."""
        store, port = self.__store, self.__content_fence_v2
        target = metadata.requirements
        attempt_id = domain_bundle_write_attempt_id_v1(
            namespace, operation_id, intent[0])
        if (intent[1] != attempt_id
                or intent[2] != canonical_json(asdict(target))
                or intent[3] != canonical_json(asdict(anchor))
                or intent[4] > metadata.graph_revision
                or intent[5] > epoch.revision):
            raise UnavailableGuard("stage frozen attempt identity differs; HOLD")
        with store._lock:
            db = store._db
            rejection = db.execute(
                "SELECT digest,status,permit_json,graph_revision,graph_epoch,"
                "finish_request_id,finish_request_digest FROM graph_bundle_rejections_v2 "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone()
        if rejection is None:
            permit = port.begin_fence(
                namespace=namespace, authority_namespace=target.authority_namespace,
                holder=self.__holder, generation=target.activation_generation,
                operation="write", operation_id=attempt_id,
                expected_anchor=anchor, retain_on_unknown=True)
            scope = FenceScope(
                namespace, target.authority_namespace,
                target.activation_generation, "write", attempt_id,
                permit, anchor, epoch, metadata.graph_revision)
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("stage original write permit changed; HOLD")
            rejection = self._record_rejected_bundle_v2(
                namespace, operation_id, intent[0], attempt_id, metadata,
                epoch, intent, permit, allow_advanced_graph=True)
        self._finish_rejected_bundle_v2(
            namespace, metadata, epoch, anchor, attempt_id, intent[0],
            operation_id, rejection, allow_advanced_graph=True)
        table = ("graph_d03_self_projection_intents_v1" if stage == "d03" else
                 "graph_d04_baseline_intents_v1")
        from .runtime.issuers import (
            d03_self_identity_projection_quote_id, d04_baseline_quote_id,
        )
        quote_id = (d03_self_identity_projection_quote_id(namespace, operation_id)
                    if stage == "d03" else
                    d04_baseline_quote_id(namespace, operation_id))
        with store._lock:
            db = store._db
            if (db.execute(
                    f"SELECT operation_id,bundle_digest FROM {table} "
                    "WHERE bot=? AND persona=? AND source_ref=? "
                    "AND original_operation_id=?",
                    namespace.as_tuple + (source_ref, original_operation_id),
                ).fetchone() != (operation_id, intent[0])
                    or db.execute(
                        "SELECT 1 FROM graph_bundle_operations WHERE bot=? "
                        "AND persona=? AND operation_id=?",
                        namespace.as_tuple + (operation_id,),
                    ).fetchone() is not None
                    or db.execute(
                        "SELECT 1 FROM graph_bundle_fences_v2 WHERE bot=? "
                        "AND persona=? AND operation_id=?",
                        namespace.as_tuple + (operation_id,),
                    ).fetchone() is not None
                    or db.execute(
                        "SELECT 1 FROM runtime_budget_reservations "
                        "WHERE operation_id=?", (operation_id,),
                    ).fetchone() is not None
                    or db.execute(
                        "SELECT 1 FROM runtime_resource_quotes "
                        "WHERE quote_id=?", (quote_id,),
                    ).fetchone() is not None
                    or db.execute(
                        "SELECT 1 FROM runtime_budget_operations "
                        "WHERE bot_id=? AND persona_id=? AND operation_id=? "
                        "AND phase='reserve'",
                        namespace.as_tuple + (operation_id,),
                    ).fetchone() is not None):
                raise UnavailableGuard("stage original no-commit differs; HOLD")
            previous = db.execute(
                "SELECT 1 FROM sqlite_master WHERE type='table' "
                "AND name='graph_stage_retry_lineage_v1'",
            ).fetchone()
            prior_lineage = (db.execute(
                "SELECT retry_index FROM graph_stage_retry_lineage_v1 "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone() if previous else None)
        next_retry_index = prior_lineage[0] + 1 if prior_lineage else 1
        if next_retry_index > 64:
            raise UnavailableGuard("stage retry bound reached; HOLD")
        return _StageRetry(
            operation_id, intent[0], attempt_id,
            canonical_digest(list(rejection)), next_retry_index)

    def _recover_stage_candidate_read(self, namespace, read_key,
                                      metadata, epoch, anchor) -> None:
        """Finish a durable content-free candidate read left active by a crash."""
        store, port = self.__store, self.__content_fence_v2
        with store._lock:
            exists = store._db.execute(
                "SELECT 1 FROM sqlite_master WHERE type='table' "
                "AND name='graph_stage_candidate_reads_v1'",
            ).fetchone()
            open_rows = (store._db.execute(
                "SELECT attempt_id,graph_revision,graph_epoch,anchor_json "
                "FROM graph_stage_candidate_reads_v1 WHERE bot=? AND persona=? "
                "AND read_key=? AND state='open'",
                namespace.as_tuple + (read_key,),
            ).fetchall() if exists else [])
        if len(open_rows) > 1:
            raise UnavailableGuard("stage candidate has multiple active read attempts")
        if not open_rows:
            return
        attempt_id, revision, read_epoch, anchor_json = open_rows[0]
        if (anchor_json != canonical_json(asdict(anchor))
                or metadata.graph_revision < revision
                or epoch.revision < read_epoch):
            raise UnavailableGuard("stage candidate read recovery anchor changed")
        permit, state = port.get_fence_operation(
            namespace=namespace,
            authority_namespace=metadata.requirements.authority_namespace,
            operation_id=attempt_id)
        if state == "active":
            if (metadata.graph_revision, epoch.revision) != (revision, read_epoch):
                raise UnavailableGuard("stage candidate active read graph changed")
            scope = FenceScope(
                namespace, metadata.requirements.authority_namespace,
                metadata.requirements.activation_generation, "read", attempt_id,
                permit, anchor, NamespaceEpoch(*namespace.as_tuple, read_epoch), revision)
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("stage candidate read permit changed")
            port.finish_fence(scope, request_id="finish:" + attempt_id,
                              request_digest="sha256:" + canonical_digest({
                                  "operation_id": attempt_id,
                                  "permit_token": permit.token,
                                  "action": "finish_read",
                              }))
        elif state not in {"finished", "absent"}:
            raise UnavailableGuard("stage candidate read recovery state differs")
        with store._lock:
            store._db.execute(
                "UPDATE graph_stage_candidate_reads_v1 SET state='closed' "
                "WHERE bot=? AND persona=? AND read_key=? "
                "AND attempt_id=? AND state='open'",
                namespace.as_tuple + (read_key, attempt_id),
            )

    def _record_stage_candidate_read(self, namespace, read_key, attempt_id,
                                     metadata, epoch, anchor) -> None:
        store = self.__store
        with store._lock:
            db = store._db
            db.execute("BEGIN IMMEDIATE")
            try:
                if self._v2_graph_stamp(namespace) != (metadata, epoch):
                    raise StaleRead("stage candidate graph changed before read intent")
                db.execute("""CREATE TABLE IF NOT EXISTS graph_stage_candidate_reads_v1(
                    bot TEXT NOT NULL, persona TEXT NOT NULL,
                    read_key TEXT NOT NULL, attempt_id TEXT NOT NULL,
                    graph_revision INTEGER NOT NULL, graph_epoch INTEGER NOT NULL,
                    anchor_json TEXT NOT NULL,
                    state TEXT NOT NULL CHECK(state IN ('open','closed')),
                    PRIMARY KEY(bot,persona,read_key,attempt_id))""")
                db.execute(
                    "INSERT INTO graph_stage_candidate_reads_v1"
                    "(bot,persona,read_key,attempt_id,graph_revision,"
                    "graph_epoch,anchor_json,state) VALUES(?,?,?,?,?,?,?,'open')",
                    namespace.as_tuple + (read_key, attempt_id,
                                          metadata.graph_revision, epoch.revision,
                                          canonical_json(asdict(anchor))),
                )
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise

    def _close_stage_candidate_read(self, namespace, read_key, attempt_id) -> None:
        with self.__store._lock:
            self.__store._db.execute(
                "UPDATE graph_stage_candidate_reads_v1 SET state='closed' "
                "WHERE bot=? AND persona=? AND read_key=? "
                "AND attempt_id=? AND state='open'",
                namespace.as_tuple + (read_key, attempt_id),
            )

    def commit_d03_self_identity_projection_v1(
        self, bootstrap: object, namespace: NamespaceId, job_id: str,
        original_operation_id: str, installation_policy, admin_policy,
        clock_policy,
    ) -> CommitReceipt:
        """Project the paired Authority self and first-arrival perspective atomically.

        The initial read only constructs a candidate. The write fence obtains a
        fresh current Authority value and the graph transaction checks its stamp.
        """
        from .authority_service.v2_contract import FencePermitV2
        from .authority_service.v2_self_identity_contract import AuthorityCurrentSelfIdentityV1
        from .domains.d03.self_identity_qualification import (
            self_identity_mapping_from_current,
        )
        from .domains.d03.self_perspective import (
            build_self_identity_projection_bundle, self_mapping_key,
            self_perspective_id, self_perspective_key,
        )
        from .host.authority_profile import (
            AdminD03SelfIdentityProjectionPolicy, AdminIngressClockPolicy,
        )
        from .installation_policy import AdminInstallationPolicy
        from .runtime.d03_self_identity_projection_identity import (
            d03_self_identity_projection_activity_id_v1,
            d03_self_identity_projection_operation_id_v1,
            d03_self_identity_projection_retry_operation_id_v2,
        )
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.issuers import (
            D03_SELF_IDENTITY_PROJECTION_WORK_KIND,
            d03_self_identity_projection_quote_id,
        )
        from .runtime_contracts import (
            CommandEnvelope, OperationIdentity, QueryEpoch, RUNTIME_SCHEMA,
            VersionedRef,
        )

        self._admin(bootstrap)
        if (type(namespace) is not NamespaceId
                or type(installation_policy) is not AdminInstallationPolicy
                or type(admin_policy) is not AdminD03SelfIdentityProjectionPolicy
                or type(clock_policy) is not AdminIngressClockPolicy
                or not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or self.__self_identity_port is None
                or self.__d02_issuer is None or self.__d11_issuer is None):
            raise UnavailableGuard("installed D03 self projection authorities required; HOLD")
        policy = installation_policy
        grant = policy.root_grant
        if (namespace != policy.namespace
                or D03_SELF_IDENTITY_PROJECTION_WORK_KIND not in grant.allowed_work_kinds):
            raise UnavailableGuard("installed D03 self projection grant differs; HOLD")
        store, port = self.__store, self.__content_fence_v2
        recovered = self._recover_d03_self_projection_before_read(
            namespace, original_operation_id, policy, admin_policy)
        if type(recovered) is CommitReceipt:
            return recovered
        retry = recovered if type(recovered) is _StageRetry else None
        try:
            reading = port.read_ingress_clock(clock_policy)
            now_utc = trusted_upper(reading)
        except Exception as exc:
            raise UnavailableGuard("paired D03 self projection clock unavailable; HOLD") from exc
        deadline = min(math.nextafter(math.fsum((
            now_utc, admin_policy.deadline_after_seconds)), -math.inf),
            grant.valid_until_utc)
        if deadline <= now_utc:
            raise UnavailableGuard("D03 self projection deadline unavailable; HOLD")
        monotonic_deadline = reading.monotonic_after_seconds + (
            deadline - reading.utc_upper_bound_seconds)
        if not math.isfinite(monotonic_deadline):
            raise UnavailableGuard("D03 self projection monotonic deadline differs")
        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
        target = metadata.requirements
        if (target.authority_id != policy.expected_authority_id
                or target.authority_namespace != policy.authority_namespace
                or port.installation_grant.installation_id != policy.installation_id):
            raise UnavailableGuard("D03 self projection installation differs; HOLD")
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("D03 self projection recovery anchor differs; HOLD")
        self._recover_stage_candidate_read(
            namespace, original_operation_id, metadata, epoch, anchor)
        read_operation = "d03-self-read-" + secrets.token_hex(16)
        self._record_stage_candidate_read(
            namespace, original_operation_id, read_operation, metadata, epoch, anchor)
        permit = port.begin_fence(
            namespace=namespace, authority_namespace=target.authority_namespace,
            holder=self.__holder, generation=target.activation_generation,
            operation="read", operation_id=read_operation, expected_anchor=anchor)
        scope = FenceScope(namespace, target.authority_namespace,
                           target.activation_generation, "read", read_operation,
                           permit, anchor, epoch, metadata.graph_revision)
        try:
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("D03 self projection read permit changed")
            guarded = port.get_current_owner_guard_for_fence(
                namespace=namespace, authority_namespace=target.authority_namespace, permit=permit)
            if (type(guarded) is not tuple or len(guarded) != 2
                    or type(guarded[0]) is not OwnerAuthorizationGuardV1
                    or guarded[1] != permit):
                raise UnavailableGuard("D03 self projection Owner head unavailable")
            current = self.__self_identity_port.current_self_identity(
                namespace=namespace,
                authority_namespace=target.authority_namespace,
                request_operation_id=read_operation, permit=permit)
            if (type(current) is not AuthorityCurrentSelfIdentityV1
                    or current.permit != permit
                    or current.request_operation_id != read_operation
                    or current.graph_revision != metadata.graph_revision
                    or current.graph_epoch != epoch.revision):
                raise UnavailableGuard("D03 self projection current read differs; HOLD")
            from .domains.d03.self_identity_qualification import require_self_identity_storage_binding_v1
            storage_admission = None
            if current.origin_graph_incarnation is not None:
                from .authority_service.d12_target_owner_admission_v1 import D12CurrentOwnerAuthorityV1
                current_owner, observed_permit = port.get_current_background_owner_authority_for_fence_v1(
                    namespace=namespace, authority_namespace=target.authority_namespace, permit=permit)
                if (type(current_owner) is not D12CurrentOwnerAuthorityV1 or current_owner.target_admission is not None
                        or current_owner.guard != guarded[0] or observed_permit != permit):
                    raise UnavailableGuard("D03 current source Owner observation unavailable")
                storage_admission = current_owner.storage_admission
            require_self_identity_storage_binding_v1(current, storage_admission, permit,
                owner_guard=guarded[0], metadata=metadata, graph_epoch=epoch, request_operation_id=read_operation)
            candidate_mapping = self_identity_mapping_from_current(current)
            with store._lock:
                if self._v2_graph_stamp(namespace) != (metadata, epoch):
                    raise StaleRead("D03 self projection graph changed during read")
                db = store._db
                role, _, role_epoch, _ = self._scene_binding_state_locked(
                    namespace, guarded[0])
                if (role_epoch != epoch
                        or current.role_head_id != role.head_id
                        or current.owner_authorization_revision
                        != guarded[0].authorization_revision
                        or current.owner_authorization_head
                        != guarded[0].authorization_head
                        or current.graph_incarnation != target.graph_incarnation
                        or current.installation_id != policy.installation_id
                        or current.manifest_digest != policy.manifest_digest):
                    raise UnavailableGuard("D03 self projection current role differs; HOLD")
                job, _, _, outbox, _, _, source_version, access_version = (
                    self._first_ingress_encoding_job_locked(namespace, job_id))
                if (job.operation_id != original_operation_id
                        or job.phase != "queued" or job.cancel_epoch != 0
                        or job.fence != 0 or job.lease_holder is not None
                        or outbox.payload_ref != source_version.key.owner.subject):
                    raise UnavailableGuard("D03 self projection job is no longer queued; HOLD")
                source_ref = source_version.key.token
                qualification = self._original_first_ingress_qualification_locked(
                    namespace, original_operation_id, source_ref)
                arrivals = db.execute(
                    "SELECT operation_id,bundle_digest FROM "
                    "graph_d03_arrival_issuance_v2 WHERE bot=? AND persona=? "
                    "AND source_ref=?", namespace.as_tuple
                    + (source_version.key.owner.subject,),
                ).fetchall()
                if len(arrivals) != 1:
                    raise UnavailableGuard("D03 self projection needs one original arrival")
                arrival_rows = db.execute(
                    "SELECT a.token,a.revision,a.value,a.valid FROM graph_atoms AS a "
                    "JOIN graph_history AS h ON h.token=a.token AND h.revision=a.revision "
                    "WHERE h.event_bot=? AND h.event_persona=? AND h.event_id=? "
                    "AND a.type_name='d03.world_event'",
                    namespace.as_tuple + (arrivals[0][0],),
                ).fetchall()
                arrival_receipt = db.execute(
                    "SELECT digest FROM graph_bundle_operations WHERE bot=? AND persona=? "
                    "AND operation_id=?", namespace.as_tuple + (arrivals[0][0],),
                ).fetchone()
                if len(arrival_rows) != 1 or arrival_receipt != (arrivals[0][1],):
                    raise UnavailableGuard("D03 self projection arrival receipt differs")
                event_row = arrival_rows[0]
                event_atom = GraphAtom(AtomKey.from_token(event_row[0]),
                                       event_row[1], json.loads(event_row[2]),
                                       bool(event_row[3]))
                mapping_key = self_mapping_key(namespace)
                mapping_row = db.execute(
                    "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                    (mapping_key.token,),
                ).fetchone()
                mapping_atom = (GraphAtom(mapping_key, mapping_row[0],
                                          json.loads(mapping_row[1]), bool(mapping_row[2]))
                                if mapping_row else GraphAtom(mapping_key, 0, {}, False))
                perspective_key = self_perspective_key(namespace,
                    self_perspective_id(namespace, event_atom.value["scene_ref"],
                                        event_atom.key.token))
                perspective_row = db.execute(
                    "SELECT revision FROM graph_atoms WHERE token=?",
                    (perspective_key.token,),
                ).fetchone()
                identity_row = db.execute(
                    "SELECT conversation_ref FROM graph_first_ingress_identity_v1 "
                    "WHERE bot=? AND persona=? AND operation_id=?",
                    namespace.as_tuple + (original_operation_id,),
                ).fetchone()
                if identity_row is None:
                    raise UnavailableGuard("D03 self projection original ingress absent")
                guard_versions = dict(db.execute(
                    "SELECT kind,version FROM graph_guard_versions WHERE bot=? "
                    "AND persona=? AND ref='current'", namespace.as_tuple,
                ).fetchall())
                authority_epochs = db.execute(
                    "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                    "WHERE bot=? AND persona=?", namespace.as_tuple,
                ).fetchone() or (0, 0)
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("D03 self projection read permit changed")
        finally:
            port.finish_fence(scope, request_id="finish:" + read_operation,
                              request_digest="sha256:" + canonical_digest({
                                  "operation_id": read_operation,
                                  "permit_token": permit.token,
                                  "action": "finish_read",
                              }))
            self._close_stage_candidate_read(
                namespace, original_operation_id, read_operation)
        base_operation_id = d03_self_identity_projection_operation_id_v1(
            namespace, source_ref, candidate_mapping.certification_ref)
        if retry is not None and retry.retry_index == 1 and (
                retry.previous_operation_id != base_operation_id):
            raise UnavailableGuard("D03 Authority registration changed before retry; HOLD")
        operation_id = (
            d03_self_identity_projection_retry_operation_id_v2(
                namespace, source_ref, candidate_mapping.certification_ref,
                retry.previous_operation_id, retry.retry_index)
            if retry is not None else base_operation_id)
        activity_id = d03_self_identity_projection_activity_id_v1(namespace, source_ref)
        lease, capability = self.grant(
            bootstrap, actor="host", issuer_domain="d11", namespace=namespace,
            domains=("d03",), activation_generation=target.activation_generation,
            operation_id=operation_id)
        try:
            authority = AuthorityContext(
                "host", "d11", capability, namespace, ("persona", "event"),
                "context", (identity_row[0],), grant.policy_ref,
                target.activation_generation)
            quote_id = d03_self_identity_projection_quote_id(namespace, operation_id)
            if perspective_row is not None:
                raise UnavailableGuard("D03 perspective exists without original stage receipt")
            read_versions = tuple(dict.fromkeys((
                *role.read_versions, source_version, access_version,
                GraphVersion(event_atom.key, event_atom.revision),
                GraphVersion(mapping_key, mapping_atom.revision),
                GraphVersion(perspective_key, perspective_row[0] if perspective_row else 0),
            )))
            envelope = CommandEnvelope(
                RUNTIME_SCHEMA,
                OperationIdentity(activity_id, None, "self-projection-attempt",
                                  D03_SELF_IDENTITY_PROJECTION_WORK_KIND,
                                  operation_id, canonical_digest({
                                      "input_refs": [source_ref]})),
                authority,
                VersionGuard(
                    read_versions, (QueryEpoch(namespace, "all", epoch.revision),),
                    *authority_epochs, store._registry.catalogue_hash,
                    guard_versions["scheme"], guard_versions["operator"],
                    guard_versions["policy"], (), (), (VersionedRef(quote_id, 1),)),
                qualification, (source_ref,), grant.lease_id, deadline,
                monotonic_deadline, "character-v1", (original_operation_id,),
            )
            bundle = build_self_identity_projection_bundle(
                envelope, role, candidate_mapping, mapping_atom, event_atom)
            return self._commit_domain_bundle_v2(
                bundle, lease, self_identity_issuance=(
                    policy, admin_policy, policy.installation_id, now_utc,
                    source_ref, candidate_mapping, job_id, original_operation_id,
                    retry))
        finally:
            self.release_authority_lease(bootstrap, lease)

    def _recover_d04_baseline_before_read(
        self, namespace, original_operation_id, installation_policy,
        admin_policy,
    ) -> CommitReceipt | None:
        """Recover an original baseline write without requiring a queued job."""
        from .authority_service.v2_contract import from_wire

        store, port = self.__store, self.__content_fence_v2
        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
            identity = store._db.execute(
                "SELECT source_ref FROM graph_first_ingress_identity_v1 WHERE bot=? "
                "AND persona=? AND operation_id=?",
                namespace.as_tuple + (original_operation_id,),
            ).fetchone()
            if identity is None:
                raise UnavailableGuard("D04 original ingress is unavailable; HOLD")
            source_ref = source_key(*namespace.as_tuple, identity[0]).token
            has_index = store._db.execute(
                "SELECT 1 FROM sqlite_master WHERE type='table' "
                "AND name='graph_d04_baseline_intents_v1'",
            ).fetchone() is not None
            indexed = (store._db.execute(
                "SELECT operation_id,bundle_digest FROM graph_d04_baseline_intents_v1 "
                "WHERE bot=? AND persona=? AND source_ref=? AND original_operation_id=?",
                namespace.as_tuple + (source_ref, original_operation_id),
            ).fetchone() if has_index else None)
            has_issued = store._db.execute(
                "SELECT 1 FROM sqlite_master WHERE type='table' "
                "AND name='graph_d04_baseline_issuance_v1'",
            ).fetchone() is not None
            issued = (store._db.execute(
                "SELECT operation_id,event_ref,quote_id,bundle_digest FROM "
                "graph_d04_baseline_issuance_v1 WHERE bot=? AND persona=? "
                "AND source_ref=?",
                namespace.as_tuple + (source_ref,),
            ).fetchall() if has_issued else [])
            if len(issued) > 1:
                raise UnavailableGuard("D04 baseline has multiple original receipts")
            if not issued and indexed is None:
                return None
            operation_id = issued[0][0] if issued else indexed[0]
            intent = store._db.execute(
                "SELECT digest,fence_attempt_id,requirements_json,anchor_json,"
                "graph_revision,graph_epoch FROM graph_bundle_intents_v2 "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone()
            if intent is None or (indexed is not None
                                  and indexed != (operation_id, intent[0])):
                raise UnavailableGuard("D04 baseline durable intent differs")
            prior = self._get_operation_fenced(
                AuthorityContext("host", "d11", "recovery", namespace,
                                 ("persona", "event"), "context", (),
                                 installation_policy.root_grant.policy_ref,
                                 metadata.requirements.activation_generation),
                operation_id, v2=True)
            saved = store._db.execute(
                "SELECT digest,permit_json,pre_graph_revision,pre_graph_epoch,"
                "post_graph_revision,post_graph_epoch,finish_request_id,"
                "finish_request_digest FROM graph_bundle_fences_v2 "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone()
            if issued:
                quote = self.__d02_issuer._load_quote(store._db, issued[0][2], 1)
                if (prior is None or saved is None
                        or issued[0][3] != prior.operation_digest
                        or saved[0] != prior.operation_digest
                        or quote.operation_id != operation_id
                        or quote.work_kind != "d04.encoding_baseline"
                        or dict(quote.ceiling) != dict(admin_policy.quote_ceiling)
                        or not any(item.key.type_name == "d04.encoding_baseline.v1"
                                   for item in prior.write_versions)):
                    raise UnavailableGuard("D04 baseline original receipt differs")
            elif prior is not None or saved is not None:
                raise UnavailableGuard("D04 baseline lacks sealed issuance")
        target = metadata.requirements
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("D04 baseline recovery anchor differs")
        if issued:
            observed, state = port.get_fence_operation(
                namespace=namespace,
                authority_namespace=target.authority_namespace,
                operation_id=intent[1])
            original_permit = from_wire(json.loads(saved[1]))
            if (observed != original_permit or state not in {"active", "finished"}
                    or original_permit.operation_id != intent[1]
                    or original_permit.pinned_anchor != anchor
                    or saved[4] != saved[2] + 1
                    or saved[5] != prior.invalidated_epochs[0].revision):
                raise UnavailableGuard("D04 baseline original fence differs")
            if state == "active":
                if (metadata.graph_revision, epoch.revision) != saved[4:6]:
                    raise UnavailableGuard("D04 baseline active graph changed")
                scope = FenceScope(
                    namespace, target.authority_namespace,
                    target.activation_generation, "write", intent[1],
                    original_permit, anchor,
                    NamespaceEpoch(*namespace.as_tuple, saved[3]), saved[2])
                if port.validate_fence(scope) != original_permit:
                    raise UnavailableGuard("D04 baseline original permit changed")
                port.finish_fence(scope, request_id=saved[6],
                                  request_digest=saved[7])
            elif (metadata.graph_revision < saved[4]
                  or epoch.revision < saved[5]):
                raise UnavailableGuard("D04 baseline graph receipt regressed")
            return replace(prior, status="duplicate")
        return self._reconcile_stage_retry(
            namespace, "d04", source_ref, original_operation_id,
            operation_id, intent, metadata, epoch, anchor)

    def read_current_d04_joint_replay_input_v2(
            self, authority: AuthorityContext, lease: object, *,
            root_ref: str, role_start: float, role_end: float,
            audience: tuple[str, ...], purpose: str):
        """Freeze a complete joint component under the current Owner read fence.

        This returns only typed input for a lock-free installed ABI2 replay.
        Its status does not authorize a product advance or numeric original.
        """
        from .domains.d04.affect import AffectProvider, AffectScheme
        from .runtime.d04_current_joint_replay_input_v2 import (
            read_current_joint_replay_input_in_transaction_v2,
        )
        from .runtime_contracts import QueryEpoch

        if (type(authority) is not AuthorityContext
                or authority.issuer_domain != "d12"
                or not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or type(root_ref) is not str or not root_ref
                or type(audience) is not tuple or not audience
                or type(purpose) is not str or not purpose):
            raise UnavailableGuard("current D04 joint Owner read unavailable")
        self._authorize(lease, authority, frozenset(("d04",)), owner_read=True)
        owner = self.__owner_leases.get(lease)
        proof = self.__owner_session_proofs.get(lease)
        if (owner is None or proof is None or audience != authority.audience
                or purpose != authority.purpose):
            raise UnavailableGuard("current D04 joint Owner scope unavailable")
        registration = self.__providers.get("d04")
        if (registration is None or not isinstance(registration[0], AffectProvider)
                or type(registration[0]._active_scheme) is not AffectScheme):
            raise UnavailableGuard("installed D04 scheme unavailable")
        scheme = registration[0]._active_scheme
        store = self.__store
        namespace = authority.namespace

        topology_verifier = self._installed_d04_authored_topology_verifier_v3()
        def reader():
            db = store._db
            if db.in_transaction:
                raise UnavailableGuard("joint read needs an idle graph connection")
            db.execute("BEGIN")
            try:
                metadata, epoch = self._v2_graph_stamp(namespace)
                row = db.execute(
                    "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                    "WHERE bot=? AND persona=?", namespace.as_tuple,
                ).fetchone()
                if row is None:
                    raise UnavailableGuard("joint authority epochs unavailable")
                return read_current_joint_replay_input_in_transaction_v2(
                    db, namespace=namespace, registry=store._registry,
                    authored_topology_verifier=topology_verifier,
                    scheme=scheme, root_ref=root_ref, role_start=role_start,
                    role_end=role_end, expected_query_epoch=QueryEpoch(
                        namespace, "all", epoch.revision),
                    expected_graph_incarnation=metadata.requirements.graph_incarnation,
                    expected_graph_revision=metadata.graph_revision,
                    expected_access_epoch=row[0], expected_delete_epoch=row[1],
                    audience=audience, purpose=purpose,
                )
            finally:
                db.rollback()

        return self._read_v2(
            authority, reader, owner_binding=owner, owner_session_proof=proof,
            fence_observer=lambda scope: topology_verifier.observe_current_location_for_fence_v3(self.__content_fence_v2, scope))

    def _installed_d04_authored_topology_verifier_v3(self):
        from .runtime.d04_owner_initialization_v3 import verifier_for_coordinator_v3
        return verifier_for_coordinator_v3(self)

