    def prepare_current_d04_joint_product_v3(
            self, authority: AuthorityContext, lease: object, *, envelope,
            root_ref: str, role_start: float, role_end: float):
        """Freeze real joint predecessors together with the complete current input.

        The installed semantic/time and numerical resource issuers must bind
        this preparation before the public adoption port may commit it.
        """
        from .domains.d04.affect import AffectProvider, AffectScheme
        from .domains.d04.joint_state_output_v1 import (
            JointStateFrozenPredecessorsV1, JointStatePredecessorV1)
        from .runtime.d04_current_joint_replay_input_v2 import (
            read_current_joint_replay_input_in_transaction_v2)
        from .runtime.d04_joint_product_assembly_v3 import D04JointProductPreparationV3
        from .runtime_contracts import CommandEnvelope, QueryEpoch

        if (type(envelope) is not CommandEnvelope or envelope.authority != authority
                or authority.issuer_domain != "d12"
                or self.__d04_installed_joint_assembly is None
                or self.__d04_installed_joint_output_policy is None
                or not isinstance(self.__store, ProductionGraphStore)):
            raise UnavailableGuard("installed D04 joint preparation unavailable; HOLD")
        self._authorize(lease, authority, frozenset(("d04",)), owner_read=True)
        owner, proof = self.__owner_leases.get(lease), self.__owner_session_proofs.get(lease)
        registration = self.__providers.get("d04")
        if (owner is None or proof is None or registration is None
                or type(registration[0]) is not AffectProvider
                or type(registration[0]._active_scheme) is not AffectScheme):
            raise UnavailableGuard("current D04 Owner/Scheme unavailable; HOLD")

        topology_verifier = self._installed_d04_authored_topology_verifier_v3()
        def read():
            db = self.__store._db
            db.execute("BEGIN")
            try:
                metadata, epoch = self._v2_graph_stamp(authority.namespace)
                rights = self._deletion_epochs_locked(db, authority.namespace)
                current = read_current_joint_replay_input_in_transaction_v2(
                    db, namespace=authority.namespace, registry=self.__store._registry,
                    authored_topology_verifier=topology_verifier,
                    scheme=registration[0]._active_scheme, root_ref=root_ref,
                    role_start=role_start, role_end=role_end,
                    expected_query_epoch=QueryEpoch(authority.namespace, "all", epoch.revision),
                    expected_graph_incarnation=metadata.requirements.graph_incarnation,
                    expected_graph_revision=metadata.graph_revision,
                    expected_access_epoch=rights[0], expected_delete_epoch=rights[1],
                    audience=authority.audience, purpose=authority.purpose)
                atoms = []
                for version in current.component.read_versions:
                    row = db.execute("SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                                     (version.key.token,)).fetchone()
                    if (row[0] if row else 0) != version.revision:
                        raise StaleRead("D04 frozen component changed")
                    atoms.append(GraphAtom(version.key, row[0], json.loads(row[1]), bool(row[2]))
                                 if row else GraphAtom(version.key, 0, {}, False))
                snapshot = GraphSnapshot(tuple(atoms), (epoch,))
                predecessors = []
                for block, checkpoint in zip(current.component.block_drives, current.checkpoints):
                    state = snapshot.get(block.graph_state_version.key)
                    checkpoint_atom = snapshot.get(block.checkpoint_version.key)
                    if (state is None or not state.valid or checkpoint_atom is None
                            or not checkpoint_atom.valid or block.predecessor_receipt_digest is None):
                        raise UnavailableGuard("D04 predecessor original unavailable; HOLD")
                    decoded = self.__store._registry.spec(state.key.type_name).validator(state.value)
                    predecessors.append(JointStatePredecessorV1(
                        block.checkpoint_ref, block.checkpoint_version.revision, checkpoint,
                        state.key.token, state.revision, decoded, block.predecessor_receipt_digest))
                guard = replace(
                    envelope.version_guard, read_versions=current.component.read_versions,
                    query_epochs=(current.component.query_epoch,),
                    access_epoch=rights[0], delete_epoch=rights[1],
                    catalogue_version=self.__store._registry.catalogue_hash,
                    scheme_version=self._version(db, authority.namespace, "scheme", "current"),
                    operator_version=self._version(db, authority.namespace, "operator", "current"),
                    policy_version=self._version(db, authority.namespace, "policy", "current"))
                frozen = JointStateFrozenPredecessorsV1(
                    authority.namespace, envelope.identity.operation_id, tuple(predecessors))
                return D04JointProductPreparationV3(
                    replace(envelope, version_guard=guard), current, frozen, snapshot)
            finally:
                db.rollback()

        return self._read_v2(authority, read, owner_binding=owner, owner_session_proof=proof,
            fence_observer=lambda scope: topology_verifier.observe_current_location_for_fence_v3(self.__content_fence_v2, scope))

    def read_current_d04_joint_output_original_v1(
            self, authority: AuthorityContext, lease: object, *,
            operation_id: str):
        """Read an adopted V2 output and its complete current source closure."""
        from .domains.d04.product_readout import check_joint_output_against_snapshot_v2
        from .runtime.d04_joint_output_original_store_v1 import (
            read_d04_joint_output_original_v1,
            read_current_d04_joint_output_source_closure_v1,
        )
        from .runtime.d04_joint_advance_v2 import read_joint_advance_v2
        from .host.installed_d04_output_policy import (
            load_installed_d04_output_policy_v1,
        )

        if (type(authority) is not AuthorityContext
                or authority.issuer_domain != "d12"
                or not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or self.__d04_installed_joint_assembly is None
                or self.__d04_installed_joint_output_policy is None
                or type(operation_id) is not str or not operation_id):
            raise UnavailableGuard("current D04 joint output Owner read unavailable")
        assembly = self.__d04_installed_joint_assembly
        try:
            current_policy = load_installed_d04_output_policy_v1(
                assembly.package_root, assembly.installation_policy.manifest_digest,
                require_formal=False, require_backend_runtime=True)
        except (OSError, TypeError, ValueError) as exc:
            raise UnavailableGuard("formal D04 output policy unavailable; HOLD") from exc
        if current_policy != self.__d04_installed_joint_output_policy:
            raise UnavailableGuard("D04 output installation changed; HOLD")
        self._authorize(lease, authority, frozenset(("d04",)), owner_read=True)
        owner = self.__owner_leases.get(lease)
        proof = self.__owner_session_proofs.get(lease)
        if owner is None or proof is None:
            raise UnavailableGuard("current D04 joint output Owner proof unavailable")
        namespace = authority.namespace

        def reader():
            db = self.__store._db
            if db.in_transaction:
                raise UnavailableGuard("joint output read needs an idle graph connection")
            db.execute("BEGIN")
            try:
                metadata, epoch = self._v2_graph_stamp(namespace)
                rights = db.execute(
                    "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                    "WHERE bot=? AND persona=?", namespace.as_tuple,
                ).fetchone()
                original = read_d04_joint_output_original_v1(
                    db, namespace, operation_id)
                if original is None:
                    return None
                from .runtime.d04_series_original_v1 import require_series_adopted_original_v1
                require_series_adopted_original_v1(db, namespace, operation_id)
                policy = self.__d04_installed_joint_output_policy
                if (rights is None
                        or rights != (original.access_epoch, original.delete_epoch)
                        or original.native_manifest_sha256
                           != self.__d04_installed_joint_assembly.installation_policy.manifest_digest
                        or original.policy_digest != policy.policy.digest
                        or original.policy_sha256 != policy.policy_sha256
                        or original.readout_sha256 != policy.policy.readout_sha256
                        or metadata.graph_revision < original.graph_revision + 1
                        or epoch.revision < original.graph_epoch + 1
                        or metadata.requirements.graph_incarnation
                           != original.graph_incarnation):
                    raise UnavailableGuard("D04 joint output installed identity changed; HOLD")
                numeric = db.execute(
                    "SELECT evidence_digest,numeric_receipt_json,"
                    "numeric_receipt_digest,verification_json,verification_digest "
                    "FROM graph_d04_joint_numeric_originals_v1 "
                    "WHERE bot=? AND persona=? AND operation_id=?",
                    namespace.as_tuple + (operation_id,),
                ).fetchone()
                joint = db.execute(
                    "SELECT evidence_digest FROM graph_d04_joint_advances_v2 "
                    "WHERE bot=? AND persona=? AND operation_id=?",
                    namespace.as_tuple + (operation_id,),
                ).fetchone()
                if numeric is None or joint != (numeric[0],):
                    raise UnavailableGuard("D04 joint numeric original unavailable; HOLD")
                evidence = read_joint_advance_v2(db, namespace, operation_id)
                if (evidence is None or evidence.digest != numeric[0]
                        or evidence.output_write_set_digest != original.write_set_digest
                        or evidence.native_manifest_sha256
                           != original.native_manifest_sha256
                        or evidence.native_sha256 != original.native_sha256):
                    raise UnavailableGuard("D04 joint adoption original differs; HOLD")
                source_snapshot = read_current_d04_joint_output_source_closure_v1(
                    db, namespace, operation_id, numeric[0],
                    original.component_digest, epoch.revision)
                closure = {atom.key: atom for atom in source_snapshot.atoms}
                source_atoms = tuple(atom for atom in source_snapshot.atoms
                                     if atom.key.type_name == "memory.source")
                numeric_body = json.loads(numeric[1])
                verification_body = json.loads(numeric[3])
                if (type(numeric_body) is not dict
                        or canonical_serialize(numeric_body) != numeric[1]
                        or numeric_body.get("receipt_digest") != numeric[2]
                        or canonical_digest({key: value for key, value
                                             in numeric_body.items()
                                             if key not in {"receipt_digest", "status"}})
                           != numeric[2]
                        or numeric_body.get("component_digest")
                           != original.component_digest
                        or numeric_body.get("full_transcript_sha256")
                           != original.full_transcript_sha256
                        or numeric_body.get("math_transcript_sha256")
                           != original.math_transcript_sha256
                        or type(numeric_body.get("source_versions")) is not list
                        or type(verification_body) is not dict
                        or canonical_serialize(verification_body) != numeric[3]
                        or canonical_digest(verification_body) != numeric[4]
                        or verification_body.get("readout_sha256")
                           != original.readout_sha256):
                    raise UnavailableGuard("D04 joint numeric source closure invalid; HOLD")
                for item in numeric_body["source_versions"]:
                    if type(item) is not list or len(item) != 7:
                        raise UnavailableGuard("D04 joint numeric source row invalid; HOLD")
                    for ref, revision in ((item[0], item[1]),
                                          (item[2], item[3]), (item[4], item[5])):
                        atom = closure.get(AtomKey.from_token(ref))
                        if atom is None or atom.revision != revision or not atom.valid:
                            raise StaleRead("D04 joint numeric source/access changed")
                source_refs = {atom.key.token for atom in source_atoms}
                for member in original.members:
                    state_sources = (member.next_state.source_refs
                                     if member.kind == "mood"
                                     else member.next_state.historical_source_refs)
                    authored = source_key(
                        *namespace.as_tuple,
                        member.next_checkpoint.block.authored_source_id).token
                    if (authored not in source_refs
                            or not set(state_sources).issubset(source_refs)):
                        raise UnavailableGuard(
                            "D04 joint output state source closure is incomplete; HOLD")
                keys = tuple(AtomKey.from_token(ref) for member in original.members
                             for ref in (member.checkpoint_ref,
                                         member.predecessor_state_ref))
                atoms = []
                for key in keys:
                    row = db.execute(
                        "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                        (key.token,),
                    ).fetchone()
                    atoms.append(GraphAtom(key, row[0], json.loads(row[1]), bool(row[2]))
                                 if row else GraphAtom(key, 0, {}, False))
                snapshot = GraphSnapshot(
                    tuple(closure.values()) + tuple(atoms),
                    (NamespaceEpoch(*namespace.as_tuple, epoch.revision),))
                check_joint_output_against_snapshot_v2(original, snapshot)
                return D04CurrentJointOutputOriginalReadV1(
                    namespace, original, snapshot, metadata.graph_revision,
                    epoch.revision, rights[0], rights[1])
            finally:
                db.rollback()

        return self._read_v2(
            authority, reader, owner_binding=owner, owner_session_proof=proof)

