    def with_current_d04_encoding_projection_v2(
            self, authority: AuthorityContext, lease: object, *,
            baseline_id: str, source_ref: str, audience: tuple[str, ...],
            purpose: str, project):
        """Reserve the Owner-fenced D04 v2 issuer seam, with no numeric release.

        The graph has no authenticated adopted joint numeric receipt original,
        and W12's projection policy is still a candidate. A caller callback is
        never allowed to turn an unsigned numeric candidate into graph state.
        """
        if (type(authority) is not AuthorityContext
                or authority.issuer_domain != "d12"
                or not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or type(baseline_id) is not str or not baseline_id
                or type(source_ref) is not str or not source_ref
                or type(audience) is not tuple or not audience
                or type(purpose) is not str or not purpose
                or not callable(project)):
            raise UnavailableGuard("installed D04 v2 projection read unavailable")
        self._authorize(lease, authority, frozenset(("d04",)), owner_read=True)
        owner = self.__owner_leases.get(lease)
        proof = self.__owner_session_proofs.get(lease)
        if owner is None or proof is None:
            raise UnavailableGuard("D04 v2 current Owner proof unavailable")

        def reader():
            raise UnavailableGuard(
                "D04 v2 adopted joint numeric original and formal issuer unavailable; HOLD")

        return self._read_v2(
            authority, reader, owner_binding=owner,
            owner_session_proof=proof)

    def commit_d04_encoding_baseline_v1(
        self, bootstrap: object, namespace: NamespaceId, job_id: str,
        original_operation_id: str, installation_policy, admin_policy,
        clock_policy,
    ) -> CommitReceipt:
        """Commit an unknown-valued D04 baseline from the original self view."""
        from .domains.d03.self_perspective import SelfPerspective
        from .domains.d04 import AffectProvider
        from .host.authority_profile import (
            AdminD04EncodingBaselinePolicy, AdminIngressClockPolicy,
        )
        from .installation_policy import AdminInstallationPolicy
        from .runtime.d04_baseline_retry_identity import (
            d04_baseline_retry_operation_id_v2,
        )
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.issuers import D04_BASELINE_WORK_KIND, d04_baseline_quote_id
        from .runtime_contracts import (
            CommandEnvelope, OperationIdentity, QueryEpoch, RUNTIME_SCHEMA,
            VersionedRef,
        )

        self._admin(bootstrap)
        if (type(namespace) is not NamespaceId
                or type(installation_policy) is not AdminInstallationPolicy
                or type(admin_policy) is not AdminD04EncodingBaselinePolicy
                or type(clock_policy) is not AdminIngressClockPolicy
                or not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or self.__self_identity_port is None):
            raise UnavailableGuard("installed D04 baseline authorities required; HOLD")
        provider_entry = self.__providers.get("d04")
        if provider_entry is None or type(provider_entry[0]) is not AffectProvider:
            raise UnavailableGuard("current D04 baseline provider unavailable; HOLD")
        provider = provider_entry[0]
        policy = installation_policy
        grant = policy.root_grant
        if (policy.namespace != namespace
                or D04_BASELINE_WORK_KIND not in grant.allowed_work_kinds):
            raise UnavailableGuard("installed D04 baseline grant differs; HOLD")
        store, port = self.__store, self.__content_fence_v2
        recovered = self._recover_d04_baseline_before_read(
            namespace, original_operation_id, policy, admin_policy)
        if type(recovered) is CommitReceipt:
            return recovered
        retry = recovered if type(recovered) is _StageRetry else None
        with store._lock:
            original_metadata, _ = self._v2_graph_stamp(namespace)
            identity = store._db.execute(
                "SELECT conversation_ref FROM graph_first_ingress_identity_v1 "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (original_operation_id,),
            ).fetchone()
        if identity is None:
            raise UnavailableGuard("D04 baseline original ingress is absent; HOLD")
        original_lease, original_capability = self.grant(
            bootstrap, actor=self.__holder, issuer_domain="d11", namespace=namespace,
            domains=("d11",),
            activation_generation=original_metadata.requirements.activation_generation,
            operation_id=original_operation_id)
        try:
            original_authority = AuthorityContext(
                self.__holder, "d11", original_capability, namespace,
                ("activity",), "context", (identity[0],), grant.policy_ref,
                original_metadata.requirements.activation_generation)
            inputs = self.read_first_ingress_baseline_inputs_v1(
                original_authority, original_lease, job_id, original_operation_id)
        finally:
            self.release_authority_lease(bootstrap, original_lease)
        try:
            reading = port.read_ingress_clock(clock_policy)
            now_utc = trusted_upper(reading)
        except Exception as exc:
            raise UnavailableGuard("paired D04 baseline clock unavailable; HOLD") from exc
        deadline = min(math.nextafter(math.fsum((
            now_utc, admin_policy.deadline_after_seconds)), -math.inf),
            grant.valid_until_utc)
        if deadline <= now_utc:
            raise UnavailableGuard("D04 baseline deadline unavailable; HOLD")
        monotonic_deadline = reading.monotonic_after_seconds + (
            deadline - reading.utc_upper_bound_seconds)
        if not math.isfinite(monotonic_deadline):
            raise UnavailableGuard("D04 baseline monotonic deadline differs")
        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
            if (metadata.graph_revision != inputs.graph_revision
                    or epoch.revision != inputs.graph_epoch):
                raise StaleRead("D04 baseline original graph changed")
            db = store._db
            perspectives = db.execute(
                "SELECT token,revision,value FROM graph_atoms WHERE bot=? "
                "AND persona=? AND type_name='d03.self_perspective.v1' AND valid=1",
                namespace.as_tuple,
            ).fetchall()
            matched = []
            for token, revision, encoded in perspectives:
                value = SelfPerspective(**json.loads(encoded))
                event_key = AtomKey.from_token(value.arrival_event_ref)
                event_row = db.execute(
                    "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                    (event_key.token,),
                ).fetchone()
                if (event_row is not None and event_row[2] == 1
                        and json.loads(event_row[1]).get("source_refs")
                        == [inputs.source_ref]):
                    matched.append((token, revision, value, event_key, event_row))
            if len(matched) != 1:
                raise UnavailableGuard("D04 baseline needs one committed self perspective")
            perspective_token, perspective_revision, perspective, event_key, event_row = (
                matched[0])
            perspective_key = AtomKey.from_token(perspective_token)
            origin = db.execute(
                "SELECT h.event_id,o.digest,i.source_ref,i.bundle_digest "
                "FROM graph_history AS h JOIN graph_bundle_operations AS o "
                "ON o.bot=h.event_bot AND o.persona=h.event_persona "
                "AND o.operation_id=h.event_id "
                "JOIN graph_d03_self_projection_issuance_v1 AS i "
                "ON i.bot=h.event_bot AND i.persona=h.event_persona "
                "AND i.operation_id=h.event_id "
                "WHERE h.token=? AND h.revision=?",
                (perspective_token, perspective_revision),
            ).fetchone()
            if (origin is None or origin[1] != origin[3]
                    or origin[2] != inputs.source_ref):
                raise UnavailableGuard("D04 baseline self perspective lacks stage receipt")
            mapping_key = AtomKey.from_token(perspective.identity_mapping_ref)
            keys = (AtomKey.from_token(inputs.source_ref),
                    access_key(*namespace.as_tuple,
                               AtomKey.from_token(inputs.source_ref).owner.subject),
                    event_key, perspective_key, mapping_key)
            atoms = []
            for key in keys:
                row = db.execute(
                    "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                    (key.token,),
                ).fetchone()
                if row is None:
                    raise UnavailableGuard("D04 baseline prerequisite graph atom absent")
                atoms.append(GraphAtom(key, row[0], json.loads(row[1]), bool(row[2])))
            snapshot = GraphSnapshot(tuple(atoms), (epoch,))
            guard_versions = dict(db.execute(
                "SELECT kind,version FROM graph_guard_versions WHERE bot=? "
                "AND persona=? AND ref='current'", namespace.as_tuple,
            ).fetchall())
            authority_epochs = db.execute(
                "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                "WHERE bot=? AND persona=?", namespace.as_tuple,
            ).fetchone() or (0, 0)
        base_operation_id = "d04-baseline-" + canonical_digest({
            "namespace": namespace.as_tuple, "source": inputs.source_ref,
            "event": event_key.token, "perspective": perspective_token,
            "perspective_revision": perspective_revision,
        })[:40]
        if retry is not None and retry.retry_index == 1 and (
                retry.previous_operation_id != base_operation_id):
            raise UnavailableGuard("D04 original perspective changed before retry; HOLD")
        operation_id = (
            d04_baseline_retry_operation_id_v2(
                namespace, inputs.source_ref, event_key.token,
                perspective_token, perspective_revision,
                retry.previous_operation_id, retry.retry_index)
            if retry is not None else base_operation_id)
        activity_id = "d04-baseline-activity-" + canonical_digest({
            "namespace": namespace.as_tuple, "source": inputs.source_ref,
        })[:40]
        lease, capability = self.grant(
            bootstrap, actor="host", issuer_domain="d11", namespace=namespace,
            domains=("d04",),
            activation_generation=metadata.requirements.activation_generation,
            operation_id=operation_id)
        try:
            authority = AuthorityContext(
                "host", "d11", capability, namespace, ("persona", "event"),
                "context", (identity[0],), grant.policy_ref,
                metadata.requirements.activation_generation)
            quote_id = d04_baseline_quote_id(namespace, operation_id)
            input_refs = (inputs.source_ref, event_key.token)
            envelope = CommandEnvelope(
                RUNTIME_SCHEMA,
                OperationIdentity(activity_id, None, "baseline-attempt",
                                  "encoding_baseline", operation_id,
                                  canonical_digest({"input_refs": list(input_refs)})),
                authority,
                VersionGuard(
                    tuple(GraphVersion(atom.key, atom.revision) for atom in atoms),
                    (QueryEpoch(namespace, "all", epoch.revision),),
                    *authority_epochs, store._registry.catalogue_hash,
                    guard_versions["scheme"], guard_versions["operator"],
                    guard_versions["policy"], (), (), (VersionedRef(quote_id, 1),)),
                inputs.qualification, input_refs, grant.lease_id,
                deadline, monotonic_deadline, "character-v1",
                (original_operation_id, origin[0]),
            )
            proposal = provider.propose_encoding_baseline(
                envelope, snapshot, source_refs=(inputs.source_ref,),
                perspective_ref=perspective_token,
                projection_policy_ref=admin_policy.snapshot_ref)
            bundle = DomainBundle(proposal.envelope, (proposal,), (), (), (), (), (), (), ())
            return self._commit_domain_bundle_v2(
                bundle, lease, baseline_issuance=(
                    admin_policy, policy.installation_id, now_utc,
                    inputs.source_ref, event_key.token, job_id, policy,
                    original_operation_id, retry))
        finally:
            self.release_authority_lease(bootstrap, lease)

    def first_ingress_c02_accounting_installed_v1(
        self, *, require_worker_result: bool = True,
    ) -> bool:
        """Whether the mandatory C02 unknown-cost continuation has its ports."""
        return (isinstance(self.__store, ProductionGraphStore)
                and self.__content_fence_v2 is not None
                and (not require_worker_result
                     or self.__worker_result_fact_port is not None)
                and self.__model_terminal_cost_port is not None
                and self.__accounting_maintenance_port is not None
                and callable(getattr(self.__d02_issuer,
                                     "issue_c02_unknown_outcome", None))
                and callable(getattr(self.__d02_issuer,
                                     "original_c02_unknown_outcome", None))
                and self.__d11_issuer is not None)

    def recover_committed_first_ingress_c02_unknown_cost_v1(
        self, bootstrap: object, namespace: NamespaceId, operation_id: str,
        *, _terminal_pinned=None,
    ) -> None:
        """Settle a durable C02 completion without re-reading its model body.

        The Authority terminal authenticates the observation digest. A
        historical read/result digest has no independent post-finish seal, so
        this path never treats it as measured CPU use or body revalidation.
        """
        from .authority_service.v2_model_egress_contract import ModelEgressIntentV1
        from .runtime.c02_cost_settlement import (
            C02CommittedCostProofV1, C02OriginalIntentLookupV1,
        )
        from .runtime.encoding_call_binding import binding_from_json, load_binding
        from .runtime.first_ingress_c02_identity import (
            first_ingress_c02_consumer_operation_id_v1,
        )
        from .runtime.model_cost_settlement import read_original_model_cost
        from .runtime.c02_terminal_job import _PinnedTerminalRead
        from .authority_service.v2_terminal_c02_recovery_contract import (
            OriginalC02ResultKeyV1, from_wire as terminal_from_wire,
        )
        from .runtime.terminal_c02_recovery_candidate_v2 import (
            FrozenTerminalC02CandidateV2,
        )

        self._admin(bootstrap)
        if _terminal_pinned is not None and type(_terminal_pinned) is not _PinnedTerminalRead:
            raise UnavailableGuard("installed pinned C02 terminal fact required; HOLD")
        lookup = self.__original_c02_cost_intent_port
        if (type(namespace) is not NamespaceId or type(operation_id) is not str
                or not operation_id or not callable(lookup)
                or not self.first_ingress_c02_accounting_installed_v1(
                    require_worker_result=False)):
            raise UnavailableGuard("installed committed C02 recovery authorities required")
        store = self.__store
        with store._lock:
            metadata, _ = self._v2_graph_stamp(namespace)
            db = store._db
            row = db.execute(
                "SELECT activity_id,receipt_json FROM graph_bundle_operations "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone()
            if row is None:
                raise UnavailableGuard("committed C02 receipt is absent; HOLD")
            detail = json.loads(row[1]).get("first_ingress_c02")
            event = db.execute(
                "SELECT revisions FROM graph_events WHERE bot=? AND persona=? "
                "AND session=? AND event_id=?",
                namespace.as_tuple + (row[0], operation_id),
            ).fetchone()
            job_writes = (() if event is None else tuple(
                version for version in GraphStore._version_rows(event[0])
                if version.key.type_name == "runtime.job"
                and version.key.owner == Owner(
                    "activity", *namespace.as_tuple, row[0])))
            if type(detail) is not dict or len(job_writes) != 1:
                raise UnavailableGuard("committed C02 job receipt differs; HOLD")
            terminal_seal = None
            if _terminal_pinned is not None:
                archived = db.execute(
                    "SELECT seal_json FROM graph_first_ingress_c02_committed_seals_v2 "
                    "WHERE bot=? AND persona=? AND operation_id=?",
                    namespace.as_tuple + (operation_id,),
                ).fetchone()
                if archived is None or "terminal_read_fact_digest" not in detail:
                    raise UnavailableGuard("committed terminal C02 seal differs; HOLD")
                raw = json.loads(archived[0])
                raw["original_key"] = terminal_from_wire(
                    raw["original_key"], OriginalC02ResultKeyV1)
                terminal_seal = FrozenTerminalC02CandidateV2(**raw)
            job_id = job_writes[0].key.name
            job = db.execute(
                "SELECT operation_id,phase,lease_holder,fence "
                "FROM runtime_jobs WHERE bot_id=? AND persona_id=? "
                "AND activity_id=? AND job_id=?",
                namespace.as_tuple + (row[0], job_id),
            ).fetchone()
            if job is None or job[1:3] != ("completed", None):
                raise UnavailableGuard("committed C02 job receipt differs; HOLD")
            original_id, _, _, worker_fence = job
            acquired = db.execute(
                "SELECT i.acquire_operation_id,i.actor,i.encoding_binding_json,"
                "i.requirements_json,i.request_digest,r.request_digest,r.job_json "
                "FROM graph_job_acquire_intents_v2 AS i "
                "JOIN graph_job_acquire_receipts_v2 AS r "
                "ON r.bot=i.bot AND r.persona=i.persona "
                "AND r.acquire_operation_id=i.acquire_operation_id "
                "WHERE i.bot=? AND i.persona=? AND i.job_id=? "
                "AND i.original_operation_id=?",
                namespace.as_tuple + (job_id, original_id),
            ).fetchall()
            provision_row = self._provision_row(db, namespace)
            if provision_row is None:
                raise UnavailableGuard("C02 original installation is absent; HOLD")
            provision = self._decode_provision_receipt(provision_row)
            installed = self.__content_fence_v2.installation_grant
            if (provision.installation_id != installed.installation_id
                    or provision.authority_id != metadata.requirements.authority_id
                    or provision.authority_namespace !=
                    metadata.requirements.authority_namespace
                    or provision.generation !=
                    metadata.requirements.activation_generation):
                raise UnavailableGuard("C02 original installation differs; HOLD")
            matches = []
            for (acquire_id, actor, binding_json, requirements_json,
                 intent_digest, receipt_digest, original_job_json) in acquired:
                binding = binding_from_json(binding_json)
                frozen = binding.request
                historic = json.loads(requirements_json)
                original_job = PersistentJob(**json.loads(original_job_json))
                derived = first_ingress_c02_consumer_operation_id_v1(
                    namespace=namespace,
                    authority_id=metadata.requirements.authority_id,
                    authority_namespace=metadata.requirements.authority_namespace,
                    installation_id=provision.installation_id, job_id=job_id,
                    acquire_operation_id=acquire_id,
                    original_operation_id=original_id, call_id=binding.call_id,
                    binding_digest=binding.binding_digest,
                    model_request_digest=binding.model_request_digest)
                if derived != operation_id:
                    continue
                current = load_binding(db, namespace, job_id)
                if (binding.namespace != namespace or current != binding
                        or intent_digest != receipt_digest
                        or (original_job.job_id, original_job.operation_id,
                            original_job.activity_id, original_job.phase,
                            original_job.lease_holder, original_job.fence,
                            original_job.cancel_epoch) != (
                                job_id, original_id, row[0], "running",
                                actor, worker_fence, 0)
                        or frozen.get("schema") !=
                        "sylanne.first-ingress-encoding-call.v3"
                        or frozen.get("acquire_operation_id") != acquire_id
                        or frozen.get("original_operation_id") != original_id
                        or frozen.get("worker_fence") != worker_fence
                        or historic.get("graph_incarnation") !=
                        metadata.requirements.graph_incarnation
                        or historic.get("authority_id") !=
                        metadata.requirements.authority_id
                        or historic.get("authority_namespace") !=
                        metadata.requirements.authority_namespace):
                    raise UnavailableGuard("C02 original V3 identity differs; HOLD")
                matches.append((C02OriginalIntentLookupV1(
                    namespace, metadata.requirements.authority_id,
                    metadata.requirements.authority_namespace,
                    provision.installation_id, job_id, original_id, acquire_id,
                    binding.call_id, binding.binding_digest,
                    binding.model_request_digest, operation_id), actor))
            if len(matches) != 1:
                raise UnavailableGuard("C02 original V3 identity is ambiguous; HOLD")
            request, actor = matches[0]
            proof = C02CommittedCostProofV1(
                job_id, original_id, operation_id,
                *(detail.get(key) for key in (
                    "read_request_digest", "read_result_digest",
                    "original_intent_digest", "terminal_receipt_digest",
                    "observation_digest", "result_digest")))
        # Both Authority calls are made outside GraphStore's lock. The lookup
        # port holds the designated observer credential and returns its ledger intent.
        original_intent = lookup(request)
        if (type(original_intent) is not ModelEgressIntentV1
                or (original_intent.authority_id, original_intent.namespace,
                    original_intent.job_id, original_intent.operation_id,
                    original_intent.acquire_operation_id, original_intent.call_id,
                    original_intent.binding_digest, original_intent.request_digest,
                    original_intent.budget_reservation_operation_id,
                    original_intent.subject, original_intent.worker_fence) != (
                        request.authority_id, request.authority_namespace,
                        request.job_id, request.acquire_operation_id,
                        request.acquire_operation_id, request.call_id,
                        request.binding_digest, request.model_request_digest,
                    request.original_operation_id, actor, worker_fence)):
            raise UnavailableGuard("Authority original C02 intent differs; HOLD")
        if proof.original_intent_digest != canonical_digest(asdict(original_intent)):
            raise UnavailableGuard("Authority original C02 intent digest differs; HOLD")
        fact = read_original_model_cost(self.__model_terminal_cost_port, original_intent)
        if (fact.recovery.state != "observed"
                or proof.terminal_receipt_digest != canonical_digest(
                    asdict(fact.receipt))
                or proof.observation_digest != fact.recovery.observation_digest):
            raise UnavailableGuard("Authority original C02 terminal differs; HOLD")
        verified = (self._first_ingress_c02_duplicate_v2(
            namespace, operation_id, original_intent=original_intent,
            pinned_read=_terminal_pinned,
            request=_terminal_pinned.fact.request)
            if terminal_seal is not None else
            self._first_ingress_c02_duplicate_v1(
                namespace, operation_id, original_intent,
                terminal_receipt_digest=proof.terminal_receipt_digest))
        if verified is None:
            raise UnavailableGuard("committed C02 fence receipt is absent; HOLD")
        self._commit_first_ingress_c02_unknown_cost_v1(
            namespace, original_intent, proof, verified,
            terminal=(terminal_seal, _terminal_pinned)
            if terminal_seal is not None else None)

    def recover_committed_first_ingress_c02_unknown_cost_v2_pinned(
        self, bootstrap: object, namespace: NamespaceId, operation_id: str,
        pinned_read,
    ) -> None:
        """Settle the original terminal C02 price from a pinned v2 ACK."""
        self.recover_committed_first_ingress_c02_unknown_cost_v1(
            bootstrap, namespace, operation_id,
            _terminal_pinned=pinned_read)

    def _commit_first_ingress_c02_unknown_cost_v1(
        self, namespace: NamespaceId, original_intent, read, verified_completion,
        *, terminal=None,
    ) -> None:
        """Move completed local C02's entire upper bound to unconfirmed once."""
        from .authority_service.v2_accounting_contract import (
            AccountingMaintenanceGrantV1, AccountingMaintenanceRequestV1,
        )
        from .runtime.c02_cost_settlement import (
            C02CommittedCostProofV1,
            apply_c02_unknown_budget_in_transaction,
            apply_c02_terminal_unknown_budget_in_transaction,
            prepare_c02_unknown_cost_plan,
            prepare_c02_terminal_unknown_cost_plan,
        )
        from .runtime.d11_types import validate_d11_writes
        from .runtime.model_cost_settlement import read_original_model_cost

        if not self.first_ingress_c02_accounting_installed_v1(
                require_worker_result=(type(read) is not C02CommittedCostProofV1
                                       and terminal is None)):
            raise UnavailableGuard("C02 local accounting authority unavailable; HOLD")
        store = self.__store
        port = self.__accounting_maintenance_port
        operation_id = (read.consumer_operation_id
                        if type(read) is C02CommittedCostProofV1 else
                        read.request.consumer_operation_id)
        intent_digest = canonical_digest(asdict(original_intent))
        completion_digest = canonical_digest(asdict(verified_completion))

        def prior_locked(db):
            row = db.execute(
                "SELECT digest,activity_id,receipt_json FROM graph_bundle_operations "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (cost_operation_id,),
            ).fetchone()
            if row is None:
                return False
            data = json.loads(row[2])
            cost_ref = data.get("cost_ref")
            self.__d02_issuer.original_c02_unknown_outcome(db, quote)
            if (data.get("original_operation_id") != operation_id
                    or data.get("original_intent_digest") != intent_digest
                    or data.get("completion_digest") != completion_digest
                    or db.execute(
                        "SELECT 1 FROM graph_events WHERE bot=? AND persona=? "
                        "AND session=? AND event_id=?",
                        namespace.as_tuple + (row[1], cost_operation_id),
                    ).fetchone() is None
                    or db.execute(
                        "SELECT 1 FROM graph_atoms WHERE token=? AND valid=1",
                        (cost_ref,),
                    ).fetchone() is None
                    or db.execute(
                        "SELECT 1 FROM runtime_budget_operations WHERE bot_id=? "
                        "AND persona_id=? AND operation_id=? AND phase='settle'",
                        namespace.as_tuple + (operation_id,),
                    ).fetchone() is None):
                raise UnavailableGuard("C02 cost receipt is incomplete or differs")
            return True

        with store._lock:
            db = store._db
            # The operation ID is stable even if accounting needs a new fence attempt.
            from .runtime.issuers import d06_first_ingress_c02_quote_id
            quote = self.__d02_issuer.original_signed_quote(
                db, d06_first_ingress_c02_quote_id(namespace, operation_id), 1)
            cost_operation_id = "c02-cost-" + canonical_digest({
                "namespace": list(namespace.as_tuple), "operation_id": operation_id,
            })[:48]
            committed = prior_locked(db)
            metadata, _ = self._v2_graph_stamp(namespace)
            attempt = db.execute(
                "SELECT intent_digest,completion_digest,attempt_id,anchor_json,state "
                "FROM graph_c02_cost_attempts_v1 WHERE bot=? AND persona=? "
                "AND operation_id=?", namespace.as_tuple + (operation_id,),
            ).fetchone()
        if committed:
            if (attempt is None or attempt[:2] != (
                    intent_digest, completion_digest) or attempt[4] != "committed"):
                raise UnavailableGuard("C02 cost lacks its original fence attempt")
            from .runtime.restore_anchor import RestoreAnchor
            port.recover_finish(AccountingMaintenanceRequestV1(
                attempt[2], original_intent, RestoreAnchor(**json.loads(attempt[3]))))
            return
        if attempt is not None and attempt[4] == "open":
            if attempt[:2] != (intent_digest, completion_digest):
                raise EventConflict("C02 accounting identity reused with different proof")
            from .runtime.restore_anchor import RestoreAnchor
            old = AccountingMaintenanceRequestV1(
                attempt[2], original_intent, RestoreAnchor(**json.loads(attempt[3])))
            try:
                port.recover_finish(old)
            except Exception:
                grant = port.begin(old)
                port.finish(old, grant)
            with store._lock:
                if prior_locked(store._db):
                    raise UnavailableGuard("C02 cost committed during recovery; retry")
                store._db.execute(
                    "UPDATE graph_c02_cost_attempts_v1 SET state='closed' "
                    "WHERE bot=? AND persona=? AND operation_id=? AND attempt_id=? "
                    "AND state='open'", namespace.as_tuple + (operation_id, attempt[2]))
        target = metadata.requirements
        if (original_intent.authority_id != target.authority_id
                or original_intent.namespace != target.authority_namespace):
            raise UnavailableGuard("C02 accounting Authority differs")
        # Network reads and Authority begin/finish stay outside GraphStore's lock.
        original_model_fact = read_original_model_cost(
            self.__model_terminal_cost_port, original_intent)
        if original_model_fact.recovery.state != "observed":
            raise UnavailableGuard("C02 original model terminal is unavailable")
        if (type(read) is C02CommittedCostProofV1
                and (read.original_intent_digest != intent_digest
                     or read.terminal_receipt_digest != canonical_digest(
                         asdict(original_model_fact.receipt)))):
            raise UnavailableGuard("C02 original terminal proof differs")
        anchor = self.__content_fence_v2.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._accounting_anchor_covers(target, anchor):
            raise UnavailableGuard("C02 accounting anchor differs")
        attempt_id = "c02-cost-fence-" + secrets.token_hex(24)
        request = AccountingMaintenanceRequestV1(attempt_id, original_intent, anchor)
        with store._lock:
            db = store._db
            db.execute("BEGIN IMMEDIATE")
            try:
                if prior_locked(db) or self._v2_graph_stamp(namespace)[0] != metadata:
                    raise StaleRead("C02 cost graph changed before fence")
                db.execute(
                    "INSERT INTO graph_c02_cost_attempts_v1"
                    "(bot,persona,operation_id,intent_digest,completion_digest,"
                    "attempt_id,anchor_json,state) VALUES(?,?,?,?,?,?,?,'open') "
                    "ON CONFLICT(bot,persona,operation_id) DO UPDATE SET "
                    "intent_digest=excluded.intent_digest,"
                    "completion_digest=excluded.completion_digest,"
                    "attempt_id=excluded.attempt_id,anchor_json=excluded.anchor_json,"
                    "state='open'",
                    namespace.as_tuple + (operation_id, intent_digest,
                    completion_digest, attempt_id, canonical_json(asdict(anchor))),
                )
                db.commit()
            except BaseException:
                db.rollback()
                raise
        grant = port.begin(request)
        terminal_digest = canonical_digest(asdict(original_model_fact.receipt))
        if (type(grant) is not AccountingMaintenanceGrantV1
                or grant.call_id != original_intent.call_id
                or grant.admission_id != original_model_fact.admission.admission_id
                or grant.observation_digest != original_model_fact.recovery.observation_digest
                or grant.terminal_receipt_digest != terminal_digest
                or grant.permit.operation_id != attempt_id
                or grant.permit.pinned_anchor != anchor):
            raise UnavailableGuard("C02 accounting grant differs")
        port.validate(request, grant)
        try:
            with store._lock:
                db = store._db
                db.execute("BEGIN IMMEDIATE")
                try:
                    current, epoch = self._v2_graph_stamp(namespace)
                    if (current != metadata or prior_locked(db)
                            or not self._accounting_anchor_covers(
                                current.requirements, anchor)):
                        raise StaleRead("C02 cost graph changed")
                    if terminal is None:
                        plan = prepare_c02_unknown_cost_plan(
                            db, self.__d02_issuer, namespace, original_intent,
                            read, verified_completion)
                    else:
                        plan = prepare_c02_terminal_unknown_cost_plan(
                            db, self.__d02_issuer, namespace, original_intent,
                            terminal[0], terminal[1], verified_completion)
                    if plan.bundle_operation_id != cost_operation_id or plan.quote != quote:
                        raise EventConflict("C02 accounting plan differs")
                    if terminal is None:
                        application = apply_c02_unknown_budget_in_transaction(
                            db, self.__d02_issuer, plan, original_intent,
                            read, verified_completion)
                    else:
                        application = apply_c02_terminal_unknown_budget_in_transaction(
                            db, self.__d02_issuer, plan, namespace,
                            original_intent, terminal[0], terminal[1],
                            verified_completion)
                    write = application.cost_write
                    if not validate_d11_writes(
                            (write,), namespace, operation_id=cost_operation_id,
                            activity_id=quote.activity_id, effect_id=quote.effect_id):
                        raise UnavailableGuard("C02 cost graph write is invalid")
                    reconcile_runtime_write(db, write)
                    bundle_digest = canonical_digest({
                        "operation_id": cost_operation_id,
                        "write": asdict(write),
                        "completion_digest": completion_digest,
                    })
                    event = Event(Scope(*namespace.as_tuple, quote.activity_id),
                                  cost_operation_id, time.time(), "domain_bundle",
                                  {"bundle_digest": bundle_digest})
                    candidate = GraphCandidate(
                        event, (GraphVersion(write.key, 0),), (write,), (epoch,))
                    graph_receipt = GraphStore._graph_commit_in_transaction(
                        store, candidate, _capability=self.__graph_capability)
                    if graph_receipt.status != "committed":
                        raise EventConflict("C02 cost graph event already exists")
                    replacement = replace(
                        current.requirements,
                        deletion_seq=anchor.deletion_seq,
                        deletion_digest=anchor.deletion_digest,
                        execution_seq=anchor.execution_seq,
                        execution_digest=anchor.execution_digest,
                        revocation_epoch=anchor.revocation_epoch)
                    store.cas_graph_recovery_metadata(
                        current, replacement, _capability=self.__graph_capability)
                    seq_row = db.execute(
                        "SELECT last_seq FROM graph_bundle_sequence WHERE bot=? "
                        "AND persona=?", namespace.as_tuple).fetchone()
                    seq = (seq_row[0] if seq_row else 0) + 1
                    db.execute(
                        "INSERT INTO graph_bundle_sequence(bot,persona,last_seq) "
                        "VALUES(?,?,?) ON CONFLICT(bot,persona) DO UPDATE SET "
                        "last_seq=excluded.last_seq", namespace.as_tuple + (seq,))
                    db.execute(
                        "INSERT INTO graph_bundle_operations"
                        "(bot,persona,operation_id,digest,activity_id,effect_id,"
                        "commit_seq,receipt_json) VALUES(?,?,?,?,?,?,?,?)",
                        namespace.as_tuple + (cost_operation_id, bundle_digest,
                        quote.activity_id, quote.effect_id, seq, canonical_json({
                            "original_operation_id": operation_id,
                            "original_intent_digest": intent_digest,
                            "completion_digest": completion_digest,
                            "cost_ref": write.key.token,
                            "budget_receipt_digest": canonical_digest(
                                asdict(application.receipt)),
                        })),
                    )
                    db.execute(
                        "UPDATE graph_c02_cost_attempts_v1 SET state='committed' "
                        "WHERE bot=? AND persona=? AND operation_id=? "
                        "AND attempt_id=?", namespace.as_tuple +
                        (operation_id, attempt_id))
                    db.commit()
                except BaseException:
                    db.rollback()
                    raise
        except BaseException:
            with store._lock:
                committed = prior_locked(store._db)
            if committed:
                port.recover_finish(request)
                return
            port.finish(request, grant)
            with store._lock:
                store._db.execute(
                    "UPDATE graph_c02_cost_attempts_v1 SET state='closed' "
                    "WHERE bot=? AND persona=? AND operation_id=? "
                    "AND attempt_id=? AND state='open'",
                    namespace.as_tuple + (operation_id, attempt_id))
            raise
        port.finish(request, grant)

    @staticmethod
    def _terminal_c02_read_attempt_id_v2(request, original_key, bundle_digest):
        return "terminal-c02-read-" + canonical_digest({
            "schema": "sylanne.first-ingress-c02-terminal-attempt.v2",
            "original_read_attempt_id": request.read_attempt_id,
            "original_key": asdict(original_key),
            "consumer_operation_id": request.consumer_operation_id,
            "bundle_digest": bundle_digest,
        })[:48]

    def read_pending_first_ingress_c02_terminal_request_v2(
        self, bootstrap: object, namespace: NamespaceId,
        consumer_operation_id: str,
    ):
        """Worker-owned read of one durable, original terminal read identity."""
        from .authority_service.v2_terminal_c02_recovery_contract import (
            OriginalC02ResultKeyV1, TerminalRecoveryReadRequestV1,
            from_wire as terminal_from_wire,
        )
        from .authority_service.v2_worker_model_result_contract import (
            WorkerModelResultReadRequestV1, from_wire as worker_from_wire,
        )
        from .runtime.terminal_c02_recovery_candidate_v2 import (
            FrozenTerminalC02CandidateV2,
            inspect_frozen_terminal_c02_candidate_v2,
        )

        self._admin(bootstrap)
        if (type(namespace) is not NamespaceId
                or type(consumer_operation_id) is not str
                or not consumer_operation_id
                or not self.first_ingress_c02_accounting_installed_v1(
                    require_worker_result=False)):
            raise UnavailableGuard("installed terminal C02 preflight required; HOLD")
        with self.__store._lock:
            db = self.__store._db
            metadata, epoch = self._v2_graph_stamp(namespace)
            intent = db.execute(
                "SELECT digest,fence_attempt_id,graph_revision,graph_epoch "
                "FROM graph_bundle_intents_v2 WHERE bot=? AND persona=? "
                "AND operation_id=?",
                namespace.as_tuple + (consumer_operation_id,),
            ).fetchone()
            candidate = db.execute(
                "SELECT schema,bundle_digest,fence_attempt_id,bundle_json,"
                "evidence_json,quote_json,seal_json FROM "
                "graph_first_ingress_c02_candidates_v2 WHERE bot=? "
                "AND persona=? AND operation_id=?",
                namespace.as_tuple + (consumer_operation_id,),
            ).fetchone()
            committed = db.execute(
                "SELECT 1 FROM graph_bundle_operations WHERE bot=? "
                "AND persona=? AND operation_id=?",
                namespace.as_tuple + (consumer_operation_id,),
            ).fetchone()
            rejected = db.execute(
                "SELECT 1 FROM graph_bundle_rejections_v2 WHERE bot=? "
                "AND persona=? AND operation_id=?",
                namespace.as_tuple + (consumer_operation_id,),
            ).fetchone()
        if committed is not None:
            return self._first_ingress_c02_duplicate_v2(
                namespace, consumer_operation_id)
        if (intent is None or candidate is None
                or rejected is not None
                or candidate[0] != "sylanne.first-ingress-c02-candidate.v2"
                or candidate[1:3] != intent[:2]
                or intent[2:] != (metadata.graph_revision, epoch.revision)):
            raise UnavailableGuard("terminal C02 first seal is unavailable; HOLD")
        try:
            raw = json.loads(candidate[6])
            raw["original_key"] = terminal_from_wire(
                raw["original_key"], OriginalC02ResultKeyV1)
            seal = FrozenTerminalC02CandidateV2(**raw)
            inspection = inspect_frozen_terminal_c02_candidate_v2(
                namespace=namespace, operation_id=consumer_operation_id,
                seal=seal, bundle_json=candidate[3], quote_json=candidate[5])
            evidence = json.loads(candidate[4])
            worker_request = worker_from_wire(
                evidence["read_request"], WorkerModelResultReadRequestV1)
            attempt_id = self._terminal_c02_read_attempt_id_v2(
                worker_request, seal.original_key, inspection.bundle.digest)
        except (TypeError, ValueError, KeyError) as exc:
            raise UnavailableGuard("terminal C02 durable attempt is invalid; HOLD") from exc
        if (canonical_json(evidence) != candidate[4]
                or canonical_serialize(asdict(seal)) != candidate[6]
                or inspection.bundle.digest != intent[0]
                or evidence.get("terminal_read_attempt_id") != attempt_id
                or worker_request.consumer_operation_id != consumer_operation_id
                or worker_request.namespace != namespace):
            raise UnavailableGuard("terminal C02 durable attempt differs; HOLD")
        return TerminalRecoveryReadRequestV1(
            seal.original_key, consumer_operation_id, attempt_id)

    def read_committed_first_ingress_c02_terminal_request_v2(
        self, bootstrap: object, namespace: NamespaceId,
        consumer_operation_id: str,
    ):
        """Return the original finished terminal attempt, or False for legacy cost."""
        from .authority_service.v2_terminal_c02_recovery_contract import (
            OriginalC02ResultKeyV1, TerminalRecoveryReadRequestV1,
            from_wire as terminal_from_wire,
        )
        from .authority_service.v2_worker_model_result_contract import (
            WorkerModelResultReadRequestV1, from_wire as worker_from_wire,
        )
        from .runtime.terminal_c02_recovery_candidate_v2 import (
            FrozenTerminalC02CandidateV2,
        )

        self._admin(bootstrap)
        if (type(namespace) is not NamespaceId
                or type(consumer_operation_id) is not str
                or not consumer_operation_id):
            raise UnavailableGuard("committed C02 identity required")
        with self.__store._lock:
            db = self.__store._db
            row = db.execute(
                "SELECT receipt_json FROM graph_bundle_operations WHERE bot=? "
                "AND persona=? AND operation_id=?",
                namespace.as_tuple + (consumer_operation_id,),
            ).fetchone()
            if row is None:
                raise UnavailableGuard("committed C02 receipt absent; HOLD")
            detail = json.loads(row[0]).get("first_ingress_c02")
            if type(detail) is not dict:
                raise UnavailableGuard("committed C02 identity differs; HOLD")
            if "terminal_read_fact_digest" not in detail:
                return False
            archive = db.execute(
                "SELECT evidence_json,seal_json FROM "
                "graph_first_ingress_c02_committed_seals_v2 WHERE bot=? "
                "AND persona=? AND operation_id=?",
                namespace.as_tuple + (consumer_operation_id,),
            ).fetchone()
        if archive is None:
            raise UnavailableGuard("committed C02 terminal seal absent; HOLD")
        try:
            evidence = json.loads(archive[0])
            raw = json.loads(archive[1])
            raw["original_key"] = terminal_from_wire(
                raw["original_key"], OriginalC02ResultKeyV1)
            seal = FrozenTerminalC02CandidateV2(**raw)
            worker_request = worker_from_wire(
                evidence["read_request"], WorkerModelResultReadRequestV1)
            request = TerminalRecoveryReadRequestV1(
                seal.original_key, consumer_operation_id,
                self._terminal_c02_read_attempt_id_v2(
                    worker_request, seal.original_key, seal.bundle_digest))
        except (TypeError, ValueError, KeyError) as exc:
            raise UnavailableGuard("committed C02 terminal attempt invalid") from exc
        if evidence.get("terminal_read_attempt_id") != request.read_attempt_id:
            raise UnavailableGuard("committed C02 terminal attempt differs")
        self._first_ingress_c02_duplicate_v2(
            namespace, consumer_operation_id, request=request)
        return request

    def claim_pending_first_ingress_c02_terminal_read_v2(
        self, bootstrap: object, namespace: NamespaceId,
        consumer_operation_id: str, request,
    ) -> bool:
        """Durably mark the only permitted terminal read before any body RPC."""
        expected = self.read_pending_first_ingress_c02_terminal_request_v2(
            bootstrap, namespace, consumer_operation_id)
        if request != expected:
            raise UnavailableGuard("terminal C02 read attempt identity differs; HOLD")
        with self.__store._lock:
            db = self.__store._db
            db.execute("BEGIN IMMEDIATE")
            try:
                if self.read_pending_first_ingress_c02_terminal_request_v2(
                        bootstrap, namespace, consumer_operation_id) != expected:
                    raise UnavailableGuard("terminal C02 first seal changed before read")
                db.execute("""CREATE TABLE IF NOT EXISTS
                    graph_first_ingress_c02_terminal_reads_v2 (
                    bot TEXT NOT NULL, persona TEXT NOT NULL,
                    operation_id TEXT NOT NULL, read_attempt_id TEXT NOT NULL,
                    request_digest TEXT NOT NULL,
                    PRIMARY KEY(bot,persona,operation_id),
                    UNIQUE(read_attempt_id))""")
                inserted = db.execute(
                    "INSERT OR IGNORE INTO graph_first_ingress_c02_terminal_reads_v2 "
                    "(bot,persona,operation_id,read_attempt_id,request_digest) "
                    "VALUES(?,?,?,?,?)",
                    namespace.as_tuple + (consumer_operation_id,
                                          expected.read_attempt_id, expected.digest),
                )
                row = db.execute(
                    "SELECT read_attempt_id,request_digest FROM "
                    "graph_first_ingress_c02_terminal_reads_v2 WHERE bot=? "
                    "AND persona=? AND operation_id=?",
                    namespace.as_tuple + (consumer_operation_id,),
                ).fetchone()
                if row != (expected.read_attempt_id, expected.digest):
                    raise UnavailableGuard("terminal C02 read claim differs; HOLD")
                db.execute("COMMIT")
                return inserted.rowcount == 1
            except BaseException:
                db.execute("ROLLBACK")
                raise

    def recover_pending_first_ingress_c02_v2_pinned(
        self, bootstrap: object, namespace: NamespaceId,
        consumer_operation_id: str, installation_policy, admin_policy,
        clock_policy, pinned_query, pinned_read,
    ) -> CommitReceipt:
        """Commit one first-sealed result after its original worker lease expires."""
        from datetime import datetime

        from .authority_service.v2_terminal_c02_recovery_contract import (
            OriginalC02ResultKeyV1, from_wire as terminal_from_wire,
        )
        from .authority_service.v2_worker_model_result_contract import (
            WorkerModelResultReadRequestV1, from_wire as worker_from_wire,
        )
        from .host.authority_profile import (
            AdminD06FirstIngressC02Policy, AdminIngressClockPolicy,
        )
        from .host.terminal_c02_recovery_query import PinnedTerminalC02RecoveryQueryV1
        from .installation_policy import AdminInstallationPolicy
        from .runtime.c02_terminal_job import (
            OriginalC02JobLeaseV1, _PinnedTerminalRead,
        )
        from .runtime.encoding_call_binding import load_binding
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.terminal_c02_recovery_candidate_v2 import (
            FrozenTerminalC02CandidateV2,
            inspect_frozen_terminal_c02_candidate_v2,
            recovery_fact_matches_frozen_v2,
        )

        self._admin(bootstrap)
        if (type(namespace) is not NamespaceId
                or type(consumer_operation_id) is not str or not consumer_operation_id
                or type(installation_policy) is not AdminInstallationPolicy
                or type(admin_policy) is not AdminD06FirstIngressC02Policy
                or type(clock_policy) is not AdminIngressClockPolicy
                or type(pinned_query) is not PinnedTerminalC02RecoveryQueryV1
                or type(pinned_read) is not _PinnedTerminalRead
                or installation_policy.namespace != namespace
                or not self.first_ingress_c02_accounting_installed_v1(
                    require_worker_result=False)):
            raise UnavailableGuard("installed terminal C02 authorities required; HOLD")
        try:
            clock_reading = self.__content_fence_v2.read_ingress_clock(clock_policy)
            now = trusted_upper(clock_reading)
        except Exception as exc:
            raise UnavailableGuard("paired terminal C02 clock unavailable; HOLD") from exc
        with self.__store._lock:
            db = self.__store._db
            metadata, epoch = self._v2_graph_stamp(namespace)
            intent = db.execute(
                "SELECT digest,fence_attempt_id,requirements_json,anchor_json,"
                "graph_revision,graph_epoch FROM graph_bundle_intents_v2 "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (consumer_operation_id,),
            ).fetchone()
            candidate = db.execute(
                "SELECT schema,bundle_digest,fence_attempt_id,bundle_json,"
                "evidence_json,quote_json,seal_json FROM "
                "graph_first_ingress_c02_candidates_v2 WHERE bot=? AND persona=? "
                "AND operation_id=?", namespace.as_tuple + (consumer_operation_id,),
            ).fetchone()
            committed = db.execute(
                "SELECT 1 FROM graph_bundle_operations WHERE bot=? AND persona=? "
                "AND operation_id=?", namespace.as_tuple + (consumer_operation_id,),
            ).fetchone()
            rejected = db.execute(
                "SELECT 1 FROM graph_bundle_rejections_v2 WHERE bot=? AND persona=? "
                "AND operation_id=?", namespace.as_tuple + (consumer_operation_id,),
            ).fetchone()
        if committed is not None:
            raise UnavailableGuard("C02 is already committed; use committed recovery")
        if (intent is None or candidate is None or rejected is not None
                or candidate[0] != "sylanne.first-ingress-c02-candidate.v2"
                or candidate[1:3] != intent[:2]
                or (intent[4], intent[5]) !=
                   (metadata.graph_revision, epoch.revision)):
            raise UnavailableGuard("terminal C02 candidate or graph stamp differs; HOLD")
        try:
            raw_seal = json.loads(candidate[6])
            raw_seal["original_key"] = terminal_from_wire(
                raw_seal["original_key"], OriginalC02ResultKeyV1)
            seal = FrozenTerminalC02CandidateV2(**raw_seal)
            inspection = inspect_frozen_terminal_c02_candidate_v2(
                namespace=namespace, operation_id=consumer_operation_id,
                seal=seal, bundle_json=candidate[3], quote_json=candidate[5])
            evidence = json.loads(candidate[4])
            request = worker_from_wire(
                evidence["read_request"], WorkerModelResultReadRequestV1)
        except (TypeError, ValueError, KeyError) as exc:
            raise UnavailableGuard("terminal C02 frozen bytes differ; HOLD") from exc
        bundle = inspection.bundle
        key = seal.original_key
        admin_digest = canonical_digest({
            "deadline_after_seconds": admin_policy.deadline_after_seconds,
            "quote_ceiling": dict(admin_policy.quote_ceiling),
            "snapshot_ref": admin_policy.snapshot_ref,
            "resource_ref": admin_policy.resource_ref,
        })
        local_deadline = (clock_reading.monotonic_after_seconds
                          + seal.business_deadline_utc
                          - clock_reading.utc_upper_bound_seconds)
        evidence_keys = {
            "schema", "read_request", "read_result_digest",
            "original_intent_digest", "terminal_receipt_digest",
            "observation_digest", "result_payload_digest",
            "admin_policy_digest", "installation_id", "manifest_digest",
            "source_ref", "encoding_baseline_ref", "call_id",
            "model_request_digest", "authority_operation_id", "binding_digest",
            "terminal_read_attempt_id",
        }
        if (type(evidence) is not dict or set(evidence) != evidence_keys
                or canonical_json(evidence) != candidate[4]
                or canonical_serialize(asdict(seal)) != candidate[6]
                or bundle.digest != intent[0]
                or domain_bundle_write_attempt_id_v1(
                    namespace, consumer_operation_id, bundle.digest) != intent[1]
                or evidence.get("schema") != candidate[0]
                or evidence.get("installation_id") != installation_policy.installation_id
                or evidence.get("manifest_digest") != installation_policy.manifest_digest
                or evidence.get("admin_policy_digest") != admin_digest
                or request.namespace != namespace
                or request.consumer_operation_id != consumer_operation_id
                or (request.authority_id, request.authority_namespace,
                    request.installation_id, request.job_id,
                    request.original_operation_id, request.acquire_operation_id,
                    request.call_id, request.binding_digest,
                    request.model_request_digest) !=
                   (key.authority_id, key.authority_namespace,
                    key.installation_id, key.job_id, key.original_operation_id,
                    key.acquire_operation_id, key.call_id, key.binding_digest,
                    key.model_request_digest)
                or evidence.get("original_intent_digest") != key.original_intent_digest
                or evidence.get("observation_digest") != key.observation_digest
                or evidence.get("terminal_receipt_digest") != key.terminal_receipt_digest
                or evidence.get("call_id") != key.call_id
                or evidence.get("model_request_digest") != key.model_request_digest
                or evidence.get("authority_operation_id") != key.acquire_operation_id
                or evidence.get("binding_digest") != key.binding_digest
                or evidence.get("terminal_read_attempt_id") !=
                   self._terminal_c02_read_attempt_id_v2(
                       request, key, bundle.digest)
                or pinned_query.request != pinned_read.fact.request
                or pinned_query.request.original_key != key
                or pinned_query.request.consumer_operation_id != consumer_operation_id
                or not seal.original_worker_lease_expires_utc <= now
                   < seal.business_deadline_utc
                or not math.isfinite(local_deadline)
                or time.monotonic() >= local_deadline):
            raise UnavailableGuard("terminal C02 frozen identity or deadline differs; HOLD")
        with self.__store._lock:
            db = self.__store._db
            if db.execute(
                    "SELECT 1 FROM sqlite_master WHERE type='table' "
                    "AND name='graph_first_ingress_c02_terminal_reads_v2'",
            ).fetchone() is None:
                raise UnavailableGuard("terminal C02 original read was never claimed; HOLD")
            claimed = db.execute(
                "SELECT read_attempt_id,request_digest FROM "
                "graph_first_ingress_c02_terminal_reads_v2 WHERE bot=? "
                "AND persona=? AND operation_id=?",
                namespace.as_tuple + (consumer_operation_id,),
            ).fetchone()
        if claimed != (pinned_query.request.read_attempt_id,
                       pinned_query.request.digest):
            raise UnavailableGuard("terminal C02 original read claim differs; HOLD")
        if not recovery_fact_matches_frozen_v2(
                seal=seal, fact=pinned_read.fact, trusted_now_utc=now):
            raise UnavailableGuard("terminal C02 pinned read differs; HOLD")
        with self.__store._lock:
            db = self.__store._db
            binding = load_binding(db, namespace, key.job_id)
            job = get_job(db, key.job_id)
            source_row = db.execute(
                "SELECT valid FROM graph_atoms WHERE token=?",
                (source_key(*namespace.as_tuple, evidence["source_ref"]).token,),
            ).fetchone()
            access_row = db.execute(
                "SELECT valid FROM graph_atoms WHERE token=?",
                (access_key(*namespace.as_tuple, evidence["source_ref"]).token,),
            ).fetchone()
        if (binding is None or binding.source_id != evidence["source_ref"]
                or (job.phase, job.lease_holder, job.cancel_epoch, job.fence) != (
                    "running", bundle.envelope.authority.actor, 0,
                    bundle.envelope.authority.worker_fence)
                or datetime.fromisoformat(job.lease_expires_utc.replace(
                    "Z", "+00:00")).timestamp() !=
                   seal.original_worker_lease_expires_utc
                or source_row != (1,) or access_row != (1,)):
            raise UnavailableGuard("terminal C02 job or source differs; HOLD")
        original = OriginalC02JobLeaseV1(
            key.job_id, key.original_operation_id, key.acquire_operation_id,
            job.lease_holder, job.fence, job.cancel_epoch, job.lease_expires_utc)
        lease, capability = self.grant(
            bootstrap, actor=bundle.envelope.authority.actor,
            issuer_domain="d06", namespace=namespace, domains=("d06", "d11"),
            activation_generation=bundle.envelope.authority.activation_generation,
            operation_id=consumer_operation_id)
        try:
            if capability != bundle.envelope.authority.capability_ref:
                raise UnavailableGuard("terminal C02 process authority differs; HOLD")
            witness = _C02TerminalRecovery(
                seal, evidence, pinned_read, original, now, clock_reading,
                local_deadline, candidate[:5], candidate[3], candidate[5])
            return self._commit_domain_bundle_v2(
                bundle, lease, c02_terminal_recovery=witness)
        finally:
            self.release_authority_lease(bootstrap, lease)

    def recover_pending_first_ingress_c02_v1(
        self, bootstrap: object, namespace: NamespaceId,
        consumer_operation_id: str, installation_policy,
        admin_policy, clock_policy,
    ) -> CommitReceipt:
        """Resume one sealed C02 candidate without reopening its model result."""
        from datetime import datetime

        from .authority_service.v2_worker_model_result_contract import (
            WorkerModelResultReadRequestV1, from_wire as worker_read_from_wire,
        )
        from .host.authority_profile import (
            AdminD06FirstIngressC02Policy, AdminIngressClockPolicy,
        )
        from .installation_policy import AdminInstallationPolicy
        from .runtime.c02_bundle_codec import (
            c02_bundle_from_wire, c02_bundle_to_wire,
        )
        from .runtime.encoding_call_binding import load_binding
        from .runtime.first_ingress_v2 import trusted_upper

        self._admin(bootstrap)
        if (type(namespace) is not NamespaceId
                or type(consumer_operation_id) is not str
                or not consumer_operation_id
                or type(installation_policy) is not AdminInstallationPolicy
                or type(admin_policy) is not AdminD06FirstIngressC02Policy
                or type(clock_policy) is not AdminIngressClockPolicy
                or installation_policy.namespace != namespace
                or not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or self.__worker_result_fact_port is None
                or self.__d11_issuer is None
                or not self.first_ingress_c02_accounting_installed_v1()):
            raise UnavailableGuard("installed pending C02 authorities required; HOLD")
        try:
            clock_reading = self.__content_fence_v2.read_ingress_clock(
                clock_policy)
            now = trusted_upper(clock_reading)
        except Exception as exc:
            raise UnavailableGuard("paired pending C02 clock unavailable; HOLD") from exc
        with self.__store._lock:
            db = self.__store._db
            metadata, epoch = self._v2_graph_stamp(namespace)
            intent = db.execute(
                "SELECT digest,fence_attempt_id,requirements_json,anchor_json,"
                "graph_revision,graph_epoch FROM graph_bundle_intents_v2 "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (consumer_operation_id,),
            ).fetchone()
            candidate = db.execute(
                "SELECT schema,bundle_digest,fence_attempt_id,bundle_json,"
                "evidence_json FROM graph_first_ingress_c02_candidates_v1 "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (consumer_operation_id,),
            ).fetchone()
            committed = db.execute(
                "SELECT 1 FROM graph_bundle_operations WHERE bot=? AND persona=? "
                "AND operation_id=?",
                namespace.as_tuple + (consumer_operation_id,),
            ).fetchone()
            rejected = db.execute(
                "SELECT 1 FROM graph_bundle_rejections_v2 WHERE bot=? AND persona=? "
                "AND operation_id=?",
                namespace.as_tuple + (consumer_operation_id,),
            ).fetchone()
        if committed is not None:
            raise UnavailableGuard("C02 is already committed; use committed recovery")
        if (intent is None or candidate is None or rejected is not None
                or candidate[0] != "sylanne.first-ingress-c02-candidate.v1"
                or candidate[1:3] != intent[:2]
                or (intent[4], intent[5]) !=
                   (metadata.graph_revision, epoch.revision)):
            raise UnavailableGuard("pending C02 candidate or graph stamp differs; HOLD")
        try:
            bundle = c02_bundle_from_wire(candidate[3])
            evidence = json.loads(candidate[4])
            request = worker_read_from_wire(
                evidence["read_request"], WorkerModelResultReadRequestV1)
        except (KeyError, TypeError, ValueError) as exc:
            raise UnavailableGuard("pending C02 candidate wire differs; HOLD") from exc
        evidence_keys = {
            "schema", "read_request", "read_result_digest",
            "original_intent_digest", "terminal_receipt_digest",
            "observation_digest", "result_payload_digest",
            "admin_policy_digest", "installation_id", "manifest_digest",
            "source_ref", "encoding_baseline_ref", "call_id",
            "model_request_digest", "authority_operation_id", "binding_digest",
        }
        admin_digest = canonical_digest({
            "deadline_after_seconds": admin_policy.deadline_after_seconds,
            "quote_ceiling": dict(admin_policy.quote_ceiling),
            "snapshot_ref": admin_policy.snapshot_ref,
            "resource_ref": admin_policy.resource_ref,
        })
        envelope = bundle.envelope
        local_monotonic_deadline = (
            clock_reading.monotonic_after_seconds
            + (envelope.deadline_utc - clock_reading.utc_upper_bound_seconds))
        if (type(evidence) is not dict or set(evidence) != evidence_keys
                or canonical_json(evidence) != candidate[4]
                or c02_bundle_to_wire(bundle) != candidate[3]
                or bundle.digest != intent[0]
                or domain_bundle_write_attempt_id_v1(
                    namespace, consumer_operation_id, bundle.digest) != intent[1]
                or envelope.identity.phase != "first_ingress_c02"
                or envelope.identity.operation_id != consumer_operation_id
                or envelope.authority.namespace != namespace
                or request.namespace != namespace
                or request.consumer_operation_id != consumer_operation_id
                or evidence["schema"] != candidate[0]
                or evidence["installation_id"] != installation_policy.installation_id
                or evidence["manifest_digest"] != installation_policy.manifest_digest
                or evidence["admin_policy_digest"] != admin_digest
                or evidence["call_id"] != request.call_id
                or evidence["model_request_digest"] != request.model_request_digest
                or evidence["authority_operation_id"] != request.acquire_operation_id
                or evidence["binding_digest"] != request.binding_digest
                or not now < envelope.deadline_utc
                or not math.isfinite(local_monotonic_deadline)
                or time.monotonic() >= local_monotonic_deadline):
            raise UnavailableGuard("pending C02 frozen identity or deadline differs; HOLD")
        with self.__store._lock:
            db = self.__store._db
            binding = load_binding(db, namespace, request.job_id)
            job = get_job(db, request.job_id)
            source_row = db.execute(
                "SELECT valid FROM graph_atoms WHERE token=?",
                (source_key(*namespace.as_tuple,
                            evidence["source_ref"]).token,),
            ).fetchone()
            access_row = db.execute(
                "SELECT valid FROM graph_atoms WHERE token=?",
                (access_key(*namespace.as_tuple,
                            evidence["source_ref"]).token,),
            ).fetchone()
        if (binding is None or binding.source_id != evidence["source_ref"]
                or (job.phase, job.lease_holder, job.cancel_epoch, job.fence) != (
                    "running", envelope.authority.actor, 0,
                    envelope.authority.worker_fence)
                or datetime.fromisoformat(
                    job.lease_expires_utc.replace("Z", "+00:00")).timestamp() <= now
                or source_row != (1,) or access_row != (1,)):
            raise UnavailableGuard("pending C02 worker or source is unavailable; HOLD")
        lease, capability = self.grant(
            bootstrap, actor=envelope.authority.actor, issuer_domain="d06",
            namespace=namespace, domains=("d06", "d11"),
            activation_generation=envelope.authority.activation_generation,
            operation_id=consumer_operation_id)
        try:
            if capability != envelope.authority.capability_ref:
                raise UnavailableGuard("pending C02 process authority differs; HOLD")
            witness = _C02PendingRecovery(
                request, evidence, installation_policy, admin_policy, now,
                clock_reading, local_monotonic_deadline,
                candidate)
            return self._commit_domain_bundle_v2(
                bundle, lease, c02_recovery=witness)
        finally:
            self.release_authority_lease(bootstrap, lease)

    def commit_first_ingress_c02_v1(
        self, bootstrap: object, original_intent, read, installation_policy,
        admin_policy, clock_policy, *, _first_seal_v2: bool = False,
    ) -> CommitReceipt:
        """Adopt one finished V3 worker result through the shared D06 graph path."""
        from datetime import datetime
        from types import SimpleNamespace

        from .authority_service.v2_model_egress_contract import ModelEgressIntentV1
        from .authority_service.v2_worker_model_result_contract import WorkerModelResultReadV1
        from .domains.d04.encoding_baseline import decode_encoding_baseline
        from .domains.d06 import D06DomainAdapter, EncodingContext
        from .domains.d06.pipeline import D06MemoryPipeline
        from .host.authority_profile import (
            AdminD06FirstIngressC02Policy, AdminIngressClockPolicy,
        )
        from .installation_policy import AdminInstallationPolicy
        from .memory_repository import MemoryRepository
        from .runtime.encoding_call_binding import load_binding
        from .runtime.d11_types import (
            D11_PROPOSAL_SCHEMA, D11_PROPOSAL_SCHEMA_HASH, job_graph_write,
            runtime_job_key,
        )
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.issuers import d06_first_ingress_c02_quote_id
        from .runtime_contracts import (
            CommandEnvelope, DependencySet, DomainProposal, OperationIdentity,
            QueryEpoch, RUNTIME_SCHEMA,
            VersionedRef,
        )

        self._admin(bootstrap)
        if (type(original_intent) is not ModelEgressIntentV1
                or type(read) is not WorkerModelResultReadV1
                or type(installation_policy) is not AdminInstallationPolicy
                or type(admin_policy) is not AdminD06FirstIngressC02Policy
                or type(clock_policy) is not AdminIngressClockPolicy
                or not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or self.__worker_result_fact_port is None
                or self.__d11_issuer is None
                or not self.first_ingress_c02_accounting_installed_v1()):
            raise UnavailableGuard("installed first-ingress C02 authorities required; HOLD")
        read.require_original_intent(original_intent)
        request = read.request
        namespace = request.namespace
        if installation_policy.namespace != namespace:
            raise UnavailableGuard("C02 installation namespace differs; HOLD")
        duplicate = self._first_ingress_c02_duplicate_v1(
            namespace, request.consumer_operation_id, original_intent, read)
        if duplicate is not None:
            self._commit_first_ingress_c02_unknown_cost_v1(
                namespace, original_intent, read, duplicate)
            return duplicate
        try:
            reading = self.__content_fence_v2.read_ingress_clock(clock_policy)
            now = trusted_upper(reading)
        except Exception as exc:
            raise UnavailableGuard("paired C02 clock unavailable; HOLD") from exc
        store = self.__store
        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
            job, _, _, outbox, _, _, source_version, access_version = (
                self._first_ingress_encoding_job_locked(namespace, request.job_id))
            binding = load_binding(store._db, namespace, request.job_id)
            if (binding is None
                    or binding.request.get("schema") !=
                    "sylanne.first-ingress-encoding-call.v3"
                    or (binding.call_id, binding.binding_digest,
                        binding.model_request_digest, binding.source_id) !=
                       (request.call_id, request.binding_digest,
                        request.model_request_digest, outbox.payload_ref)
                    or (job.operation_id, job.phase, job.lease_holder,
                        job.cancel_epoch, job.fence) !=
                       (request.original_operation_id, "running",
                        original_intent.subject, 0, original_intent.worker_fence)
                    or request.acquire_operation_id !=
                       binding.request["acquire_operation_id"]
                    or request.consumer_operation_id == job.operation_id):
                raise UnavailableGuard("C02 original V3 worker identity differs; HOLD")
            baseline = self._committed_first_ingress_baseline_locked(
                namespace, binding.source_id, metadata, epoch)
            if binding.request.get("baseline") != asdict(baseline):
                raise UnavailableGuard("C02 frozen baseline differs; HOLD")
            db = store._db
            source_row = db.execute(
                "SELECT value FROM graph_atoms WHERE token=? AND valid=1",
                (source_version.key.token,),
            ).fetchone()
            baseline_row = db.execute(
                "SELECT value FROM graph_atoms WHERE token=? AND valid=1",
                (baseline.baseline_ref,),
            ).fetchone()
            if source_row is None or baseline_row is None:
                raise UnavailableGuard("C02 source or baseline absent; HOLD")
            source = SourceRecord.from_dict(json.loads(source_row[0]))
            decoded = decode_encoding_baseline(json.loads(baseline_row[0]))
            perspective_key = AtomKey.from_token(decoded.perspective_ref)
            perspective_row = db.execute(
                "SELECT value FROM graph_atoms WHERE token=? AND valid=1",
                (perspective_key.token,),
            ).fetchone()
            if perspective_row is None:
                raise UnavailableGuard("C02 self perspective absent; HOLD")
            perspective = json.loads(perspective_row[0])
            event_key = AtomKey.from_token(perspective["arrival_event_ref"])
            mapping_key = AtomKey.from_token(perspective["identity_mapping_ref"])
            keys = tuple(dict.fromkeys((
                source_version.key, access_version.key, event_key,
                perspective_key, mapping_key,
                *(AtomKey.from_token(item.ref) for item in
                  decoded.then_feeling_versions),
                *(AtomKey.from_token(item.ref) for item in
                  decoded.interpretation_versions),
                AtomKey.from_token(baseline.baseline_ref),
            )))
            rows = [db.execute(
                "SELECT revision,valid FROM graph_atoms WHERE token=?",
                (key.token,),
            ).fetchone() for key in keys]
            if any(row is None or row[1] != 1 for row in rows):
                raise UnavailableGuard("C02 committed context changed; HOLD")
            versions = tuple(GraphVersion(key, row[0])
                             for key, row in zip(keys, rows))
            context = EncodingContext(
                event_key.token, perspective_key.token,
                tuple(item.ref for item in decoded.then_feeling_versions),
                tuple(item.ref for item in decoded.interpretation_versions),
                (), tuple((item.key.token, item.revision) for item in versions))
            qualification = self._original_first_ingress_qualification_locked(
                namespace, job.operation_id, source_version.key.token)
            job_key = runtime_job_key(*namespace.as_tuple, job.activity_id,
                                      job.job_id)
            job_row = db.execute(
                "SELECT revision,valid FROM graph_atoms WHERE token=?",
                (job_key.token,),
            ).fetchone()
            if job_row is None or job_row[1] != 1:
                raise UnavailableGuard("C02 original job projection absent; HOLD")
            authority_epochs = db.execute(
                "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                "WHERE bot=? AND persona=?", namespace.as_tuple,
            ).fetchone()
            guards = dict(db.execute(
                "SELECT kind,version FROM graph_guard_versions WHERE bot=? "
                "AND persona=? AND ref='current'", namespace.as_tuple,
            ).fetchall())
        repository = MemoryRepository(store, *namespace.as_tuple)
        # D06's preparation reads a snapshot through its repository.store.
        # Give it only coordinator-authorized reads of this same graph store;
        # ProductionGraphStore intentionally denies direct domain access.
        repository.store = SimpleNamespace(
            _registry=store._registry,
            graph_snapshot=lambda keys: GraphStore.graph_snapshot(
                store, keys, _capability=store._coordinator_capability),
            graph_epoch=lambda bot, persona: GraphStore.graph_epoch(
                store, bot, persona, _capability=store._coordinator_capability),
        )
        pipeline = D06MemoryPipeline(D06DomainAdapter(namespace), repository)
        audience = tuple(binding.request["envelope"]["authority"]["audience"])
        if len(audience) != 1:
            raise UnavailableGuard("C02 requires one original audience; HOLD")
        prepared = pipeline.prepare_worker_first_ingress_encoding(
            read, binding, source, context,
            encoding_baseline_ref=baseline.baseline_ref,
            audience=audience[0], purpose="consolidation")
        worker_expires = datetime.fromisoformat(job.lease_expires_utc.replace(
            "Z", "+00:00")).timestamp()
        deadline = min(now + admin_policy.deadline_after_seconds,
                       installation_policy.root_grant.valid_until_utc)
        if not _first_seal_v2:
            deadline = min(deadline, worker_expires)
        if deadline <= now:
            raise UnavailableGuard("C02 worker or quote deadline expired; HOLD")
        if _first_seal_v2 and deadline <= worker_expires:
            raise UnavailableGuard("C02 v2 business deadline cannot outlive worker lease; HOLD")
        operation_id = request.consumer_operation_id
        lease, capability = self.grant(
            bootstrap, actor=job.lease_holder, issuer_domain="d06",
            namespace=namespace, domains=("d06", "d11"),
            activation_generation=metadata.requirements.activation_generation,
            operation_id=operation_id)
        try:
            authority = AuthorityContext(
                job.lease_holder, "d06", capability, namespace,
                ("event", "activity"),
                "consolidation", audience,
                installation_policy.root_grant.policy_ref,
                metadata.requirements.activation_generation, job.fence)
            episode = prepared.prepared.proposal.episode
            trace = prepared.prepared.proposal.trace
            from .memory_types import episode_key, subjective_trace_v2_key
            output_versions = (
                GraphVersion(episode_key(*namespace.as_tuple,
                                         episode.episode_id), 0),
                GraphVersion(subjective_trace_v2_key(*namespace.as_tuple,
                                                     trace.trace_id), 0),
            )
            input_refs = (source_version.key.token, event_key.token,
                          baseline.baseline_ref)
            envelope = CommandEnvelope(
                RUNTIME_SCHEMA,
                OperationIdentity(job.activity_id, None, "first-ingress-c02",
                                  "first_ingress_c02", operation_id,
                                  canonical_digest({"input_refs": list(input_refs)})),
                authority,
                VersionGuard(
                    versions + (GraphVersion(job_key, job_row[0]),) + output_versions,
                    (QueryEpoch(namespace, "all", epoch.revision),),
                    *authority_epochs, store._registry.catalogue_hash,
                    guards["scheme"], guards["operator"], guards["policy"],
                    (), (), (VersionedRef(
                        d06_first_ingress_c02_quote_id(namespace, operation_id),
                        1),)),
                qualification, input_refs, job.budget_ref, deadline,
                reading.monotonic_after_seconds +
                (deadline - reading.utc_upper_bound_seconds),
                binding.request["envelope"]["character_interval_ref"],
                (job.operation_id, request.acquire_operation_id),
            )
            held = pipeline.compile_first_ingress_c02_v2(
                envelope, prepared, read,
                audience=audience[0], purpose="consolidation")
            completed_job = replace(
                job, phase="completed", result_ref=episode.episode_id,
                lease_holder=None, lease_expires_utc=None)
            job_proposal = DomainProposal(
                "d11", D11_PROPOSAL_SCHEMA, D11_PROPOSAL_SCHEMA_HASH,
                envelope, (job_graph_write(completed_job),),
                DependencySet(), (), ())
            bundle = DomainBundle(envelope, (held.proposal, job_proposal), (), (), (),
                                  (), (), (), ())
            receipt = self._commit_domain_bundle_v2(
                bundle, lease, c02_adoption=(
                    original_intent, read, binding, held, installation_policy,
                    admin_policy, now), c02_first_seal_v2=_first_seal_v2)
            verified = self._first_ingress_c02_duplicate_v1(
                namespace, operation_id, original_intent, read)
            if verified is None:
                raise UnavailableGuard("C02 content receipt missing before cost accounting")
            self._commit_first_ingress_c02_unknown_cost_v1(
                namespace, original_intent, read, verified)
            return receipt
        finally:
            self.release_authority_lease(bootstrap, lease)

    def commit_first_ingress_c02_v2(
        self, bootstrap: object, original_intent, read, installation_policy,
        admin_policy, clock_policy,
    ) -> CommitReceipt:
        """First-seal one C02 with a business deadline beyond its worker lease."""
        return self.commit_first_ingress_c02_v1(
            bootstrap, original_intent, read, installation_policy,
            admin_policy, clock_policy, _first_seal_v2=True)

    def _first_ingress_c02_duplicate_v2(
        self, namespace: NamespaceId, operation_id: str, *,
        original_intent=None, pinned_read=None, request=None,
    ) -> CommitReceipt | None:
        """Verify an exact v2 seal, business receipt and finished write fence."""
        from .authority_service.v2_contract import FencePermitV2, from_wire
        from .authority_service.v2_terminal_c02_recovery_contract import (
            OriginalC02ResultKeyV1, TerminalRecoveryReadRequestV1,
            from_wire as terminal_from_wire,
        )
        from .authority_service.v2_worker_model_result_contract import (
            WorkerModelResultReadRequestV1, from_wire as worker_from_wire,
        )
        from .runtime.c02_terminal_job import _PinnedTerminalRead
        from .runtime.terminal_c02_recovery_candidate_v2 import (
            FrozenTerminalC02CandidateV2,
            inspect_frozen_terminal_c02_candidate_v2,
        )

        store = self.__store
        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
            db = store._db
            archive = db.execute(
                "SELECT schema,bundle_digest,fence_attempt_id,bundle_json,"
                "evidence_json,quote_json,seal_json FROM "
                "graph_first_ingress_c02_committed_seals_v2 WHERE bot=? "
                "AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone()
            row = db.execute(
                "SELECT digest,activity_id,effect_id,commit_seq,receipt_json "
                "FROM graph_bundle_operations WHERE bot=? AND persona=? "
                "AND operation_id=?", namespace.as_tuple + (operation_id,),
            ).fetchone()
            if row is None:
                return None
            if archive is None:
                raise EventConflict("committed C02 v2 seal is absent")
            try:
                raw = json.loads(archive[6])
                raw["original_key"] = terminal_from_wire(
                    raw["original_key"], OriginalC02ResultKeyV1)
                seal = FrozenTerminalC02CandidateV2(**raw)
                inspection = inspect_frozen_terminal_c02_candidate_v2(
                    namespace=namespace, operation_id=operation_id, seal=seal,
                    bundle_json=archive[3], quote_json=archive[5])
                evidence = json.loads(archive[4])
                worker_request = worker_from_wire(
                    evidence["read_request"], WorkerModelResultReadRequestV1)
                data = json.loads(row[4])
                c02 = data["first_ingress_c02"]
            except (TypeError, ValueError, KeyError) as exc:
                raise UnavailableGuard("committed C02 v2 wire differs; HOLD") from exc
            expected_attempt = self._terminal_c02_read_attempt_id_v2(
                worker_request, seal.original_key, seal.bundle_digest)
            expected_request = TerminalRecoveryReadRequestV1(
                seal.original_key, operation_id, expected_attempt)
            common = {
                "read_request_digest": worker_request.digest,
                "read_result_digest": evidence["read_result_digest"],
                "original_intent_digest": seal.original_key.original_intent_digest,
                "terminal_receipt_digest": seal.original_key.terminal_receipt_digest,
                "observation_digest": seal.original_key.observation_digest,
                "result_digest": evidence["result_payload_digest"],
                "seal_schema": seal.schema,
                "original_key_digest": seal.original_key.digest,
                "signed_quote_digest": seal.quote_digest,
                "terminal_read_attempt_id": expected_attempt,
            }
            if (type(c02) is not dict or archive[0] != seal.schema
                    or archive[1] != row[0]
                    or archive[2] != domain_bundle_write_attempt_id_v1(
                        namespace, operation_id, row[0])
                    or inspection.bundle.digest != row[0]
                    or canonical_json(evidence) != archive[4]
                    or canonical_serialize(asdict(seal)) != archive[6]
                    or evidence.get("terminal_read_attempt_id") != expected_attempt
                    or worker_request.consumer_operation_id != operation_id
                    or (request is not None and request != expected_request)
                    or (original_intent is not None and
                        canonical_digest(asdict(original_intent)) !=
                        seal.original_key.original_intent_digest)):
                raise EventConflict("committed C02 v2 original identity differs")
            if "terminal_read_fact_digest" in c02:
                if (type(pinned_read) is _PinnedTerminalRead
                        and (pinned_read.fact.request != expected_request
                             or pinned_read.fact.digest != c02["terminal_read_fact_digest"])):
                    raise EventConflict("committed C02 v2 terminal fact differs")
                if (set(c02) != set(common) | {
                        "terminal_read_request_digest", "terminal_read_fact_digest"}
                        or any(c02[key] != value for key, value in common.items())
                        or c02["terminal_read_request_digest"] != expected_request.digest):
                    raise EventConflict("committed C02 v2 terminal receipt differs")
            elif c02 != {key: common[key] for key in (
                    "read_request_digest", "read_result_digest",
                    "original_intent_digest", "terminal_receipt_digest",
                    "observation_digest", "result_digest", "seal_schema")}:
                raise EventConflict("committed C02 v2 live receipt differs")
            quote = self.__d02_issuer.original_signed_quote(
                db, seal.quote_id, seal.quote_version)
            if canonical_serialize(asdict(quote)) != archive[5]:
                raise UnavailableGuard("committed C02 v2 historical quote differs; HOLD")
            graph = db.execute(
                "SELECT reads,revisions,epoch_revision FROM graph_events "
                "WHERE bot=? AND persona=? AND session=? AND event_id=?",
                namespace.as_tuple + (row[1], operation_id),
            ).fetchone()
            fence = db.execute(
                "SELECT digest,permit_json,pre_graph_revision,pre_graph_epoch,"
                "post_graph_revision,post_graph_epoch,finish_request_id,"
                "finish_request_digest FROM graph_bundle_fences_v2 WHERE bot=? "
                "AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone()
            if graph is None or fence is None or fence[0] != row[0]:
                raise UnavailableGuard("committed C02 v2 graph or fence absent; HOLD")
            receipt = CommitReceipt(
                "duplicate", operation_id, row[0], row[1], row[2], row[3],
                GraphStore._version_rows(graph[0]),
                GraphStore._version_rows(graph[1]),
                (NamespaceEpoch(*namespace.as_tuple, graph[2]),),
                tuple(data["ledger_refs"]), tuple(data["outbox_refs"]),
            )
        anchor = self.__content_fence_v2.current_anchor(
            namespace=namespace,
            authority_namespace=metadata.requirements.authority_namespace)
        if not self._anchor_matches(metadata.requirements, anchor):
            raise UnavailableGuard("C02 v2 replay Authority anchor differs")
        try:
            permit = from_wire(json.loads(fence[1]))
        except (TypeError, ValueError) as exc:
            raise UnavailableGuard("C02 v2 replay permit invalid") from exc
        attempt_id = domain_bundle_write_attempt_id_v1(
            namespace, operation_id, row[0])
        if (type(permit) is not FencePermitV2 or permit.operation != "write"
                or permit.operation_id != attempt_id
                or permit.pinned_anchor != anchor or permit.holder != self.__holder
                or permit.generation != metadata.requirements.activation_generation
                or fence[4] != fence[2] + 1 or fence[5] < fence[3]
                or fence[6] != "finish:" + attempt_id
                or fence[7] != "sha256:" + canonical_digest({
                    "operation_id": attempt_id, "permit_token": permit.token,
                    "action": "finish_domain_bundle",
                    "business_operation_id": operation_id,
                    "bundle_digest": row[0],
                })
                or metadata.graph_revision < fence[4]
                or epoch.revision < fence[5]):
            raise UnavailableGuard("C02 v2 replay write fence differs")
        observed, state = self.__content_fence_v2.get_fence_operation(
            namespace=namespace,
            authority_namespace=metadata.requirements.authority_namespace,
            operation_id=permit.operation_id)
        if observed != permit or state not in {"active", "finished"}:
            raise UnavailableGuard("C02 v2 replay Authority write state differs")
        if state == "active":
            if (metadata.graph_revision, epoch.revision) != (fence[4], fence[5]):
                raise UnavailableGuard("C02 v2 replay active fence lost its graph stamp")
            scope = FenceScope(
                namespace, metadata.requirements.authority_namespace,
                metadata.requirements.activation_generation,
                "write", permit.operation_id, permit, anchor,
                NamespaceEpoch(*namespace.as_tuple, fence[3]), fence[2])
            if self.__content_fence_v2.validate_fence(scope) != permit:
                raise UnavailableGuard("C02 v2 replay active write permit differs")
            self.__content_fence_v2.finish_fence(
                scope, request_id=fence[6], request_digest=fence[7])
        return receipt

    def _first_ingress_c02_duplicate_v1(
        self, namespace: NamespaceId, operation_id: str, original_intent, read=None,
        *, terminal_receipt_digest: str | None = None,
    ) -> CommitReceipt | None:
        """Replay a committed C02 from its result or terminal and graph receipts."""
        from .authority_service.v2_contract import FencePermitV2, from_wire

        store = self.__store
        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
            row = store._db.execute(
                "SELECT digest,activity_id,effect_id,commit_seq,receipt_json "
                "FROM graph_bundle_operations WHERE bot=? AND persona=? "
                "AND operation_id=?", namespace.as_tuple + (operation_id,),
            ).fetchone()
            if row is None:
                return None
            data = json.loads(row[4])
            c02 = data.get("first_ingress_c02")
            archived_seal = (
                store._db.execute(
                    "SELECT schema,bundle_digest FROM "
                    "graph_first_ingress_c02_committed_seals_v2 WHERE bot=? "
                    "AND persona=? AND operation_id=?",
                    namespace.as_tuple + (operation_id,),
                ).fetchone()
                if store._db.execute(
                    "SELECT 1 FROM sqlite_master WHERE type='table' "
                    "AND name='graph_first_ingress_c02_committed_seals_v2'"
                ).fetchone() else None)
            seal_schema = (
                "sylanne.first-ingress-c02-candidate.v2"
                if archived_seal is not None else None)
            expected_c02 = (
                {"read_request_digest": read.request.digest,
                 "read_result_digest": canonical_digest(asdict(read)),
                 "original_intent_digest": canonical_digest(asdict(original_intent)),
                 "terminal_receipt_digest": canonical_digest(
                     asdict(read.terminal_receipt)),
                 "observation_digest": read.observation.digest,
                 "result_digest": canonical_digest(read.observation.result),
                 **({"seal_schema": seal_schema} if seal_schema is not None else {})}
                if read is not None else None)
            if (not isinstance(c02, dict)
                    or (archived_seal is not None and
                        (archived_seal[0] != seal_schema or archived_seal[1] != row[0]))
                    or set(c02) != {
                        "read_request_digest", "read_result_digest",
                        "original_intent_digest", "terminal_receipt_digest",
                        "observation_digest", "result_digest"} | (
                            {"seal_schema"} if seal_schema is not None else set())
                    or (c02 != expected_c02 if read is not None else
                        c02["original_intent_digest"] != canonical_digest(
                            asdict(original_intent))
                        or c02["terminal_receipt_digest"] != terminal_receipt_digest
                        or any(type(value) is not str or len(value) != 64
                               or any(char not in "0123456789abcdef" for char in value)
                               for key, value in c02.items()
                               if key != "seal_schema"))):
                raise EventConflict("C02 operation ID reused with different original result")
            graph = store._db.execute(
                "SELECT reads,revisions,epoch_revision FROM graph_events "
                "WHERE bot=? AND persona=? AND session=? AND event_id=?",
                namespace.as_tuple + (row[1], operation_id),
            ).fetchone()
            fence = store._db.execute(
                "SELECT digest,permit_json,pre_graph_revision,pre_graph_epoch,"
                "post_graph_revision,post_graph_epoch,finish_request_id,"
                "finish_request_digest FROM graph_bundle_fences_v2 WHERE bot=? "
                "AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone()
            if graph is None or fence is None or fence[0] != row[0]:
                raise UnavailableGuard("C02 committed graph or fence receipt is absent")
            receipt = CommitReceipt(
                "duplicate", operation_id, row[0], row[1], row[2], row[3],
                GraphStore._version_rows(graph[0]),
                GraphStore._version_rows(graph[1]),
                (NamespaceEpoch(*namespace.as_tuple, graph[2]),),
                tuple(data["ledger_refs"]), tuple(data["outbox_refs"]),
            )
        anchor = self.__content_fence_v2.current_anchor(
            namespace=namespace,
            authority_namespace=metadata.requirements.authority_namespace)
        if not self._anchor_matches(metadata.requirements, anchor):
            raise UnavailableGuard("C02 replay Authority anchor differs")
        try:
            permit = from_wire(json.loads(fence[1]))
        except (TypeError, ValueError) as exc:
            raise UnavailableGuard("C02 replay write permit is invalid") from exc
        attempt_id = domain_bundle_write_attempt_id_v1(
            namespace, operation_id, row[0])
        if (type(permit) is not FencePermitV2 or permit.operation != "write"
                or permit.operation_id != attempt_id
                or permit.pinned_anchor != anchor or permit.holder != self.__holder
                or permit.generation != metadata.requirements.activation_generation
                or fence[4] != fence[2] + 1
                or fence[5] < fence[3]
                or fence[6] != "finish:" + attempt_id
                or fence[7] != "sha256:" + canonical_digest({
                    "operation_id": attempt_id, "permit_token": permit.token,
                    "action": "finish_domain_bundle",
                    "business_operation_id": operation_id,
                    "bundle_digest": row[0],
                })
                or metadata.graph_revision < fence[4]
                or epoch.revision < fence[5]):
            raise UnavailableGuard("C02 replay graph write fence differs")
        observed, state = self.__content_fence_v2.get_fence_operation(
            namespace=namespace,
            authority_namespace=metadata.requirements.authority_namespace,
            operation_id=permit.operation_id)
        if observed != permit or state not in {"active", "finished"}:
            raise UnavailableGuard("C02 replay Authority write state differs")
        if state == "active":
            if (metadata.graph_revision, epoch.revision) != (fence[4], fence[5]):
                raise UnavailableGuard("C02 replay active fence lost its graph stamp")
            scope = FenceScope(
                namespace, metadata.requirements.authority_namespace,
                metadata.requirements.activation_generation,
                "write", permit.operation_id, permit, anchor,
                NamespaceEpoch(*namespace.as_tuple, fence[3]), fence[2])
            if self.__content_fence_v2.validate_fence(scope) != permit:
                raise UnavailableGuard("C02 replay active write permit differs")
            self.__content_fence_v2.finish_fence(
                scope, request_id=fence[6], request_digest=fence[7])
        return receipt

    def _read_d04_root_freeze_v3_for_d11(self, db, namespace, operation_id):
        """Only the active W01 Owner write transaction may feed D11's issuer."""
        context = self.__d04_root_v3_freeze_context
        if (context is None or db is not self.__store._db or not db.in_transaction
                or not self.__store._lock._is_owned()
                or context.namespace != namespace
                or context.operation_id != operation_id):
            raise UnavailableGuard("current Owner-fenced D04 V3 root read unavailable")
        for ref, revision, value, valid in context.read_rows:
            row = db.execute(
                "SELECT revision,value,valid FROM graph_atoms WHERE token=?", (ref,)
            ).fetchone()
            current = (0, "{}", 0) if row is None else row
            if current != (revision, value, valid):
                raise StaleRead("D04 root V3 graph input changed before D11 freeze")
        return context.read

    def _derive_current_d04_root_v3_locked(self, db, *, namespace,
                                           operation_id, authority, binding,
                                           owner_proof, fence_scope, preset,
                                           handle, readout, output_policy):
        """Derive the exact root from current D12 heads and installed ABI2 bytes."""
        from .domains.d04.authored_lineage_v3 import (
            AuthoredRootBlockInputV3, AuthoredRootInputV3,
            RootAuthoredFacetV3, authored_root_write_rows_v3,
            compile_authored_root_candidate_v3, issue_authored_root_writes_v3,
            run_authored_initial_box_math_v3,
        )
        from .domains.d04.root import AuthoredRootPreset
        from .domains.d12.types import (
            ActiveSchemeHeadV1, CharacterDraft, active_scheme_head_key,
            character_draft_key,
        )
        from .native_runtime.d04_candidate import _assets
        from .runtime.d12_compiled_candidate_store_v1 import (
            read_current_compiled_authored_root_selection_v1,
        )
        from .runtime.d11_d04_root_freeze_v3 import D11RootFreezeReadV3
        from .runtime.scheme_original_store_v1 import (
            read_compilation_original_for_operation_v1,
        )
        from .runtime_contracts import VersionedRef

        if type(preset) is not AuthoredRootPreset:
            raise UnavailableGuard("typed D04 authored root preset unavailable")
        assets = preset.assets
        affect, scheme_hash, operator, operator_hash = _assets(
            self.__d04_installed_joint_assembly.package_root, handle)
        versions = ("scheme_version", "operator_version",
                    "parameter_version", "coupling_version")
        if (assets.scheme_sha256 != scheme_hash
                or assets.operator_sha256 != operator_hash
                or assets.parameter_sha256
                   != canonical_digest(affect.get("parameter_bounds"))
                or assets.coupling_sha256
                   != canonical_digest(operator.get("operator", {}).get("j"))
                or any(getattr(assets, name) != affect.get(name)
                       or getattr(assets, name) != operator.get(name)
                       for name in versions)
                or assets.readout_sha256 != readout.asset_sha256
                or assets.readout_version != readout.readout_version
                or preset.axes != output_policy.axis_ids):
            raise UnavailableGuard("D04 root preset differs from installed assets")
        draft_key = character_draft_key(namespace)
        head_key = active_scheme_head_key(namespace)
        activation_key = AtomKey(Owner("persona", *namespace.as_tuple),
                                 "d01.persona_activation.v1", "current")
        initial_keys = (activation_key, draft_key, head_key)
        read_rows = []
        for key in initial_keys:
            row = db.execute(
                "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                (key.token,),
            ).fetchone()
            if row is None or row[0] < 1 or row[2] != 1:
                raise UnavailableGuard("D01 activation or current D12 draft/head absent")
            if canonical_json(json.loads(row[1])) != row[1]:
                raise UnavailableGuard("D04 root prerequisite graph value is not canonical")
            self.__store._registry.validate(key, json.loads(row[1]))
            read_rows.append((key.token, *row))
        draft_raw = json.loads(read_rows[1][2])
        head_raw = json.loads(read_rows[2][2])
        if (draft_raw.pop("schema", None) != draft_key.type_name
                or head_raw.pop("schema", None) != head_key.type_name):
            raise UnavailableGuard("D12 root draft/head schema differs")
        draft = CharacterDraft(**draft_raw)
        head = ActiveSchemeHeadV1(**head_raw)
        draft_digest = canonical_digest(draft)
        if (draft.scope != namespace.persona_id
                or draft.revision != read_rows[1][1]
                or head.scope != namespace.persona_id
                or head.generation != read_rows[2][1]
                or head.draft_ref != draft_key.token
                or head.draft_revision != draft.revision
                or head.draft_digest != draft_digest):
            raise UnavailableGuard("D12 active head does not adopt the current root draft")
        field = draft.fields.get("d04.authored_root")
        if (type(field) is not dict or set(field) != {
                "candidate_id", "cursor", "preset_digest", "asset_digest", "blocks"}
                or type(field["blocks"]) is not list
                or not draft.field_sources.get("d04.authored_root")):
            raise UnavailableGuard("current D12 draft lacks an exact D04 V3 root")
        source = draft.field_sources["d04.authored_root"]
        field_digest = canonical_digest((
            draft_digest, "d04", (("d04.authored_root", field, source),)))
        selected = read_current_compiled_authored_root_selection_v1(
            db, namespace, draft_digest, field_digest)
        compiled_original = read_compilation_original_for_operation_v1(
            db, namespace, compiled_digest=head.compiled_digest)
        if (selected.field_value_json != canonical_serialize(field)
                or selected.field_source != source
                or compiled_original is None
                or compiled_original.compiled.draft_ref != draft_key.token
                or compiled_original.compiled.draft_revision != draft.revision
                or compiled_original.compiled.draft_digest != draft_digest
                or not any(
                    receipt.domain == "d04"
                    and receipt.field_names == ("d04.authored_root",)
                    and receipt.field_input_digest == field_digest
                    and receipt.candidate_ref
                       == "d12-domain-candidate:" + selected.candidate_digest
                    for receipt in compiled_original.compiled.domain_receipts)):
            raise UnavailableGuard("D12 active compilation lacks this exact root selection")
        blocks = []
        for item in field["blocks"]:
            if type(item) is not dict or set(item) != {
                    "facet", "axes", "latent_state", "ordered_box",
                    "initial_error_ref"}:
                raise UnavailableGuard("D04 V3 root block differs")
            blocks.append(AuthoredRootBlockInputV3(
                RootAuthoredFacetV3(**item["facet"]), tuple(item["axes"]),
                tuple(item["latent_state"]),
                tuple(tuple(pair) for pair in item["ordered_box"]),
                item["initial_error_ref"],
            ))
        selection = AuthoredRootInputV3(
            field["candidate_id"], namespace.as_tuple, authority.actor,
            f"{draft_key.token}@{draft.revision}:{draft_digest}",
            field["cursor"], field["preset_digest"], field["asset_digest"],
            tuple(blocks),
        )
        candidate = compile_authored_root_candidate_v3(preset, selection)
        initial_box = run_authored_initial_box_math_v3(handle, candidate)
        output = issue_authored_root_writes_v3(
            candidate, initial_box, readout, output_policy, operation_id)
        rows = authored_root_write_rows_v3(output.members)
        for ref, _, _ in rows:
            row = db.execute(
                "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                (ref,),
            ).fetchone()
            if row is not None:
                raise UnavailableGuard("D04 V3 root already has a graph state")
            read_rows.append((ref, 0, "{}", 0))
        read_rows.sort(key=lambda item: item[0])
        owner_token, owner_request = owner_proof
        owner_binding_digest = canonical_digest((owner_token, owner_request))
        owner_binding_payload = asdict(binding)
        for name in ("capabilities", "purposes", "audiences"):
            owner_binding_payload[name] = tuple(sorted(owner_binding_payload[name]))
        read = D11RootFreezeReadV3(
            namespace=namespace, operation_id=operation_id,
            owner_actor_id=authority.actor,
            owner_session_id=owner_request.credential_id,
            owner_session_binding_digest=owner_binding_digest,
            active_scheme_head=VersionedRef(head_key.token, head.generation),
            draft_head=VersionedRef(draft_key.token, draft.revision),
            draft_digest=draft_digest,
            root_input_digest=canonical_digest(selection),
            candidate_digest=candidate.digest,
            preset_digest=preset.digest, asset_digest=assets.digest,
            native_manifest_sha256=handle.production_binding.manifest_sha256,
            native_sha256=handle.production_binding.native_sha256,
            abi2_initial_box_digest=initial_box.proof_digest,
            abi2_readout_digest=output.readout_output_digest,
            initial_transcript_digest=initial_box.proof_digest,
            output_projection_digest=output.issuance_digest,
            authored_write_set_json=canonical_serialize(rows),
            authored_write_set_digest=output.write_set_digest,
            graph_read_set_digest=canonical_digest(read_rows),
            owner_fence_digest=canonical_digest((fence_scope.permit.token,
                                                 owner_binding_payload, owner_binding_digest)),
        )
        return SimpleNamespace(
            namespace=namespace, operation_id=operation_id, read_rows=tuple(read_rows),
            read=read, selection=selection, candidate=candidate,
            initial_box=initial_box, output=output, rows=rows,
        )

    def read_current_d04_root_budget_lease_v3(
            self, namespace: NamespaceId) -> str | None:
        """Select one current signed D11 lease dedicated to the V3 root."""
        from .runtime.d11_d04_root_freeze_v3 import ROOT_WORK_KIND_V3

        if (type(namespace) is not NamespaceId
                or not isinstance(self.__store, ProductionGraphStore)
                or self.__d11_issuer is None):
            return None
        with self.__store._lock:
            db = self.__store._db
            if db.in_transaction:
                raise UnavailableGuard("D04 root budget read needs an idle connection")
            db.execute("BEGIN")
            try:
                rows = db.execute(
                    "SELECT DISTINCT lease_id FROM runtime_budget_grants "
                    "WHERE status='active' ORDER BY lease_id",
                ).fetchall()
                eligible = []
                for (lease_id,) in rows:
                    try:
                        grant = self.__d11_issuer.current_budget_grant(db, lease_id)
                        budget = get_budget_lease(db, lease_id)
                    except (ValueError, RuntimeError, LookupError):
                        continue
                    if (grant.bot_id, grant.persona_id) != namespace.as_tuple:
                        continue
                    if (budget.bot_id, budget.persona_id) != namespace.as_tuple:
                        continue
                    if (grant.allowed_work_kinds == (ROOT_WORK_KIND_V3,)
                            and grant.valid_until_utc > time.time()
                            and budget.state == "active"
                            and grant.max_ceiling
                            and all(value > 0 for value in grant.max_ceiling.values())):
                        eligible.append(lease_id)
                return eligible[0] if len(eligible) == 1 else None
            finally:
                db.execute("ROLLBACK")

    def commit_current_d04_authored_root_v3(
            self, authority: AuthorityContext, lease: object, *,
            operation_id: str, compiled_digest: str,
            parent_budget_lease_ref: str, preset: object):
        """Adopt only one independently claimed, measured and accounted root."""
        from .domains.d04.root import AuthoredRootPreset
        from .runtime.d04_root_execution_v3 import execute_current_root_execution_v3
        from .runtime.d04_root_adoption_execution_v3 import adopt_executed_root_v3, replay_executed_root_v3
        from .runtime.d04_root_replay_v3 import replay_current_d04_root_v3
        from .runtime.d04_root_historical_cost_v3 import settle_historical_root_cpu_v3
        from .runtime.d04_appraisal_driver_v3 import read_d04_original_v3
        if (type(authority) is not AuthorityContext or authority.issuer_domain != "d12"
                or type(preset) is not AuthoredRootPreset
                or self.__d04_installed_joint_assembly is None
                or self.__c04_authority_port_v3 is None):
            raise UnavailableGuard("installed independently metered root authority unavailable")
        self._authorize(lease, authority, frozenset(("d04", "d11", "d12")), owner_read=True)
        request = dict(operation_id=operation_id, compiled_digest=compiled_digest,
            parent_budget_lease_ref=parent_budget_lease_ref, preset=preset)
        replay = replay_executed_root_v3(self, authority, lease, **request)
        if replay is not None:
            return replay
        # Old already-adopted roots remain exact historical reads. This path
        # never issues new math, a reservation, or an old unmetered adoption.
        replay = replay_current_d04_root_v3(self, authority, lease, **request)
        if replay is not None:
            return replay
        executed = execute_current_root_execution_v3(self, authority, lease, **request)
        if executed.terminal is None:
            raise UnavailableGuard("root original remains " + executed.status)
        try:
            return adopt_executed_root_v3(self, authority, lease, executed, preset=preset)
        except (ValueError, TypeError, UnavailableGuard):
            with self.__store._lock:
                committed = read_d04_original_v3(self.__store._db, authority.namespace,
                    "root_execution_link", operation_id)
            if committed is not None:
                return replay_executed_root_v3(self, authority, lease, **request)
            settle_historical_root_cpu_v3(self, self.__bootstrap,
                self.__d04_installed_joint_assembly.admin_bundle, operation_id=operation_id)
            raise UnavailableGuard("actual root CPU settled; current root adoption unavailable") from None

    def read_current_d04_authored_root_v3(
            self, authority: AuthorityContext, lease: object, *,
            operation_id: str):
        """Read the committed V3 root only under the current signed Owner fence."""
        from .runtime.d04_root_original_store_v3 import read_d04_root_original_v3
        from .runtime.d11_d04_root_freeze_v3 import read_d11_root_freeze_v3

        if (type(authority) is not AuthorityContext
                or authority.issuer_domain != "d12"
                or type(operation_id) is not str or not operation_id
                or not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or self.__d11_issuer is None):
            raise UnavailableGuard("current D04 authored root Owner read unavailable")
        self._authorize(lease, authority, frozenset(("d04", "d11", "d12")),
                        owner_read=True)
        binding = self.__owner_leases.get(lease)
        proof = self.__owner_session_proofs.get(lease)
        if (binding is None or proof is None
                or "workbench.activate" not in binding.capabilities):
            raise UnavailableGuard("current D04 authored root Owner proof unavailable")

        def read():
            db = self.__store._db
            if db.in_transaction:
                raise UnavailableGuard("D04 authored root read needs an idle connection")
            db.execute("BEGIN")
            try:
                original = read_d04_root_original_v3(
                    db, namespace=authority.namespace, operation_id=operation_id)
                freeze = read_d11_root_freeze_v3(
                    db, self.__d11_issuer, namespace=authority.namespace,
                    operation_id=operation_id)
                if (freeze is None
                        or freeze.original_digest != original.signed_freeze_digest):
                    raise UnavailableGuard("D04 V3 root signed freeze differs")
                return original
            finally:
                db.execute("ROLLBACK")

        return self._read_v2(authority, read, owner_binding=binding,
                             owner_session_proof=proof)

    def commit_d04_joint_advance_v2(self, bundle: DomainBundle, lease: object,
                                    installed_replay: object,
                                    installed_output: object = None) -> CommitReceipt:
        """Adopt one package-bound full/LOO replay with all member writes atomically."""
        from .domains.d04.trusted_joint_replay import (
            D04InstalledJointNumericReplayV1,
            is_package_bound_joint_numeric_replay_v1,
        )
        from .host.installed_package import verify_installed_backend_runtime_v1
        from .host.installed_d04_output_policy import (
            load_installed_d04_output_policy_v1,
        )
        from .domains.d04.joint_state_output_v1 import JointStateOutputOriginalV1
        from .runtime.d04_joint_advance_v2 import ProductAdvanceEvidenceV2

        assembly = self.__d04_installed_joint_assembly
        if (assembly is None or self.__d04_installed_joint_output_policy is None
                or type(bundle) is not DomainBundle
                or type(bundle.product_advance) is not ProductAdvanceEvidenceV2
                or type(installed_replay) is not D04InstalledJointNumericReplayV1
                or type(installed_output) is not JointStateOutputOriginalV1
                or not is_package_bound_joint_numeric_replay_v1(installed_replay)):
            raise UnavailableGuard("installed D04 joint replay unavailable; HOLD")
        policy = assembly.installation_policy
        grant = assembly.installation_grant
        current_grant = getattr(self.__content_fence_v2, "installation_grant", None)
        if (policy.namespace != bundle.envelope.authority.namespace
                or grant.installation_id != policy.installation_id
                or grant.manifest_digest != policy.manifest_digest
                or grant.authority_id != policy.expected_authority_id
                or current_grant is None
                or current_grant.installation_id != grant.installation_id
                or current_grant.manifest_digest != grant.manifest_digest
                or current_grant.authority_id != grant.authority_id
                or installed_replay.candidate.native_manifest_sha256
                   != policy.manifest_digest):
            raise UnavailableGuard("D04 joint installed identity differs; HOLD")
        package = verify_installed_backend_runtime_v1(
            assembly.package_root, policy.manifest_digest,
            available_cpu_features=assembly.available_cpu_features,
        )
        if (not package.verified or package.runtime_scope not in {"formal-alpha1", "backend-production-acceptance"}
                or package.manifest_digest != policy.manifest_digest):
            raise UnavailableGuard("formal D04 installed package unavailable; HOLD")
        selected_output_policy = load_installed_d04_output_policy_v1(
            assembly.package_root, policy.manifest_digest,
            require_formal=False, require_backend_runtime=True)
        if selected_output_policy != self.__d04_installed_joint_output_policy:
            raise UnavailableGuard("D04 installed output policy changed; HOLD")
        self._authorize(
            lease, bundle.envelope.authority,
            frozenset(proposal.domain for proposal in bundle.proposals),
        )
        if not isinstance(self.__store, ProductionGraphStore) or self.__content_fence_v2 is None:
            raise UnavailableGuard("D04 joint advance needs a production V2 write fence")
        return self._commit_domain_bundle_v2(
            bundle, lease, d04_joint_replay=installed_replay,
            d04_joint_output=installed_output)

    def commit_domain_bundle(self, bundle: DomainBundle, lease: object) -> CommitReceipt:
        if not isinstance(bundle, DomainBundle):
            raise TypeError("bundle must be DomainBundle")
        if bundle.root_adoption is not None:
            raise UnavailableGuard(
                "authored D04 root needs its dedicated installed adoption; HOLD")
        authority = bundle.envelope.authority
        self._authorize(lease, authority,
                        frozenset(proposal.domain for proposal in bundle.proposals))
        if (isinstance(self.__store, ProductionGraphStore)
                and self.__content_fence_v2 is not None):
            return self._commit_domain_bundle_v2(bundle, lease)
        with self._content_fence(authority.namespace, authority.activation_generation, "write"):
            store = self.__store
            with store._lock:
                self._admit_content(
                    authority.namespace, authority.activation_generation, "write",
                    tuple(item.key.token for item in bundle.envelope.version_guard.read_versions)
                    + tuple(write.key.token for proposal in bundle.proposals
                            for write in proposal.typed_writes),
                )
            return self._commit_domain_bundle_fenced(bundle, lease)

    def _validate_first_ingress_c02_terminal_locked(
        self, db, bundle, witness: _C02TerminalRecovery, job, seal, fact,
        v2_write,
    ) -> bool:
        """Check the original result, source and settled cost inside the write fence."""
        from .runtime.encoding_call_binding import binding_to_json, load_binding
        from .runtime.model_cost_settlement import OriginalModelCostCommitV1
        from .runtime.terminal_c02_recovery_candidate_v2 import (
            recovery_fact_matches_frozen_v2,
        )
        from .runtime.d11_types import job_graph_write

        envelope = bundle.envelope
        namespace = envelope.authority.namespace
        key = seal.original_key
        evidence = witness.evidence
        if (v2_write is None or witness.seal != seal
                or fact != witness.pinned_read.fact
                or not recovery_fact_matches_frozen_v2(
                    seal=seal, fact=fact, trusted_now_utc=witness.now)
                or len(bundle.proposals) != 2
                or tuple(proposal.domain for proposal in bundle.proposals)
                   != ("d06", "d11")
                or len(bundle.proposals[1].typed_writes) != 1
                or envelope.identity.operation_id != seal.consumer_operation_id
                or envelope.authority.actor != witness.original.holder
                or envelope.authority.worker_fence != witness.original.fence
                or evidence.get("original_intent_digest") != key.original_intent_digest
                or evidence.get("observation_digest") != key.observation_digest
                or evidence.get("terminal_receipt_digest") != key.terminal_receipt_digest):
            raise UnavailableGuard("terminal C02 original result differs; HOLD")
        binding = load_binding(db, namespace, key.job_id)
        acquire = db.execute(
            "SELECT i.job_id,i.original_operation_id,i.actor,"
            "i.encoding_binding_json,i.graph_revision,i.graph_epoch "
            "FROM graph_job_acquire_intents_v2 AS i "
            "WHERE i.bot=? AND i.persona=? AND i.acquire_operation_id=?",
            namespace.as_tuple + (key.acquire_operation_id,),
        ).fetchone()
        if (binding is None or acquire is None
                or acquire[:4] != (key.job_id, key.original_operation_id,
                                    witness.original.holder, binding_to_json(binding))
                or binding.request.get("schema") !=
                   "sylanne.first-ingress-encoding-call.v3"
                or (binding.call_id, binding.binding_digest,
                    binding.model_request_digest) !=
                   (key.call_id, key.binding_digest, key.model_request_digest)
                or (job.bot_id, job.persona_id, job.operation_id,
                    job.activity_id, job.phase, job.lease_holder,
                    job.fence, job.cancel_epoch, job.result_ref) !=
                   (*namespace.as_tuple, key.original_operation_id,
                    envelope.identity.activity_id, "running",
                    witness.original.holder, witness.original.fence, 0, None)):
            raise UnavailableGuard("terminal C02 original binding or job differs; HOLD")
        expected_job = replace(
            job, phase="completed",
            result_ref=bundle.proposals[0].typed_writes[0].value["episode_id"],
            lease_holder=None, lease_expires_utc=None)
        if bundle.proposals[1].typed_writes[0] != job_graph_write(expected_job):
            raise UnavailableGuard("terminal C02 graph job projection differs; HOLD")
        metadata, epoch = self._v2_graph_stamp(namespace)
        baseline = self._committed_first_ingress_baseline_locked(
            namespace, binding.source_id, metadata, epoch,
            acquire_stamp=acquire[4:6])
        if (binding.request.get("baseline") != asdict(baseline)
                or evidence.get("encoding_baseline_ref") != baseline.baseline_ref
                or evidence.get("source_ref") != binding.source_id
                or envelope.input_refs[0] != source_key(
                    *namespace.as_tuple, binding.source_id).token):
            raise UnavailableGuard("terminal C02 committed source or baseline differs; HOLD")
        epochs = db.execute(
            "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
            "WHERE bot=? AND persona=?", namespace.as_tuple,
        ).fetchone()
        source = db.execute(
            "SELECT revision,valid FROM graph_atoms WHERE token=?",
            (envelope.input_refs[0],),
        ).fetchone()
        access = db.execute(
            "SELECT revision,valid FROM graph_atoms WHERE token=?",
            (access_key(*namespace.as_tuple, binding.source_id).token,),
        ).fetchone()
        if (epochs != (envelope.version_guard.access_epoch,
                       envelope.version_guard.delete_epoch)
                or source != (binding.source_revision, 1)
                or access != (binding.access_revision, 1)):
            raise UnavailableGuard("terminal C02 current source access differs; HOLD")
        from .runtime.model_cost_settlement import original_model_cost_operation_id_v1
        cost_operation_id = original_model_cost_operation_id_v1(
            namespace, binding.call_id)
        cost_row = db.execute(
            "SELECT receipt_json FROM graph_bundle_operations "
            "WHERE bot=? AND persona=? AND operation_id=?",
            namespace.as_tuple + (cost_operation_id,),
        ).fetchone()
        if cost_row is None:
            raise UnavailableGuard("terminal C02 original model cost absent; HOLD")
        cost = OriginalModelCostCommitV1(
            **json.loads(cost_row[0])["original_model_cost"])
        if (cost.status != "committed" or cost.call_id != binding.call_id
                or cost.terminal_receipt_digest != key.terminal_receipt_digest
                or db.execute(
                    "SELECT state FROM runtime_budget_reservations "
                    "WHERE lease_id=? AND operation_id=?",
                    (job.budget_ref, job.operation_id),
                ).fetchone() != ("settled",)):
            raise UnavailableGuard("terminal C02 original cost differs; HOLD")
        return True

    def _validate_first_ingress_c02_adoption_locked(
        self, db, bundle, adoption, v2_write,
    ) -> None:
        """Join the Authority finished-read fact to current graph and cost."""
        from datetime import datetime

        from .runtime.encoding_call_binding import binding_to_json, load_binding
        from .runtime.model_cost_settlement import OriginalModelCostCommitV1

        witness, fact, permit = adoption
        recovery = isinstance(witness, _C02PendingRecovery)
        if recovery:
            from .runtime.first_ingress_v2 import trusted_upper

            request = witness.request
            evidence = witness.evidence
            installation = witness.installation
            now = trusted_upper(witness.clock_reading)
            if (now >= bundle.envelope.deadline_utc
                    or time.monotonic() >= witness.local_monotonic_deadline):
                raise UnavailableGuard("pending C02 deadline expired; HOLD")
            held = None
        else:
            original_intent, read, binding, held, installation, _admin, now = witness
            request = read.request
        envelope = bundle.envelope
        namespace = envelope.authority.namespace
        if (v2_write is None or len(bundle.proposals) != 2
                or (not recovery and bundle.proposals[0] != held.proposal)
                or bundle.proposals[0].domain != "d06"
                or bundle.proposals[1].domain != "d11"
                or len(bundle.proposals[1].typed_writes) != 1
                or (not recovery and held.status != "candidate_hold")
                or request.namespace != namespace
                or request.consumer_operation_id != envelope.identity.operation_id
                or request.installation_id != installation.installation_id
                or fact.read_request != request
                or fact.write_permit != permit
                or fact.bundle_digest != bundle.digest
                or (fact.result_digest != evidence["read_result_digest"]
                    if recovery else
                    fact.result_digest != canonical_digest(asdict(read)))
                or (fact.original_intent_digest != evidence["original_intent_digest"]
                    if recovery else
                    fact.original_intent_digest != canonical_digest(
                        asdict(original_intent)))
                or (canonical_digest(asdict(fact.terminal_receipt))
                    != evidence["terminal_receipt_digest"] if recovery else
                    fact.terminal_receipt != read.terminal_receipt)
                or (fact.terminal_receipt.observation_digest
                    != evidence["observation_digest"] if recovery else
                    held.observation_digest != read.observation.digest)
                or (evidence["call_id"] != request.call_id
                    if recovery else held.call_id != request.call_id)
                or (evidence["model_request_digest"] != request.model_request_digest
                    if recovery else held.request_digest != request.model_request_digest)
                or (evidence["authority_operation_id"] != request.acquire_operation_id
                    if recovery else held.authority_operation_id != request.acquire_operation_id)
                or (not recovery and held.result_digest !=
                    canonical_digest(read.observation.result))):
            raise UnavailableGuard("C02 Authority result or held proposal differs; HOLD")
        if not recovery:
            read.require_original_intent(original_intent)
        job = get_job(db, request.job_id)
        current_binding = load_binding(db, namespace, request.job_id)
        if recovery:
            binding = current_binding
        acquire = db.execute(
            "SELECT i.job_id,i.original_operation_id,i.actor,"
            "i.encoding_binding_json,i.graph_revision,i.graph_epoch,"
            "r.job_json FROM graph_job_acquire_intents_v2 AS i "
            "JOIN graph_job_acquire_receipts_v2 AS r "
            "ON r.bot=i.bot AND r.persona=i.persona "
            "AND r.acquire_operation_id=i.acquire_operation_id "
            "WHERE i.bot=? AND i.persona=? AND i.acquire_operation_id=?",
            namespace.as_tuple + (request.acquire_operation_id,),
        ).fetchone()
        if (current_binding is None or current_binding != binding or acquire is None
                or acquire[:4] != (
                    request.job_id, request.original_operation_id,
                    envelope.authority.actor, binding_to_json(binding))
                or binding.request.get("schema") !=
                "sylanne.first-ingress-encoding-call.v3"
                or (binding.call_id, binding.binding_digest,
                    binding.model_request_digest) != (
                    request.call_id, request.binding_digest,
                    request.model_request_digest)
                or (job.bot_id, job.persona_id, job.operation_id,
                    job.activity_id, job.phase, job.lease_holder,
                    job.fence, job.cancel_epoch, job.result_ref) != (
                    *namespace.as_tuple, request.original_operation_id,
                    envelope.identity.activity_id, "running",
                    envelope.authority.actor, envelope.authority.worker_fence,
                    0, None)
                or json.loads(acquire[6]) != asdict(job)
                or datetime.fromisoformat(job.lease_expires_utc.replace(
                    "Z", "+00:00")).timestamp() <= now):
            raise UnavailableGuard("C02 original V3 worker or acquire differs; HOLD")
        from .runtime.d11_types import job_graph_write

        expected_job = replace(
            job, phase="completed",
            result_ref=bundle.proposals[0].typed_writes[0].value["episode_id"],
            lease_holder=None, lease_expires_utc=None)
        if bundle.proposals[1].typed_writes[0] != job_graph_write(expected_job):
            raise UnavailableGuard("C02 completed job projection differs; HOLD")
        metadata, epoch = self._v2_graph_stamp(namespace)
        baseline = self._committed_first_ingress_baseline_locked(
            namespace, binding.source_id, metadata, epoch,
            acquire_stamp=acquire[4:6])
        if (binding.request.get("baseline") != asdict(baseline)
                or (evidence["encoding_baseline_ref"] != baseline.baseline_ref
                    if recovery else held.encoding_baseline_ref != baseline.baseline_ref)
                or (evidence["source_ref"] != binding.source_id
                    if recovery else held.source_ref != binding.source_id)
                or envelope.input_refs[0] != source_key(
                    *namespace.as_tuple, binding.source_id).token):
            raise UnavailableGuard("C02 committed source or baseline differs; HOLD")
        epochs = db.execute(
            "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
            "WHERE bot=? AND persona=?", namespace.as_tuple,
        ).fetchone()
        source = db.execute(
            "SELECT revision,valid FROM graph_atoms WHERE token=?",
            (envelope.input_refs[0],),
        ).fetchone()
        access = db.execute(
            "SELECT revision,valid FROM graph_atoms WHERE token=?",
            (access_key(*namespace.as_tuple, binding.source_id).token,),
        ).fetchone()
        if (epochs != (envelope.version_guard.access_epoch,
                       envelope.version_guard.delete_epoch)
                or source != (binding.source_revision, 1)
                or access != (binding.access_revision, 1)):
            raise UnavailableGuard("C02 source access or epoch changed; HOLD")
        from .runtime.model_cost_settlement import original_model_cost_operation_id_v1
        cost_operation_id = original_model_cost_operation_id_v1(
            namespace, binding.call_id)
        cost_row = db.execute(
            "SELECT receipt_json FROM graph_bundle_operations "
            "WHERE bot=? AND persona=? AND operation_id=?",
            namespace.as_tuple + (cost_operation_id,),
        ).fetchone()
        if cost_row is None:
            raise UnavailableGuard("C02 original model cost is absent; HOLD")
        cost = OriginalModelCostCommitV1(
            **json.loads(cost_row[0])["original_model_cost"])
        if (cost.status != "committed"
                or cost.call_id != binding.call_id
                or cost.terminal_receipt_digest != canonical_digest(
                    asdict(fact.terminal_receipt))
                or db.execute(
                    "SELECT state FROM runtime_budget_reservations "
                    "WHERE lease_id=? AND operation_id=?",
                    (job.budget_ref, job.operation_id),
                ).fetchone() != ("settled",)):
            raise UnavailableGuard("C02 original terminal cost differs; HOLD")

    def _stage_retry_intent_locked(self, db, namespace, stage, source_ref,
                                   original_operation_id, operation_id, digest,
                                   retry: _StageRetry) -> None:
        """CAS the current stage head while retaining the rejected predecessor."""
        table = ("graph_d03_self_projection_intents_v1" if stage == "d03" else
                 "graph_d04_baseline_intents_v1")
        old = db.execute(
            f"SELECT operation_id,bundle_digest FROM {table} "
            "WHERE bot=? AND persona=? AND source_ref=? "
            "AND original_operation_id=?",
            namespace.as_tuple + (source_ref, original_operation_id),
        ).fetchone()
        previous_intent = db.execute(
            "SELECT digest,fence_attempt_id FROM graph_bundle_intents_v2 "
            "WHERE bot=? AND persona=? AND operation_id=?",
            namespace.as_tuple + (retry.previous_operation_id,),
        ).fetchone()
        previous_rejection = db.execute(
            "SELECT digest,status,permit_json,graph_revision,graph_epoch,"
            "finish_request_id,finish_request_digest "
            "FROM graph_bundle_rejections_v2 WHERE bot=? AND persona=? "
            "AND operation_id=?",
            namespace.as_tuple + (retry.previous_operation_id,),
        ).fetchone()
        if (old != (retry.previous_operation_id, retry.previous_bundle_digest)
                or previous_intent != (retry.previous_bundle_digest,
                                       retry.previous_attempt_id)
                or previous_rejection is None
                or previous_rejection[1] != "rejected_no_commit"
                or canonical_digest(list(previous_rejection))
                != retry.previous_rejection_digest
                or db.execute(
                    "SELECT 1 FROM graph_bundle_operations WHERE bot=? "
                    "AND persona=? AND operation_id=?",
                    namespace.as_tuple + (retry.previous_operation_id,),
                ).fetchone() is not None
                or db.execute(
                    "SELECT 1 FROM graph_bundle_fences_v2 WHERE bot=? "
                    "AND persona=? AND operation_id=?",
                    namespace.as_tuple + (retry.previous_operation_id,),
                ).fetchone() is not None):
            raise EventConflict("stage retry predecessor is not a rejected no-commit")
        db.execute("""CREATE TABLE IF NOT EXISTS graph_stage_retry_lineage_v1(
            bot TEXT NOT NULL, persona TEXT NOT NULL,
            stage TEXT NOT NULL CHECK(stage IN ('d03','d04')),
            source_ref TEXT NOT NULL, original_operation_id TEXT NOT NULL,
            operation_id TEXT NOT NULL, previous_operation_id TEXT NOT NULL,
            retry_index INTEGER NOT NULL CHECK(retry_index > 0),
            previous_bundle_digest TEXT NOT NULL,
            previous_attempt_id TEXT NOT NULL,
            previous_rejection_digest TEXT NOT NULL,
            PRIMARY KEY(bot,persona,operation_id),
            UNIQUE(bot,persona,stage,source_ref,original_operation_id,retry_index))""")
        db.execute("""CREATE TRIGGER IF NOT EXISTS graph_stage_retry_lineage_no_update_v1
            BEFORE UPDATE ON graph_stage_retry_lineage_v1
            BEGIN SELECT RAISE(ABORT, 'stage retry lineage is immutable'); END""")
        db.execute("""CREATE TRIGGER IF NOT EXISTS graph_stage_retry_lineage_no_delete_v1
            BEFORE DELETE ON graph_stage_retry_lineage_v1
            BEGIN SELECT RAISE(ABORT, 'stage retry lineage is immutable'); END""")
        predecessor = db.execute(
            "SELECT retry_index FROM graph_stage_retry_lineage_v1 "
            "WHERE bot=? AND persona=? AND operation_id=?",
            namespace.as_tuple + (retry.previous_operation_id,),
        ).fetchone()
        if retry.retry_index != (predecessor[0] + 1 if predecessor else 1):
            raise EventConflict("stage retry ordinal is not consecutive")
        if retry.retry_index > 64:
            raise UnavailableGuard("stage retry bound reached; HOLD")
        db.execute(
            "INSERT INTO graph_stage_retry_lineage_v1"
            "(bot,persona,stage,source_ref,original_operation_id,operation_id,"
            "previous_operation_id,retry_index,previous_bundle_digest,"
            "previous_attempt_id,previous_rejection_digest) "
            "VALUES(?,?,?,?,?,?,?,?,?,?,?)",
            namespace.as_tuple + (
                stage, source_ref, original_operation_id, operation_id,
                retry.previous_operation_id, retry.retry_index,
                retry.previous_bundle_digest, retry.previous_attempt_id,
                retry.previous_rejection_digest),
        )
        updated = db.execute(
            f"UPDATE {table} SET operation_id=?,bundle_digest=? "
            "WHERE bot=? AND persona=? AND source_ref=? "
            "AND original_operation_id=? AND operation_id=? AND bundle_digest=?",
            (operation_id, digest) + namespace.as_tuple
            + (source_ref, original_operation_id,
               retry.previous_operation_id, retry.previous_bundle_digest),
        )
        if updated.rowcount != 1:
            raise EventConflict("stage retry head changed")

    def read_current_d13_ingress_inventory_v1(
            self, authority: AuthorityContext, lease: object, *,
            ingress_operation_id: str, c02_operation_id: str,
    ) -> CurrentD13IngressInventoryV1:
        """Read one current private ingress without asserting a D09 turn order.

        D13 cannot construct a completed turn from an arrival alone.  This
        metadata-only read gives its future window issuer a fenced starting
        point; it never exposes source text or authorizes a short-context slice.
        """
        from .host.authority_profile import AdminIngressClockPolicy
        from .host.v2_fence_port import VerifiedIngressClockV2
        from .runtime.c02_bundle_codec import c02_bundle_from_wire
        from .runtime.first_ingress_v2 import (
            scene_ref_for_conversation, trusted_upper,
        )
        from .runtime.reply_entity_route_v2 import (
            read_current_reply_entity_route_binding_v2,
        )
        from .runtime.reply_model_job import CurrentReplyRouteManifestV2
        from .runtime_contracts import QueryEpoch

        store = self.__store
        port = self.__content_fence_v2
        if (not isinstance(store, ProductionGraphStore) or port is None
                or type(self.__scene_clock_policy) is not AdminIngressClockPolicy):
            raise UnavailableGuard("installed D13 ingress read authorities required")
        self._authorize(lease, authority, frozenset({"d11"}))
        if (authority.issuer_domain != "d11" or authority.purpose != "context"
                or authority.worker_fence is not None
                or type(ingress_operation_id) is not str
                or not ingress_operation_id
                or type(c02_operation_id) is not str or not c02_operation_id):
            raise AuthorityDenied("D13 ingress read requires scoped D11 context")
        namespace = authority.namespace
        try:
            installation = port.installation_grant
            clock = port.read_ingress_clock(self.__scene_clock_policy)
            if (type(clock) is not VerifiedIngressClockV2
                    or clock.sample.authority_id != installation.authority_id
                    or clock.sample.installation_id != installation.installation_id
                    or clock.sample.source_id != self.__scene_clock_policy.source_id):
                raise ValueError("paired clock identity differs")
            now_utc = trusted_upper(clock)
        except Exception as exc:
            raise UnavailableGuard("paired D13 ingress clock unavailable; HOLD") from exc

        def reader():
            db = store._db
            db.execute("BEGIN")
            try:
                identity = self._reply_ingress_identity_locked(
                    namespace, ingress_operation_id)
                source_id = identity["source_ref"]
                source_key_value = source_key(*namespace.as_tuple, source_id)
                source_ref = source_key_value.token
                seal = db.execute(
                    "SELECT schema,bundle_digest,bundle_json FROM "
                    "graph_first_ingress_c02_committed_seals_v2 WHERE "
                    "bot=? AND persona=? AND operation_id=?",
                    namespace.as_tuple + (c02_operation_id,),
                ).fetchone()
                operation = db.execute(
                    "SELECT digest FROM graph_bundle_operations WHERE bot=? "
                    "AND persona=? AND operation_id=?",
                    namespace.as_tuple + (c02_operation_id,),
                ).fetchone()
                if (seal is None or operation != (seal[1],)
                        or seal[0] != "sylanne.first-ingress-c02-candidate.v2"):
                    raise UnavailableGuard("D13 original C02 seal is absent; HOLD")
                bundle = c02_bundle_from_wire(seal[2])
                if (bundle.digest != seal[1]
                        or bundle.envelope.identity.operation_id != c02_operation_id
                        or bundle.envelope.authority.namespace != namespace
                        or bundle.envelope.source_qualification.source_refs
                           != (source_ref,)):
                    raise UnavailableGuard("D13 C02 source lineage differs; HOLD")
                scene_ref = scene_ref_for_conversation(
                    namespace, identity["platform_ref"],
                    identity["conversation_ref"])
                route = CurrentReplyRouteManifestV2(
                    namespace, c02_operation_id, source_ref,
                    identity["platform_ref"], identity["conversation_ref"],
                    scene_ref, canonical_digest({
                        "account_ref": identity["platform_ref"],
                        "destination_ref": identity["conversation_ref"],
                        "scene_ref": scene_ref,
                    }),
                )
                _, epoch = self._v2_graph_stamp(namespace)
                binding = read_current_reply_entity_route_binding_v2(
                    db, namespace, route,
                    QueryEpoch(namespace, "all", epoch.revision),
                    now_utc=now_utc)
                if authority.audience != (binding.conversation_ref,):
                    raise AuthorityDenied("D13 ingress audience differs from original route")
                source_row = db.execute(
                    "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                    (binding.source_version.key.token,),
                ).fetchone()
                access_row = db.execute(
                    "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                    (binding.access_version.key.token,),
                ).fetchone()
                if (source_row is None or access_row is None
                        or (source_row[0], source_row[2])
                           != (binding.source_version.revision, 1)
                        or (access_row[0], access_row[2])
                           != (binding.access_version.revision, 1)):
                    raise UnavailableGuard("D13 source or access changed; HOLD")
                source = SourceRecord.from_dict(json.loads(source_row[1]))
                access = json.loads(access_row[1])
                validate_access(access)
                expires_at = source.recorded_at + 72 * 60 * 60
                if ("context" not in source.purposes
                        or "context" not in access["purposes"]
                        or binding.conversation_ref not in access["audiences"]
                        or not source.recorded_at <= now_utc < expires_at):
                    raise UnavailableGuard("D13 ingress context window unavailable; HOLD")
                epochs = db.execute(
                    "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                    "WHERE bot=? AND persona=?", namespace.as_tuple,
                ).fetchone()
                if epochs is None:
                    raise UnavailableGuard("D13 access or deletion epoch absent; HOLD")
                result = CurrentD13IngressInventoryV1(
                    ingress_operation_id, c02_operation_id, binding, seal[1],
                    now_utc, expires_at, epochs[0], epochs[1])
                db.execute("COMMIT")
                return result
            except BaseException:
                db.execute("ROLLBACK")
                raise

        result = self._read_v2(authority, reader)
        finished_at = trusted_upper(clock)
        if (not finished_at < result.source_expires_at_utc
                or result.route_binding.valid_until_utc is not None
                and not finished_at < result.route_binding.valid_until_utc):
            raise UnavailableGuard("D13 ingress read expired; HOLD")
        return result

    def _current_d13_inbound_inputs_locked_v1(
            self, namespace: NamespaceId, ingress_operation_id: str,
            c02_operation_id: str, now_utc: float):
        """Reconstruct the original ingress inside the graph transaction."""
        from .runtime.c02_bundle_codec import c02_bundle_from_wire
        from .runtime.first_ingress_v2 import scene_ref_for_conversation
        from .runtime.reply_entity_route_v2 import read_current_reply_entity_route_binding_v2
        from .runtime.reply_model_job import CurrentReplyRouteManifestV2
        from .runtime_contracts import QueryEpoch

        store = self.__store
        db = store._db
        if not store._lock._is_owned() or not db.in_transaction:
            raise RuntimeError("D13 inbound inputs require the held graph transaction")
        identity = self._reply_ingress_identity_locked(namespace, ingress_operation_id)
        source_ref = source_key(*namespace.as_tuple, identity["source_ref"]).token
        seal = db.execute(
            "SELECT schema,bundle_digest,bundle_json FROM "
            "graph_first_ingress_c02_committed_seals_v2 WHERE "
            "bot=? AND persona=? AND operation_id=?",
            namespace.as_tuple + (c02_operation_id,),
        ).fetchone()
        operation = db.execute(
            "SELECT digest FROM graph_bundle_operations WHERE bot=? AND persona=? "
            "AND operation_id=?", namespace.as_tuple + (c02_operation_id,),
        ).fetchone()
        if (seal is None or seal[0] != "sylanne.first-ingress-c02-candidate.v2"
                or operation != (seal[1],)):
            raise UnavailableGuard("D13 original C02 seal is absent; HOLD")
        bundle = c02_bundle_from_wire(seal[2])
        if (bundle.digest != seal[1]
                or bundle.envelope.identity.operation_id != c02_operation_id
                or bundle.envelope.authority.namespace != namespace
                or bundle.envelope.source_qualification.source_refs != (source_ref,)):
            raise UnavailableGuard("D13 C02 source lineage differs; HOLD")
        scene_ref = scene_ref_for_conversation(
            namespace, identity["platform_ref"], identity["conversation_ref"])
        route = CurrentReplyRouteManifestV2(
            namespace, c02_operation_id, source_ref,
            identity["platform_ref"], identity["conversation_ref"], scene_ref,
            canonical_digest({
                "account_ref": identity["platform_ref"],
                "destination_ref": identity["conversation_ref"],
                "scene_ref": scene_ref,
            }),
        )
        _, epoch = self._v2_graph_stamp(namespace)
        binding = read_current_reply_entity_route_binding_v2(
            db, namespace, route, QueryEpoch(namespace, "all", epoch.revision),
            now_utc=now_utc)

        def atom(version):
            row = db.execute(
                "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                (version.key.token,),
            ).fetchone()
            if row is None or (row[0], row[2]) != (version.revision, 1):
                raise UnavailableGuard("D13 inbound source or arrival changed; HOLD")
            return GraphAtom(version.key, row[0], json.loads(row[1]), True)

        arrival = atom(binding.arrival_event_version)
        account = atom(binding.binding_version)
        source = atom(binding.source_version)
        access = atom(binding.access_version)
        record = SourceRecord.from_dict(source.value)
        validate_access(access.value)
        if ("context" not in record.purposes
                or "context" not in access.value["purposes"]
                or identity["conversation_ref"] not in record.audiences
                or identity["conversation_ref"] not in access.value["audiences"]
                or not record.recorded_at <= now_utc < record.recorded_at + 72 * 60 * 60):
            raise UnavailableGuard("D13 original context source is unavailable; HOLD")
        authority_epochs = db.execute(
            "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
            "WHERE bot=? AND persona=?", namespace.as_tuple,
        ).fetchone()
        if authority_epochs is None:
            raise UnavailableGuard("D13 access or deletion epoch is absent; HOLD")
        return binding, arrival, account, source, access, epoch, authority_epochs

    def commit_confirmed_d13_inbound_turn_v1(
            self, authority: AuthorityContext, lease: object, *,
            ingress_operation_id: str, c02_operation_id: str,
    ) -> D13InboundTurnReceiptV1:
        """Commit exactly one original host-received turn under a v2 write fence.

        This narrow issuer does not infer any outbound delivery or issue a D13
        window. The ingress operation itself is the durable idempotency key.
        """
        from .authority_service.v2_contract import FencePermitV2, from_wire, to_wire
        from .domains.d09.turn_order import (
            complete_inbound_turn_v1, reserve_turn_slot_v1, turn_order_key,
            turn_slot_key, turn_completion_key, validate_turn_order_v1,
        )
        from .host.authority_profile import AdminIngressClockPolicy
        from .host.v2_fence_port import VerifiedIngressClockV2
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.restore_anchor import RestoreAnchor

        store = self.__store
        port = self.__content_fence_v2
        if (not isinstance(store, ProductionGraphStore) or port is None
                or type(self.__scene_clock_policy) is not AdminIngressClockPolicy):
            raise UnavailableGuard("installed D13 turn authorities required; HOLD")
        self._authorize(lease, authority, frozenset({"d09"}))
        if (authority.issuer_domain != "d09" or authority.purpose != "context"
                or authority.worker_fence is not None
                or "scene" not in authority.owner_scope
                or len(authority.audience) != 1
                or type(ingress_operation_id) is not str or not ingress_operation_id
                or type(c02_operation_id) is not str or not c02_operation_id):
            raise AuthorityDenied("D13 inbound turn needs scoped D09 context")
        namespace = authority.namespace
        try:
            installation = port.installation_grant
            clock = port.read_ingress_clock(self.__scene_clock_policy)
            if (type(clock) is not VerifiedIngressClockV2
                    or clock.sample.authority_id != installation.authority_id
                    or clock.sample.installation_id != installation.installation_id
                    or clock.sample.source_id != self.__scene_clock_policy.source_id):
                raise ValueError("paired clock identity differs")
            now_utc = trusted_upper(clock)
        except Exception as exc:
            raise UnavailableGuard("paired D13 inbound clock unavailable; HOLD") from exc

        def check_original_locked():
            binding, arrival, account, source, access, current_epoch, authority_epochs = (
                self._current_d13_inbound_inputs_locked_v1(
                    namespace, ingress_operation_id, c02_operation_id, now_utc))
            if authority.audience != (binding.conversation_ref,):
                raise AuthorityDenied("D13 turn audience differs from original ingress")
            return binding, arrival, account, source, access, current_epoch, authority_epochs

        def preflight():
            db = store._db
            db.execute("BEGIN")
            try:
                check_original_locked()
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise

        attempt_id = "d13-inbound-turn-" + canonical_digest({
            "namespace": namespace.as_tuple,
            "ingress_operation_id": ingress_operation_id,
        })
        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
            row = store._db.execute(
                "SELECT c02_operation_id,attempt_id,anchor_json,pre_graph_revision,"
                "pre_graph_epoch,permit_json,finish_request_id,"
                "finish_request_digest,receipt_json FROM "
                "graph_d13_inbound_turn_attempts_v1 WHERE bot=? AND persona=? "
                "AND ingress_operation_id=?",
                namespace.as_tuple + (ingress_operation_id,),
            ).fetchone()
        target = metadata.requirements
        if (target.namespace != namespace
                or target.activation_generation != authority.activation_generation):
            raise UnavailableGuard("D13 graph recovery generation differs; HOLD")
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("D13 graph recovery anchor differs; HOLD")
        if row is not None:
            if row[0:2] != (c02_operation_id, attempt_id):
                raise EventConflict("original D13 ingress operation differs")
            if RestoreAnchor(**json.loads(row[2])) != anchor:
                raise UnavailableGuard("original D13 turn anchor changed; HOLD")
        self._read_v2(authority, preflight)
        if row is None:
            with store._lock:
                db = store._db
                db.execute("BEGIN IMMEDIATE")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise StaleRead("D13 graph changed before original intent")
                    db.execute(
                        "INSERT INTO graph_d13_inbound_turn_attempts_v1"
                        "(bot,persona,ingress_operation_id,c02_operation_id,attempt_id,"
                        "anchor_json,pre_graph_revision,pre_graph_epoch) "
                        "VALUES(?,?,?,?,?,?,?,?)",
                        namespace.as_tuple + (ingress_operation_id,
                                              c02_operation_id, attempt_id,
                                              canonical_json(asdict(anchor)),
                                              metadata.graph_revision, epoch.revision),
                    )
                    db.execute("COMMIT")
                except BaseException:
                    db.execute("ROLLBACK")
                    raise
            row = (c02_operation_id, attempt_id, canonical_json(asdict(anchor)),
                   metadata.graph_revision, epoch.revision, None, None, None, None)

        def finish_saved(permit: FencePermitV2, receipt: D13InboundTurnReceiptV1):
            if (type(permit) is not FencePermitV2
                    or permit.operation_id != attempt_id
                    or permit.operation != "write"
                    or permit.pinned_anchor != anchor):
                raise UnavailableGuard("D13 original write permit differs; HOLD")
            reader = getattr(port, "get_fence_operation", None)
            if not callable(reader):
                raise UnavailableGuard("D13 original fence reader unavailable; HOLD")
            observed, state = reader(
                namespace=namespace,
                authority_namespace=target.authority_namespace,
                operation_id=attempt_id)
            if observed != permit or state not in {"active", "finished"}:
                raise UnavailableGuard("D13 original fence state differs; HOLD")
            if state == "active":
                scope = FenceScope(
                    namespace, target.authority_namespace,
                    authority.activation_generation, "write", attempt_id,
                    permit, anchor,
                    NamespaceEpoch(*namespace.as_tuple, row[4]), row[3])
                if port.validate_fence(scope) != permit:
                    raise UnavailableGuard("D13 original write fence changed; HOLD")
                port.finish_fence(
                    scope, request_id=row[6], request_digest=row[7])
            return receipt

        if row[8] is not None:
            if row[5] is None or row[6] is None or row[7] is None:
                raise UnavailableGuard("D13 durable turn receipt is incomplete; HOLD")
            receipt = D13InboundTurnReceiptV1(**json.loads(row[8]))
            permit = from_wire(json.loads(row[5]))
            finish_saved(permit, receipt)

            def verify_replay():
                db = store._db
                db.execute("BEGIN")
                try:
                    binding, arrival, _, source, access, _, _ = check_original_locked()
                    if (receipt.ingress_operation_id != ingress_operation_id
                            or receipt.c02_operation_id != c02_operation_id
                            or receipt.fence_attempt_id != attempt_id
                            or receipt.order_ref != turn_order_key(
                                namespace, binding.scene_ref,
                                binding.conversation_ref).token
                            or receipt.slot_ref != turn_slot_key(
                                namespace, binding.scene_ref,
                                binding.conversation_ref,
                                receipt.sequence).token
                            or receipt.completion_ref != turn_completion_key(
                                namespace, binding.scene_ref,
                                binding.conversation_ref,
                                receipt.sequence).token):
                        raise EventConflict("D13 original turn receipt differs")
                    for token in (receipt.order_ref, receipt.slot_ref,
                                  receipt.completion_ref):
                        history = db.execute(
                            "SELECT value,valid FROM graph_history WHERE token=? "
                            "AND event_bot=? AND event_persona=? "
                            "AND event_session='d13-inbound-turn' AND event_id=?",
                            (token, *namespace.as_tuple, ingress_operation_id),
                        ).fetchall()
                        if len(history) != 1 or history[0][1] != 1:
                            raise UnavailableGuard("D13 original turn graph history differs; HOLD")
                    for token in (receipt.slot_ref, receipt.completion_ref):
                        current = db.execute(
                            "SELECT value,valid FROM graph_atoms WHERE token=?", (token,),
                        ).fetchone()
                        if current is None or current[1] != 1:
                            raise UnavailableGuard("D13 original turn is no longer current; HOLD")
                    completion = json.loads(db.execute(
                        "SELECT value FROM graph_atoms WHERE token=?",
                        (receipt.completion_ref,),
                    ).fetchone()[0])
                    if (completion["evidence_ref"] != arrival.key.token
                            or completion["source_ref"] != source.key.token
                            or completion["access_ref"] != access.key.token):
                        raise UnavailableGuard("D13 original completion lineage differs; HOLD")
                    db.execute("COMMIT")
                except BaseException:
                    db.execute("ROLLBACK")
                    raise

            self._read_v2(authority, verify_replay)
            return receipt

        if (metadata.graph_revision != row[3] or epoch.revision != row[4]):
            raise UnavailableGuard("pending D13 original turn lost its graph head; HOLD")
        permit = port.begin_fence(
            namespace=namespace, authority_namespace=target.authority_namespace,
            holder=self.__holder, generation=authority.activation_generation,
            operation="write", operation_id=attempt_id, expected_anchor=anchor,
            retain_on_unknown=True)
        if (type(permit) is not FencePermitV2
                or permit.operation_id != attempt_id
                or permit.operation != "write"
                or permit.holder != self.__holder
                or permit.pinned_anchor != anchor):
            raise UnavailableGuard("D13 inbound write permit differs; HOLD")
        scope = FenceScope(
            namespace, target.authority_namespace,
            authority.activation_generation, "write", attempt_id,
            permit, anchor, epoch, metadata.graph_revision)
        finish_id = "finish:" + attempt_id
        finish_digest = "sha256:" + canonical_digest({
            "operation_id": attempt_id, "permit_token": permit.token,
            "action": "finish_d13_inbound_turn",
            "ingress_operation_id": ingress_operation_id,
        })
        if port.validate_fence(scope) != permit:
            raise UnavailableGuard("D13 inbound write fence changed; HOLD")
        with store._lock:
            db = store._db
            db.execute("BEGIN IMMEDIATE")
            try:
                if self._v2_graph_stamp(namespace) != (metadata, epoch):
                    raise StaleRead("D13 turn graph head changed")
                db.execute(
                    "UPDATE graph_d13_inbound_turn_attempts_v1 SET "
                    "permit_json=?,finish_request_id=?,finish_request_digest=? "
                    "WHERE bot=? AND persona=? AND ingress_operation_id=? "
                    "AND receipt_json IS NULL",
                    (canonical_json(to_wire(permit)), finish_id, finish_digest)
                    + namespace.as_tuple + (ingress_operation_id,),
                )
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise

        with store._lock:
            db = store._db
            db.execute("BEGIN IMMEDIATE")
            try:
                if self._v2_graph_stamp(namespace) != (metadata, epoch):
                    raise StaleRead("D13 turn graph head changed")
                binding, arrival, account, source, access, observed_epoch, _ = (
                    check_original_locked())
                if observed_epoch != epoch:
                    raise StaleRead("D13 turn scene order query changed")
                scene, conversation = binding.scene_ref, binding.conversation_ref
                order_key = turn_order_key(namespace, scene, conversation)
                order_row = db.execute(
                    "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                    (order_key.token,),
                ).fetchone()
                if order_row is not None and order_row[2] != 1:
                    raise UnavailableGuard("D13 scene order is invalid; HOLD")
                order = (None if order_row is None else GraphAtom(
                    order_key, order_row[0], json.loads(order_row[1]), True))
                if order is not None:
                    validate_turn_order_v1(order.value)
                duplicate_origin = db.execute(
                    "SELECT 1 FROM graph_atoms WHERE bot=? AND persona=? "
                    "AND type_name='d09.turn_slot.v1' "
                    "AND json_extract(value,'$.origin_ref')=? LIMIT 1",
                    namespace.as_tuple + (arrival.key.token,),
                ).fetchone()
                if duplicate_origin is not None:
                    raise EventConflict("original ingress already has a turn slot")
                all_slots = db.execute(
                    "SELECT token,value,valid FROM graph_atoms WHERE "
                    "bot=? AND persona=? AND type_name='d09.turn_slot.v1' "
                    "AND owner_kind='scene' AND subject=? AND name LIKE ?",
                    namespace.as_tuple + (scene, order_key.name + ":%"),
                ).fetchall()
                sequences = set()
                for token, encoded, valid in all_slots:
                    value = json.loads(encoded)
                    if (value.get("scene_ref"), value.get("conversation_ref")) == (
                            scene, conversation):
                        sequence = value.get("sequence")
                        if (not valid or type(sequence) is not int
                                or token != turn_slot_key(
                                    namespace, scene, conversation, sequence).token
                                or sequence in sequences):
                            raise UnavailableGuard("D13 scene slot closure differs; HOLD")
                        sequences.add(sequence)
                high = order.value["high_watermark"] if order is not None else -1
                if sequences != set(range(high + 1)):
                    raise UnavailableGuard("D13 scene slot sequence has a hole; HOLD")
                reservation = reserve_turn_slot_v1(
                    namespace, scene, conversation, "inbound", arrival.key.token,
                    current_order=order)
                order_write, slot_write = reservation.writes
                slot = GraphAtom(slot_write.key, 1, slot_write.value, True)
                evidence_version = binding.binding_evidence_event_version
                evidence_row = db.execute(
                    "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                    (evidence_version.key.token,)).fetchone()
                if (evidence_version.revision < 1 or evidence_row is None
                        or evidence_row[0] != evidence_version.revision or evidence_row[2] != 1):
                    raise StaleRead("D09 original account-binding evidence changed")
                binding_evidence = GraphAtom(evidence_version.key, evidence_row[0],
                    json.loads(evidence_row[1]), True)
                completion = complete_inbound_turn_v1(
                    namespace, slot, arrival, account, source, access,
                    binding_evidence=binding_evidence)
                if (reservation.absent_slot != slot_write.key
                        or completion.absent_completion != completion.write.key):
                    raise UnavailableGuard("D13 turn absence candidate differs; HOLD")
                # Completion is immutable history. Current source/access remain
                # guarded reads here and must be rechecked by every D13 read.
                completion_write = GraphWrite(
                    completion.write.key, completion.write.value)
                read_map = {
                    order_key: order.revision if order is not None else 0,
                    slot_write.key: 0, completion_write.key: 0,
                }
                for atom in (arrival, account, source, access):
                    read_map[atom.key] = atom.revision
                for version in (binding.anchor_version,
                                binding.binding_evidence_event_version,
                                *binding.binding_scan_versions):
                    read_map[version.key] = version.revision
                candidate = GraphCandidate(
                    Event(Scope(*namespace.as_tuple, "d13-inbound-turn"),
                          ingress_operation_id, now_utc, "d13.inbound_turn", {
                              "c02_operation_id": c02_operation_id,
                              "arrival_ref": arrival.key.token,
                              "source_ref": source.key.token,
                          }),
                    tuple(GraphVersion(key, revision) for key, revision in
                          sorted(read_map.items(), key=lambda item: item[0].token)),
                    (order_write, slot_write, completion_write), (epoch,),
                )
                result = []

                def seal(db, graph_receipt):
                    expected = {
                        GraphVersion(order_key, read_map[order_key] + 1),
                        GraphVersion(slot_write.key, 1),
                        GraphVersion(completion_write.key, 1),
                    }
                    if (graph_receipt.status != "committed"
                            or set(graph_receipt.revisions) != expected
                            or graph_receipt.epoch.revision != epoch.revision + 1):
                        raise UnavailableGuard("D13 turn graph receipt differs; HOLD")
                    store.cas_graph_recovery_metadata(
                        metadata, target, _capability=self.__graph_capability)
                    receipt = D13InboundTurnReceiptV1(
                        ingress_operation_id, c02_operation_id,
                        reservation.sequence, order_key.token,
                        slot_write.key.token, completion_write.key.token,
                        metadata.graph_revision + 1,
                        graph_receipt.epoch.revision, attempt_id)
                    db.execute(
                        "UPDATE graph_d13_inbound_turn_attempts_v1 SET receipt_json=? "
                        "WHERE bot=? AND persona=? AND ingress_operation_id=? "
                        "AND receipt_json IS NULL",
                        (canonical_json(asdict(receipt)),)
                        + namespace.as_tuple + (ingress_operation_id,),
                    )
                    if db.execute("SELECT changes()").fetchone() != (1,):
                        raise EventConflict("D13 original operation was already sealed")
                    result.append(receipt)

                GraphStore._graph_commit_in_transaction(
                    store, candidate, _receipt_hook=seal,
                    _capability=self.__graph_capability)
                db.execute("COMMIT")
            except BaseException:
                if db.in_transaction:
                    db.execute("ROLLBACK")
                raise
        port.finish_fence(scope, request_id=finish_id,
                          request_digest=finish_digest)
        return result[0]

    def read_current_d13_conversation_window_v1(
            self, authority: AuthorityContext, lease: object, *,
            scene_ref: str, max_slots: int = 32,
            before_sequence: int | None = None,
            _worker_scope: FenceScope | None = None,
            _schedule_scope: FenceScope | None = None,
    ):
        """Issue a bounded D11 window from current, confirmed inbound turns.

        `before_sequence` is an exclusive cursor. Every omitted slot, including
        unverified outbound slots, is represented in missing_ranges. A returned
        projection is a fenced snapshot; consumers must use its read_set and
        epochs rather than treating immutable completions as access grants.
        Its 72-hour check holds at the paired clock sample; D11 must recheck
        freshness before any later use or external dispatch.
        """
        from .authority_service.v2_owner_contract import OwnerAuthorizationGuardV1
        from .host.authority_profile import AdminIngressClockPolicy
        from .host.v2_fence_port import VerifiedIngressClockV2
        from .runtime.first_ingress_v2 import trusted_upper

        store = self.__store
        port = self.__content_fence_v2
        if (not isinstance(store, ProductionGraphStore) or port is None
                or type(self.__scene_clock_policy) is not AdminIngressClockPolicy):
            raise UnavailableGuard("installed D13 window authorities required; HOLD")
        self._authorize(lease, authority, frozenset({"d11"}))
        if (authority.issuer_domain != "d11" or authority.purpose != "context"
                or authority.worker_fence is not None
                or len(authority.audience) != 1
                or type(scene_ref) is not str or not scene_ref.startswith("scene:")
                or type(max_slots) is not int or not 1 <= max_slots <= 64
                or (before_sequence is not None and
                    (type(before_sequence) is not int or before_sequence < 1))):
            raise AuthorityDenied("D13 window requires bounded D11 context")
        namespace = authority.namespace
        conversation = authority.audience[0]
        try:
            installation = port.installation_grant
            clock = port.read_ingress_clock(self.__scene_clock_policy)
            if (type(clock) is not VerifiedIngressClockV2
                    or clock.sample.authority_id != installation.authority_id
                    or clock.sample.installation_id != installation.installation_id
                    or clock.sample.source_id != self.__scene_clock_policy.source_id):
                raise ValueError("paired clock identity differs")
            now_utc = trusted_upper(clock)
        except Exception as exc:
            raise UnavailableGuard("paired D13 window clock unavailable; HOLD") from exc
        guard_box = {}

        def observe_owner(scope):
            reader = getattr(port, "get_current_owner_guard_for_fence", None)
            if not callable(reader):
                raise UnavailableGuard("D13 Owner guard reader unavailable; HOLD")
            guarded = reader(
                namespace=namespace,
                authority_namespace=scope.authority_namespace,
                permit=scope.permit)
            if (type(guarded) is not tuple or len(guarded) != 2
                    or type(guarded[0]) is not OwnerAuthorizationGuardV1
                    or guarded[1] != scope.permit):
                raise UnavailableGuard("D13 current Owner guard differs; HOLD")
            guard = guarded[0]
            if (guard.namespace != namespace
                    or guard.authority_id != installation.authority_id
                    or guard.installation_id != installation.installation_id
                    or guard.authorization_revision != 1
                    or guard.pending_revoke_operation_id is not None
                    or guard.minimum_revocation_revision != 0
                    or guard.minimum_revocation_epoch != 0):
                raise UnavailableGuard("D13 Owner authorization is unavailable; HOLD")
            guard_box["guard"] = guard
            return guard

        def reader():
            from .runtime.d13_current_window import read_current_d13_window_for_authority_v1

            db = store._db
            db.execute("BEGIN")
            try:
                result = read_current_d13_window_for_authority_v1(
                    db, namespace, scene_ref, conversation, max_slots, now_utc,
                    before_sequence=before_sequence,
                    expected_activation_generation=authority.activation_generation,
                    expected_owner_authorization_head=guard_box["guard"].authorization_head,
                )
                db.execute("COMMIT")
                return result
            except BaseException:
                if db.in_transaction:
                    db.execute("ROLLBACK")
                raise

        if _worker_scope is None and _schedule_scope is None:
            return self._read_v2(authority, reader,
                                 fence_observer=observe_owner)
        if _schedule_scope is not None:
            if _worker_scope is not None:
                raise UnavailableGuard("D13 window cannot mix recovery scopes")
            scope = _schedule_scope
            if (type(scope) is not FenceScope or scope.namespace != namespace
                    or scope.operation != "write"
                    or scope.permit.holder != self.__holder
                    or scope.generation != authority.activation_generation
                    or port.validate_fence(scope) != scope.permit):
                raise UnavailableGuard("D13 schedule recovery scope differs; HOLD")
            observed_guard = observe_owner(scope)
            with store._lock:
                metadata, epoch = self._v2_graph_stamp(namespace)
                if (metadata.graph_revision != scope.graph_revision
                        or epoch != scope.graph_epoch
                        or metadata.requirements.authority_namespace
                        != scope.authority_namespace):
                    raise StaleRead("D13 schedule recovery graph head changed")
                from .authority_service.v2_contract import to_wire
                saved = store._db.execute(
                    "SELECT permit_json,receipt_json FROM "
                    "graph_d13_precompression_attempts_v2 WHERE bot=? "
                    "AND persona=? AND attempt_id=?",
                    namespace.as_tuple + (scope.operation_id,),
                ).fetchone()
                if saved != (canonical_json(to_wire(scope.permit)), None):
                    raise UnavailableGuard("D13 schedule recovery lacks original permit")
                result = reader()
            if (port.validate_fence(scope) != scope.permit
                    or observe_owner(scope) != observed_guard):
                raise UnavailableGuard("D13 schedule recovery authorization changed")
            return result
        # A crash after beginning the worker write blocks a new read fence.
        # Reuse only that exact live write permit for a fresh current window.
        scope = _worker_scope
        if (type(scope) is not FenceScope or scope.namespace != namespace
                or scope.operation != "write" or scope.permit.holder != self.__holder
                or scope.generation != authority.activation_generation):
            raise UnavailableGuard("D13 recovery write scope differs; HOLD")
        if port.validate_fence(scope) != scope.permit:
            raise UnavailableGuard("D13 recovery write fence changed; HOLD")
        observed_guard = observe_owner(scope)
        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
            if (metadata.graph_revision != scope.graph_revision
                    or epoch != scope.graph_epoch
                    or metadata.requirements.authority_namespace
                    != scope.authority_namespace):
                raise StaleRead("D13 recovery window graph head changed")
            from .authority_service.v2_contract import to_wire
            worker_row = store._db.execute(
                "SELECT permit_json,receipt_json FROM graph_d13_worker_attempts_v2 "
                "WHERE bot=? AND persona=? AND attempt_id=?",
                namespace.as_tuple + (scope.operation_id,)).fetchone()
            if worker_row != (canonical_json(to_wire(scope.permit)), None):
                raise UnavailableGuard("D13 recovery window has no original worker permit")
            result = reader()
        if (port.validate_fence(scope) != scope.permit
                or observe_owner(scope) != observed_guard):
            raise UnavailableGuard("D13 recovery window authorization changed")
        return result

    def _d13_precompression_ledger_locked_v2(
            self, namespace: NamespaceId, conversation_ref: str,
            trusted_now_utc: float) -> tuple[bool, frozenset[str]]:
        """Read original D11 jobs and current standby caches in the held SQL view."""
        from .runtime.d13_precompression_job import plan_from_precompression_job_v1

        store = self.__store
        if not store._lock._is_owned() or not store._db.in_transaction:
            raise RuntimeError("D13 scheduler ledger requires a graph transaction")
        db = store._db
        attempted: set[str] = set()
        outstanding = False
        rows = db.execute(
            "SELECT job_id FROM runtime_jobs WHERE bot_id=? AND persona_id=? "
            "AND work_kind='d13.precompress'", namespace.as_tuple,
        ).fetchall()
        for (job_id,) in rows:
            job = get_job(db, job_id)
            if job.continuation.get("conversation_ref") != conversation_ref:
                continue
            try:
                plan = plan_from_precompression_job_v1(job)
            except ValueError as exc:
                raise UnavailableGuard("D13 original job ledger is invalid; HOLD") from exc
            attempted.add(plan.input_digest)
            if job.phase in {"queued", "waiting", "running", "deferred"}:
                outstanding = True
        blocks = db.execute(
            "SELECT value FROM graph_atoms WHERE bot=? AND persona=? "
            "AND type_name='d13.compressed_turn_block.v2' AND valid=1",
            namespace.as_tuple,
        ).fetchall()
        for (encoded,) in blocks:
            value = json.loads(encoded)
            if (value.get("conversation_ref") == conversation_ref
                    and value.get("status") in {"standby", "active"}
                    and type(value.get("expires_at_utc")) in (int, float)
                    and trusted_now_utc < value["expires_at_utc"]):
                outstanding = True
        return outstanding, frozenset(attempted)

    def _replay_d13_precompression_schedule_v2(
            self, authority: AuthorityContext, scene_ref: str,
            original_operation_id: str):
        """Return only the exact original receipt; never issue another job."""
        from .authority_service.v2_contract import from_wire
        from .runtime.d13_precompression_job import plan_from_precompression_job_v1
        from .runtime.restore_anchor import RestoreAnchor

        store = self.__store
        policy = self.__d13_precompression_policy
        port = self.__content_fence_v2
        namespace = authority.namespace
        with store._lock:
            db = store._db
            row = db.execute(
                "SELECT intent_digest,attempt_id,anchor_json,pre_graph_revision,"
                "pre_graph_epoch,permit_json,finish_request_id,"
                "finish_request_digest,receipt_json FROM "
                "graph_d13_precompression_attempts_v2 WHERE bot=? AND persona=? "
                "AND operation_id=?", namespace.as_tuple + (original_operation_id,),
            ).fetchone()
            if row is None or row[8] is None:
                raise UnavailableGuard("D13 original schedule is unresolved; HOLD")
            payload = json.loads(row[8])
            budget = BudgetReceipt(**payload["budget"])
            original_job = PersistentJob(**payload["job"])
            current_job = get_job(db, original_job.job_id)
            plan = plan_from_precompression_job_v1(original_job)
            if (payload.get("intent_digest") != row[0]
                    or original_job.operation_id != original_operation_id
                    or original_job.work_kind != policy.work_kind
                    or original_job.budget_ref != policy.lease_id
                    or (original_job.bot_id, original_job.persona_id) != namespace.as_tuple
                    or payload.get("requested_scene_ref") != scene_ref
                    or current_job.operation_id != original_operation_id
                    or current_job.work_kind != original_job.work_kind
                    or budget.operation_id != original_operation_id
                    or budget.lease_id != policy.lease_id
                    or budget.status != "reserved"
                    or row[5] is None or row[6] is None or row[7] is None):
                raise UnavailableGuard("D13 original schedule receipt differs; HOLD")
            job_operation = "job:" + canonical_digest({
                "operation_id": original_operation_id,
                "job_id": original_job.job_id,
            })[:32]
            created = db.execute(
                "SELECT job_json FROM runtime_job_operations WHERE bot_id=? "
                "AND persona_id=? AND operation_id=? AND phase='create'",
                namespace.as_tuple + (job_operation,),
            ).fetchone()
            if (created is None or
                    canonical_digest(json.loads(created[0])) !=
                    canonical_digest(asdict(original_job))):
                raise UnavailableGuard("D13 original durable job differs; HOLD")
            reservation = db.execute(
                "SELECT digest,ceiling_json FROM runtime_budget_reservations "
                "WHERE lease_id=? AND operation_id=?",
                (policy.lease_id, original_operation_id),
            ).fetchone()
            if (reservation is None or reservation[0] != budget.digest
                    or json.loads(reservation[1]) != dict(policy.quote_ceiling)):
                raise UnavailableGuard("D13 original reservation differs; HOLD")
            historical, _ = self.__d11_issuer.signed_budget_grant_at_version(
                db, policy.lease_id, policy.grant_version)
            if ((historical.grant_id, historical.version, historical.lease_id,
                 historical.bot_id, historical.persona_id) !=
                    (policy.grant_id, policy.grant_version, policy.lease_id,
                     *namespace.as_tuple)):
                raise UnavailableGuard("D13 original signed grant differs; HOLD")
        anchor = RestoreAnchor(**json.loads(row[2]))
        permit = from_wire(json.loads(row[5]))
        observed, state = port.get_fence_operation(
            namespace=namespace, authority_namespace=anchor.namespace,
            operation_id=row[1])
        if (observed != permit or state not in {"active", "finished"}
                or permit.pinned_anchor != anchor):
            raise UnavailableGuard("D13 original write fence differs; HOLD")
        if state == "active":
            scope = FenceScope(
                namespace, anchor.namespace,
                authority.activation_generation, "write", row[1], permit,
                anchor, NamespaceEpoch(*namespace.as_tuple, row[4]), row[3])
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("D13 original write permit changed; HOLD")
            port.finish_fence(scope, request_id=row[6], request_digest=row[7])
        with store._lock:
            store._db.execute(
                "UPDATE graph_d13_precompression_attempts_v2 SET "
                "finish_confirmed=1 WHERE bot=? AND persona=? AND "
                "operation_id=? AND receipt_json IS NOT NULL",
                namespace.as_tuple + (original_operation_id,),
            )
        return budget, original_job

    def _check_d13_schedule_inputs_locked_v2(
            self, namespace: NamespaceId, window, policy, input_digest: str,
            *, activation_generation: int, now_utc: float,
            deadline_utc: float):
        """Recheck source, absence, and signed D11 head in one SQL view."""
        store = self.__store
        if not store._lock._is_owned() or not store._db.in_transaction:
            raise RuntimeError("D13 schedule check requires a graph transaction")
        db = store._db
        for ref in window.read_set:
            row = db.execute(
                "SELECT revision,valid FROM graph_atoms WHERE token=?",
                (ref.ref,),
            ).fetchone()
            if (row is not None if ref.version == 0 else row != (ref.version, 1)):
                raise StaleRead("D13 schedule source read set changed")
        authority_epochs = db.execute(
            "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
            "WHERE bot=? AND persona=?", namespace.as_tuple,
        ).fetchone()
        if (authority_epochs != (window.access_epoch, window.delete_epoch)
                or window.activation_epoch != activation_generation):
            raise StaleRead("D13 schedule access or activation changed")
        busy, attempted = self._d13_precompression_ledger_locked_v2(
            namespace, window.conversation_ref, now_utc)
        if busy or input_digest in attempted:
            raise StaleRead("D13 precompression already attempted or outstanding")
        grant = self.__d11_issuer.current_budget_grant(db, policy.lease_id)
        budget_lease = get_budget_lease(db, policy.lease_id)
        if ((grant.grant_id, grant.version, grant.lease_id,
             grant.bot_id, grant.persona_id) !=
                (policy.grant_id, policy.grant_version, policy.lease_id,
                 *namespace.as_tuple)
                or budget_lease.parent_id is not None
                or budget_lease.state != "active"
                or (budget_lease.bot_id, budget_lease.persona_id)
                != namespace.as_tuple
                or grant.valid_until_utc < deadline_utc
                or policy.work_kind not in grant.allowed_work_kinds
                or any(amount > grant.max_ceiling.get(name, 0)
                       or amount > budget_lease.available(name)
                       for name, amount in policy.quote_ceiling.items())):
            raise UnavailableGuard("D13 installed D11 technical grant or budget unavailable; HOLD")
        return grant

    def _commit_d13_schedule_business_locked_v2(
            self, namespace: NamespaceId, window, policy, intent, job,
            scene_ref: str, scope: FenceScope, metadata,
            epoch: NamespaceEpoch, now_utc: float, deadline_utc: float,
    ) -> tuple[BudgetReceipt, PersistentJob]:
        """One fenced SQL transaction body shared by first run and recovery."""
        store = self.__store
        if not store._lock._is_owned() or not store._db.in_transaction:
            raise RuntimeError("D13 original schedule needs held business transaction")
        db = store._db
        operation_id = job.operation_id
        if self._v2_graph_stamp(namespace) != (metadata, epoch):
            raise StaleRead("D13 schedule graph head changed")
        from .authority_service.v2_contract import to_wire
        saved = db.execute(
            "SELECT attempt_id,intent_digest,permit_json,receipt_json,rejected_json "
            "FROM graph_d13_precompression_attempts_v2 WHERE bot=? AND "
            "persona=? AND operation_id=?",
            namespace.as_tuple + (operation_id,),
        ).fetchone()
        if (saved != (scope.operation_id, intent.intent_digest,
                     canonical_json(to_wire(scope.permit)), None, None)):
            raise UnavailableGuard("D13 original schedule seal differs; HOLD")
        grant = self._check_d13_schedule_inputs_locked_v2(
            namespace, window, policy, intent.plan.input_digest,
            activation_generation=scope.generation,
            now_utc=now_utc, deadline_utc=deadline_utc)
        digest = canonical_digest({
            "schema": "d13.deterministic-schedule.v2",
            "intent_digest": intent.intent_digest,
            "grant_id": grant.grant_id, "grant_version": grant.version,
            "installation_id": policy.installation_id,
            "ceiling": dict(policy.quote_ceiling),
        })
        budget_receipt = reserve_budget(
            db, policy.lease_id, operation_id, digest,
            dict(policy.quote_ceiling))
        job_operation = "job:" + canonical_digest({
            "operation_id": operation_id, "job_id": job.job_id,
        })[:32]
        persisted = create_job(db, job, job_operation, digest)
        payload = {
            "intent_digest": intent.intent_digest,
            "requested_scene_ref": scene_ref,
            "budget": asdict(budget_receipt), "job": asdict(persisted),
        }
        db.execute(
            "UPDATE graph_d13_precompression_attempts_v2 SET receipt_json=? "
            "WHERE bot=? AND persona=? AND operation_id=? AND receipt_json IS NULL",
            (canonical_json(payload), *namespace.as_tuple, operation_id),
        )
        if db.execute("SELECT changes()").fetchone() != (1,):
            raise EventConflict("D13 original schedule receipt already sealed")
        return budget_receipt, persisted

    def _d13_schedule_commit_clock_locked_v2(
            self, installation, window_utc: float, deadline_utc: float,
            expires_at_utc: float) -> float:
        """Sample after acquiring the graph lock, immediately before BEGIN."""
        from .host.v2_fence_port import VerifiedIngressClockV2
        from .runtime.first_ingress_v2 import trusted_upper

        store = self.__store
        if not store._lock._is_owned() or store._db.in_transaction:
            raise RuntimeError("D13 commit clock requires graph lock outside SQL")
        clock = self.__content_fence_v2.read_ingress_clock(
            self.__scene_clock_policy)
        if (type(clock) is not VerifiedIngressClockV2
                or clock.sample.authority_id != installation.authority_id
                or clock.sample.installation_id != installation.installation_id
                or clock.sample.source_id != self.__scene_clock_policy.source_id):
            raise UnavailableGuard("D13 commit paired clock changed; HOLD")
        now_utc = trusted_upper(clock)
        if (now_utc < window_utc or now_utc >= deadline_utc
                or now_utc >= expires_at_utc):
            raise UnavailableGuard("D13 original schedule deadline elapsed; HOLD")
        return now_utc

    def _d13_schedule_recovery_row_v2(self, namespace: NamespaceId,
                                      original_operation_id: str):
        """Decode only a namespace-local, sealed original intent."""
        from .runtime.d13_precompression_job import (
            D13PrecompressionIntentV1, plan_from_precompression_job_v1,
        )
        from .runtime.d13_technical_policy import D13ScheduleRecoveryItemV2

        policy = self.__d13_precompression_policy
        with self.__store._lock:
            row = self.__store._db.execute(
                "SELECT intent_digest,intent_json,attempt_id,anchor_json,"
                "pre_graph_revision,pre_graph_epoch,permit_json,"
                "finish_request_id,finish_request_digest,receipt_json,"
                "finish_confirmed,rejected_json FROM "
                "graph_d13_precompression_attempts_v2 "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (original_operation_id,),
            ).fetchone()
        if row is None:
            raise UnavailableGuard("D13 original schedule attempt absent; HOLD")
        try:
            frozen = json.loads(row[1])
            job = PersistentJob(**frozen["job"])
            intent = D13PrecompressionIntentV1(
                plan_from_precompression_job_v1(job), job,
                frozen["ceiling"], frozen["intent_digest"])
            item = D13ScheduleRecoveryItemV2(
                original_operation_id,
                job.continuation["conversation_ref"],
                frozen["requested_scene_ref"])
        except (KeyError, TypeError, ValueError) as exc:
            raise UnavailableGuard("D13 original schedule intent invalid; HOLD") from exc
        if (row[0] != intent.intent_digest or
                row[1] != canonical_json(frozen) or
                job.operation_id != original_operation_id or
                (job.bot_id, job.persona_id) != namespace.as_tuple or
                job.work_kind != policy.work_kind or
                job.budget_ref != policy.lease_id or
                job.resource_ref != policy.resource_ref or
                job.operator_versions != {"d13_compiler": policy.compiler_version} or
                dict(intent.ceiling) != dict(policy.quote_ceiling) or
                row[2] != "d13-precompression-" + canonical_digest({
                    "namespace": namespace.as_tuple,
                    "operation_id": original_operation_id,
                    "intent_digest": intent.intent_digest,
                })[:48]):
            raise UnavailableGuard("D13 original schedule identity differs; HOLD")
        return row, intent, item

    def discover_d13_precompression_schedule_attempts_v2(
            self, authority: AuthorityContext, lease: object,
    ):
        """Reveal only original IDs and route metadata in the installed namespace.

        D11 may call this with an empty audience, before it knows the original
        conversation. Actual recovery requires a new authority context for the
        saved conversation and verifies that route again.
        """
        from .runtime.d13_technical_policy import AdminD13PrecompressionPolicyV1

        policy = self.__d13_precompression_policy
        port = self.__content_fence_v2
        if (not isinstance(self.__store, ProductionGraphStore) or port is None
                or type(policy) is not AdminD13PrecompressionPolicyV1):
            raise UnavailableGuard("installed D13 recovery authorities absent; HOLD")
        self._authorize(lease, authority, frozenset({"d11"}))
        if (authority.issuer_domain != "d11" or authority.purpose != "context"
                or authority.worker_fence is not None
                or authority.audience and len(authority.audience) != 1
                or authority.namespace != policy.namespace
                or policy.installation_id != port.installation_grant.installation_id):
            raise AuthorityDenied("D13 discovery differs from installed D11 context")
        with self.__store._lock:
            rows = self.__store._db.execute(
                "SELECT a.operation_id FROM graph_d13_precompression_attempts_v2 a "
                "WHERE a.bot=? AND a.persona=? AND "
                "((a.receipt_json IS NULL AND a.rejected_json IS NULL) "
                "OR a.finish_confirmed=0 OR EXISTS ("
                "SELECT 1 FROM runtime_jobs WHERE runtime_jobs.bot_id=a.bot "
                "AND runtime_jobs.persona_id=a.persona AND "
                "runtime_jobs.job_id=a.operation_id AND "
                "runtime_jobs.phase IN ('queued','running'))) "
                "ORDER BY a.rowid LIMIT 65", authority.namespace.as_tuple,
            ).fetchall()
        if len(rows) > 64:
            raise UnavailableGuard("D13 unresolved attempt scan exceeds bound; HOLD")
        items = []
        for (operation_id,) in rows:
            _, _, item = self._d13_schedule_recovery_row_v2(
                authority.namespace, operation_id)
            if authority.audience and authority.audience != (item.conversation_ref,):
                continue
            items.append(item)
        return tuple(items)

    def _reject_d13_schedule_without_commit_v2(
            self, namespace: NamespaceId, original_operation_id: str,
            scope: FenceScope, reason: str) -> None:
        """Seal a known no-commit rejection before finishing its original fence."""
        from .authority_service.v2_contract import to_wire

        permit = scope.permit
        request_id = "reject:" + scope.operation_id
        request_digest = "sha256:" + canonical_digest({
            "operation_id": scope.operation_id,
            "permit_token": permit.token,
            "action": "reject_d13_precompression_schedule",
        })
        rejected = canonical_json({
            "status": "rejected_no_commit", "reason": reason,
            "request_id": request_id, "request_digest": request_digest,
        })
        store = self.__store
        with store._lock:
            db = store._db
            db.execute("BEGIN IMMEDIATE")
            try:
                row = db.execute(
                    "SELECT permit_json,receipt_json,rejected_json FROM "
                    "graph_d13_precompression_attempts_v2 WHERE bot=? "
                    "AND persona=? AND operation_id=?",
                    namespace.as_tuple + (original_operation_id,),
                ).fetchone()
                reserved = db.execute(
                    "SELECT 1 FROM runtime_budget_reservations WHERE "
                    "lease_id=? AND operation_id=?",
                    (self.__d13_precompression_policy.lease_id,
                     original_operation_id),
                ).fetchone()
                job = db.execute(
                    "SELECT 1 FROM runtime_jobs WHERE bot_id=? AND "
                    "persona_id=? AND operation_id=?",
                    namespace.as_tuple + (original_operation_id,),
                ).fetchone()
                if (row is None or row[0] != canonical_json(to_wire(permit))
                        or row[1] is not None or row[2] not in (None, rejected)
                        or reserved is not None or job is not None):
                    raise UnavailableGuard("D13 no-commit rejection is uncertain; HOLD")
                db.execute(
                    "UPDATE graph_d13_precompression_attempts_v2 SET "
                    "rejected_json=? WHERE bot=? AND persona=? AND operation_id=?",
                    (rejected, *namespace.as_tuple, original_operation_id),
                )
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise
        self.__content_fence_v2.finish_fence(
            scope, request_id=request_id, request_digest=request_digest)
        with store._lock:
            store._db.execute(
                "UPDATE graph_d13_precompression_attempts_v2 SET "
                "finish_confirmed=1 WHERE bot=? AND persona=? AND "
                "operation_id=? AND rejected_json=?",
                namespace.as_tuple + (original_operation_id, rejected),
            )

    def _replay_d13_schedule_rejection_v2(
            self, namespace: NamespaceId, original_operation_id: str,
            row, authority: AuthorityContext) -> None:
        """Resolve an uncertain reject finish without mistaking it for a job."""
        from .authority_service.v2_contract import from_wire
        from .runtime.restore_anchor import RestoreAnchor

        try:
            rejected = json.loads(row[11])
            anchor = RestoreAnchor(**json.loads(row[3]))
            permit = from_wire(json.loads(row[6]))
            expected_id = "reject:" + row[2]
            expected_digest = "sha256:" + canonical_digest({
                "operation_id": row[2], "permit_token": permit.token,
                "action": "reject_d13_precompression_schedule",
            })
        except (TypeError, ValueError, KeyError) as exc:
            raise UnavailableGuard("D13 rejection seal invalid; HOLD") from exc
        if (rejected.get("status") != "rejected_no_commit"
                or rejected.get("request_id") != expected_id
                or rejected.get("request_digest") != expected_digest
                or permit.pinned_anchor != anchor):
            raise UnavailableGuard("D13 rejection identity differs; HOLD")
        with self.__store._lock:
            db = self.__store._db
            if (db.execute(
                    "SELECT 1 FROM runtime_budget_reservations WHERE "
                    "lease_id=? AND operation_id=?",
                    (self.__d13_precompression_policy.lease_id,
                     original_operation_id),
                ).fetchone() is not None or db.execute(
                    "SELECT 1 FROM runtime_jobs WHERE bot_id=? AND "
                    "persona_id=? AND operation_id=?",
                    namespace.as_tuple + (original_operation_id,),
                ).fetchone() is not None):
                raise UnavailableGuard("D13 rejected attempt has business commit; HOLD")
        port = self.__content_fence_v2
        observed, state = port.get_fence_operation(
            namespace=namespace, authority_namespace=anchor.namespace,
            operation_id=row[2])
        if observed != permit or state not in {"active", "finished"}:
            raise UnavailableGuard("D13 rejected original fence differs; HOLD")
        if state == "active":
            scope = FenceScope(
                namespace, anchor.namespace, authority.activation_generation,
                "write", row[2], permit, anchor,
                NamespaceEpoch(*namespace.as_tuple, row[5]), row[4])
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("D13 rejected original permit changed; HOLD")
            port.finish_fence(
                scope, request_id=expected_id,
                request_digest=expected_digest)
        with self.__store._lock:
            self.__store._db.execute(
                "UPDATE graph_d13_precompression_attempts_v2 SET "
                "finish_confirmed=1 WHERE bot=? AND persona=? AND "
                "operation_id=? AND rejected_json=?",
                namespace.as_tuple + (original_operation_id, row[11]),
            )
        raise UnavailableGuard("D13 original schedule was rejected without commit; HOLD")

    def recover_d13_precompression_schedule_v2(
            self, authority: AuthorityContext, lease: object, *,
            original_operation_id: str,
    ) -> tuple[BudgetReceipt, PersistentJob]:
        """Finish the exact original D13 write or commit it under that permit."""
        from .authority_service.v2_contract import FencePermitV2, from_wire, to_wire
        from .host.authority_profile import AdminIngressClockPolicy
        from .host.v2_fence_port import VerifiedIngressClockV2
        from .runtime.d13_precompression_job import prepare_precompression_intent_v1
        from .runtime.d13_technical_policy import AdminD13PrecompressionPolicyV1
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.restore_anchor import RestoreAnchor

        store = self.__store
        port = self.__content_fence_v2
        policy = self.__d13_precompression_policy
        if (not isinstance(store, ProductionGraphStore) or port is None
                or type(policy) is not AdminD13PrecompressionPolicyV1
                or type(self.__scene_clock_policy) is not AdminIngressClockPolicy):
            raise UnavailableGuard("installed D13 recovery authorities absent; HOLD")
        self._authorize(lease, authority, frozenset({"d11"}))
        namespace = authority.namespace
        if (type(original_operation_id) is not str or not original_operation_id
                or authority.issuer_domain != "d11" or authority.purpose != "context"
                or authority.worker_fence is not None
                or namespace != policy.namespace
                or policy.installation_id != port.installation_grant.installation_id):
            raise AuthorityDenied("D13 recovery differs from installed D11 context")
        row, intent, item = self._d13_schedule_recovery_row_v2(
            namespace, original_operation_id)
        if authority.audience != (item.conversation_ref,):
            raise AuthorityDenied("D13 recovery requires original conversation audience")
        if row[11] is not None:
            self._replay_d13_schedule_rejection_v2(
                namespace, original_operation_id, row, authority)
        if row[9] is not None:
            return self._replay_d13_precompression_schedule_v2(
                authority, item.scene_ref, original_operation_id)

        anchor = RestoreAnchor(**json.loads(row[3]))
        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
        original_epoch = NamespaceEpoch(*namespace.as_tuple, row[5])
        graph_head_changed = (
            metadata.graph_revision != row[4] or epoch != original_epoch or
            metadata.requirements.authority_namespace != anchor.namespace or
            metadata.requirements.activation_generation
            != authority.activation_generation or
            not self._anchor_matches(metadata.requirements, anchor))
        if row[6] is None:
            # begin_fence is exact-ID idempotent for an active Authority write.
            # It also covers a crash between durable local intent and begin.
            permit = port.begin_fence(
                namespace=namespace, authority_namespace=anchor.namespace,
                holder=self.__holder, generation=authority.activation_generation,
                operation="write", operation_id=row[2], expected_anchor=anchor,
                retain_on_unknown=True)
        else:
            permit, state = port.get_fence_operation(
                namespace=namespace, authority_namespace=anchor.namespace,
                operation_id=row[2])
            if state != "active":
                raise UnavailableGuard("D13 original schedule is not active; HOLD")
        if (type(permit) is not FencePermitV2
                or row[6] is not None and row[6] != canonical_json(to_wire(permit))
                or permit.operation_id != row[2] or permit.operation != "write"
                or permit.holder != self.__holder or permit.pinned_anchor != anchor):
            raise UnavailableGuard("D13 original schedule permit differs; HOLD")
        scope = FenceScope(
            namespace, anchor.namespace, authority.activation_generation,
            "write", row[2], permit, anchor, original_epoch, row[4])
        finish_id = "finish:" + row[2]
        finish_digest = "sha256:" + canonical_digest({
            "operation_id": row[2], "permit_token": permit.token,
            "action": "finish_d13_precompression_schedule",
            "original_operation_id": original_operation_id,
        })
        if (row[7] is not None and row[7:9] != (finish_id, finish_digest)
                or not graph_head_changed and
                port.validate_fence(scope) != permit):
            raise UnavailableGuard("D13 original schedule finish scope differs; HOLD")
        with store._lock:
            db = store._db
            db.execute("BEGIN IMMEDIATE")
            try:
                current = db.execute(
                    "SELECT permit_json,finish_request_id,finish_request_digest,"
                    "receipt_json FROM graph_d13_precompression_attempts_v2 "
                    "WHERE bot=? AND persona=? AND operation_id=?",
                    namespace.as_tuple + (original_operation_id,),
                ).fetchone()
                if (current is None or current[3] is not None or
                        current[0] not in (None, canonical_json(to_wire(permit))) or
                        current[1] not in (None, finish_id) or
                        current[2] not in (None, finish_digest)):
                    raise UnavailableGuard("D13 original attempt changed; HOLD")
                db.execute(
                    "UPDATE graph_d13_precompression_attempts_v2 SET "
                    "permit_json=?,finish_request_id=?,finish_request_digest=? "
                    "WHERE bot=? AND persona=? AND operation_id=?",
                    (canonical_json(to_wire(permit)), finish_id, finish_digest,
                     *namespace.as_tuple, original_operation_id),
                )
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise
        with store._lock:
            graph_head_changed = (
                graph_head_changed or self._v2_graph_stamp(namespace)
                != (metadata, epoch))
        if graph_head_changed:
            self._reject_d13_schedule_without_commit_v2(
                namespace, original_operation_id, scope, "graph_head_changed")
            raise UnavailableGuard("D13 original schedule graph head changed; HOLD")
        commit_attempted = False
        try:
            window = self.read_current_d13_conversation_window_v1(
                authority, lease, scene_ref=item.scene_ref,
                max_slots=policy.max_slots, _schedule_scope=scope)
            deadline = datetime.fromisoformat(
                intent.job.deadline_utc.replace("Z", "+00:00")).timestamp()
            if (window.namespace != namespace or
                    window.conversation_ref != item.conversation_ref or
                    not window.turns or window.missing_ranges or
                    not window.trusted_utc < deadline <= intent.plan.expires_at_utc):
                raise UnavailableGuard("D13 recovery current window differs; HOLD")
            current_intent = prepare_precompression_intent_v1(
                window, history_token_budget=policy.history_token_budget,
                background_capacity=True, outstanding_candidate=False,
                attempted_input_digests=frozenset(),
                parent_budget_lease_ref=policy.lease_id,
                resource_ref=policy.resource_ref,
                ceiling=dict(policy.quote_ceiling), deadline_utc=deadline)
            if current_intent != intent:
                raise UnavailableGuard("D13 recovery original plan or source differs; HOLD")
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("D13 original schedule fence changed; HOLD")
            job = replace(intent.job, operator_versions={
                "d13_compiler": policy.compiler_version,
                "d11_grant": f"{policy.grant_id}:{policy.grant_version}",
                "installation_id": policy.installation_id,
            })
            with store._lock:
                now_utc = self._d13_schedule_commit_clock_locked_v2(
                    port.installation_grant, window.trusted_utc, deadline,
                    intent.plan.expires_at_utc)
                db = store._db
                db.execute("BEGIN IMMEDIATE")
                try:
                    result = self._commit_d13_schedule_business_locked_v2(
                        namespace, window, policy, intent, job, item.scene_ref,
                        scope, metadata, epoch, now_utc, deadline)
                    commit_attempted = True
                    db.execute("COMMIT")
                except BaseException:
                    if db.in_transaction:
                        db.execute("ROLLBACK")
                    raise
        except Exception as exc:
            if not commit_attempted:
                self._reject_d13_schedule_without_commit_v2(
                    namespace, original_operation_id, scope,
                    "current_window_or_budget_invalid")
            raise exc
        port.finish_fence(scope, request_id=finish_id,
                          request_digest=finish_digest)
        with store._lock:
            store._db.execute(
                "UPDATE graph_d13_precompression_attempts_v2 SET "
                "finish_confirmed=1 WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (original_operation_id,),
            )
        return result

    def schedule_d13_paid_precompression_v1(self, authority, lease, *, scene_ref):
        """Schedule or recover one installed independent paid D13 original."""
        from .runtime.d13_paid_product_v1 import schedule_d13_paid_precompression_graph_v1
        return schedule_d13_paid_precompression_graph_v1(
            self, authority, lease, scene_ref=scene_ref)

    def prepare_d13_paid_call_v1(self, authority, lease, *, job_id,
                                 timeout_seconds, privacy_tier, lease_seconds=300):
        """Acquire and seal the original worker, or return recovery-only identity."""
        from .runtime.d13_paid_product_v1 import prepare_d13_paid_call_graph_v1
        return prepare_d13_paid_call_graph_v1(
            self, authority, lease, job_id=job_id, timeout_seconds=timeout_seconds,
            privacy_tier=privacy_tier, lease_seconds=lease_seconds)

    def record_d13_paid_result_read_v1(self, authority, lease, *, job_id, intent, read):
        """Authenticate original terminal and persist its read before settlement."""
        from .runtime.d13_paid_product_v1 import record_d13_paid_read_graph_v1
        return record_d13_paid_read_graph_v1(
            self, authority, lease, job_id=job_id, intent=intent, read=read)

    def settle_d13_paid_precompression_v1(self, authority, lease, *, job_id):
        """Commit the original paid cost once using its saved Authority evidence."""
        from .runtime.d13_paid_product_v1 import settle_d13_paid_graph_v1
        return settle_d13_paid_graph_v1(self, authority, lease, job_id=job_id)

    def complete_d13_paid_precompression_v1(self, authority, lease, *, job_id, selected_main):
        """Recheck current source/model and atomically complete job plus standby."""
        from .runtime.d13_paid_product_v1 import complete_d13_paid_graph_v1
        return complete_d13_paid_graph_v1(
            self, authority, lease, job_id=job_id, selected_main=selected_main)

    def recover_d13_paid_precompression_v1(self, authority, lease, *, job_id):
        """Return only durable original recovery actions; never replace a call."""
        from .runtime.d13_paid_product_v1 import recover_d13_paid_graph_v1
        return recover_d13_paid_graph_v1(self, authority, lease, job_id=job_id)

    def schedule_d13_deterministic_precompression_v2(
            self, authority: AuthorityContext, lease: object, *,
            scene_ref: str, original_operation_id: str | None = None,
    ) -> tuple[BudgetReceipt, PersistentJob] | None:
        """Reserve one installed D11 technical unit and queue its original D13 job.

        Only a deterministic compiler is admitted.  The original V2 write
        attempt is persisted before Authority sees it; uncertain outcomes are
        reconciled by passing its original operation ID on retry.
        """
        from .authority_service.v2_contract import FencePermitV2, from_wire, to_wire
        from .host.authority_profile import AdminIngressClockPolicy
        from .host.v2_fence_port import VerifiedIngressClockV2
        from .runtime.d13_precompression_job import (
            D13PrecompressionIntentV1, plan_from_precompression_job_v1,
            prepare_precompression_intent_v1,
        )
        from .runtime.d13_technical_policy import AdminD13PrecompressionPolicyV1
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.restore_anchor import RestoreAnchor

        store = self.__store
        port = self.__content_fence_v2
        policy = self.__d13_precompression_policy
        if (not isinstance(store, ProductionGraphStore) or port is None
                or type(self.__scene_clock_policy) is not AdminIngressClockPolicy
                or type(policy) is not AdminD13PrecompressionPolicyV1
                or not callable(getattr(self.__d11_issuer, "current_budget_grant", None))):
            raise UnavailableGuard("installed D13 technical schedule authorities absent; HOLD")
        self._authorize(lease, authority, frozenset({"d11"}))
        namespace = authority.namespace
        installation = port.installation_grant
        if (authority.issuer_domain != "d11" or authority.purpose != "context"
                or authority.worker_fence is not None
                or len(authority.audience) != 1
                or type(scene_ref) is not str or not scene_ref.startswith("scene:")
                or policy.namespace != namespace
                or policy.installation_id != installation.installation_id):
            raise AuthorityDenied("D13 schedule differs from installed D11 context")
        if original_operation_id is not None:
            if type(original_operation_id) is not str or not original_operation_id:
                raise TypeError("original D13 operation ID required for replay")
            _, _, original_item = self._d13_schedule_recovery_row_v2(
                namespace, original_operation_id)
            if original_item.scene_ref != scene_ref:
                raise AuthorityDenied("D13 original scene differs from request")
            return self.recover_d13_precompression_schedule_v2(
                authority, lease, original_operation_id=original_operation_id)

        # A committed job or uncertain finish may outlive the original caller.
        # Reconcile its original attempt before a normal read fence, which
        # would be blocked while the original write is still active.
        matching = tuple(item for item in
                         self.discover_d13_precompression_schedule_attempts_v2(
                             authority, lease) if item.scene_ref == scene_ref)
        if len(matching) > 1:
            raise UnavailableGuard("multiple original D13 schedules need recovery; HOLD")
        if matching:
            return self.recover_d13_precompression_schedule_v2(
                authority, lease,
                original_operation_id=matching[0].original_operation_id)

        window = self.read_current_d13_conversation_window_v1(
            authority, lease, scene_ref=scene_ref, max_slots=policy.max_slots)
        # A bounded page with any known gap cannot establish the oldest
        # complete eligible prefix. Leave it as raw context for this slice.
        if not window.turns or window.missing_ranges:
            return None
        replay_existing = False
        saved_permit_json = None
        with store._lock:
            db = store._db
            db.execute("BEGIN")
            try:
                outstanding, attempted = self._d13_precompression_ledger_locked_v2(
                    namespace, window.conversation_ref, window.trusted_utc)
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise
        deadline = min(window.trusted_utc + policy.deadline_after_seconds,
                       min(turn.trusted_utc for turn in window.turns) + 72 * 3600)
        # The plan may cover fewer turns than the page. The pure intent checks
        # its exact earliest-turn expiry again after selecting the prefix.
        if deadline <= window.trusted_utc:
            return None
        intent = prepare_precompression_intent_v1(
            window, history_token_budget=policy.history_token_budget,
            background_capacity=True, outstanding_candidate=outstanding,
            attempted_input_digests=attempted,
            parent_budget_lease_ref=policy.lease_id,
            resource_ref=policy.resource_ref,
            ceiling=dict(policy.quote_ceiling), deadline_utc=deadline)
        if intent is None:
            return None
        with store._lock:
            prior_intent = store._db.execute(
                "SELECT intent_json FROM graph_d13_precompression_attempts_v2 "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (intent.plan.job_ref,),
            ).fetchone()
        if prior_intent is not None:
            try:
                original = json.loads(prior_intent[0])
                original_job = PersistentJob(**original["job"])
                original_plan = plan_from_precompression_job_v1(original_job)
                restored = D13PrecompressionIntentV1(
                    original_plan, original_job, original["ceiling"],
                    original["intent_digest"])
                original_deadline = datetime.fromisoformat(
                    original_job.deadline_utc.replace("Z", "+00:00")
                ).timestamp()
            except (KeyError, TypeError, ValueError) as exc:
                raise UnavailableGuard("original D13 schedule intent is invalid; HOLD") from exc
            if (restored.plan != intent.plan
                    or original.get("requested_scene_ref") != scene_ref
                    or restored.job.budget_ref != policy.lease_id
                    or restored.job.resource_ref != policy.resource_ref
                    or dict(restored.ceiling) != dict(policy.quote_ceiling)
                    or not window.trusted_utc < original_deadline
                    <= restored.plan.expires_at_utc):
                raise UnavailableGuard("original D13 schedule intent changed; HOLD")
            intent = restored
            deadline = original_deadline
        job = replace(intent.job, operator_versions={
            "d13_compiler": policy.compiler_version,
            "d11_grant": f"{policy.grant_id}:{policy.grant_version}",
            "installation_id": policy.installation_id,
        })
        operation_id = job.operation_id
        # Reject predictable stale/insufficient work before retaining a V2
        # write attempt. The same checks run again with reservation and job.
        with store._lock:
            db = store._db
            db.execute("BEGIN")
            try:
                self._check_d13_schedule_inputs_locked_v2(
                    namespace, window, policy, intent.plan.input_digest,
                    activation_generation=authority.activation_generation,
                    now_utc=window.trusted_utc, deadline_utc=deadline)
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise
        attempt_id = "d13-precompression-" + canonical_digest({
            "namespace": namespace.as_tuple, "operation_id": operation_id,
            "intent_digest": intent.intent_digest,
        })[:48]
        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
        target = metadata.requirements
        if target.namespace != namespace or target.activation_generation != authority.activation_generation:
            raise UnavailableGuard("D13 schedule graph recovery generation differs; HOLD")
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("D13 schedule recovery anchor differs; HOLD")
        with store._lock:
            db = store._db
            db.execute("BEGIN IMMEDIATE")
            try:
                if self._v2_graph_stamp(namespace) != (metadata, epoch):
                    raise StaleRead("D13 graph changed before original schedule attempt")
                prior = db.execute(
                    "SELECT intent_digest,attempt_id,anchor_json,pre_graph_revision,"
                    "pre_graph_epoch,receipt_json,permit_json,intent_json,"
                    "rejected_json FROM "
                    "graph_d13_precompression_attempts_v2 WHERE bot=? AND persona=? "
                    "AND operation_id=?", namespace.as_tuple + (operation_id,),
                ).fetchone()
                if prior is not None:
                    if prior[8] is not None:
                        raise UnavailableGuard(
                            "D13 original schedule was rejected without commit; HOLD")
                    if prior[0:2] != (intent.intent_digest, attempt_id):
                        raise EventConflict("D13 original operation reused with different intent")
                    if prior[7] != canonical_json({
                            "job": asdict(intent.job),
                            "ceiling": dict(intent.ceiling),
                            "intent_digest": intent.intent_digest,
                            "requested_scene_ref": scene_ref}):
                        raise EventConflict("D13 original frozen intent changed")
                    if prior[5] is not None:
                        replay_existing = True
                    if (RestoreAnchor(**json.loads(prior[2])) != anchor
                            or prior[3:5] != (metadata.graph_revision, epoch.revision)):
                        raise UnavailableGuard("pending D13 schedule lost original graph head; HOLD")
                    saved_permit_json = prior[6]
                else:
                    db.execute(
                        "INSERT INTO graph_d13_precompression_attempts_v2"
                        "(bot,persona,operation_id,intent_digest,intent_json,"
                        "attempt_id,anchor_json,pre_graph_revision,pre_graph_epoch) "
                        "VALUES(?,?,?,?,?,?,?,?,?)",
                        namespace.as_tuple + (
                            operation_id, intent.intent_digest,
                            canonical_json({"job": asdict(intent.job),
                                            "ceiling": dict(intent.ceiling),
                                            "intent_digest": intent.intent_digest,
                                            "requested_scene_ref": scene_ref}),
                            attempt_id, canonical_json(asdict(anchor)),
                            metadata.graph_revision, epoch.revision),
                    )
                db.execute("COMMIT")
            except BaseException:
                if db.in_transaction:
                    db.execute("ROLLBACK")
                raise
        if replay_existing:
            return self._replay_d13_precompression_schedule_v2(
                authority, scene_ref, operation_id)
        if saved_permit_json is None:
            permit = port.begin_fence(
                namespace=namespace, authority_namespace=target.authority_namespace,
                holder=self.__holder, generation=authority.activation_generation,
                operation="write", operation_id=attempt_id, expected_anchor=anchor,
                retain_on_unknown=True)
        else:
            permit = from_wire(json.loads(saved_permit_json))
            observed, state = port.get_fence_operation(
                namespace=namespace,
                authority_namespace=target.authority_namespace,
                operation_id=attempt_id)
            if observed != permit or state != "active":
                raise UnavailableGuard("pending D13 original write is unresolved; HOLD")
        if (type(permit) is not FencePermitV2 or permit.operation_id != attempt_id
                or permit.operation != "write" or permit.holder != self.__holder
                or permit.pinned_anchor != anchor):
            raise UnavailableGuard("D13 original schedule permit differs; HOLD")
        scope = FenceScope(
            namespace, target.authority_namespace,
            authority.activation_generation, "write", attempt_id,
            permit, anchor, epoch, metadata.graph_revision)
        finish_id = "finish:" + attempt_id
        finish_digest = "sha256:" + canonical_digest({
            "operation_id": attempt_id, "permit_token": permit.token,
            "action": "finish_d13_precompression_schedule",
            "original_operation_id": operation_id,
        })
        if port.validate_fence(scope) != permit:
            raise UnavailableGuard("D13 original schedule write fence changed; HOLD")
        with store._lock:
            db = store._db
            db.execute("BEGIN IMMEDIATE")
            try:
                row = db.execute(
                    "SELECT permit_json,finish_request_id,finish_request_digest "
                    "FROM graph_d13_precompression_attempts_v2 WHERE bot=? AND "
                    "persona=? AND operation_id=?", namespace.as_tuple + (operation_id,),
                ).fetchone()
                expected = (canonical_json(to_wire(permit)), finish_id, finish_digest)
                if row[0] is not None and row != expected:
                    raise UnavailableGuard("D13 original schedule permit changed; HOLD")
                db.execute(
                    "UPDATE graph_d13_precompression_attempts_v2 SET "
                    "permit_json=?,finish_request_id=?,finish_request_digest=? "
                    "WHERE bot=? AND persona=? AND operation_id=?",
                    expected + namespace.as_tuple + (operation_id,),
                )
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise
        failure = None
        commit_attempted = False
        try:
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("D13 original schedule write fence changed; HOLD")
            with store._lock:
                now_utc = self._d13_schedule_commit_clock_locked_v2(
                    installation, window.trusted_utc, deadline,
                    intent.plan.expires_at_utc)
                db = store._db
                db.execute("BEGIN IMMEDIATE")
                try:
                    budget_receipt, persisted = self._commit_d13_schedule_business_locked_v2(
                        namespace, window, policy, intent, job, scene_ref, scope,
                        metadata, epoch, now_utc, deadline)
                    commit_attempted = True
                    db.execute("COMMIT")
                except BaseException:
                    if db.in_transaction:
                        db.execute("ROLLBACK")
                    raise
        except BaseException as exc:
            failure = exc
        if failure is not None:
            if not commit_attempted and isinstance(failure, Exception):
                self._reject_d13_schedule_without_commit_v2(
                    namespace, operation_id, scope,
                    "current_window_or_budget_invalid")
            raise failure
        port.finish_fence(scope, request_id=finish_id,
                          request_digest=finish_digest)
        with store._lock:
            store._db.execute(
                "UPDATE graph_d13_precompression_attempts_v2 SET "
                "finish_confirmed=1 WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            )
        return budget_receipt, persisted

    def _d13_worker_replay_v2(self, authority, operation_id, request_digest):
        """Read an exact committed D13 worker result without requiring its old head."""
        from .authority_service.v2_contract import from_wire
        from .runtime.restore_anchor import RestoreAnchor

        namespace = authority.namespace
        port = self.__content_fence_v2
        with self.__store._lock:
            row = self.__store._db.execute(
                "SELECT request_digest,attempt_id,anchor_json,pre_graph_revision,"
                "pre_graph_epoch,permit_json,finish_request_id,finish_request_digest,"
                "receipt_json FROM graph_d13_worker_attempts_v2 WHERE bot=? "
                "AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone()
        if row is None:
            return None
        if row[0] != request_digest:
            raise EventConflict("D13 worker operation reused with different input")
        if row[8] is None:
            return None
        if any(value is None for value in row[5:8]):
            raise UnavailableGuard("D13 worker committed receipt lacks permit; HOLD")
        anchor = RestoreAnchor(**json.loads(row[2]))
        permit = from_wire(json.loads(row[5]))
        observed, state = port.get_fence_operation(
            namespace=namespace, authority_namespace=anchor.namespace,
            operation_id=row[1])
        if (observed != permit or state not in {"active", "finished"}
                or permit.pinned_anchor != anchor):
            raise UnavailableGuard("D13 worker original fence differs; HOLD")
        if state == "active":
            scope = FenceScope(
                namespace, anchor.namespace, authority.activation_generation,
                "write", row[1], permit, anchor,
                NamespaceEpoch(*namespace.as_tuple, row[4]), row[3])
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("D13 worker original permit changed; HOLD")
            port.finish_fence(scope, request_id=row[6], request_digest=row[7])
        return json.loads(row[8])

    def _d13_worker_pending_scope_v2(self, authority, operation_id,
                                     request_digest):
        """Recover only the original unresolved attempt and its exact write."""
        from .authority_service.v2_contract import FencePermitV2, from_wire, to_wire
        from .runtime.restore_anchor import RestoreAnchor

        store, port, namespace = self.__store, self.__content_fence_v2, authority.namespace
        with store._lock:
            db = store._db
            row = db.execute(
                "SELECT request_digest,attempt_id,anchor_json,pre_graph_revision,"
                "pre_graph_epoch,permit_json,finish_request_id,finish_request_digest,"
                "receipt_json FROM graph_d13_worker_attempts_v2 WHERE bot=? "
                "AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone()
            if row is None:
                return None
            metadata, epoch = self._v2_graph_stamp(namespace)
        if row[0] != request_digest:
            raise EventConflict("D13 worker original request digest differs")
        if row[8] is not None:
            raise UnavailableGuard("D13 worker receipt appeared during recovery; HOLD")
        saved_anchor = RestoreAnchor(**json.loads(row[2]))
        target = metadata.requirements
        if (target.namespace != namespace
                or target.activation_generation != authority.activation_generation
                or (metadata.graph_revision, epoch.revision) != row[3:5]
                or target.authority_namespace != saved_anchor.namespace):
            raise UnavailableGuard("D13 worker original graph stamp differs; HOLD")
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if anchor != saved_anchor or not self._anchor_matches(target, anchor):
            raise UnavailableGuard("D13 worker original Authority anchor differs; HOLD")
        try:
            permit, state = port.get_fence_operation(
                namespace=namespace, authority_namespace=anchor.namespace,
                operation_id=row[1])
        except Exception:
            if row[5] is not None:
                raise UnavailableGuard("D13 worker saved permit is unavailable; HOLD")
            try:
                permit = port.begin_fence(
                    namespace=namespace, authority_namespace=anchor.namespace,
                    holder=self.__holder, generation=authority.activation_generation,
                    operation="write", operation_id=row[1],
                    expected_anchor=anchor, retain_on_unknown=True)
            except Exception:
                try:
                    permit, state = port.get_fence_operation(
                        namespace=namespace, authority_namespace=anchor.namespace,
                        operation_id=row[1])
                except Exception as exc:
                    raise UnavailableGuard(
                        "D13 worker original begin outcome unavailable; HOLD") from exc
            else:
                state = "active"
        if (state != "active" or type(permit) is not FencePermitV2
                or permit.operation != "write" or permit.operation_id != row[1]
                or permit.holder != self.__holder or permit.pinned_anchor != anchor
                or permit.subject != port.installation_grant.subject
                or permit.authority_id != port.installation_grant.authority_id):
            raise UnavailableGuard("D13 worker original active permit differs; HOLD")
        finish_id = "finish:" + row[1]
        finish_digest = "sha256:" + canonical_digest({
            "action": "finish_d13_worker", "operation_id": operation_id,
            "permit_token": permit.token,
        })
        expected = (canonical_json(to_wire(permit)), finish_id, finish_digest)
        if row[5] is not None and row[5:8] != expected:
            raise UnavailableGuard("D13 worker saved permit identity differs; HOLD")
        if row[5] is None:
            with store._lock:
                db = store._db
                db.execute("BEGIN IMMEDIATE")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise StaleRead("D13 worker graph changed during recovery")
                    db.execute(
                        "UPDATE graph_d13_worker_attempts_v2 SET permit_json=?,"
                        "finish_request_id=?,finish_request_digest=? WHERE bot=? "
                        "AND persona=? AND operation_id=? AND permit_json IS NULL "
                        "AND receipt_json IS NULL",
                        expected + namespace.as_tuple + (operation_id,))
                    if db.execute("SELECT changes()").fetchone() != (1,):
                        raise UnavailableGuard("D13 worker permit raced; HOLD")
                    db.execute("COMMIT")
                except BaseException:
                    if db.in_transaction:
                        db.execute("ROLLBACK")
                    raise
        scope = FenceScope(
            namespace, target.authority_namespace,
            authority.activation_generation, "write", row[1], permit,
            anchor, epoch, metadata.graph_revision)
        if port.validate_fence(scope) != permit:
            raise UnavailableGuard("D13 worker recovered write fence changed; HOLD")
        return scope

    def _d13_worker_write_v2(self, authority, operation_id, request_digest,
                             commit):
        """Retain the original V2 write before one atomic business transaction."""
        store = self.__store
        port = self.__content_fence_v2
        namespace = authority.namespace
        prior = self._d13_worker_replay_v2(authority, operation_id, request_digest)
        if prior is not None:
            return prior
        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
        target = metadata.requirements
        if (target.namespace != namespace
                or target.activation_generation != authority.activation_generation):
            raise UnavailableGuard("D13 worker activation differs; HOLD")
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("D13 worker recovery anchor differs; HOLD")
        attempt_id = "d13-worker-" + canonical_digest({
            "operation_id": operation_id, "request_digest": request_digest,
            "namespace": namespace.as_tuple,
        })[:48]
        with store._lock:
            db = store._db
            db.execute("BEGIN IMMEDIATE")
            try:
                if self._v2_graph_stamp(namespace) != (metadata, epoch):
                    raise StaleRead("D13 worker graph changed before intent")
                prior_row = db.execute(
                    "SELECT request_digest,attempt_id,anchor_json,"
                    "pre_graph_revision,pre_graph_epoch,receipt_json FROM "
                    "graph_d13_worker_attempts_v2 WHERE bot=? AND persona=? "
                    "AND operation_id=?",
                    namespace.as_tuple + (operation_id,)).fetchone()
                if prior_row is None:
                    db.execute(
                        "INSERT INTO graph_d13_worker_attempts_v2"
                        "(bot,persona,operation_id,request_digest,attempt_id,"
                        "anchor_json,pre_graph_revision,pre_graph_epoch) "
                        "VALUES(?,?,?,?,?,?,?,?)",
                        namespace.as_tuple + (
                            operation_id, request_digest, attempt_id,
                            canonical_json(asdict(anchor)),
                            metadata.graph_revision, epoch.revision))
                elif prior_row != (
                        request_digest, attempt_id,
                        canonical_json(asdict(anchor)),
                        metadata.graph_revision, epoch.revision, None):
                    raise UnavailableGuard("D13 original worker attempt differs; HOLD")
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise
        scope = self._d13_worker_pending_scope_v2(
            authority, operation_id, request_digest)
        if scope is None or scope.operation_id != attempt_id:
            raise UnavailableGuard("D13 original worker scope unavailable; HOLD")
        permit = scope.permit
        finish_id = "finish:" + attempt_id
        finish_digest = "sha256:" + canonical_digest({
            "action": "finish_d13_worker", "operation_id": operation_id,
            "permit_token": permit.token,
        })
        from .runtime.first_ingress_v2 import trusted_upper
        try:
            clock = port.read_ingress_clock(self.__scene_clock_policy)
            trusted_upper(clock)
        except Exception:
            port.finish_fence(
                scope, request_id="reject:" + attempt_id,
                request_digest="sha256:" + canonical_digest({
                    "action": "reject_d13_worker",
                    "operation_id": operation_id,
                    "permit_token": permit.token,
                }))
            raise UnavailableGuard("D13 worker trusted clock unavailable; HOLD")
        with store._lock:
            db = store._db
            db.execute("BEGIN IMMEDIATE")
            commit_started = False
            try:
                if self._v2_graph_stamp(namespace) != (metadata, epoch):
                    raise StaleRead("D13 worker graph head changed")
                now = trusted_upper(clock)
                result = commit(db, metadata, epoch, now)
                db.execute(
                    "UPDATE graph_d13_worker_attempts_v2 SET receipt_json=? "
                    "WHERE bot=? AND persona=? AND operation_id=? AND receipt_json IS NULL",
                    (canonical_json(result), *namespace.as_tuple, operation_id))
                if db.execute("SELECT changes()").fetchone() != (1,):
                    raise EventConflict("D13 worker receipt was already sealed")
                commit_started = True
                db.execute("COMMIT")
            except BaseException as exc:
                if db.in_transaction:
                    db.execute("ROLLBACK")
                failure = exc
            else:
                failure = None
        if failure is not None:
            # The receipt and every business mutation share one transaction.
            # A rolled-back, known rejection cannot hold the namespace fence.
            if not commit_started and isinstance(failure, Exception):
                port.finish_fence(
                    scope, request_id="reject:" + attempt_id,
                    request_digest="sha256:" + canonical_digest({
                        "action": "reject_d13_worker",
                        "operation_id": operation_id,
                        "permit_token": permit.token,
                    }))
            raise failure
        port.finish_fence(scope, request_id=finish_id,
                          request_digest=finish_digest)
        return result

    def _d13_worker_original_scene_v2(self, namespace, job):
        with self.__store._lock:
            row = self.__store._db.execute(
                "SELECT receipt_json FROM graph_d13_precompression_attempts_v2 "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (job.operation_id,)).fetchone()
        if row is None or row[0] is None:
            raise UnavailableGuard("D13 original schedule receipt is absent; HOLD")
        payload = json.loads(row[0])
        if (payload.get("job", {}).get("job_id") != job.job_id
                or type(payload.get("requested_scene_ref")) is not str
                or not payload["requested_scene_ref"].startswith("scene:")):
            raise UnavailableGuard("D13 original scene identity differs; HOLD")
        return payload["requested_scene_ref"]

    def acquire_d13_deterministic_precompression_job_v2(
            self, authority: AuthorityContext, lease: object, job_id: str, *,
            lease_seconds: int) -> PersistentJob:
        """Acquire the original queued D13 job under a V2 write fence."""
        from .domains.d13.precompression import compile_deterministic_candidate
        from .runtime.d13_precompression_job import plan_from_precompression_job_v1
        from .runtime.d13_technical_policy import AdminD13PrecompressionPolicyV1

        store, port, policy = (self.__store, self.__content_fence_v2,
                               self.__d13_precompression_policy)
        if (not isinstance(store, ProductionGraphStore) or port is None
                or type(policy) is not AdminD13PrecompressionPolicyV1):
            raise UnavailableGuard("installed D13 worker authorities absent; HOLD")
        self._authorize(lease, authority, frozenset({"d11"}))
        if (authority.issuer_domain != "d11" or authority.purpose != "context"
                or authority.worker_fence is not None or len(authority.audience) != 1
                or policy.namespace != authority.namespace
                or policy.installation_id != port.installation_grant.installation_id
                or type(lease_seconds) is not int or not 1 <= lease_seconds <= 3600):
            raise AuthorityDenied("D13 worker scope differs")
        with store._lock:
            original = get_job(store._db, job_id)
        plan = plan_from_precompression_job_v1(original)
        if ((original.bot_id, original.persona_id) != authority.namespace.as_tuple
                or original.budget_ref != policy.lease_id
                or original.operator_versions.get("d13_compiler") != policy.compiler_version
                or original.operator_versions.get("d11_grant") !=
                    f"{policy.grant_id}:{policy.grant_version}"
                or original.operator_versions.get("installation_id") !=
                    policy.installation_id):
            raise AuthorityDenied("D13 worker original job differs")
        expected_fence = original.fence if original.phase == "queued" else original.fence - 1
        operation_id = "d13:acquire:" + canonical_digest({
            "job_id": job_id, "holder": authority.actor,
            "expected_fence": expected_fence,
        })[:48]
        request_digest = canonical_digest({
            "operation_id": operation_id, "lease_seconds": lease_seconds,
            "job_id": job_id, "holder": authority.actor,
        })
        prior = self._d13_worker_replay_v2(authority, operation_id, request_digest)
        if prior is not None:
            saved = PersistentJob(**prior["job"])
            with store._lock:
                current = get_job(store._db, job_id)
            if current != saved:
                raise UnavailableGuard("D13 acquired job changed after receipt; HOLD")
            return saved
        if original.phase != "queued" or original.cancel_epoch:
            raise UnavailableGuard("D13 original job is not queued; HOLD")
        pending_scope = self._d13_worker_pending_scope_v2(
            authority, operation_id, request_digest)
        window = self.read_current_d13_conversation_window_v1(
            authority, lease,
            scene_ref=self._d13_worker_original_scene_v2(authority.namespace, original),
            max_slots=policy.max_slots, _worker_scope=pending_scope)
        if (window.conversation_ref != original.continuation.get("conversation_ref")
                or window.missing_ranges):
            raise StaleRead("D13 worker original window changed")
        compile_deterministic_candidate(window, plan)
        def commit(db, _metadata, _epoch, now):
            current = get_job(db, job_id)
            if current != original:
                raise StaleRead("D13 original job changed before acquire")
            self._check_d13_worker_inputs_locked_v2(
                db, authority.namespace, window, plan, policy, now)
            now_text = datetime.fromtimestamp(now, timezone.utc).isoformat().replace(
                "+00:00", "Z")
            updated = acquire_job(db, job_id, authority.actor,
                                  now_utc=now_text, lease_seconds=lease_seconds)
            return {"job": asdict(updated)}

        result = self._d13_worker_write_v2(
            authority, operation_id, request_digest, commit)
        return PersistentJob(**result["job"])

    def _check_d13_worker_inputs_locked_v2(
            self, db, namespace, window, plan, policy, now):
        if (not self.__store._lock._is_owned() or not db.in_transaction
                or window.namespace != namespace or window.scene_ref != plan.scene_ref
                or window.audience_ref != plan.audience_ref
                or window.access_epoch != plan.access_epoch
                or window.delete_epoch != plan.delete_epoch
                or window.activation_epoch != plan.activation_epoch
                or window.activation_epoch != self._v2_graph_stamp(
                    namespace)[0].requirements.activation_generation
                or now < window.trusted_utc or now >= plan.expires_at_utc):
            raise StaleRead("D13 worker original window is stale")
        for ref in window.read_set:
            row = db.execute("SELECT revision,valid FROM graph_atoms WHERE token=?",
                             (ref.ref,)).fetchone()
            if (row is not None if ref.version == 0 else row != (ref.version, 1)):
                raise StaleRead("D13 worker source read set changed")
        if db.execute(
                "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                "WHERE bot=? AND persona=?", namespace.as_tuple).fetchone() != (
                    window.access_epoch, window.delete_epoch):
            raise StaleRead("D13 worker access or deletion epoch changed")
        grant = self.__d11_issuer.current_budget_grant(db, policy.lease_id)
        budget = get_budget_lease(db, policy.lease_id)
        if ((grant.grant_id, grant.version, grant.lease_id) !=
                (policy.grant_id, policy.grant_version, policy.lease_id)
                or policy.work_kind not in grant.allowed_work_kinds
                or grant.valid_until_utc <= now
                or grant.max_ceiling.get("d13_compute_units", 0) < 1
                or budget.state != "active"
                or (budget.bot_id, budget.persona_id) != namespace.as_tuple):
            raise UnavailableGuard("D13 original technical grant is no longer current")

    def complete_d13_deterministic_precompression_job_v2(
            self, authority: AuthorityContext, lease: object, job_id: str, *,
            fence: int):
        """Atomically adopt standby, complete the D11 job, and settle one unit."""
        from .domains.d13.precompression import compile_deterministic_candidate
        from .domains.d13.provider import block_graph_value
        from .runtime.d13_precompression_job import (
            D13CacheCommitReceiptV1, plan_from_precompression_job_v1,
            prepare_adoption_intent_v1,
        )
        from .runtime.d13_technical_policy import AdminD13PrecompressionPolicyV1
        from .runtime.jobs import checkpoint_job, transition_job

        store, port, policy = (self.__store, self.__content_fence_v2,
                               self.__d13_precompression_policy)
        if (not isinstance(store, ProductionGraphStore) or port is None
                or type(policy) is not AdminD13PrecompressionPolicyV1):
            raise UnavailableGuard("installed D13 worker authorities absent; HOLD")
        self._authorize(lease, authority, frozenset({"d11"}))
        if (authority.issuer_domain != "d11" or authority.purpose != "context"
                or authority.worker_fence is not None or len(authority.audience) != 1
                or policy.namespace != authority.namespace
                or policy.installation_id != port.installation_grant.installation_id
                or type(fence) is not int or fence < 1):
            raise AuthorityDenied("D13 completion worker scope differs")
        operation_id = "d13:complete:" + canonical_digest({
            "job_id": job_id, "holder": authority.actor, "fence": fence,
        })[:48]
        request_digest = canonical_digest({
            "operation_id": operation_id, "job_id": job_id,
            "holder": authority.actor, "fence": fence,
        })
        prior = self._d13_worker_replay_v2(authority, operation_id, request_digest)
        if prior is not None:
            receipt = D13CacheCommitReceiptV1(**prior["cache"])
            budget = BudgetReceipt(**prior["budget"])
            job = PersistentJob(**prior["job"])
            with store._lock:
                current = get_job(store._db, job_id)
                row = store._db.execute(
                    "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                    (AtomKey(Owner("persona", *authority.namespace.as_tuple),
                             "d13.compressed_turn_block.v2", receipt.block_ref).token,
                     )).fetchone()
            if (current != job or row is None or row[0] != receipt.cache_revision
                    or row[2] != 1):
                raise UnavailableGuard("D13 completion replay state differs; HOLD")
            return receipt, budget, job
        with store._lock:
            original = get_job(store._db, job_id)
        plan = plan_from_precompression_job_v1(original)
        if ((original.bot_id, original.persona_id) != authority.namespace.as_tuple
                or original.budget_ref != policy.lease_id
                or original.operator_versions.get("d13_compiler") != policy.compiler_version
                or original.operator_versions.get("d11_grant") !=
                    f"{policy.grant_id}:{policy.grant_version}"
                or original.operator_versions.get("installation_id") !=
                    policy.installation_id
                or original.phase != "running" or original.lease_holder != authority.actor
                or original.fence != fence or original.cancel_epoch):
            raise UnavailableGuard("D13 original worker fence differs; HOLD")
        pending_scope = self._d13_worker_pending_scope_v2(
            authority, operation_id, request_digest)
        window = self.read_current_d13_conversation_window_v1(
            authority, lease,
            scene_ref=self._d13_worker_original_scene_v2(authority.namespace, original),
            max_slots=policy.max_slots, _worker_scope=pending_scope)
        candidate = compile_deterministic_candidate(window, plan)
        intent = prepare_adoption_intent_v1(
            original, holder=authority.actor, fence=fence,
            now_utc=window.trusted_utc, plan=plan, candidate=candidate,
            current_window=window)
        def commit(db, metadata, epoch, now):
            current = get_job(db, job_id)
            if current != original:
                raise StaleRead("D13 worker fence changed before completion")
            self._check_d13_worker_inputs_locked_v2(
                db, authority.namespace, window, plan, policy, now)
            if (now >= datetime.fromisoformat(
                    current.lease_expires_utc.replace("Z", "+00:00")).timestamp()
                    or now >= datetime.fromisoformat(
                        current.deadline_utc.replace("Z", "+00:00")).timestamp()):
                raise UnavailableGuard("D13 worker lease or deadline expired; HOLD")
            reservation = db.execute(
                "SELECT digest,ceiling_json,state FROM runtime_budget_reservations "
                "WHERE lease_id=? AND operation_id=?",
                (policy.lease_id, current.operation_id)).fetchone()
            if (reservation is None or reservation[2] != "reserved"
                    or json.loads(reservation[1]) != {"d13_compute_units": 1}):
                raise UnavailableGuard("D13 original reservation differs; HOLD")
            key = AtomKey(Owner("persona", *authority.namespace.as_tuple),
                          "d13.compressed_turn_block.v2", intent.block.block_ref)
            if db.execute("SELECT 1 FROM graph_atoms WHERE token=?",
                          (key.token,)).fetchone() is not None:
                raise StaleRead("D13 cache block already occupies original identity")
            refs = tuple(dict.fromkeys((*window.read_set, *intent.source_dependencies)))
            reads = tuple(GraphVersion(AtomKey.from_token(ref.ref), ref.version)
                          for ref in refs)
            event = Event(
                Scope(*authority.namespace.as_tuple, "d13-precompression"),
                operation_id, now, "d13.cache_standby",
                {"input_digest": plan.input_digest, "job_id": job_id})
            candidate_graph = GraphCandidate(
                event, (GraphVersion(key, 0), *reads),
                (GraphWrite(key, block_graph_value(intent.block),
                            tuple(AtomKey.from_token(ref.ref)
                                  for ref in intent.source_dependencies)),),
                (epoch,))
            sealed = []

            def seal(db, graph_receipt):
                if (graph_receipt.status != "committed"
                        or graph_receipt.revisions != (GraphVersion(key, 1),)
                        or graph_receipt.epoch.revision != epoch.revision + 1):
                    raise UnavailableGuard("D13 standby graph seal differs; HOLD")
                store.cas_graph_recovery_metadata(
                    metadata, metadata.requirements,
                    _capability=self.__graph_capability)
                budget = settle_budget(
                    db, policy.lease_id, current.operation_id,
                    reservation[0], {"d13_compute_units": 1})
                if budget.status != "settled":
                    raise UnavailableGuard("D13 technical unit did not settle")
                checkpoint_job(db, job_id, authority.actor, fence,
                               continuation=current.continuation,
                               usage={"d13_compute_units": 1})
                completed = transition_job(
                    db, job_id, authority.actor, fence, target_phase="completed",
                    result_ref=intent.block.block_ref)
                receipt = D13CacheCommitReceiptV1(
                    intent.operation_id, intent.input_digest,
                    intent.block.block_ref, "adopt", metadata.graph_revision + 1,
                    1, window.delete_epoch, False, False, None)
                sealed.append({"cache": asdict(receipt), "budget": asdict(budget),
                               "job": asdict(completed)})

            GraphStore._graph_commit_in_transaction(
                store, candidate_graph, _receipt_hook=seal,
                _capability=self.__graph_capability)
            return sealed[0]

        result = self._d13_worker_write_v2(
            authority, operation_id, request_digest, commit)
        return (D13CacheCommitReceiptV1(**result["cache"]),
                BudgetReceipt(**result["budget"]),
                PersistentJob(**result["job"]))

    def expire_d13_deterministic_precompression_job_v2(
            self, authority: AuthorityContext, lease: object, job_id: str):
        """Revoke an expired original job and settle its fixed technical unit.

        A queued job never ran, while an acquired job consumed its one local
        compute unit. Both cases use the original reservation in one fenced
        transaction; an unresolved completion fence remains a HOLD.
        """
        from .runtime.d13_precompression_job import plan_from_precompression_job_v1
        from .runtime.d13_technical_policy import AdminD13PrecompressionPolicyV1
        from .runtime.jobs import checkpoint_job, transition_job

        store, port, policy = (self.__store, self.__content_fence_v2,
                               self.__d13_precompression_policy)
        if (not isinstance(store, ProductionGraphStore) or port is None
                or type(policy) is not AdminD13PrecompressionPolicyV1):
            raise UnavailableGuard("installed D13 expiry authorities absent; HOLD")
        self._authorize(lease, authority, frozenset({"d11"}))
        if (authority.issuer_domain != "d11" or authority.purpose != "context"
                or authority.worker_fence is not None or len(authority.audience) != 1
                or policy.namespace != authority.namespace
                or policy.installation_id != port.installation_grant.installation_id):
            raise AuthorityDenied("D13 expiry scope differs")
        with store._lock:
            original = get_job(store._db, job_id)
        plan_from_precompression_job_v1(original)
        if ((original.bot_id, original.persona_id) != authority.namespace.as_tuple
                or original.budget_ref != policy.lease_id
                or original.work_kind != policy.work_kind
                or original.resource_ref != policy.resource_ref
                or original.operator_versions.get("d13_compiler") != policy.compiler_version
                or original.operator_versions.get("d11_grant") !=
                    f"{policy.grant_id}:{policy.grant_version}"
                or original.operator_versions.get("installation_id") !=
                    policy.installation_id):
            raise AuthorityDenied("D13 expiry original job differs")
        operation_id = "d13:expire:" + canonical_digest({"job_id": job_id})[:48]
        request_digest = canonical_digest({
            "operation_id": operation_id, "job_id": job_id,
            "original_operation_id": original.operation_id,
        })
        prior = self._d13_worker_replay_v2(authority, operation_id, request_digest)
        if prior is not None:
            budget, job = BudgetReceipt(**prior["budget"]), PersistentJob(**prior["job"])
            with store._lock:
                current = get_job(store._db, job_id)
            if current != job or job.phase != "cancelled":
                raise UnavailableGuard("D13 expiry replay state differs; HOLD")
            return budget, job
        if original.phase not in {"queued", "running"} or original.cancel_epoch:
            raise UnavailableGuard("D13 original job is not expirable; HOLD")
        if original.phase == "running" and (original.lease_holder is None
                                             or original.usage not in ({}, {"d13_compute_units": 1})):
            raise UnavailableGuard("D13 running usage is not fixed; HOLD")
        from .runtime.first_ingress_v2 import trusted_upper
        preflight_now = trusted_upper(port.read_ingress_clock(self.__scene_clock_policy))
        if preflight_now < datetime.fromisoformat(
                original.deadline_utc.replace("Z", "+00:00")).timestamp():
            raise UnavailableGuard("D13 original job deadline is live; HOLD")

        def commit(db, _metadata, _epoch, now):
            current = get_job(db, job_id)
            if current != original:
                raise StaleRead("D13 original job changed before expiry")
            deadline = datetime.fromisoformat(
                current.deadline_utc.replace("Z", "+00:00")).timestamp()
            if now < deadline:
                raise UnavailableGuard("D13 original job deadline is live; HOLD")
            receipt_row = db.execute(
                "SELECT receipt_json FROM graph_d13_precompression_attempts_v2 "
                "WHERE bot=? AND persona=? AND operation_id=?",
                authority.namespace.as_tuple + (current.operation_id,)).fetchone()
            if receipt_row is None or receipt_row[0] is None:
                raise UnavailableGuard("D13 original schedule receipt absent; HOLD")
            schedule = json.loads(receipt_row[0])
            if (schedule.get("job", {}).get("job_id") != job_id
                    or schedule.get("budget", {}).get("status") != "reserved"
                    or schedule["budget"].get("operation_id") != current.operation_id
                    or schedule["budget"].get("lease_id") != policy.lease_id):
                raise UnavailableGuard("D13 original schedule receipt differs; HOLD")
            reservation = db.execute(
                "SELECT digest,ceiling_json,state FROM runtime_budget_reservations "
                "WHERE lease_id=? AND operation_id=?",
                (policy.lease_id, current.operation_id)).fetchone()
            if (reservation is None or reservation[0] != schedule["budget"]["digest"]
                    or reservation[2] != "reserved"
                    or json.loads(reservation[1]) != {"d13_compute_units": 1}):
                raise UnavailableGuard("D13 original reservation differs; HOLD")
            if current.phase == "running":
                checkpoint_job(db, job_id, current.lease_holder, current.fence,
                               continuation=current.continuation,
                               usage={"d13_compute_units": 1})
            cancelled = cancel_job(db, job_id, operation_id, request_digest)
            if cancelled.phase == "draining":
                cancelled = transition_job(
                    db, job_id, cancelled.lease_holder, cancelled.fence,
                    target_phase="cancelled")
            if cancelled.phase != "cancelled":
                raise UnavailableGuard("D13 expired worker did not terminate; HOLD")
            actual = ({"d13_compute_units": 1} if current.phase == "running" else {})
            budget = settle_budget(
                db, policy.lease_id, current.operation_id, reservation[0], actual,
                execution_revoked=True)
            if budget.status != "settled":
                raise UnavailableGuard("D13 expired technical budget did not settle")
            return {"budget": asdict(budget), "job": asdict(cancelled)}

        result = self._d13_worker_write_v2(
            authority, operation_id, request_digest, commit)
        return BudgetReceipt(**result["budget"]), PersistentJob(**result["job"])

    def _current_d13_cache_block_locked_v1(
            self, namespace: NamespaceId, block_ref: str, *,
            trusted_now_utc: float):
        """Return a usable current block only inside W01's fenced SQL read.

        No caller-provided D11 window is inferred from this narrow barrier.
        A future projection issuer must additionally prove the full window.
        """
        from .domains.d13.provider import _block_from_graph_value

        store = self.__store
        if (not store._lock._is_owned() or not store._db.in_transaction
                or type(trusted_now_utc) not in (int, float)
                or not math.isfinite(trusted_now_utc)):
            raise RuntimeError("D13 current read needs the held graph transaction")
        key = AtomKey(Owner("persona", *namespace.as_tuple),
                      "d13.compressed_turn_block.v2", block_ref)
        row = store._db.execute(
            "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
            (key.token,),
        ).fetchone()
        retired = store._db.execute(
            "SELECT 1 FROM graph_d13_retirements_v1 WHERE bot=? AND persona=? "
            "AND block_token=?", namespace.as_tuple + (key.token,),
        ).fetchone()
        if row is None or row[2] != 1 or retired is not None:
            return None
        block = _block_from_graph_value(json.loads(row[1]))
        if (block.block_ref != block_ref or block.status != "active"
                or trusted_now_utc >= block.expires_at_utc):
            return None
        return block

    def _retire_expired_d13_cache_in_transaction_v1(
            self, intent, *, trusted_now_utc: float, expected_metadata,
            expected_epoch: NamespaceEpoch):
        """Retire one expired graph cache under an already validated write fence.

        The caller owns the graph lock and SQLite transaction.  Old history
        still contains plaintext, so the durable cleanup task is mandatory
        and the receipt must never claim physical reclamation.
        """
        from .domains.d13.provider import _block_from_graph_value, block_graph_value
        from .runtime.d13_precompression_job import (
            D13CacheCommitReceiptV1, D13CacheTransitionIntentV1,
        )

        store = self.__store
        if (type(intent) is not D13CacheTransitionIntentV1
                or intent.action != "retire" or intent.reason != "72h_expired"
                or not store._lock._is_owned() or not store._db.in_transaction):
            raise UnavailableGuard("D13 retirement needs an expired fenced graph transaction")
        namespace = intent.namespace
        db = store._db
        prior = db.execute(
            "SELECT input_digest,block_token,receipt_json FROM "
            "graph_d13_retirements_v1 WHERE bot=? AND persona=? AND operation_id=?",
            namespace.as_tuple + (intent.operation_id,),
        ).fetchone()
        if prior is not None:
            if prior[:2] != (intent.input_digest, AtomKey(
                    Owner("persona", *namespace.as_tuple),
                    "d13.compressed_turn_block.v2", intent.block.block_ref).token):
                raise EventConflict("D13 retirement operation was reused")
            receipt = D13CacheCommitReceiptV1(**json.loads(prior[2]))
            row = db.execute(
                "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                (prior[1],),
            ).fetchone()
            if (row is None or row[0] != receipt.cache_revision or row[2] != 1
                    or _block_from_graph_value(json.loads(row[1])) != intent.block):
                raise UnavailableGuard("D13 retired graph block differs; HOLD")
            task = db.execute(
                "SELECT state FROM graph_d13_cleanup_tasks_v1 WHERE bot=? "
                "AND persona=? AND task_ref=? AND block_token=?",
                namespace.as_tuple + (receipt.cleanup_task_ref, prior[1]),
            ).fetchone()
            if task != ("pending",):
                raise UnavailableGuard("D13 durable cleanup task differs; HOLD")
            return receipt
        if self._v2_graph_stamp(namespace) != (expected_metadata, expected_epoch):
            raise StaleRead("D13 retirement graph head changed")
        key = AtomKey(Owner("persona", *namespace.as_tuple),
                      "d13.compressed_turn_block.v2", intent.block.block_ref)
        row = db.execute(
            "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
            (key.token,),
        ).fetchone()
        if row is None or row[2] != 1 or row[0] != intent.expected_cache_revision:
            raise StaleRead("D13 cache CAS revision changed")
        old = _block_from_graph_value(json.loads(row[1]))
        if (row[1] != canonical_json(block_graph_value(old))
                or old.status not in {"standby", "active"}
                or intent.block != replace(old, status="retired")
                or intent.audience_ref != old.audience_ref
                or intent.conversation_ref != old.conversation_ref
                or trusted_now_utc < old.expires_at_utc
                or not old.expires_at_utc <= intent.trusted_utc <= trusted_now_utc):
            raise UnavailableGuard("D13 cache is not currently due for retirement; HOLD")
        historical = db.execute(
            "SELECT value,valid FROM graph_history WHERE token=? AND revision=? "
            "AND event_bot=? AND event_persona=?",
            (key.token, row[0], *namespace.as_tuple),
        ).fetchall()
        if historical != [(row[1], 1)]:
            raise UnavailableGuard("D13 current cache lacks its graph history; HOLD")
        epochs = db.execute(
            "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
            "WHERE bot=? AND persona=?", namespace.as_tuple,
        ).fetchone() or (0, 0)
        if epochs != (intent.access_epoch, intent.delete_epoch):
            raise StaleRead("D13 access or deletion epoch changed")
        cleanup_ref = "d13:cleanup:" + intent.input_digest[:48]
        event = Event(
            Scope(*namespace.as_tuple, "d13-cache-retirement"),
            intent.operation_id, trusted_now_utc, "d13.cache_retired",
            {"input_digest": intent.input_digest, "block_token": key.token},
        )
        candidate = GraphCandidate(
            event, (GraphVersion(key, row[0]),),
            (GraphWrite(key, block_graph_value(intent.block)),),
            (expected_epoch,),
        )
        result = []

        def seal(db, graph_receipt):
            if (graph_receipt.status != "committed"
                    or graph_receipt.revisions != (GraphVersion(key, row[0] + 1),)
                    or graph_receipt.epoch.revision != expected_epoch.revision + 1):
                raise UnavailableGuard("D13 retirement graph seal differs; HOLD")
            store.cas_graph_recovery_metadata(
                expected_metadata, expected_metadata.requirements,
                _capability=self.__graph_capability)
            receipt = D13CacheCommitReceiptV1(
                intent.operation_id, intent.input_digest, intent.block.block_ref,
                "retire", expected_metadata.graph_revision + 1, row[0] + 1,
                epochs[1], True, False, cleanup_ref,
            )
            db.execute(
                "INSERT INTO graph_d13_cleanup_tasks_v1"
                "(bot,persona,task_ref,block_token,retirement_operation_id,state) "
                "VALUES(?,?,?,?,?,'pending')",
                namespace.as_tuple + (cleanup_ref, key.token, intent.operation_id),
            )
            db.execute(
                "INSERT INTO graph_d13_retirements_v1"
                "(bot,persona,operation_id,input_digest,block_token,old_revision,"
                "cache_revision,graph_revision,graph_epoch,cleanup_task_ref,receipt_json) "
                "VALUES(?,?,?,?,?,?,?,?,?,?,?)",
                namespace.as_tuple + (
                    intent.operation_id, intent.input_digest, key.token, row[0],
                    receipt.cache_revision, receipt.graph_revision,
                    graph_receipt.epoch.revision, cleanup_ref,
                    canonical_json(asdict(receipt))),
            )
            result.append(receipt)

        GraphStore._graph_commit_in_transaction(
            store, candidate, _receipt_hook=seal,
            _capability=self.__graph_capability,
        )
        if self._current_d13_cache_block_locked_v1(
                namespace, intent.block.block_ref,
                trusted_now_utc=trusted_now_utc) is not None:
            raise UnavailableGuard("D13 retired cache remained readable; HOLD")
        return result[0]

    def _commit_domain_bundle_v2(self, bundle: DomainBundle,
                                 lease: object, *, arrival_issuance=None,
                                 attention_issuance=None,
                                 c04_association_issuance=None,
                                 baseline_issuance=None,
                                 self_identity_issuance=None,
                                 correction_issuance=None,
                                  c02_adoption=None,
                                  c02_recovery: _C02PendingRecovery | None = None,
                                  c02_terminal_recovery: _C02TerminalRecovery | None = None,
                                  c02_first_seal_v2: bool = False,
                                  d04_joint_replay=None,
                                  d04_joint_output=None) -> CommitReceipt:
        """Commit under a durable write attempt; reconcile before any duplicate read."""
        from .authority_service.v2_contract import FencePermitV2, from_wire, to_wire
        from .runtime.d04_joint_advance_v2 import ProductAdvanceEvidenceV2

        if bundle.root_adoption is not None:
            raise UnavailableGuard(
                "authored D04 root needs its dedicated installed adoption; HOLD")
        if (type(bundle.product_advance) is ProductAdvanceEvidenceV2
                and (d04_joint_replay is None or d04_joint_output is None)):
            raise UnavailableGuard("installed D04 joint output unavailable; HOLD")

        store = self.__store
        port = self.__content_fence_v2
        authority = bundle.envelope.authority
        namespace = authority.namespace
        operation_id = bundle.envelope.identity.operation_id
        digest = bundle.digest
        is_c04 = any(
            write.key.type_name == "d06.recollection.v1"
            for proposal in bundle.proposals for write in proposal.typed_writes)
        if is_c04 and c04_association_issuance is None:
            raise UnavailableGuard(
                "production C04 requires same-transaction association proof; HOLD")
        if c04_association_issuance is not None and (
                not is_c04 or bundle.envelope.identity.phase != "realize-recollection"):
            raise AuthorityDenied("C04 association proof needs a recollection bundle")
        if sum(item is not None for item in (
                c02_adoption, c02_recovery, c02_terminal_recovery)) > 1:
            raise ValueError("C02 cannot mix original adoption and recovery")
        if c02_first_seal_v2 and (c02_adoption is None or c02_recovery is not None
                                  or c02_terminal_recovery is not None):
            raise ValueError("C02 v2 first seal requires original adoption")
        if c02_terminal_recovery is not None and c02_terminal_recovery.seal.bundle_digest != digest:
            raise EventConflict("terminal C02 frozen bundle differs")
        c02_witness = (c02_terminal_recovery if c02_terminal_recovery is not None
                       else c02_recovery if c02_recovery is not None else c02_adoption)
        if (bundle.envelope.identity.phase == "first_ingress_c02") != (
                c02_witness is not None):
            raise UnavailableGuard("C02 requires its installed result adoption; HOLD")
        attempt_id = domain_bundle_write_attempt_id_v1(
            namespace, operation_id, digest)
        c02_candidate = None
        c02_first_seal_key = None
        if c02_terminal_recovery is not None:
            c02_candidate = c02_terminal_recovery.sealed_candidate
        elif c02_recovery is not None:
            c02_candidate = c02_recovery.sealed_candidate
        elif c02_adoption is not None:
            from .authority_service.v2_worker_model_result_contract import (
                to_wire as worker_read_to_wire,
            )
            from .runtime.c02_bundle_codec import (
                c02_bundle_from_wire, c02_bundle_to_wire,
            )
            if c02_first_seal_v2:
                from .authority_service.v2_terminal_c02_recovery_contract import (
                    OriginalC02ResultKeyV1,
                )

            original_intent, read, binding, held, installation, admin, _ = (
                c02_adoption)
            evidence = {
                "schema": ("sylanne.first-ingress-c02-candidate.v2"
                           if c02_first_seal_v2 else
                           "sylanne.first-ingress-c02-candidate.v1"),
                "read_request": worker_read_to_wire(read.request),
                "read_result_digest": canonical_digest(asdict(read)),
                "original_intent_digest": canonical_digest(asdict(original_intent)),
                "terminal_receipt_digest": canonical_digest(
                    asdict(read.terminal_receipt)),
                "observation_digest": held.observation_digest,
                "result_payload_digest": held.result_digest,
                "admin_policy_digest": canonical_digest({
                    "deadline_after_seconds": admin.deadline_after_seconds,
                    "quote_ceiling": dict(admin.quote_ceiling),
                    "snapshot_ref": admin.snapshot_ref,
                    "resource_ref": admin.resource_ref,
                }),
                "installation_id": installation.installation_id,
                "manifest_digest": installation.manifest_digest,
                "source_ref": held.source_ref,
                "encoding_baseline_ref": held.encoding_baseline_ref,
                "call_id": held.call_id,
                "model_request_digest": held.request_digest,
                "authority_operation_id": held.authority_operation_id,
                "binding_digest": binding.binding_digest,
            }
            if c02_first_seal_v2:
                request = read.request
                c02_first_seal_key = OriginalC02ResultKeyV1(
                    request.authority_id, request.authority_namespace,
                    request.namespace, request.installation_id, request.job_id,
                    request.original_operation_id, request.acquire_operation_id,
                    request.acquire_operation_id, request.call_id,
                    request.binding_digest, request.model_request_digest,
                    evidence["original_intent_digest"],
                    evidence["observation_digest"],
                    evidence["terminal_receipt_digest"])
                evidence["terminal_read_attempt_id"] = (
                    self._terminal_c02_read_attempt_id_v2(
                        request, c02_first_seal_key, digest))
            bundle_json = c02_bundle_to_wire(bundle)
            if (type(bundle_json) is not str
                    or c02_bundle_from_wire(bundle_json) != bundle):
                raise UnavailableGuard("C02 candidate bundle codec differs; HOLD")
            c02_candidate = (
                evidence["schema"], digest, attempt_id, bundle_json,
                canonical_json(evidence))
        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
            prior = store._db.execute(
                "SELECT digest FROM graph_bundle_operations WHERE bot=? AND persona=? "
                "AND operation_id=?", namespace.as_tuple + (operation_id,),
            ).fetchone()
            saved = store._db.execute(
                "SELECT digest,permit_json,pre_graph_revision,pre_graph_epoch,"
                "post_graph_revision,post_graph_epoch,finish_request_id,finish_request_digest "
                "FROM graph_bundle_fences_v2 WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone()
            intent = store._db.execute(
                "SELECT digest,fence_attempt_id,requirements_json,anchor_json,"
                "graph_revision,graph_epoch FROM graph_bundle_intents_v2 "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone()
            rejection = store._db.execute(
                "SELECT digest,status,permit_json,graph_revision,graph_epoch,"
                "finish_request_id,finish_request_digest FROM graph_bundle_rejections_v2 "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone()
        target = metadata.requirements
        if target.namespace != namespace or target.activation_generation != authority.activation_generation:
            raise UnavailableGuard("v2 graph recovery identity or generation differs")
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("v2 graph recovery anchor differs")
        requirements_json = canonical_json(asdict(target))
        anchor_json = canonical_json(asdict(anchor))
        if c02_terminal_recovery is not None and intent is None:
            raise UnavailableGuard("terminal C02 durable first-seal intent is absent; HOLD")
        if intent is None and prior is None:
            with store._lock:
                db = store._db
                db.execute("BEGIN IMMEDIATE")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise StaleRead("v2 graph recovery stamp changed before intent")
                    if self_identity_issuance is not None:
                        db.execute("""CREATE TABLE IF NOT EXISTS graph_d03_self_projection_intents_v1(
                            bot TEXT NOT NULL, persona TEXT NOT NULL,
                            source_ref TEXT NOT NULL, original_operation_id TEXT NOT NULL,
                            operation_id TEXT NOT NULL, bundle_digest TEXT NOT NULL,
                            PRIMARY KEY(bot,persona,source_ref,original_operation_id))""")
                        if self_identity_issuance[8] is None:
                            db.execute(
                                "INSERT OR IGNORE INTO graph_d03_self_projection_intents_v1"
                                "(bot,persona,source_ref,original_operation_id,"
                                "operation_id,bundle_digest) VALUES(?,?,?,?,?,?)",
                                namespace.as_tuple + (self_identity_issuance[4],
                                                      self_identity_issuance[7],
                                                      operation_id, digest),
                            )
                        else:
                            self._stage_retry_intent_locked(
                                db, namespace, "d03", self_identity_issuance[4],
                                self_identity_issuance[7], operation_id, digest,
                                self_identity_issuance[8])
                        indexed = db.execute(
                            "SELECT operation_id,bundle_digest FROM "
                            "graph_d03_self_projection_intents_v1 WHERE bot=? AND persona=? "
                            "AND source_ref=? AND original_operation_id=?",
                            namespace.as_tuple + (self_identity_issuance[4],
                                                  self_identity_issuance[7]),
                        ).fetchone()
                        if indexed != (operation_id, digest):
                            raise EventConflict("D03 self stage recovery identity differs")
                    if baseline_issuance is not None:
                        db.execute("""CREATE TABLE IF NOT EXISTS graph_d04_baseline_intents_v1(
                            bot TEXT NOT NULL, persona TEXT NOT NULL,
                            source_ref TEXT NOT NULL, original_operation_id TEXT NOT NULL,
                            operation_id TEXT NOT NULL, bundle_digest TEXT NOT NULL,
                            PRIMARY KEY(bot,persona,source_ref,original_operation_id))""")
                        if baseline_issuance[8] is None:
                            db.execute(
                                "INSERT OR IGNORE INTO graph_d04_baseline_intents_v1"
                                "(bot,persona,source_ref,original_operation_id,"
                                "operation_id,bundle_digest) VALUES(?,?,?,?,?,?)",
                                namespace.as_tuple + (baseline_issuance[3],
                                                      baseline_issuance[7],
                                                      operation_id, digest),
                            )
                        else:
                            self._stage_retry_intent_locked(
                                db, namespace, "d04", baseline_issuance[3],
                                baseline_issuance[7], operation_id, digest,
                                baseline_issuance[8])
                        indexed = db.execute(
                            "SELECT operation_id,bundle_digest FROM "
                            "graph_d04_baseline_intents_v1 WHERE bot=? AND persona=? "
                            "AND source_ref=? AND original_operation_id=?",
                            namespace.as_tuple + (baseline_issuance[3],
                                                  baseline_issuance[7]),
                        ).fetchone()
                        if indexed != (operation_id, digest):
                            raise EventConflict("D04 baseline recovery identity differs")
                    db.execute(
                        "INSERT OR IGNORE INTO graph_bundle_intents_v2"
                        "(bot,persona,operation_id,digest,fence_attempt_id,"
                        "requirements_json,anchor_json,graph_revision,graph_epoch) "
                        "VALUES(?,?,?,?,?,?,?,?,?)",
                        namespace.as_tuple + (
                            operation_id, digest, attempt_id, requirements_json,
                            anchor_json, metadata.graph_revision, epoch.revision),
                    )
                    intent = db.execute(
                        "SELECT digest,fence_attempt_id,requirements_json,anchor_json,"
                        "graph_revision,graph_epoch FROM graph_bundle_intents_v2 "
                        "WHERE bot=? AND persona=? AND operation_id=?",
                        namespace.as_tuple + (operation_id,),
                    ).fetchone()
                    if c02_candidate is not None:
                        if c02_first_seal_v2:
                            db.execute("""CREATE TABLE IF NOT EXISTS
                                graph_first_ingress_c02_candidates_v2 (
                                bot TEXT NOT NULL, persona TEXT NOT NULL,
                                operation_id TEXT NOT NULL,
                                schema TEXT NOT NULL CHECK(schema=
                                    'sylanne.first-ingress-c02-candidate.v2'),
                                bundle_digest TEXT NOT NULL,
                                fence_attempt_id TEXT NOT NULL,
                                bundle_json TEXT NOT NULL,
                                evidence_json TEXT NOT NULL,
                                quote_json TEXT NOT NULL,
                                seal_json TEXT NOT NULL,
                                PRIMARY KEY(bot,persona,operation_id),
                                FOREIGN KEY(bot,persona,operation_id)
                                    REFERENCES graph_bundle_intents_v2(
                                        bot,persona,operation_id))""")
                            quote, seal = self.__d11_issuer.issue_d06_first_ingress_c02_quote_at_first_seal_v2(
                                db, bundle, c02_adoption[5],
                                original_key=c02_first_seal_key,
                                sealed_at_utc=c02_adoption[6])
                            candidate_values = c02_candidate + (
                                canonical_serialize(asdict(quote)),
                                canonical_serialize(asdict(seal)))
                            db.execute(
                                "INSERT INTO graph_first_ingress_c02_candidates_v2"
                                "(bot,persona,operation_id,schema,bundle_digest,"
                                "fence_attempt_id,bundle_json,evidence_json,"
                                "quote_json,seal_json) VALUES(?,?,?,?,?,?,?,?,?,?)",
                                namespace.as_tuple + (operation_id,)
                                + candidate_values)
                            sealed = db.execute(
                                "SELECT schema,bundle_digest,fence_attempt_id,"
                                "bundle_json,evidence_json,quote_json,seal_json "
                                "FROM graph_first_ingress_c02_candidates_v2 "
                                "WHERE bot=? AND persona=? AND operation_id=?",
                                namespace.as_tuple + (operation_id,),
                            ).fetchone()
                            if sealed != candidate_values:
                                raise EventConflict("C02 v2 first seal differs")
                        else:
                            db.execute(
                                "INSERT OR IGNORE INTO graph_first_ingress_c02_candidates_v1"
                                "(bot,persona,operation_id,schema,bundle_digest,"
                                "fence_attempt_id,bundle_json,evidence_json) "
                                "VALUES(?,?,?,?,?,?,?,?)",
                                namespace.as_tuple + (operation_id,) + c02_candidate,
                            )
                            sealed = db.execute(
                                "SELECT schema,bundle_digest,fence_attempt_id,"
                                "bundle_json,evidence_json FROM "
                                "graph_first_ingress_c02_candidates_v1 WHERE bot=? "
                                "AND persona=? AND operation_id=?",
                                namespace.as_tuple + (operation_id,),
                            ).fetchone()
                        if sealed[:5] != c02_candidate or intent[0:2] != (
                                digest, attempt_id):
                            raise EventConflict("C02 candidate or intent identity differs")
                    db.execute("COMMIT")
                except BaseException:
                    db.execute("ROLLBACK")
                    raise
        if intent is None:
            raise UnavailableGuard("durable v2 bundle intent is absent")
        if intent[0] != digest:
            raise EventConflict("operation ID reused with different bundle")
        c02_v2_quote = None
        if c02_candidate is not None and prior is None:
            with store._lock:
                if c02_first_seal_v2 or c02_terminal_recovery is not None:
                    sealed = store._db.execute(
                        "SELECT schema,bundle_digest,fence_attempt_id,"
                        "bundle_json,evidence_json,quote_json,seal_json "
                        "FROM graph_first_ingress_c02_candidates_v2 "
                        "WHERE bot=? AND persona=? AND operation_id=?",
                        namespace.as_tuple + (operation_id,),
                    ).fetchone()
                else:
                    sealed = store._db.execute(
                        "SELECT schema,bundle_digest,fence_attempt_id,"
                        "bundle_json,evidence_json FROM "
                        "graph_first_ingress_c02_candidates_v1 WHERE bot=? "
                        "AND persona=? AND operation_id=?",
                        namespace.as_tuple + (operation_id,),
                    ).fetchone()
            if sealed is None:
                raise UnavailableGuard("durable C02 candidate is absent; HOLD")
            if sealed[:5] != c02_candidate:
                raise EventConflict("durable C02 candidate identity differs")
            if c02_first_seal_v2 or c02_terminal_recovery is not None:
                from .authority_service.v2_terminal_c02_recovery_contract import (
                    OriginalC02ResultKeyV1, from_wire as terminal_key_from_wire,
                )
                from .runtime.terminal_c02_recovery_candidate_v2 import (
                    FrozenTerminalC02CandidateV2,
                    inspect_frozen_terminal_c02_candidate_v2,
                )

                try:
                    raw_seal = json.loads(sealed[6])
                    raw_seal["original_key"] = terminal_key_from_wire(
                        raw_seal["original_key"], OriginalC02ResultKeyV1)
                    seal = FrozenTerminalC02CandidateV2(**raw_seal)
                    inspection = inspect_frozen_terminal_c02_candidate_v2(
                        namespace=namespace, operation_id=operation_id,
                        seal=seal, bundle_json=sealed[3],
                        quote_json=sealed[5])
                except (TypeError, ValueError, KeyError) as exc:
                    raise UnavailableGuard("durable C02 v2 seal is invalid; HOLD") from exc
                expected_key = (c02_terminal_recovery.seal.original_key
                                if c02_terminal_recovery is not None else
                                c02_first_seal_key)
                if inspection.bundle != bundle or seal.original_key != expected_key:
                    raise EventConflict("durable C02 v2 original key or bundle differs")
                if (c02_terminal_recovery is not None
                        and seal != c02_terminal_recovery.seal):
                    raise EventConflict("durable C02 v2 seal differs")
                with store._lock:
                    c02_v2_quote = self.__d02_issuer.original_signed_quote(
                        store._db, seal.quote_id, seal.quote_version)
                if canonical_serialize(asdict(c02_v2_quote)) != sealed[5]:
                    raise UnavailableGuard("durable C02 v2 signed quote differs; HOLD")
        if (intent[1] != attempt_id or intent[2] != requirements_json
                or intent[3] != anchor_json):
            raise UnavailableGuard("durable v2 bundle intent identity differs")
        if prior is None and (intent[4], intent[5]) != (
                metadata.graph_revision, epoch.revision):
            raise UnavailableGuard("uncommitted v2 bundle intent lost its graph stamp")
        if rejection is not None:
            if prior is not None or saved is not None:
                raise UnavailableGuard("rejected v2 bundle has a business receipt")
            self._finish_rejected_bundle_v2(
                namespace, metadata, epoch, anchor, attempt_id, digest,
                operation_id, rejection)
            raise UnavailableGuard("v2 bundle is terminal rejected_no_commit")
        if prior is not None:
            if prior[0] != digest:
                raise EventConflict("operation ID reused with different bundle")
            if saved is None or saved[0] != digest:
                raise UnavailableGuard("durable v2 bundle fence receipt is absent")
            try:
                original = from_wire(json.loads(saved[1]))
            except (TypeError, ValueError) as exc:
                raise UnavailableGuard("durable v2 bundle permit is invalid") from exc
            if (type(original) is not FencePermitV2
                    or original.operation_id != attempt_id
                    or original.operation != "write" or original.holder != self.__holder
                    or original.subject != port.installation_grant.subject
                    or original.authority_id != target.authority_id
                    or original.namespace != target.authority_namespace
                    or original.generation != target.activation_generation
                    or original.pinned_anchor != anchor
                    or (saved[2], saved[3]) != (intent[4], intent[5])
                    or saved[4] != saved[2] + 1
                    or saved[5] < saved[3]
                    or saved[6] != "finish:" + attempt_id
                    or saved[7] != "sha256:" + canonical_digest({
                        "operation_id": attempt_id, "permit_token": original.token,
                        "action": "finish_domain_bundle",
                        "business_operation_id": operation_id, "bundle_digest": digest,
                    })):
                raise UnavailableGuard("durable v2 bundle fence identity differs")
            observed, state = port.get_fence_operation(
                namespace=namespace, authority_namespace=target.authority_namespace,
                operation_id=attempt_id)
            if observed != original or state not in {"active", "finished"}:
                raise UnavailableGuard("v2 bundle Authority fence status differs")
            if state == "active":
                if (metadata.graph_revision != saved[4]
                        or epoch.revision != saved[5]):
                    raise UnavailableGuard("active v2 bundle fence lost its business stamp")
                scope = FenceScope(
                    namespace, target.authority_namespace, target.activation_generation,
                    "write", attempt_id, original, anchor,
                    NamespaceEpoch(*namespace.as_tuple, saved[3]), saved[2])
                if port.validate_fence(scope) != original:
                    raise UnavailableGuard("v2 bundle write permit changed")
                port.finish_fence(scope, request_id=saved[6], request_digest=saved[7])
            elif (metadata.graph_revision < saved[4]
                  or epoch.revision < saved[5]):
                raise UnavailableGuard("finished v2 bundle fence lost its business stamp")
            return self._read_v2(authority, lambda: self._commit_domain_bundle_fenced(
                bundle, lease, v2_read=True))
        if saved is not None:
            raise UnavailableGuard("v2 bundle fence exists without business receipt")
        dispatch_clock_reading = None
        if (self.__dispatch_admission_issuer is not None
                and any(write.key.type_name == "d09.verified_segment_batch.v1"
                        for proposal in bundle.proposals for write in proposal.typed_writes)):
            from .host.authority_profile import AdminIngressClockPolicy

            if type(self.__dispatch_clock_policy) is not AdminIngressClockPolicy:
                raise UnavailableGuard("dispatch admission clock policy is unavailable")
            try:
                dispatch_clock_reading = port.read_ingress_clock(
                    self.__dispatch_clock_policy)
            except Exception as exc:
                raise UnavailableGuard("paired dispatch admission clock is unavailable") from exc
        permit = port.begin_fence(
            namespace=namespace, authority_namespace=target.authority_namespace,
            holder=self.__holder, generation=target.activation_generation,
            operation="write", operation_id=attempt_id, expected_anchor=anchor,
            retain_on_unknown=True)
        scope = FenceScope(namespace, target.authority_namespace,
                           target.activation_generation, "write", attempt_id,
                           permit, anchor, epoch, metadata.graph_revision)
        finish_id = "finish:" + attempt_id
        finish_digest = "sha256:" + canonical_digest({
            "operation_id": attempt_id, "permit_token": permit.token,
            "action": "finish_domain_bundle", "business_operation_id": operation_id,
            "bundle_digest": digest,
        })
        if port.validate_fence(scope) != permit:
            raise UnavailableGuard("v2 bundle write permit changed")
        d04_topology_verifier = None
        if d04_joint_replay is not None:
            d04_topology_verifier = self._installed_d04_authored_topology_verifier_v3()
            d04_topology_verifier.observe_current_location_for_fence_v3(port, scope)
        dispatch_owner_guard = None
        dispatch_current_effect = None
        dispatch_effect_snapshot = None
        if dispatch_clock_reading is not None:
            from .authority_service.v2_contract import (
                AuthorityCurrentEffectSnapshotV2,
                canonical_digest as authority_canonical_digest,
            )
            from .authority_service.v2_execution_bridge import CurrentEffectReadV2

            owner_reader = getattr(port, "get_current_owner_guard_for_fence", None)
            effect_reader = getattr(port, "read_current_effect", None)
            snapshot_reader = getattr(
                port, "read_current_effect_snapshot_for_write_fence", None)
            if (not callable(owner_reader) or not callable(effect_reader)
                    or not callable(snapshot_reader)):
                raise UnavailableGuard(
                    "dispatch admission Owner/effect inventory reader unavailable; HOLD")
            guarded = owner_reader(
                namespace=namespace, authority_namespace=target.authority_namespace,
                permit=permit)
            if (type(guarded) is not tuple or len(guarded) != 2
                    or type(guarded[0]) is not OwnerAuthorizationGuardV1
                    or guarded[1] != permit):
                raise UnavailableGuard("dispatch admission Owner guard differs; HOLD")
            dispatch_owner_guard = guarded[0]
            dispatch_current_effect = effect_reader(
                namespace=namespace, authority_namespace=target.authority_namespace,
                effect_id=bundle.envelope.identity.effect_id)
            dispatch_effect_snapshot = snapshot_reader(
                namespace=namespace, authority_namespace=target.authority_namespace,
                permit=permit)
            if (type(dispatch_current_effect) is not CurrentEffectReadV2
                    or dispatch_current_effect.effect_id
                    != bundle.envelope.identity.effect_id
                    or type(dispatch_effect_snapshot) is not AuthorityCurrentEffectSnapshotV2
                    or dispatch_effect_snapshot.authority_id != permit.authority_id
                    or dispatch_effect_snapshot.namespace != permit.namespace
                    or dispatch_effect_snapshot.anchor != permit.pinned_anchor
                    or dispatch_effect_snapshot.permit_digest
                    != authority_canonical_digest(permit)
                    or dispatch_effect_snapshot.execution_head_seq
                    != dispatch_current_effect.execution_head_seq
                    or dispatch_effect_snapshot.execution_head_digest
                    != dispatch_current_effect.execution_head_digest
                    or (dispatch_current_effect.state == "absent" and any(
                        item.effect_id == dispatch_current_effect.effect_id
                        for item in dispatch_effect_snapshot.unresolved_effects))
                    or port.validate_fence(scope) != permit):
                raise UnavailableGuard(
                    "dispatch admission current effect inventory differs; HOLD")
        c02_fact = None
        if c02_witness is not None and c02_terminal_recovery is None:
            from .authority_service.v2_worker_result_read_fact_contract import (
                WorkerResultReadFactRequestV2, WorkerResultReadFactV2,
            )

            request = (c02_recovery.request if c02_recovery is not None
                       else c02_adoption[1].request)
            c02_fact = self.__worker_result_fact_port.current_worker_result_read_fact(
                WorkerResultReadFactRequestV2(
                    read_request=request, write_permit=permit,
                    bundle_digest=digest))
            if (type(c02_fact) is not WorkerResultReadFactV2
                    or c02_fact.read_request != request
                    or c02_fact.write_permit != permit
                    or c02_fact.bundle_digest != digest
                    or (c02_fact.result_digest !=
                        (c02_recovery.evidence["read_result_digest"]
                         if c02_recovery is not None else
                         canonical_digest(asdict(c02_adoption[1]))))):
                raise UnavailableGuard("original Authority worker result fact differs; HOLD")
        transaction_state = {"phase": "before_transaction"}
        try:
            scene_owner_guard = None
            if correction_issuance is not None:
                owner_authority, principal, binding, session_proof = correction_issuance[6:]
                _, current_binding = self._owner_binding_in_fence(
                    owner_authority, scope, principal, binding, session_proof)
                if (current_binding != binding
                        or "workbench.correct" not in current_binding.capabilities
                        or port.validate_fence(scope) != permit):
                    raise UnavailableGuard("current correction Owner authority changed; HOLD")
            if any(
                    proposal.domain == "d03" and any(
                        write.key.type_name == "d03.world_event"
                        and (write.value.get("kind") == "message_received"
                             or write.value.get("reality") == "host_observed")
                        for write in proposal.typed_writes)
                    for proposal in bundle.proposals):
                reader = getattr(port, "get_current_owner_guard_for_fence", None)
                if not callable(reader):
                    raise UnavailableGuard("current scene Owner guard port is unavailable")
                guarded = reader(
                    namespace=namespace,
                    authority_namespace=target.authority_namespace,
                    permit=permit)
                if (type(guarded) is not tuple or len(guarded) != 2
                        or type(guarded[0]) is not OwnerAuthorizationGuardV1
                        or guarded[1] != permit
                        or port.validate_fence(scope) != permit):
                    raise UnavailableGuard("current scene Owner guard is unavailable")
                scene_owner_guard = guarded[0]
            qualified_self = None
            current_self_policy = (
                self_identity_issuance[0] if self_identity_issuance is not None else
                baseline_issuance[6] if baseline_issuance is not None
                and len(baseline_issuance) == 9 else None)
            if current_self_policy is not None:
                from .domains.d03.self_identity_qualification import (
                    qualify_authority_current_self_identity,
                )

                if self.__self_identity_port is None:
                    raise UnavailableGuard("current Authority self identity port unavailable; HOLD")
                reader = getattr(port, "get_current_owner_guard_for_fence", None)
                if not callable(reader):
                    raise UnavailableGuard("current Owner guard port unavailable; HOLD")
                guarded = reader(namespace=namespace,
                    authority_namespace=target.authority_namespace, permit=permit)
                if (type(guarded) is not tuple or len(guarded) != 2
                        or type(guarded[0]) is not OwnerAuthorizationGuardV1
                        or guarded[1] != permit):
                    raise UnavailableGuard("current Owner guard unavailable; HOLD")
                scene_owner_guard = guarded[0]
                with store._lock:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise StaleRead("self identity graph changed before Authority read")
                    role, _, role_epoch, _ = self._scene_binding_state_locked(
                        namespace, scene_owner_guard)
                    activation_key = AtomKey(
                        Owner("persona", *namespace.as_tuple),
                        "d01.persona_activation.v1", "current")
                    row = store._db.execute(
                        "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                        (activation_key.token,),
                    ).fetchone()
                    if row is None:
                        raise UnavailableGuard("current D01 activation unavailable; HOLD")
                    activation_atom = GraphAtom(
                        activation_key, row[0], json.loads(row[1]), bool(row[2]))
                if role_epoch != epoch:
                    raise StaleRead("current D01 epoch changed before Authority read")
                current = self.__self_identity_port.current_self_identity(
                    namespace=namespace,
                    authority_namespace=target.authority_namespace,
                    request_operation_id=operation_id,
                    permit=permit,
                )
                self_storage_admission = None
                if current.origin_graph_incarnation is not None:
                    from .authority_service.d12_target_owner_admission_v1 import D12CurrentOwnerAuthorityV1
                    current_owner, observed_permit = port.get_current_background_owner_authority_for_fence_v1(
                        namespace=namespace, authority_namespace=target.authority_namespace, permit=permit)
                    if (type(current_owner) is not D12CurrentOwnerAuthorityV1 or current_owner.target_admission is not None
                            or current_owner.guard != scene_owner_guard or observed_permit != permit):
                        raise UnavailableGuard("D03 current source Owner observation unavailable")
                    self_storage_admission = current_owner.storage_admission
                qualified_mapping = qualify_authority_current_self_identity(
                    role=role, activation_atom=activation_atom,
                    policy=current_self_policy,
                    installation_grant=port.installation_grant,
                    owner_guard=scene_owner_guard,
                    request_operation_id=operation_id, permit=permit,
                    port=SimpleNamespace(current_self_identity=lambda **_: current),
                    storage_admission=self_storage_admission, graph_metadata=metadata, graph_epoch=epoch,
                )
                if (current.graph_revision != metadata.graph_revision
                        or current.graph_epoch != epoch.revision
                        or port.validate_fence(scope) != permit):
                    raise UnavailableGuard("current self identity changed; HOLD")
                if (self_identity_issuance is not None
                        and qualified_mapping != self_identity_issuance[5]):
                    raise UnavailableGuard("current self identity changed; HOLD")
                qualified_self = (role, qualified_mapping, current)
            receipt = self._commit_domain_bundle_fenced(
                bundle, lease, v2_write=(metadata, epoch, finish_id,
                                         finish_digest, canonical_json(to_wire(permit))),
                v2_transaction_state=transaction_state,
                dispatch_clock_reading=dispatch_clock_reading,
                dispatch_admission_scope=scope,
                dispatch_admission_owner_guard=dispatch_owner_guard,
                dispatch_admission_current_effect=dispatch_current_effect,
                dispatch_admission_effect_snapshot=dispatch_effect_snapshot,
                scene_owner_guard=scene_owner_guard,
                now_utc=(arrival_issuance[2] if arrival_issuance else
                         attention_issuance[1] if attention_issuance else
                         c04_association_issuance[7]
                         if c04_association_issuance else
                         baseline_issuance[2] if baseline_issuance else
                         self_identity_issuance[3] if self_identity_issuance else
                         correction_issuance[2] if correction_issuance else
                          c02_witness.now if isinstance(
                              c02_witness, (_C02PendingRecovery,
                                            _C02TerminalRecovery)) else
                         c02_adoption[6] if c02_adoption is not None else None),
                arrival_issuance=arrival_issuance,
                attention_issuance=attention_issuance,
                c04_association_issuance=c04_association_issuance,
                baseline_issuance=baseline_issuance,
                self_identity_issuance=self_identity_issuance,
                correction_issuance=correction_issuance,
                d04_joint_replay=d04_joint_replay,
                d04_joint_output=d04_joint_output, d04_topology_verifier=d04_topology_verifier,
                qualified_self=qualified_self,
                 c02_adoption=(c02_witness, c02_fact, permit)
                 if c02_witness is not None else None,
                 c02_first_seal_quote=c02_v2_quote,
                 c02_terminal_recovery=c02_terminal_recovery)
        except Exception:
            if transaction_state["phase"] in {"before_transaction", "rolled_back"}:
                rejection = self._record_rejected_bundle_v2(
                    namespace, operation_id, digest, attempt_id, metadata, epoch,
                    intent, permit,
                    c02_first_seal_v2=(c02_first_seal_v2
                                       or c02_terminal_recovery is not None))
                self._finish_rejected_bundle_v2(
                    namespace, metadata, epoch, anchor, attempt_id, digest,
                    operation_id, rejection)
            raise
        if port.validate_fence(scope) != permit:
            raise UnavailableGuard("v2 bundle write permit changed after commit")
        with store._lock:
            current, current_epoch = self._v2_graph_stamp(namespace)
            if (current.requirements != metadata.requirements
                    or current.graph_revision != metadata.graph_revision + 1
                    or current_epoch.revision != receipt.invalidated_epochs[0].revision):
                raise UnavailableGuard("v2 bundle graph stamp changed after commit")
        port.finish_fence(scope, request_id=finish_id, request_digest=finish_digest)
        return receipt

    def _record_rejected_bundle_v2(self, namespace, operation_id, digest,
                                   attempt_id, metadata, epoch, intent, permit,
                                   *, allow_advanced_graph=False,
                                   c02_first_seal_v2=False):
        """Record a proven rollback before any Authority abort finish."""
        from .authority_service.v2_contract import to_wire

        store = self.__store
        finish_id = "abort:" + attempt_id
        finish_digest = "sha256:" + canonical_digest({
            "operation_id": attempt_id, "permit_token": permit.token,
            "action": "rejected_no_commit", "business_operation_id": operation_id,
            "bundle_digest": digest,
        })
        expected = (
            digest, "rejected_no_commit", canonical_json(to_wire(permit)),
            metadata.graph_revision, epoch.revision, finish_id, finish_digest,
        )
        with store._lock:
            db = store._db
            db.execute("BEGIN IMMEDIATE")
            try:
                current_intent = db.execute(
                    "SELECT digest,fence_attempt_id,requirements_json,anchor_json,"
                    "graph_revision,graph_epoch FROM graph_bundle_intents_v2 "
                    "WHERE bot=? AND persona=? AND operation_id=?",
                    namespace.as_tuple + (operation_id,),
                ).fetchone()
                if (current_intent != intent
                        or self._v2_graph_stamp(namespace) != (metadata, epoch)
                        or (allow_advanced_graph and
                            (intent[4] > metadata.graph_revision
                             or intent[5] > epoch.revision))
                        or db.execute(
                            "SELECT 1 FROM graph_bundle_operations WHERE bot=? "
                            "AND persona=? AND operation_id=?",
                            namespace.as_tuple + (operation_id,),
                        ).fetchone() is not None
                        or db.execute(
                            "SELECT 1 FROM graph_bundle_fences_v2 WHERE bot=? "
                            "AND persona=? AND operation_id=?",
                            namespace.as_tuple + (operation_id,),
                        ).fetchone() is not None):
                    raise UnavailableGuard("v2 bundle rollback cannot be proven")
                db.execute(
                    "INSERT OR IGNORE INTO graph_bundle_rejections_v2"
                    "(bot,persona,operation_id,digest,status,permit_json,"
                    "graph_revision,graph_epoch,finish_request_id,finish_request_digest) "
                    "VALUES(?,?,?,?,?,?,?,?,?,?)",
                    namespace.as_tuple + (operation_id,) + expected,
                )
                recorded = db.execute(
                    "SELECT digest,status,permit_json,graph_revision,graph_epoch,"
                    "finish_request_id,finish_request_digest "
                    "FROM graph_bundle_rejections_v2 WHERE bot=? AND persona=? "
                    "AND operation_id=?", namespace.as_tuple + (operation_id,),
                ).fetchone()
                if recorded != expected:
                    raise UnavailableGuard("v2 bundle rejection identity differs")
                db.execute(
                    "DELETE FROM " + (
                        "graph_first_ingress_c02_candidates_v2 "
                        if c02_first_seal_v2 else
                        "graph_first_ingress_c02_candidates_v1 ") +
                    "WHERE bot=? AND persona=? AND operation_id=? "
                    "AND bundle_digest=?",
                    namespace.as_tuple + (operation_id, digest),
                )
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise
        return expected

    def _finish_rejected_bundle_v2(self, namespace, metadata, epoch, anchor,
                                   attempt_id, digest, operation_id, rejection,
                                   *, allow_advanced_graph=False):
        from .authority_service.v2_contract import FencePermitV2, from_wire

        port = self.__content_fence_v2
        target = metadata.requirements
        try:
            permit = from_wire(json.loads(rejection[2]))
        except (TypeError, ValueError) as exc:
            raise UnavailableGuard("durable v2 rejected permit is invalid") from exc
        if (rejection[0] != digest or rejection[1] != "rejected_no_commit"
                or type(permit) is not FencePermitV2
                or permit.operation_id != attempt_id or permit.operation != "write"
                or permit.subject != port.installation_grant.subject
                or permit.holder != self.__holder
                or permit.authority_id != target.authority_id
                or permit.namespace != target.authority_namespace
                or permit.generation != target.activation_generation
                or permit.pinned_anchor != anchor
                or (not allow_advanced_graph and
                    (rejection[3], rejection[4]) !=
                    (metadata.graph_revision, epoch.revision))
                or (allow_advanced_graph and
                    (rejection[3] > metadata.graph_revision
                     or rejection[4] > epoch.revision))
                or rejection[5] != "abort:" + attempt_id
                or rejection[6] != "sha256:" + canonical_digest({
                    "operation_id": attempt_id, "permit_token": permit.token,
                    "action": "rejected_no_commit",
                    "business_operation_id": operation_id, "bundle_digest": digest,
                })):
            raise UnavailableGuard("durable v2 rejected fence identity differs")
        observed, state = port.get_fence_operation(
            namespace=namespace, authority_namespace=target.authority_namespace,
            operation_id=attempt_id)
        if observed != permit or state not in {"active", "finished"}:
            raise UnavailableGuard("rejected v2 Authority fence status differs")
        scope = FenceScope(
            namespace, target.authority_namespace,
            target.activation_generation, "write", attempt_id,
            permit, anchor,
            NamespaceEpoch(*namespace.as_tuple, rejection[4]), rejection[3])
        if (state == "active" and
                ((rejection[3], rejection[4]) !=
                 (metadata.graph_revision, epoch.revision)
                 or port.validate_fence(scope) != permit)):
            raise UnavailableGuard("rejected v2 write permit changed")
        port.finish_fence(scope, request_id=rejection[5], request_digest=rejection[6])

    def _commit_domain_bundle_fenced(self, bundle: DomainBundle,
                                     lease: object, *, v2_read: bool = False,
                                     v2_write=None, v2_transaction_state=None,
                                      in_transaction: bool = False,
                                      now_utc: float | None = None,
                                      dispatch_clock_reading=None,
                                      dispatch_clock_frozen_now_utc=None,
                                      dispatch_admission_scope=None,
                                      dispatch_admission_owner_guard=None,
                                      dispatch_admission_current_effect=None,
                                      dispatch_admission_effect_snapshot=None,
                                      natural_final_admission=None,
                                      provisional_check_candidate=None,
                                      installed_final_check_reissuer=None,
                                      ingress_deadline_check=None,
                                     scene_owner_guard=None,
                                      arrival_issuance=None,
                                      attention_issuance=None,
                                      c04_association_issuance=None,
                                      c04_adoption_issuance_v3=None,
                                      c04_runtime_writes_v3=(),
                                      d04_joint_replay=None,
                                      d04_joint_output=None, d04_topology_verifier=None,
                                      d04_numeric_issuance_v3=None,
                                      domain_production_issuance_v1=None,
                                      baseline_issuance=None,
                                      self_identity_issuance=None,
                                      correction_issuance=None,
                                       qualified_self=None,
                                       c02_adoption=None,
                                       c02_first_seal_quote=None,
                                       c02_terminal_recovery: _C02TerminalRecovery | None = None
                                       ) -> CommitReceipt:
        """Join a caller-owned graph transaction when ``in_transaction`` is set.

        The caller holds the store lock and owns COMMIT or ROLLBACK.
        """
        from .runtime.d04_joint_advance_v2 import ProductAdvanceEvidenceV2

        if bundle.root_adoption is not None:
            raise UnavailableGuard(
                "authored D04 root needs its dedicated installed adoption; HOLD")
